def available_resources(psutil):
    try:
        memory = max(0, int(psutil.virtual_memory().available))
    except (OSError, NotImplementedError, psutil.Error):
        try:
            memory = max(0, int(os.sysconf("SC_AVPHYS_PAGES")) * int(os.sysconf("SC_PAGE_SIZE")))
        except (AttributeError, OSError, ValueError):
            memory = 0
    cpus = max(1, os.cpu_count() or 1)
    try:
        affinity = psutil.Process().cpu_affinity()
        if affinity:
            cpus = min(cpus, len(affinity))
    except (AttributeError, OSError, NotImplementedError, psutil.Error):
        try:
            cpus = min(cpus, max(1, len(os.sched_getaffinity(0))))
        except (AttributeError, OSError):
            pass
    if sys.platform.startswith("linux"):
        roots = [Path("/sys/fs/cgroup")]
        try:
            for line in Path("/proc/self/cgroup").read_text().splitlines():
                hierarchy, controllers, name = line.split(":", 2)
                if hierarchy == "0" and not controllers and ".." not in Path(name).parts:
                    roots.append(Path("/sys/fs/cgroup") / name.lstrip("/"))
        except (OSError, ValueError):
            pass
        seen = set()
        for root in roots:
            for location in (root, *root.parents):
                if location in seen or Path("/sys/fs/cgroup") not in (location, *location.parents):
                    continue
                seen.add(location)
                for limit_file, used_file in (("memory.max", "memory.current"), ("memory/memory.limit_in_bytes", "memory/memory.usage_in_bytes")):
                    try:
                        limit = (location / limit_file).read_text().strip()
                        used = int((location / used_file).read_text().strip())
                        if limit.isdecimal():
                            memory = min(memory, max(0, int(limit) - used))
                    except (OSError, ValueError):
                        pass
                try:
                    quota, period = (location / "cpu.max").read_text().split()
                    if quota.isdecimal() and int(period) > 0:
                        cpus = min(cpus, max(1, math.ceil(int(quota) / int(period))))
                except (OSError, ValueError):
                    pass
    return {"memory": memory, "cpus": cpus}

def execution_threads(psutil, policy=None):
    cpus = available_resources(psutil)["cpus"]
    default = max(1, math.isqrt(cpus))
    return default if policy is None else policy.integer("execution", "calibration_thread_limit", default, 1, cpus)

def compatible_python(requirement, version):
    if not requirement:
        return True
    current = tuple(int(value) for value in version[:3])
    for item in str(requirement).split(","):
        match = re.fullmatch(r"\s*(>=|<=|==|!=|~=|>|<)\s*(\d+(?:\.\d+){0,2})(\.\*)?\s*", item)
        if match is None:
            return False
        operator, raw, wildcard = match.groups()
        parts = tuple(int(value) for value in raw.split("."))
        target = parts + (0,) * (3 - len(parts))
        if wildcard:
            if operator not in ("==", "!="):
                return False
            same = current[:len(parts)] == parts
            okay = same if operator == "==" else not same
        elif operator == "~=":
            if len(parts) < 2:
                return False
            prefix = parts[:-1]
            okay = current >= target and current[:len(prefix)] == prefix
        else:
            okay = {">=": current >= target, "<=": current <= target, ">": current > target, "<": current < target,
                    "==": current == target, "!=": current != target}[operator]
        if not okay:
            return False
    return True


def build_digest(source=None):
    identity = None
    if source is None:
        info = Path(__file__).stat()
        identity = (info.st_mtime_ns, info.st_ctime_ns, info.st_size, info.st_dev, info.st_ino)
        cached = getattr(build_digest, "cached", None)
        if cached is not None and cached[0] == identity:
            return cached[1]
        source = Path(__file__).read_text(encoding="utf-8")
    tree = ast.parse(source)
    nodes = []
    embedded = 0
    for item in tree.body:
        if isinstance(item, ast.Assign) and any(isinstance(target, ast.Name) and target.id == "EMBEDDED_RELEASE" for target in item.targets):
            if len(item.targets) != 1 or not isinstance(item.value, ast.Dict) or not isinstance(ast.literal_eval(item.value), dict):
                raise YuanError("内置发布数据必须是静态对象 / Embedded release data must be a static object")
            embedded += 1
            item.value = ast.Dict(keys=[], values=[])
        nodes.append(ast.dump(item, include_attributes=False))
    if embedded != 1:
        raise YuanError("内置发布数据身份不唯一 / Embedded release identity is not unique")
    result = payload_digest(nodes)
    if identity is not None:
        build_digest.cached = identity, result
    return result

def release_source(state):
    if EMBEDDED_RELEASE:
        if (not isinstance(EMBEDDED_RELEASE, dict) or EMBEDDED_RELEASE.get("format") != "yuan-embedded-release-v1"
                or not isinstance(EMBEDDED_RELEASE.get("descriptor"), dict) or not isinstance(EMBEDDED_RELEASE.get("trust"), dict)):
            raise YuanError("内置自有模型发布数据无效 / Invalid embedded owned-model release")
        return Path(__file__).resolve(), copy.deepcopy(EMBEDDED_RELEASE["descriptor"]), True
    paths = (Path(state).parent / "Yuan.release.json", Path(__file__).resolve().with_name("Yuan.release.json"))
    path = next((path for path in paths if path.is_file() and not path.is_symlink()), None)
    return (path, checked_json(path), False) if path is not None else (None, None, False)

def embedded_source_text(payload):
    source = Path(__file__).read_text(encoding="utf-8")
    tree = ast.parse(source)
    assignment = next(item for item in tree.body if isinstance(item, ast.Assign) and any(isinstance(target, ast.Name) and target.id == "EMBEDDED_RELEASE" for target in item.targets))
    lines = source.splitlines(keepends=True)
    updated = "".join(lines[:assignment.lineno - 1]) + "EMBEDDED_RELEASE = " + repr(payload) + "\n" + "".join(lines[assignment.end_lineno:])
    if build_digest(updated) != build_digest(source):
        raise YuanError("嵌入发布数据改变了执行代码 / Embedding release data changed executable code")
    return updated

def behavior_digest():
    return build_digest()


def payload_digest(value):
    return hashlib.sha256(json.dumps(value, ensure_ascii=False, sort_keys=True, allow_nan=False, separators=(",", ":")).encode("utf-8")).hexdigest()

def checked_json(path):
    try:
        with Path(path).open(encoding="utf-8") as stream:
            value = json.load(stream, parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
        if not isinstance(value, dict):
            raise ValueError("Expected an object")
        return value
    except (OSError, ValueError, TypeError) as exc:
        raise YuanError("运行记录无法校验，原文件已保留 / Runtime record cannot be validated; original retained: " + str(Path(path).name)) from exc

def is_digest(value):
    return isinstance(value, str) and re.fullmatch(r"[0-9a-f]{64}", value) is not None

def can_converse(values):
    return all(values.get(key) is True for key in ("runtime_ready", "pipeline_ready", "audio_ready", "model_ready"))

def readiness_view(values, closing=False):
    ready = bool(not closing and can_converse(values) and values.get("storage_ready") is True and values.get("conversation_ready") is True)
    if ready:
        return True, "ready"
    if values.get("runtime_ready") is not True:
        return False, None
    if values.get("audio_ready") is not True:
        return False, "mic_missing"
    if values.get("storage_ready") is not True:
        return False, "history_full"
    return False, values.get("model_blocker") or "preparing_model"

class AnyCancel:
    def __init__(self, *events):
        self.events = tuple(value for value in events if value is not None)

    def is_set(self):
        return any(value.is_set() for value in self.events)

    def wait(self, timeout):
        deadline = time.monotonic() + max(0.0, timeout)
        while not self.is_set():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            if self.events:
                self.events[0].wait(min(remaining, math.sqrt(tick())))
            else:
                time.sleep(min(remaining, math.sqrt(tick())))
        return self.is_set()

class Cancelled(Exception):
    pass

TEXT["semantic_verifier"] = ("独立语音验证模型", "Independent speech verifier")

class YuanError(RuntimeError):
    pass

class YuanFault(YuanError):
    def __init__(self, message, *, category="unknown", code="runtime_failure", stage=None, **details):
        super().__init__(message)
        self.category = category
        self.code = code
        self.stage = stage
        self.details = details

class EngineFault(YuanFault):
    def __init__(self, message, *, category="engine", code="engine_failure", stage=None, **details):
        super().__init__(message, category=category, code=code, stage=stage, **details)

class InvalidDownload(YuanError):
    pass

class InvalidAudio(YuanError):
    pass

class IneligibleSample(YuanError):
    pass

class AcceptanceFailed(IneligibleSample):
    pass

class FlushResult(dict):
    def __bool__(self):
        return self.get("ok") is True

def tick():
    return max(sys.getswitchinterval(), time.get_clock_info("monotonic").resolution)

def timing_floor():
    return max(sys.float_info.epsilon, time.get_clock_info("monotonic").resolution)

def elapsed_seconds(started):
    return max(timing_floor(), time.monotonic() - started)

def check(cancel):
    if cancel is not None and cancel.is_set():
        raise Cancelled()

def tr(key, language="中文"):
    value = TEXT.get(key)
    if value:
        return value[language == "English"]
    return str(key)

def human_bytes(value):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        return "—"
    value = max(0.0, float(value))
    units = ("B", "KiB", "MiB", "GiB", "TiB", "PiB")
    for unit in units:
        if value < 1024 or unit == units[-1]:
            return f"{value:.1f} {unit}"
        value /= 1024

def human_duration(seconds):
    if not isinstance(seconds, (int, float)) or not math.isfinite(seconds) or seconds < 0:
        return "—"
    seconds = int(math.ceil(seconds))
    if seconds < 60:
        return f"{seconds}s"
    minutes, seconds = divmod(seconds, 60)
    if minutes < 60:
        return f"{minutes}m {seconds:02}s"
    hours, minutes = divmod(minutes, 60)
    return f"{hours}h {minutes:02}m"

def local_message(value, language):
    if not isinstance(value, dict):
        return str(value)
    title = value.get(language) or value.get("中文") or value.get("English") or ""
    detail = value.get("detail")
    return "\n".join(str(part) for part in (title, detail) if part)

def safe_path(root, relative):
    root = Path(root).resolve()
    value = str(relative)
    if not value or "\\" in value or ":" in value or "\x00" in value:
        raise YuanError("目录路径无效 / Invalid workspace path")
    path = (root / value).resolve()
    if path == root or root not in path.parents:
        raise YuanError("拒绝访问工作目录以外的路径 / Refusing a path outside the workspace")
    return path

def database_path(root, name):
    path = safe_path(root, name)
    for suffix in ("", "-wal", "-shm", "-journal"):
        candidate = Path(root) / (name + suffix)
        if candidate.is_symlink():
            raise YuanError("拒绝使用链接数据库文件 / Refusing a linked database file")
        safe_path(root, name + suffix)
    return path

def sync_dir(path):
    if os.name != "nt":
        try:
            fd = os.open(str(path), os.O_RDONLY)
            try:
                os.fsync(fd)
            finally:
                os.close(fd)
        except OSError:
            pass

def atomic_json(path, payload, cancel=None):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(dir=path.parent, prefix=".write-", suffix=".tmp")
    try:
        with os.fdopen(fd, "w", encoding="utf-8") as stream:
            json.dump(payload, stream, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
            stream.flush()
            os.fsync(stream.fileno())
        check(cancel)
        os.replace(name, path)
        sync_dir(path.parent)
    finally:
        if os.path.exists(name):
            os.unlink(name)

def read_json(path, default=None):
    try:
        with Path(path).open(encoding="utf-8") as stream:
            value = json.load(stream)
            return value if isinstance(value, dict) else ({} if default is None else default)
    except (OSError, ValueError, TypeError):
        return {} if default is None else default

def workspace_settings(state, language="中文", prompt=None):
    path = safe_path(state, "settings.json")
    values = checked_json(path) if path.exists() else {}
    language = values.get("language", language)
    prompt = values.get("prompt", tr("default_prompt", language) if prompt is None else prompt)
    if language not in ("中文", "English") or not isinstance(prompt, str):
        raise YuanFault("目录设置无效，原文件已保留 / Invalid workspace settings; original retained",
                        category="configuration", code="workspace_settings_invalid")
    return {"language": language, "prompt": prompt}

def digest_file(path, cancel=None, algorithm="sha256"):
    path = Path(path)
    value = hashlib.new(algorithm)
    with path.open("rb") as stream:
        while True:
            check(cancel)
            part = stream.read(os.statvfs(path.parent).f_bsize * 256 if hasattr(os, "statvfs") else 1024 * 1024)
            if not part:
                break
            value.update(part)
    return value.hexdigest()


def redact(value):
    if isinstance(value, dict):
        return {str(key): "<redacted>" if str(key).lower() in ("password", "token", "authorization", "api_key", "secret") else redact(item) for key, item in value.items()}
    if isinstance(value, (tuple, list)):
        return [redact(item) for item in value]
    if not isinstance(value, str):
        return value
    def clean(match):
        raw = match.group(0)
        try:
            parts = urllib.parse.urlsplit(raw)
            host = parts.netloc.rsplit("@", 1)[-1]
            return urllib.parse.urlunsplit((parts.scheme, ("<redacted>@" if "@" in parts.netloc else "") + host, parts.path,
                                           "<redacted>" if parts.query else "", ""))
        except ValueError:
            return "<redacted-url>"
    return re.sub(r"(?:https?|socks5h?)://[^\s\"'<>]+", clean, value, flags=re.IGNORECASE)

def failure_category(exc):
    seen = set()
    current = exc
    while current is not None and id(current) not in seen:
        seen.add(id(current))
        if isinstance(current, YuanFault) and current.category != "unknown":
            return current.category
        if isinstance(current, OSError) and (current.errno in (errno.ENOSPC, errno.EACCES, errno.EROFS, getattr(errno, "EDQUOT", -1)) or getattr(current, "winerror", None) in (5, 39, 112)):
            return "storage"
        if isinstance(current, urllib.error.HTTPError):
            return "configuration" if current.code in (401, 403, 407) else "network" if current.code in (408, 429) or current.code >= 500 else "resolution"
        current = current.__cause__ if current.__cause__ is not None else (None if current.__suppress_context__ else current.__context__)
    reason = concise_error(exc).lower()
    if any(word in reason for word in ("no space left", "out of space", "disk full", "permission denied", "access is denied", "read-only file system", "空间不足", "download exceeds the current resource budget")):
        return "storage"
    if any(word in reason for word in ("hash mismatch", "哈希", "摘要不匹配", "完整性", "certificate verify failed", "sslcertverificationerror", "artifact hashes", "versions differ from the lock", "artifact lock", "lock mismatch")):
        return "integrity"
    if any(word in reason for word in ("component execution deadline", "component progress", "stage deadline", "stage event channel", "阶段执行期限", "控制命令未按时", "control command timed out")):
        return "timeout"
    if any(word in reason for word in ("network connection deadline", "network read deadline", "timed out", "timeout", "temporary failure in name resolution", "getaddrinfo failed", "connection reset", "connection refused", "connection aborted", "network is unreachable", "retrying (retry", "max retries exceeded", "could not fetch url", "name or service not known")):
        return "network"
    if any(word in reason for word in ("requires a different python", "not a supported wheel", "unsupported python", "does not meet requirements", "dll load failed", "undefined symbol", "cannot open shared object file", "illegal instruction", "no module named ensurepip", "no module named 'ensurepip'", "no module named venv", "no module named 'venv'", "incompatible", "abi mismatch")):
        return "compatibility"
    if any(word in reason for word in ("no matching distribution found", "could not find a version that satisfies", "resolutionimpossible")):
        return "resolution"
    return "unknown"

def fault_details(exc, stage=None):
    category = failure_category(exc)
    details = dict(exc.details) if isinstance(exc, YuanFault) else {}
    if isinstance(exc, urllib.error.HTTPError):
        details.update(url=exc.geturl(), http_status=exc.code)
    if isinstance(exc, OSError) and (exc.errno in (errno.EACCES, errno.EPERM) or getattr(exc, "winerror", None) == 5):
        details["permission_denied"] = True
    return {"category": category, "code": getattr(exc, "code", category + "_failure"), "stage": getattr(exc, "stage", None) or stage,
            "details": details, "reason": concise_error(exc)}

def fault_event(exc, stage=None):
    return redact(fault_details(exc, stage))

def runtime_identity(state, entry=None):
    state = Path(state)
    pointer = read_json(state / "runtime-current.json")
    if entry is None and pointer.get("directory"):
        try:
            entry = read_json(safe_path(state, pointer["directory"]) / "lock.json")
        except YuanError:
            entry = None
    return payload_digest([platform.system(), platform.machine(), entry or {"host": sys.version, "executable": sys.executable}, os.cpu_count()])

class StartupControl:
    def __init__(self, cancel, deadline, clock=None, transfer_seconds=0.0):
        self.cancel, self._deadline, self.clock = cancel, deadline, clock or time.monotonic
        self.transfer_seconds = max(0.0, float(transfer_seconds))
        self._transfer_used = 0.0
        self._transfer_started = None
        self._transfer_depth = 0
        self.lock = threading.RLock()

    @property
    def transfer_used(self):
        with self.lock:
            active = max(0.0, self.clock() - self._transfer_started) if self._transfer_started is not None else 0.0
            return self._transfer_used + active

    @property
    def transfer_remaining(self):
        return max(0.0, self.transfer_seconds - self.transfer_used)

    @property
    def deadline(self):
        return self._deadline + min(self.transfer_seconds, self.transfer_used)

    def transfer_fault(self):
        return YuanFault("累计下载预算已用尽，已保留可续传部分 / Cumulative download budget exhausted; resumable data retained",
                         category="timeout", code="startup_transfer_deadline", stage="engine_startup",
                         transfer_seconds=self.transfer_seconds, transfer_used_seconds=self.transfer_used)

    def is_set(self):
        if self.cancel.is_set():
            return True
        with self.lock:
            used = self.transfer_used
            if (self._transfer_started is not None or used > 0.0) and used >= self.transfer_seconds:
                raise self.transfer_fault()
            if self.clock() >= self.deadline:
                raise YuanFault("运行准备暂未完成，将从检查点继续 / Runtime preparation will continue from its checkpoint", category="timeout", code="startup_campaign_deadline", stage="engine_startup")
        return False

    @contextmanager
    def transfer(self):
        with self.lock:
            check(self)
            if self.transfer_remaining <= 0.0:
                raise self.transfer_fault()
            if self._transfer_depth == 0:
                self._transfer_started = self.clock()
            self._transfer_depth += 1
        try:
            yield
            check(self)
        finally:
            with self.lock:
                self._transfer_depth -= 1
                if self._transfer_depth == 0:
                    self._transfer_used += max(0.0, self.clock() - self._transfer_started)
                    self._transfer_started = None

    def wait(self, seconds):
        check(self)
        with self.lock:
            remaining = max(0.0, self.deadline - self.clock())
            if self._transfer_started is not None:
                remaining = self.transfer_remaining
        self.cancel.wait(max(0.0, min(seconds, remaining)))
        return self.is_set()


class TransferBudget:
    def __init__(self, initial, maximum, idle, margin=2.0, clock=None):
        if any(isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0
               for value in (initial, maximum, idle, margin)):
            raise ValueError("下载时间预算无效 / Invalid transfer time budget")
        self.clock = clock or time.monotonic
        self.started = self.clock()
        self.hard_deadline = self.started + maximum
        self.deadline = min(self.hard_deadline, self.started + initial)
        self.idle, self.margin = idle, max(1.0, margin)
        self.previous = None
        self.previous_at = self.started
        self.speed = None

    def advance(self, current, total):
        now = self.clock()
        if now >= self.deadline:
            return self.deadline
        if self.previous is not None and current > self.previous:
            elapsed = max(tick(), now - self.previous_at)
            measured = (current - self.previous) / elapsed
            weight = -math.expm1(-elapsed / max(tick(), self.idle))
            self.speed = measured if self.speed is None else self.speed + weight * (measured - self.speed)
            remaining = max(0, total - current) / self.speed if total is not None and self.speed > 0 else self.idle
            self.deadline = min(self.hard_deadline, max(self.deadline, now + max(self.idle, remaining * self.margin)))
        elif self.previous is not None and current < self.previous:
            self.speed = None
        if self.previous is None or current != self.previous:
            self.previous, self.previous_at = current, now
        return self.deadline


class TransferRate:
    def __init__(self, interval, clock=None):
        self.clock = clock or time.monotonic
        self.interval = max(tick(), interval)
        self.at = self.clock()
        self.pending = 0
        self.value = None

    def advance(self, amount):
        self.pending += max(0, amount)
        now = self.clock()
        elapsed = now - self.at
        if elapsed >= self.interval:
            measured = self.pending / elapsed
            weight = -math.expm1(-elapsed / (self.interval * 4))
            self.value = measured if self.value is None else self.value + weight * (measured - self.value)
            self.at, self.pending = now, 0
        return self.value

class DownloadStorage:
    def __init__(self, directory, reserve):
        self.directory, self.reserve = Path(directory), max(0, int(reserve))
        self.lock = threading.Lock()

    def write(self, stream, block):
        with self.lock:
            if shutil.disk_usage(self.directory).free < self.reserve + len(block):
                raise YuanFault("下载将占用保留空间，已暂停 / Download would consume reserved space; paused",
                                category="storage", code="download_disk_reserve", stage="download", reserve_bytes=self.reserve)
            if stream.write(block) != len(block):
                raise YuanFault("下载文件写入未完成 / Download file write was incomplete", category="storage", code="download_short_write", stage="download")

class DownloadLedger:
    def __init__(self, artifacts, phase_id, emit, interval, clock=None):
        self.clock = clock or time.monotonic
        self.emit, self.phase_id = emit, phase_id
        self.interval = max(tick(), interval)
        self.last_emit = -math.inf
        self.lock = threading.RLock()
        self.rate = TransferRate(self.interval, self.clock)
        self.rows = {item["sha256"]: {"artifact_id": item["sha256"], "file": item["filename"], "file_index": index + 1,
                                    "current": 0, "total": item.get("size"), "transfer_state": "download_queued", "verified": False}
                     for index, item in enumerate(artifacts)}

    def update(self, artifact_id, values, transferred=0, force=False):
        with self.lock:
            row = self.rows[artifact_id]
            row.update(values)
            speed = self.rate.advance(transferred)
            now = self.clock()
            if not force and now - self.last_emit < self.interval:
                return
            self.last_emit = now
            rows = list(self.rows.values())
            active = [value for value in rows if not value.get("verified") and value.get("transfer_state") != "download_queued"]
            selected = row if row in active or not active else active[0]
            total = sum(value["total"] for value in rows) if all(value.get("total") is not None for value in rows) else None
            current = sum(value.get("current", 0) for value in rows)
            completed = sum(bool(value.get("verified")) for value in rows)
            eta = 0.0 if completed == len(rows) else max(0, total - current) / speed if total is not None and speed and current < total else None
            snapshot = {**selected, "phase_id": self.phase_id, "key": "download", "unit": "bytes", "file_count": len(rows),
                        "files_completed": completed, "active_files": len(active), "overall_current": current, "overall_total": total,
                        "overall_speed": speed, "eta_seconds": eta,
                        "last_progress_at": max((value.get("last_progress_at", 0) for value in rows), default=0)}
            self.emit("progress", **snapshot)

class NetworkConfig:
    def __init__(self, state, source=None):
        self.state = Path(state).resolve()
        self.source = dict(os.environ if source is None else source)
        path = safe_path(self.state, "network.json")
        local = checked_json(path) if path.exists() else {}
        if not isinstance(local.get("inherit_system", True), bool):
            raise YuanFault("网络继承配置必须为布尔值 / Network inheritance must be boolean", category="configuration", code="network_config_invalid")
        values = {}
        if local.get("inherit_system", True):
            source = self.source
            home = Path(source.get("HOME") or source.get("USERPROFILE") or str(Path.home()))
            config = source.get("PIP_CONFIG_FILE")
            if not source.get("YUAN_NETWORK_CONFIGURED") and config != os.devnull:
                if os.name == "nt":
                    paths = [Path(source.get("PROGRAMDATA", "C:/ProgramData")) / "pip/pip.ini", home / "pip/pip.ini"]
                    if source.get("APPDATA"):
                        paths.append(Path(source["APPDATA"]) / "pip/pip.ini")
                    paths.append(Path(sys.prefix) / "pip.ini")
                else:
                    paths = [Path(root) / "pip/pip.conf" for root in source.get("XDG_CONFIG_DIRS", "/etc/xdg").split(os.pathsep)]
                    paths += [Path("/etc/pip.conf"), home / ".pip/pip.conf", Path(source.get("XDG_CONFIG_HOME", str(home / ".config"))) / "pip/pip.conf", Path(sys.prefix) / "pip.conf"]
                if config:
                    paths.append(Path(config).expanduser())
                for candidate in dict.fromkeys(paths):
                    if not candidate.is_file():
                        continue
                    parser = configparser.RawConfigParser(interpolation=None)
                    try:
                        with candidate.open(encoding="utf-8-sig") as stream:
                            parser.read_file(stream)
                    except (OSError, configparser.Error, UnicodeError) as exc:
                        raise YuanFault("无法读取 pip 网络配置 / Cannot read pip network settings", category="configuration", code="pip_config_invalid", file=str(candidate)) from exc
                    for section in ("global", "install"):
                        if parser.has_section(section):
                            for key in ("index-url", "extra-index-url", "proxy", "cert", "client-cert"):
                                if parser.has_option(section, key):
                                    values[key] = parser.get(section, key).strip()
            for key in ("index-url", "extra-index-url", "proxy", "cert", "client-cert"):
                value = source.get("PIP_" + key.upper().replace("-", "_"))
                if value:
                    values[key] = value
            values.setdefault("index-url", source.get("UV_DEFAULT_INDEX") or source.get("UV_INDEX_URL") or "https://pypi.org/simple")
            values.setdefault("extra-index-url", source.get("UV_EXTRA_INDEX_URL", ""))
            proxies = urllib.request.getproxies() if source == dict(os.environ) else {}
            values.setdefault("proxy", source.get("https_proxy") or source.get("HTTPS_PROXY") or source.get("all_proxy") or source.get("ALL_PROXY") or proxies.get("https", ""))
            values.setdefault("cert", source.get("REQUESTS_CA_BUNDLE") or source.get("SSL_CERT_FILE", ""))
            values.setdefault("client-cert", source.get("SSL_CLIENT_CERT", ""))
        for field, key in (("index_url", "index-url"), ("proxy", "proxy"), ("ca_file", "cert"), ("client_cert", "client-cert")):
            if field in local:
                if not isinstance(local[field], str):
                    raise YuanFault("网络配置值必须为字符串 / Network setting must be a string", category="configuration", code="network_config_invalid", field=field)
                values[key] = local[field].strip()
        if "extra_index_urls" in local:
            extra = local["extra_index_urls"]
            if not isinstance(extra, list) or not all(isinstance(value, str) for value in extra):
                raise YuanFault("附加包源配置必须为字符串列表 / Extra indices must be a list of strings", category="configuration", code="network_config_invalid")
            values["extra-index-url"] = " ".join(extra)
        self.index_urls = list(dict.fromkeys([values.get("index-url") or "https://pypi.org/simple", *values.get("extra-index-url", "").split()]))
        for url in self.index_urls:
            parsed = urllib.parse.urlsplit(url)
            if parsed.scheme != "https" or not parsed.hostname or any(character.isspace() for character in url):
                raise YuanFault("包源必须使用 HTTPS / Package indices must use HTTPS", category="configuration", code="insecure_package_index", url=url)
        self.proxy = values.get("proxy", "")
        self.proxy_explicit = "proxy" in local
        if self.proxy:
            parsed = urllib.parse.urlsplit(self.proxy)
            if parsed.scheme not in ("http", "https") or not parsed.hostname:
                raise YuanFault("代理必须为 HTTP 或 HTTPS 地址 / Proxy must be an HTTP or HTTPS URL", category="configuration", code="proxy_config_invalid")
        self.ca_file = values.get("cert", "")
        self.client_cert = values.get("client-cert", "")
        for attr in ("ca_file", "client_cert"):
            value = getattr(self, attr)
            if value:
                candidate = Path(value).expanduser()
                if not candidate.is_absolute():
                    candidate = self.state / candidate
                if not candidate.is_file():
                    raise YuanFault("证书文件不可用 / Certificate file unavailable", category="configuration", code="certificate_file_missing", file=str(candidate))
                setattr(self, attr, str(candidate.resolve()))
        self.inherit = local.get("inherit_system", True)

    def apply(self, env):
        for key in tuple(env):
            if key.startswith("PIP_") or key.startswith("UV_") or key in ("REQUESTS_CA_BUNDLE", "SSL_CERT_FILE", "SSL_CLIENT_CERT"):
                env.pop(key, None)
            elif (not self.inherit or self.proxy_explicit) and key.lower() in ("http_proxy", "https_proxy", "all_proxy", "no_proxy"):
                env.pop(key, None)
        env.update(PIP_CONFIG_FILE=os.devnull, PIP_INDEX_URL=self.index_urls[0], UV_INDEX_URL=self.index_urls[0],
                   UV_NATIVE_TLS="1", YUAN_NETWORK_CONFIGURED="1")
        if len(self.index_urls) > 1:
            env["PIP_EXTRA_INDEX_URL"] = env["UV_EXTRA_INDEX_URL"] = " ".join(self.index_urls[1:])
        if self.proxy:
            env["PIP_PROXY"] = self.proxy
            for key in ("HTTP_PROXY", "HTTPS_PROXY", "http_proxy", "https_proxy"):
                env[key] = self.proxy
        if self.ca_file:
            for key in ("PIP_CERT", "SSL_CERT_FILE", "REQUESTS_CA_BUNDLE"):
                env[key] = self.ca_file
        if self.client_cert:
            env["PIP_CLIENT_CERT"] = env["SSL_CLIENT_CERT"] = self.client_cert
        return env

    def opener(self):
        import ssl
        context = ssl.create_default_context(cafile=self.ca_file or None)
        if self.client_cert:
            context.load_cert_chain(self.client_cert)
        handlers = [HTTPSOnly(), urllib.request.HTTPSHandler(context=context)]
        if self.proxy:
            handlers.append(urllib.request.ProxyHandler({"http": self.proxy, "https": self.proxy}))
        elif not self.inherit or self.proxy_explicit:
            handlers.append(urllib.request.ProxyHandler({}))
        passwords = urllib.request.HTTPPasswordMgrWithDefaultRealm()
        for url in self.index_urls:
            parts = urllib.parse.urlsplit(url)
            if parts.username is not None:
                host = parts.netloc.rsplit("@", 1)[-1]
                passwords.add_password(None, parts.scheme + "://" + host, urllib.parse.unquote(parts.username), urllib.parse.unquote(parts.password or ""))
        handlers.append(urllib.request.HTTPBasicAuthHandler(passwords))
        return urllib.request.build_opener(*handlers)

    def summary(self):
        return redact({"indices": self.index_urls, "proxy": self.proxy or None, "ca_file": self.ca_file or "system", "client_cert": bool(self.client_cert)})

class AdaptivePolicy:
    locks = {}
    save_locks = {}
    registry_lock = threading.Lock()

    def __init__(self, state):
        self.state = Path(state)
        self.path = safe_path(self.state, "policy.json")
        self.effective_path = safe_path(self.state, "policy-effective.json")
        self.lock_path = safe_path(self.state, "policy.lock")
        with self.registry_lock:
            identity = str(self.state.resolve())
            self.lock = self.locks.setdefault(identity, threading.RLock())
            self.save_lock = self.save_locks.setdefault(identity, threading.Lock())
        saved = read_json(self.path, {})
        self.overrides = saved.get("overrides", {})
        if not isinstance(self.overrides, dict):
            self.overrides = {}
        saved = read_json(self.effective_path, {})
        self.effective = saved.get("effective", {})
        self.measurements = saved.get("measurements", {})
        if not isinstance(self.effective, dict):
            self.effective = {}
        if not isinstance(self.measurements, dict):
            self.measurements = {}
        self.dirty = {}
        self.observations = {}

    def number(self, section, key, default, lower, upper):
        lower = float(lower)
        upper = max(lower, float(upper))
        with self.lock:
            section_overrides = self.overrides.get(section, {})
            value = section_overrides.get(key, default) if isinstance(section_overrides, dict) else default
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(float(value)):
                value = default
            value = max(lower, min(upper, float(value)))
            self.effective.setdefault(section, {})[key] = value
            self.dirty.setdefault(section, {})[key] = value
        return value

    def integer(self, section, key, default, lower, upper):
        return int(round(self.number(section, key, default, lower, upper)))

    def ratio(self, section, key, default):
        return self.number(section, key, default, 0.0, 1.0)

    def measured(self, section, key, default):
        with self.lock:
            row = self.measurements.get(section, {}).get(key, {})
            value = row.get("mean", default) if isinstance(row, dict) else default
        return value if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value >= 0 else default

    def observe(self, section, key, value):
        value = float(value)
        if not math.isfinite(value) or value < 0:
            return
        horizon = self.number("measurement", "effective_observations", math.sqrt(max(1, os.cpu_count() or 1)) + 1, 1, 4096)
        decay = math.exp(-1 / horizon)
        with self.lock:
            old = self.measurements.setdefault(section, {}).get(key, {})
            count = max(0, int(old.get("count", 0)))
            prior = old.get("mean", value)
            weight = max(0.0, float(old.get("weight", min(count, horizon)))) * decay
            mean = (float(prior) * weight + value) / (weight + 1)
            variance = (float(old.get("variance", 0.0)) * weight + (value - prior) * (value - mean)) / (weight + 1)
            row = {"count": count + 1, "weight": weight + 1, "mean": mean, "variance": max(0.0, variance),
                   "maximum": max(value, float(old.get("maximum", 0.0)) * decay), "updated": time.time()}
            self.measurements[section][key] = row
            delta = self.observations.setdefault(section, {}).setdefault(key, {"count": 0, "factor": 1.0, "weight": 0.0, "total": 0.0, "maximum": 0.0, "squares": 0.0})
            delta["count"] += 1
            delta["factor"] *= decay
            delta["weight"] = delta["weight"] * decay + 1
            delta["total"] = delta["total"] * decay + value
            delta["squares"] = delta["squares"] * decay + value * value
            delta["maximum"] = max(value, delta["maximum"] * decay)

    @contextmanager
    def exclusive(self):
        self.state.mkdir(parents=True, exist_ok=True)
        wait = self.number("policy", "lock_timeout_seconds", 5.0, tick(), 60.0)
        deadline = time.monotonic() + wait
        while True:
            try:
                lease = WorkspaceLease(self.lock_path)
                break
            except YuanError:
                if time.monotonic() >= deadline:
                    raise YuanError("配置写锁超时 / Configuration write lock timed out")
                time.sleep(min(math.sqrt(tick()), max(0.0, deadline - time.monotonic())))
        try:
            yield
        finally:
            lease.close()

    @staticmethod
    def apply_observations(measures, observations):
        for section, values in observations.items():
            target = measures.setdefault(section, {})
            if not isinstance(target, dict):
                raise YuanError("运行测量记录无效 / Invalid runtime measurement record")
            for key, delta in values.items():
                row = target.get(key, {})
                if not isinstance(row, dict):
                    raise YuanError("运行测量记录无效 / Invalid runtime measurement record")
                count = int(row.get("count", 0))
                weight = max(0.0, float(row.get("weight", 0.0))) * delta["factor"]
                total_weight = weight + delta["weight"]
                prior = float(row.get("mean", 0.0))
                mean = (prior * weight + delta["total"]) / total_weight
                second = ((float(row.get("variance", 0.0)) + prior * prior) * weight + delta["squares"]) / total_weight
                target[key] = {"count": count + delta["count"], "weight": total_weight, "mean": mean,
                               "variance": max(0.0, second - mean * mean),
                               "maximum": max(float(row.get("maximum", 0.0)) * delta["factor"], delta["maximum"]), "updated": time.time()}

    @staticmethod
    def merge_observations(older, newer):
        for section, values in newer.items():
            target = older.setdefault(section, {})
            for key, delta in values.items():
                prior = target.get(key)
                if prior is None:
                    target[key] = dict(delta)
                    continue
                target[key] = {"count": prior["count"] + delta["count"], "factor": prior["factor"] * delta["factor"],
                               "maximum": max(prior["maximum"] * delta["factor"], delta["maximum"]),
                               **{name: prior[name] * delta["factor"] + delta[name] for name in ("weight", "total", "squares")}}

    def save(self):
        with self.save_lock:
            with self.lock:
                if not self.dirty and not self.observations:
                    return
            with self.exclusive():
                with self.lock:
                    dirty, observations = self.dirty, self.observations
                    self.dirty, self.observations = {}, {}
                try:
                    payload = read_json(self.effective_path, {})
                    effective = payload.setdefault("effective", {})
                    measures = payload.setdefault("measurements", {})
                    if not isinstance(effective, dict) or not isinstance(measures, dict):
                        raise YuanError("运行测量记录无效 / Invalid runtime measurement record")
                    for section, values in dirty.items():
                        target = effective.setdefault(section, {})
                        if not isinstance(target, dict):
                            raise YuanError("运行配置记录无效 / Invalid runtime configuration record")
                        target.update(values)
                    self.apply_observations(measures, observations)
                    current = read_json(self.path, {}).get("overrides", {})
                    if read_json(self.effective_path, {}) != payload:
                        atomic_json(self.effective_path, payload)
                except BaseException:
                    with self.lock:
                        for section, values in self.dirty.items():
                            dirty.setdefault(section, {}).update(values)
                        self.merge_observations(observations, self.observations)
                        self.dirty, self.observations = dirty, observations
                    raise
                with self.lock:
                    for section, values in self.dirty.items():
                        effective.setdefault(section, {}).update(values)
                    self.apply_observations(measures, self.observations)
                    self.effective, self.measurements = effective, measures
                    if isinstance(current, dict):
                        self.overrides = current

    def estimate(self, section, key, default, upper_tail=True):
        from statistics import NormalDist
        with self.lock:
            row = dict(self.measurements.get(section, {}).get(key, {}))
        count = row.get("count", 0)
        mean, variance = row.get("mean"), row.get("variance", 0.0)
        if not isinstance(count, int) or count < 2 or not isinstance(mean, (int, float)) or not math.isfinite(mean) or mean < 0:
            return default
        confidence = self.number("measurement", "confidence", 0.95, 0.5, 0.999)
        spread = math.sqrt(max(0.0, float(variance)))
        quantile = NormalDist().inv_cdf(confidence) if upper_tail else 0.0
        value = mean + quantile * spread * math.sqrt(1 + 1 / count)
        return value if math.isfinite(value) else default


@contextmanager
def operation(emit, key, scope="startup", budget_seconds=None, stall_seconds=None, **details):
    operation_id = uuid.uuid4().hex
    started = time.monotonic()
    values = {"key": key, "operation_id": operation_id, "scope": scope, "pid": os.getpid(), "thread": threading.current_thread().name, **details}
    if budget_seconds is not None:
        values["budget_seconds"] = budget_seconds
    if stall_seconds is not None:
        values["stall_seconds"] = stall_seconds
    emit("operation", **values, outcome="begin")
    try:
        yield operation_id
    except BaseException as exc:
        emit("operation", **values, outcome="cancelled" if isinstance(exc, Cancelled) else "failed", elapsed=time.monotonic() - started, reason=concise_error(exc), fault=fault_event(exc, key))
        raise
    else:
        emit("operation", **values, outcome="complete", elapsed=time.monotonic() - started)

def supervised(key, scope="runtime"):
    def decorate(function):
        @wraps(function)
        def execute(self, *args, **kwargs):
            with operation(self.emit, key, scope):
                return function(self, *args, **kwargs)
        return execute
    return decorate

def supervised_stream(key, scope="runtime"):
    def decorate(function):
        @wraps(function)
        def execute(self, *args, **kwargs):
            iterator = function(self, *args, **kwargs)
            try:
                while True:
                    with operation(self.emit, key, scope, replaceable=True):
                        try:
                            value = next(iterator)
                        except StopIteration:
                            return
                    yield value
            finally:
                with operation(self.emit, key + "_close", scope, replaceable=True):
                    iterator.close()
        return execute
    return decorate

class StageSupervisor:
    def __init__(self, state, emit, clock=None, identity=None):
        self.policy = AdaptivePolicy(state)
        self.emit = emit
        self.clock = clock or time.monotonic
        self.path = safe_path(state, "supervision.json")
        self.fingerprint = identity or runtime_identity(state)
        saved = read_json(self.path, {})
        profiles = saved.get("profiles", {})
        self.profiles = profiles if isinstance(profiles, dict) else {}
        profile = self.profiles.get(self.fingerprint, {})
        self.history = profile.get("stages", {}) if isinstance(profile, dict) else {}
        if not isinstance(self.history, dict):
            self.history = {}
        self.minimum = self.policy.number("supervision", "minimum_seconds", 1.0, tick(), 60.0)
        self.ceiling = self.policy.number("supervision", "maximum_phase_seconds", 1800.0, self.minimum, 86400.0)
        self.initial = self.policy.number("supervision", "initial_phase_seconds", 120.0, self.minimum, self.ceiling)
        self.margin = self.policy.number("supervision", "history_margin", 4.0, 1.0, 32.0)
        self.period = self.policy.number("supervision", "heartbeat_seconds", 1.0, math.sqrt(tick()), 10.0)
        self.grace = self.policy.number("supervision", "shutdown_seconds", 60.0, self.minimum, self.ceiling)
        self.policy.save()
        self.active = {}
        self.last_report = -math.inf
        self.startup = None
        self.history_dirty = False
        self.last_history_write = -math.inf

    def budget(self, key, suggested=None):
        baseline = self.initial
        row = self.history.get(key, {})
        if isinstance(row, dict):
            measured = row.get("seconds")
            if isinstance(measured, (int, float)) and not isinstance(measured, bool) and math.isfinite(measured) and measured > 0:
                baseline = max(self.initial, measured * self.margin)
        if isinstance(suggested, (int, float)) and not isinstance(suggested, bool) and math.isfinite(suggested) and suggested > 0:
            baseline = max(baseline, suggested)
        return self.policy.number("supervision", key + "_seconds", baseline, self.minimum, self.ceiling)

    def start(self, pid, remaining=None):
        now = self.clock()
        total = self.policy.number("supervision", "startup_total_seconds", self.initial * 16, self.initial, 86400.0)
        if remaining is not None:
            total = min(total, max(tick(), remaining))
        self.startup = {"key": "engine_startup", "started": now, "deadline": now + total, "budget_seconds": total, "pid": pid, "operation_id": "startup"}
        self.active["bootstrap"] = {"key": "engine_startup", "started": now, "deadline": now + self.budget("engine_startup"), "pid": pid, "operation_id": "bootstrap"}
        self.policy.save()

    def record(self, key, outcome, seconds, fault=None):
        row = self.history.setdefault(key, {})
        if not isinstance(row, dict):
            row = self.history[key] = {}
        row["at"] = time.time()
        if outcome == "complete":
            previous = row.get("seconds", seconds)
            if not isinstance(previous, (int, float)) or not math.isfinite(previous) or previous <= 0:
                previous = seconds
            row["seconds"] = max(seconds, (previous + seconds) / 2)
            row["successes"] = int(row.get("successes", 0)) + 1
            row["consecutive_failures"] = 0
        elif outcome == "failed":
            row["failures"] = int(row.get("failures", 0)) + 1
            row["consecutive_failures"] = int(row.get("consecutive_failures", 0)) + 1
            row["last_failure"] = {"elapsed_lower_bound": seconds, **(fault or {})}
        self.history_dirty = True

    def observe(self, event):
        kind = event.get("type")
        if kind == "ready":
            self.startup = None
            self.active.pop("bootstrap", None)
            self.active.pop("handoff", None)
        elif kind == "operation":
            identifier, key = event.get("operation_id"), event.get("key")
            if not isinstance(identifier, str) or not identifier or not isinstance(key, str) or not key:
                return
            replaceable = event.get("replaceable") is True and event.get("scope") != "startup"
            if replaceable:
                identifier = payload_digest([event.get("scope"), event.get("pid"), event.get("thread"), key])
            outcome = event.get("outcome")
            now = self.clock()
            if outcome == "begin":
                self.active.pop("bootstrap", None)
                self.active.pop("handoff", None)
                if replaceable or identifier not in self.active:
                    budget = self.budget(key, event.get("budget_seconds"))
                    suggested = event.get("stall_seconds", budget)
                    if isinstance(suggested, bool) or not isinstance(suggested, (int, float)) or not math.isfinite(suggested) or suggested <= 0:
                        suggested = budget
                    stall = self.policy.number("supervision", key + "_stall_seconds", suggested, self.minimum, budget)
                    self.active[identifier] = {**event, "started": now, "deadline": now + budget, "budget_seconds": budget,
                                               "stall_seconds": stall, "stall_deadline": now + stall, "progress": -1}
            elif outcome == "progress":
                row, current = self.active.get(identifier), event.get("current")
                if row is not None and row["key"] == key and isinstance(current, (int, float)) and not isinstance(current, bool) and math.isfinite(current) and current > row["progress"]:
                    row["progress"] = current
                    row["stall_deadline"] = now + row["stall_seconds"]
            elif outcome in ("complete", "cancelled", "failed"):
                row = self.active.get(identifier)
                if row is None or row["key"] != key:
                    return
                self.active.pop(identifier)
                if outcome != "cancelled":
                    self.record(key, outcome, max(tick(), now - row["started"]), event.get("fault"))
                    self.flush_history(force=outcome == "failed")
            else:
                return
            if self.startup and not self.active:
                self.active["handoff"] = {"key": "engine_startup", "started": now, "deadline": now + self.budget("engine_startup"), "pid": self.startup["pid"], "operation_id": "handoff"}
            self.last_report = -math.inf

    def flush_history(self, force=False):
        now = self.clock()
        if not self.history_dirty or not force and now - self.last_history_write < self.period:
            return
        self.last_history_write = now
        try:
            profiles = read_json(self.path, {}).get("profiles", {})
            if not isinstance(profiles, dict):
                profiles = {}
            profiles[self.fingerprint] = {"stages": self.history, "at": time.time()}
            limit = self.policy.integer("supervision", "retained_profiles", 8, 1, 128)
            profiles = dict(sorted(profiles.items(), key=lambda item: item[1].get("at", 0) if isinstance(item[1], dict) else 0, reverse=True)[:limit])
            atomic_json(self.path, {"profiles": profiles})
            self.history_dirty = False
        except (OSError, YuanError) as exc:
            self.emit("notice", key="journal_failure", component="supervision_history", reason=concise_error(exc))

    def poll(self):
        now = self.clock()
        rows = list(self.active.values()) + ([self.startup] if self.startup else [])
        def deadline(row):
            return min(row["deadline"], row.get("stall_deadline", row["deadline"]))
        for row in sorted(rows, key=deadline):
            if now >= deadline(row):
                details = {"operation_id": row.get("operation_id"), "pid": row.get("pid"), "elapsed": now - row["started"],
                           "budget_seconds": row["deadline"] - row["started"],
                           "timeout_kind": "total" if now >= row["deadline"] else "stalled", "component": row.get("component")}
                fault = EngineFault("阶段执行期限已到 / Stage deadline reached", category="timeout", code="stage_deadline" if now >= row["deadline"] else "stage_stalled", stage=row["key"], **details)
                if not row.get("failure_recorded"):
                    row["failure_recorded"] = True
                    self.record(row["key"], "failed", now - row["started"], fault_event(fault))
                    self.flush_history(force=True)
                raise fault
        self.flush_history()
        if now - self.last_report >= self.period:
            self.last_report = now
            row = min(rows, key=deadline) if rows else None
            if row:
                self.emit("supervision", key=row["key"], operation_id=row.get("operation_id"), pid=row.get("pid"), elapsed=now - row["started"],
                          remaining_seconds=max(0.0, deadline(row) - now), total_remaining_seconds=max(0.0, row["deadline"] - now), total=None)
            else:
                self.emit("supervision", complete=True)

class WorkspaceLease:
    def __init__(self, path):
        self.stream = None
        path = Path(path)
        path.parent.mkdir(parents=True, exist_ok=True)
        if path.is_symlink():
            raise YuanError("拒绝使用链接锁文件 / Refusing a linked lock file")
        stream = path.open("a+b")
        try:
            if os.name == "nt":
                import msvcrt
                if path.stat().st_size == 0:
                    stream.write(b"\0")
                    stream.flush()
                stream.seek(0)
                msvcrt.locking(stream.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl
                fcntl.flock(stream.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            self.stream = stream
        except Exception:
            stream.close()
            raise YuanError("另一个 Yuan 正在使用此目录 / Another Yuan is using this workspace")

    def close(self):
        stream, self.stream = self.stream, None
        if stream is None:
            return
        try:
            if os.name == "nt":
                import msvcrt
                stream.seek(0)
                msvcrt.locking(stream.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl
                fcntl.flock(stream.fileno(), fcntl.LOCK_UN)
        finally:
            stream.close()

    def __enter__(self):
        return self

    def __exit__(self, *args):
        self.close()

def workspace_state(workspace):
    return ensure_workspace_identity(safe_path(workspace, STATE_NAME + "-" + build_digest()))

def ensure_workspace_identity(state, verified_assets=False):
    state = Path(state).resolve()
    identity = {"protocol": "yuan-workspace-v1", "build_sha256": build_digest(), "schema_version": 1}
    path = safe_path(state, "workspace-identity.json")
    if path.exists():
        if checked_json(path) != identity:
            raise YuanFault("数据空间属于其他版本，已拒绝复用 / Workspace belongs to another build; reuse refused", category="integrity", code="workspace_build_mismatch")
    else:
        if any((state / name).exists() for name in ("memory/memory.sqlite3", "runtime-current.json", "policy-effective.json")) or (state / "learning").exists() and not verified_assets:
            raise YuanFault("数据空间缺少当前版本身份，已保留且不加载 / Existing workspace has no current-build identity; preserved without loading", category="integrity", code="workspace_identity_missing")
        state.mkdir(parents=True, exist_ok=True)
        atomic_json(path, identity)
    return state

def workspace_environment(workspace):
    workspace = Path(workspace).resolve()
    state = ensure_workspace_identity(workspace_state(workspace))
    cache = safe_path(state, "cache")
    values = {
        "HOME": state / "home", "USERPROFILE": state / "home",
        "APPDATA": state / "config" / "roaming", "LOCALAPPDATA": state / "config" / "local",
        "TORCH_HOME": cache / "torch", "TORCH_EXTENSIONS_DIR": cache / "torch-extensions",
        "TRITON_CACHE_DIR": cache / "triton", "TORCHINDUCTOR_CACHE_DIR": cache / "inductor", "CUDA_CACHE_PATH": cache / "cuda",
        "XDG_CACHE_HOME": cache / "xdg", "XDG_CONFIG_HOME": state / "config", "XDG_DATA_HOME": state / "data", "XDG_STATE_HOME": state / "state",
        "UV_CACHE_DIR": cache / "uv", "UV_PYTHON_INSTALL_DIR": state / "python", "UV_TOOL_DIR": state / "tools",
        "UV_TOOL_BIN_DIR": state / "bin", "UV_PYTHON_BIN_DIR": state / "bin", "PIP_CACHE_DIR": cache / "pip",
        "TMPDIR": state / "temp", "TEMP": state / "temp", "TMP": state / "temp",
    }
    env = NetworkConfig(state).apply(os.environ.copy())
    for key in ("PYTHONPATH", "PYTHONHOME", "VIRTUAL_ENV", "PYTHONSTARTUP"):
        env.pop(key, None)
    for key in ("CUDA_VISIBLE_DEVICES", "HIP_VISIBLE_DEVICES", "ROCR_VISIBLE_DEVICES"):
        if env.get(key) in ("", "-1"):
            env.pop(key, None)
    for key, path in values.items():
        path = safe_path(state, path.relative_to(state).as_posix())
        path.mkdir(parents=True, exist_ok=True)
        env[key] = str(path)
    env.update({
        "YUAN_WORKSPACE": str(workspace), "PYTHONNOUSERSITE": "1", "PYTHONDONTWRITEBYTECODE": "1", "PYTHONUNBUFFERED": "1",
        "PYTHONUTF8": "1", "PYTHONIOENCODING": "utf-8", "PIP_NO_COMPILE": "1", "UV_COMPILE_BYTECODE": "0",
        "PIP_DISABLE_PIP_VERSION_CHECK": "1", "PIP_NO_INPUT": "1", "PIP_CONFIG_FILE": os.devnull, "UV_NO_MODIFY_PATH": "1", "UV_PYTHON_INSTALL_BIN": "0",
    })
    return env

def host_python():
    path = Path(sys.executable)
    if os.name == "nt" and path.name.lower() in ("pythonw.exe", "pythonw_d.exe"):
        console = path.with_name(path.name.lower().replace("pythonw", "python", 1))
        if console.is_file():
            return str(console)
    return str(path)

def runtime_python(path):
    return Path(path) / ("Scripts/python.exe" if os.name == "nt" else "bin/python")

def end_process(process, timeout=None):
    if process is None or process.poll() is not None:
        return
    grace = max(tick(), timeout if timeout is not None else max(1.0, math.sqrt(os.cpu_count() or 1)))
    try:
        if os.name == "nt":
            subprocess.run(["taskkill", "/PID", str(process.pid), "/T", "/F"], stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
                           check=False, timeout=grace, creationflags=subprocess.CREATE_NO_WINDOW)
        else:
            os.killpg(process.pid, signal.SIGTERM)
    except (OSError, subprocess.TimeoutExpired):
        try:
            process.terminate()
        except OSError:
            pass
    try:
        process.wait(timeout=grace)
        return
    except subprocess.TimeoutExpired:
        pass
    try:
        if os.name != "nt":
            os.killpg(process.pid, signal.SIGKILL)
        else:
            process.kill()
    except OSError:
        pass
    try:
        process.wait(timeout=grace)
    except subprocess.TimeoutExpired as exc:
        raise EngineFault("系统未能回收进程，已停止启动重试 / OS could not reclaim the process; startup retries stopped", code="process_reap_failed", pid=process.pid, process_retained=True) from exc

def spawn(command, env, **kwargs):
    options = {"start_new_session": True} if os.name != "nt" else {"creationflags": subprocess.CREATE_NEW_PROCESS_GROUP | subprocess.CREATE_NO_WINDOW}
    return subprocess.Popen(command, env=env, cwd=env["YUAN_WORKSPACE"], **options, **kwargs)

def process_activity(pid):
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes
        class Counters(ctypes.Structure):
            _fields_ = [(name, ctypes.c_ulonglong) for name in ("reads", "writes", "others", "read_bytes", "write_bytes", "other_bytes")]
        kernel = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel.OpenProcess.argtypes = (wintypes.DWORD, wintypes.BOOL, wintypes.DWORD)
        kernel.OpenProcess.restype = wintypes.HANDLE
        kernel.GetProcessTimes.argtypes = (wintypes.HANDLE, ctypes.POINTER(wintypes.FILETIME), ctypes.POINTER(wintypes.FILETIME), ctypes.POINTER(wintypes.FILETIME), ctypes.POINTER(wintypes.FILETIME))
        kernel.GetProcessIoCounters.argtypes = (wintypes.HANDLE, ctypes.POINTER(Counters))
        kernel.CloseHandle.argtypes = (wintypes.HANDLE,)
        handle = kernel.OpenProcess(0x1000, False, pid)
        if not handle:
            return None
        try:
            created, ended, system, user = (wintypes.FILETIME() for _ in range(4))
            counters = Counters()
            if not kernel.GetProcessTimes(handle, ctypes.byref(created), ctypes.byref(ended), ctypes.byref(system), ctypes.byref(user)):
                return None
            cpu = (((system.dwHighDateTime << 32) | system.dwLowDateTime) + ((user.dwHighDateTime << 32) | user.dwLowDateTime)) / 10000000
            if not kernel.GetProcessIoCounters(handle, ctypes.byref(counters)):
                return (cpu, 0, 0)
            return (cpu, counters.read_bytes, counters.write_bytes)
        finally:
            kernel.CloseHandle(handle)
    if sys.platform.startswith("linux"):
        try:
            root = Path("/proc") / str(pid)
            fields = (root / "stat").read_text().rsplit(")", 1)[1].split()
            cpu = (int(fields[11]) + int(fields[12])) / os.sysconf("SC_CLK_TCK")
            values = {}
            try:
                for line in (root / "io").read_text().splitlines():
                    key, value = line.split(":", 1)
                    values[key] = int(value.strip())
            except OSError:
                pass
            return (cpu, values.get("read_bytes", 0) + values.get("rchar", 0), values.get("write_bytes", 0) + values.get("wchar", 0))
        except (OSError, ValueError, IndexError):
            return None
    return None

def run_command(command, env, cancel, progress=None, heartbeat=None, heartbeat_seconds=None, stall_seconds=None, timeout_seconds=None, stage=None, events=None, adaptive=False):
    check(cancel)
    process = spawn(command, env, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, stdin=subprocess.DEVNULL, text=True, encoding="utf-8", errors="replace", bufsize=1)
    result = deque(maxlen=256)
    updates = queue.Queue(maxsize=max(16, (os.cpu_count() or 1) * 2))
    stopped = threading.Event()
    started = last_output = last_activity = time.monotonic()
    last_heartbeat = -math.inf
    period = max(tick(), heartbeat_seconds or math.sqrt(tick()))
    budget = timeout_seconds if timeout_seconds is not None else max(period, stall_seconds * 4 if stall_seconds else 120.0)
    if isinstance(budget, bool) or not isinstance(budget, (int, float)) or not math.isfinite(budget) or budget <= 0:
        end_process(process)
        process.stdout.close()
        raise ValueError("Invalid process deadline")
    deadline = started + budget
    previous_activity = None
    previous_progress = None
    progress_stages = set()
    monitor = None
    psutil = sys.modules.get("psutil")
    if psutil is not None:
        try:
            monitor = psutil.Process(process.pid)
        except Exception:
            pass
    evidence = {}
    child_fault = None
    def read():
        try:
            while not stopped.is_set():
                line = process.stdout.readline(65536)
                if not line:
                    break
                while not stopped.is_set():
                    try:
                        updates.put(line.rstrip("\r\n"), timeout=math.sqrt(tick()))
                        break
                    except queue.Full:
                        pass
        except (OSError, ValueError):
            pass
    reader = threading.Thread(target=read, daemon=True, name="YuanComponentOutput")
    reader.start()
    try:
        while process.poll() is None or reader.is_alive() or not updates.empty():
            check(cancel)
            try:
                line = updates.get(timeout=min(period, math.sqrt(tick())))
            except queue.Empty:
                line = None
            if line is not None:
                result.append(line)
                last_output = time.monotonic()
                if adaptive:
                    raw = re.fullmatch(r"Progress ([0-9]+) of ([0-9]+)", line.strip())
                    productive = False
                    if raw:
                        current = (int(raw[1]), int(raw[2]))
                        productive = previous_progress is None or current[1] != previous_progress[1] or current[0] > previous_progress[0]
                        previous_progress = current
                    elif "Downloading " in line or "Using cached " in line:
                        previous_progress = None
                    elif re.search(r"Installing collected packages|Successfully installed", line) and line not in progress_stages:
                        progress_stages.add(line)
                        productive = True
                    if productive:
                        deadline = max(deadline, last_output + budget)
                category = failure_category(YuanError(line))
                if category != "unknown":
                    evidence.setdefault(category, line)
                event = None
                if events is not None:
                    try:
                        candidate = json.loads(line)
                        if isinstance(candidate, dict) and isinstance(candidate.get("type"), str):
                            event = candidate
                    except (ValueError, TypeError):
                        pass
                if event is not None:
                    if event.get("type") == "error" and isinstance(event.get("fault"), dict):
                        child_fault = event["fault"]
                    events(event)
                elif progress:
                    progress(redact(line))
            now = time.monotonic()
            if now >= deadline and process.poll() is None:
                raise YuanFault("组件执行期限已到 / Component execution deadline reached", category="timeout", code="component_deadline", stage=stage,
                                command=[str(value) for value in command], pid=process.pid, elapsed=now-started, budget_seconds=budget, output=redact(list(result)))
            if now - last_heartbeat >= period:
                last_heartbeat = now
                activity = None
                if monitor is not None:
                    try:
                        processes = [monitor, *monitor.children(recursive=True)]
                        cpu_seconds = read_bytes = write_bytes = 0.0
                        for child in processes:
                            cpu = child.cpu_times()
                            cpu_seconds += cpu.user + cpu.system
                            try:
                                io = child.io_counters()
                                read_bytes += io.read_bytes
                                write_bytes += io.write_bytes
                            except (AttributeError, OSError, psutil.Error):
                                pass
                        activity = (round(cpu_seconds, 6), read_bytes, write_bytes)
                        if activity != previous_activity:
                            previous_activity = activity
                            last_activity = now
                            if adaptive:
                                deadline = max(deadline, now + budget)
                    except (OSError, psutil.Error):
                        monitor = None
                if activity is None:
                    activity = process_activity(process.pid)
                    if activity is not None and activity != previous_activity:
                        previous_activity = activity
                        last_activity = now
                        if adaptive:
                            deadline = max(deadline, now + budget)
                if heartbeat:
                    heartbeat({"pid": process.pid, "elapsed": now - started, "output_idle": now - last_output, "activity_idle": now - last_activity,
                               "process_running": process.poll() is None, "process_activity": activity, "monitor_available": activity is not None,
                               "remaining_seconds": max(0.0, deadline - now), "budget_seconds": budget})
                if stall_seconds and now - max(last_output, last_activity) > stall_seconds and process.poll() is None:
                    raise YuanFault("组件没有可观察进展 / No observable component progress", category="timeout", code="component_stalled", stage=stage,
                                    command=[str(value) for value in command], pid=process.pid, idle_seconds=now-max(last_output, last_activity), output=redact(list(result)))
        returncode = process.wait()
        if child_fault:
            raise YuanFault(child_fault.get("reason") or "运行预检失败 / Runtime probe failed", category=child_fault.get("category", "unknown"),
                            code=child_fault.get("code", "runtime_probe_failed"), stage=child_fault.get("stage") or stage, **child_fault.get("details", {}))
        if returncode:
            category = next((key for key in ("storage", "integrity", "network", "compatibility", "resolution") if key in evidence), "unknown")
            urls = re.findall(r"https://[^\s\"'<>]+", evidence.get("network", ""))
            raise YuanFault("运行组件未能准备完成 / Runtime preparation failed", category=category, code="package_command_failed", stage=stage,
                            command=[str(value) for value in command], pid=process.pid, returncode=returncode, output=redact(list(result)),
                            evidence=redact(evidence), url=urls[0].rstrip(").,;:") if urls else None)
        return "\n".join(result)
    finally:
        stopped.set()
        try:
            if process.poll() is None:
                end_process(process)
            if events is not None:
                events({"type": "process_reaped", "scope": "runtime_probe", "pid": process.pid, "returncode": process.returncode})
        finally:
            reader.join(timeout=max(period, math.sqrt(tick())))
            if not reader.is_alive():
                process.stdout.close()

def startup_preflight(state, dependencies=None, emit=None):
    state = Path(state)
    state.mkdir(parents=True, exist_ok=True)
    fd, name = tempfile.mkstemp(prefix=".preflight-", dir=state)
    try:
        os.write(fd, b"Yuan")
        os.fsync(fd)
    finally:
        os.close(fd)
        Path(name).unlink(missing_ok=True)
    disk = shutil.disk_usage(state)
    result = {"storage_writable": True, "free_bytes": disk.free, "python": platform.python_version(), "system": platform.system(),
              "machine": platform.machine(), "display": bool(sys.platform in ("win32", "darwin") or os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY")),
              "device_presence": None, "audio_permissions": "not_probed", "runtime_profile": "yuan-runtime-v6"}
    if disk.free <= 0:
        raise YuanError("所选目录没有可用空间 / Selected folder has no free space")
    if dependencies is not None:
        sd = dependencies["sounddevice"]
        result.update(audio_ready=False, audio_formats="unavailable", audio_failure=None)
        try:
            devices = sd.query_devices()
            inputs = [index for index, device in enumerate(devices) if int(device.get("max_input_channels", 0)) > 0]
            outputs = [index for index, device in enumerate(devices) if int(device.get("max_output_channels", 0)) > 0]
            result.update(device_presence=bool(inputs and outputs), input_devices=len(inputs), output_devices=len(outputs))
            if not inputs or not outputs:
                result["audio_failure"] = "device_absent"
            else:
                failures = {}
                for direction, indices in (("input", inputs), ("output", outputs)):
                    reasons = []
                    for index in indices:
                        try:
                            getattr(sd, "check_" + direction + "_settings")(device=index, channels=1, dtype="float32", samplerate=int(round(devices[index]["default_samplerate"])))
                            break
                        except (OSError, ValueError, RuntimeError, sd.PortAudioError) as exc:
                            reasons.append(concise_error(exc))
                    else:
                        failures[direction] = reasons
                result.update(audio_ready=not failures, audio_formats="unsupported" if failures else "supported", audio_failure=failures or None)
        except (OSError, RuntimeError, sd.PortAudioError) as exc:
            result.update(audio_failure=concise_error(exc), audio_formats="unavailable")
        if not result["audio_ready"] and emit:
            emit("deployment_preflight", key="audio_wait", learning_blocked=False, **result)
    if emit:
        emit("deployment_preflight", key="deployment_preflight", **result)
    return result

class WheelCatalog:
    @staticmethod
    def tags(python, command):
        program = "import json;from pip._vendor.packaging.tags import sys_tags;print(json.dumps([str(t) for t in sys_tags()]))"
        values = json.loads(command([str(python), "-c", program]).strip())
        if not isinstance(values, list) or not values or not all(isinstance(value, str) for value in values):
            raise YuanFault("解释器平台标签无效 / Invalid interpreter platform tags", category="compatibility", code="wheel_tags_invalid")
        return {tag: index for index, tag in enumerate(values)}

    @staticmethod
    def select(text, base, tags, name, version):
        from html.parser import HTMLParser
        class Links(HTMLParser):
            def __init__(self):
                super().__init__(convert_charrefs=True)
                self.rows = []
            def handle_starttag(self, tag, attrs):
                if tag.casefold() == "a":
                    self.rows.append(dict(attrs))
        parser = Links()
        parser.feed(text)
        candidates = []
        for row in parser.rows:
            if "data-yanked" in row:
                continue
            url = urllib.parse.urljoin(base, row.get("href") or "")
            parsed = urllib.parse.urlsplit(url)
            if parsed.scheme != "https" or parsed.hostname not in ("download.pytorch.org", "download-r2.pytorch.org") or parsed.username or parsed.password:
                continue
            filename = urllib.parse.unquote(parsed.path.rsplit("/", 1)[-1])
            parts = filename[:-4].split("-") if filename.endswith(".whl") else []
            if len(parts) not in (5, 6) or parts[0].replace("_", "-").casefold() != name.casefold() or parts[1].split("+", 1)[0] != version:
                continue
            ranks = [tags[key] for py in parts[-3].split(".") for abi in parts[-2].split(".") for platform_tag in parts[-1].split(".") if (key := py + "-" + abi + "-" + platform_tag) in tags]
            digest = urllib.parse.parse_qs(parsed.fragment).get("sha256", [None])[0]
            if not ranks or not is_digest(digest):
                continue
            clean = urllib.parse.urlunsplit(parsed._replace(fragment=""))
            candidates.append((min(ranks), filename, {"name": name, "version": parts[1], "url": clean, "filename": filename, "sha256": digest}))
        if not candidates:
            raise YuanFault("当前后端没有匹配的官方运行组件 / No matching official runtime wheel for this backend", category="compatibility", code="wheel_candidate_missing", backend=base, version=version)
        return min(candidates, key=lambda value: value[:2])[2]

    @staticmethod
    def read(network, url, cancel):
        chunks, length = [], 0
        with network.request(url) as response:
            for chunk in network.blocks(response):
                check(cancel)
                length += len(chunk)
                if length > 64 * 1024 * 1024:
                    raise InvalidDownload("组件目录超过安全大小 / Component catalog exceeds its safety bound")
                chunks.append(chunk)
        return b"".join(chunks).decode("utf-8")

class RuntimeInstaller:
    def __init__(self, workspace, cancel, emit):
        self.workspace, self.cancel, self.emit = Path(workspace), cancel, emit
        self.state = workspace_state(workspace)
        self.env = workspace_environment(workspace)
        self.lock_path = safe_path(self.state, "runtime-lock.json")
        self.policy = AdaptivePolicy(self.state)
        self.network_config = NetworkConfig(self.state)
        self.network = Network(cancel, self.policy, self.network_config)
        self.heartbeat_seconds = self.policy.number("runtime", "heartbeat_seconds", 1.0, math.sqrt(tick()), max(1.0, math.sqrt(os.cpu_count() or 1)))
        self.stall_seconds = self.policy.number("runtime", "process_stall_seconds", self.network.timeout_ceiling * 4, self.network.timeout_ceiling, max(self.network.timeout_ceiling * 4, self.network.timeout_ceiling * (os.cpu_count() or 1)))
        self.download_attempts = self.policy.integer("runtime", "download_attempts", 3, 1, max(3, math.isqrt(os.cpu_count() or 1)))
        self.phase = "runtime"
        self.phase_id = uuid.uuid4().hex
        self.supervisor = StageSupervisor(self.state, self.emit)
        self.progress = {}
        self.last_raw = None
        self.reuse_cache = {}
        self.cached_checked = False
        self.cached_value = None
        self.verified_entry = None
        self.hardware = self.detect_hardware()
        self.compute_backend = None
        self.policy.save()
        self.emit("runtime_network", key="runtime_network", **self.network_config.summary())

    def stage(self, key):
        self.phase = key
        self.phase_id = uuid.uuid4().hex
        self.progress = {"phase_id": self.phase_id, "key": key, "current": 0, "total": None, "unit": "bytes", "last_progress_at": time.time()}
        self.last_raw = None
        self.emit("status", key=key, phase_id=self.phase_id)
        self.emit("progress", **self.progress)
        self.resources()

    def resources(self, **values):
        self.selected_executable = str(values.pop("executable", getattr(self, "selected_executable", host_python())))
        data = {"executable": self.selected_executable, "process_running": False, "monitor_available": False,
                "task_running": True, "task_kind": self.phase}
        try:
            disk = shutil.disk_usage(self.state)
            data.update(disk_free=disk.free, disk_total=disk.total)
        except OSError:
            pass
        self.emit("startup_resources", **{**data, **values})

    def report(self, line):
        line = line.strip()
        if not line:
            return
        raw = re.fullmatch(r"Progress ([0-9]+) of ([0-9]+)", line)
        if raw:
            current, total = int(raw[1]), int(raw[2])
            now = time.monotonic()
            speed = None
            if self.last_raw and current >= self.last_raw[1]:
                speed = (current - self.last_raw[1]) / max(tick(), now - self.last_raw[0])
            self.last_raw = (now, current)
            self.progress.update(current=current, total=total or None, speed=speed, last_progress_at=time.time())
        else:
            if "Downloading " in line or "Using cached " in line:
                self.last_raw = None
                self.progress.update(current=0, total=None, speed=None, file=line, detail=line)
            else:
                self.progress["detail"] = line
            self.progress["last_progress_at"] = time.time()
            self.emit("runtime_message", detail=line, stage=self.phase)
        self.emit("progress", **self.progress)

    def command(self, command, report=False, transfer=False):
        is_probe = any(flag in command for flag in ("--probe", "--probe-import", "--verify-install"))
        def receive(event):
            self.supervisor.observe(event)
            if event.get("type") not in ("error", "exit", "ready", "status"):
                values = {key: value for key, value in event.items() if key not in ("type", "attempt_id", "_sequence", "at", "event_sequence", "phase_id")}
                self.emit(event["type"], **values)
        def heartbeat(values):
            self.resources(executable=command[0], **values)
            if is_probe:
                self.supervisor.poll()
            self.emit("progress", **{**self.progress, **values})
        budget = self.supervisor.budget(self.phase, self.stall_seconds)
        env = dict(self.env)
        if is_probe:
            names = (command[-1],) if "--probe-import" in command else () if "--verify-install" in command else RUNTIME_MODULES
            budgets = {"stage_import_" + name: self.supervisor.budget("stage_import_" + name) for name in names}
            if "--probe" in command:
                budgets["stage_probe_compute"] = self.supervisor.budget("stage_probe_compute")
            if "--verify-install" in command:
                budgets["runtime_inventory"] = budget
            env["YUAN_IMPORT_BUDGETS"] = json.dumps(budgets)
            env["YUAN_IMPORT_IDENTITY"] = self.supervisor.fingerprint
            budget = max(budget, sum(budgets.values()) + self.supervisor.grace)
        if isinstance(self.cancel, StartupControl):
            check(self.cancel)
            env["YUAN_STARTUP_DEADLINE"] = str(self.cancel.deadline)
        self.supervisor.policy.save()
        began = time.monotonic()
        try:
            with self.cancel.transfer() if transfer and isinstance(self.cancel, StartupControl) else nullcontext():
                result = run_command(command, env, self.cancel, self.report if report else None, heartbeat=heartbeat,
                                     heartbeat_seconds=self.heartbeat_seconds, stall_seconds=None if is_probe else self.stall_seconds,
                                     timeout_seconds=budget, stage=self.phase, events=receive if is_probe else None, adaptive=not is_probe)
            self.emit("runtime_message", stage=self.phase, command=[str(value) for value in command], returncode=0, elapsed=time.monotonic()-began)
            return result
        except YuanFault as exc:
            if exc.stage is None:
                exc.stage = self.phase
            raise
        finally:
            self.supervisor.flush_history(force=True)
            if is_probe:
                self.supervisor.active.clear()
                self.supervisor.startup = None
                self.emit("supervision", complete=True)
            self.resources(executable=command[0])

    def interpreter(self, request="host"):
        if request == "host":
            if sys.version_info[:2] < (3, 10):
                raise YuanError("当前 Python 版本不满足要求 / Host Python does not meet requirements")
            return host_python()
        executable = self._uv()
        self.command([str(executable), "--no-config", "python", "install", request], report=True, transfer=True)
        result = self.command([str(executable), "--no-config", "python", "find", "--managed-python", request]).strip().splitlines()
        if not result:
            raise YuanError("独立 Python 查找结果为空 / Managed Python lookup returned no result")
        resolved = Path(result[-1]).resolve()
        if Path(self.env["UV_PYTHON_INSTALL_DIR"]).resolve() not in resolved.parents or not resolved.is_file():
            raise YuanError("独立 Python 校验失败 / Managed Python validation failed")
        self.command([str(resolved), "-c", "import sys;assert sys.version_info >= (3,10);assert sys.implementation.name=='cpython'"])
        return str(resolved)

    def detect_hardware(self):
        hardware = {"system": platform.system(), "machine": platform.machine(), "cuda": None,
                    "visibility": os.environ.get("CUDA_VISIBLE_DEVICES"), "driver": None, "adapters": []}
        timeout = self.policy.number("runtime", "hardware_probe_seconds", 10.0, 1.0, 60.0)
        def execute(arguments):
            result = subprocess.run(arguments, capture_output=True, timeout=timeout, env=self.env, creationflags=getattr(subprocess, "CREATE_NO_WINDOW", 0))
            check(self.cancel)
            return result.stdout.decode("utf-8-sig", "replace") if result.returncode == 0 else ""
        if hardware["system"] == "Windows":
            powershell = shutil.which("powershell.exe") or str(Path(os.environ.get("SystemRoot", "C:/Windows")) / "System32/WindowsPowerShell/v1.0/powershell.exe")
            try:
                text = execute([powershell, "-NoProfile", "-NonInteractive", "-Command", "[Console]::OutputEncoding=[Text.UTF8Encoding]::new();Get-CimInstance Win32_VideoController | Select-Object Name,PNPDeviceID,DriverVersion,ConfigManagerErrorCode | ConvertTo-Json -Compress"])
                rows = json.loads(text) if text else []
                rows = [rows] if isinstance(rows, dict) else rows
                for row in rows:
                    name, identifier = str(row.get("Name", "")), str(row.get("PNPDeviceID", "")).upper()
                    vendor = "nvidia" if "VEN_10DE" in identifier else "amd" if "VEN_1002" in identifier else "intel" if "VEN_8086" in identifier else None
                    if vendor:
                        hardware["adapters"].append({"name": name, "vendor": vendor, "driver": str(row.get("DriverVersion", "")), "status": row.get("ConfigManagerErrorCode")})
            except (OSError, ValueError, subprocess.TimeoutExpired, TypeError):
                pass
        elif hardware["system"] == "Linux":
            for directory in sorted(Path("/sys/class/drm").glob("card[0-9]*")):
                if not re.fullmatch(r"card[0-9]+", directory.name):
                    continue
                try:
                    vendor_id = (directory / "device/vendor").read_text().strip().lower()
                    vendor = {"0x10de": "nvidia", "0x1002": "amd", "0x8086": "intel"}.get(vendor_id)
                    if vendor:
                        hardware["adapters"].append({"name": directory.name, "vendor": vendor})
                except OSError:
                    pass
        elif hardware["system"] == "Darwin" and hardware["machine"].casefold() in ("arm64", "aarch64"):
            hardware["adapters"].append({"name": "Apple Silicon", "vendor": "apple"})
        executable = shutil.which("nvidia-smi")
        if executable is None and hardware["system"] == "Windows":
            candidates = [Path(os.environ.get("SystemRoot", "C:/Windows")) / "System32/nvidia-smi.exe", Path(os.environ.get("ProgramFiles", "C:/Program Files")) / "NVIDIA Corporation/NVSMI/nvidia-smi.exe"]
            executable = next((str(path) for path in candidates if path.is_file()), None)
        if executable:
            try:
                from xml.etree import ElementTree
                text = execute([executable, "-q", "-x"])
                if text:
                    tree = ElementTree.fromstring(text)
                    version = tree.findtext("cuda_version", "")
                    if tree.findall("gpu"):
                        hardware.update(driver=tree.findtext("driver_version"), devices=[item.findtext("product_name", "") for item in tree.findall("gpu")])
                        if re.fullmatch(r"\d+\.\d+", version):
                            hardware["cuda"] = version
                        if not any(item["vendor"] == "nvidia" for item in hardware["adapters"]):
                            hardware["adapters"] += [{"name": name, "vendor": "nvidia"} for name in hardware["devices"]]
                if not hardware["cuda"]:
                    match = re.search(r"CUDA Version:\s*([0-9]+\.[0-9]+)", execute([executable]))
                    if match:
                        hardware["cuda"] = match[1]
                capabilities = execute([executable, "--query-gpu=compute_cap", "--format=csv,noheader,nounits"])
                hardware["compute_capabilities"] = [value.strip() for value in capabilities.splitlines() if re.fullmatch(r"\s*[0-9]+\.[0-9]+\s*", value)]
            except (OSError, ValueError, subprocess.TimeoutExpired, ElementTree.ParseError):
                pass
        atomic_json(self.state / "hardware.json", hardware, self.cancel)
        self.emit("hardware", hardware=hardware)
        return hardware


    def backend_candidates(self):
        system = self.hardware["system"]
        devices = self.hardware.get("adapters", [])
        vendors = {str(item.get("vendor", "")).casefold() for item in devices}
        nvidia = bool(self.hardware.get("cuda") or "nvidia" in vendors)
        if system == "Darwin":
            return ["native"]
        if nvidia:
            version = self.hardware.get("cuda")
            maximum = tuple(map(int, version.split("."))) if version else None
            capabilities = [float(value) for value in self.hardware.get("compute_capabilities", []) if re.fullmatch(r"[0-9]+\.[0-9]+", str(value))]
            channels = []
            for capability in sorted(set(capabilities), reverse=True) or [None]:
                compatible = (["cu128", "cu130"] if capability is not None and capability >= 10 else
                              ["cu126"] if capability is not None and capability < 7.5 else ["cu126", "cu128", "cu130"])
                channels.extend(channel for channel in compatible if channel not in channels)
            if maximum is not None:
                channels = [channel for channel in channels if (int(channel[2:-1]), int(channel[-1])) <= maximum]
            if system == "Windows":
                channels.append("directml")
            if channels:
                return channels
            raise YuanFault("显卡驱动与计算组件正在重新匹配 / Rematching the graphics driver and compute components", category="compatibility", code="accelerator_driver_match", hardware=self.hardware)
        if system == "Windows" and devices:
            return (["xpu"] if "intel" in vendors else []) + ["directml"]
        if system == "Linux":
            if "amd" in vendors and Path("/dev/kfd").exists():
                return ["rocm7.1"]
            if "intel" in vendors:
                return ["xpu"]
            if devices:
                raise YuanFault("正在匹配图形计算驱动 / Matching the graphics compute driver", category="compatibility", code="accelerator_driver_match", hardware=self.hardware)
        return ["cpu"]


    def required_packages(self):
        if self.compute_backend == "directml":
            return tuple("numpy>=1.26,<2" if item.startswith("numpy") else item for item in PACKAGES) + ("torch-directml==0.2.5.dev240914",)
        return PACKAGES

    def runtime_signature(self):
        return payload_digest(["yuan-runtime-v6", self.required_packages(), self.hardware, self.compute_backend, PYTHON_REQUIREMENT, "torch==2.10.0", "metadata-first-resume-v6"])

    def _platform_key(self, python):
        script = "import json,platform,sys,sysconfig;print(json.dumps([platform.system(),platform.machine(),sys.version_info[:2],sys.implementation.name,sysconfig.get_config_var('SOABI')],separators=(',',':')))"
        platform_value = self.command([str(python), "-c", script]).strip()
        value = json.dumps([json.loads(platform_value), self.compute_backend, self.hardware], sort_keys=True, separators=(",", ":"))
        return hashlib.sha256(value.encode()).hexdigest(), value

    def _packages(self, python):
        script = "import importlib.metadata as m,json,re;v=[{'name':re.sub(r'[-_.]+','-',str(d.metadata['Name'])).lower(),'version':d.version} for d in m.distributions() if d.metadata.get('Name')];print(json.dumps(sorted(v,key=lambda x:x['name']),separators=(',',':')))"
        return json.loads(self.command([str(python), "-c", script]).strip())

    def _validate_entry(self, entry, platform_value):
        if not isinstance(entry, dict) or entry.get("platform") != platform_value or not isinstance(entry.get("artifacts"), list) or not entry["artifacts"]:
            raise YuanError("运行组件锁定记录不完整 / Runtime artifact lock is incomplete")
        packages = []
        for item in entry["artifacts"]:
            if not isinstance(item, dict) or not re.fullmatch(r"[a-z0-9]+(?:[-.][a-z0-9]+)*", str(item.get("name", ""))) or not re.fullmatch(r"[a-zA-Z0-9.!+_-]+", str(item.get("version", ""))) or not is_digest(item.get("sha256")):
                raise YuanError("运行组件缺少精确版本或 SHA256 / Runtime artifact lacks an exact version or SHA256")
            size = item.get("size")
            if size is not None and (isinstance(size, bool) or not isinstance(size, int) or size <= 0):
                raise YuanError("运行组件大小无效 / Invalid runtime artifact size")
            parsed = urllib.parse.urlparse(item.get("url", ""))
            filename = item.get("filename", "")
            if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.password or not re.fullmatch(r"[a-zA-Z0-9_.+!-]+\.whl", filename):
                raise YuanError("运行组件来源或文件名无效 / Invalid runtime artifact source or filename")
            if urllib.parse.unquote(Path(parsed.path).name) != filename:
                raise YuanError("运行组件来源与文件名不一致 / Runtime artifact source and filename mismatch")
            packages.append({"name": item["name"], "version": item["version"]})
        packages.sort(key=lambda item: item["name"])
        names = [item["name"] for item in packages]
        required = {re.split(r"[<>=!~\[]", item)[0].lower() for item in ("torch", *self.required_packages())}
        if len(names) != len(set(names)) or not required.issubset(names) or packages != entry.get("packages"):
            raise YuanError("运行组件版本清单不完整或重复 / Runtime package manifest is incomplete or duplicated")
        return entry

    def _verify_hashes(self, previous, current):
        if set(previous) != set(current) or any(not hashes or not current[package] or hashes != current[package] for package, hashes in previous.items()):
            raise YuanError("运行组件哈希缺失或不匹配 / Runtime artifact hashes are missing or mismatched")

    def _entry_from_report(self, report, platform_value):
        if report.get("version") != "1" or not isinstance(report.get("install"), list):
            raise YuanError("运行组件解析报告版本不受支持 / Unsupported runtime resolution report version")
        artifacts = []
        for item in report["install"]:
            metadata = item.get("metadata", {})
            download = item.get("download_info", {})
            archive = download.get("archive_info", {})
            digest = archive.get("hashes", {}).get("sha256")
            url = download.get("url", "")
            if item.get("is_yanked"):
                raise YuanError("拒绝已撤回的运行组件 / Refusing a withdrawn runtime artifact")
            name = re.sub(r"[-_.]+", "-", str(metadata.get("name", ""))).lower()
            version = str(metadata.get("version", ""))
            if urllib.parse.urlsplit(url).scheme == "file":
                clean = urllib.parse.urlunsplit(urllib.parse.urlsplit(url)._replace(fragment=""))
                artifact = getattr(self, "local_artifacts", {}).get(clean)
                if not artifact or artifact["name"] != name or artifact["version"] != version or artifact["sha256"] != digest:
                    raise YuanFault("本地组件与已核验来源不一致 / Local component differs from its verified source", category="integrity", code="local_artifact_mismatch")
                artifacts.append(dict(artifact))
            else:
                artifacts.append({"name": name, "version": version, "url": url,
                                  "filename": urllib.parse.unquote(Path(urllib.parse.urlparse(url).path).name), "sha256": digest})
        artifacts.sort(key=lambda item: item["name"])
        entry = {"platform": platform_value, "packages": [{"name": item["name"], "version": item["version"]} for item in artifacts], "artifacts": artifacts}
        return self._validate_entry(entry, platform_value)


    def _installation_identity(self, python, entry):
        runtime = Path(python).parent.parent
        stamps = []
        for path in (Path(python), runtime / "pyvenv.cfg"):
            info = path.stat()
            stamps.append([str(path), info.st_size, info.st_mtime_ns, digest_file(path, self.cancel)])
        return payload_digest([payload_digest(entry), stamps])

    def _verify_installation(self, python, entry):
        self.supervisor.flush_history(force=True)
        self.supervisor = StageSupervisor(self.state, self.emit, identity=runtime_identity(self.state, entry))
        self.stage("runtime_inventory")
        self.command([str(python), "-B", str(Path(__file__).resolve()), "--verify-install", str(self.state)], report=True)

    def _probe(self, python, entry):
        self.supervisor.flush_history(force=True)
        self.supervisor = StageSupervisor(self.state, self.emit, identity=runtime_identity(self.state, entry))
        expected = {item["name"]: item["version"] for item in entry["packages"]}
        packages = self._packages(python)
        actual = {item["name"]: item["version"] for item in packages}
        if len(actual) != len(packages) or any(actual.get(name) != version for name, version in expected.items()) or set(actual) - set(expected) - {"pip", "setuptools", "wheel"}:
            raise YuanFault("运行环境版本与锁定记录不一致 / Runtime versions differ from the lock", category="integrity", code="installed_versions_mismatch", stage=self.phase)
        self.command([str(python), "-m", "pip", "check"], report=True)
        failure_path = Path(python).parent.parent / "probe-failure.json"
        identity = payload_digest([self._installation_identity(python, entry), build_digest()])
        previous = read_json(failure_path)
        fault = previous.get("fault", {}) if previous.get("identity") == identity else {}
        component = str(fault.get("stage", "")).removeprefix("stage_import_")
        if fault.get("category") == "timeout" and component in RUNTIME_MODULES:
            self.emit("notice", key="runtime_import_diagnostic", component=component, previous_fault=fault)
            try:
                self.command([str(python), "-B", str(Path(__file__).resolve()), "--probe-import", str(self.state), component], report=True)
            except YuanFault as exc:
                if failure_category(exc) == "timeout":
                    exc.details.update(component=component, retry_blocker="retry_import_unchanged", diagnostic_mode="isolated_import")
                atomic_json(failure_path, {"identity": identity, "fault": fault_event(exc), "at": time.time()}, self.cancel)
                raise
            self.emit("notice", key="runtime_import_diagnostic_passed", component=component)
        try:
            self.command([str(python), "-B", str(Path(__file__).resolve()), "--probe", str(self.state)], report=True)
        except YuanFault as exc:
            atomic_json(failure_path, {"identity": identity, "fault": fault_event(exc), "at": time.time()}, self.cancel)
            raise
        failure_path.unlink(missing_ok=True)
        self.verified_entry = entry

    def _reuse(self, pointer, signature, lock):
        if not pointer or pointer.get("base_signature") != signature:
            return None
        runtime = safe_path(self.state, pointer["directory"])
        stamps = []
        for path in (runtime / "ready.json", runtime / "lock.json", runtime / "pyvenv.cfg", runtime_python(runtime)):
            try:
                info = path.stat()
                stamps.append((str(path), info.st_size, info.st_mtime_ns))
            except OSError:
                stamps.append((str(path), None, None))
        key = payload_digest([pointer, signature, lock, stamps])
        if key in self.reuse_cache:
            value, failure = self.reuse_cache[key]
            if failure is not None:
                self.emit("notice", key="runtime_cached_failure", reason=concise_error(failure))
                raise failure
            return value
        try:
            value = self._reuse_once(pointer, signature, lock)
        except Cancelled:
            raise
        except Exception as exc:
            self.reuse_cache[key] = (None, exc)
            raise
        self.reuse_cache[key] = (value, None)
        return value

    def _reuse_once(self, pointer, signature, lock):
        if not pointer or pointer.get("base_signature") != signature:
            return None
        runtime = safe_path(self.state, pointer["directory"])
        python = runtime_python(runtime)
        if not python.is_file():
            return None
        marker = checked_json(runtime / "ready.json")
        entry = checked_json(runtime / "lock.json")
        platform_key, platform_value = self._platform_key(python)
        self._validate_entry(entry, platform_value)
        digest = payload_digest(entry)
        expected = lock.get("platforms", {}).get(platform_key)
        if marker.get("lock") != digest or pointer.get("lock") != digest or marker.get("base_signature") != signature or expected != entry:
            raise YuanError("运行环境标记与锁定记录不一致 / Runtime marker and artifact lock mismatch")
        self._verify_hashes({item["name"]: item["sha256"] for item in expected["artifacts"]}, {item["name"]: item["sha256"] for item in entry["artifacts"]})
        self._verify_installation(python, entry)
        self.stage("runtime_verify")
        self._probe(python, entry)
        return python

    def _download(self, artifact, position, total_files, network=None, ledger=None, storage=None, cancel=None):
        network = network if network is not None else self.network
        cancel = cancel if cancel is not None else self.cancel
        target = safe_path(self.state, "runtime-artifacts/" + artifact["sha256"] + "/" + artifact["filename"])
        context = {"phase_id": self.phase_id, "artifact_id": artifact["sha256"], "file": artifact["filename"]}
        progress = {**context, "key": "download", "file_index": position, "file_count": total_files,
                    "current": 0, "total": artifact.get("size"), "unit": "bytes", "speed": None,
                    "transfer_state": "download_connecting", "last_progress_at": time.time()}
        def publish(transferred=0, force=False):
            if ledger is not None:
                ledger.update(artifact["sha256"], progress, transferred=transferred, force=force)
            else:
                self.progress = dict(progress)
                self.emit("progress", **self.progress)
        publish(force=True)
        def complete(path, cached=False):
            check(cancel)
            info = path.stat()
            size = info.st_size
            with self.network.host_lock:
                if not hasattr(self, "artifact_checks"):
                    self.artifact_checks = {}
                self.artifact_checks[str(path)] = (artifact["sha256"], size, info.st_mtime_ns, info.st_ctime_ns)
            progress.update(current=size, total=size, cached=cached, verified=True, transfer_state="download_complete", last_progress_at=time.time())
            publish(force=True)
            self.emit("download_complete", key="download_complete", component="runtime_download", **context, cached=cached)
            self.policy.save()
            return path
        check(cancel)
        if target.is_file() and not target.is_symlink():
            info = target.stat()
            stamp = (artifact["sha256"], info.st_size, info.st_mtime_ns, info.st_ctime_ns)
            with self.network.host_lock:
                verified = getattr(self, "artifact_checks", {}).get(str(target)) == stamp
            if (artifact.get("size") is None or info.st_size == artifact["size"]) and (verified or digest_file(target, cancel) == artifact["sha256"]):
                return complete(target, True)
        for attempt in range(self.download_attempts):
            check(cancel)
            previous = [None, -math.inf]
            rate = TransferRate(self.heartbeat_seconds)
            progress.update(download_attempt=attempt + 1, download_attempts=self.download_attempts, speed=None, verified=False)
            def state_changed(key, **values):
                progress.update(transfer_state="download_" + key, **values)
                publish(force=True)
            def report(done, total):
                now = time.monotonic()
                delta = max(0, done - previous[0]) if previous[0] is not None else 0
                previous[0] = done
                progress.update(current=done, total=total, speed=rate.advance(delta))
                if delta:
                    progress["last_progress_at"] = time.time()
                publish(transferred=delta)
                if now - previous[1] >= self.heartbeat_seconds:
                    self.resources()
                    previous[1] = now
            try:
                disk = shutil.disk_usage(self.state)
                reserve = storage.reserve if storage is not None else self.policy.integer("runtime", "disk_reserve_bytes", 0, 0, disk.total)
                budget = max(0, disk.free - reserve)
                part = target.with_name(target.name + ".partial")
                if part.is_file() and not part.is_symlink():
                    budget += part.stat().st_size
                path = network.download(artifact["url"], target, expected_size=artifact.get("size"), expected_hash=artifact["sha256"],
                                        max_bytes=budget, progress=report, events=state_changed, storage=storage)
                return complete(path)
            except Cancelled:
                raise
            except (OSError, YuanError) as exc:
                if isinstance(exc, YuanFault):
                    exc.details.update(artifact_id=artifact["sha256"], file=artifact["filename"])
                if attempt + 1 >= self.download_attempts or failure_category(exc) != "network":
                    raise
                network.note_failure(artifact["url"])
                delay = network.connection_timeout(artifact["url"]) * math.sqrt(attempt + 1)
                progress.update(transfer_state="download_retrying", speed=None)
                publish(force=True)
                self.emit("notice", key="retry", component="runtime_download", **context, attempt=attempt + 1, reason=concise_error(exc), retry_seconds=delay)
                if cancel.wait(delay):
                    raise Cancelled()
        raise YuanError("运行组件下载失败 / Runtime download failed")

    def _download_all(self, artifacts):
        if not artifacts:
            return []
        stop = threading.Event()
        cancel = AnyCancel(self.cancel, stop)
        connections = self.policy.integer("network", "pending_connections", 2, 1, 16)
        workers = self.policy.integer("runtime", "download_workers", min(connections, max(1, math.isqrt(os.cpu_count() or 1))), 1, min(connections, len(artifacts)))
        disk = shutil.disk_usage(self.state)
        storage = DownloadStorage(self.state, self.policy.integer("runtime", "disk_reserve_bytes", 0, 0, disk.total))
        ledger = DownloadLedger(artifacts, self.phase_id, self.emit, self.heartbeat_seconds)
        self.policy.save()
        output = [None] * len(artifacts)
        def fetch(index, artifact):
            check(cancel)
            network = Network(cancel, self.policy, self.network_config)
            return self._download(artifact, index + 1, len(artifacts), network=network, ledger=ledger, storage=storage, cancel=cancel)
        transfer = self.cancel.transfer() if isinstance(self.cancel, StartupControl) else nullcontext()
        with transfer:
            with ThreadPoolExecutor(max_workers=workers, thread_name_prefix="YuanDownload") as executor:
                futures = {}
                try:
                    for index, artifact in enumerate(artifacts):
                        check(cancel)
                        futures[executor.submit(fetch, index, artifact)] = index
                    for future in as_completed(futures):
                        check(cancel)
                        output[futures[future]] = future.result()
                except BaseException:
                    stop.set()
                    for future in futures:
                        future.cancel()
                    raise
        check(self.cancel)
        return output

    def torch_requirement(self, python, runtime):
        backend = self.compute_backend or ("cpu" if platform.system() in ("Linux", "Windows") else "native")
        if backend == "native":
            return "torch==2.10.0"
        channel = "cpu" if backend == "directml" else backend
        version = "2.4.1" if backend == "directml" else "2.10.0"
        if channel not in ("cpu", "xpu") and not re.fullmatch(r"(?:cu\d{2,4}|rocm\d+\.\d+(?:\.\d+)?)", channel):
            raise YuanFault("计算后端标识无效 / Invalid compute backend identifier", category="compatibility", code="backend_identifier")
        index = "https://download.pytorch.org/whl/" + channel + "/torch/"
        tags = WheelCatalog.tags(python, self.command)
        path = self.state / ("torch-catalog-" + payload_digest([channel, version, list(tags)]) + ".json")
        saved = read_json(path)
        artifact = saved.get("artifact")
        if not isinstance(artifact, dict) or not is_digest(artifact.get("sha256")):
            artifact = WheelCatalog.select(WheelCatalog.read(self.network, index, self.cancel), index, tags, "torch", version)
            try:
                with self.network.request(artifact["url"], method="HEAD") as response:
                    size = response.headers.get("Content-Length", "")
                    if re.fullmatch(r"[0-9]+", size) and int(size) > 0:
                        artifact["size"] = int(size)
            except Cancelled:
                raise
            except (OSError, ValueError, YuanError):
                pass
            atomic_json(path, {"artifact": artifact}, self.cancel)
        parsed = urllib.parse.urlsplit(artifact.get("url", ""))
        if parsed.hostname not in ("download.pytorch.org", "download-r2.pytorch.org") or not parsed.path.startswith("/whl/" + channel + "/") or artifact.get("name") != "torch" or str(artifact.get("version", "")).split("+", 1)[0] != version:
            path.unlink(missing_ok=True)
            raise YuanFault("组件缓存与所选后端不一致 / Component cache differs from the selected backend", category="integrity", code="wheel_catalog_identity")
        self.stage("download")
        local = self._download_all([artifact])[0]
        self.local_artifacts = getattr(self, "local_artifacts", {})
        self.local_artifacts[local.resolve().as_uri()] = artifact
        self.stage("runtime_resolve")
        return "torch @ " + local.resolve().as_uri() + "#sha256=" + artifact["sha256"]


    def _ensure_candidate(self, request):
        failures = []
        for backend in self.backend_candidates():
            check(self.cancel)
            self.compute_backend = backend
            self.env["YUAN_COMPUTE_BACKEND"] = backend
            self.emit("runtime_profile", compute_backend=backend, hardware=self.hardware)
            try:
                return self._ensure_backend(request)
            except Cancelled:
                raise
            except Exception as exc:
                if failure_category(exc) != "compatibility":
                    raise
                failures.append({"backend": backend, "reason": concise_error(exc)})
                self.emit("notice", key="backend_next", backend=backend, reason=concise_error(exc))
        raise YuanFault("正在匹配显卡与运行组件 / Matching graphics hardware and runtime components", category="compatibility", code="compute_candidates_exhausted", stage=self.phase, candidates=failures)


    def _ensure_backend(self, request):
        version = sys.version_info[:2] if request == "host" else tuple(int(value) for value in re.findall(r"[0-9]+", request.split("-", 2)[1])[:2])
        if self.compute_backend == "directml" and version >= (3, 13):
            raise YuanFault("为 DirectML 自动匹配兼容解释器 / Automatically matching a compatible interpreter for DirectML", category="compatibility", code="directml_python_match", stage=self.phase)
        signature = self.runtime_signature()
        self.stage("runtime")
        lock = checked_json(self.lock_path) if self.lock_path.exists() else {"python_requirement": PYTHON_REQUIREMENT, "platforms": {}}
        if lock.get("python_requirement") != PYTHON_REQUIREMENT or not isinstance(lock.get("platforms"), dict):
            raise YuanError("运行环境锁定格式无效，未解除锁定 / Invalid runtime lock format; lock was not removed")
        current_path = self.state / "runtime-current.json"
        pointer = checked_json(current_path) if current_path.exists() else {}
        build_path = self.state / "runtime-build.json"
        build = checked_json(build_path) if build_path.exists() else {}
        if build.get("base_signature") == signature and build.get("interpreter") == request:
            runtime = safe_path(self.state, build["directory"])
        else:
            runtime = safe_path(self.state, "runtimes/" + uuid.uuid4().hex)
            runtime.parent.mkdir(parents=True, exist_ok=True)
            build = {"directory": runtime.relative_to(self.state).as_posix(), "base_signature": signature, "interpreter": request}
            atomic_json(build_path, build, self.cancel)
        python = runtime_python(runtime)
        if not python.is_file():
            self.create_environment(self.interpreter(request), runtime)
        else:
            try:
                self.command([str(python), "-c", "import sys;assert sys.version_info >= (3,10)"])
            except Cancelled:
                raise
            except Exception:
                runtime = safe_path(self.state, "runtimes/" + uuid.uuid4().hex)
                build = {"directory": runtime.relative_to(self.state).as_posix(), "base_signature": signature, "interpreter": request}
                atomic_json(build_path, build, self.cancel)
                self.create_environment(self.interpreter(request), runtime)
                python = runtime_python(runtime)
        help_text = self.pip_command(python, ["help", "install"])
        version_text = self.pip_command(python, ["--version"])
        match = re.match(r"pip ([0-9]+)(?:\.([0-9]+))?", version_text)
        pip_version = (int(match[1]), int(match[2] or 0)) if match else (0, 0)
        if pip_version < (26, 2) or "--dry-run" not in help_text or "--report" not in help_text:
            self.command([str(python), "-m", "pip", "install", "--only-binary=:all:", "--no-deps", "--upgrade", "pip>=26.2"], report=True, transfer=True)
            help_text = self.pip_command(python, ["help", "install"])
        progress_args = ["--progress-bar", "raw" if re.search(r"\braw\b", help_text) else "off"]
        platform_key, platform_value = self._platform_key(python)
        entry = lock["platforms"].get(platform_key)
        if entry is None:
            self.stage("runtime_resolve")
            torch_requirement = self.torch_requirement(python, runtime)
            report_path = runtime / "resolve.json"
            self.command([str(python), "-m", "pip", "install", "--only-binary=:all:", "--dry-run", "--ignore-installed", "--report", str(report_path), *progress_args,
                          "--timeout", str(self.network.timeout_ceiling), "--retries", str(self.download_attempts), torch_requirement, *self.required_packages()], report=True, transfer=True)
            entry = self._entry_from_report(checked_json(report_path), platform_value)
            lock["platforms"][platform_key] = entry
            atomic_json(self.lock_path, lock, self.cancel)
            report_path.unlink(missing_ok=True)
        else:
            self._validate_entry(entry, platform_value)
        if read_json(runtime / "lock.json") != entry:
            atomic_json(runtime / "lock.json", entry, self.cancel)
        requirements = runtime / "install-lock.txt"
        identity = self._installation_identity(python, entry)
        installed = build.get("installed") == {"identity": identity, "lock": payload_digest(entry)}
        if installed:
            try:
                self._verify_installation(python, entry)
            except Cancelled:
                raise
            except Exception as exc:
                if failure_category(exc) != "integrity":
                    raise
                installed = False
                self.emit("notice", key="runtime_install_repair", reason=concise_error(exc), fault=fault_event(exc))
            else:
                self.emit("notice", key="runtime_install_reused", executable=str(python))
        if not installed:
            build.pop("installed", None)
            build["stage"] = "preparing_install"
            atomic_json(build_path, build, self.cancel)
            self.stage("download")
            wheels = self._download_all(entry["artifacts"])
            content = "\n".join(item["name"] + " @ " + path.resolve().as_uri() + " --hash=sha256:" + item["sha256"] for item, path in zip(entry["artifacts"], wheels)) + "\n"
            with requirements.open("w", encoding="utf-8", newline="\n") as stream:
                stream.write(content)
                stream.flush()
                os.fsync(stream.fileno())
            self.stage("runtime_install")
            self.command([str(python), "-m", "pip", "install", "--no-index", "--no-deps", "--only-binary=:all:", "--no-compile", "--require-hashes", "--force-reinstall", "-r", str(requirements), *progress_args], report=True)
            build.update(stage="installed", installed={"identity": self._installation_identity(python, entry), "lock": payload_digest(entry)})
            atomic_json(build_path, build, self.cancel)
            self._verify_installation(python, entry)
        self.stage("runtime_verify")
        self._probe(python, entry)
        digest = payload_digest(entry)
        marker = {"base_signature": signature, "lock": digest, "platform": platform_key,
                  "compute_backend": self.compute_backend, "hardware": payload_digest(self.hardware), "verified_at": time.time()}
        atomic_json(runtime / "ready.json", marker, self.cancel)
        selected = {**marker, "directory": runtime.relative_to(self.state).as_posix()}
        if pointer:
            atomic_json(self.state / "runtime-previous.json", pointer, self.cancel)
        atomic_json(current_path, selected, self.cancel)
        build_path.unlink(missing_ok=True)
        requirements.unlink(missing_ok=True)
        self.emit("progress", key="runtime_verify", phase_id=self.phase_id, current=1, total=1, unit="checks", last_progress_at=time.time())
        self._cleanup_runtimes(selected)
        return python

    def _cleanup_runtimes(self, selected):
        protected = {selected["directory"]}
        for name in ("runtime-previous.json", "runtime-build.json"):
            value = read_json(self.state / name)
            if value.get("directory"):
                protected.add(value["directory"])
        root = safe_path(self.state, "runtimes")
        for path in root.iterdir():
            if path.is_dir() and not path.is_symlink() and path.relative_to(self.state).as_posix() not in protected and re.fullmatch(r"[0-9a-f]{32}", path.name):
                shutil.rmtree(path, ignore_errors=True)


    def bootstrap_pip(self, python):
        version = json.loads(self.command([str(python), "-c", "import json,sys;print(json.dumps(list(sys.version_info[:3])))"]))
        directory = safe_path(self.state, "tools/pip-bootstrap")
        directory.mkdir(parents=True, exist_ok=True)
        marker = read_json(directory / "release.json")
        if marker.get("file") and is_digest(marker.get("sha256")) and compatible_python(marker.get("requires_python"), version):
            candidate = safe_path(directory, marker["file"])
            if candidate.suffix == ".whl" and candidate.is_file() and digest_file(candidate, self.cancel) == marker["sha256"]:
                return candidate
        self.emit("notice", key="pip_bootstrap")
        catalog = self.network.json("https://pypi.org/pypi/pip/json")
        candidates = []
        for number, entries in catalog.get("releases", {}).items():
            if not re.fullmatch(r"[0-9]+(?:\.[0-9]+){1,2}", number):
                continue
            for entry in entries:
                name = entry.get("filename", "")
                url = urllib.parse.urlparse(entry.get("url", ""))
                checksum = entry.get("digests", {}).get("sha256")
                size = entry.get("size")
                if (entry.get("yanked") or not re.fullmatch(r"pip-[0-9.]+-py3-none-any\.whl", name)
                        or not compatible_python(entry.get("requires_python"), version) or not is_digest(checksum)
                        or isinstance(size, bool) or not isinstance(size, int) or size <= 0
                        or url.scheme != "https" or url.hostname != "files.pythonhosted.org" or url.username or url.password
                        or urllib.parse.unquote(Path(url.path).name) != name):
                    continue
                candidates.append((tuple(int(value) for value in number.split(".")), entry))
        if not candidates:
            raise YuanFault("没有兼容且可校验的安装工具 / No compatible verifiable installer is available",
                            category="compatibility", code="pip_bootstrap_unavailable", stage=self.phase)
        _, entry = max(candidates, key=lambda item: item[0])
        target = safe_path(directory, entry["filename"])
        available = StorageBudget(self.state).snapshot()["available_bytes"]
        maximum = self.policy.integer("runtime", "installer_download_bytes", 32 * 1024 ** 2, 1, max(1, available))
        with StorageBudget(self.state).reserve(entry["size"]):
            self.network.download(entry["url"], target, expected_size=entry["size"], expected_hash=entry["digests"]["sha256"], max_bytes=maximum)
        with zipfile.ZipFile(target) as archive:
            if "pip/__main__.py" not in archive.namelist() or archive.testzip() is not None:
                raise YuanError("安装工具归档无效 / Invalid installer archive")
        atomic_json(directory / "release.json", {"file": target.name, "sha256": entry["digests"]["sha256"],
                    "requires_python": entry.get("requires_python", ""), "version": entry["version"] if "version" in entry else target.name.split("-")[1]}, self.cancel)
        return target

    def pip_command(self, python, arguments, report=False):
        try:
            self.command([str(python), "-c", "import pip"])
        except Cancelled:
            raise
        except YuanFault as exc:
            if exc.code != "package_command_failed":
                raise
            archive = self.bootstrap_pip(python)
            script = "import runpy,sys;sys.path.insert(0,sys.argv.pop(1));sys.argv[0]='pip';runpy.run_module('pip',run_name='__main__')"
            return self.command([str(python), "-c", script, str(archive), *arguments], report=report)
        return self.command([str(python), "-m", "pip", *arguments], report=report)

    def create_environment(self, python, runtime):
        try:
            self.command([str(python), "-m", "venv", "--without-pip", str(runtime)], report=True)
        except Cancelled:
            raise
        except YuanFault as exc:
            if exc.code != "package_command_failed" or exc.category in ("storage", "network", "integrity"):
                raise
            executable = self._uv()
            self.command([str(executable), "--no-config", "venv", "--python", str(python), str(runtime)], report=True)
        target = runtime_python(runtime)
        try:
            self.command([str(target), "-m", "ensurepip", "--upgrade"], report=True)
        except Cancelled:
            raise
        except YuanFault as exc:
            if exc.code != "package_command_failed" or exc.category in ("storage", "network", "integrity"):
                raise
            archive = self.bootstrap_pip(target)
            self.pip_command(target, ["install", "--no-index", "--no-deps", "--no-compile", str(archive)], report=True)

    def _uv(self):
        tools = self.state / "tools" / "uv"
        candidates = (tools / "bin" / "uv", tools / "Scripts" / "uv.exe", tools / "uv" / "uv", tools / "uv" / "uv.exe")
        executable = next((value for value in candidates if value.is_file() and not value.is_symlink()), None)
        if executable is None:
            tools.mkdir(parents=True, exist_ok=True)
            self.pip_command(host_python(), ["install", "--only-binary=:all:", "--no-deps", "--target", str(tools), "uv"], report=True)
            executable = next((value for value in candidates if value.is_file() and not value.is_symlink()), None)
        if executable is None:
            raise YuanError("无法自动取得兼容 Python 管理工具 / Compatible Python manager could not be provisioned")
        return executable

    def interpreter_candidates(self):
        vendors = {item.get("vendor") for item in self.hardware.get("adapters", [])}
        legacy = self.hardware.get("system") == "Windows" and bool(vendors) and "nvidia" not in vendors
        requirement = ">=3.10,<3.13" if legacy else PYTHON_REQUIREMENT
        if compatible_python(requirement, sys.version_info) and sys.implementation.name == "cpython":
            yield "host"
        executable = self._uv()
        raw = self.command([str(executable), "--no-config", "python", "list", "--managed-python", "--output-format", "json", requirement])
        rows = json.loads(raw)
        if not isinstance(rows, list):
            raise YuanError("Python 候选清单格式无效 / Invalid Python candidate catalog")
        versions = {}
        for row in rows:
            if not isinstance(row, dict) or row.get("implementation") != "cpython" or row.get("variant", "default") != "default":
                continue
            version = str(row.get("version", ""))
            if not re.fullmatch(r"[0-9]+\.[0-9]+\.[0-9]+", version):
                continue
            values = tuple(int(value) for value in version.split("."))
            if not compatible_python(requirement, values):
                continue
            key = row.get("key")
            if not isinstance(key, str) or not re.fullmatch(r"cpython-[a-zA-Z0-9_.+-]+", key):
                continue
            if not row.get("path") and urllib.parse.urlparse(str(row.get("url", ""))).scheme != "https":
                continue
            previous = versions.get(values[:2])
            if previous is None or values > previous[0]:
                versions[values[:2]] = (values, key)
        limit = self.policy.integer("runtime", "python_candidate_limit", max(1, len(versions)), 1, max(1, len(versions)))
        for _, key in sorted(versions.values(), reverse=True)[:limit]:
            yield key

    def failure_kind(self, exc):
        return failure_category(exc)

    def _cached_runtime(self):
        if self.cached_checked:
            return self.cached_value
        self.cached_checked = True
        current = read_json(self.state / "runtime-current.json")
        if not current or current.get("hardware") != payload_digest(self.hardware):
            return None
        backend = current.get("compute_backend")
        interval = self.policy.number("runtime", "backend_recheck_seconds", 86400.0, 1.0, 30 * 86400.0)
        verified = current.get("verified_at", 0)
        if backend == "cpu" and self.hardware.get("cuda") and (not isinstance(verified, (int, float)) or not math.isfinite(verified) or verified + interval <= time.time()):
            return None
        if backend not in ("native", "cpu", "xpu", "directml") and (not isinstance(backend, str) or not re.fullmatch(r"(?:cu\d{2,4}|rocm\d+\.\d+(?:\.\d+)?)", backend)):
            return None
        self.compute_backend = backend
        self.env["YUAN_COMPUTE_BACKEND"] = backend
        signature = self.runtime_signature()
        lock = checked_json(self.lock_path)
        try:
            self.cached_value = self._reuse(current, signature, lock)
            return self.cached_value
        except Cancelled:
            raise
        except Exception as exc:
            if failure_category(exc) not in ("integrity", "compatibility"):
                raise
            self.emit("notice", key="runtime", component="runtime_repair", reason=concise_error(exc), fault=fault_event(exc, self.phase))
            return None

    def ensure(self):
        self.stage("runtime")
        cached = self._cached_runtime()
        if cached is not None:
            return cached
        history_path = safe_path(self.state, "runtime-compatibility.json")
        history = read_json(history_path)
        records = history.get("candidates", {})
        if not isinstance(records, dict):
            records = {}
        interval = self.policy.number("runtime", "compatibility_recheck_seconds", 86400.0, 1.0, 30 * 86400.0)
        attempted = []
        for request in self.interpreter_candidates():
            check(self.cancel)
            key = payload_digest([request, sys.executable if request == "host" else None, sys.version if request == "host" else None,
                                  PACKAGES, "torch==2.10.0", self.hardware, "yuan-runtime-pinned-v6", self.network_config.index_urls])
            record = records.get(key, {})
            if record.get("failed_at", 0) + interval > time.time():
                attempted.append({"interpreter": request, "cached_failure": True, "reason": record.get("reason")})
                self.emit("notice", key="runtime_candidate_skipped", interpreter=request, reason=record.get("reason"), recheck_at=record["failed_at"] + interval)
                continue
            try:
                python = self._ensure_candidate(request)
                records.pop(key, None)
                atomic_json(history_path, {"candidates": records}, self.cancel)
                self.emit("runtime_profile", selected_interpreter=request, executable=str(python), verified=True)
                return python
            except Cancelled:
                raise
            except Exception as exc:
                kind = self.failure_kind(exc)
                reason = concise_error(exc)
                self.emit("runtime_failure", interpreter=request, classification=kind, stage=self.phase, reason=reason, fault=fault_event(exc, self.phase))
                if kind != "compatibility":
                    raise
                record = {"interpreter": request, "failed_at": time.time(), "reason": reason, "stage": self.phase}
                records[key] = record
                attempted.append(record)
                atomic_json(history_path, {"candidates": records}, self.cancel)
                self.emit("notice", key="runtime_fallback", interpreter=request, reason=reason)
        raise YuanFault("没有通过完整验证的 Python 候选 / No Python candidate passed complete verification", category="compatibility", code="python_candidates_exhausted", stage=self.phase, candidates=attempted)

class HTTPSOnly(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, fp, code, message, headers, newurl):
        if urllib.parse.urlparse(newurl).scheme != "https":
            raise YuanFault("拒绝非加密重定向 / Refused an insecure redirect", category="configuration", code="insecure_redirect")
        return super().redirect_request(request, fp, code, message, headers, newurl)

class Network:
    connection_registry = {}
    connection_registry_lock = threading.Lock()

    def __init__(self, cancel=None, policy=None, config=None):
        self.cancel = cancel
        self.config = config or (NetworkConfig(policy.state) if policy is not None else None)
        self.latency = 1.0
        self.policy = policy
        if policy is not None:
            self.timeout_floor = policy.number("network", "timeout_floor", 2.0, max(tick(), 0.1), max(2.0, math.sqrt(os.cpu_count() or 1) * 4))
            self.timeout_ceiling = policy.number("network", "timeout_ceiling", 30.0, self.timeout_floor, max(30.0, self.timeout_floor * max(4, os.cpu_count() or 1)))
        else:
            self.timeout_floor, self.timeout_ceiling = 2.0, 30.0
        self.cold_timeout = policy.number("network", "connect_cold_seconds", self.timeout_ceiling, self.timeout_floor, self.timeout_ceiling) if policy else self.timeout_ceiling
        self.connect_margin = policy.number("network", "connect_history_margin", 4.0, 1.0, 32.0) if policy else 4.0
        self.read_idle_seconds = policy.number("network", "read_idle_seconds", self.timeout_ceiling, self.timeout_floor, 86400.0) if policy else self.timeout_ceiling
        self.transfer_seconds = policy.number("network", "download_total_seconds", self.timeout_ceiling * 64, self.read_idle_seconds, 86400.0) if policy else self.timeout_ceiling * 64
        self.transfer_max_seconds = policy.number("network", "download_max_seconds", self.transfer_seconds * 4, self.transfer_seconds, 86400.0) if policy else self.transfer_seconds * 4
        self.transfer_margin = policy.number("network", "download_history_margin", 2.0, 1.0, 8.0) if policy else 2.0
        self.latency = self.cold_timeout / self.connect_margin
        self.host_budgets = {}
        self.host_lock = threading.Lock()
        if policy:
            policy.save()
        group = str(policy.state.resolve()) if policy is not None else "process"
        limit = policy.integer("network", "pending_connections", 2, 1, 16) if policy is not None else 2
        with self.connection_registry_lock:
            self.connection_gate = self.connection_registry.setdefault(group, threading.BoundedSemaphore(limit))

    @property
    def timeout(self):
        return max(self.timeout_floor, min(self.timeout_ceiling, self.latency * self.connect_margin))

    def origin_key(self, url):
        parts = urllib.parse.urlsplit(url)
        config = [self.config.proxy, self.config.ca_file, self.config.client_cert] if self.config else None
        return payload_digest([parts.scheme, parts.hostname, parts.port, config])

    def connection_timeout(self, url):
        key = self.origin_key(url)
        with self.host_lock:
            value = self.host_budgets.get(key)
        if value is None:
            measured = self.policy.measured("network_connect", key, -1.0) if self.policy else -1.0
            value = self.cold_timeout if measured < 0 else measured * self.connect_margin
        return max(self.timeout_floor, min(self.timeout_ceiling, value))

    def note_failure(self, url):
        budget = self.connection_timeout(url)
        with self.host_lock:
            self.host_budgets[self.origin_key(url)] = min(self.timeout_ceiling, max(self.cold_timeout, budget * math.sqrt(2)))

    def request(self, url, headers=None, method=None, deadline=None):
        if urllib.parse.urlparse(url).scheme != "https":
            raise YuanError("仅允许加密网络连接 / Only HTTPS connections are permitted")
        check(self.cancel)
        parts = urllib.parse.urlsplit(url)
        request_url = urllib.parse.urlunsplit((parts.scheme, parts.netloc.rsplit("@", 1)[-1], parts.path, parts.query, parts.fragment))
        request = urllib.request.Request(request_url, headers={"User-Agent": "Yuan-Audio/1.0 (local audio learning)", **(headers or {})}, method=method)
        before = time.monotonic()
        done = threading.Event()
        abandoned = threading.Event()
        result_box = []
        connect_budget = self.connection_timeout(url)
        deadline = min(deadline, before + connect_budget) if deadline is not None else before + connect_budget
        while not self.connection_gate.acquire(timeout=min(math.sqrt(tick()), max(tick(), deadline - time.monotonic()))):
            check(self.cancel)
            if time.monotonic() >= deadline:
                raise YuanFault("先前网络连接仍未退出 / Earlier network connections have not returned", category="network", code="network_connections_pending", url=url)
        def connect():
            result = None
            try:
                opener = self.config.opener() if self.config else urllib.request.build_opener(HTTPSOnly())
                result = opener.open(request, timeout=max(connect_budget, self.read_idle_seconds))
                if abandoned.is_set():
                    result.close()
                else:
                    result_box.append(result)
            except BaseException as exc:
                result_box.append(exc)
            finally:
                self.connection_gate.release()
                done.set()
                if abandoned.is_set() and result is not None:
                    result.close()
        try:
            check(self.cancel)
            if time.monotonic() >= deadline:
                raise YuanFault("网络连接期限已到 / Network connection deadline reached", category="network", code="network_connect_deadline", url=url, connect_seconds=connect_budget)
            threading.Thread(target=connect, daemon=True, name="YuanNetworkConnect").start()
        except BaseException:
            self.connection_gate.release()
            raise
        try:
            while not done.wait(math.sqrt(tick())):
                check(self.cancel)
                if time.monotonic() >= deadline:
                    raise YuanFault("网络连接期限已到 / Network connection deadline reached", category="network", code="network_connect_deadline", url=url, connect_seconds=connect_budget)
            check(self.cancel)
            if time.monotonic() >= deadline:
                raise YuanFault("网络连接期限已到 / Network connection deadline reached", category="network", code="network_connect_deadline", url=url, connect_seconds=connect_budget)
        except BaseException:
            abandoned.set()
            if result_box and not isinstance(result_box[0], BaseException):
                result_box[0].close()
            raise
        result = result_box[0]
        if isinstance(result, BaseException):
            if isinstance(result, urllib.error.HTTPError):
                raise result
            raise YuanFault("网络连接未完成 / Network connection failed", category=failure_category(result) if failure_category(result) != "unknown" else "network", code="network_connect_failed", url=url) from result
        elapsed = time.monotonic() - before
        self.latency = (self.latency + elapsed) / 2
        key = self.origin_key(url)
        with self.host_lock:
            self.host_budgets[key] = max(self.timeout_floor, min(self.timeout_ceiling, elapsed * self.connect_margin))
        if self.policy:
            self.policy.observe("network_connect", key, elapsed)
        if urllib.parse.urlparse(result.geturl()).scheme != "https":
            result.close()
            raise YuanFault("拒绝非加密重定向 / Refused an insecure redirect", category="configuration", code="insecure_redirect")
        return result

    def blocks(self, response, deadline=None):
        stopped = threading.Event()
        chunks = queue.Queue(maxsize=2)
        def send(value):
            while not stopped.is_set():
                try:
                    chunks.put(value, timeout=math.sqrt(tick()))
                    return
                except queue.Full:
                    pass
        def read():
            try:
                reader = getattr(response, "read1", response.read)
                while not stopped.is_set():
                    block = reader(1024 * 1024)
                    if not block:
                        break
                    send(block)
                send(None)
            except BaseException as exc:
                send(exc)
        thread = threading.Thread(target=read, daemon=True)
        thread.start()
        last_block = time.monotonic()
        try:
            while True:
                check(self.cancel)
                limit = deadline() if callable(deadline) else deadline
                if limit is not None and time.monotonic() >= limit:
                    raise YuanFault("单文件下载执行期限已到 / File transfer deadline reached", category="network", code="network_file_deadline", url=response.geturl() if hasattr(response, "geturl") else None)
                try:
                    block = chunks.get(timeout=math.sqrt(tick()))
                except queue.Empty:
                    if time.monotonic() - last_block >= self.read_idle_seconds:
                        raise YuanFault("网络读取期限已到 / Network read deadline reached", category="network", code="network_read_deadline", url=response.geturl() if hasattr(response, "geturl") else None)
                    continue
                last_block = time.monotonic()
                check(self.cancel)
                limit = deadline() if callable(deadline) else deadline
                if limit is not None and last_block >= limit:
                    raise YuanFault("网络读取总期限已到 / Network total read deadline reached", category="network", code="network_file_deadline")
                if block is None:
                    break
                if isinstance(block, BaseException):
                    if isinstance(block, Cancelled):
                        raise block
                    category = failure_category(block)
                    raise YuanFault("网络读取未完成 / Network read failed", category=category if category != "unknown" else "network", code="network_read_failed",
                                    url=response.geturl() if hasattr(response, "geturl") else None) from block
                yield block
        finally:
            stopped.set()
            if thread.is_alive():
                try:
                    import socket
                    raw = getattr(getattr(response, "fp", None), "raw", None)
                    connection = getattr(raw, "_sock", None)
                    if connection:
                        connection.shutdown(socket.SHUT_RDWR)
                except OSError:
                    pass

    @contextmanager
    def transfer(self):
        pending, seen = [self.cancel], set()
        with ExitStack() as stack:
            while pending:
                cancel = pending.pop()
                if cancel is None or id(cancel) in seen:
                    continue
                seen.add(id(cancel))
                if isinstance(cancel, StartupControl):
                    stack.enter_context(cancel.transfer())
                elif isinstance(cancel, AnyCancel):
                    pending.extend(reversed(cancel.events))
            check(self.cancel)
            yield

    def json(self, url, with_headers=False):
        with self.transfer():
            return self._json(url, with_headers=with_headers)

    def _json(self, url, with_headers=False):
        key = self.origin_key(url)
        initial = min(self.transfer_seconds, self.connection_timeout(url) + self.read_idle_seconds)
        observed = self.policy.measured("network_manifest", key, initial / self.transfer_margin) if self.policy else initial / self.transfer_margin
        maximum = min(self.transfer_seconds, self.timeout_ceiling + self.read_idle_seconds)
        budget = max(tick(), min(maximum, max(self.timeout_floor, observed * self.transfer_margin)))
        if self.policy:
            budget = self.policy.number("network", "manifest_total_seconds", budget, tick(), maximum)
        began = time.monotonic()
        deadline = began + budget
        payload = bytearray()
        with self.request(url, deadline=deadline) as response:
            headers = dict(response.headers.items()) if with_headers else {}
            for block in self.blocks(response, deadline=deadline):
                if len(payload) + len(block) > 16 * 1024 * 1024:
                    raise YuanError("网络清单超过安全容量 / Network manifest exceeds safe capacity")
                payload.extend(block)
        check(self.cancel)
        if time.monotonic() >= deadline:
            raise YuanFault("清单读取总期限已到 / Manifest total deadline reached", category="network", code="network_manifest_deadline", url=url)
        result = json.loads(payload, parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
        if time.monotonic() >= deadline:
            raise YuanFault("清单处理总期限已到 / Manifest processing deadline reached", category="network", code="network_manifest_deadline", url=url)
        if self.policy:
            self.policy.observe("network_manifest", key, elapsed_seconds(began))
        return (result, headers) if with_headers else result

    def download(self, url, target, expected_size=None, expected_hash=None, progress=None, max_bytes=None, algorithm=None, events=None, storage=None):
        with self.transfer():
            return self._download(url, target, expected_size, expected_hash, progress, max_bytes, algorithm, events, storage)

    def _download(self, url, target, expected_size=None, expected_hash=None, progress=None, max_bytes=None, algorithm=None, events=None, storage=None):
        budget = TransferBudget(self.transfer_seconds, self.transfer_max_seconds, self.read_idle_seconds, self.transfer_margin)
        deadline = budget.deadline
        target = Path(target)
        part = target.with_name(target.name + ".partial")
        check(self.cancel)
        if target.is_symlink() or part.is_symlink():
            raise InvalidDownload("拒绝使用链接指向的下载文件 / Refusing a linked download target")
        target.parent.mkdir(parents=True, exist_ok=True)
        algorithm = algorithm or "sha256"
        if algorithm not in ("sha1", "sha256"):
            raise InvalidDownload("不支持的完整性算法 / Unsupported integrity algorithm")
        if expected_size is not None and (isinstance(expected_size, bool) or not isinstance(expected_size, int) or expected_size < 0):
            raise InvalidDownload("无效的下载大小 / Invalid download size")
        if max_bytes is not None and (isinstance(max_bytes, bool) or not isinstance(max_bytes, int) or max_bytes < 0):
            raise YuanError("无效的下载资源预算 / Invalid download resource budget")
        if expected_hash:
            expected_hash = str(expected_hash).lower()
            if len(expected_hash) != hashlib.new(algorithm).digest_size * 2 or any(c not in "0123456789abcdef" for c in expected_hash):
                raise InvalidDownload("无效的完整性摘要 / Invalid integrity digest")
        if max_bytes is not None and expected_size is not None and expected_size > max_bytes:
            raise YuanError("下载超过当前资源预算 / Download exceeds the current resource budget")
        if target.is_file():
            size = target.stat().st_size
            size_ok = (expected_size is None or size == expected_size) and (max_bytes is None or size <= max_bytes)
            hash_ok = not expected_hash or digest_file(target, self.cancel, algorithm) == expected_hash
            if size_ok and hash_ok:
                if progress:
                    progress(size, size)
                return target
        offset = part.stat().st_size if part.is_file() else 0
        if offset and (not expected_hash or max_bytes is not None and offset > max_bytes):
            part.unlink(missing_ok=True)
            offset = 0
        if offset and expected_hash and digest_file(part, self.cancel, algorithm) == expected_hash and (expected_size is None or offset == expected_size):
            check(self.cancel)
            os.replace(part, target)
            sync_dir(target.parent)
            if progress:
                progress(offset, offset)
            return target
        if expected_size is not None and offset >= expected_size:
            if offset == expected_size and part.is_file() and expected_hash and digest_file(part, self.cancel, algorithm) == expected_hash:
                check(self.cancel)
                os.replace(part, target)
                sync_dir(target.parent)
                if progress:
                    progress(offset, offset)
                return target
            part.unlink(missing_ok=True)
            offset = 0
        headers = {"Accept-Encoding": "identity"}
        if offset:
            headers["Range"] = f"bytes={offset}-"
        if events:
            events("connecting", source=urllib.parse.urlsplit(url).hostname, connect_seconds=self.connection_timeout(url), read_idle_seconds=self.read_idle_seconds, transfer_seconds=self.transfer_seconds)
        try:
            response = self.request(url, headers, deadline=deadline)
        except urllib.error.HTTPError as exc:
            if exc.code != 416 or not offset:
                raise
            exc.close()
            part.unlink(missing_ok=True)
            offset = 0
            response = self.request(url, {"Accept-Encoding": "identity"}, deadline=deadline)
        with response:
            if events:
                events("receiving", source=urllib.parse.urlsplit(response.geturl()).hostname)
            status = getattr(response, "status", 200)
            if status not in (200, 206):
                raise YuanError(f"下载状态异常 / Unexpected download status: {status}")
            if response.headers.get("Content-Encoding", "identity").strip().lower() not in ("", "identity"):
                raise YuanError("下载编码与原始文件不匹配 / Download encoding differs from the original file")
            length = response.headers.get("Content-Length")
            if length is not None and not re.fullmatch(r"[0-9]+", length.strip()):
                raise YuanError("下载长度无效 / Invalid download content length")
            length = int(length) if length is not None else None
            response_end = None
            if status == 206:
                match = re.fullmatch(r"bytes ([0-9]+)-([0-9]+)/([0-9]+|\*)", response.headers.get("Content-Range", "").strip())
                if match is None:
                    raise YuanError("下载续传范围无效 / Invalid download content range")
                first, last = int(match[1]), int(match[2])
                complete = int(match[3]) if match[3] != "*" else None
                if first != offset or last < first or complete is not None and last >= complete:
                    raise YuanError("下载续传偏移不匹配 / Download resume offset mismatch")
                if length is not None and length != last - first + 1:
                    raise YuanError("下载范围与长度不匹配 / Download range and length mismatch")
                response_end = last + 1
                total = complete if complete is not None else expected_size
                if total is None:
                    raise YuanError("无法确认下载完整长度 / Cannot establish the complete download length")
            else:
                offset = 0
                total = length if length is not None else expected_size
            if expected_size is not None and total is not None and total != expected_size:
                raise InvalidDownload("下载大小与可信清单不匹配 / Download size differs from the trusted manifest")
            if max_bytes is not None and total is not None and total > max_bytes:
                raise YuanError("下载超过当前资源预算 / Download exceeds the current resource budget")
            written = offset
            budget.advance(written, total)
            if progress:
                progress(written, total)
            with part.open("ab" if offset else "wb") as stream:
                for block in self.blocks(response, deadline=lambda: budget.deadline):
                    check(self.cancel)
                    written += len(block)
                    limits = (expected_size, max_bytes, total, response_end)
                    if any(bound is not None and written > bound for bound in limits):
                        raise InvalidDownload("下载超过已声明大小 / Download exceeds its declared size")
                    if storage is not None:
                        storage.write(stream, block)
                    else:
                        if shutil.disk_usage(target.parent).free < len(block):
                            raise YuanError("所选目录空间不足 / The selected folder is out of space")
                        stream.write(block)
                    budget.advance(written, total)
                    if progress:
                        progress(written, total)
                stream.flush()
                os.fsync(stream.fileno())
        check(self.cancel)
        declared = expected_size if expected_size is not None else total
        if (declared is not None and written != declared) or (response_end is not None and written != response_end):
            raise YuanFault("下载提前结束，将保留已下载部分 / Download ended early; partial data retained",
                            category="network", code="network_incomplete", stage="download", url=url,
                            received_bytes=written, expected_bytes=declared, response_end=response_end)
        if events:
            events("verifying")
        if expected_hash and digest_file(part, self.cancel, algorithm) != expected_hash:
            part.unlink(missing_ok=True)
            raise InvalidDownload("文件完整性校验失败 / File integrity validation failed")
        check(self.cancel)
        os.replace(part, target)
        sync_dir(target.parent)
        return target



class StorageBudget:
    lock = threading.RLock()
    reservations = {}

    def __init__(self, state):
        self.state = Path(state).resolve()
        self.state.mkdir(parents=True, exist_ok=True)
        self.key = str(self.state)
        self.path = safe_path(self.state, "storage-budget.json")

    def configure(self, model, queue_bytes=0):
        page = sqlite3.connect(":memory:")
        try:
            page_bytes = int(page.execute("PRAGMA page_size").fetchone()[0])
        finally:
            page.close()
        parameters = getattr(model, "model_bytes", 0) or sum(value.numel() * value.element_size() for value in model.network.parameters())
        waveform = model.capacity() * model.np.dtype(model.np.float32).itemsize
        checkpoint = max(page_bytes, parameters * 4 + page_bytes)
        conversation = max(page_bytes, (max(queue_bytes, waveform * 2) + waveform * 2) * 2)
        atomic_json(self.path, {"model_identity": model.identity(), "checkpoint_bytes": checkpoint, "conversation_bytes": conversation})
        return self.snapshot()

    def snapshot(self, required=0, purpose="learning"):
        limits = read_json(self.path, {})
        checkpoint = max(0, int(limits.get("checkpoint_bytes", 0)))
        conversation = max(0, int(limits.get("conversation_bytes", 0)))
        free = shutil.disk_usage(self.state).free
        with self.lock:
            pending = self.reservations.get(self.key, 0)
        reserve = checkpoint if purpose == "conversation" else conversation if purpose == "checkpoint" else checkpoint + conversation
        return {"free_bytes": free, "reserved_bytes": reserve, "pending_bytes": pending,
                "checkpoint_bytes": checkpoint, "conversation_bytes": conversation,
                "available_bytes": max(0, free - reserve - pending),
                "ready": free >= reserve + pending + max(0, int(required)), "purpose": purpose}

    @contextmanager
    def reserve(self, required, purpose="learning"):
        required = max(0, int(required))
        with self.lock:
            result = self.snapshot(required, purpose)
            if not result["ready"]:
                raise OSError(errno.ENOSPC, "保留对话与检查点空间，已暂停新写入 / New write paused to preserve conversation and checkpoint space")
            self.reservations[self.key] = self.reservations.get(self.key, 0) + required
        try:
            yield result
        finally:
            with self.lock:
                remaining = max(0, self.reservations.get(self.key, 0) - required)
                if remaining:
                    self.reservations[self.key] = remaining
                else:
                    self.reservations.pop(self.key, None)

    def reclaim_recovery(self, cancel=None, required=0):
        root = safe_path(self.state, "learning/recovery")
        if not root.is_dir() or root.is_symlink():
            return 0
        entries, total = [], 0
        for path in root.iterdir():
            check(cancel)
            if path.is_symlink() or not path.is_dir() or not re.fullmatch(r"[0-9a-f]{32}", path.name):
                continue
            files = list(path.iterdir())
            if any(file.is_symlink() or not file.is_file() for file in files):
                continue
            size = sum(file.stat().st_size for file in files)
            total += size
            entries.append((path.stat().st_mtime_ns, path, size))
        policy = AdaptivePolicy(self.state)
        available = self.snapshot(required)["available_bytes"]
        budget = policy.integer("storage", "checkpoint_recovery_bytes", (available + total) // 4, 0, max(1, available + total))
        keep = policy.integer("storage", "checkpoint_recovery_generations", 1, 0, max(1, math.isqrt(os.cpu_count() or 1)))
        remaining, removed = len(entries), 0
        for _, path, size in sorted(entries):
            check(cancel)
            if remaining <= keep and total <= budget and self.snapshot(required)["ready"]:
                break
            shutil.rmtree(path)
            remaining -= 1
            total -= size
            removed += size
        if removed:
            sync_dir(root)
        return removed

    def reclaim(self, store, cancel, required=0):
        removed = 0
        before = self.snapshot(required)
        if before["ready"]:
            return before
        removed += self.reclaim_recovery(cancel, required)
        store.prune_memory_versions(cancel)
        eligible = ("g.retention='training_cache' AND g.split='train' AND s.generated=0 AND s.audio_status IN ('ready','evicted') "
                    "AND (s.visits>0 OR (s.learnable=0 AND COALESCE(json_extract(s.metadata,'$.transcript_verified'),0)=0 AND EXISTS(SELECT 1 FROM samples learned WHERE learned.audio=s.audio AND learned.generated=0 AND learned.visits>0)) "
                    "OR EXISTS(SELECT 1 FROM turn_pairs p WHERE (p.user_sample=s.id OR p.assistant_sample=s.id) AND p.visits>0)) "
                    "AND NOT EXISTS(SELECT 1 FROM turn_pairs p WHERE p.group_id=g.id AND p.verified=1) "
                    "AND NOT EXISTS(SELECT 1 FROM turn_pairs p WHERE (p.user_sample=s.id OR p.assistant_sample=s.id) AND p.eligible=1 AND p.visits=0 AND " + store.training_pair_filter + ")")
        with store.audio_files(cancel):
            rows = store.db.execute("SELECT s.audio FROM samples s JOIN groups g ON g.id=s.group_id WHERE " + eligible + " GROUP BY s.audio ORDER BY max(s.visits) DESC,min(s.created)").fetchall()
            for row in rows:
                check(cancel)
                if self.snapshot(required)["ready"]:
                    break
                path = safe_path(store.root, row["audio"])
                if path.is_symlink():
                    continue
                with store.transaction():
                    protected = store.db.execute("SELECT 1 FROM samples s JOIN groups g ON g.id=s.group_id WHERE s.audio=? AND s.audio_status<>'evicted' AND NOT (" + eligible + ") LIMIT 1", (row["audio"],)).fetchone()
                    if protected:
                        continue
                    try:
                        size = path.stat().st_size
                    except FileNotFoundError:
                        size = 0
                    store.db.execute("UPDATE samples SET audio_status='evicted',retry_at=0,read_failures=0,audio_error='' WHERE audio=? AND audio_status<>'evicted'", (row["audio"],))
                    path.unlink(missing_ok=True)
                removed += size
                store.integrity_cache.pop(row["audio"], None)
        if removed:
            sync_dir(store.audio)
            store.set_setting("storage_reclaimed_bytes", int(store.setting("storage_reclaimed_bytes", 0)) + removed)
        result = self.snapshot(required)
        result["reclaimed_bytes"] = removed
        return result

class AudioStore:
    file_lock = threading.RLock()
    training_pair_filter = "(p.verified=1 OR (p.source='published_dialogue_turns' AND json_extract(p.evidence,'$.method')='published_stereo_dialogue_v1' AND json_extract(p.evidence,'$.training_only')=1))"

    @staticmethod
    def trainable_pair(pair):
        if pair["verified"]:
            return True
        evidence = json.loads(pair["evidence"])
        return (pair["source"] == "published_dialogue_turns" and evidence.get("method") == "published_stereo_dialogue_v1"
                and evidence.get("training_only") is True)
    memory_selection = "FROM samples s JOIN groups g ON g.id=s.group_id JOIN sessions x ON x.id=s.group_id WHERE g.origin='local' AND s.group_id<>? AND x.ended IS NOT NULL AND s.audio_status='ready' AND s.memory_eligible=1 AND s.count>1"

    @staticmethod
    def memory_reason(metadata, eligible=True, generated=False):
        for key in ("capture_gap", "interrupted", "discontinuous", "input_incomplete", "final"):
            if metadata.get(key):
                return key
        return AudioStore.context_reason(metadata, eligible, generated)


    def __init__(self, state, recover=True):
        state = ensure_workspace_identity(state)
        self.root = safe_path(state, "memory")
        self.root.mkdir(parents=True, exist_ok=True)
        self.audio = safe_path(self.root, "audio")
        self.audio.mkdir(exist_ok=True)
        self.db = sqlite3.connect(str(database_path(self.root, "memory.sqlite3")), timeout=math.sqrt(os.cpu_count() or 1))
        self.db.row_factory = sqlite3.Row
        try:
            tables = {row[0] for row in self.db.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            expected = (1, build_digest())
            if tables:
                row = self.db.execute("SELECT schema_version,build_sha256 FROM workspace_identity WHERE singleton=1").fetchone() if "workspace_identity" in tables else None
                if row is None or tuple(row) != expected:
                    raise YuanFault("数据库版本身份不匹配，已拒绝读取旧数据 / Database build identity mismatch; old data will not be read", category="integrity", code="database_build_mismatch")
            self.db.execute("CREATE TABLE IF NOT EXISTS workspace_identity(singleton INTEGER PRIMARY KEY CHECK(singleton=1),schema_version INTEGER NOT NULL,build_sha256 TEXT NOT NULL)")
            self.db.execute("INSERT OR IGNORE INTO workspace_identity VALUES(1,?,?)", expected)
            self.db.commit()
        except BaseException:
            self.db.close()
            raise
        self.db.create_function("yuan_sample_supervision", 1, lambda value: payload_digest(self.sample_supervision(json.loads(value))), deterministic=True)
        self.db.create_function("yuan_pair_supervision", 1, lambda value: payload_digest(self.pair_supervision(json.loads(value))), deterministic=True)
        self.db.create_function("yuan_evidence", 1, lambda value: payload_digest(self.evidence_metadata(json.loads(value))), deterministic=True)
        self.transaction_depth = 0
        self.integrity_cache = {}
        self.coverage_cache = {}
        self.policy = AdaptivePolicy(state)
        self.db.execute("PRAGMA journal_mode=WAL")
        self.db.execute("PRAGMA foreign_keys=ON")
        self.db.execute("PRAGMA recursive_triggers=ON")
        self.db.executescript("""
        CREATE TABLE IF NOT EXISTS groups(id TEXT PRIMARY KEY, split TEXT NOT NULL CHECK(split IN ('train','validation','guard','release')), origin TEXT NOT NULL, created REAL NOT NULL, source_key TEXT NOT NULL, retention TEXT NOT NULL DEFAULT 'protected' CHECK(retention IN ('protected','training_cache')), provenance TEXT NOT NULL DEFAULT '{}');
        CREATE INDEX IF NOT EXISTS group_source ON groups(source_key,split);
        CREATE TABLE IF NOT EXISTS evaluation_group_revisions(group_id TEXT PRIMARY KEY REFERENCES groups(id) ON DELETE CASCADE,revision INTEGER NOT NULL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, prompt TEXT NOT NULL, language TEXT NOT NULL, started REAL NOT NULL, ended REAL);
        CREATE TABLE IF NOT EXISTS samples(id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id), role TEXT NOT NULL, task TEXT NOT NULL CHECK(task IN ('acoustic','generated_reply')), audio TEXT NOT NULL, seconds REAL NOT NULL, rate INTEGER NOT NULL, count INTEGER NOT NULL, cursor INTEGER NOT NULL DEFAULT 0, visits INTEGER NOT NULL DEFAULT 0, created REAL NOT NULL, digest TEXT NOT NULL, file_sha256 TEXT NOT NULL, audio_status TEXT NOT NULL DEFAULT 'ready' CHECK(audio_status IN ('ready','retry','invalid','evicted')), retry_at REAL NOT NULL DEFAULT 0, read_failures INTEGER NOT NULL DEFAULT 0, audio_error TEXT NOT NULL DEFAULT '', generated INTEGER NOT NULL CHECK(generated IN (0,1)), learnable INTEGER NOT NULL CHECK(learnable IN (0,1)), dialogue_eligible INTEGER NOT NULL CHECK(dialogue_eligible IN (0,1)), memory_eligible INTEGER NOT NULL DEFAULT 0 CHECK(memory_eligible IN (0,1)), memory_exclusion TEXT NOT NULL DEFAULT '', exclusion TEXT NOT NULL DEFAULT '', metadata TEXT NOT NULL DEFAULT '{}');
        CREATE INDEX IF NOT EXISTS sample_group ON samples(group_id, created);
        CREATE INDEX IF NOT EXISTS sample_digest ON samples(digest);
        DROP INDEX IF EXISTS eligible_digest;
        CREATE UNIQUE INDEX IF NOT EXISTS acoustic_digest ON samples(digest) WHERE learnable=1;
        CREATE TABLE IF NOT EXISTS audio_partitions(digest TEXT PRIMARY KEY, source_key TEXT NOT NULL, split TEXT NOT NULL CHECK(split IN ('train','validation','guard','release')));
        INSERT OR IGNORE INTO audio_partitions(digest,source_key,split) SELECT s.digest,g.source_key,g.split FROM samples s JOIN groups g ON g.id=s.group_id WHERE s.generated=0 AND (s.learnable=1 OR s.dialogue_eligible=1) ORDER BY s.created,s.id;
        CREATE INDEX IF NOT EXISTS sample_learning ON samples(task,learnable,visits,created);
        CREATE INDEX IF NOT EXISTS sample_memory ON samples(memory_eligible,audio_status,group_id,created);
        CREATE TABLE IF NOT EXISTS turn_pairs(id TEXT PRIMARY KEY, group_id TEXT NOT NULL REFERENCES groups(id), user_sample TEXT NOT NULL REFERENCES samples(id), assistant_sample TEXT NOT NULL REFERENCES samples(id), source TEXT NOT NULL, quality REAL NOT NULL, verified INTEGER NOT NULL CHECK(verified IN (0,1)), eligible INTEGER NOT NULL DEFAULT 1 CHECK(eligible IN (0,1)), eligibility_error TEXT NOT NULL DEFAULT '', evidence TEXT NOT NULL DEFAULT '{}', retry_at REAL NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, error TEXT NOT NULL DEFAULT '', cursor INTEGER NOT NULL DEFAULT 0, visits INTEGER NOT NULL DEFAULT 0, created REAL NOT NULL, UNIQUE(user_sample,assistant_sample));
        CREATE INDEX IF NOT EXISTS pair_learning ON turn_pairs(verified,visits,created);
        CREATE TABLE IF NOT EXISTS memories(sample_id TEXT NOT NULL REFERENCES samples(id) ON DELETE CASCADE, model_key TEXT NOT NULL, start INTEGER NOT NULL CHECK(start>=0), end INTEGER NOT NULL CHECK(end>start), vector BLOB NOT NULL, dims INTEGER NOT NULL, created REAL NOT NULL, PRIMARY KEY(sample_id,model_key,start,end));
        CREATE TABLE IF NOT EXISTS memory_progress(sample_id TEXT NOT NULL REFERENCES samples(id) ON DELETE CASCADE, model_key TEXT NOT NULL, next_start INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,retry_at REAL NOT NULL DEFAULT 0, PRIMARY KEY(sample_id,model_key));
        CREATE TABLE IF NOT EXISTS memory_calibrations(model_key TEXT PRIMARY KEY,attempt TEXT NOT NULL,certificate TEXT NOT NULL,updated REAL NOT NULL);
        CREATE INDEX IF NOT EXISTS memory_model ON memories(model_key,created);
        CREATE TABLE IF NOT EXISTS memory_buckets(model_key TEXT NOT NULL, band INTEGER NOT NULL, bucket INTEGER NOT NULL, sample_id TEXT NOT NULL, start INTEGER NOT NULL, end INTEGER NOT NULL, PRIMARY KEY(model_key,band,bucket,sample_id,start,end), FOREIGN KEY(sample_id,model_key,start,end) REFERENCES memories(sample_id,model_key,start,end) ON DELETE CASCADE);
        CREATE INDEX IF NOT EXISTS memory_bucket_sample ON memory_buckets(sample_id,model_key);
        CREATE TABLE IF NOT EXISTS memory_index_stats(model_key TEXT PRIMARY KEY, items INTEGER NOT NULL DEFAULT 0);
        CREATE TRIGGER IF NOT EXISTS memory_count_add AFTER INSERT ON memories BEGIN INSERT INTO memory_index_stats(model_key,items) VALUES(NEW.model_key,1) ON CONFLICT(model_key) DO UPDATE SET items=items+1; END;
        CREATE TRIGGER IF NOT EXISTS memory_count_remove AFTER DELETE ON memories BEGIN UPDATE memory_index_stats SET items=max(0,items-1) WHERE model_key=OLD.model_key; END;
        CREATE TRIGGER IF NOT EXISTS revoke_memory AFTER UPDATE OF memory_eligible,audio_status ON samples
        WHEN NEW.memory_eligible=0 OR NEW.audio_status<>'ready'
        BEGIN DELETE FROM memories WHERE sample_id=NEW.id; DELETE FROM memory_progress WHERE sample_id=NEW.id; END;
        CREATE TRIGGER IF NOT EXISTS changed_memory_audio AFTER UPDATE OF digest,file_sha256,rate,count ON samples
        WHEN OLD.digest IS NOT NEW.digest OR OLD.file_sha256 IS NOT NEW.file_sha256 OR OLD.rate IS NOT NEW.rate OR OLD.count IS NOT NEW.count
        BEGIN DELETE FROM memories WHERE sample_id=NEW.id; DELETE FROM memory_progress WHERE sample_id=NEW.id; END;
        CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY, url TEXT NOT NULL, path TEXT, metadata TEXT NOT NULL, offset INTEGER NOT NULL DEFAULT 0, finished INTEGER NOT NULL DEFAULT 0, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','ready','retry','quarantined','finished')), retry_at REAL NOT NULL DEFAULT 0, failures INTEGER NOT NULL DEFAULT 0, last_error TEXT NOT NULL DEFAULT '', created REAL NOT NULL);
        CREATE INDEX IF NOT EXISTS source_schedule ON sources(finished,status,retry_at,created);
        CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY, value TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS final_acceptance_runs(id TEXT PRIMARY KEY,identity_sha256 TEXT NOT NULL UNIQUE,receipt TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('reserved','evaluating','accepted','rejected','stale')),updated REAL NOT NULL);
        CREATE TABLE IF NOT EXISTS final_acceptance_sources(source TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES final_acceptance_runs(id));
        """)
        self._revision_triggers()
        if recover:
            self.db.execute("UPDATE sessions SET ended=? WHERE ended IS NULL", (time.time(),))
            self.commit()
            for path in self.audio.glob("*.partial"):
                path.unlink(missing_ok=True)
            self.repair()

    def repair(self):
        for row in self.db.execute("SELECT * FROM samples WHERE audio_status<>'evicted'").fetchall():
            try:
                safe_path(self.root, row["audio"]).stat()
            except (OSError, YuanError) as exc:
                self.audio_failure(row, exc)
        tracked = {row[0] for row in self.db.execute("SELECT audio FROM samples")}
        for path in self.audio.glob("*.flac"):
            if path.relative_to(self.root).as_posix() not in tracked and len(path.stem) == hashlib.sha256().digest_size * 2:
                path.unlink(missing_ok=True)

    def setting(self, key, default=None):
        row = self.db.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
        if not row:
            return default
        try:
            return json.loads(row[0])
        except (ValueError, TypeError):
            return default

    def set_setting(self, key, value):
        encoded = json.dumps(value, ensure_ascii=False, allow_nan=False)
        row = self.db.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
        if row and row[0] == encoded:
            return
        self.db.execute("INSERT OR REPLACE INTO settings VALUES(?,?)", (key, encoded))
        self.commit()

    def revise(self, group_id, kind="content"):
        if kind not in ("content", "evaluation", "metadata", "addition"):
            raise YuanError("数据修订类型无效 / Invalid data revision kind")
        row = self.db.execute("SELECT split FROM groups WHERE id=?", (group_id,)).fetchone()
        if row is None:
            raise YuanError("数据修订来源不存在 / Data revision source is missing")
        keys = ["metadata_revision"] if kind == "metadata" else ["data_revision", "revision_" + row["split"]]
        if kind != "metadata":
            keys.append("training_addition_revision" if row["split"] == "train" and kind == "addition" else
                        "training_revision" if row["split"] == "train" and kind == "content" else "evaluation_revision")
        with self.transaction():
            for key in keys:
                self.db.execute("INSERT INTO settings(key,value) VALUES(?, '1') ON CONFLICT(key) DO UPDATE SET value=CAST(COALESCE(CAST(settings.value AS INTEGER),0)+1 AS TEXT)", (key,))

    @staticmethod
    def sample_supervision(metadata):
        return {key: value for key, value in metadata.items() if key not in ("attribution", "annotation", "annotation_id")}

    @staticmethod
    def evidence_metadata(metadata):
        return {key: value for key, value in metadata.items() if key != "attribution"}

    @staticmethod
    def pair_supervision(evidence):
        return {key: value for key, value in evidence.items() if key not in
                ("reviewer", "annotation_id", "annotation_sha256", "attribution", "reference_checks", "retrieval")}

    def group(self, group_id, origin, forced=None, source_key=None, retention="protected", provenance=None):
        if retention not in ("protected", "training_cache"):
            raise YuanError("数据保留策略无效 / Invalid data retention policy")
        source_key = str(source_key or group_id)
        row = self.db.execute("SELECT split,source_key FROM groups WHERE id=?", (group_id,)).fetchone()
        if row:
            if source_key != group_id and row["source_key"] != source_key:
                if row["source_key"] != group_id or self.db.execute("SELECT 1 FROM samples WHERE group_id=?", (group_id,)).fetchone():
                    raise YuanError("同一来源组的原始录音标识发生变化 / Original recording identity changed within a group")
                related = self.db.execute("SELECT split FROM groups WHERE source_key=? LIMIT 1", (source_key,)).fetchone()
                split = related[0] if related else row["split"]
                if forced is not None and forced != split:
                    raise YuanError("同源录音不能分入不同数据集 / Recordings from one source cannot cross dataset splits")
                self.db.execute("UPDATE groups SET source_key=?,split=? WHERE id=?", (source_key, split, group_id))
                self.commit()
                return split
            if forced is not None and row["split"] != forced:
                raise YuanError("已有数据集划分不能在运行中改变 / An existing dataset split cannot change during operation")
            return row["split"]
        related = self.db.execute("SELECT split FROM groups WHERE source_key=? LIMIT 1", (source_key,)).fetchone()
        if related:
            split = related[0]
            if forced is not None and forced != split:
                raise YuanError("同源录音不能分入不同数据集 / Recordings from one source cannot cross dataset splits")
        elif forced in ("train", "validation", "guard", "release"):
            split = forced
        else:
            counts = dict(self.db.execute("SELECT split,count(DISTINCT source_key) FROM groups WHERE split<>'release' AND id IN (SELECT group_id FROM samples WHERE learnable=1 UNION SELECT group_id FROM turn_pairs WHERE verified=1) GROUP BY split"))
            empty = next((name for name in ("train", "validation", "guard") if not counts.get(name)), None)
            split = empty or min(("validation", "guard"), key=lambda name: counts.get(name, 0))
            if not empty and counts.get(split, 0) >= math.isqrt(sum(counts.values()) + 1):
                split = "train"
        self.db.execute("INSERT INTO groups(id,split,origin,created,source_key,retention,provenance) VALUES(?,?,?,?,?,?,?)", (group_id, split, origin, time.time(), source_key, retention, json.dumps(provenance or {}, ensure_ascii=False, allow_nan=False, separators=(",", ":"))))
        self.commit()
        return split

    def session(self, session_id, prompt, language):
        self.db.execute("INSERT INTO sessions VALUES(?,?,?,?,NULL)", (session_id, prompt, language, time.time()))
        self.commit()

    def end_session(self, session_id):
        self.db.execute("UPDATE sessions SET ended=? WHERE id=? AND ended IS NULL", (time.time(), session_id))
        self.commit()

    def add(self, group_id, role, waveform, rate, origin, cancel=None, generated=False, eligible=True, created=None, metadata=None, task="acoustic", sample_id=None, prepared=None):
        with self.audio_files(cancel):
            return self._add(group_id, role, waveform, rate, origin, cancel, generated, eligible, created, metadata, task, sample_id, prepared)

    def audio_eligibility(self, group_id, checksum, eligible, generated):
        if generated:
            return False, "generated"
        if not eligible:
            return False, "capture_quality"
        group = self.db.execute("SELECT source_key,split FROM groups WHERE id=?", (group_id,)).fetchone()
        self.db.execute("INSERT OR IGNORE INTO audio_partitions(digest,source_key,split) VALUES(?,?,?)", (checksum, group["source_key"], group["split"]))
        binding = self.db.execute("SELECT source_key,split FROM audio_partitions WHERE digest=?", (checksum,)).fetchone()
        if binding["split"] != group["split"]:
            return False, "duplicate_partition"
        if binding["source_key"] != group["source_key"]:
            return False, "duplicate_source"
        return True, ""

    def validate_transcript(self, checksum, sample_id, metadata):
        if metadata.get("transcript_verified") is not True:
            return
        text = metadata.get("transcript")
        if not isinstance(text, str) or not text.strip() or metadata.get("language") not in ("中文", "English", "mixed"):
            raise IneligibleSample("已确认转写缺少文本或语言 / Verified transcript lacks text or language")
        normalized = SpeechVerifier.normalize_text(text)
        rows = self.db.execute("SELECT metadata FROM samples WHERE digest=? AND id<>? AND generated=0 AND dialogue_eligible=1 AND json_extract(metadata,'$.transcript_verified')=1", (checksum, sample_id)).fetchall()
        for row in rows:
            prior = json.loads(row["metadata"])
            if SpeechVerifier.normalize_text(prior.get("transcript", "")) != normalized or prior.get("language") != metadata["language"]:
                raise IneligibleSample("同一音频存在冲突的已确认转写 / Conflicting verified transcripts for the same audio")

    def refresh_audio_owner(self, checksum, preferred=None):
        owner = self.db.execute("SELECT id FROM samples WHERE digest=? AND generated=0 AND dialogue_eligible=1 AND task='acoustic' AND exclusion NOT LIKE 'acoustic:%' ORDER BY COALESCE(json_extract(metadata,'$.transcript_verified')=1 AND length(json_extract(metadata,'$.transcript'))>0,0) DESC,COALESCE(length(json_extract(metadata,'$.annotation_id'))>0,0) DESC,(json_type(metadata,'$.utterance_final') IN ('true','false')) DESC,learnable DESC,(id=?) DESC,created,id LIMIT 1", (checksum, preferred)).fetchone()
        identifier = owner["id"] if owner else None
        self.db.execute("UPDATE samples SET learnable=0 WHERE digest=? AND learnable=1 AND id IS NOT ?", (checksum, identifier))
        if identifier is not None:
            self.db.execute("UPDATE samples SET learnable=1 WHERE id=? AND learnable=0", (identifier,))

    def _add(self, group_id, role, waveform, rate, origin, cancel=None, generated=False, eligible=True, created=None, metadata=None, task="acoustic", sample_id=None, prepared=None):
        generated = bool(generated or (origin == "local" and role == "assistant"))
        task = "generated_reply" if generated else str(task)
        if task not in ("acoustic", "generated_reply"):
            raise YuanError("音频学习任务无效 / Invalid audio learning task")
        explicit_time = created is not None
        created = time.time() if created is None else float(created)
        if not math.isfinite(created):
            raise YuanError("音频时间无效 / Invalid audio timestamp")
        metadata = dict(metadata or {})
        own_preparation = prepared is None
        prepared = self.prepare_audio(waveform, rate, cancel, purpose="conversation" if origin == "local" else "learning") if prepared is None else prepared
        checksum = prepared["digest"]
        try:
            check(cancel)
            with self.transaction():
                if origin == "public":
                    existing = self.db.execute("SELECT id FROM samples WHERE digest=? AND group_id=? AND role=? AND task=? ORDER BY created,id LIMIT 1", (checksum, group_id, role, task)).fetchone()
                    if existing:
                        sample_id = existing["id"]
                sample_id = str(sample_id or uuid.uuid4().hex)
                previous = self.db.execute("SELECT * FROM samples WHERE id=?", (sample_id,)).fetchone()
                if previous is not None:
                    if (previous["digest"] != checksum or previous["group_id"] != group_id or previous["role"] != role
                            or previous["task"] != task or previous["rate"] != prepared["rate"] or previous["count"] != prepared["count"]):
                        raise YuanError("音频片段标识与内容不一致 / Audio sample identity does not match its content")
                    if not explicit_time:
                        created = previous["created"]
                    prior_metadata = json.loads(previous["metadata"])
                    if origin != "dataset":
                        verified_update = metadata.get("transcript_verified") is True
                        metadata = {**prior_metadata, **metadata}
                        if prior_metadata.get("transcript_verified") is True and not verified_update:
                            metadata.update({key: prior_metadata[key] for key in ("transcript", "transcript_verified", "language") if key in prior_metadata})
                self.group(group_id, origin, source_key=metadata.get("recording_id") or metadata.get("source") or group_id,
                           retention="training_cache" if origin == "public" else "protected",
                           provenance={key: metadata[key] for key in ("source", "url", "license", "license_url", "attribution", "source_sha256", "source_sha1") if key in metadata})
                dialogue_eligible, exclusion = self.audio_eligibility(group_id, checksum, eligible, generated)
                if dialogue_eligible:
                    self.validate_transcript(checksum, sample_id, metadata)
                encoded_metadata = json.dumps(metadata, ensure_ascii=False, allow_nan=False, separators=(",", ":"))
                memory_reason = self.memory_reason(metadata, eligible, generated)
                if previous is not None:
                    changed = (previous["exclusion"] == "annotation_removed" or previous["created"] != created
                               or self.sample_supervision(prior_metadata) != self.sample_supervision(metadata)
                               or bool(previous["dialogue_eligible"]) != dialogue_eligible
                               or previous["memory_exclusion"] != memory_reason)
                    if changed:
                        self.db.execute("UPDATE samples SET metadata=?,created=?,cursor=0,visits=0,memory_eligible=?,memory_exclusion=?,learnable=0,dialogue_eligible=?,exclusion=? WHERE id=?",
                                        (encoded_metadata, created, int(not memory_reason), memory_reason, int(dialogue_eligible), exclusion, sample_id))
                        self.db.execute("DELETE FROM memories WHERE sample_id=?", (sample_id,))
                        self.db.execute("DELETE FROM memory_progress WHERE sample_id=?", (sample_id,))
                        if self.db.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='speech_training'").fetchone():
                            self.db.execute("DELETE FROM speech_training WHERE sample=?", (sample_id,))
                        self.db.execute("UPDATE turn_pairs SET eligible=0,verified=0,cursor=0,visits=0,retry_at=0,failures=0,error='' WHERE user_sample=? OR assistant_sample=?", (sample_id, sample_id))
                        self.refresh_audio_owner(checksum, sample_id if previous["learnable"] else None)
                    elif prior_metadata != metadata:
                        self.db.execute("UPDATE samples SET metadata=? WHERE id=?", (encoded_metadata, sample_id))
                    return sample_id
                owner = self.db.execute("SELECT id FROM samples WHERE digest=? AND learnable=1", (checksum,)).fetchone()
                learnable = bool(dialogue_eligible and not generated and task == "acoustic" and owner is None)
                self.db.execute("INSERT INTO samples(id,group_id,role,task,audio,seconds,rate,count,created,digest,file_sha256,generated,learnable,dialogue_eligible,memory_eligible,memory_exclusion,exclusion,metadata) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                                (sample_id, group_id, role, task, prepared["audio"], prepared["count"] / prepared["rate"], prepared["rate"], prepared["count"], created, checksum, prepared["file_sha256"], int(generated), int(learnable), int(dialogue_eligible), int(not memory_reason), memory_reason, exclusion, encoded_metadata))
                self.refresh_audio_owner(checksum)
            return sample_id
        except BaseException:
            if own_preparation:
                self.discard_audio(prepared)
            raise

    def add_pair(self, group_id, user_sample, assistant_sample, source, quality=1.0, verified=False, created=None, evidence=None):
        quality = float(quality)
        if not math.isfinite(quality) or quality <= 0 or user_sample == assistant_sample:
            raise YuanError("对话配对质量或角色无效 / Invalid dialogue pair quality or roles")
        rows = self.db.execute("SELECT * FROM samples WHERE id IN (?,?)", (user_sample, assistant_sample)).fetchall()
        by_id = {row["id"]: row for row in rows}
        if user_sample not in by_id or assistant_sample not in by_id or by_id[user_sample]["group_id"] != group_id or by_id[assistant_sample]["group_id"] != group_id:
            raise YuanError("对话配对来源不一致 / Dialogue pair provenance mismatch")
        user, assistant = by_id[user_sample], by_id[assistant_sample]
        if user["digest"] == assistant["digest"]:
            raise IneligibleSample("输入与回复不能引用同一音频 / Input and reply cannot reference the same audio")
        evidence = dict(evidence or {})
        if verified:
            required = ("reviewer", "annotation_id", "recording_id", "user_speaker", "assistant_speaker", "prompt")
            group = self.db.execute("SELECT source_key FROM groups WHERE id=?", (group_id,)).fetchone()
            valid = (all(isinstance(evidence.get(key), str) and evidence[key].strip() for key in required)
                     and evidence.get("method") == "human_audio_annotation"
                     and evidence.get("language") in ("中文", "English")
                     and evidence.get("roles_verified") is True and evidence.get("response_verified") is True
                     and evidence["user_speaker"] != evidence["assistant_speaker"]
                     and evidence["recording_id"] == group["source_key"]
                     and evidence.get("user_sha256") == user["digest"] and evidence.get("assistant_sha256") == assistant["digest"]
                     and user["role"] == "user" and assistant["role"] == "assistant"
                     and not user["generated"] and not assistant["generated"]
                     and user["dialogue_eligible"] and assistant["dialogue_eligible"])
            if not valid:
                raise YuanError("对话配对缺少可信角色、回复关系或来源证据 / Dialogue pair lacks valid role, reply or provenance evidence")
        pair_id = hashlib.sha256((group_id + "\0" + user_sample + "\0" + assistant_sample + "\0" + str(source)).encode()).hexdigest()
        timestamp = time.time() if created is None else float(created)
        if not math.isfinite(timestamp):
            raise YuanError("对话配对时间无效 / Invalid dialogue pair timestamp")
        with self.transaction():
            previous = self.db.execute("SELECT evidence,source,quality FROM turn_pairs WHERE user_sample=? AND assistant_sample=?", (user_sample, assistant_sample)).fetchone()
            changed = previous is not None and (self.pair_supervision(json.loads(previous["evidence"])) != self.pair_supervision(evidence) or previous["source"] != str(source) or previous["quality"] != quality)
            self.db.execute("INSERT INTO turn_pairs(id,group_id,user_sample,assistant_sample,source,quality,verified,evidence,created) VALUES(?,?,?,?,?,?,?,?,?) ON CONFLICT(user_sample,assistant_sample) DO UPDATE SET source=excluded.source,verified=excluded.verified,evidence=excluded.evidence,quality=excluded.quality,eligible=1,cursor=CASE WHEN ? THEN 0 ELSE turn_pairs.cursor END,visits=CASE WHEN ? THEN 0 ELSE turn_pairs.visits END,retry_at=0,failures=0,error='' WHERE excluded.verified>=turn_pairs.verified",
                            (pair_id, group_id, user_sample, assistant_sample, str(source), quality, int(bool(verified)), json.dumps(evidence, ensure_ascii=False, allow_nan=False, separators=(",", ":")), timestamp, int(changed), int(changed)))
            if changed:
                self.revise(group_id)
        return self.db.execute("SELECT id FROM turn_pairs WHERE user_sample=? AND assistant_sample=?", (user_sample, assistant_sample)).fetchone()[0]

    def add_corpus_pair(self, group_id, user_sample, assistant_sample, prompt):
        user, assistant = self.sample(user_sample), self.sample(assistant_sample)
        if (user is None or assistant is None or user["group_id"] != group_id or assistant["group_id"] != group_id
                or user["generated"] or assistant["generated"] or not user["dialogue_eligible"] or not assistant["dialogue_eligible"]
                or user["role"] != "user" or assistant["role"] != "assistant" or not isinstance(prompt, str) or not prompt.strip()):
            raise IneligibleSample("公开对话训练来源无效 / Invalid public dialogue training provenance")
        left, right = json.loads(user["metadata"]), json.loads(assistant["metadata"])
        keys = ("recording_id", "corpus", "revision", "source_file_sha256", "license")
        if (any(not left.get(key) or left.get(key) != right.get(key) for key in keys)
                or left["corpus"] != PublicDialogue.repository or left["license"] != "CC-BY-SA-4.0"
                or not is_digest(left["source_file_sha256"]) or not re.fullmatch(r"[a-f0-9]{40}", str(left["revision"]))
                or {left.get("channel"), right.get("channel")} != {0, 1}
                or any(item.get("channel_separation_verified") is not True for item in (left, right))
                or left.get("turn_index", -1) + 1 != right.get("turn_index")
                or left.get("source_end") != right.get("source_start")):
            raise IneligibleSample("公开对话缺少录音、声道或轮次证据 / Public dialogue lacks recording, channel or turn evidence")
        evidence = {key: left[key] for key in keys}
        evidence.update(method="published_stereo_dialogue_v1", training_only=True, language="English", prompt=prompt,
                        user_sha256=user["digest"], assistant_sha256=assistant["digest"], scenarios=[], contrasts={},
                        user_speaker=str(left["channel"]), assistant_speaker=str(right["channel"]), relation="next_speaker_turn")
        return self.add_pair(group_id, user_sample, assistant_sample, "published_dialogue_turns", verified=False, evidence=evidence)

    def training_pairs(self, split, limit, hop, model, cancel=None):
        if split not in ("validation", "guard"):
            raise YuanError("训练评估划分无效 / Invalid training evaluation split")
        query = ("SELECT p.*,g.split,g.origin,g.source_key FROM turn_pairs p JOIN groups g ON g.id=p.group_id "
                 "JOIN samples u ON u.id=p.user_sample JOIN samples a ON a.id=p.assistant_sample "
                 "WHERE g.split=? AND p.verified=1 AND p.eligible=1 AND p.retry_at<=? "
                 "AND u.audio_status='ready' AND a.audio_status='ready' AND u.generated=0 AND a.generated=0 "
                 "AND u.dialogue_eligible=1 AND a.dialogue_eligible=1 AND u.count>=? AND a.count>=? "
                 "ORDER BY g.source_key,p.id")
        selected, seen = [], set()
        budgets = EvaluationEligibility.budgets(model)
        cursor = self.db.execute(query, (split, time.time(), hop, hop))
        try:
            for row in cursor:
                check(cancel)
                if row["source_key"] in seen:
                    continue
                evidence = json.loads(row["evidence"])
                if not SpeechVerifier.answers(evidence) or not EvaluationEligibility.pair(self, model, row, split, budgets)["ready"]:
                    continue
                try:
                    SpeechVerifier.answer_policy(evidence)
                except IneligibleSample:
                    continue
                seen.add(row["source_key"])
                selected.append(row)
                if len(selected) >= max(2, int(limit)):
                    break
        finally:
            cursor.close()
        return selected

    def assert_independent(self, group_ids):
        if not group_ids:
            return
        placeholders = ",".join("?" for _ in group_ids)
        overlap = self.db.execute("SELECT a.source_key FROM groups a JOIN groups b ON a.source_key=b.source_key AND a.split<>b.split WHERE a.id IN (" + placeholders + ") LIMIT 1", tuple(group_ids)).fetchone()
        repeated = self.db.execute("SELECT a.digest FROM samples a JOIN groups ga ON ga.id=a.group_id JOIN samples b ON b.digest=a.digest AND b.group_id<>a.group_id JOIN groups gb ON gb.id=b.group_id WHERE a.group_id IN (" + placeholders + ") AND ga.split<>gb.split AND (a.learnable=1 OR a.dialogue_eligible=1) AND (b.learnable=1 OR b.dialogue_eligible=1) LIMIT 1", tuple(group_ids)).fetchone()
        if overlap or repeated:
            raise YuanError("训练与留出数据存在同源或重复音频 / Training and held-out data share a source or duplicate audio")

    def db_size(self):
        return sum(path.stat().st_size for path in self.root.glob("memory.sqlite3*") if path.is_file())

    def next_sample(self, split, min_count=2):
        return self.db.execute("SELECT samples.*,groups.split,groups.origin FROM samples JOIN groups ON groups.id=group_id WHERE split=? AND samples.audio_status='ready' AND task='acoustic' AND learnable=1 AND generated=0 AND count>=? ORDER BY visits,samples.created LIMIT 1", (split, max(1, int(min_count)))).fetchone()

    def held_out(self, split, limit, min_count=2):
        return self.db.execute("WITH eligible AS (SELECT s.*,g.split,g.origin,g.source_key,ROW_NUMBER() OVER (PARTITION BY g.source_key ORDER BY s.id) AS position FROM samples s JOIN groups g ON g.id=s.group_id WHERE g.split=? AND s.audio_status='ready' AND s.task='acoustic' AND s.learnable=1 AND s.generated=0 AND s.count>=?) SELECT * FROM eligible WHERE position=1 ORDER BY id LIMIT ?", (split, max(1, int(min_count)), max(1, int(limit)))).fetchall()

    def next_pair(self, split, min_source=2, min_target=2):
        return self.db.execute("SELECT p.*,g.split,g.origin,g.source_key FROM turn_pairs p JOIN groups g ON g.id=p.group_id JOIN samples u ON u.id=p.user_sample JOIN samples a ON a.id=p.assistant_sample WHERE g.split=? AND p.retry_at<=? AND p.eligible=1 AND u.audio_status='ready' AND a.audio_status='ready' AND " + self.training_pair_filter + " AND u.generated=0 AND a.generated=0 AND u.dialogue_eligible=1 AND a.dialogue_eligible=1 AND u.count>=? AND a.count>=? ORDER BY p.visits,p.created LIMIT 1", (split, time.time(), max(1, int(min_source)), max(1, int(min_target)))).fetchone()

    def coverage_pairs(self, split, language, hop):
        if split != "train":
            return self.evaluation_pairs(split, language, hop)
        return self.db.execute("SELECT p.*,g.split,g.origin,g.source_key FROM turn_pairs p JOIN groups g ON g.id=p.group_id JOIN samples u ON u.id=p.user_sample JOIN samples a ON a.id=p.assistant_sample WHERE g.split=? AND json_extract(p.evidence,'$.language')=? AND p.retry_at<=? AND " + self.training_pair_filter + " AND p.eligible=1 AND u.audio_status='ready' AND a.audio_status='ready' AND u.generated=0 AND a.generated=0 AND u.dialogue_eligible=1 AND a.dialogue_eligible=1 AND u.count>=? AND a.count>=? ORDER BY g.source_key,p.id", (split, language, time.time(), max(1, int(hop)), max(1, int(hop)))).fetchall()

    def evaluation_pairs(self, split, language, hop):
        return self.db.execute("SELECT p.*,g.split,g.origin,g.source_key FROM turn_pairs p JOIN groups g ON g.id=p.group_id JOIN samples u ON u.id=p.user_sample JOIN samples a ON a.id=p.assistant_sample WHERE g.split=? AND json_extract(p.evidence,'$.language')=? AND p.retry_at<=? AND p.verified=1 AND p.eligible=1 AND u.audio_status='ready' AND a.audio_status='ready' AND u.generated=0 AND a.generated=0 AND u.dialogue_eligible=1 AND a.dialogue_eligible=1 AND u.count>=? AND a.count>=? ORDER BY g.source_key,p.id", (split, language, time.time(), hop, hop)).fetchall()

    def sample(self, sample_id):
        return self.db.execute("SELECT s.*,g.split,g.origin,g.source_key FROM samples s JOIN groups g ON g.id=s.group_id WHERE s.id=?", (sample_id,)).fetchone()

    def read_audio(self, row, start=0, count=None, cancel=None, verify=False):
        import numpy as np
        import soundfile as sf
        def signature(path):
            stat = path.stat()
            return stat.st_size, stat.st_mtime_ns, stat.st_ctime_ns, stat.st_dev, stat.st_ino
        try:
            check(cancel)
            path = safe_path(self.root, row["audio"])
            before = signature(path)
            expected = row["file_sha256"]
            cached = self.integrity_cache.get(row["audio"])
            if verify or cached != (before, expected):
                if not is_digest(expected) or digest_file(path, cancel) != expected:
                    raise InvalidAudio("历史音频内容摘要不匹配 / Historical audio content digest mismatch")
            with sf.SoundFile(str(path)) as stream:
                if stream.samplerate != row["rate"] or stream.channels != 1 or stream.frames != row["count"]:
                    raise InvalidAudio("历史音频格式或长度不匹配 / Historical audio format or length mismatch")
                start = max(0, min(int(start), stream.frames))
                stream.seek(start)
                count = stream.frames - start if count is None else max(0, min(int(count), stream.frames - start))
                values = stream.read(count, dtype="float32", always_2d=False)
            check(cancel)
            if signature(path) != before:
                raise OSError("音频读取期间发生变化 / Audio changed while being read")
            if not values.size or not np.isfinite(values).all():
                raise InvalidAudio("历史音频无效 / Historical audio is invalid")
            limit = self.policy.integer("storage", "integrity_cache_entries", max(16, (os.cpu_count() or 1) * 16), 1, 65536)
            if len(self.integrity_cache) >= limit:
                self.integrity_cache.pop(next(iter(self.integrity_cache)))
            self.integrity_cache[row["audio"]] = (before, expected)
            current = self.db.execute("SELECT audio_status,read_failures FROM samples WHERE id=?", (row["id"],)).fetchone()
            if current and (current["audio_status"] != "ready" or current["read_failures"]):
                self.db.execute("UPDATE samples SET audio_status='ready',retry_at=0,read_failures=0,audio_error='' WHERE id=?", (row["id"],))
                self.commit()
            return values
        except Cancelled:
            raise
        except (OSError, RuntimeError, ValueError) as exc:
            self.audio_failure(row, exc)
            raise

    def advance(self, row, cursor):
        wrapped = cursor >= row["count"]
        self.db.execute("UPDATE samples SET cursor=?,visits=visits+? WHERE id=?", (0 if wrapped else max(0, cursor), int(wrapped), row["id"]))
        self.commit()

    def advance_pair(self, row, cursor, target_count):
        wrapped = cursor >= target_count
        self.db.execute("UPDATE turn_pairs SET cursor=?,visits=visits+? WHERE id=?", (0 if wrapped else max(0, cursor), int(wrapped), row["id"]))
        self.commit()

    def memory_rows(self, exclude_group, model_key, batch_size, cancel=None):
        cursor = self.db.execute("SELECT s.*,m.vector,m.dims,m.start AS memory_start,m.end AS memory_end FROM samples s JOIN groups g ON g.id=s.group_id JOIN sessions x ON x.id=s.group_id JOIN memories m ON m.sample_id=s.id WHERE g.origin='local' AND s.group_id<>? AND x.ended IS NOT NULL AND s.audio_status='ready' AND s.memory_eligible=1 AND s.count>1 AND m.model_key=? ORDER BY s.created DESC,s.id", (exclude_group, model_key))
        try:
            while True:
                check(cancel)
                rows = cursor.fetchmany(max(1, int(batch_size)))
                if not rows:
                    return
                for row in rows:
                    check(cancel)
                    yield row
        finally:
            cursor.close()

    def save_memory_vector(self, sample_id, model_key, vector, start=0, end=None):
        import numpy as np
        row = self.db.execute("SELECT count,memory_eligible,audio_status FROM samples WHERE id=?", (sample_id,)).fetchone()
        if row is None or not row["memory_eligible"] or row["audio_status"] != "ready":
            return False
        end = row["count"] if end is None else end
        if type(start) is not int or type(end) is not int or not 0 <= start < end <= row["count"]:
            raise ValueError("记忆区间无效 / Invalid memory interval")
        values = np.asarray(vector, dtype=np.float32).reshape(-1)
        if not values.size or not np.isfinite(values).all() or np.linalg.norm(values) <= np.finfo(np.float32).eps:
            raise InvalidAudio("记忆向量无效 / Invalid memory vector")
        buckets = self.memory_signature(model_key, values)
        with self.transaction():
            self.db.execute("DELETE FROM memories WHERE sample_id=? AND model_key=? AND start=? AND end=?", (sample_id, model_key, start, end))
            self.db.execute("INSERT INTO memories(sample_id,model_key,start,end,vector,dims,created) VALUES(?,?,?,?,?,?,?)", (sample_id, model_key, start, end, values.tobytes(), len(values), time.time()))
            self.db.executemany("INSERT INTO memory_buckets(model_key,band,bucket,sample_id,start,end) VALUES(?,?,?,?,?,?)", ((model_key, band, value, sample_id, start, end) for band, value in enumerate(buckets)))
            self.db.execute("INSERT INTO memory_progress(sample_id,model_key,next_start) VALUES(?,?,?) ON CONFLICT(sample_id,model_key) DO UPDATE SET next_start=max(memory_progress.next_start,excluded.next_start),failures=0,retry_at=0", (sample_id, model_key, end))
        return True

    def stats(self):
        rows = self.db.execute("SELECT origin,count(*) AS n,coalesce(sum(seconds),0) AS seconds,sum(learnable AND audio_status='ready') AS learnable,sum(generated) AS generated,sum(NOT generated AND (NOT learnable OR audio_status<>'ready')) AS excluded FROM samples JOIN groups ON groups.id=group_id GROUP BY origin").fetchall()
        result = {row["origin"]: {"count": row["n"], "seconds": row["seconds"], "learnable": row["learnable"], "generated": row["generated"], "excluded": row["excluded"]} for row in rows}
        pairs = self.db.execute("SELECT g.split,count(*) AS n,sum(p.verified AND p.eligible AND u.dialogue_eligible AND a.dialogue_eligible AND u.audio_status='ready' AND a.audio_status='ready' AND NOT u.generated AND NOT a.generated) AS verified FROM turn_pairs p JOIN groups g ON g.id=p.group_id JOIN samples u ON u.id=p.user_sample JOIN samples a ON a.id=p.assistant_sample GROUP BY g.split").fetchall()
        result["dialogue"] = {"count": sum(row["n"] for row in pairs), "verified": sum(row["verified"] or 0 for row in pairs), **{row["split"]: row["verified"] or 0 for row in pairs}}
        supervised = self.db.execute("SELECT g.split,count(*) AS n FROM turn_pairs p JOIN groups g ON g.id=p.group_id JOIN samples u ON u.id=p.user_sample JOIN samples a ON a.id=p.assistant_sample WHERE " + self.training_pair_filter + " AND p.eligible=1 AND u.dialogue_eligible=1 AND a.dialogue_eligible=1 AND u.audio_status='ready' AND a.audio_status='ready' AND u.generated=0 AND a.generated=0 GROUP BY g.split").fetchall()
        result["dialogue"]["supervised"] = sum(row["n"] for row in supervised)
        result["dialogue"]["training_splits"] = {row["split"]: row["n"] for row in supervised}
        return result

    def close(self):
        try:
            self.db.execute("PRAGMA wal_checkpoint(PASSIVE)")
        finally:
            self.db.close()

    def commit(self):
        if not self.transaction_depth:
            try:
                self.db.commit()
            except BaseException:
                self.db.rollback()
                raise

    @contextmanager
    def transaction(self):
        outer = self.transaction_depth == 0
        if outer:
            self.db.execute("BEGIN IMMEDIATE")
        self.transaction_depth += 1
        try:
            yield
            if outer:
                self.db.commit()
        except BaseException:
            if outer:
                self.db.rollback()
            raise
        finally:
            self.transaction_depth -= 1

    def retry_delay(self, attempts, invalid=False):
        base = self.policy.number("storage", "audio_retry_seconds", max(0.1, math.sqrt(tick())), tick(), 3600.0)
        ceiling = self.policy.number("storage", "audio_retry_max_seconds", max(60.0, base), base, 86400.0)
        if invalid:
            base = self.policy.number("storage", "integrity_recheck_seconds", ceiling, base, 86400.0)
        return min(max(base, ceiling), base * min(max(1, attempts), math.sqrt(max(base, ceiling) / base)) ** 2)

    def audio_failure(self, row, exc):
        if row is None or getattr(exc, "yuan_sample", None) == row["id"]:
            return
        current = self.db.execute("SELECT read_failures,audio,audio_status FROM samples WHERE id=?", (row["id"],)).fetchone()
        if current is None or current["audio_status"] == "evicted":
            return
        invalid = isinstance(exc, InvalidAudio)
        attempts = current["read_failures"] + 1
        self.db.execute("UPDATE samples SET audio_status=?,retry_at=?,read_failures=?,audio_error=? WHERE id=?",
                        ("invalid" if invalid else "retry", time.time() + self.retry_delay(attempts, invalid), attempts, concise_error(exc), row["id"]))
        self.db.execute("DELETE FROM memories WHERE sample_id=?", (row["id"],))
        self.integrity_cache.pop(current["audio"], None)
        self.commit()
        try:
            exc.yuan_sample = row["id"]
        except (AttributeError, TypeError):
            pass

    def pair_failure(self, row, exc):
        current = self.db.execute("SELECT failures FROM turn_pairs WHERE id=?", (row["id"],)).fetchone()
        if current is None:
            return
        attempts = current[0] + 1
        self.db.execute("UPDATE turn_pairs SET retry_at=?,failures=?,error=? WHERE id=?",
                        (time.time() + self.retry_delay(attempts), attempts, concise_error(exc), row["id"]))
        self.commit()

    def recheck_audio(self, cancel=None):
        limit = self.policy.integer("storage", "recheck_batch", max(1, math.isqrt(os.cpu_count() or 1)), 1, max(1, os.cpu_count() or 1))
        rows = self.db.execute("SELECT * FROM samples WHERE audio_status IN ('retry','invalid') AND retry_at<=? ORDER BY retry_at,id LIMIT ?", (time.time(), limit)).fetchall()
        recovered = 0
        for row in rows:
            check(cancel)
            try:
                self.read_audio(row, 0, min(row["count"], row["rate"]), cancel=cancel, verify=True)
                recovered += 1
            except Cancelled:
                raise
            except (OSError, RuntimeError, ValueError):
                pass
        return recovered

    def prepare_audio(self, waveform, rate, cancel=None, purpose="learning"):
        import numpy as np
        import soundfile as sf
        waveform = np.asarray(waveform, dtype=np.float32).reshape(-1)
        if not waveform.size or not np.isfinite(waveform).all() or isinstance(rate, bool) or not isinstance(rate, int) or rate <= 0:
            raise InvalidAudio("音频样本无效 / Invalid audio sample")
        if np.max(np.abs(waveform)) > 1:
            raise InvalidAudio("音频超出可保存范围 / Audio is outside the supported range")
        canonical = np.floor(waveform.astype(np.float64) * (1 << 23)).clip(-(1 << 23), (1 << 23) - 1).astype("<i4")
        checksum = hashlib.sha256(canonical.tobytes() + str(rate).encode("ascii")).hexdigest()
        target = safe_path(self.audio, checksum + ".flac")
        temporary = self.audio / (checksum + "-" + uuid.uuid4().hex + ".partial")
        new_file = not target.is_file()
        with StorageBudget(self.root.parent).reserve(waveform.nbytes * 2 + self.db_size(), purpose):
            try:
                check(cancel)
                sf.write(str(temporary), canonical.astype(np.float32) / (1 << 23), rate, format="FLAC", subtype="PCM_24")
                with temporary.open("rb") as stream:
                    os.fsync(stream.fileno())
                file_sha256 = digest_file(temporary, cancel)
                check(cancel)
                existing_hash = None if new_file else digest_file(target, cancel)
                known = self.db.execute("SELECT file_sha256 FROM samples WHERE audio=? LIMIT 1", (target.relative_to(self.root).as_posix(),)).fetchone()
                if known and existing_hash == known["file_sha256"]:
                    file_sha256 = existing_hash
                elif new_file or existing_hash != file_sha256:
                    os.replace(temporary, target)
                    sync_dir(target.parent)
                    self.integrity_cache.pop(target.relative_to(self.root).as_posix(), None)
                    if known:
                        with self.transaction():
                            self.db.execute("UPDATE samples SET file_sha256=?,audio_status='ready',retry_at=0,read_failures=0,audio_error='' WHERE audio=? AND digest=?",
                                            (file_sha256, target.relative_to(self.root).as_posix(), checksum))
                if known:
                    with self.transaction():
                        self.db.execute("UPDATE samples SET audio_status='ready',retry_at=0,read_failures=0,audio_error='' WHERE audio=? AND digest=? AND audio_status='evicted' AND file_sha256=?",
                                        (target.relative_to(self.root).as_posix(), checksum, file_sha256))
                return {"audio": target.relative_to(self.root).as_posix(), "digest": checksum, "file_sha256": file_sha256,
                        "rate": rate, "count": len(waveform), "new_file": new_file}
            finally:
                temporary.unlink(missing_ok=True)

    def discard_audio(self, prepared):
        if prepared.get("new_file") and not self.db.execute("SELECT 1 FROM samples WHERE audio=?", (prepared["audio"],)).fetchone():
            safe_path(self.root, prepared["audio"]).unlink(missing_ok=True)
            self.integrity_cache.pop(prepared["audio"], None)

    @contextmanager
    def audio_files(self, cancel=None):
        while not self.file_lock.acquire(timeout=math.sqrt(tick())):
            check(cancel)
        try:
            check(cancel)
            yield
        finally:
            self.file_lock.release()


    def exclude_task(self, row, task, reason):
        if task == "dialogue":
            self.db.execute("UPDATE turn_pairs SET eligible=0,eligibility_error=?,retry_at=0 WHERE id=?", (str(reason), row["id"]))
        elif task == "acoustic":
            self.db.execute("UPDATE samples SET learnable=0,exclusion=? WHERE id=?", ("acoustic: " + str(reason), row["id"]))
        else:
            raise ValueError(task)
        self.commit()

    def memory_signature(self, model_key, vector):
        import numpy as np
        dimensions = len(vector)
        bits = max(1, int(math.ceil(math.log2(max(2, dimensions)))))
        bands = max(2, int(math.ceil(math.sqrt(bits))))
        cache = getattr(self, "memory_projections", None)
        identity = (model_key, dimensions)
        if cache is None or cache[0] != identity:
            seed = int(payload_digest(["yuan-memory-index-v1", model_key, dimensions]), 16)
            projections = np.random.default_rng(seed).standard_normal((bands, bits, dimensions)).astype(np.float32)
            self.memory_projections = identity, projections
        else:
            projections = cache[1]
        signs = np.einsum("bkd,d->bk", projections, vector) >= 0
        return tuple(sum(int(value) << offset for offset, value in enumerate(row)) for row in signs)

    def prune_memory_versions(self, cancel=None):
        check(cancel)
        with self.transaction():
            keys = [self.setting(name) for name in ("serving_memory_key", "building_memory_key", "previous_memory_key")]
            keys = sorted({key for key in keys if isinstance(key, str) and key})
            if not keys:
                return False
            placeholders = ",".join("?" for key in keys)
            for table in ("memories", "memory_progress", "memory_index_stats", "memory_calibrations"):
                check(cancel)
                self.db.execute("DELETE FROM " + table + " WHERE model_key NOT IN (" + placeholders + ")", keys)
        return True

    def memory_index_pending(self, model_key):
        return self.db.execute("SELECT 1 FROM samples s JOIN groups g ON g.id=s.group_id JOIN sessions x ON x.id=s.group_id LEFT JOIN memory_progress m ON m.sample_id=s.id AND m.model_key=? WHERE g.origin='local' AND x.ended IS NOT NULL AND s.audio_status='ready' AND s.memory_eligible=1 AND s.count>1 AND COALESCE(m.next_start,0)<s.count LIMIT 1", (model_key,)).fetchone() is not None

    def indexed_memory_count(self, model_key):
        row = self.db.execute("SELECT items FROM memory_index_stats WHERE model_key=?", (model_key,)).fetchone()
        return max(0, int(row[0])) if row is not None else 0

    def memory_candidates(self, exclude_group, model_key, query, limit, cancel):
        limit = max(1, int(limit))
        selection = "SELECT s.*,m.vector,m.dims,m.start AS memory_start,m.end AS memory_end FROM memories m JOIN samples s ON s.id=m.sample_id JOIN groups g ON g.id=s.group_id JOIN sessions x ON x.id=s.group_id "
        eligible = "g.origin='local' AND s.group_id<>? AND x.ended IS NOT NULL AND s.audio_status='ready' AND s.memory_eligible=1 AND s.count>1 AND m.model_key=?"
        try:
            signatures = self.memory_signature(model_key, query)
            bits = max(1, int(math.ceil(math.log2(max(2, len(query))))))
            found = {}
            for distance in (0, 1):
                for band, bucket in enumerate(signatures):
                    variants = (bucket,) if distance == 0 else tuple(bucket ^ (1 << bit) for bit in range(bits))
                    for value in variants:
                        check(cancel)
                        remaining = limit - len(found)
                        if remaining <= 0:
                            break
                        statement = selection + "JOIN memory_buckets b ON b.sample_id=m.sample_id AND b.model_key=m.model_key AND b.start=m.start AND b.end=m.end WHERE b.model_key=? AND b.band=? AND b.bucket=? AND " + eligible + " ORDER BY m.created DESC,s.id LIMIT ?"
                        for row in self.db.execute(statement, (model_key, band, value, exclude_group, model_key, remaining)):
                            if row["dims"] == len(query):
                                found[(row["id"], row["memory_start"], row["memory_end"])] = row
                    if len(found) >= limit:
                        break
                if len(found) >= limit:
                    break
            if len(found) < limit:
                for row in self.db.execute(selection + "WHERE " + eligible + " ORDER BY m.created DESC,s.id LIMIT ?", (exclude_group, model_key, limit)):
                    check(cancel)
                    if row["dims"] == len(query):
                        found.setdefault((row["id"], row["memory_start"], row["memory_end"]), row)
                    if len(found) >= limit:
                        break
            self.memory_search_mode = "indexed_approximate"
            for row in found.values():
                check(cancel)
                yield row
        except sqlite3.DatabaseError:
            self.memory_index_repair = True
            self.memory_search_mode = "exact_fallback"
            for index, row in enumerate(self.memory_rows(exclude_group, model_key, max(1, math.isqrt(limit)), cancel)):
                if index >= limit:
                    break
                yield row

    def repair_memory_index(self, model_key, cancel):
        import numpy as np
        check(cancel)
        with self.transaction():
            row = self.db.execute("SELECT m.* FROM memories m WHERE m.model_key=? AND NOT EXISTS(SELECT 1 FROM memory_buckets b WHERE b.sample_id=m.sample_id AND b.model_key=m.model_key AND b.start=m.start AND b.end=m.end) ORDER BY m.created DESC LIMIT 1", (model_key,)).fetchone()
            if row is None:
                self.memory_index_repair = False
                return False
            try:
                vector = np.frombuffer(row["vector"], dtype=np.float32)
                valid = len(vector) == row["dims"] and np.isfinite(vector).all() and np.linalg.norm(vector) > np.finfo(np.float32).eps
            except ValueError:
                valid = False
            if not valid:
                self.db.execute("DELETE FROM memories WHERE sample_id=? AND model_key=? AND start=? AND end=?", (row["sample_id"], model_key, row["start"], row["end"]))
                self.db.execute("UPDATE memory_progress SET next_start=min(next_start,?) WHERE sample_id=? AND model_key=?", (row["start"], row["sample_id"], model_key))
            else:
                buckets = self.memory_signature(model_key, vector)
                check(cancel)
                self.db.executemany("INSERT INTO memory_buckets(model_key,band,bucket,sample_id,start,end) VALUES(?,?,?,?,?,?)", ((model_key, band, value, row["sample_id"], row["start"], row["end"]) for band, value in enumerate(buckets)))
            self.memory_index_repair = True
        return True

    def _revision_triggers(self):
        def bump(key, condition="1"):
            return ("INSERT INTO settings(key,value) SELECT '" + key + "','1' WHERE " + condition +
                    " ON CONFLICT(key) DO UPDATE SET value=CAST(COALESCE(CAST(settings.value AS INTEGER),0)+1 AS TEXT);")
        def changed(columns):
            return " OR ".join("OLD." + col + " IS NOT NEW." + col for col in columns)
        def group_bump(ids, condition="1"):
            return ("INSERT INTO evaluation_group_revisions(group_id,revision) SELECT id,1 FROM groups WHERE id IN (" + ids + ") AND (" + condition + ") "
                    "ON CONFLICT(group_id) DO UPDATE SET revision=evaluation_group_revisions.revision+1;")
        def group_splits(action):
            ids = "OLD.group_id,NEW.group_id" if action == "UPDATE" else ("OLD" if action == "DELETE" else "NEW") + ".group_id"
            return "(SELECT split FROM groups WHERE id IN (" + ids + "))"
        fields = {
            "samples": ("group_id", "role", "task", "digest", "file_sha256", "rate", "count", "generated", "learnable", "dialogue_eligible", "memory_eligible", "created"),
            "turn_pairs": ("group_id", "user_sample", "assistant_sample", "source", "quality", "verified", "eligible")
        }
        statements = []
        for table, columns in fields.items():
            field = "metadata" if table == "samples" else "evidence"
            evidence = "yuan_evidence(OLD." + field + ") IS NOT yuan_evidence(NEW." + field + ")"
            supervision = "yuan_" + ("sample" if table == "samples" else "pair") + "_supervision"
            training = "(" + changed(columns) + " OR " + supervision + "(OLD." + field + ") IS NOT " + supervision + "(NEW." + field + "))"
            content = changed(columns) + " OR " + evidence
            if table == "samples":
                invalid = "(OLD.audio_status IS NOT NEW.audio_status AND NEW.audio_status='invalid')"
                training = "(" + training + " OR " + invalid + ")"
                content += " OR " + invalid
            for action in ("INSERT", "UPDATE", "DELETE"):
                ref = "OLD" if action == "DELETE" else "NEW"
                affected = group_splits(action)
                ids = "OLD.group_id,NEW.group_id" if action == "UPDATE" else ref + ".group_id"
                body = bump("data_revision") + group_bump(ids)
                for split in ("train", "validation", "guard", "release"):
                    body += bump("revision_" + split, "'" + split + "' IN " + affected)
                learnable = "1" if table == "turn_pairs" else ref + ".generated=0 AND (" + ref + ".learnable=1 OR " + ref + ".dialogue_eligible=1)"
                if table == "samples" and action == "UPDATE":
                    learnable = "((OLD.generated=0 AND (OLD.learnable=1 OR OLD.dialogue_eligible=1)) OR (NEW.generated=0 AND (NEW.learnable=1 OR NEW.dialogue_eligible=1)))"
                condition = "'train' IN " + affected + " AND (" + learnable + ")"
                if action == "UPDATE":
                    condition += " AND " + training
                body += bump("training_addition_revision" if action == "INSERT" else "training_revision", condition)
                body += bump("evaluation_revision", "EXISTS(SELECT 1 FROM " + affected + " WHERE split<>'train')")
                name = "revision_" + table + "_" + action.lower()
                statements.append("DROP TRIGGER IF EXISTS " + name + ";")
                statements.append("CREATE TRIGGER " + name + " AFTER " + action + " ON " + table + (" WHEN " + content if action == "UPDATE" else "") + " BEGIN " + body + " END;")
            name = "metadata_" + table + "_update"
            statements.append("DROP TRIGGER IF EXISTS " + name + ";")
            statements.append("CREATE TRIGGER " + name + " AFTER UPDATE OF " + field + " ON " + table + " WHEN OLD." + field + " IS NOT NEW." + field + " BEGIN " + bump("metadata_revision") + " END;")
            availability = ("retry_at", "audio", "audio_status") if table == "samples" else ("retry_at",)
            affected = group_splits("UPDATE")
            body = bump("availability_revision") + bump("data_revision")
            if table == "samples":
                body += group_bump("OLD.group_id,NEW.group_id", "OLD.audio_status IS NOT NEW.audio_status")
            for split in ("train", "validation", "guard", "release"):
                body += bump("revision_" + split, "'" + split + "' IN " + affected)
            body += bump("evaluation_revision", "EXISTS(SELECT 1 FROM " + affected + " WHERE split<>'train')")
            name = "availability_" + table + "_update"
            statements.append("DROP TRIGGER IF EXISTS " + name + ";")
            statements.append("CREATE TRIGGER " + name + " AFTER UPDATE OF " + ",".join(availability) + " ON " + table + " WHEN " + changed(availability) + " BEGIN " + body + " END;")
        body = bump("data_revision") + bump("training_revision", "OLD.split='train' OR NEW.split='train'") + bump("evaluation_revision") + group_bump("OLD.id,NEW.id")
        for split in ("train", "validation", "guard", "release"):
            body += bump("revision_" + split, "OLD.split='" + split + "' OR NEW.split='" + split + "'")
        statements.append("DROP TRIGGER IF EXISTS revision_groups_update;")
        statements.append("CREATE TRIGGER revision_groups_update AFTER UPDATE OF split,source_key,origin,provenance ON groups WHEN " + changed(("split", "source_key", "origin", "provenance")) + " BEGIN " + body + " END;")
        name = "revision_sessions_update"
        statements.append("DROP TRIGGER IF EXISTS " + name + ";")
        statements.append("CREATE TRIGGER " + name + " AFTER UPDATE OF prompt,language ON sessions WHEN " + changed(("prompt", "language"))
                          + " BEGIN " + group_bump("OLD.id,NEW.id") + bump("data_revision") + bump("evaluation_revision")
                          + bump("training_revision", "EXISTS(SELECT 1 FROM groups WHERE id IN (OLD.id,NEW.id) AND split='train')") + " END;")
        self.db.executescript("BEGIN IMMEDIATE;\n" + "\n".join(statements) + "\nCOMMIT;")

    def evaluation_snapshot(self, rows):
        rows = tuple(rows)
        pending = {row["group_id"] for row in rows}
        records, seen = [], set()
        def references(value):
            if isinstance(value, dict):
                for key, item in value.items():
                    if key in ("sample", "user_sample", "assistant_sample") and isinstance(item, str):
                        yield item
                    elif key == "samples" and isinstance(item, list):
                        yield from (entry for entry in item if isinstance(entry, str))
                    else:
                        yield from references(item)
            elif isinstance(value, list):
                for item in value:
                    yield from references(item)
        with self.transaction():
            for expected in rows:
                keys = set(expected.keys())
                if "id" not in keys:
                    continue
                pair = "user_sample" in keys
                current = (self.db.execute("SELECT p.*,g.split,g.origin,g.source_key FROM turn_pairs p JOIN groups g ON g.id=p.group_id WHERE p.id=?", (expected["id"],)).fetchone()
                           if pair else self.sample(expected["id"]))
                fields = ("id", "group_id", "user_sample", "assistant_sample", "source", "quality", "verified", "eligible", "evidence", "split", "origin", "source_key") if pair else (
                    "id", "group_id", "role", "task", "digest", "file_sha256", "rate", "count", "generated", "learnable", "memory_eligible", "dialogue_eligible", "audio_status", "created", "metadata", "split", "origin", "source_key")
                for key in fields:
                    if current is None:
                        raise YuanError("评估选中记录已删除 / Selected evaluation record was removed")
                    if key not in keys:
                        continue
                    before, after = expected[key], current[key]
                    if key in ("metadata", "evidence"):
                        before, after = (self.evidence_metadata(json.loads(value)) for value in (before, after))
                    if before != after:
                        raise YuanError("评估选中记录已修订 / Selected evaluation record was revised")
            while pending:
                group_id = min(pending)
                pending.remove(group_id)
                if group_id in seen:
                    continue
                seen.add(group_id)
                group = self.db.execute("SELECT g.id,g.split,g.origin,g.source_key,g.provenance,COALESCE(r.revision,0) AS revision FROM groups g LEFT JOIN evaluation_group_revisions r ON r.group_id=g.id WHERE g.id=?", (group_id,)).fetchone()
                if group is None:
                    raise YuanError("评估来源已删除 / Evaluation source was removed")
                samples = []
                for row in self.db.execute("SELECT id,group_id,role,task,digest,file_sha256,rate,count,generated,learnable,memory_eligible,dialogue_eligible,audio_status,created,metadata FROM samples WHERE group_id=? ORDER BY id", (group_id,)):
                    item = dict(row)
                    item["metadata"] = self.evidence_metadata(json.loads(item["metadata"]))
                    samples.append(payload_digest(item))
                pairs = []
                for row in self.db.execute("SELECT id,group_id,user_sample,assistant_sample,source,quality,verified,eligible,evidence FROM turn_pairs WHERE group_id=? ORDER BY id", (group_id,)):
                    item = dict(row)
                    item["evidence"] = self.evidence_metadata(json.loads(item["evidence"]))
                    pairs.append(payload_digest(item))
                    for sample_id in references(item):
                        dependency = self.db.execute("SELECT group_id FROM samples WHERE id=?", (sample_id,)).fetchone()
                        if dependency is None:
                            raise YuanError("评估引用音频缺失 / Referenced evaluation audio is missing")
                        if dependency[0] not in seen:
                            pending.add(dependency[0])
                session = self.db.execute("SELECT prompt,language FROM sessions WHERE id=?", (group_id,)).fetchone()
                records.append({"id": group_id, "sha256": payload_digest([dict(group), samples, pairs, dict(session) if session else None])})
            self.assert_independent(sorted(seen))
        value = {"protocol": "yuan-evaluation-snapshot-v1", "groups": sorted(records, key=lambda item: item["id"])}
        return {**value, "sha256": payload_digest(value)}

    def snapshot_valid(self, snapshot):
        try:
            if (not isinstance(snapshot, dict) or snapshot.get("protocol") != "yuan-evaluation-snapshot-v1"
                    or not snapshot.get("groups")
                    or snapshot.get("sha256") != payload_digest({key: value for key, value in snapshot.items() if key != "sha256"})):
                return False
            current = self.evaluation_snapshot([{"group_id": item["id"]} for item in snapshot["groups"]])
            return current == snapshot
        except (KeyError, TypeError, ValueError, YuanError):
            return False

    def validation_current(self, record):
        return (isinstance(record, dict) and record.get("training_revision") == self.setting("training_revision")
                and self.snapshot_valid(record.get("evaluation_snapshot")))

    def revisions(self):
        keys = ("data_revision", "training_revision", "training_addition_revision", "evaluation_revision", "availability_revision", "metadata_revision", "revision_train", "revision_validation", "revision_guard", "revision_release")
        rows = dict(self.db.execute("SELECT key,value FROM settings WHERE key IN (" + ",".join("?" for _ in keys) + ")", keys).fetchall())
        return {key: json.loads(rows[key]) if key in rows else None for key in keys}

    @staticmethod
    def context_reason(metadata, eligible=True, generated=False):
        if generated:
            if metadata.get("actually_played") is not True:
                return "not_heard"
            for key in ("capture_gap", "discontinuous"):
                if metadata.get(key):
                    return key
            return ""
        for key in ("capture_gap", "discontinuous", "input_incomplete"):
            if metadata.get(key):
                return key
        if metadata.get("playback_overlap"):
            quality = metadata.get("capture_quality", {})
            if not isinstance(quality, dict) or quality.get("protocol") != "yuan-capture-quality-v1":
                return "overlap_unverified"
            if quality.get("reference_complete") is not True or quality.get("residual_clean") is not True or quality.get("user_speech") is not True:
                return "overlap_unverified"
            return ""
        return "" if eligible else "capture_quality"




def owned_release_preflight(state, emit):
    state = Path(state)
    previous = read_json(state / "owned-release.json")
    try:
        path, value, embedded = release_source(state)
        if value is not None:
            source = value.get("source")
            if (value.get("format") != "yuan-owned-release-source-v2" or value.get("owner") != APP_NAME
                    or not is_digest(value.get("sha256")) or not isinstance(source, str) or not source.strip()):
                raise YuanError("自有模型来源配置无效 / Invalid owned model source configuration")
            if value.get("build_sha256") != build_digest():
                raise YuanError("自有模型与执行代码不匹配 / Owned model and executable code do not match")
            parsed = urllib.parse.urlparse(source)
            if parsed.scheme:
                if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.password:
                    raise YuanError("自有模型只接受受控 HTTPS 来源 / Owned models require a controlled HTTPS source")
            elif embedded:
                if not isinstance(EMBEDDED_RELEASE.get("bundle"), str) or not EMBEDDED_RELEASE["bundle"]:
                    raise YuanError("内置已验收模型资产缺失 / Embedded accepted-model assets are missing")
            else:
                archive = safe_path(path.parent, source)
                reusable = any(record.get("bundle_sha256") == value["sha256"] and is_digest(record.get("manifest_sha256")) for record in (previous, read_json(state / "owned-release-pending.json")))
                if not archive.is_file() and not reusable:
                    raise YuanError("自有模型交付包不存在 / Owned model delivery package is missing")
            ReleaseTrust(state).keys()
            emit("deployment_preflight", key="owned_source_found", source_configured=True, accepted=False, embedded=embedded)
            return True
        if previous.get("directory") and is_digest(previous.get("manifest_sha256")):
            root = safe_path(state, previous["directory"])
            if not root.is_dir() or not safe_path(root, "release-manifest.json").is_file():
                raise YuanError("已安装自有模型清单缺失 / Installed owned-model manifest is missing")
            ReleaseTrust(state).keys()
            emit("deployment_preflight", key="owned_source_found", source_configured=True, accepted=False)
            return True
        emit("deployment_preflight", key="owned_source_absent", source_configured=False, accepted=False, automatic=True, blocker="accepted_owned_assets_missing")
        return False
    except YuanFault:
        raise
    except (OSError, ValueError, TypeError, YuanError) as exc:
        emit("deployment_preflight", key="owned_source_invalid", source_configured=False, accepted=False, reason=concise_error(exc))
        raise YuanFault(concise_error(exc), category="configuration", code="owned_source_invalid", stage="stage_owned_release") from exc

class ReleaseTrust:
    def __init__(self, state):
        self.state = Path(state).resolve()

    @staticmethod
    def canonical(payload):
        return json.dumps({key: value for key, value in payload.items() if key != "signature"}, ensure_ascii=False,
                          sort_keys=True, allow_nan=False, separators=(",", ":")).encode("utf-8")

    def keys(self):
        locations = (Path(__file__).resolve().with_name("Yuan.trust.json"), self.state.parent / "Yuan.trust.json")
        path = next((path for path in locations if path.is_file() and not path.is_symlink()), None)
        if EMBEDDED_RELEASE:
            data = EMBEDDED_RELEASE.get("trust", {})
        elif path is not None:
            data = checked_json(path)
        else:
            raise YuanError("缺少内置信任密钥或开发端发布身份 / Embedded trust key or publisher identity is missing")
        keys = data.get("keys")
        if data.get("format") != "yuan-release-trust-v1" or not isinstance(keys, dict) or not keys:
            raise YuanError("发布信任配置无效 / Invalid publisher trust configuration")
        for identifier, value in keys.items():
            if not is_digest(value) or hashlib.sha256(bytes.fromhex(value)).hexdigest() != identifier:
                raise YuanError("发布信任密钥标识不匹配 / Publisher trust key identity mismatch")
        return keys

    def verify(self, payload):
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PublicKey
        from cryptography.exceptions import InvalidSignature
        signature = payload.get("signature", {})
        if not isinstance(signature, dict) or signature.get("algorithm") != "Ed25519":
            raise YuanError("自有模型交付缺少可信签名 / Owned model delivery lacks a trusted signature")
        keys = self.keys()
        public = keys.get(signature.get("key_id"))
        value = signature.get("value")
        if public is None or not isinstance(value, str) or re.fullmatch(r"[0-9a-f]{128}", value) is None:
            raise YuanError("签名密钥不受信任或签名格式无效 / Untrusted signing key or invalid signature encoding")
        try:
            Ed25519PublicKey.from_public_bytes(bytes.fromhex(public)).verify(bytes.fromhex(value), self.canonical(payload))
        except (ValueError, TypeError, InvalidSignature) as exc:
            raise YuanError("自有模型签名校验失败 / Owned model signature validation failed") from exc
        return signature["key_id"]

    def signing_key(self):
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
        path = safe_path(self.state, "publisher/release-signing.pem")
        if not path.is_file() or path.is_symlink():
            raise YuanError("开发端发布签名密钥缺失 / Publisher signing key is missing")
        if os.name != "nt" and path.stat().st_mode & 0o077:
            raise YuanError("发布私钥访问权限过宽 / Publisher private-key permissions are too broad")
        key = serialization.load_pem_private_key(path.read_bytes(), password=None)
        if not isinstance(key, Ed25519PrivateKey):
            raise YuanError("发布签名密钥类型无效 / Invalid publisher signing-key type")
        return key

    def sign(self, payload):
        from cryptography.hazmat.primitives import serialization
        key = self.signing_key()
        public = key.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
        identifier = hashlib.sha256(public).hexdigest()
        if self.keys().get(identifier) != public.hex():
            raise YuanError("签名私钥与独立信任配置不匹配 / Signing key does not match the independent trust configuration")
        result = {name: value for name, value in payload.items() if name != "signature"}
        result["signature"] = {"algorithm": "Ed25519", "key_id": identifier, "value": key.sign(self.canonical(result)).hex()}
        self.verify(result)
        return result

    def initialize_publisher(self):
        from cryptography.hazmat.primitives import serialization
        from cryptography.hazmat.primitives.asymmetric.ed25519 import Ed25519PrivateKey
        path = safe_path(self.state, "publisher/release-signing.pem")
        trust = self.state.parent / "Yuan.trust.json"
        if path.exists() or trust.exists():
            raise YuanError("已有发布身份不会被覆盖 / Existing publisher identity will not be overwritten")
        path.parent.mkdir(parents=True, exist_ok=True)
        if os.name != "nt":
            path.parent.chmod(0o700)
        key = Ed25519PrivateKey.generate()
        public = key.public_key().public_bytes(serialization.Encoding.Raw, serialization.PublicFormat.Raw)
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(descriptor, "wb") as stream:
            stream.write(key.private_bytes(serialization.Encoding.PEM, serialization.PrivateFormat.PKCS8, serialization.NoEncryption()))
            stream.flush()
            os.fsync(stream.fileno())
        atomic_json(trust, {"format": "yuan-release-trust-v1", "keys": {hashlib.sha256(public).hexdigest(): public.hex()}})
        return trust

class OwnedReleaseInstaller:
    def __init__(self, state, emit):
        self.state, self.emit = Path(state), emit
        self.policy = AdaptivePolicy(state)
        self.pointer = safe_path(state, "owned-release.json")

    def _manifest(self, root, cancel, expected=None):
        path = safe_path(root, "release-manifest.json")
        if expected is not None and digest_file(path, cancel) != expected:
            raise YuanError("自有模型清单摘要不匹配 / Owned model manifest digest mismatch")
        manifest = checked_json(path)
        ReleaseTrust(self.state).verify(manifest)
        provenance = manifest.get("provenance", {})
        if (manifest.get("format") != "yuan-owned-release-v3" or provenance.get("owner") != APP_NAME
                or provenance.get("self_trained") is not True or provenance.get("external_model") is not False
                or provenance.get("text_to_speech") is not False or manifest.get("evaluator_sha256") != behavior_digest()):
            raise YuanError("自有模型来源声明或验收程序不匹配 / Owned model provenance declaration or evaluator mismatch")
        if manifest.get("build_sha256") != build_digest():
            raise YuanError("代码与自有模型交付版本不一致，请由发布端重新验收并导出配套包 / Code and owned model delivery differ; the publisher must revalidate and export a matching bundle")
        files = manifest.get("files")
        if not isinstance(files, dict) or not files or not all(isinstance(name, str) and is_digest(checksum) for name, checksum in files.items()):
            raise YuanError("自有模型文件清单无效 / Invalid owned model file manifest")
        if not {"learning/model.json", "learning/release.json", "learning/training-provenance.json", "learning/acceptance-policy.json"}.issubset(files):
            raise YuanError("自有模型缺少结构或验收记录 / Owned model lacks configuration or acceptance records")
        for name, checksum in files.items():
            check(cancel)
            path = safe_path(root, name)
            if path.is_symlink() or not path.is_file() or digest_file(path, cancel) != checksum:
                raise YuanError("自有模型文件校验失败 / Owned model file validation failed: " + name)
        provenance_record = checked_json(safe_path(root, "learning/training-provenance.json"))
        if (provenance_record.get("format") != "yuan-training-provenance-v1" or provenance_record.get("identity") != manifest.get("identity")
                or provenance_record.get("owner") != APP_NAME or provenance_record.get("external_model") is not False
                or not isinstance(provenance_record.get("steps"), int) or provenance_record["steps"] <= 0
                or not is_digest(provenance_record.get("lineage_sha256"))):
            raise YuanError("自有模型训练来源记录不完整 / Owned model training provenance is incomplete")
        review = checked_json(safe_path(root, "learning/release.json"))
        evaluation_name = review.get("evaluation_file")
        if not isinstance(evaluation_name, str) or "learning/" + evaluation_name not in files:
            raise YuanError("验收结果不在签名清单中 / Acceptance result is absent from the signed manifest")
        evaluation = checked_json(safe_path(root, "learning/" + evaluation_name))
        model = evaluation.get("model", {})
        if provenance_record.get("model_sha256") != model.get("sha256") or provenance_record["steps"] != model.get("steps") or "learning/" + str(model.get("file")) not in files:
            raise YuanError("训练来源记录与验收模型不一致 / Training provenance does not match the accepted model")
        for case in evaluation.get("cases", []):
            if any("learning/" + str(case.get(field + "_file")) not in files for field in ("input", "output")):
                raise YuanError("听测音频不在签名清单中 / Listening audio is absent from the signed manifest")
        return manifest

    def _extract(self, archive, root, cancel):
        import psutil
        free = StorageBudget(self.state).snapshot()["available_bytes"]
        budget = self.policy.integer("deployment", "bundle_unpacked_bytes", free // 3, 1, max(1, free))
        entries = self.policy.integer("deployment", "bundle_file_limit", 4096, 1, 1048576)
        manifest_limit = self.policy.integer("deployment", "manifest_bytes", min(4 * 1024 * 1024, psutil.virtual_memory().available // 16), 1, max(1, psutil.virtual_memory().available // 8))
        with zipfile.ZipFile(archive) as bundle:
            items = bundle.infolist()
            if len(items) > entries or sum(item.file_size for item in items) > budget:
                raise YuanError("自有模型包超过解包预算 / Owned model package exceeds extraction budget")
            names = set()
            file_items = {}
            for item in items:
                check(cancel)
                name = item.filename.rstrip("/")
                path = safe_path(root, name)
                if name != path.relative_to(root).as_posix() or stat.S_ISLNK(item.external_attr >> 16) or name.casefold() in names or item.flag_bits & 1:
                    raise YuanError("模型包包含不安全路径、链接或重复项 / Model package contains an unsafe path, link or duplicate")
                names.add(name.casefold())
                if item.is_dir():
                    if name.split("/")[0] not in ("learning", "datasets"):
                        raise YuanError("模型包目录无效 / Invalid model package directory")
                    continue
                if name != "release-manifest.json" and (name.split("/")[0] not in ("learning", "datasets") or path.suffix.lower() not in (".json", ".pt", ".flac", ".wav", ".ogg", ".opus", ".mp3", ".aif", ".aiff")):
                    raise YuanError("模型包包含非运行资产 / Model package contains an unsupported asset")
                file_items[name] = item
            info = file_items.get("release-manifest.json")
            if info is None or info.file_size > manifest_limit:
                raise YuanError("自有模型清单缺失或过大 / Owned model manifest is missing or too large")
            manifest = json.loads(bundle.read(info))
            if not isinstance(manifest, dict):
                raise YuanError("模型包清单无效 / Invalid model package manifest")
            ReleaseTrust(self.state).verify(manifest)
            files = manifest.get("files", {})
            if not isinstance(files, dict) or set(files) != set(file_items) - {"release-manifest.json"}:
                raise YuanError("模型包文件与清单不一致 / Model package files do not match its manifest")
            for name, item in file_items.items():
                check(cancel)
                path = safe_path(root, name)
                path.parent.mkdir(parents=True, exist_ok=True)
                written = 0
                checksum = hashlib.sha256()
                with bundle.open(item) as incoming, path.open("xb") as outgoing:
                    while True:
                        check(cancel)
                        block = incoming.read(min(1024 * 1024, budget + 1))
                        if not block:
                            break
                        written += len(block)
                        if written > item.file_size or written > budget:
                            raise YuanError("模型包解压大小不匹配 / Model package extraction size mismatch")
                        checksum.update(block)
                        outgoing.write(block)
                    outgoing.flush()
                    os.fsync(outgoing.fileno())
                if written != item.file_size or name in files and checksum.hexdigest() != files[name]:
                    raise YuanError("模型包资产摘要不匹配 / Model package asset digest mismatch")
        return self._manifest(root, cancel)

    def _import(self, root, cancel):
        import numpy as np
        configuration = checked_json(safe_path(root, "learning/model.json"))
        limits = {"rate": 96000, "hop": 96000, "width": 512, "layers": 8}
        for key, default in limits.items():
            value = configuration.get(key)
            maximum = self.policy.integer("deployment", key + "_limit", default, 1, max(default, default * 4))
            if isinstance(value, bool) or not isinstance(value, int) or not 0 < value <= maximum:
                raise YuanError("自有模型结构超过执行边界 / Owned model configuration exceeds execution bounds")
        if configuration["hop"] > configuration["rate"]:
            raise YuanError("自有模型帧长度无效 / Invalid owned model frame length")
        normalizer = types.SimpleNamespace(np=np, rate=configuration["rate"], layers=configuration["layers"])
        normalizer.normalize = lambda audio, rate: NativeAudio.normalize(normalizer, audio, rate)
        self._manifest(root, cancel)
        ensure_workspace_identity(root, verified_assets=True)
        store = AudioStore(root, recover=False)
        try:
            importer = DatasetImporter(root, store, normalizer, self.emit, namespace="owned")
            while importer.step(cancel):
                check(cancel)
            manifests = list(safe_path(root, "datasets").glob("*.json"))
            if not manifests or any(store.setting(importer.identity_key(path, checked_json(path))) != digest_file(path, cancel) for path in manifests):
                raise YuanError("自有模型听测数据未完整导入 / Owned model listening data was not completely imported")
        finally:
            store.close()

    def prepare(self, cancel):
        self.state.mkdir(parents=True, exist_ok=True)
        descriptor_path, descriptor, embedded = release_source(self.state)
        previous = read_json(self.pointer)
        if descriptor is None:
            if previous.get("directory") and is_digest(previous.get("manifest_sha256")):
                root = safe_path(self.state, previous["directory"])
                self._manifest(root, cancel, previous["manifest_sha256"])
                self._import(root, cancel)
                return root
            self.emit("deployment", key="owned_source_absent", source_configured=False, model_supplied=False, automatic=True, blocker="accepted_owned_assets_missing")
            return None
        if (descriptor.get("format") != "yuan-owned-release-source-v2" or descriptor.get("owner") != APP_NAME
                or not is_digest(descriptor.get("sha256")) or not isinstance(descriptor.get("source"), str)):
            raise YuanError("自有模型交付来源配置无效 / Invalid owned model delivery source configuration")
        ReleaseTrust(self.state).verify(descriptor)
        if descriptor.get("build_sha256") != build_digest():
            raise YuanError("自有模型与执行代码不匹配 / Owned model and executable code do not match")
        checksum = descriptor["sha256"]
        root = safe_path(self.state, "owned-releases/" + checksum)
        pending = read_json(safe_path(self.state, "owned-release-pending.json"), {})
        if pending.get("bundle_sha256") == checksum:
            previous = pending
        if root.is_dir() and previous.get("bundle_sha256") == checksum and is_digest(previous.get("manifest_sha256")):
            self._manifest(root, cancel, previous["manifest_sha256"])
            self._import(root, cancel)
            return root
        self.emit("deployment", key="owned_release_installing", source_configured=True, bundle_sha256=checksum)
        archive = safe_path(self.state, "owned-release-downloads/" + checksum + ".zip")
        archive.parent.mkdir(parents=True, exist_ok=True)
        source = descriptor["source"]
        if urllib.parse.urlparse(source).scheme:
            parsed = urllib.parse.urlparse(source)
            if parsed.scheme != "https" or not parsed.hostname or parsed.username or parsed.password:
                raise YuanError("自有模型只接受受控 HTTPS 来源 / Owned models require a controlled HTTPS source")
            Network(cancel, self.policy).download(source, archive, expected_hash=checksum, max_bytes=max(1, StorageBudget(self.state).snapshot()["available_bytes"] // 3),
                                                progress=lambda done, total: self.emit("source_progress", component="owned_release", current=done, total=total))
        elif embedded:
            self.unpack_embedded(archive, checksum, cancel)
        else:
            source_path = safe_path(descriptor_path.parent, source)
            if source_path.is_symlink() or digest_file(source_path, cancel) != checksum:
                raise YuanError("自有模型交付包摘要不匹配 / Owned model delivery package digest mismatch")
            archive = source_path
        if digest_file(archive, cancel) != checksum:
            raise YuanError("自有模型交付包校验失败 / Owned model delivery package verification failed")
        root.parent.mkdir(parents=True, exist_ok=True)
        staging = Path(tempfile.mkdtemp(dir=root.parent, prefix=".install-"))
        try:
            self._extract(archive, staging, cancel)
            self._import(staging, cancel)
            check(cancel)
            if root.exists():
                shutil.rmtree(root)
            os.replace(staging, root)
            sync_dir(root.parent)
            manifest_sha256 = digest_file(root / "release-manifest.json", cancel)
            atomic_json(safe_path(self.state, "owned-release-pending.json"), {"directory": root.relative_to(self.state).as_posix(), "bundle_sha256": checksum,
                                       "manifest_sha256": manifest_sha256, "source_config_sha256": payload_digest(descriptor)}, cancel)
            self.emit("deployment", key="owned_release_verifying", model_supplied=True, bundle_sha256=checksum)
            return root
        finally:
            if staging.exists():
                shutil.rmtree(staging, ignore_errors=True)

    def activate(self, root, model, cancel):
        root = Path(root).resolve()
        if not model.playback_ready or not model.dialogue_ready or Path(model.release_root).resolve() != root:
            raise YuanError("未通过验收的交付不能激活 / An unaccepted delivery cannot be activated")
        pending_path = safe_path(self.state, "owned-release-pending.json")
        pending = read_json(pending_path, {})
        if pending.get("directory") != root.relative_to(self.state).as_posix():
            previous = read_json(self.pointer, {})
            if previous.get("directory") == root.relative_to(self.state).as_posix():
                return
            raise YuanError("交付激活指针不匹配 / Delivery activation pointer mismatch")
        self._manifest(root, cancel, pending.get("manifest_sha256"))
        previous = read_json(self.pointer, {})
        if previous.get("directory") and previous.get("directory") != pending["directory"]:
            pending["previous"] = {key: previous[key] for key in ("directory", "manifest_sha256", "bundle_sha256") if key in previous}
        pending["serving_model"] = model.serving_digest
        local_review = safe_path(self.state, "learning/release.json")
        if local_review.is_file():
            pending["superseded_local_review_sha256"] = digest_file(local_review, cancel)
        pending["activated_at"] = time.time()
        atomic_json(self.pointer, pending, cancel)
        try:
            pending_path.unlink(missing_ok=True)
            archive = safe_path(self.state, "owned-release-downloads/" + pending["bundle_sha256"] + ".zip")
            archive.unlink(missing_ok=True)
        except OSError as exc:
            self.emit("notice", key="storage_cleanup", reason=concise_error(exc), serving_preserved=True)
        self.emit("deployment", key="release_loaded", model_supplied=True, conversation_verified=True, serving_digest=model.serving_digest)

    def export(self, model, cancel):
        if not model.refresh_release() or not model.playback_ready:
            raise YuanError("只有已验收的自有模型可以交付 / Only an accepted owned model can be delivered")
        ReleaseTrust(self.state).signing_key()
        root = getattr(model, "release_root", model.state)
        learning = safe_path(root, "learning")
        review = checked_json(learning / "release.json")
        evaluation = checked_json(safe_path(learning, review["evaluation_file"]))
        training = evaluation["model"].get("training_provenance", {})
        if (training.get("owner") != APP_NAME or training.get("self_trained") is not True or training.get("external_model") is not False
                or not is_digest(training.get("lineage_sha256")) or evaluation["model"].get("steps", 0) <= 0):
            raise YuanError("缺少可绑定到当前模型的自有训练记录 / Owned training records bound to this model are missing")
        provenance = {"format": "yuan-training-provenance-v1", "identity": model.identity(), "model_sha256": model.serving_digest,
                      "steps": evaluation["model"]["steps"], **training}
        atomic_json(learning / "training-provenance.json", provenance, cancel)
        files = {"learning/model.json", "learning/release.json", "learning/training-provenance.json", "learning/acceptance-policy.json",
                 "learning/" + review["evaluation_file"], "learning/" + evaluation["model"]["file"]}
        recordings = {case["recording_id"] for case in evaluation["cases"]}
        if review.get("automatic"):
            descriptor = review["automatic"]
            audit = checked_json(safe_path(learning, descriptor["audit_file"]))
            if descriptor.get("protocol") != "yuan-independent-task-release-v1":
                raise YuanError("自动交付缺少可复验的任务证据 / Automatic delivery lacks reproducible task evidence")
            files.update(("learning/" + descriptor["audit_file"], "learning/" + audit["verifier"]["file"]))
            for result in audit["cases"]:
                files.update("learning/" + item["file"] for item in result["controls"].values())
        for case in evaluation["cases"]:
            files.update("learning/" + case[field + "_file"] for field in ("input", "output"))
        sources = {name: safe_path(root, name) for name in files}
        found = set()
        splits = set()
        dataset_roots = {Path(value).resolve() for value in (root, model.state, model.owned_root) if value is not None}
        for dataset_root in sorted(dataset_roots):
            datasets = safe_path(dataset_root, "datasets")
            for path in sorted(datasets.glob("*.json")):
                data = checked_json(path)
                splits.add(data.get("split"))
                if data.get("recording_id") in recordings:
                    if data.get("split") != "release":
                        raise YuanError("交付听测数据必须显式划分为发布留出集 / Delivery listening datasets must explicitly use the release split")
                    found.add(data["recording_id"])
                assets = {"datasets/" + path.name: path}
                for turn in data["turns"]:
                    asset = safe_path(datasets, turn["audio"])
                    assets["datasets/" + asset.relative_to(datasets).as_posix()] = asset
                for name, asset in assets.items():
                    if name in sources and digest_file(sources[name], cancel) != digest_file(asset, cancel):
                        raise YuanError("不同来源的数据集文件名发生冲突 / Dataset filenames conflict across sources")
                    sources[name] = asset
        if found != recordings:
            raise YuanError("交付缺少可重建的原始听测数据 / Delivery lacks reconstructable original listening data")
        files = set(sources)
        mapping = {name: digest_file(sources[name], cancel) for name in sorted(files)}
        manifest = {"format": "yuan-owned-release-v3", "provenance": {"owner": APP_NAME, "self_trained": True, "external_model": False, "text_to_speech": False},
                    "evaluator_sha256": behavior_digest(), "build_sha256": build_digest(), "identity": model.identity(), "files": mapping}
        if not {"train", "validation", "guard", "release"}.issubset(splits):
            raise YuanError("交付包需要训练、验证、保护与发布留出数据 / Delivery requires training, validation, guard and release-held-out data")
        manifest = ReleaseTrust(self.state).sign(manifest)
        directory = safe_path(self.state, "exports/" + model.serving_digest)
        directory.mkdir(parents=True, exist_ok=True)
        target = directory / "Yuan.release.zip"
        temporary = target.with_suffix(".partial")
        try:
            with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                archive.writestr("release-manifest.json", json.dumps(manifest, ensure_ascii=False, allow_nan=False, separators=(",", ":")))
                for name in sorted(files):
                    check(cancel)
                    path = sources[name]
                    archive.write(path, name)
                    if digest_file(path, cancel) != mapping[name]:
                        raise YuanError("交付期间资产发生变化 / An asset changed during delivery export")
            with temporary.open("rb") as stream:
                os.fsync(stream.fileno())
            os.replace(temporary, target)
            descriptor = ReleaseTrust(self.state).sign({"format": "yuan-owned-release-source-v2", "owner": APP_NAME,
                                                       "source": target.name, "sha256": digest_file(target, cancel),
                                                       "build_sha256": build_digest()})
            payload = {"format": "yuan-embedded-release-v1", "descriptor": descriptor,
                       "trust": {"format": "yuan-release-trust-v1", "keys": ReleaseTrust(self.state).keys()},
                       "bundle": base64.b64encode(target.read_bytes()).decode("ascii")}
            source = embedded_source_text(payload)
            delivered = directory / "Yuan.zip"
            delivery_temp = delivered.with_suffix(".partial")
            try:
                with zipfile.ZipFile(delivery_temp, "w", compression=zipfile.ZIP_DEFLATED) as output:
                    output.writestr("Yuan.py", source.encode("utf-8"))
                with zipfile.ZipFile(delivery_temp) as output:
                    if output.namelist() != ["Yuan.py"] or build_digest(output.read("Yuan.py").decode("utf-8")) != build_digest():
                        raise YuanError("单文件交付校验失败 / Single-file delivery validation failed")
                with delivery_temp.open("rb") as stream:
                    os.fsync(stream.fileno())
                os.replace(delivery_temp, delivered)
                sync_dir(directory)
            finally:
                delivery_temp.unlink(missing_ok=True)
            target.unlink(missing_ok=True)
            target = delivered
        finally:
            temporary.unlink(missing_ok=True)
        self.emit("notice", key="owned_release_exported", directory=str(directory), model=model.serving_digest, reason=str(directory))
        return target

    def unpack_embedded(self, target, checksum, cancel):
        payload = EMBEDDED_RELEASE.get("bundle")
        if not isinstance(payload, str) or not payload:
            raise YuanError("内置自有模型资产缺失 / Embedded owned-model assets are missing")
        if target.is_file() and digest_file(target, cancel) == checksum:
            return
        expected = (len(payload) // 4) * 3 - (len(payload) - len(payload.rstrip("=")))
        if expected <= 0 or len(payload) % 4:
            raise YuanError("内置自有模型编码无效 / Invalid embedded owned-model encoding")
        temporary = target.with_suffix(".partial")
        try:
            with StorageBudget(self.state).reserve(expected, "embedded_release"):
                digest = hashlib.sha256()
                with temporary.open("wb") as outgoing:
                    for offset in range(0, len(payload), 1024 * 1024):
                        check(cancel)
                        block = base64.b64decode(payload[offset:offset + 1024 * 1024], validate=True)
                        digest.update(block)
                        outgoing.write(block)
                        self.emit("source_progress", component="owned_release", current=min(expected, outgoing.tell()), total=expected)
                    outgoing.flush()
                    os.fsync(outgoing.fileno())
                if temporary.stat().st_size != expected or digest.hexdigest() != checksum:
                    raise YuanError("内置自有模型资产校验失败 / Embedded owned-model assets failed verification")
                check(cancel)
                os.replace(temporary, target)
                sync_dir(target.parent)
        finally:
            temporary.unlink(missing_ok=True)


class AudioSequence:
    def __init__(self, count, reader):
        if isinstance(count, bool) or not isinstance(count, int) or count <= 0 or not callable(reader):
            raise ValueError("音频序列无效 / Invalid audio sequence")
        self.count, self.reader = count, reader

    def __len__(self):
        return self.count

    def blocks(self, size, cancel=None):
        import numpy as np
        size = max(1, int(size))
        for start in range(0, self.count, size):
            check(cancel)
            count = min(size, self.count - start)
            values = np.asarray(self.reader(start, count), dtype=np.float32)
            if values.ndim != 1 or len(values) != count or not np.isfinite(values).all():
                raise InvalidAudio("音频序列缺失或损坏 / Audio sequence is incomplete or invalid")
            yield values


class AudioEncoding:
    def __init__(self, hidden, pending, condition, encoder=None):
        self.hidden, self.pending, self.condition, self.encoder = hidden, pending, condition, encoder


RUNTIME_MODULES = ("numpy", "torch", "psutil", "certifi", "zstandard", "sounddevice", "soundfile", "soxr", "cryptography", "pyarrow")

class NativeDriver:
    handles = []
    import_lock = threading.RLock()

    def __init__(self, state, emit, cancel):
        self.state, self.emit, self.cancel = Path(state), emit, cancel
        self.root = safe_path(state, "native-audio")
        self.root.mkdir(parents=True, exist_ok=True)
        self.policy = AdaptivePolicy(state)
        self.network = Network(cancel, self.policy)
        self.marker = self.root / "driver.json"

    def load(self, values):
        import ctypes
        paths = []
        for item in values:
            path = safe_path(self.root, item["file"])
            if not path.is_file() or digest_file(path, self.cancel) != item["sha256"]:
                raise YuanError("音频驱动文件校验失败 / Audio driver file verification failed")
            paths.append(path)
        paths.sort(key=lambda path: (not path.name.startswith("libasound"), path.name))
        selected = None
        for path in paths:
            self.handles.append(ctypes.CDLL(str(path), mode=ctypes.RTLD_GLOBAL))
            if path.name.startswith("libportaudio"):
                selected = path
        if selected is None:
            raise YuanError("缺少音频驱动主库 / Audio driver main library is missing")
        return selected

    def package(self, name, subdir):
        catalog = self.network.json("https://api.anaconda.org/package/conda-forge/" + name)
        versions = sorted({value for value in catalog.get("versions", []) if isinstance(value, str) and re.fullmatch(r"[0-9]+(?:\.[0-9]+)*", value)}, key=lambda value: tuple(map(int, value.split("."))), reverse=True)
        libc = platform.libc_ver()[1]
        for version in versions:
            check(self.cancel)
            release = self.network.json("https://api.anaconda.org/release/conda-forge/" + name + "/" + version)
            candidates = []
            for item in release.get("distributions", []):
                attrs, filename, size = item.get("attrs", {}), item.get("basename", ""), item.get("size")
                if (attrs.get("subdir") != subdir or not isinstance(filename, str) or not filename.startswith(subdir + "/")
                        or not filename.endswith((".conda", ".tar.bz2")) or not is_digest(item.get("sha256"))
                        or isinstance(size, bool) or not isinstance(size, int) or size <= 0):
                    continue
                glibc = next((value.removeprefix("__glibc ") for value in attrs.get("depends", []) if value.startswith("__glibc ")), None)
                if glibc and libc and not compatible_python(glibc.replace(".a0", ""), tuple(map(int, libc.split("."))) + (0,)):
                    continue
                candidates.append(item)
            if candidates:
                return max(candidates, key=lambda item: (int(item["attrs"].get("build_number", 0)), str(item.get("upload_time", ""))))
        raise YuanFault("没有可校验的兼容音频驱动 / No verifiable compatible audio driver is available", category="compatibility", code="native_audio_unavailable")

    def extract(self, path, names, maximum):
        import tarfile
        import zstandard
        output = []
        with zipfile.ZipFile(path) if path.suffix == ".conda" else nullcontext() as archive:
            entries = [item for item in archive.infolist() if item.filename.startswith("pkg-") and item.filename.endswith(".tar.zst")] if archive else [None]
            if len(entries) != 1:
                raise InvalidDownload("音频驱动归档结构无效 / Invalid audio driver archive layout")
            with archive.open(entries[0]) if archive else path.open("rb") as raw:
                with zstandard.ZstdDecompressor().stream_reader(raw) if archive else nullcontext(raw) as source:
                    with tarfile.open(fileobj=source, mode="r|" if archive else "r|bz2") as stream:
                        total = 0
                        for member in stream:
                            check(self.cancel)
                            relative = Path(member.name)
                            if (not member.isfile() or relative.parent != Path("lib")
                                    or not any(re.fullmatch(re.escape(name) + r"\.so(?:\.[0-9]+)*", relative.name) for name in names)):
                                continue
                            total += member.size
                            if member.size <= 0 or total > maximum:
                                raise InvalidDownload("音频驱动解压超过存储预算 / Audio driver extraction exceeds its storage budget")
                            target = safe_path(self.root, relative.name)
                            temporary = target.with_suffix(target.suffix + ".partial")
                            try:
                                with stream.extractfile(member) as data, temporary.open("wb") as destination:
                                    copied = 0
                                    while copied < member.size:
                                        check(self.cancel)
                                        block = data.read(min(member.size - copied, 1024 * 1024))
                                        if not block:
                                            raise InvalidDownload("音频驱动归档不完整 / Audio driver archive is incomplete")
                                        destination.write(block)
                                        copied += len(block)
                                    destination.flush()
                                    os.fsync(destination.fileno())
                                os.replace(temporary, target)
                                output.append({"file": target.name, "sha256": digest_file(target, self.cancel)})
                            finally:
                                temporary.unlink(missing_ok=True)
        if not output:
            raise InvalidDownload("音频驱动归档没有运行库 / Audio driver archive contains no runtime library")
        return output

    def ensure(self):
        import ctypes.util
        if not sys.platform.startswith("linux") or ctypes.util.find_library("portaudio"):
            return None
        saved = read_json(self.marker)
        if saved.get("libraries"):
            try:
                return self.load(saved["libraries"])
            except (OSError, ValueError, KeyError, TypeError, YuanError):
                pass
        machines = {"x86_64": "linux-64", "amd64": "linux-64", "aarch64": "linux-aarch64", "arm64": "linux-aarch64", "ppc64le": "linux-ppc64le"}
        subdir = machines.get(platform.machine().lower())
        if not subdir:
            raise YuanFault("当前架构没有可用音频驱动 / No audio driver is available for this architecture", category="compatibility", code="native_audio_architecture")
        libraries, packages = [], []
        with operation(self.emit, "stage_native_audio", "runtime"):
            for name, names in (("alsa-lib", ("libasound",)), ("portaudio", ("libportaudio",))):
                item = self.package(name, subdir)
                available = StorageBudget(self.state).snapshot()["available_bytes"]
                maximum = self.policy.integer("runtime", "native_audio_bytes", available // max(2, os.cpu_count() or 1), 1, max(1, available))
                filename = Path(item["basename"]).name
                target = safe_path(self.root, filename)
                url = "https://conda.anaconda.org/conda-forge/" + item["basename"]
                with StorageBudget(self.state).reserve(min(available, item["size"] + maximum)):
                    try:
                        self.network.download(url, target, item["size"], item["sha256"], max_bytes=maximum)
                        libraries.extend(self.extract(target, names, maximum))
                    finally:
                        target.unlink(missing_ok=True)
                packages.append({"file": filename, "sha256": item["sha256"], "license": item["attrs"].get("license"), "source": url})
            selected = self.load(libraries)
            atomic_json(self.marker, {"libraries": libraries, "packages": packages}, self.cancel)
            return selected



def import_runtime_module(name, state, emit, cancel, supervisor, budgets):
    import importlib
    check(cancel)
    key = "stage_import_" + name
    budget = supervisor.budget(key, budgets.get(key))
    stall = supervisor.policy.number("supervision", key + "_stall_seconds", budget, supervisor.minimum, budget)
    with operation(emit, key, "import", budget_seconds=budget, stall_seconds=stall, component=name):
        try:
            if name == "sounddevice":
                import ctypes.util
                with NativeDriver.import_lock:
                    driver = NativeDriver(state, emit, cancel).ensure()
                    original = ctypes.util.find_library
                    try:
                        if driver is not None:
                            ctypes.util.find_library = lambda value: str(driver) if value == "portaudio" else original(value)
                        module = importlib.import_module(name)
                    finally:
                        ctypes.util.find_library = original
            else:
                module = importlib.import_module(name)
            check(cancel)
            emit("dependency_loaded", key="dependency_loaded", component=name, version=str(getattr(module, "__version__", "")))
            return module
        except Cancelled:
            raise
        except BaseException as exc:
            raise YuanFault("运行组件导入失败 / Runtime component import failed", category="integrity" if isinstance(exc, ModuleNotFoundError) else failure_category(exc),
                            code="dependency_import_failed", stage=key, component=name) from exc

def load_runtime_modules(state, emit, cancel=None):
    state = Path(state).resolve()
    identity = os.environ.get("YUAN_IMPORT_IDENTITY")
    supervisor = StageSupervisor(state, emit, identity=identity if is_digest(identity) else None)
    try:
        budgets = json.loads(os.environ.get("YUAN_IMPORT_BUDGETS", "{}"))
    except (ValueError, TypeError):
        budgets = {}
    if not isinstance(budgets, dict):
        budgets = {}
    emit("runtime_profile", python=platform.python_version(), executable=sys.executable, system=platform.system(), machine=platform.machine(),
         cwd=str(Path.cwd()), environment=supervisor.fingerprint, mode="probe" if "--probe" in sys.argv else "engine")
    names = RUNTIME_MODULES if "--probe" in sys.argv else tuple(name for name in RUNTIME_MODULES if name != "pyarrow")
    modules = {name: import_runtime_module(name, state, emit, cancel, supervisor, budgets) for name in names}
    supervisor.policy.save()
    emit("runtime_profile", components={name: str(getattr(module, "__version__", "")) for name, module in modules.items()})
    return modules

class CapabilityEvidence:
    protocol = "yuan-capability-evidence-v2"
    task_scope = "independently_calibrated_annotated_answer_tasks"
    dialogue_scope = "independently_calibrated_recorded_dialogue"
    human_scope = "independent_human_listening"
    checks = {"language_coverage": "understandable", "prompt_following": "follows_prompt", "input_understanding": "relevant_reply", "history_use": "follows_history", "natural_ending": "ends_normally", "audio_stability": "no_abnormal_audio"}
    scenarios = {"follows_prompt": "prompt", "relevant_reply": "input", "follows_history": "history"}

    @classmethod
    def required(cls, case):
        return tuple(key for key in cls.checks.values() if key not in cls.scenarios or cls.scenarios[key] in case.get("scenarios", []))

    @classmethod
    def complete(cls, cases, checks):
        if not isinstance(cases, list) or not cases or not isinstance(checks, list) or len(checks) != len(cases):
            return False
        if any(not isinstance(row, dict) or not isinstance(row.get("id"), str) or not row["id"] for row in [*cases, *checks]):
            return False
        approved = {row["id"]: row for row in checks}
        return len(approved) == len(cases) and len({case["id"] for case in cases}) == len(cases) and set(approved) == {case["id"] for case in cases} and all(all(approved[case["id"]].get(key) is True for key in cls.required(case)) for case in cases)

    @classmethod
    def dialogue_annotation(cls, evidence):
        annotation = evidence.get("dialogue")
        if annotation is None:
            return False
        if (not isinstance(annotation, dict) or annotation.get("method") != "human_multiturn_dialogue_v1"
                or annotation.get("verified") is not True
                or any(not isinstance(annotation.get(key), str) or not annotation[key].strip() for key in ("domain", "reviewer", "annotation_id", "recording_id"))
                or annotation["recording_id"] != evidence.get("recording_id")):
            raise YuanError("多轮对话标注缺少可核验身份 / Multi-turn dialogue annotation lacks a verifiable identity")
        return True

    @classmethod
    def dialogue_reference(cls, evidence):
        return bool(cls.dialogue_annotation(evidence) and evidence.get("method") == "human_audio_annotation"
                    and all(evidence.get("reference_checks", {}).get(key) is True for key in cls.checks.values())
                    and evidence.get("semantic", {}).get("method") == "human_dialogue_answers_v1" and SpeechVerifier.answers(evidence)
                    and all(evidence.get("contrasts", {}).get(dimension, {}).get("semantic", {}).get("method") == "human_dialogue_answers_v1"
                            and SpeechVerifier.answers(evidence, dimension) for dimension in evidence.get("scenarios", [])))

    @classmethod
    def dialogue_case(cls, case, evidence):
        history = case.get("history", [])
        if not cls.dialogue_reference(evidence) or not {"user", "assistant"}.issubset({item.get("role") for item in history}):
            return None
        return {"passed": True, "recording_id": case["recording_id"], "annotation_sha256": payload_digest(evidence["dialogue"]),
                "domain": evidence["dialogue"]["domain"], "history_sha256": payload_digest(history),
                "scope": "recorded_dialogue_benchmark"}

    @classmethod
    def automatic_scope(cls, results):
        return cls.dialogue_scope if results and all(isinstance(item.get("dialogue_evidence"), dict) and item["dialogue_evidence"].get("passed") is True for item in results) else cls.task_scope

    @staticmethod
    def task_checks(result, scope):
        assessment, controls = result["assessment"], result["controls"]
        semantic = assessment.get("semantic_passed") is True
        def contrast(name):
            control = controls.get(name)
            return None if control is None else bool(semantic and control.get("assessment", {}).get("semantic_passed") is True and control["assessment"].get("passed") is True)
        return {"id": result["id"], "understandable": semantic, "follows_prompt": contrast("prompt"), "relevant_reply": contrast("input"),
                "follows_history": contrast("history"), "ends_normally": assessment.get("natural") is True,
                "no_abnormal_audio": assessment.get("quality_passed") is True, "evidence_scope": scope,
                "dialogue_evidence": copy.deepcopy(result.get("dialogue_evidence"))}

    @classmethod
    def build(cls, evaluation, checks, scope):
        cases = evaluation.get("cases", [])
        if not cls.complete(cases, checks):
            raise YuanError("能力证据未逐项通过 / Capability evidence has not passed its individual checks")
        if scope not in (cls.human_scope, cls.task_scope, cls.dialogue_scope):
            raise YuanError("能力证据范围无效 / Invalid capability evidence scope")
        minimum = evaluation.get("minimum_independent_sources")
        if type(minimum) is not int or minimum < 2:
            raise YuanError("能力证据缺少独立来源边界 / Capability evidence lacks independent-source bounds")
        approved = {row["id"]: row for row in checks}
        languages = {}
        for language in AcceptancePolicy.languages:
            selected = [case for case in cases if case.get("language") == language]
            dimensions = {}
            for name, key in cls.checks.items():
                applicable = [case for case in selected if key in cls.required(case)]
                sources = sorted({case["recording_id"] for case in applicable})
                dimensions[name] = {"passed": len(sources) >= minimum and all(approved[case["id"]].get(key) is True for case in applicable),
                                    "cases": [case["id"] for case in applicable], "sources": sources, "scope": scope}
            languages[language] = dimensions
        full = all(item["passed"] for dimensions in languages.values() for item in dimensions.values())
        if scope == cls.dialogue_scope:
            for case in cases:
                item = approved[case["id"]].get("dialogue_evidence")
                if (not isinstance(item, dict) or item.get("passed") is not True or item.get("recording_id") != case["recording_id"]
                        or item.get("scope") != "recorded_dialogue_benchmark" or not is_digest(item.get("annotation_sha256"))
                        or item.get("history_sha256") != payload_digest(case.get("history", []))
                        or not {"user", "assistant"}.issubset({row.get("role") for row in case.get("history", [])})):
                    raise YuanError("自动对话验收缺少独立多轮证据 / Automatic dialogue acceptance lacks independent multi-turn evidence")
        identity = {"protocol": cls.protocol, "model_sha256": evaluation["model"]["sha256"], "dataset_sha256": evaluation["dataset_sha256"],
                    "evaluator_sha256": evaluation["evaluator_sha256"], "build_sha256": evaluation["build_sha256"],
                    "acceptance_policy_sha256": evaluation["acceptance_policy_sha256"], "scope": scope, "languages": languages,
                    "method": "independent_human_listening" if scope == cls.human_scope else "independent_calibrated_audio_verifier",
                    "coverage_scope": "annotated_answer_tasks" if scope == cls.task_scope else "recorded_dialogue_benchmark",
                    "minimum_independent_sources": minimum, "unrestricted_dialogue": False,
                    "final_acceptance_sha256": FinalAcceptance.validate(evaluation)["sha256"],
                    "dialogue_ready": bool(full and scope in (cls.human_scope, cls.dialogue_scope)),
                    "annotated_tasks_ready": bool(full and scope in (cls.task_scope, cls.dialogue_scope))}
        return {**identity, "sha256": payload_digest(identity)}

    @classmethod
    def ready(cls, report, model_sha256=None):
        try:
            if (not isinstance(report, dict) or report.get("protocol") != cls.protocol or report.get("dialogue_ready") is not True
                    or report.get("scope") not in (cls.human_scope, cls.dialogue_scope)
                    or report.get("coverage_scope") != "recorded_dialogue_benchmark"
                    or model_sha256 is not None and report.get("model_sha256") != model_sha256
                    or not is_digest(report.get("model_sha256"))
                    or report.get("sha256") != payload_digest({key: value for key, value in report.items() if key != "sha256"})):
                return False
            minimum = report.get("minimum_independent_sources")
            if type(minimum) is not int or minimum < 2 or set(report.get("languages", {})) != set(AcceptancePolicy.languages):
                return False
            return all(set(dimensions) == set(cls.checks) and all(item.get("passed") is True and len(set(item.get("sources", []))) >= minimum for item in dimensions.values()) for dimensions in report["languages"].values())
        except (TypeError, ValueError, KeyError, AttributeError):
            return False

class FinalAcceptance:
    protocol = "yuan-frozen-final-acceptance-v1"

    @staticmethod
    def verifier_key(verifier):
        if verifier is None or getattr(verifier, "accepted", None) is None or not is_digest(verifier.certificate.get("weights_sha256")):
            return None
        certificate = {key: value for key, value in verifier.certificate.items() if key != "created"}
        return payload_digest({"identity": verifier.identity(), "certificate": certificate})

    @classmethod
    def identity(cls, model, store, policy):
        value = {"candidate_sha256": model.active_digest, "evaluator_sha256": behavior_digest(),
                 "build_sha256": build_digest(), "verifier_sha256": cls.verifier_key(getattr(model, "verifier", None)),
                 "training_revision": store.setting("training_revision"), "acceptance_policy_sha256": policy.digest}
        return {**value, "sha256": payload_digest(value)}

    @classmethod
    def current(cls, model, store, policy):
        identity = cls.identity(model, store, policy)
        return store.db.execute("SELECT * FROM final_acceptance_runs WHERE identity_sha256=?", (identity["sha256"],)).fetchone()

    @classmethod
    def filter_rows(cls, model, store, policy, rows):
        current = cls.current(model, store, policy)
        if current is not None:
            if current["status"] not in ("reserved", "evaluating"):
                return []
            allowed = set(json.loads(current["receipt"])["pair_ids"])
            return [row for row in rows if row["id"] in allowed]
        used = {row[0] for row in store.db.execute("SELECT source FROM final_acceptance_sources")}
        return [row for row in rows if "source:" + row["source_key"] not in used
                and all("audio:" + store.sample(row[key])["digest"] not in used for key in ("user_sample", "assistant_sample"))]

    @classmethod
    def claim(cls, model, store, policy, selected, snapshot):
        identity = cls.identity(model, store, policy)
        if not is_digest(identity["candidate_sha256"]) or not is_digest(identity["verifier_sha256"]):
            raise IneligibleSample("最终验收要求冻结模型与独立验证器 / Final acceptance requires a frozen model and independent verifier")
        keys = set()
        for group in snapshot["groups"]:
            row = store.db.execute("SELECT source_key,split FROM groups WHERE id=?", (group["id"],)).fetchone()
            if row is None or row["split"] != "release":
                raise IneligibleSample("最终验收引用必须来自独立发布划分 / Final acceptance references must belong to the independent release split")
            keys.add("source:" + row["source_key"])
            keys.update("audio:" + row[0] for row in store.db.execute("SELECT digest FROM samples WHERE group_id=? AND generated=0", (group["id"],)))
        value = {"protocol": cls.protocol, "identity": identity, "evaluation_snapshot_sha256": snapshot["sha256"],
                 "pair_ids": sorted(row["id"] for row in selected), "sources": sorted(keys),
                 "purpose": "final_acceptance_only", "training_feedback": False}
        receipt = {**value, "sha256": payload_digest(value)}
        pending = cls.current(model, store, policy)
        if pending is not None and pending["status"] in ("reserved", "evaluating"):
            previous = json.loads(pending["receipt"])
            if previous != receipt or not store.snapshot_valid(snapshot):
                cls.finish(store, previous, "stale")
                raise IneligibleSample("最终验收冻结快照已失效 / Frozen final acceptance snapshot is stale")
        with store.transaction():
            if not store.snapshot_valid(snapshot):
                raise IneligibleSample("最终验收快照已改变 / Final acceptance snapshot changed")
            existing = cls.current(model, store, policy)
            if existing is not None:
                if existing["status"] not in ("reserved", "evaluating") or json.loads(existing["receipt"]) != receipt:
                    raise IneligibleSample("冻结候选已使用最终验收数据 / Frozen candidate has already used final acceptance data")
                return receipt
            for key in keys:
                if store.db.execute("SELECT 1 FROM final_acceptance_sources WHERE source=?", (key,)).fetchone():
                    raise IneligibleSample("最终验收来源已被其他候选使用 / Final acceptance source was used by another candidate")
            store.db.execute("INSERT INTO final_acceptance_runs VALUES(?,?,?,'reserved',?)", (receipt["sha256"], identity["sha256"], json.dumps(receipt, sort_keys=True), time.time()))
            store.db.executemany("INSERT INTO final_acceptance_sources VALUES(?,?)", ((key, receipt["sha256"]) for key in keys))
            store.set_setting("final_acceptance_revision", uuid.uuid4().hex)
        store.coverage_cache.clear()
        return receipt

    @classmethod
    def validate(cls, evaluation):
        receipt = evaluation.get("final_acceptance", {})
        identity = receipt.get("identity", {})
        if (receipt.get("protocol") != cls.protocol or receipt.get("training_feedback") is not False
                or receipt.get("sha256") != payload_digest({key: value for key, value in receipt.items() if key != "sha256"})
                or identity.get("sha256") != payload_digest({key: value for key, value in identity.items() if key != "sha256"})
                or identity.get("candidate_sha256") != evaluation.get("model", {}).get("sha256")
                or any(identity.get(key) != evaluation.get(key) for key in ("evaluator_sha256", "build_sha256", "acceptance_policy_sha256", "training_revision"))
                or receipt.get("evaluation_snapshot_sha256") != evaluation.get("evaluation_snapshot", {}).get("sha256")
                or receipt.get("pair_ids") != sorted(case["pair"] for case in evaluation.get("cases", []))
                or not is_digest(identity.get("verifier_sha256"))):
            raise YuanError("最终验收冻结身份或快照不匹配 / Frozen final acceptance identity or snapshot mismatch")
        return receipt

    @staticmethod
    def finish(store, receipt, status):
        if status not in ("evaluating", "accepted", "rejected", "stale"):
            raise ValueError("Invalid final acceptance state")
        with store.transaction():
            store.db.execute("UPDATE final_acceptance_runs SET status=?,updated=? WHERE id=? AND status IN ('reserved','evaluating')",
                             (status, time.time(), receipt["sha256"]))
            store.set_setting("final_acceptance_revision", uuid.uuid4().hex)
        store.coverage_cache.clear()

class EvaluationEligibility:
    @staticmethod
    def budgets(model):
        import psutil
        capacity = model.capacity()
        reply = model.reply_samples((), ())
        memory = available_resources(psutil)["memory"] // max(2, model.layers + 1)
        per_sample = max(4, math.ceil(model.width * 128 / model.hop))
        verifier = min(capacity, memory // per_sample)
        return {"capacity": capacity, "reply": reply, "verifier": verifier // model.hop * model.hop}

    @classmethod
    def pair(cls, store, model, pair, split, limits=None):
        limits = limits or cls.budgets(model)
        left, right = store.sample(pair["user_sample"]), store.sample(pair["assistant_sample"])
        reasons = set()
        if left is None or right is None:
            return {"ready": False, "reasons": ["missing_audio"], "limits": limits}
        for row in (left, right):
            if row["audio_status"] != "ready" or row["rate"] != model.rate or row["count"] < model.hop or row["generated"]:
                reasons.add("invalid_audio")
        if left["count"] > limits["capacity"]:
            reasons.add("input_budget")
        if split != "train":
            if right["count"] > limits["reply"]:
                reasons.add("reply_budget")
            if right["count"] > limits["verifier"]:
                reasons.add("verifier_budget")
            history = store.db.execute("SELECT * FROM samples WHERE group_id=? AND created<? AND generated=0 AND dialogue_eligible=1 AND audio_status='ready' ORDER BY created,id", (pair["group_id"], left["created"])).fetchall()
            seen, total = {left["digest"], right["digest"]}, 0
            for row in history:
                if row["digest"] not in seen:
                    seen.add(row["digest"])
                    total += row["count"]
                    if row["rate"] != model.rate or AudioStore.context_reason(json.loads(row["metadata"]), generated=False):
                        reasons.add("invalid_history")
            context_limit = max(0, min(limits["capacity"] // 2, limits["capacity"] - left["count"]))
            if total > context_limit:
                reasons.add("history_budget")
            evidence = json.loads(pair["evidence"])
            for dimension, control in evidence.get("contrasts", {}).items():
                identifiers = [control.get("sample")] if dimension == "input" else control.get("samples", []) if dimension == "history" else []
                counts = 0
                for identifier in identifiers:
                    row = store.sample(identifier)
                    if row is None or row["audio_status"] != "ready" or row["generated"] or row["rate"] != model.rate:
                        reasons.add("invalid_control")
                    else:
                        counts += row["count"]
                bound = limits["capacity"] - total if dimension == "input" else context_limit
                if counts > bound:
                    reasons.add("control_budget")
        return {"ready": not reasons, "reasons": sorted(reasons), "limits": limits}

class AcceptancePolicy:
    dimensions = ("prompt", "input", "history")
    reference_checks = ("understandable", "follows_prompt", "relevant_reply", "follows_history", "ends_normally", "no_abnormal_audio")
    languages = ("中文", "English")

    def __init__(self, model):
        root = model.owned_root if model.owned_root is not None else model.state
        self.path = safe_path(root, "learning/acceptance-policy.json")
        if not self.path.exists() and model.owned_root is None:
            source = safe_path(model.state.parent, "Yuan.acceptance.json")
            if os.environ.get("YUAN_PUBLISHER") == "1" and source.is_file():
                data = checked_json(source)
            else:
                data = {"format": "yuan-acceptance-policy-v1", "scenarios": list(self.dimensions),
                        "confidence": model.policy.number("acceptance", "confidence", 0.95, 0.5, 0.999),
                        "maximum_failure_rate": model.policy.number("acceptance", "maximum_failure_rate", 0.05, 0.001, 0.1)}
            self.validate(data)
            atomic_json(self.path, data, model.cancel)
        self.data = checked_json(self.path)
        self.validate(self.data)
        self.confidence = float(self.data["confidence"])
        self.maximum_failure = float(self.data["maximum_failure_rate"])
        self.minimum = max(2, math.ceil(math.log1p(-self.confidence) / math.log1p(-self.maximum_failure)))
        self.digest = payload_digest(self.data)

    @classmethod
    def validate(cls, data):
        if data.get("format") != "yuan-acceptance-policy-v1":
            raise YuanError("缺少开发端验收策略 / Publisher acceptance policy is missing")
        for key in ("confidence", "maximum_failure_rate"):
            value = data.get(key)
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or not 0 < value < 1:
                raise YuanError("验收置信度或风险边界无效 / Invalid acceptance confidence or risk bound")
        for key in ("maximum_relative_regression", "maximum_absolute_regression"):
            value = data.get(key, 0.0)
            if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value < 0:
                raise YuanError("回归容忍边界无效 / Invalid regression tolerance")
        if data["confidence"] <= 0.5:
            raise YuanError("比较置信度必须大于二分之一 / Comparison confidence must exceed one half")
        scenarios = data.get("scenarios")
        if not isinstance(scenarios, list) or set(scenarios) != set(cls.dimensions) or len(scenarios) != len(cls.dimensions):
            raise YuanError("验收必须覆盖提示词、输入与多轮历史 / Acceptance must cover prompt, input and multi-turn history")

    def failure_bound(self, failures, total):
        if type(failures) is not int or type(total) is not int or not 0 <= failures <= total or total < 1:
            raise ValueError("失败计数无效 / Invalid failure count")
        if failures == total:
            return 1.0
        if failures == 0:
            return -math.expm1(math.log1p(-self.confidence) / total)
        coefficients = [math.lgamma(total + 1) - math.lgamma(index + 1) - math.lgamma(total - index + 1) for index in range(failures + 1)]
        low, high = failures / total, 1.0
        target = math.log1p(-self.confidence)
        while True:
            middle = (low + high) / 2
            if middle in (low, high):
                return high
            a, b = math.log(middle), math.log1p(-middle)
            terms = [value + index * a + (total - index) * b for index, value in enumerate(coefficients)]
            largest = max(terms)
            probability = largest + math.log(sum(math.exp(value - largest) for value in terms))
            if probability > target:
                low = middle
            else:
                high = middle

    def coverage(self, store, model, splits=("train", "validation", "guard", "release"), controls=None, fresh=False):
        revisions = store.revisions()
        execution = tuple(sorted(EvaluationEligibility.budgets(model).items()))
        sources = {language: {} for language in self.languages}
        cells, selected, missing, reference_missing, dialogue_missing = [], {}, [], [], []
        for split in splits:
            if split not in ("train", "validation", "guard", "release"):
                raise YuanError("数据划分无效 / Invalid data split")
            need_controls = split in ("validation", "guard", "release") if controls is None else bool(controls)
            final_key = (FinalAcceptance.identity(model, store, self)["sha256"], store.setting("final_acceptance_revision")) if split == "release" else None
            key = (split, need_controls, model.hop, self.digest, final_key, execution)
            cached = store.coverage_cache.get(key)
            version = revisions["revision_" + split]
            if fresh or cached is None or cached[0] != version or time.time() >= cached[1]:
                result = self._coverage_split(store, model, split, need_controls)
                retry = store.db.execute("SELECT min(p.retry_at) FROM turn_pairs p JOIN groups g ON g.id=p.group_id WHERE g.split=? AND p.eligible=1 AND p.retry_at>?", (split, time.time())).fetchone()[0]
                store.coverage_cache[key] = (version, retry if retry is not None else math.inf, result)
            else:
                result = cached[2]
            cells.extend(copy.deepcopy(result["cells"]))
            missing.extend(copy.deepcopy(result["missing"]))
            reference_missing.extend(copy.deepcopy(result["reference_missing"]))
            dialogue_missing.extend(copy.deepcopy(result["dialogue_missing"]))
            selected[split] = list(result["selected"])
            for language in self.languages:
                sources[language][split] = result["sources"][language]
        if len(store.coverage_cache) > len(("train", "validation", "guard", "release")) * 2:
            current_final = (FinalAcceptance.identity(model, store, self)["sha256"], store.setting("final_acceptance_revision"))
            store.coverage_cache = {key: value for key, value in store.coverage_cache.items()
                                    if key[2:4] == (model.hop, self.digest) and key[-1] == execution and (key[0] != "release" or key[4] == current_final)}
        return {"sources": sources, "cells": cells, "missing": missing, "ready": not missing, "selected": selected,
                "reference_missing": reference_missing, "reference_ready": "release" in selected and not reference_missing,
                "dialogue_missing": dialogue_missing, "dialogue_reference_ready": "release" in selected and not dialogue_missing,
                "acceptance_policy_sha256": self.digest, "revisions": revisions, "data_gaps": self.data_gaps(store, model)}

    def _coverage_split(self, store, model, split, need_controls):
        query = ("SELECT p.*,g.split,g.origin,g.source_key,u.metadata AS user_metadata,a.metadata AS target_metadata,"
                 "EXISTS(SELECT 1 FROM samples h WHERE h.group_id=p.group_id AND h.created<u.created AND h.digest NOT IN (u.digest,a.digest) AND h.generated=0 AND h.dialogue_eligible=1 AND h.audio_status='ready' AND h.count>0) AS has_history,"
                 "EXISTS(SELECT 1 FROM samples h WHERE h.group_id=p.group_id AND h.created<u.created AND h.digest NOT IN (u.digest,a.digest) AND h.role='assistant' AND h.generated=0 AND h.dialogue_eligible=1 AND h.audio_status='ready' AND h.count>0) AS has_assistant_history "
                 "FROM turn_pairs p JOIN groups g ON g.id=p.group_id JOIN samples u ON u.id=p.user_sample JOIN samples a ON a.id=p.assistant_sample "
                 "WHERE g.split=? AND p.eligible=1 AND p.retry_at<=? AND " + (store.training_pair_filter if split == "train" else "p.verified=1") +
                 " AND u.audio_status='ready' AND a.audio_status='ready' AND u.generated=0 AND a.generated=0 AND u.dialogue_eligible=1 AND a.dialogue_eligible=1 AND u.count>=? AND a.count>=? ORDER BY g.source_key,p.id")
        rows = store.db.execute(query, (split, time.time(), model.hop, model.hop)).fetchall()
        if split == "release":
            rows = FinalAcceptance.filter_rows(model, store, self, rows)
        by_language = {language: [] for language in self.languages}
        limits = EvaluationEligibility.budgets(model)
        executable = {row["id"]: EvaluationEligibility.pair(store, model, row, split, limits) for row in rows}
        for row in rows:
            evidence = json.loads(row["evidence"])
            if evidence.get("language") in by_language:
                by_language[evidence["language"]].append((row, evidence))
        cells, missing, reference_missing, dialogue_missing, chosen, sources = [], [], [], [], {}, {}
        for language, entries in by_language.items():
            sources[language] = len({row["source_key"] for row, evidence in entries})
            for dimension in (None,) if split == "train" else self.dimensions:
                eligible, observed, reference_rows, dialogue_rows = [], set(), {}, {}
                scenario_sources, control_sources, ending_sources, history_sources, reference_sources = set(), set(), set(), set(), set()
                execution_blockers = {}
                for row, evidence in entries:
                    if dimension is not None and dimension not in evidence.get("scenarios", []):
                        continue
                    source = row["source_key"]
                    scenario_sources.add(source)
                    if need_controls and dimension not in evidence.get("contrasts", {}):
                        continue
                    control_sources.add(source)
                    if split != "train" and any(json.loads(row[field]).get("utterance_final") is not True for field in ("user_metadata", "target_metadata")):
                        continue
                    ending_sources.add(source)
                    if dimension == "history" and not row["has_history"]:
                        continue
                    history_sources.add(source)
                    eligibility = executable[row["id"]]
                    if not eligibility["ready"]:
                        for reason in eligibility["reasons"]:
                            execution_blockers.setdefault(reason, set()).add(source)
                        continue
                    reference = evidence.get("reference_checks", {})
                    if evidence.get("method") == "human_audio_annotation" and isinstance(reference, dict) and all(reference.get(key) is True for key in self.reference_checks):
                        reference_sources.add(source)
                        reference_rows.setdefault(source, row)
                    if split == "release" and row["has_history"] and row["has_assistant_history"] and CapabilityEvidence.dialogue_reference(evidence):
                        dialogue_rows.setdefault(source, row)
                    if source not in observed:
                        observed.add(source)
                        eligible.append(row)
                if split == "release":
                    eligible = [dialogue_rows.get(row["source_key"], reference_rows.get(row["source_key"], row)) for row in eligible]
                    eligible.sort(key=lambda row: (row["source_key"] not in dialogue_rows, row["source_key"] not in reference_rows))
                required = 1 if split == "train" else self.minimum
                cell = {"language": language, "split": split, "scenario": dimension, "have": len(observed), "need": required,
                        "scenario_sources": len(scenario_sources), "control_sources": len(control_sources), "ending_sources": len(ending_sources),
                        "history_sources": len(history_sources), "controls_required": need_controls, "reference_sources": len(reference_sources),
                        "dialogue_reference_sources": len(dialogue_rows), "present_sources": len(scenario_sources),
                        "executable_sources": len(observed), "execution_limits": limits,
                        "execution_blockers": {key: len(value) for key, value in execution_blockers.items()},
                        "evidence_scope": {"train": "training", "validation": "tuning", "guard": "regression_selection", "release": "final_acceptance"}[split], "ready": len(observed) >= required}
                cells.append(cell)
                if not cell["ready"]:
                    missing.append(dict(cell))
                if split == "release" and len(reference_sources) < required:
                    reference_missing.append({"language": language, "split": split, "scenario": dimension, "have": len(reference_sources), "need": required, "missing": "reference_checks"})
                if split == "release" and len(dialogue_rows) < required:
                    dialogue_missing.append({"language": language, "split": split, "scenario": dimension, "have": len(dialogue_rows), "need": required, "missing": "recorded_dialogue_benchmark"})
                for row in eligible[:required]:
                    chosen[row["id"]] = row
        return {"cells": cells, "sources": sources, "missing": missing, "reference_missing": reference_missing, "dialogue_missing": dialogue_missing, "selected": list(chosen.values()) if not missing else []}

    def data_gaps(self, store, model):
        gaps = []
        verifier_limit = EvaluationEligibility.budgets(model)["verifier"]
        for language in self.languages:
            for split in ("train", "validation", "guard"):
                need = 1 if split == "train" else self.minimum
                row = store.db.execute("SELECT count(DISTINCT g.source_key) FROM samples s JOIN groups g ON g.id=s.group_id WHERE g.split=? AND s.generated=0 AND s.dialogue_eligible=1 AND s.audio_status='ready' AND s.count BETWEEN ? AND ? AND json_extract(s.metadata,'$.transcript_verified')=1 AND json_extract(s.metadata,'$.language')=? AND length(json_extract(s.metadata,'$.transcript'))>0", (split, model.hop, verifier_limit, language)).fetchone()
                if row[0] < need:
                    gaps.append({"kind": "transcript_supervision", "language": language, "split": split, "have": row[0], "need": need})
        count = store.db.execute("SELECT count(*) FROM samples s JOIN groups g ON g.id=s.group_id WHERE g.split='train' AND s.learnable=1 AND s.audio_status='ready'").fetchone()[0]
        if not count:
            gaps.append({"kind": "raw_audio", "language": None, "split": "train", "have": 0, "need": 1})
        gaps.extend(MemoryCalibration(model, store).selection(self, splits=("train", "validation", "guard"))["missing"])
        return gaps

    def acquisition_plan(self, report):
        tasks = {}
        for cell in report["cells"]:
            count = max(0, cell["need"] - cell["have"])
            if not count:
                continue
            key = (cell["language"], cell["split"], cell["scenario"])
            raw = cell["split"] == "train" and cell["language"] == "English"
            tasks[key] = {"language": cell["language"], "split": cell["split"], "scenario": cell["scenario"],
                          "missing_sources": count, "evidence_scope": cell["evidence_scope"],
                          "automatic_source": "public_dialogue" if raw else "annotated_catalog",
                          "requires": "recorded_speaker_turns" if raw else "independent_human_annotations", "gap_kind": "paired_dialogue" if cell["split"] == "train" else "task_annotations", "coverage_guaranteed": False,
                          "discovery_required": not raw, "completion": "validated_independent_coverage",
                          "execution_blockers": cell.get("execution_blockers", {}),
                          "recovery": "select_complete_shorter_annotated_recordings_or_restore_resources" if cell.get("execution_blockers") else "acquire_independent_sources"}
        for cell in report["reference_missing"]:
            key = (cell["language"], cell["split"], cell["scenario"])
            task = tasks.setdefault(key, {"language": cell["language"], "split": cell["split"], "scenario": cell["scenario"], "missing_sources": 0,
                                        "evidence_scope": "acceptance", "automatic_source": "annotated_catalog", "requires": "independent_human_annotations",
                                        "discovery_required": True, "completion": "validated_independent_coverage"})
            task["missing_reference_sources"] = max(0, cell["need"] - cell["have"])
        for cell in report.get("dialogue_missing", []):
            key = (cell["language"], cell["split"], cell["scenario"])
            task = tasks.setdefault(key, {"language": cell["language"], "split": cell["split"], "scenario": cell["scenario"], "missing_sources": 0,
                                         "evidence_scope": "recorded_dialogue_benchmark", "automatic_source": "annotated_catalog",
                                         "discovery_required": True, "completion": "validated_independent_coverage"})
            task.update(missing_dialogue_sources=max(0, cell["need"] - cell["have"]), requires="independent_human_multiturn_annotations",
                        gap_kind="dialogue_annotations", coverage_guaranteed=False)
        for gap in report.get("data_gaps", []):
            if gap["kind"] == "retrieval_supervision":
                tasks[(gap["language"], gap["split"], gap["kind"], gap["relevant"])] = {
                    "language": gap["language"], "split": gap["split"], "scenario": None, "relevant": gap["relevant"],
                    "missing_sources": gap["need"] - gap["have"], "evidence_scope": "retrieval_training" if gap["split"] == "train" else "retrieval_calibration",
                    "automatic_source": "annotated_catalog", "requires": "independent_human_retrieval_annotations",
                    "gap_kind": gap["kind"], "discovery_required": True, "coverage_guaranteed": False,
                    "completion": "validated_independent_coverage"}
                continue
            native = [item["repository"] for item in PublishedSpeech.specifications if gap["language"] in item["languages"]]
            tasks[(gap["language"], gap["split"], gap["kind"])] = {"language": gap["language"], "split": gap["split"], "scenario": None, "missing_sources": gap["need"] - gap["have"], "evidence_scope": "transcript_supervision" if native else "acoustic_training", "automatic_source": "native_speech" if native else "public_audio", "repositories": native, "requires": "publisher_human_transcriptions" if native else "licensed_audio", "gap_kind": gap["kind"], "discovery_required": False, "coverage_guaranteed": False, "completion": "validated_independent_coverage"}
        for task in tasks.values():
            if task["automatic_source"] == "annotated_catalog":
                fields = ["human_recording", "recording_id", "license", "reviewer", "annotation_id", "speaker", "audio_sha256", "verified_reply_relation"]
                if task.get("gap_kind") == "retrieval_supervision":
                    fields.extend(("human_retrieval_relevance_v1", "historical_audio_reference", "relevant_label"))
                else:
                    fields.append("scenario:" + str(task.get("scenario")))
                    if task["split"] != "train":
                        fields.extend(("verified_contrasts", "utterance_final"))
                    if task.get("missing_reference_sources", 0):
                        fields.append("reference_checks")
                    if task.get("missing_dialogue_sources", 0):
                        fields.append("independent_multiturn_dialogue_annotation")
                task["required_fields"] = fields
                task["adapters"] = ["yuan-paired-audio-v1", "recorded-messages"]
        return sorted(tasks.values(), key=lambda task: (task["split"] != "train", -task["missing_sources"], task["language"] or "", task["scenario"] or "", task.get("gap_kind", "reference_checks")))

    def select(self, store, model, split="release", require_controls=None, fresh=False):
        return self.coverage(store, model, (split,), controls=require_controls, fresh=fresh)["selected"][split]

    def check_coverage(self, cases):
        for language in self.languages:
            for dimension in self.dimensions:
                sources = {case["recording_id"] for case in cases if case.get("language") == language and dimension in case.get("scenarios", [])}
                if len(sources) < self.minimum:
                    raise YuanError("独立中英文场景覆盖未达到验收置信要求 / Independent Chinese and English scenario coverage does not meet the acceptance confidence requirement")

def network_digest(network, cancel=None):
    digest = hashlib.sha256()
    for name, value in sorted(network.state_dict().items()):
        check(cancel)
        value = value.detach().cpu().contiguous()
        digest.update(payload_digest([name, list(value.shape), str(value.dtype)]).encode("ascii"))
        view = memoryview(value.numpy()).cast("B")
        size = max(1, math.isqrt(max(1, len(view))))
        for start in range(0, len(view), size):
            check(cancel)
            digest.update(view[start:start + size])
    return digest.hexdigest()

def tensors_finite(torch, values):
    flags = {}
    for value in values:
        if not isinstance(value, torch.Tensor):
            return False
        key = str(value.device)
        flags.setdefault(key, []).append(torch.isfinite(value.detach()).all())
    return all(bool(torch.stack(group).all().item()) for group in flags.values())

def gradient_checkpoint(value, cancel):
    if isinstance(value, (tuple, list)):
        for item in value:
            gradient_checkpoint(item, cancel)
    elif getattr(value, "requires_grad", False):
        def before_backward(gradient):
            check(cancel)
            return gradient
        value.register_hook(before_backward)
    return value

class CooperativeCompute:
    def __init__(self, model, component, device=None):
        self.model, self.component = model, component
        self.device = model.device if device is None else device
        self.section = "cooperative_" + component

    def target(self):
        frame = self.model.hop / self.model.rate
        baseline = math.sqrt(frame * max(frame, self.model.chunk_seconds))
        return max(frame, getattr(self.model, "compute_quantum_seconds", baseline))

    def frames(self, maximum):
        maximum = max(1, int(maximum))
        observed = self.model.policy.measured(self.section, "seconds_per_frame", 0.0)
        total = self.model.policy.measured(getattr(self.model, "performance_section", "performance"), "training_seconds_per_frame", 0.0)
        seconds = max(observed, total)
        requested = self.target() / seconds if seconds > 0 else max(1, math.isqrt(maximum))
        return max(1, min(maximum, int(requested)))

    def run(self, operation, frames, cancel):
        check(cancel)
        began = time.monotonic()
        result = operation()
        compute_sync(self.model.torch, self.device)
        elapsed = elapsed_seconds(began)
        check(cancel)
        self.model.policy.observe(self.section, "seconds_per_frame", elapsed / max(1, frames))
        self.model.policy.observe(self.section, "atomic_seconds", elapsed)
        self.model.policy.observe(self.section, "over_budget", float(elapsed > self.target()))
        return gradient_checkpoint(result, cancel)

class CancellableOutput:
    def __init__(self, stream, cancel, block_bytes):
        self.stream, self.cancel = stream, cancel
        self.block_bytes = max(1, int(block_bytes))

    def write(self, data):
        view = memoryview(data)
        total = 0
        while total < len(view):
            check(self.cancel)
            written = self.stream.write(view[total:total + self.block_bytes])
            if written is None or written <= 0:
                raise OSError("Checkpoint write made no progress")
            total += written
        check(self.cancel)
        return total

    def flush(self):
        check(self.cancel)
        self.stream.flush()
        check(self.cancel)

    def tell(self):
        return self.stream.tell()

def save_checkpoint(torch, payload, path, cancel, block_bytes):
    check(cancel)
    try:
        with open(path, "wb") as stream:
            torch.save(payload, CancellableOutput(stream, cancel, block_bytes))
            stream.flush()
            check(cancel)
            os.fsync(stream.fileno())
            check(cancel)
    except BaseException:
        check(cancel)
        raise

def relocate_network(torch, network, optimizer, device):
    if network is None:
        return
    before = list(network.parameters())
    if optimizer is not None:
        optimizer.zero_grad(set_to_none=True)
    network.to(device)
    if optimizer is None:
        return
    replacements = dict(zip(before, network.parameters()))
    def move(value, target):
        if isinstance(value, torch.Tensor):
            return value.to(target)
        if isinstance(value, dict):
            return {key: move(item, target) for key, item in value.items()}
        if isinstance(value, (tuple, list)):
            return type(value)(move(item, target) for item in value)
        return value
    for group in optimizer.param_groups:
        group["params"] = [replacements.get(parameter, parameter) for parameter in group["params"]]
        for parameter in group["params"]:
            original = next((old for old, new in replacements.items() if new is parameter), parameter)
            values = optimizer.state.pop(original, {})
            for key, value in tuple(values.items()):
                target = device if key != "step" or group.get("capturable") or group.get("fused") else torch.device("cpu")
                values[key] = move(value, target)
            if values:
                optimizer.state[parameter] = values

def unsupported_operation(exc):
    message = str(exc).casefold()
    return isinstance(exc, NotImplementedError) or isinstance(exc, RuntimeError) and "out of memory" not in message and any(
        phrase in message for phrase in ("not implemented", "not supported", "unsupported operator", "could not run", "does not support"))

class SpeechVerifier:
    protocol = "yuan-self-trained-speech-verifier-v4-task-normalization"

    def __init__(self, model, store, emit):
        self.model, self.store, self.emit = model, store, emit
        self.configure_device(model.device)
        self.root = safe_path(model.state, "learning/verifier")
        self.root.mkdir(parents=True, exist_ok=True)
        self.store.db.execute("CREATE TABLE IF NOT EXISTS speech_training(sample TEXT PRIMARY KEY REFERENCES samples(id) ON DELETE CASCADE, visits INTEGER NOT NULL DEFAULT 0, retry_at REAL NOT NULL DEFAULT 0)")
        self.store.commit()
        self.network = self.optimizer = self.accepted = None
        self.steps = 0
        self.manifest = read_json(self.root / "current.json")
        self.training_revision = store.setting("training_revision")
        self.calibration_revision = None
        self.calibration_checked = False
        self.certificate = {}
        self.dirty = False
        self.interval = max(1, math.isqrt(model.width * model.layers))

    def configure_device(self, device):
        self.device = self.model.torch.device(device)
        certificate = read_json(Path(self.model.state) / "compute-verified.json")
        rows = certificate.get("devices", []) if certificate.get("build_sha256") == build_digest() else []
        identity = compute_device_identity(self.model.torch, self.device)
        verified = next((row for row in rows if row.get("device") == str(self.device) and row.get("identity_sha256") == identity), {})
        self.feature_device = self.model.torch.device(verified.get("verifier_feature_device", str(self.device)))
        self.ctc_device = self.model.torch.device(verified.get("verifier_ctc_device", str(self.device)))

    def relocate(self, device):
        relocate_network(self.model.torch, self.network, self.optimizer, device)
        relocate_network(self.model.torch, self.accepted, None, device)
        self.configure_device(device)

    def ctc_loss(self, output, targets):
        torch = self.model.torch
        def calculate(device):
            return torch.nn.functional.ctc_loss(output.to(device), targets.to(device),
                       torch.tensor([output.shape[0]], dtype=torch.long), torch.tensor([targets.numel()], dtype=torch.long), blank=0, zero_infinity=False)
        try:
            return calculate(self.ctc_device)
        except (RuntimeError, NotImplementedError) as exc:
            if self.ctc_device.type == "cpu" or not unsupported_operation(exc):
                raise
            self.ctc_device = torch.device("cpu")
            self.emit("compute_partition", component="verifier_ctc", device="cpu", network_device=str(self.device), reason=concise_error(exc))
            return calculate(self.ctc_device)

    @staticmethod
    def normalize_text(value):
        return " ".join(unicodedata.normalize("NFC", str(value)).split())

    @classmethod
    def recognition_text(cls, value):
        text = cls.normalize_text(value)
        text = text.rstrip("。！？!?").rstrip()
        if text.endswith(".") and not text.endswith(".."):
            text = text[:-1].rstrip()
        return text.casefold()

    @staticmethod
    def normalize_answer(value):
        if not isinstance(value, str):
            raise ValueError("答案必须是文本 / An answer must be text")
        return " ".join(unicodedata.normalize("NFC", value).split())

    @staticmethod
    def error_rate(expected, observed):
        a, b = list(expected), list(observed)
        previous = list(range(len(b) + 1))
        for index, left in enumerate(a, 1):
            current = [index]
            for position, right in enumerate(b, 1):
                current.append(min(current[-1] + 1, previous[position] + 1, previous[position - 1] + (left != right)))
            previous = current
        return previous[-1] / max(1, len(a))

    def identity(self):
        return payload_digest([self.protocol, self.model.rate, self.model.hop, self.model.width, "utf8-ctc-257", behavior_digest()])

    def build(self):
        torch = self.model.torch
        width, size = self.model.width, self.model.hop * 4
        class Recognizer(torch.nn.Module):
            def __init__(self):
                super().__init__()
                self.input = torch.nn.Sequential(torch.nn.Linear(size // 2 + 1, width), torch.nn.LayerNorm(width), torch.nn.GELU())
                self.forward_encoder = portable_recurrent(torch, width, width, batch_first=True)
                self.backward_encoder = portable_recurrent(torch, width, width, batch_first=True)
                self.output = torch.nn.Linear(width * 2, 257)
            def forward(self, features, cancel=None, budget=None):
                check(cancel)
                step = budget.frames(features.shape[1]) if budget is not None else max(1, math.isqrt(features.shape[1]))
                encoded = []
                for start in range(0, features.shape[1], step):
                    block = features[:, start:start + step]
                    check(cancel)
                    value = budget.run(lambda: self.input(block), block.shape[1], cancel) if budget is not None else self.input(block)
                    encoded.append(gradient_checkpoint(value, cancel))
                inputs = torch.cat(encoded, dim=1)
                directions = []
                for encoder, reverse in ((self.forward_encoder, False), (self.backward_encoder, True)):
                    values = inputs.flip(1) if reverse else inputs
                    pieces, hidden = [], None
                    for start in range(0, values.shape[1], step):
                        check(cancel)
                        block = values[:, start:start + step]
                        output, hidden = budget.run(lambda: encoder(block, hidden), block.shape[1], cancel) if budget is not None else encoder(block, hidden)
                        pieces.append(gradient_checkpoint(output, cancel))
                        gradient_checkpoint(hidden, cancel)
                    value = torch.cat(pieces, dim=1)
                    directions.append(value.flip(1) if reverse else value)
                joined = torch.cat(directions, dim=-1)
                outputs = []
                for start in range(0, joined.shape[1], step):
                    check(cancel)
                    block = joined[:, start:start + step]
                    value = budget.run(lambda: self.output(block).log_softmax(-1), block.shape[1], cancel) if budget is not None else self.output(block).log_softmax(-1)
                    outputs.append(gradient_checkpoint(value, cancel))
                return torch.cat(outputs, dim=1)
        return Recognizer().to(device=self.device, dtype=torch.float32)

    def features(self, values, cancel=None):
        check(cancel)
        torch, np = self.model.torch, self.model.np
        values = np.asarray(values, dtype=np.float32).reshape(-1)
        if len(values) < self.model.hop or not np.isfinite(values).all():
            raise InvalidAudio("语义验证输入无效 / Invalid semantic verification input")
        import psutil
        working = max(len(values), len(values) // self.model.hop * self.model.width * 32) * np.dtype(np.float32).itemsize
        if len(values) > self.model.capacity() or working > available_resources(psutil)["memory"] // max(2, self.model.layers + 1):
            raise IneligibleSample("语义验证音频超过资源预算 / Semantic verification audio exceeds the resource budget")
        audio = torch.from_numpy(values.copy()).to(self.feature_device)
        size, hop = self.model.hop * 4, self.model.hop
        if len(audio) < size:
            audio = torch.nn.functional.pad(audio, (0, size - len(audio)))
        frames = audio.unfold(0, size, hop)
        window = torch.hann_window(size, device=self.feature_device)
        budget = CooperativeCompute(self.model, "verifier_features", device=self.feature_device)
        step = budget.frames(len(frames))
        pieces = []
        for start in range(0, len(frames), step):
            block = frames[start:start + step]
            try:
                pieces.append(budget.run(lambda: torch.log1p(torch.abs(torch.fft.rfft(block * window))), len(block), cancel))
            except (RuntimeError, NotImplementedError) as exc:
                if self.feature_device.type == "cpu" or not unsupported_operation(exc):
                    raise
                self.feature_device = torch.device("cpu")
                self.emit("compute_partition", component="verifier_spectrum", device="cpu", network_device=str(self.device), reason=concise_error(exc))
                return self.features(values, cancel)
        spectrum = torch.cat(pieces)
        check(cancel)
        mean = spectrum.mean()
        scale = spectrum.std(unbiased=False).clamp_min(torch.finfo(torch.float32).eps)
        return ((spectrum - mean) / scale).unsqueeze(0).to(self.device)

    def transcribe(self, values, network=None, cancel=None):
        torch = self.model.torch
        network = self.accepted if network is None else network
        if network is None:
            return ""
        with torch.no_grad():
            tokens = network(self.features(values, cancel), cancel=cancel, budget=CooperativeCompute(self.model, "verifier_forward")).argmax(-1).reshape(-1).tolist()
        check(cancel)
        output, previous = [], None
        for token in tokens:
            if token and token != previous:
                output.append(token - 1)
            previous = token
        try:
            return self.normalize_text(bytes(output).decode("utf-8", errors="strict"))
        except UnicodeDecodeError:
            return ""

    def rows(self, split, limit=None):
        sql = ("WITH eligible AS (SELECT s.*,g.split,g.origin,g.source_key,COALESCE(v.visits,0) AS speech_visits,"
               "ROW_NUMBER() OVER (PARTITION BY s.digest ORDER BY s.learnable DESC,s.created,s.id) AS transcript_position "
               "FROM samples s JOIN groups g ON g.id=s.group_id LEFT JOIN speech_training v ON v.sample=s.id "
               "WHERE g.split=? AND s.generated=0 AND s.dialogue_eligible=1 AND s.audio_status='ready' "
               "AND s.count>=? AND s.count<=? AND json_extract(s.metadata,'$.transcript_verified')=1 "
               "AND (json_extract(s.metadata,'$.language') IN ('中文','English') OR (g.split='train' AND json_extract(s.metadata,'$.language')='mixed')) "
               "AND length(json_extract(s.metadata,'$.transcript'))>0) "
               "SELECT * FROM eligible WHERE transcript_position=1 AND COALESCE((SELECT retry_at FROM speech_training WHERE sample=eligible.id),0)<=? ORDER BY speech_visits,id")
        args = [split, self.model.hop, EvaluationEligibility.budgets(self.model)["verifier"], time.time()]
        if limit is not None:
            if type(limit) is not int or limit < 1:
                raise ValueError("转写样本数量无效 / Invalid transcript sample limit")
            sql += " LIMIT ?"
            args.append(limit)
        return self.store.db.execute(sql, args).fetchall()

    def _prepare(self, cancel):
            if self.network is not None:
                return
            check(cancel)
            self.network = self.build()
            parameters = sum(value.numel() for value in self.network.parameters())
            self.optimizer = self.model.torch.optim.AdamW(self.network.parameters(), lr=1 / math.sqrt(parameters), weight_decay=1 / parameters, foreach=False)
            manifest = self.manifest
            if manifest.get("identity") != self.identity() or manifest.get("training_revision") != self.training_revision:
                return
            try:
                path = safe_path(self.root, manifest["file"])
                config = {key: getattr(self.model, key) for key in ("rate", "hop", "width", "layers")}
                ModelResources.checkpoint(path, ModelResources.estimate(config)["weight_bytes"] * 4)
                if digest_file(path, cancel) != manifest.get("sha256"):
                    raise InvalidAudio("验证模型摘要不匹配 / Verifier model checksum mismatch")
                state = self.model.torch.load(path, map_location="cpu", weights_only=True)
                if any(not self.model.torch.isfinite(value).all() for value in state["network"].values()):
                    raise YuanError("验证模型权重无效 / Invalid verifier weights")
                self.network.load_state_dict(state["network"], strict=True)
                self.optimizer.load_state_dict(state["optimizer"])
                relocate_network(self.model.torch, self.network, self.optimizer, self.device)
                for values in self.optimizer.state.values():
                    for value in values.values():
                        if isinstance(value, self.model.torch.Tensor) and not self.model.torch.isfinite(value).all():
                            raise YuanError("验证模型优化器状态无效 / Invalid verifier optimizer state")
                if type(state.get("steps")) is not int or state["steps"] < 0 or state["steps"] != manifest.get("steps"):
                    raise YuanError("验证模型训练进度无效 / Invalid verifier training progress")
                self.steps = state["steps"]
                if manifest.get("certificate", {}).get("passed") is True:
                    self.accepted = copy.deepcopy(self.network).eval().requires_grad_(False)
                    self.certificate = manifest["certificate"]
                    if self.certificate.get("weights_sha256") != network_digest(self.accepted, cancel):
                        raise YuanError("校准验证器权重身份不匹配 / Calibrated verifier weights do not match")
                    self.calibration_checked = False
            except (OSError, ValueError, TypeError, KeyError, RuntimeError) as exc:
                self.network = self.optimizer = self.accepted = None
                self.manifest, self.certificate = {}, {}
                self.steps = 0
                self.dirty = False
                self.emit("notice", key="semantic_evidence_missing", reason=concise_error(exc))
                raise

    def ready(self, cancel=None):
        if self.store.setting("training_revision") != self.training_revision:
            self.network = self.optimizer = self.accepted = None
            self.manifest, self.certificate = {}, {}
            self.steps = 0
            self.training_revision = self.store.setting("training_revision")
            return False
        if self.accepted is None and self.manifest.get("certificate", {}).get("passed") is True:
            self._prepare(cancel)
        if self.accepted is None:
            return False
        if self.certificate.get("identity") != self.identity() or self.certificate.get("acceptance_policy_sha256") != AcceptancePolicy(self.model).digest:
            self.accepted, self.certificate = None, {}
            return False
        revision = self.store.setting("evaluation_revision")
        if revision != self.calibration_revision or not self.calibration_checked:
            records = self.certificate.get("records", [])
            for record in records:
                row = self.store.sample(record["sample"])
                if row is None or self.row_signature(row) != record["signature"] or row["split"] not in ("validation", "guard"):
                    self.accepted, self.certificate = None, {}
                    return False
            if not self.store.snapshot_valid(self.certificate.get("evaluation_snapshot")):
                self.accepted, self.certificate = None, {}
                return False
            self.store.assert_independent([record["group"] for record in records])
            self.calibration_revision = revision
            self.calibration_checked = True
        return bool(self.certificate.get("passed"))

    @staticmethod
    def row_signature(row):
        values = {key: row[key] for key in ("id", "group_id", "split", "source_key", "digest", "file_sha256", "audio_status", "dialogue_eligible", "generated")}
        values["metadata"] = AudioStore.evidence_metadata(json.loads(row["metadata"]))
        return payload_digest(values)

    def quality(self, values):
        np = self.model.np
        x = np.asarray(values, dtype=np.float64).reshape(-1)
        if len(x) < self.model.hop or not np.isfinite(x).all() or np.max(np.abs(x)) > 1:
            return None
        eps = np.finfo(np.float32).eps
        rms = math.sqrt(float(np.mean(x * x)))
        if rms <= eps:
            return None
        frames = x[:len(x) // self.model.hop * self.model.hop].reshape(-1, self.model.hop)
        power = np.abs(np.fft.rfft(frames * np.hanning(self.model.hop), axis=-1)) ** 2 + eps ** 2
        return {"rms": rms, "dc": abs(float(np.mean(x))) / rms,
                "clipping": float(np.mean(np.abs(x) >= 1 - eps)),
                "flatness": float(np.mean(np.exp(np.mean(np.log(power), axis=-1)) / np.mean(power, axis=-1))),
                "crest": float(np.max(np.abs(x))) / rms}

    def calibrate(self, cancel, fixed=None):
        acceptance = AcceptancePolicy(self.model)
        revisions = self.store.revisions()
        selected, observed = [], set()
        source_limit = max(acceptance.minimum, math.isqrt(max(1, self.model.capacity() // self.model.hop)) * self.model.layers)
        for split in ("validation", "guard"):
            counts = {language: 0 for language in acceptance.languages}
            for row in (self.rows(split) if fixed is None else [item for item in fixed if item["split"] == split]):
                metadata = json.loads(row["metadata"])
                language, source = metadata["language"], row["source_key"]
                if language not in counts or source in observed or fixed is None and counts[language] >= source_limit:
                    continue
                selected.append(row)
                observed.add(source)
                counts[language] += 1
            if any(value < acceptance.minimum for value in counts.values()):
                return False
        self.store.assert_independent([row["group_id"] for row in selected])
        snapshot = self.store.evaluation_snapshot(selected)
        records, qualities, measures = [], {language: [] for language in acceptance.languages}, {}
        self.network.eval()
        for row in selected:
            check(cancel)
            values = self.store.read_audio(row, cancel=cancel, verify=True)
            metadata = json.loads(row["metadata"])
            expected = self.normalize_text(metadata["transcript"])
            observed = self.transcribe(values, self.network, cancel)
            raw_error = self.error_rate(expected, observed)
            normalized = self.recognition_text(expected)
            error = self.error_rate(normalized, self.recognition_text(observed))
            if not normalized:
                return False
            key = row["split"] + ":" + metadata["language"]
            measures.setdefault(key, []).append(error)
            quality = self.quality(values)
            if not expected or quality is None:
                return False
            qualities[metadata["language"]].append(quality)
            records.append({"sample": row["id"], "group": row["group_id"], "signature": self.row_signature(row), "error": error, "raw_error": raw_error})
        measurements = {}
        for key, errors in measures.items():
            failures = sum(error > 0 for error in errors)
            upper = acceptance.failure_bound(failures, len(errors))
            measurements[key] = {"sources": len(errors), "failures": failures, "mean_error": sum(errors) / len(errors),
                                 "failure_rate_upper": upper, "passed": upper <= acceptance.maximum_failure}
        passed = len(measurements) == len(acceptance.languages) * 2 and all(item["passed"] for item in measurements.values())
        self.emit("learning", key="semantic_verifier", stage="verifier_validation", passed=passed,
                  measurements=measurements, conversation_verified=False)
        if not passed:
            return False
        bounds = {}
        for language, rows in qualities.items():
            bounds[language] = {}
            for key in rows[0]:
                numbers = [row[key] for row in rows]
                tolerance = max(float(self.model.np.finfo(self.model.np.float32).eps), (max(numbers) - min(numbers)) / math.sqrt(len(numbers)))
                bounds[language][key] = [max(0.0, min(numbers) - tolerance), max(numbers) + tolerance]
        if self.store.setting("training_revision") != revisions["training_revision"] or not self.store.snapshot_valid(snapshot):
            return False
        self.certificate = {"protocol": self.protocol, "passed": True, "identity": self.identity(), "acceptance_policy_sha256": acceptance.digest,
                            "training_revision": self.training_revision, "records": records, "bounds": bounds, "steps": self.steps,
                            "evaluation_snapshot": snapshot, "measurements": measurements,
                            "normalization": "recognition: NFC whitespace terminal-sentence-punctuation casefold; task answers: strict NFC unless independently annotated policy",
                            "scope": "independent transcript content recognition within the acceptance risk bound; annotated-answer tasks only", "created": time.time()}
        self.accepted = copy.deepcopy(self.network).eval().requires_grad_(False)
        self.certificate["weights_sha256"] = network_digest(self.accepted, cancel)
        self.calibration_revision = revisions["evaluation_revision"]
        self.calibration_checked = False
        return True

    def checkpoint(self, cancel):
        if self.network is None or not self.dirty:
            return
        name = "verifier-" + uuid.uuid4().hex + ".pt"
        path, temporary = self.root / name, self.root / (name + ".partial")
        size = sum(value.numel() * value.element_size() for value in self.network.parameters())
        committed = False
        try:
            with StorageBudget(self.model.state).reserve(max(1, size * 4), "checkpoint"):
                save_checkpoint(self.model.torch, {"network": self.network.state_dict(), "optimizer": self.optimizer.state_dict(), "steps": self.steps}, temporary, cancel, self.model.width * self.model.hop * 4)
                with temporary.open("rb") as stream:
                    os.fsync(stream.fileno())
                check(cancel)
                os.replace(temporary, path)
                manifest = {"identity": self.identity(), "file": name, "sha256": digest_file(path, cancel), "training_revision": self.training_revision,
                            "certificate": self.certificate, "steps": self.steps, "self_trained": True, "external_model": False}
                atomic_json(self.root / "current.json", manifest, cancel)
                committed = True
                self.manifest = manifest
                self.dirty = False
                for old in self.root.glob("verifier-*.pt"):
                    if old != path:
                        old.unlink(missing_ok=True)
        finally:
            temporary.unlink(missing_ok=True)
            if not committed:
                path.unlink(missing_ok=True)

    def step(self, cancel):
        if self.ready(cancel):
            return False
        rows = self.rows("train", 1)
        if not rows:
            return False
        row = rows[0]
        self._prepare(cancel)
        torch = self.model.torch
        try:
            values = self.store.read_audio(row, cancel=cancel, verify=True)
            transcript = self.normalize_text(json.loads(row["metadata"])["transcript"])
            targets = torch.tensor([value + 1 for value in transcript.encode("utf-8")], dtype=torch.long)
            features = self.features(values, cancel)
            minimum = len(targets) + sum(a == b for a, b in zip(targets.tolist(), targets.tolist()[1:]))
            if not len(targets) or features.shape[1] < minimum:
                raise IneligibleSample("转写监督与音频帧数不匹配 / Transcript supervision does not fit the audio frames")
            check(cancel)
            self.network.train().requires_grad_(True)
            self.optimizer.zero_grad(set_to_none=True)
            budget = CooperativeCompute(self.model, "verifier_training")
            began = time.monotonic()
            output = self.network(features, cancel=cancel, budget=budget).transpose(0, 1)
            loss = budget.run(lambda: self.ctc_loss(output, targets), output.shape[0], cancel)
            if not torch.isfinite(loss):
                raise YuanError("语义验证模型训练损失无效 / Invalid verifier training loss")
            gradient_checkpoint(loss, cancel).backward()
            check(cancel)
            self.model.policy.observe("cooperative_verifier_training", "seconds_per_frame", elapsed_seconds(began) / features.shape[1])
            torch.nn.utils.clip_grad_norm_(self.network.parameters(), math.sqrt(sum(value.numel() for value in self.network.parameters())), error_if_nonfinite=True)
            self.optimizer.step()
            if not tensors_finite(torch, self.network.parameters()):
                self.network = self.optimizer = self.accepted = None
                self.manifest, self.certificate = {}, {}
                raise YuanError("语义验证模型更新无效 / Invalid verifier update")
            self.steps += 1
            self.dirty = True
            self.store.db.execute("INSERT INTO speech_training(sample,visits) VALUES(?,1) ON CONFLICT(sample) DO UPDATE SET visits=visits+1,retry_at=0", (row["id"],))
            self.store.commit()
            self.emit("learning", key="semantic_verifier", stage="verifier_training", verifier_steps=self.steps, verifier_loss=float(loss.detach().item()), conversation_verified=False)
            if self.steps % self.interval == 0:
                self.calibrate(cancel)
                self.checkpoint(cancel)
            return True
        except (InvalidAudio, IneligibleSample) as exc:
            self.store.db.execute("INSERT INTO speech_training(sample,retry_at) VALUES(?,?) ON CONFLICT(sample) DO UPDATE SET retry_at=excluded.retry_at", (row["id"], time.time() + self.store.retry_delay(row["speech_visits"] + 1)))
            self.store.commit()
            self.emit("notice", key="sample_skipped", sample=row["id"], reason=concise_error(exc))
            return False
        finally:
            if self.optimizer is not None:
                self.optimizer.zero_grad(set_to_none=True)

    @classmethod
    def answer_policy(cls, evidence, dimension=None):
        semantic = evidence.get("semantic", {}) if dimension is None else evidence.get("contrasts", {}).get(dimension, {}).get("semantic", {})
        name = semantic.get("normalization", "strict_nfc_v1") if isinstance(semantic, dict) else "strict_nfc_v1"
        if name != "strict_nfc_v1" and (name != "casefold_terminal_v1" or semantic.get("normalization_verified") is not True):
            raise IneligibleSample("答案规范化缺少人工标注依据 / Answer normalization lacks human annotation evidence")
        return name

    @classmethod
    def task_answer(cls, value, policy="strict_nfc_v1"):
        text = cls.normalize_answer(value)
        if policy == "strict_nfc_v1":
            return text
        if policy == "casefold_terminal_v1":
            return cls.recognition_text(text)
        raise IneligibleSample("答案规范化策略不受支持 / Unsupported answer normalization policy")

    @classmethod
    def answers(cls, evidence, dimension=None):
        semantic = evidence.get("semantic", {}) if dimension is None else evidence.get("contrasts", {}).get(dimension, {}).get("semantic", {})
        answers = semantic.get("accepted_transcripts") if isinstance(semantic, dict) else None
        if (not isinstance(semantic, dict) or semantic.get("verified") is not True or semantic.get("method") not in ("human_task_answers_v1", "human_dialogue_answers_v1")
                or not isinstance(answers, list) or not answers or any(not isinstance(answer, str) or not cls.normalize_answer(answer) for answer in answers)):
            return ()
        return tuple(dict.fromkeys(cls.normalize_answer(answer) for answer in answers))

    def assess(self, values, language, answers, generation, cancel, normalization="strict_nfc_v1"):
        check(cancel)
        ready = self.ready(cancel)
        base = {"scope": "annotated_answer_set", "semantic_method": "exact_annotated_answer_match", "recognizer_ready": ready,
                "answer_evidence_ready": bool(answers), "recognition_scope": "independent_calibration_only", "open_dialogue_verified": False, "normalization": normalization}
        natural = generation.get("complete") is True and generation.get("natural") is True and generation.get("limited") is False
        if not ready or not answers:
            return {**base, "passed": False, "semantic_passed": False, "quality_passed": False, "natural": natural,
                    "semantic_outcome": "unassessed", "assessment_status": "insufficient_evidence", "reason": "semantic_evidence_missing"}
        transcript = self.task_answer(self.transcribe(values, cancel=cancel), normalization)
        answers = tuple(self.task_answer(answer, normalization) for answer in answers)
        if not transcript:
            return {**base, "passed": False, "semantic_passed": False, "quality_passed": False, "natural": natural,
                    "semantic_outcome": "not_matched", "assessment_status": "not_verified", "reason": "transcription_unavailable", "error": 1.0}
        semantic = transcript in answers
        quality = self.quality(values)
        bounds = self.certificate.get("bounds", {}).get(language, {})
        quality_ok = quality is not None and isinstance(bounds, dict) and bool(bounds)
        if quality_ok:
            for key, value in quality.items():
                bound = bounds.get(key)
                if (not isinstance(bound, (list, tuple)) or len(bound) != 2
                        or any(isinstance(number, bool) or not isinstance(number, (int, float)) or not math.isfinite(number) for number in bound)
                        or not bound[0] <= value <= bound[1]):
                    quality_ok = False
                    break
        reasons = ([] if semantic else ["annotated_answer_not_matched"]) + ([] if quality_ok else ["audio_quality_not_verified"]) + ([] if natural else ["ending_not_verified"])
        return {**base, "passed": bool(semantic and quality_ok and natural), "semantic_passed": semantic, "quality_passed": bool(quality_ok),
                "natural": natural, "transcript": transcript, "answer_sha256": payload_digest(list(answers)), "quality": quality,
                "error": min(self.error_rate(answer, transcript) for answer in answers), "semantic_outcome": "matched" if semantic else "not_matched",
                "assessment_status": "passed" if not reasons else "not_verified", "reasons": reasons}

    def snapshot(self, directory, cancel):
        if not self.ready(cancel):
            raise YuanError("独立语音验证模型尚未校准 / Independent speech verifier is not calibrated")
        if self.certificate.get("weights_sha256") != network_digest(self.accepted, cancel):
            raise YuanError("冻结验证器权重已改变 / Frozen verifier weights changed")
        target = directory / "verifier.pt"
        temporary = target.with_suffix(".part")
        try:
            state = {key: value.detach().cpu() for key, value in self.accepted.state_dict().items()}
            with StorageBudget(self.model.state).reserve(max(1, sum(value.numel() * value.element_size() for value in state.values())) * 2, "verifier_release"):
                save_checkpoint(self.model.torch, {"network": state}, temporary, cancel, self.model.width * self.model.hop * 4)
                with temporary.open("rb") as stream:
                    os.fsync(stream.fileno())
                check(cancel)
                os.replace(temporary, target)
            return {"protocol": self.protocol, "identity": self.identity(), "file": target.relative_to(safe_path(self.model.state, "learning")).as_posix(),
                    "sha256": digest_file(target, cancel), "certificate": copy.deepcopy(self.certificate), "self_trained": True, "external_model": False}
        finally:
            temporary.unlink(missing_ok=True)

    def restore_snapshot(self, snapshot, directory, cancel):
        if (snapshot.get("protocol") != self.protocol or snapshot.get("identity") != self.identity()
                or snapshot.get("self_trained") is not True or snapshot.get("external_model") is not False):
            raise YuanError("自动验收验证模型来源不符合要求 / Automatic verifier provenance is invalid")
        path = safe_path(directory, snapshot["file"])
        config = {key: getattr(self.model, key) for key in ("rate", "hop", "width", "layers")}
        ModelResources.checkpoint(path, ModelResources.estimate(config)["weight_bytes"] * 2)
        if digest_file(path, cancel) != snapshot.get("sha256"):
            raise YuanError("自动验收验证模型摘要不匹配 / Automatic verifier checksum mismatch")
        state = self.model.torch.load(path, map_location="cpu", weights_only=True)
        network = self.build()
        if not isinstance(state.get("network"), dict) or any(not self.model.torch.isfinite(value).all() for value in state["network"].values()):
            raise YuanError("自动验收验证模型权重无效 / Invalid automatic verifier weights")
        network.load_state_dict(state["network"], strict=True)
        network.eval().requires_grad_(False)
        certificate = snapshot.get("certificate", {})
        if certificate.get("weights_sha256") != network_digest(network, cancel):
            raise YuanError("最终验证器权重与校准记录不匹配 / Final verifier weights differ from calibration records")
        if certificate.get("acceptance_policy_sha256") != AcceptancePolicy(self.model).digest or certificate.get("identity") != self.identity():
            raise YuanError("自动验收校准策略已改变 / Automatic verifier calibration policy changed")
        records = certificate.get("records", [])
        if not records or len({record["sample"] for record in records}) != len(records):
            raise YuanError("自动验收缺少独立校准记录 / Automatic verifier lacks independent calibration records")
        fixed, files = [], [path]
        for record in records:
            check(cancel)
            row = self.store.db.execute("SELECT s.*,g.split,g.origin,g.source_key FROM samples s JOIN groups g ON g.id=s.group_id WHERE s.id=?", (record["sample"],)).fetchone()
            if (row is None or row["split"] not in ("validation", "guard") or row["generated"] or not row["dialogue_eligible"]
                    or row["audio_status"] != "ready" or self.row_signature(row) != record["signature"]):
                raise YuanError("自动验收校准数据已改变 / Automatic verifier calibration data changed")
            metadata = json.loads(row["metadata"])
            if metadata.get("transcript_verified") is not True or metadata.get("language") not in AcceptancePolicy.languages:
                raise YuanError("校准音频缺少可信转写 / Calibration audio lacks verified transcripts")
            fixed.append(row)
            files.append(safe_path(self.store.root, row["audio"]))
        self.network, self.steps = network, int(certificate.get("steps", 0))
        if not self.calibrate(cancel, fixed=fixed) or {item["sample"] for item in self.certificate["records"]} != {item["sample"] for item in records}:
            raise YuanError("独立验证模型重新校准未通过 / Independent verifier recalibration failed")
        return files

class ModelResources:
    @staticmethod
    def checkpoint(path, maximum):
        path = Path(path)
        if path.is_symlink() or not path.is_file() or not 0 < path.stat().st_size <= maximum:
            raise YuanError("模型检查点文件超出结构容量 / Model checkpoint file exceeds architecture capacity")
        if zipfile.is_zipfile(path):
            with zipfile.ZipFile(path) as archive:
                if sum(item.file_size for item in archive.infolist()) > maximum:
                    raise YuanError("模型检查点展开容量无效 / Invalid expanded checkpoint size")
        return path

    @staticmethod
    def configuration(value):
        keys = ("rate", "hop", "width", "layers")
        if (not isinstance(value, dict) or any(type(value.get(key)) is not int or value[key] <= 0 for key in keys)
                or value["hop"] > value["rate"]):
            raise ValueError("模型结构配置无效 / Invalid model architecture configuration")
        return {key: value[key] for key in keys}

    @staticmethod
    def estimate(config):
        rate, hop, width, layers = (config[key] for key in ("rate", "hop", "width", "layers"))
        parameters = (40 * layers + 48) * width * width + (6 * hop + 320) * width + hop * 2
        weights = parameters * 4
        working = max(rate, hop * width) * 4 * 32 + width * layers * 4 * 72 * width
        copies = {"baseline": 1, "serving": 1, "candidate": 1, "gradients": 1, "optimizer": 2,
                  "checkpoint": 2, "promotion": 2, "verifier": 2}
        return {"weight_bytes": weights, "working_bytes": working, "copies": copies,
                "required_bytes": weights * sum(copies.values()) + working}

    @classmethod
    def validate(cls, config, psutil, policy):
        config = cls.configuration(config)
        estimate = cls.estimate(config)
        limits = available_resources(psutil)
        fraction = policy.ratio("model", "initial_training_memory_fraction", 1 / math.sqrt(len(estimate["copies"])))
        if fraction <= 0.0:
            raise YuanFault("模型内存预算必须大于零 / Model memory budget must be positive",
                            category="configuration", code="model_memory_budget_invalid", stage="stage_configuration")
        budget = int(limits["memory"] * fraction)
        if estimate["required_bytes"] > budget:
            raise YuanFault("当前资源不足，模型结构与权重保持不变 / Current resources are insufficient; architecture and weights are preserved",
                            category="resource", code="model_memory_insufficient", stage="stage_configuration",
                            available_bytes=limits["memory"], required_bytes=math.ceil(estimate["required_bytes"] / fraction),
                            model_budget_bytes=budget, model_required_bytes=estimate["required_bytes"])
        return config, estimate

def portable_recurrent(torch, *args, **kwargs):
    class Recurrent(torch.nn.GRU):
        def forward(self, inputs, hx=None):
            if inputs.device.type != "privateuseone":
                return super().forward(inputs, hx)
            return self.portable(inputs, hx)

        def portable(self, inputs, hx=None):
            if inputs.ndim != 3 or self.bidirectional or self.dropout:
                raise YuanError("循环计算结构不匹配 / Recurrent compute structure mismatch")
            values = inputs if self.batch_first else inputs.transpose(0, 1)
            if hx is None:
                hx = values.new_zeros(self.num_layers, values.shape[0], self.hidden_size)
            states = []
            for layer in range(self.num_layers):
                weight_i = getattr(self, "weight_ih_l" + str(layer))
                weight_h = getattr(self, "weight_hh_l" + str(layer))
                bias_i = getattr(self, "bias_ih_l" + str(layer)) if self.bias else None
                bias_h = getattr(self, "bias_hh_l" + str(layer)) if self.bias else None
                projected = torch.nn.functional.linear(values, weight_i, bias_i)
                current = hx[layer]
                outputs = []
                for position in range(values.shape[1]):
                    incoming = projected[:, position]
                    recurrent = torch.nn.functional.linear(current, weight_h, bias_h)
                    ir, iz, inn = incoming.chunk(3, -1)
                    hr, hz, hn = recurrent.chunk(3, -1)
                    reset = torch.sigmoid(ir + hr)
                    update = torch.sigmoid(iz + hz)
                    candidate = torch.tanh(inn + reset * hn)
                    current = candidate + update * (current - candidate)
                    outputs.append(current)
                values = torch.stack(outputs, 1)
                states.append(current)
            return (values if self.batch_first else values.transpose(0, 1)), torch.stack(states)
    return Recurrent(*args, **kwargs)


def compute_device_identity(torch, device, name=None):
    device = torch.device(device)
    module = getattr(torch, device.type, None)
    if name is None:
        if module is not None and hasattr(module, "get_device_name"):
            name = module.get_device_name(device)
        elif device.type == "privateuseone":
            import torch_directml
            name = torch_directml.device_name(device.index or 0)
        else:
            name = "Apple Metal" if device.type == "mps" else "CPU" if device.type == "cpu" else str(device)
    identity = {"device": str(device), "name": str(name), "system": platform.system(), "machine": platform.machine(),
                "visibility": {key: os.environ.get(key) for key in ("CUDA_VISIBLE_DEVICES", "HIP_VISIBLE_DEVICES", "ROCR_VISIBLE_DEVICES", "ZE_AFFINITY_MASK", "ONEAPI_DEVICE_SELECTOR")}}
    if module is not None and hasattr(module, "get_device_properties"):
        properties = module.get_device_properties(device)
        for key in ("name", "major", "minor", "total_memory", "uuid", "pci_bus_id", "luid"):
            value = getattr(properties, key, None)
            if value is not None:
                identity[key] = value if isinstance(value, (str, int, float, bool)) else str(value)
    return payload_digest(identity)

def compute_devices(torch, state, emit):
    expected = os.environ.get("YUAN_COMPUTE_BACKEND") or read_json(Path(state) / "runtime-current.json").get("compute_backend", "")
    devices = []
    if expected == "directml":
        try:
            import torch_directml
            for index in range(torch_directml.device_count()):
                devices.append((torch_directml.device(index), torch_directml.device_name(index)))
        except (ImportError, OSError, RuntimeError) as exc:
            raise YuanFault("DirectML 环境需要修复，保留显卡模式 / DirectML runtime needs repair; accelerator mode retained", category="compatibility", code="compute_backend_failed", backend=expected) from exc
    else:
        if torch.cuda.is_available():
            for index in range(torch.cuda.device_count()):
                devices.append((torch.device("cuda", index), torch.cuda.get_device_name(index)))
        if not devices and hasattr(torch, "xpu") and torch.xpu.is_available():
            for index in range(torch.xpu.device_count()):
                devices.append((torch.device("xpu", index), torch.xpu.get_device_name(index)))
        if not devices and hasattr(torch.backends, "mps") and torch.backends.mps.is_available():
            devices.append((torch.device("mps"), "Apple Metal"))
    if not devices:
        hardware = read_json(Path(state) / "hardware.json")
        if expected not in ("", "cpu", "native") or hardware.get("adapters"):
            raise YuanFault("正在修复显卡运行链路，未切换为 CPU / Repairing the accelerator pipeline without switching to CPU", category="compatibility", code="compute_backend_failed", backend=expected, hardware=hardware)
        devices = [(torch.device("cpu"), "CPU")]
    emit("accelerators", devices=[{"device": str(device), "name": name} for device, name in devices], backend=expected)
    return devices


def compute_sync(torch, device):
    module = getattr(torch, device.type, None)
    if module is not None and hasattr(module, "synchronize"):
        if device.type in ("cuda", "xpu"):
            module.synchronize(device)
        elif device.type == "mps":
            module.synchronize()

def probe_device_memory(state, device, config, required, cancel, policy, emit):
    import psutil
    state = Path(state).resolve()
    check(cancel)
    host = available_resources(psutil)["memory"]
    fraction = policy.ratio("learning", "memory_probe_host_fraction", 1 / math.sqrt(len(ModelResources.estimate(config)["copies"])))
    limit = int(host * fraction)
    if type(required) is not int or required < 1 or required > limit:
        raise YuanFault("探测需求超过安全主机预算 / Probe requirement exceeds the safe host budget", category="resource", code="memory_probe_budget", required_bytes=required, host_budget_bytes=limit)
    root = safe_path(state, "tmp")
    root.mkdir(parents=True, exist_ok=True)
    baseline = max(math.sqrt(config["rate"] / config["hop"]), policy.measured("learning_control", "memory_probe_seconds", 0.0) * 2)
    budget = policy.number("learning", "memory_probe_seconds", baseline, 1.0, max(baseline, math.sqrt(host / max(1, required)) * baseline))
    began = time.monotonic()
    process = None
    with tempfile.TemporaryDirectory(prefix="memory-probe-", dir=root) as directory:
        directory = Path(directory)
        request = directory / "request.json"
        result_path = directory / "result.json"
        atomic_json(request, {"device": str(device), "configuration": config, "allocation_bytes": required,
                              "result": str(result_path.relative_to(Path(state)))}, cancel)
        try:
            with (directory / "output.log").open("wb") as log:
                env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1")
                options = {"creationflags": subprocess.CREATE_NO_WINDOW} if os.name == "nt" else {}
                process = subprocess.Popen([sys.executable, str(Path(__file__).resolve()), "--probe-device-memory", str(state), str(request)],
                                           cwd=str(Path(state).parent), env=env, stdin=subprocess.DEVNULL, stdout=log, stderr=log, **options)
                while process.poll() is None:
                    check(cancel)
                    if time.monotonic() - began >= budget:
                        raise YuanFault("设备预算探测超时，保留后端并稍后缩小重试 / Device budget probe timed out; backend retained for a smaller retry", category="resource", code="memory_probe_timeout")
                    if cancel is None:
                        time.sleep(math.sqrt(tick()))
                    else:
                        cancel.wait(math.sqrt(tick()))
                check(cancel)
            result = read_json(result_path)
            if (process.returncode != 0 or result.get("verified") is not True or result.get("device") != str(device)
                    or result.get("configuration") != config or type(result.get("allocation_bytes")) is not int
                    or result["allocation_bytes"] < required):
                reason = result.get("reason", "设备分配或真实训练探测未通过 / Device allocation or actual training probe did not pass")
                raise YuanFault(str(reason), category="resource", code="memory_probe_failed")
            elapsed = elapsed_seconds(began)
            policy.observe("learning_control", "memory_probe_seconds", elapsed)
            emit("learning_memory", device=str(device), memory_evidence="allocation_probe", probe_seconds=elapsed,
                 tested_allocation_bytes=result["allocation_bytes"], measured_free_memory=False)
            return result
        finally:
            if process is not None and process.poll() is None:
                process.terminate()
                try:
                    process.wait(timeout=max(1.0, math.sqrt(tick())))
                except subprocess.TimeoutExpired:
                    process.kill()
                    process.wait()


def memory_probe_entry(state, request):
    state = Path(state).resolve()
    request = safe_path(state, Path(request).resolve().relative_to(state).as_posix())
    value = checked_json(request)
    config = ModelResources.configuration(value["configuration"])
    result_path = safe_path(state, value["result"])
    required = value["allocation_bytes"]
    result = {"device": value["device"], "configuration": config, "allocation_bytes": required, "verified": False}
    try:
        import numpy as np
        import psutil
        import torch
        if type(required) is not int or not 0 < required <= available_resources(psutil)["memory"]:
            raise ValueError("探测容量无效 / Invalid probe capacity")
        if value["device"].split(":", 1)[0] == "privateuseone":
            import torch_directml
            device = torch_directml.device(int(value["device"].partition(":")[2] or 0))
        else:
            device = torch.device(value["device"])
        torch.set_num_threads(1)
        reserve = torch.empty((math.ceil(required / 4),), device=device, dtype=torch.float32)
        reserve.fill_(0)
        if float(reserve[-1].detach().cpu().item()) != 0:
            raise YuanError("分配探测产生无效数值 / Allocation probe produced invalid values")
        policy = AdaptivePolicy(state)
        components = probe_training_components(torch, np, state, policy, device, config, None, lambda *args, **kwargs: None)
        compute_sync(torch, device)
        result.update(verified=components.get("training_components_verified") is True,
                      allocation_bytes=reserve.numel() * reserve.element_size(), memory_evidence="allocation_probe")
        del reserve
    except Exception as exc:
        result["reason"] = concise_error(exc)
    atomic_json(result_path, result)


class NativeAudio:
    def __init__(self, state, cancel, emit, owned_root=None, dependencies=None):
        dependencies = dependencies if dependencies is not None else load_runtime_modules(state, emit, cancel)
        np, psutil, torch = (dependencies[name] for name in ("numpy", "psutil", "torch"))
        self.np, self.torch, self.emit, self.state = np, torch, emit, Path(state)
        self.cancel = cancel
        self.owned_root = Path(owned_root) if owned_root is not None else None
        self.release_root = self.state
        self.input_budget = None
        self.steps = 0
        self.accepted = 0
        self.acoustic_ready = False
        self.dialogue_ready = False
        self.dialogue_trained = False
        self.playback_ready = False
        self.serving_network = None
        self.serving_digest = None
        self.release_signature = None
        self.release_failure = None
        self.capability_evidence = {}
        self.capacity_scale = 1.0
        self.training_retry_at = 0.0
        self.training_oom_window = None
        self.active_digest = None
        self.policy = AdaptivePolicy(self.state)
        with operation(emit, "stage_device"):
            self.device = self._device()
        self.dtype = torch.float32
        with operation(emit, "stage_configuration"):
            self.rate, self.hop, self.width, self.layers, self.chunk_seconds, self.capacity_seconds = self._configuration(psutil)
            self.configure_execution()
        with operation(emit, "stage_threads"):
            threads = execution_threads(psutil, self.policy)
            if os.environ.get("YUAN_TRAINER") == "1":
                threads = max(1, min(threads, available_resources(psutil)["cpus"] - 1))
            torch.set_num_threads(threads)
        self.output_rate = self.rate
        with operation(emit, "stage_build"):
            try:
                self.network = self._build().to(self.device, dtype=self.dtype)
            except (RuntimeError, MemoryError) as exc:
                raise YuanFault("模型尚未完成设备分配，保留当前加速后端 / Model device allocation is incomplete; selected backend retained", category="resource" if "memory" in str(exc).casefold() else "compatibility", code="model_device_allocation", device=str(self.device)) from exc
        self.performance_section = self.performance_identity()
        with operation(emit, "stage_restore"):
            self.restore()
            self.network.eval().requires_grad_(False)
        with operation(emit, "stage_release"):
            self.refresh_release()
            if self.playback_ready and self.release_root != self.state and not self.steps and not self.dialogue_trained:
                self.network = copy.deepcopy(self.serving_network).eval().requires_grad_(False)
                self.steps = int(self.serving_manifest.get("steps", 0))
                self.accepted = int(self.serving_manifest.get("accepted", 0))
                self._persist(self.network, self.serving_manifest.get("metrics", {}), self.cancel, increment=False, task="dialogue")
        parameters = sum(value.numel() for value in self.network.parameters())
        self.model_bytes = parameters * torch.finfo(self.dtype).bits // 8
        StorageBudget(self.state).configure(self)
        self.policy.save()
        self.emit("policy", **self.policy.effective)
        self.emit("model", name="Yuan Native Audio", device=str(self.device), dtype=str(self.dtype).replace("torch.", ""),
                  input_rate=self.rate, output_rate=self.output_rate, architecture=f"{self.width}d · {self.layers} latent audio/dialogue layers · {self.hop} samples/frame",
                  identity=self.identity()[:12], mode="ordered prompt + processed audio → Yuan latent dialogue core → autoregressive waveform", size=human_bytes(self.model_bytes), parameters=parameters,
                  accepted=self.accepted, steps=self.steps, acoustic_ready=self.acoustic_ready, dialogue_ready=self.dialogue_ready, playback_ready=self.playback_ready,
                  conversation_verified=self.dialogue_ready, dialogue_trained=self.dialogue_trained, serving_digest=self.serving_digest, capability=self.capability())

    def capability(self):
        if self.service_ready():
            return "dialogue_benchmark_ready" if self.capability_evidence.get("scope") == CapabilityEvidence.dialogue_scope else "dialogue_ready"
        if self.playback_ready and getattr(self, "release_scope", None) == "independently_calibrated_annotated_answer_tasks":
            return "annotated_tasks_only"
        if self.dialogue_trained:
            return "release_wait"
        if self.acoustic_ready:
            return "acoustic_only"
        return "cold_start"

    def _device(self):
        devices = compute_devices(self.torch, self.state, self.emit)
        def score(item):
            device, name = item
            try:
                if device.type in ("cuda", "xpu"):
                    module = getattr(self.torch, device.type)
                    free, total = module.mem_get_info(device)
                    return int(free)
            except (AttributeError, OSError, RuntimeError):
                pass
            return 0
        certificate = read_json(self.state / "compute-verified.json")
        expected_backend = os.environ.get("YUAN_COMPUTE_BACKEND", "")
        if certificate.get("backend") == expected_backend and certificate.get("devices"):
            verified = {item["device"]: item.get("identity_sha256") for item in certificate["devices"]} if certificate.get("build_sha256") == build_digest() else {}
            devices = [item for item in devices if verified.get(str(item[0])) == compute_device_identity(self.torch, item[0], item[1])]
            if not devices:
                raise YuanFault("设备拓扑已变化，将重新验证 / Device topology changed; verification will restart", category="compatibility", code="compute_backend_failed")
        devices.sort(key=score, reverse=True)
        selected = devices[0][0]
        self.accelerators = [{"device": str(device), "name": name} for device, name in devices]
        if selected.type == "cuda":
            self.torch.cuda.set_device(selected)
            self.torch.backends.cudnn.benchmark = True
            self.torch.backends.cuda.matmul.allow_tf32 = True
            self.torch.backends.cudnn.allow_tf32 = True
        if selected.type == "xpu":
            self.torch.xpu.set_device(selected)
        return selected


    def performance_identity(self):
        import psutil
        return "performance:" + payload_digest([platform.system(), platform.machine(), platform.processor(), available_resources(psutil)["cpus"],
                                                   str(self.device), str(self.torch.__version__), self.identity(), str(self.dtype)])

    def training_placement(self, device, learner=None):
        target = self.torch.device(device)
        previous = self.device
        compute_sync(self.torch, previous)
        relocate_network(self.torch, self.network, None, target)
        relocate_network(self.torch, self.serving_network, None, target)
        if learner is not None:
            relocate_network(self.torch, learner.candidate, learner.optimizer, target)
        verifier = getattr(self, "verifier", None)
        if verifier is not None:
            verifier.relocate(target)
        self.device = target
        self.performance_section = self.performance_identity()
        if previous != target:
            self.device_memory_probe = {}
            self.memory_probe_retry_at = 0.0
        if previous != target:
            module = getattr(self.torch, previous.type, None)
            if module is not None and hasattr(module, "empty_cache"):
                module.empty_cache()
        self.emit("compute_placement", device=str(target), serving_device=str(target), verifier_device=str(verifier.device) if verifier else None,
                  candidate_device=str(target) if learner is not None and learner.candidate is not None else None,
                  training_paused=target.type == "cpu" and previous.type != "cpu")

    def switch_device(self, device, cancel, learner=None):
        check(cancel)
        target = self.torch.device(device)
        if learner is not None:
            learner.checkpoint(cancel, force=True)
        self.training_placement(target, learner)
        self.performance_section = self.performance_identity()
        self.capacity_scale = 1.0
        self.training_retry_at = 0.0
        self.training_oom_window = None
        self.input_budget = None
        self.calibrate(cancel, force=True)
        self.emit("model", device=str(target), performance_identity=self.performance_section)

    def _configuration(self, psutil):
        path = safe_path(self.state, "learning/model.json")
        saved = None
        if self.owned_root is not None:
            try:
                supplied = ModelResources.configuration(checked_json(safe_path(self.owned_root, "learning/model.json")))
            except (OSError, ValueError, TypeError, YuanError) as exc:
                raise YuanFault("自有模型结构配置无效 / Invalid owned model configuration", category="integrity", code="model_configuration_invalid") from exc
            ModelResources.validate(supplied, psutil, self.policy)
            if path.exists() and read_json(path) != supplied:
                check(self.cancel)
                archive = safe_path(self.state, "model-states/" + uuid.uuid4().hex)
                archive.parent.mkdir(parents=True, exist_ok=True)
                os.replace(path.parent, archive)
                sync_dir(archive.parent)
            atomic_json(path, supplied, self.cancel)
        if path.exists():
            try:
                saved = ModelResources.configuration(checked_json(path))
            except (ValueError, TypeError, KeyError, OverflowError, YuanError) as exc:
                check(self.cancel)
                archive = safe_path(self.state, "model-states/invalid-" + uuid.uuid4().hex)
                archive.parent.mkdir(parents=True, exist_ok=True)
                os.replace(path.parent, archive)
                sync_dir(archive.parent)
                self.emit("deployment", key="native_bootstrap", recovery="invalid_configuration", reason=concise_error(exc),
                          archived=str(archive.relative_to(self.state)), conversation_verified=False)
            else:
                saved, self.configuration_budget = ModelResources.validate(saved, psutil, self.policy)
        if saved is None:
            source = safe_path(self.state.parent, "Yuan.model.json")
            if os.environ.get("YUAN_PUBLISHER") == "1" and source.is_file():
                saved, self.configuration_budget = ModelResources.validate(checked_json(source), psutil, self.policy)
            else:
                limits = available_resources(psutil)
                cpus = limits["cpus"]
                rate = self.policy.integer("model", "sample_rate", 16000, 8000, 48000)
                seconds = self.policy.number("model", "frame_seconds", 0.01, 1 / rate, 0.04)
                hop = max(1, round(rate * seconds))
                layers = self.policy.integer("model", "layers", max(1, math.isqrt(cpus) // 2), 1, 4)
                saved = {"rate": rate, "hop": hop, "width": 32, "layers": layers}
                saved, self.configuration_budget = ModelResources.validate(saved, psutil, self.policy)
                headroom = self.memory_headroom()
                accelerator = self.device.type in ("cuda", "xpu", "mps") and headroom["measured"]
                fraction = self.policy.ratio("model", "initial_accelerator_memory_fraction", 1 / math.sqrt(len(self.configuration_budget["copies"])))
                device_budget = int(headroom["device_available"] * fraction)
                ceiling = max(32, math.isqrt(max(1, device_budget // ((40 * layers + 48) * 4 * sum(self.configuration_budget["copies"].values()))))) if accelerator else 32 * max(1, math.isqrt(cpus))
                selection_budget = self.policy.number("model", "architecture_selection_seconds", max(1.0, math.sqrt(cpus)), 1.0, max(1.0, math.sqrt(cpus) * 4))
                selection_began = time.monotonic()
                previous_probe = None
                while saved["width"] * 2 <= ceiling and time.monotonic() - selection_began < selection_budget:
                    proposal = {**saved, "width": saved["width"] * 2}
                    try:
                        proposal, estimate = ModelResources.validate(proposal, psutil, self.policy)
                    except YuanFault as exc:
                        if exc.category != "resource":
                            raise
                        break
                    if accelerator:
                        if estimate["required_bytes"] > device_budget:
                            break
                        try:
                            probe = probe_training_components(self.torch, self.np, self.state, self.policy, self.device, proposal, self.cancel, self.emit)
                        except (RuntimeError, MemoryError) as exc:
                            if isinstance(exc, MemoryError) or "out of memory" in str(exc).casefold():
                                self.emit("deployment", key="native_model_created", selection="resource_boundary", device=str(self.device), reason=concise_error(exc), conversation_verified=False)
                                break
                            raise
                        frame_cost = probe["audio_seconds_per_frame"]
                        latency_limit = self.policy.number("model", "initial_frame_compute_seconds", math.sqrt(seconds), seconds, max(seconds, selection_budget))
                        self.policy.observe("architecture:" + str(proposal["width"]), "seconds_per_frame", frame_cost)
                        if frame_cost > latency_limit or previous_probe is not None and frame_cost > previous_probe * math.sqrt(2):
                            break
                        previous_probe = frame_cost
                    saved, self.configuration_budget = proposal, estimate
                saved["width"] = self.policy.integer("model", "width", saved["width"], 32, saved["width"])
                saved, self.configuration_budget = ModelResources.validate(saved, psutil, self.policy)
            atomic_json(path, saved, self.cancel)
            self.emit("deployment", key="native_model_created", automatic=True, configuration=saved, trained=False, conversation_verified=False)
        chunk, capacity = self._execution_limits(psutil, saved["rate"], saved["hop"])
        return saved["rate"], saved["hop"], saved["width"], saved["layers"], chunk, capacity

    def _execution_limits(self, psutil, rate, hop):
        resources = available_resources(psutil)
        gib = max(0.25, resources["memory"] / (1024 ** 3))
        cpu = resources["cpus"]
        baseline = max(2.0, min(math.sqrt(cpu), math.sqrt(gib) * 2))
        chunk = self.policy.number("execution", "chunk_seconds", baseline, hop / rate, max(baseline, math.sqrt(gib * cpu)))
        capacity_default = max(chunk * 3, chunk * 2 * math.sqrt(gib))
        capacity = self.policy.number("execution", "capacity_seconds", capacity_default, chunk, max(capacity_default, chunk * max(4, math.sqrt(gib * cpu))))
        return chunk, capacity

    def _build(self):
        torch, width, hop, layers = self.torch, self.width, self.hop, self.layers
        class Net(torch.nn.Module):
            def __init__(self):
                super().__init__()
                self.prompt = torch.nn.Embedding(256, width)
                self.prompt_recurrent = portable_recurrent(torch, width, width, batch_first=True)
                self.prompt_mix = torch.nn.Sequential(torch.nn.Linear(width, width), torch.nn.Tanh())
                self.roles = torch.nn.Embedding(4, width)
                self.tasks = torch.nn.Embedding(2, width)
                latent = max(1, min(hop, width // 2))
                self.codec_encoder = torch.nn.Sequential(torch.nn.Linear(hop, latent), torch.nn.LayerNorm(latent) if latent > 1 else torch.nn.Identity(), torch.nn.Tanh())
                self.codec_decoder = torch.nn.Sequential(torch.nn.Linear(latent, width), torch.nn.GELU(), torch.nn.Linear(width, hop), torch.nn.Tanh())
                self.frame_encoder = torch.nn.Sequential(torch.nn.Linear(latent, width), torch.nn.LayerNorm(width), torch.nn.GELU(), torch.nn.Linear(width, width), torch.nn.Tanh())
                self.audio_encoder = portable_recurrent(torch, width, width, num_layers=layers, batch_first=True)
                self.memory_projection = torch.nn.Sequential(torch.nn.Linear(width, width), torch.nn.Tanh())
                self.dialogue_core = portable_recurrent(torch, width, width, num_layers=layers, batch_first=True)
                self.decoder_input = torch.nn.Sequential(torch.nn.Linear(latent, width), torch.nn.Tanh())
                self.audio_decoder = portable_recurrent(torch, width, width, num_layers=layers, batch_first=True)
                self.decoder_condition = torch.nn.Sequential(torch.nn.Linear(width, width), torch.nn.Tanh())
                self.output = torch.nn.Linear(width, latent)
                self.ending = torch.nn.Linear(width, 1)
                self.begin = torch.nn.Parameter(torch.zeros(1, 1, hop))
                torch.nn.init.xavier_uniform_(self.output.weight, gain=1 / math.sqrt(width))
                torch.nn.init.zeros_(self.output.bias)
                torch.nn.init.zeros_(self.ending.bias)
            def condition(self, ids, hidden=None):
                _, hidden = self.prompt_recurrent(self.prompt(ids), hidden)
                return hidden
            def initial(self, prompt_hidden, task):
                base = self.prompt_mix(prompt_hidden[-1]) + self.tasks.weight[task].reshape(1, -1)
                return base.unsqueeze(0).expand(layers, -1, -1).contiguous()
            def encode(self, frames, hidden, role, condition=None, audio_state=None, cancel=None, frame_step=None):
                check(cancel)
                values = self.frame_encoder(self.codec_encoder(frames)) + self.roles.weight[role].reshape(1, 1, -1)
                step = max(1, int(frame_step or values.shape[1]))
                pieces = []
                for start in range(0, values.shape[1], step):
                    check(cancel)
                    encoded, audio_state = self.audio_encoder(values[:, start:start + step], audio_state)
                    pieces.append(gradient_checkpoint(encoded, cancel))
                    gradient_checkpoint(audio_state, cancel)
                encoded = torch.cat(pieces, dim=1)
                summary = self.memory_projection(encoded.mean(dim=1, keepdim=True))
                if condition is not None:
                    summary = summary + condition[-1].unsqueeze(1)
                _, hidden = self.dialogue_core(summary, hidden)
                return hidden, audio_state
            def memory(self, frames, role):
                values = self.frame_encoder(self.codec_encoder(frames)) + self.roles.weight[role].reshape(1, 1, -1)
                encoded, hidden = self.audio_encoder(values)
                pooled = self.memory_projection((encoded.mean(dim=1) + hidden[-1]) / 2)
                return torch.nn.functional.normalize(pooled, dim=-1)
            def reconstruct(self, frames):
                return self.codec_decoder(self.codec_encoder(frames))
            def decode(self, previous, hidden, condition=None):
                inputs = self.decoder_input(self.codec_encoder(previous))
                if condition is not None:
                    inputs = inputs + self.decoder_condition(condition[-1]).unsqueeze(1)
                values, hidden = self.audio_decoder(inputs, hidden)
                return self.codec_decoder(torch.tanh(self.output(values))), self.ending(values).squeeze(-1), hidden
        return Net()

    @contextmanager
    def interruptible(self, cancel):
        previous = self.cancel
        self.cancel = cancel
        try:
            check(cancel)
            yield
        finally:
            self.cancel = previous

    def capacity(self):
        sample_bytes = self.np.dtype(self.np.float32).itemsize
        headroom = self.memory_headroom()
        available = min(headroom["host_available"], headroom["device_available"]) if headroom["measured"] else headroom["host_available"]
        memory_bound = available // max(sample_bytes * 24, self.width * sample_bytes)
        configured = int(self.rate * self.capacity_seconds * self.capacity_scale)
        return max(self.hop * 2, min(configured, int(memory_bound)))

    def window(self):
        configured = getattr(self, "training_window_samples", int(self.rate * self.chunk_seconds / 2))
        bounded = min(self.capacity() // 4, configured)
        return max(self.hop * 2, int(bounded) // self.hop * self.hop)

    def memory_window(self):
        capacity = self.capacity()
        seconds = self.policy.number("memory", "segment_seconds", capacity / self.rate / 4,
                                     self.hop * 2 / self.rate, max(self.hop * 2 / self.rate, capacity / self.rate))
        return max(self.hop * 2, min(capacity, int(seconds * self.rate)) // self.hop * self.hop)

    def configure_execution(self):
        frame = self.hop / self.rate
        baseline = math.sqrt(frame * max(frame, self.chunk_seconds))
        self.compute_quantum_seconds = self.policy.number("execution", "interactive_yield_seconds", baseline, frame,
                                                         max(baseline, self.chunk_seconds))
        seconds = self.policy.number("learning", "training_window_seconds", self.chunk_seconds / 2,
                                     frame * 2, max(frame * 2, self.capacity_seconds / 4))
        self.training_window_samples = max(self.hop * 2, int(seconds * self.rate) // self.hop * self.hop)
        seconds = self.policy.number("inference", "stream_block_seconds", max(frame, math.sqrt(frame)),
                                     frame, max(frame, self.capacity_seconds))
        self.decode_block_frames = max(1, int(round(seconds / frame)))

    def memory_headroom(self):
        import psutil
        host = available_resources(psutil)["memory"]
        available = host if self.device.type == "cpu" else 0
        measured = self.device.type == "cpu"
        evidence = "host_measurement" if measured else "unknown"
        reason = None
        try:
            if self.device.type in ("cuda", "xpu"):
                module = getattr(self.torch, self.device.type)
                free, total = module.mem_get_info(self.device)
                cached = max(0, module.memory_reserved(self.device) - module.memory_allocated(self.device))
                available = max(0, min(int(total), int(free + cached)))
                measured, evidence = True, "device_measurement"
            elif self.device.type == "mps":
                mps = self.torch.mps
                maximum = int(mps.recommended_max_memory())
                current = int(mps.current_allocated_memory())
                available = min(host, max(0, maximum - current))
                measured, evidence = True, "device_measurement"
            elif self.device.type != "cpu":
                reason = "设备内存查询尚无直接测量，训练预算将独立探测 / Device memory has no direct measurement; training budget will be probed independently"
        except (AttributeError, RuntimeError, OSError, NotImplementedError) as exc:
            available, measured, evidence = 0, False, "unknown"
            reason = concise_error(exc)
        return {"device": str(self.device), "host_available": host, "device_available": available,
                "measured": measured, "memory_evidence": evidence, "reason": reason}

    def probe_training_budget(self, required, resident, cancel):
        config = {key: getattr(self, key) for key in ("rate", "hop", "width", "layers")}
        identity = payload_digest([str(self.device), config, self.performance_section])
        now = time.monotonic()
        cache = getattr(self, "device_memory_probe", {})
        baseline = max(self.capacity_seconds, self.policy.measured(self.performance_section, "training_seconds_per_frame", 0.0) * self.window() / self.hop)
        lifetime = self.policy.number("learning", "memory_probe_valid_seconds", baseline, self.chunk_seconds, max(baseline, self.capacity_seconds * self.layers))
        if (cache.get("identity") == identity and cache.get("verified") is True and now < cache.get("expires", 0)
                and cache.get("allocation_bytes", 0) + cache.get("resident_bytes", 0) >= required + resident):
            return cache
        if now < getattr(self, "memory_probe_retry_at", 0.0):
            return {"verified": False, "reason": "resource_probe_cooldown"}
        try:
            result = probe_device_memory(self.state, self.device, config, required, cancel, self.policy, self.emit)
        except Cancelled:
            raise
        except (OSError, RuntimeError, ValueError, YuanError, MemoryError) as exc:
            delay = self.policy.number("learning", "memory_probe_retry_seconds", max(self.chunk_seconds, math.sqrt(self.capacity_seconds)),
                                       self.hop / self.rate, max(self.chunk_seconds, self.capacity_seconds))
            self.memory_probe_retry_at = time.monotonic() + delay
            self.training_window_samples = max(self.hop * 2, int(self.window() / math.sqrt(2)) // self.hop * self.hop)
            self.device_memory_probe = {"verified": False, "reason": concise_error(exc), "retry_seconds": delay}
            self.emit("learning_memory", device=str(self.device), memory_evidence="unknown", **self.device_memory_probe)
            return self.device_memory_probe
        result.update(identity=identity, resident_bytes=resident, expires=time.monotonic() + lifetime)
        self.device_memory_probe = result
        self.memory_probe_retry_at = 0.0
        return result

    def training_budget(self, learner=None):
        headroom = self.memory_headroom()
        candidate = getattr(learner, "candidate", None)
        optimizer = getattr(learner, "optimizer", None)
        resident = 0
        if candidate is not None:
            for value in candidate.parameters():
                resident += value.numel() * value.element_size()
                if value.grad is not None:
                    resident += value.grad.numel() * value.grad.element_size()
        if optimizer is not None:
            for state in optimizer.state.values():
                for value in state.values():
                    if isinstance(value, self.torch.Tensor) and value.device.type == self.device.type:
                        resident += value.numel() * value.element_size()
        copies = {"candidate": 1, "gradient": 1, "moments": 2, "promotion": 1, "restore": 1}
        fixed = max(0, self.model_bytes * sum(copies.values()) - resident)
        retrieval = learner.retrieval_plan(self.cancel) if learner is not None and hasattr(learner, "retrieval_plan") else {"samples": 0}
        frames = max(self.width, math.ceil((self.window() + retrieval["samples"]) / self.hop))
        estimate = self.width * self.layers * self.np.dtype(self.np.float32).itemsize * 72
        per_frame = self.policy.measured(getattr(self, "performance_section", "performance"), "training_bytes_per_frame", estimate)
        variable = math.ceil(frames * max(estimate, per_frame))
        required = fixed + variable
        host_required = self.model_bytes * 2 + (self.window() + retrieval["samples"]) * self.np.dtype(self.np.float32).itemsize * 4
        cooling = time.monotonic() < self.training_retry_at
        probe = {}
        if not headroom["measured"] and headroom["host_available"] >= host_required and not cooling:
            probe = self.probe_training_budget(required, resident, self.cancel)
        verified = headroom["measured"] and headroom["device_available"] >= required
        verified = verified or probe.get("verified") is True
        return {**headroom, "fixed_bytes": fixed, "activation_bytes": variable, "required_bytes": required, "host_required_bytes": host_required,
                "minimum_bytes": fixed + self.width * max(estimate, per_frame), "cooldown": cooling,
                "memory_evidence": "allocation_probe" if probe.get("verified") else headroom["memory_evidence"], "allocation_probe": probe,
                "ready": bool(verified and headroom["host_available"] >= host_required and not cooling)}

    def recover_training_memory(self, learner):
        import gc
        previous = self.window()
        unchanged = self.training_oom_window == previous
        self.training_oom_window = previous
        self.device_memory_probe = {}
        self.memory_probe_retry_at = 0.0
        self.training_window_samples = max(self.hop * 2, int(previous / math.sqrt(2)) // self.hop * self.hop)
        learner.candidate = learner.optimizer = None
        learner.dirty = False
        gc.collect()
        try:
            if self.device.type == "cuda":
                self.torch.cuda.empty_cache()
            elif self.device.type == "mps":
                self.torch.mps.empty_cache()
        except (AttributeError, RuntimeError):
            pass
        minimum = self.hop * 2
        base_capacity = max(minimum, int(self.rate * self.capacity_seconds))
        floor = min(1.0, minimum * 4 / base_capacity)
        self.capacity_scale = max(floor, self.capacity_scale / math.sqrt(2))
        current = self.window()
        bounded = current >= previous or unchanged
        delay = self.policy.number("learning", "memory_retry_seconds", max(self.chunk_seconds, math.sqrt(self.capacity_seconds)), self.hop / self.rate, max(self.chunk_seconds, self.capacity_seconds))
        self.training_retry_at = time.monotonic() + delay if bounded else 0.0
        self.emit("learning", key="memory_fixed_pause" if bounded else "memory_reduced", previous_window=previous, window=current, device=str(self.device), retry_seconds=delay if bounded else 0.0, **learner._state())

    def normalize(self, waveform, rate):
        processed = AudioPreprocessor(rate, self.rate).process(waveform, final=True)
        if not processed.size:
            raise InvalidAudio("输入音频为空 / Input audio is empty")
        return processed

    def _prompt_ids(self, prompt):
        import psutil
        data = str(prompt).encode("utf-8") or b"\0"
        budget = max(self.width, available_resources(psutil)["memory"] // max(1, self.width * self.torch.tensor([], dtype=self.dtype).element_size() * 16))
        if len(data) > budget:
            raise YuanError("提示词超过当前内存预算 / Instructions exceed the current memory budget")
        values = self.np.frombuffer(data, dtype=self.np.uint8).astype(self.np.int64)
        return self.torch.from_numpy(values).to(self.device).reshape(1, -1)

    def _frames(self, waveform):
        torch = self.torch
        np = self.np
        values = np.asarray(waveform, dtype=np.float32).reshape(-1)
        missing = (-len(values)) % self.hop
        if missing:
            values = np.pad(values, (0, missing))
        tensor = torch.from_numpy(values.copy()).to(self.device, dtype=self.dtype).reshape(1, -1, self.hop)
        return tensor, len(waveform)

    def audio_blocks(self, waveform, cancel=None):
        step = max(self.hop, min(self.width * self.hop, self.window() // self.hop * self.hop))
        if isinstance(waveform, AudioSequence):
            yield from waveform.blocks(step, cancel)
        else:
            values = self.np.asarray(waveform, dtype=self.np.float32)
            if values.ndim != 1 or not self.np.isfinite(values).all():
                raise InvalidAudio("模型输入音频无效 / Invalid model audio input")
            for start in range(0, len(values), step):
                check(cancel)
                yield values[start:start + step]

    def _encode_audio(self, network, waveform, hidden, role, cancel, pending=None, final=True, condition=None, audio_state=None):
        np, torch = self.np, self.torch
        pending = np.empty(0, dtype=np.float32) if pending is None else pending
        total = len(waveform) + len(pending)
        consumed = 0
        compute = CooperativeCompute(self, "audio_encoder")
        block_samples = self.width * self.hop
        gradient_window = max(block_samples, self.window() // self.hop * self.hop)
        training = torch.is_grad_enabled()
        for values in self.audio_blocks(waveform, cancel):
            check(cancel)
            values = np.concatenate((pending, values)) if len(pending) else values
            count = len(values) // block_samples * block_samples
            pending = values[count:].copy()
            if not count:
                continue
            consumed += count
            track = training and consumed > max(0, total - gradient_window)
            with torch.set_grad_enabled(track):
                if not track:
                    hidden = hidden.detach()
                    if audio_state is not None:
                        audio_state = audio_state.detach()
                frames, _ = self._frames(values[:count])
                hidden, audio_state = compute.run(lambda: network.encode(frames, hidden, self.role_index(role), condition, audio_state, cancel=cancel, frame_step=compute.frames(frames.shape[1])), frames.shape[1], cancel)
        if final and len(pending):
            check(cancel)
            frames, _ = self._frames(pending)
            hidden, audio_state = compute.run(lambda: network.encode(frames, hidden, self.role_index(role), condition, audio_state, cancel=cancel, frame_step=compute.frames(frames.shape[1])), frames.shape[1], cancel)
            pending = np.empty(0, dtype=np.float32)
        return hidden, pending, audio_state

    def _prompt_condition(self, network, prompt, cancel, task):
        ids = self._prompt_ids(prompt)
        prompt_hidden = None
        step = max(1, self.width)
        checkpointed = self.torch.is_grad_enabled() and ids.shape[1] > step
        if checkpointed:
            from torch.utils.checkpoint import checkpoint
        def condition(block, hidden):
            check(cancel)
            return network.condition(block, hidden)
        for start in range(0, ids.shape[1], step):
            check(cancel)
            block = ids[:, start:start + step]
            if checkpointed:
                prompt_hidden = checkpoint(condition, block, prompt_hidden, use_reentrant=False)
            else:
                prompt_hidden = condition(block, prompt_hidden)
        return network.initial(prompt_hidden, int(task == "dialogue"))

    def _encode(self, network, prompt, waveform, context=(), cancel=None, task="dialogue", condition=None, recalled=(), incoming_count=None, context_id=None):
        condition = self._prompt_condition(network, prompt, cancel, task) if condition is None else condition
        hidden = condition
        context = self._history_budget(context, len(waveform) if incoming_count is None else incoming_count, recalled, context_id)
        for role, audio in (*context, ("user", waveform)):
            if len(audio):
                hidden, pending, encoder = self._encode_audio(network, audio, hidden, role, cancel, condition=condition)
        return hidden

    def memory_embedding(self, network, waveform, role="user", cancel=None):
        np, torch = self.np, self.torch
        if not len(waveform):
            raise InvalidAudio("音频记忆输入为空 / Audio memory input is empty")
        block_samples = max(1, self.width) * self.hop
        pending = np.empty(0, dtype=np.float32)
        total, count = None, 0
        for values in self.audio_blocks(waveform, cancel):
            check(cancel)
            values = np.concatenate((pending, values)) if len(pending) else values
            complete = len(values) // block_samples * block_samples
            for start in range(0, complete, block_samples):
                check(cancel)
                frames, _ = self._frames(values[start:start + block_samples])
                vector = gradient_checkpoint(network.memory(frames, self.role_index(role)), cancel)
                total = vector if total is None else total + vector
                count += 1
            pending = values[complete:].copy()
        if len(pending):
            check(cancel)
            frames, _ = self._frames(pending)
            vector = gradient_checkpoint(network.memory(frames, self.role_index(role)), cancel)
            total = vector if total is None else total + vector
            count += 1
        if total is None:
            raise InvalidAudio("音频记忆输入为空 / Audio memory input is empty")
        check(cancel)
        return torch.nn.functional.normalize(total / count, dim=-1)

    @supervised('memory_encoding', 'runtime')
    def memory_vector(self, waveform, role="user", cancel=None):
        np, torch = self.np, self.torch
        network = self.serving_network if self.playback_ready and self.serving_network is not None else self.network
        network.eval()
        with self.interruptible(cancel), torch.inference_mode():
            vector = self.memory_embedding(network, waveform, role, cancel)
            values = vector.reshape(-1).detach().float().cpu().numpy().copy()
        if not values.size or not np.isfinite(values).all():
            raise YuanError("音频记忆向量无效 / Invalid audio memory vector")
        return np.ascontiguousarray(values, dtype=np.float32)

    def reply_samples(self, incoming, history=()):
        capacity = self.capacity()
        fraction = self.policy.ratio("inference", "reply_capacity_fraction", 0.5)
        seconds = self.policy.number("inference", "reply_max_seconds", capacity * fraction / self.rate, self.hop / self.rate, capacity / self.rate)
        return max(self.hop, min(capacity, int(seconds * self.rate / self.hop) * self.hop))

    def _decode(self, network, hidden, count, cancel=None, stop=True, phase=False, previous=None, condition=None):
        torch = self.torch
        previous = network.begin if previous is None else previous
        condition = hidden if condition is None else condition
        pieces = []
        total = max(1, math.ceil(count / self.hop))
        last = 0.0
        stopped = False
        for frame in range(total):
            check(cancel)
            predicted, ending, hidden = gradient_checkpoint(network.decode(previous, hidden, condition), cancel)
            if not torch.isfinite(predicted).all() or not torch.isfinite(ending).all():
                raise YuanError("模型输出含无效数值 / Model output contains invalid values")
            pieces.append(predicted)
            previous = predicted
            now = time.monotonic()
            if phase and (now - last >= math.sqrt(self.hop / self.rate) or frame + 1 == total):
                self.emit("phase", key="generating", current=frame + 1, total=total, unit="frames")
                last = now
            if stop and ending.item() > 0:
                stopped = True
                break
        if phase and stop:
            self.emit("generation_end", key="natural_end" if stopped else "limited", natural=stopped, limited=not stopped, frames=len(pieces), samples=min(count, len(pieces) * self.hop))
            if not stopped:
                self.emit("notice", key="limited", component="generation")
        return torch.cat(pieces, dim=1).reshape(1, -1)[:, :count]

    def respond_audio(self, prompt, history, waveform, cancel, max_samples=None, network=None, evaluation=None):
        pieces = list(self.stream_audio(prompt, history, waveform, cancel, max_samples=max_samples, network=network, evaluation=evaluation))
        check(cancel)
        if not pieces:
            raise YuanError("模型未产生有效音频 / Model produced no valid audio")
        return self.np.ascontiguousarray(self.np.concatenate(pieces), dtype=self.np.float32)

    def _acoustic_loss(self, prediction, target):
        torch = self.torch
        destination = prediction.device
        if destination.type in ("privateuseone", "mps"):
            prediction, target = prediction.to("cpu"), target.to("cpu")
        waveform = torch.nn.functional.smooth_l1_loss(prediction, target)
        motion = torch.nn.functional.smooth_l1_loss(prediction[:, 1:] - prediction[:, :-1], target[:, 1:] - target[:, :-1]) if target.shape[1] > 1 else waveform * 0
        spectra = []
        maximum = min(target.shape[1], self.hop * max(2, self.layers + 1))
        size = self.hop
        while size <= maximum:
            window = torch.hann_window(size, device=prediction.device, dtype=prediction.dtype)
            left = prediction.unfold(-1, size, max(1, size // 2)) * window
            right = target.unfold(-1, size, max(1, size // 2)) * window
            left = torch.log1p(torch.abs(torch.fft.rfft(left, dim=-1)))
            right = torch.log1p(torch.abs(torch.fft.rfft(right, dim=-1)))
            spectra.append(torch.nn.functional.smooth_l1_loss(left, right))
            size *= 2
        spectrum = sum(spectra) / len(spectra) if spectra else waveform * 0
        return (waveform + motion + spectrum).to(destination)

    def loss(self, network, prompt, source, target, ended=False, context=(), rollout=False, task="acoustic", prefix=None, end_label_valid=False, contrasts=(), rollout_frames=None, rollout_weight=1.0):
        torch = self.torch
        check(self.cancel)
        n = min(len(target), self.window())
        if n < self.hop or len(source) < self.hop:
            raise YuanError("音频样本过短，无法学习 / Audio sample is too short to learn from")
        phase = self.training_phase()
        codec_frames, _ = self._frames(target[:n])
        reconstructed = network.reconstruct(codec_frames).reshape(1, -1)[:, :n]
        codec_loss = self._acoustic_loss(reconstructed, codec_frames.reshape(1, -1)[:, :n])
        if phase == "representation":
            self.loss_components = {"representation": float(codec_loss.detach().item()), "stage": phase, "semantic_acceptance": False}
            return codec_loss
        condition = self._encode(network, prompt, source, context, self.cancel, task=task)
        hidden = condition
        seed = network.begin
        if prefix is not None:
            with torch.no_grad():
                for audio in prefix():
                    check(self.cancel)
                    if len(audio) % self.hop:
                        raise YuanError("回复前缀没有按帧对齐 / Reply prefix is not frame aligned")
                    prefix_frames, _ = self._frames(audio)
                    previous_frames = torch.cat((seed, prefix_frames[:, :-1]), dim=1)
                    for offset in range(0, previous_frames.shape[1], max(1, self.width)):
                        check(self.cancel)
                        _, _, hidden = network.decode(previous_frames[:, offset:offset + self.width], hidden, condition.detach())
                    seed = prefix_frames[:, -1:]
                hidden = hidden.detach()
                seed = seed.detach()
        target_frames, _ = self._frames(target[:n])
        previous = torch.cat((seed, target_frames[:, :-1]), dim=1)
        predictions = []
        endings = []
        compute = CooperativeCompute(self, "audio_decoder")
        step = compute.frames(self.width)
        current_hidden = hidden
        for start in range(0, previous.shape[1], step):
            check(self.cancel)
            block = previous[:, start:start + step]
            predicted, ending, current_hidden = compute.run(lambda: network.decode(block, current_hidden, condition), block.shape[1], self.cancel)
            predictions.append(predicted)
            endings.append(ending)
        prediction = torch.cat(predictions, dim=1).reshape(1, -1)[:, :n]
        target_tensor = target_frames.reshape(1, -1)[:, :n]
        loss = self._acoustic_loss(prediction, target_tensor) + codec_loss
        if end_label_valid:
            end_logits = torch.cat(endings, dim=1)
            end_target = torch.zeros_like(end_logits)
            if ended and n == len(target):
                end_target[:, -1] = 1
            end_loss = torch.nn.functional.binary_cross_entropy_with_logits(end_logits, end_target)
            loss = loss + end_loss / math.sqrt(max(1, n / self.hop))
        free_loss = loss.new_zeros(())
        free_count = 0
        if rollout:
            if isinstance(rollout_weight, bool) or not isinstance(rollout_weight, (int, float)) or not math.isfinite(rollout_weight) or not 0 <= rollout_weight <= 1:
                raise YuanError("自回归训练权重无效 / Invalid autoregressive training weight")
            if rollout_frames is not None and (type(rollout_frames) is not int or rollout_frames < 1):
                raise YuanError("自回归训练窗口无效 / Invalid autoregressive training window")
            free_count = n if rollout_frames is None else min(n, rollout_frames * self.hop)
            free_hidden, free_previous = hidden, seed
            free_predictions, free_endings = [], []
            for offset in range(math.ceil(free_count / self.hop)):
                check(self.cancel)
                predicted, ending, free_hidden = gradient_checkpoint(network.decode(free_previous, free_hidden, condition), self.cancel)
                free_predictions.append(predicted)
                free_endings.append(ending)
                free_previous = predicted
            free = torch.cat(free_predictions, dim=1).reshape(1, -1)[:, :free_count]
            free_loss = self._acoustic_loss(free, target_tensor[:, :free_count])
            if end_label_valid:
                logits = torch.cat(free_endings, dim=1)
                labels = torch.zeros_like(logits)
                if ended and free_count == len(target):
                    labels[:, -1] = 1
                free_loss = free_loss + torch.nn.functional.binary_cross_entropy_with_logits(logits, labels) / math.sqrt(max(1, free_count / self.hop))
            loss = loss + rollout_weight * free_loss
        reconstruction = loss
        contrast_loss = loss.new_zeros(())
        if task == "dialogue" and prefix is None and contrasts:
            scale = reconstruction.detach().abs().clamp_min(math.sqrt(torch.finfo(self.dtype).eps)) / math.sqrt(max(1, n / self.hop))
            for alternative in contrasts:
                check(self.cancel)
                wrong_condition = self._encode(network, alternative["prompt"], alternative["source"], alternative["context"], self.cancel, task=task)
                wrong_hidden = wrong_condition
                predictions = []
                for start in range(0, previous.shape[1], step):
                    check(self.cancel)
                    block = previous[:, start:start + step]
                    predicted, ending, wrong_hidden = compute.run(lambda: network.decode(block, wrong_hidden, wrong_condition), block.shape[1], self.cancel)
                    predictions.append(predicted)
                wrong = torch.cat(predictions, dim=1).reshape(1, -1)[:, :n]
                wrong_error = self._acoustic_loss(wrong, target_tensor)
                positive_error = self._acoustic_loss(prediction, target_tensor)
                contrast_loss = contrast_loss + torch.nn.functional.softplus((positive_error - wrong_error) / scale) * scale
            loss = loss + contrast_loss / len(contrasts)
        self.loss_components = {"representation": float(codec_loss.detach().item()), "curriculum_phase": phase, "reconstruction": float(reconstruction.detach().item()), "conditioning": float(contrast_loss.detach().item()),
                                "rollout": float(free_loss.detach().item()), "rollout_samples": free_count,
                                "rollout_weight": float(rollout_weight) if rollout else 0.0,
                                "stage": "conditioning_contrasts" if contrasts else "conditional_reply" if task == "dialogue" else "acoustic"}
        return loss

    def training_phase(self):
        manifest = getattr(self, "training_manifest", None) or {}
        phase = manifest.get("curriculum", {}).get("phase", "representation")
        if phase not in ("representation", "acoustic", "conditional_dialogue", "multi_turn"):
            raise YuanError("训练阶段无效 / Invalid training phase")
        return phase

    def clone(self):
        budget = self.training_budget()
        if not budget["ready"]:
            raise YuanFault("候选模型分配前资源不足 / Insufficient resources before candidate allocation", category="resource", code="candidate_memory_insufficient", **budget)
        return copy.deepcopy(self.network).to(self.device, dtype=self.dtype)

    def identity(self):
        payload = ["yuan-owned-audio-codec-v8-staged-training", self.rate, self.hop, self.width, self.layers]
        return hashlib.sha256(json.dumps(payload, separators=(",", ":")).encode()).hexdigest()

    def _load_network(self, manifest, cancel=None, state=None):
        if not isinstance(manifest, dict) or manifest.get("identity") != self.identity() or not is_digest(manifest.get("sha256")):
            raise YuanError("模型结构或摘要不匹配，原文件已保留 / Model architecture or digest mismatch; originals retained")
        directory = safe_path(self.state if state is None else state, "learning")
        path = safe_path(directory, manifest["file"])
        if path.suffix != ".pt" or digest_file(path, cancel) != manifest["sha256"]:
            raise YuanError("模型完整性校验失败 / Model integrity validation failed")
        import psutil
        config = {key: getattr(self, key) for key in ("rate", "hop", "width", "layers")}
        ModelResources.validate(config, psutil, self.policy)
        maximum = ModelResources.estimate(config)["weight_bytes"] * 2
        ModelResources.checkpoint(path, maximum)
        weights = self.torch.load(str(path), map_location="cpu", weights_only=True)
        if not isinstance(weights, dict) or not weights or not all(isinstance(value, self.torch.Tensor) and self.torch.isfinite(value).all() for value in weights.values()):
            raise YuanError("模型权重无效 / Invalid model weights")
        network = self._build()
        network.load_state_dict(weights, strict=True)
        return network.to(self.device, dtype=self.dtype).eval().requires_grad_(False)

    @staticmethod
    def _checkpoint_failure(exc):
        current, seen = exc, set()
        while current is not None and id(current) not in seen:
            seen.add(id(current))
            if (isinstance(current, (Cancelled, MemoryError))
                    or isinstance(current, OSError) and not isinstance(current, FileNotFoundError)
                    or isinstance(current, YuanFault) and current.category in ("resource", "storage", "timeout")
                    or isinstance(current, RuntimeError) and "out of memory" in str(current).casefold()):
                raise exc
            current = current.__cause__ or current.__context__
        return concise_error(exc)

    def _training_manifest(self, manifest):
        if (not isinstance(manifest, dict) or manifest.get("identity") != self.identity()
                or not is_digest(manifest.get("sha256")) or not isinstance(manifest.get("file"), str)
                or Path(manifest["file"]).name != manifest["file"] or not manifest["file"].endswith(".pt")
                or any(type(manifest.get(key)) is not int or manifest[key] < 0 for key in ("steps", "accepted"))):
            raise YuanError("模型检查点记录无效 / Invalid model checkpoint record")
        curriculum = manifest.get("curriculum", {})
        if (not isinstance(curriculum, dict) or curriculum.get("phase", "representation") not in ("representation", "acoustic", "conditional_dialogue", "multi_turn")
                or not isinstance(curriculum.get("validated", {}), dict)):
            raise YuanError("模型训练阶段记录无效 / Invalid model curriculum record")
        return manifest

    def _quarantine_training(self, cancel):
        directory = safe_path(self.state, "learning")
        protected = set()
        for name in ("release.json", "pending-review.json", "previous-release.json"):
            pointer = read_json(directory / name)
            try:
                evaluation = read_json(safe_path(directory, pointer["evaluation_file"]))
                protected.add(evaluation["model"]["file"])
            except (KeyError, TypeError, YuanError):
                continue
        files = [path for pattern in ("model-*.pt", "model-*.json", "active.json", "previous.json") for path in directory.glob(pattern)
                 if path.is_file() and not path.is_symlink() and path.name not in protected
                 and not (path.suffix == ".json" and path.with_suffix(".pt").name in protected)]
        if not files:
            return
        destination = safe_path(directory, "recovery/" + uuid.uuid4().hex)
        destination.mkdir(parents=True, exist_ok=False)
        for path in files:
            check(cancel)
            os.replace(path, destination / path.name)
        sync_dir(destination)
        sync_dir(directory)
        StorageBudget(self.state).reclaim_recovery(cancel)

    def restore(self):
        directory = safe_path(self.state, "learning")
        directory.mkdir(parents=True, exist_ok=True)
        self.training_manifest = None
        if self._resume_training_activation(cancel=self.cancel):
            return
        failures = []
        paths = [directory / name for name in ("active.json", "previous.json")]
        paths.extend(sorted(directory.glob("model-*.json"), key=lambda path: path.stat().st_mtime_ns, reverse=True))
        for path in paths:
            check(self.cancel)
            if not path.exists():
                continue
            try:
                manifest = self._training_manifest(checked_json(path))
                if path.name not in ("active.json", "previous.json"):
                    provenance = manifest.get("training_provenance", {})
                    if (not isinstance(provenance, dict) or provenance.get("owner") != APP_NAME
                            or provenance.get("external_model") is not False or provenance.get("text_to_speech") is not False
                            or provenance.get("build_sha256") != build_digest() or path.with_suffix(".pt").name != manifest["file"]):
                        raise YuanError("备用检查点缺少当前版本来源证明 / Fallback checkpoint lacks current-build provenance")
                    metrics = manifest.get("metrics", {})
                    validation_store = AudioStore(self.state, recover=False)
                    try:
                        if not validation_store.validation_current(metrics):
                            raise YuanError("备用检查点依赖的数据已经修订 / Fallback checkpoint depends on revised data")
                    finally:
                        validation_store.close()
                if manifest.get("training_provenance", {}).get("build_sha256") != build_digest():
                    raise YuanError("不加载其他版本产生的模型 / Models from other code versions are not loaded")
                network = self._load_network(manifest, self.cancel)
            except Cancelled:
                raise
            except Exception as exc:
                failures.append(self._checkpoint_failure(exc))
                self.emit("notice", key="checkpoint_failure", file=path.name, reason=failures[-1])
                continue
            check(self.cancel)
            self._publish_training(manifest, None, network, self.cancel)
            if path.name != "active.json":
                self.emit("notice", key="model_recovered", file=manifest["file"], failures=failures)
            return
        if failures or any(directory.glob("model-*.pt")):
            self._quarantine_training(self.cancel)
            self.emit("notice", key="native_bootstrap", recovery="no_usable_checkpoint", failures=failures, conversation_verified=False)
        self.steps = self.accepted = 0
        self.acoustic_ready = self.dialogue_trained = False
        self.active_digest = None
        if self.owned_root is None:
            self._persist(self.network, {}, self.cancel, increment=False, task=None)

    @supervised('model_persist', 'learning')
    def _persist(self, network, metrics, cancel, increment, task, store=None):
        if store is not None and store.db.in_transaction:
            raise YuanError("模型文件必须在数据库写事务之外保存 / Model files must be saved outside database write transactions")
        directory = safe_path(self.state, "learning")
        directory.mkdir(parents=True, exist_ok=True)
        name = "model-" + uuid.uuid4().hex + ".pt"
        target = directory / name
        temporary = target.with_suffix(".partial")
        sidecar = target.with_suffix(".json")
        check(cancel)
        committed = False
        baseline = self.active_digest
        previous = getattr(self, "training_manifest", None)
        phase = self.training_phase()
        stage = metrics.get("phase_readiness", {})
        phase_ready = metrics.get("phase_ready") is True and stage.get("ready") is True and stage.get("phase") == phase
        acoustic_ready = self.acoustic_ready or task == "acoustic" and phase == "acoustic" and phase_ready
        dialogue_trained = self.dialogue_trained or task == "dialogue" and metrics.get("regression", {}).get("passed") is True
        with StorageBudget(self.state).reserve(max(1, sum(value.numel() * value.element_size() for value in network.parameters()) * 2), "checkpoint"):
            try:
                saved = {key: value.detach().cpu().contiguous() for key, value in network.state_dict().items()}
                if not all(self.torch.isfinite(value).all() for value in saved.values()):
                    raise YuanError("拒绝保存无效模型权重 / Refusing to save invalid model weights")
                save_checkpoint(self.torch, saved, temporary, cancel, self.width * self.hop * 4)
                with temporary.open("rb") as stream:
                    os.fsync(stream.fileno())
                check(cancel)
                verified = self.torch.load(str(temporary), map_location="cpu", weights_only=True)
                if set(verified) != set(saved) or any(not self.torch.equal(verified[key], value) for key, value in saved.items()):
                    raise YuanError("模型写入后校验失败 / Model post-write verification failed")
                os.replace(temporary, target)
                sync_dir(directory)
                accepted = self.accepted + int(bool(increment))
                checksum = digest_file(target, cancel)
                manifest = {"identity": self.identity(), "file": name, "sha256": checksum, "steps": self.steps,
                            "accepted": accepted, "metrics": metrics, "acoustic_ready": acoustic_ready,
                            "dialogue_trained": dialogue_trained, "created": time.time()}
                curriculum = copy.deepcopy((previous or {}).get("curriculum", {"phase": "representation", "validated": {}}))
                if (metrics.get("training_validated") is True and phase_ready
                        and ((phase in ("representation", "acoustic") and task == "acoustic")
                             or (phase in ("conditional_dialogue", "multi_turn") and task == "dialogue"))
                        and (phase != "multi_turn" or metrics.get("regression", {}).get("passed") is True)):
                    next_phase = {"representation": "acoustic", "acoustic": "conditional_dialogue", "conditional_dialogue": "multi_turn", "multi_turn": "multi_turn"}[phase]
                    curriculum["validated"][phase] = {"model_sha256": checksum, "model_file": name, "data_evidence_sha256": metrics.get("data_evidence_sha256"),
                                                        "validation": metrics.get("validation_comparison"), "guard": metrics.get("guard_comparison"),
                                                        "proficiency": copy.deepcopy(stage)}
                    curriculum["phase"] = next_phase
                manifest["curriculum"] = curriculum
                prior = previous or getattr(self, "serving_manifest", {})
                prior_provenance = prior.get("training_provenance", {}) if isinstance(prior, dict) else {}
                manifest["training_provenance"] = {"owner": APP_NAME, "self_trained": bool(task in ("acoustic", "dialogue") and self.steps > 0 or prior_provenance.get("self_trained") is True),
                                                   "external_model": False, "text_to_speech": False,
                                                   "origin": "yuan-native-network", "parent_model": prior.get("sha256") if isinstance(prior, dict) else None,
                                                   "build_sha256": build_digest(), "data_revision": metrics.get("data_revision"),
                                                   "lineage_sha256": payload_digest([prior_provenance.get("lineage_sha256"), checksum, self.steps, metrics])}
                atomic_json(sidecar, manifest, cancel)
                if store is not None:
                    check(cancel)
                    with store.transaction():
                        if not store.validation_current(metrics) or self.active_digest != baseline:
                            return False
                        if store.setting("pending_training_activation"):
                            raise YuanError("上次模型更新尚未完成恢复 / The previous model update still needs recovery")
                        store.set_setting("pending_training_activation", {"manifest": manifest, "previous": previous})
                    committed = True
                self._publish_training(manifest, previous, network, cancel)
                committed = True
                if store is not None:
                    store.set_setting("pending_training_activation", None)
            finally:
                temporary.unlink(missing_ok=True)
                if not committed:
                    target.unlink(missing_ok=True)
                    sidecar.unlink(missing_ok=True)
            try:
                self._prune_models()
            except (OSError, ValueError, TypeError, YuanError) as exc:
                self.emit("notice", reason=concise_error(exc), component="checkpoint_cleanup")
        return True

    def _publish_training(self, manifest, previous, network, cancel):
        steps, accepted = manifest.get("steps"), manifest.get("accepted")
        if any(isinstance(value, bool) or not isinstance(value, int) or value < 0 for value in (steps, accepted)):
            raise YuanError("模型训练计数无效 / Invalid model training counters")
        directory = safe_path(self.state, "learning")
        if previous:
            atomic_json(directory / "previous.json", previous, cancel)
        atomic_json(directory / "active.json", manifest, cancel)
        self.network = network
        self.training_manifest = manifest
        self.steps, self.accepted = steps, accepted
        self.acoustic_ready = manifest.get("acoustic_ready") is True
        self.dialogue_trained = manifest.get("dialogue_trained") is True
        self.active_digest = manifest["sha256"]

    def _resume_training_activation(self, store=None, cancel=None):
        owns_store = store is None
        if owns_store:
            if not safe_path(self.state, "memory/memory.sqlite3").is_file():
                return False
            store = AudioStore(self.state, recover=False)
        try:
            check(cancel)
            row = store.db.execute("SELECT value FROM settings WHERE key='pending_training_activation'").fetchone()
            if row is None:
                return False
            raw = row["value"]
            try:
                record = json.loads(raw, parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
                if record is None:
                    return False
                if not isinstance(record, dict):
                    raise YuanError("模型提交记录无效 / Invalid model commit record")
                manifest = self._training_manifest(record.get("manifest"))
                previous = record.get("previous")
                if previous is not None:
                    self._training_manifest(previous)
                metrics = manifest.get("metrics", {})
                if not store.validation_current(metrics):
                    raise YuanError("待提交模型依赖的数据已经修订 / Pending model depends on revised data")
                network = self._load_network(manifest, cancel)
            except Cancelled:
                raise
            except Exception as exc:
                reason = self._checkpoint_failure(exc)
                check(cancel)
                with store.transaction():
                    current = store.db.execute("SELECT value FROM settings WHERE key='pending_training_activation'").fetchone()
                    if current is None or current["value"] != raw:
                        raise YuanError("恢复期间模型提交记录发生变化 / Model commit record changed during recovery")
                    store.set_setting("rejected_training_activation", {"sha256": hashlib.sha256(raw.encode()).hexdigest(), "reason": reason, "created": time.time()})
                    store.set_setting("pending_training_activation", None)
                self.emit("notice", key="checkpoint_failure", file="pending_training_activation", reason=reason)
                return False
            check(cancel)
            with store.transaction():
                current = store.db.execute("SELECT value FROM settings WHERE key='pending_training_activation'").fetchone()
                if current is None or current["value"] != raw:
                    raise YuanError("恢复期间模型提交记录发生变化 / Model commit record changed during recovery")
                if not store.validation_current(metrics):
                    reason = "恢复期间训练或评估数据已修订 / Training or evaluation data changed during recovery"
                    store.set_setting("rejected_training_activation", {"sha256": hashlib.sha256(raw.encode()).hexdigest(), "reason": reason, "created": time.time()})
                    store.set_setting("pending_training_activation", None)
                    self.emit("notice", key="checkpoint_failure", file="pending_training_activation", reason=reason)
                    return False
                self._publish_training(manifest, previous, network, cancel)
                store.set_setting("pending_training_activation", None)
            self.emit("notice", key="promotion_recovered", model=self.active_digest, serving_model=self.serving_digest)
            return True
        finally:
            if owns_store:
                store.close()

    def _prune_models(self):
        StorageBudget(self.state).reclaim_recovery(self.cancel)
        directory = safe_path(self.state, "learning")
        protected = set()
        for name in ("active.json", "previous.json"):
            manifest = read_json(directory / name)
            if manifest.get("file"):
                protected.add(manifest["file"])
            for evidence in manifest.get("curriculum", {}).get("validated", {}).values():
                if isinstance(evidence, dict) and isinstance(evidence.get("model_file"), str):
                    protected.add(evidence["model_file"])
        for name in ("release.json", "pending-review.json", "previous-release.json"):
            pointer = read_json(directory / name)
            try:
                evaluation = read_json(safe_path(directory, pointer["evaluation_file"]))
                protected.add(evaluation["model"]["file"])
            except (KeyError, TypeError, YuanError):
                pass
        keep = self.policy.integer("learning", "retained_models", 2, 2, max(2, self.layers * 4))
        manifests = []
        for path in directory.glob("model-*.json"):
            manifest = read_json(path)
            if manifest.get("identity") == self.identity() and manifest.get("file"):
                manifests.append((float(manifest.get("created", 0)), path, manifest))
        for _, _, manifest in sorted(manifests, key=lambda value: value[0], reverse=True)[:keep]:
            protected.add(manifest["file"])
        for _, path, manifest in manifests:
            if manifest["file"] not in protected:
                try:
                    safe_path(directory, manifest["file"]).unlink(missing_ok=True)
                    path.unlink(missing_ok=True)
                except (OSError, YuanError) as exc:
                    self.emit("notice", reason=concise_error(exc), component="checkpoint_cleanup")

    def _prune_evaluations(self, cancel=None):
            directory = safe_path(self.state, "learning")
            root = safe_path(directory, "evaluations")
            if not root.is_dir() or root.is_symlink():
                return
            try:
                protected = set()
                for name in ("release.json", "pending-review.json", "previous-release.json", "evaluation-resume.json"):
                    pointer_path = directory / name
                    if not pointer_path.exists():
                        continue
                    pointer = checked_json(pointer_path)
                    path = safe_path(directory, pointer["evaluation_file"])
                    relative = path.relative_to(root)
                    protected.add(relative.parts[0])
                for file in getattr(self, "release_files", {}):
                    path = Path(file)
                    if root in path.parents:
                        protected.add(path.relative_to(root).parts[0])
                candidates = []
                total = 0
                for path in root.iterdir():
                    check(cancel)
                    if path.is_symlink() or not path.is_dir() or len(path.name) != len(uuid.uuid4().hex) or any(value not in "0123456789abcdef" for value in path.name):
                        continue
                    files = list(path.rglob("*"))
                    if any(file.is_symlink() for file in files):
                        continue
                    size = sum(file.stat().st_size for file in files if file.is_file())
                    total += size
                    if path.name not in protected:
                        candidates.append((path.stat().st_mtime_ns, path, size))
                keep = self.policy.integer("storage", "retained_evaluations", max(1, self.layers), 0, max(1, self.width))
                free = shutil.disk_usage(self.state).free
                budget = self.policy.integer("storage", "evaluation_cache_bytes", max(0, (free + total) // 4), 0, max(1, free + total))
                remaining = len(candidates)
                removed = reclaimed = 0
                for _, path, size in sorted(candidates, key=lambda row: row[0]):
                    if remaining <= keep and total <= budget:
                        break
                    check(cancel)
                    shutil.rmtree(path)
                    remaining -= 1
                    removed += 1
                    reclaimed += size
                    total -= size
                if removed:
                    self.emit("storage_cleanup", key="evaluation_cleanup", removed=removed, reclaimed_bytes=reclaimed, protected=len(protected), retained_bytes=total)
            except Cancelled:
                raise
            except (OSError, ValueError, KeyError, TypeError, YuanError) as exc:
                self.emit("notice", key="evaluation_cleanup", reason=concise_error(exc), protected=True)

    def _review_case(self, store, case, cancel=None):
        cancel = self.cancel if cancel is None else cancel
        pair = store.db.execute("SELECT p.*,g.split,g.source_key FROM turn_pairs p JOIN groups g ON g.id=p.group_id WHERE p.id=?", (case["pair"],)).fetchone()
        if pair is None or pair["split"] != "release" or not pair["verified"] or not pair["eligible"]:
            raise YuanError("听测样本不是独立发布留出配对 / Listening case is not an independent release-held-out pair")
        user, assistant = store.sample(pair["user_sample"]), store.sample(pair["assistant_sample"])
        evidence = json.loads(pair["evidence"])
        if (user is None or assistant is None or user["generated"] or assistant["generated"]
                or not user["dialogue_eligible"] or not assistant["dialogue_eligible"]
                or evidence.get("scenarios", []) != case.get("scenarios", [])
                or evidence.get("language") != case.get("language") or evidence.get("prompt") != case.get("prompt")
                or user["digest"] != case.get("user_digest") or assistant["digest"] != case.get("target_digest")
                or case.get("input_samples") != user["count"] or case.get("input_start") != 0 or case.get("input_end") != user["count"]
                or pair["source_key"] != case.get("recording_id") or payload_digest(evidence) != case.get("annotation_digest")):
            raise YuanError("听测数据来源或标注发生变化 / Listening dataset provenance or annotations changed")
        for row in (user, assistant):
            store.read_audio(row, 0, min(row["count"], self.hop), cancel=cancel, verify=True)
        history = case.get("history")
        if not isinstance(history, list) or "history" in evidence.get("scenarios", []) and not history:
            raise YuanError("听测历史音频已改变或缺失 / Listening history audio has changed or is missing")
        seen = set()
        seen_audio = {user["digest"], assistant["digest"]}
        previous = None
        for item in history:
            row = store.sample(item.get("id")) if isinstance(item, dict) else None
            if (row is None or row["id"] in seen or row["digest"] in seen_audio or row["group_id"] != pair["group_id"] or row["generated"] or not row["dialogue_eligible"]
                    or row["id"] in (user["id"], assistant["id"]) or row["created"] >= user["created"] or row["digest"] != item.get("sha256") or row["role"] != item.get("role")):
                raise YuanError("听测历史来源无效 / Invalid listening history provenance")
            order = (row["created"], row["id"])
            start, samples = item.get("start"), item.get("samples")
            if (previous is not None and order < previous or isinstance(start, bool) or not isinstance(start, int) or start < 0
                    or isinstance(samples, bool) or not isinstance(samples, int) or samples <= 0 or start + samples > row["count"]):
                raise YuanError("听测历史顺序或范围无效 / Invalid listening history order or range")
            store.read_audio(row, start, min(samples, self.hop), cancel=cancel, verify=True)
            seen.add(row["id"])
            seen_audio.add(row["digest"])
            previous = order
        return pair

    def review_history(self, store, pair, cancel):
        user, target = store.sample(pair["user_sample"]), store.sample(pair["assistant_sample"])
        if user is None or target is None:
            raise IneligibleSample("验收样本缺失 / Acceptance sample is missing")
        rows = store.db.execute("SELECT * FROM samples WHERE group_id=? AND created<? AND generated=0 AND dialogue_eligible=1 AND audio_status='ready' AND id NOT IN (?,?) ORDER BY created,id",
                                (pair["group_id"], user["created"], pair["user_sample"], pair["assistant_sample"])).fetchall()
        remaining = self.context_budget(user["count"])
        selected, seen = [], {user["digest"], target["digest"]}
        for row in rows:
            check(cancel)
            if row["digest"] in seen:
                continue
            if row["count"] > remaining or row["rate"] != self.rate or AudioStore.context_reason(json.loads(row["metadata"]), generated=False):
                raise IneligibleSample("验收历史不能在当前预算内完整保留 / Acceptance history cannot be retained completely within the current budget")
            audio = store.read_audio(row, 0, row["count"], cancel=cancel, verify=True)
            selected.append(((self.context_role(row["role"], json.loads(row["metadata"])), audio), {"id": row["id"], "sha256": row["digest"], "role": row["role"], "start": 0, "samples": len(audio)}))
            seen.add(row["digest"])
            remaining -= len(audio)
        return tuple(item[0] for item in selected), [item[1] for item in selected]

    def refresh_release(self):
        directory = safe_path(self.state, "learning")
        current = directory / "release.json"
        valid = False
        deployment = read_json(safe_path(self.state, "owned-release.json"), {})
        superseded = deployment.get("superseded_local_review_sha256")
        if current.exists() and (not superseded or digest_file(current, self.cancel) != superseded):
            try:
                valid = self._load_review(current)
            except Cancelled:
                raise
            except Exception as exc:
                self._release_error(exc, candidate=False)
        elif self.owned_root is None:
            self.dialogue_ready = self.playback_ready = False
            self.serving_network = self.serving_digest = None
            self.capability_evidence = {}
            self.release_signature = None
        if not valid and (directory / "previous-release.json").is_file():
            try:
                previous = directory / "previous-release.json"
                valid = self._load_review(previous)
                if valid:
                    atomic_json(current, checked_json(previous), self.cancel)
                    self.emit("notice", key="automatic_release_wait", reason="已恢复上一验收版本 / Previous accepted version restored", serving_preserved=True)
            except Cancelled:
                raise
            except Exception as exc:
                self._release_error(exc, candidate=False)
        if not valid and self.owned_root is not None:
            try:
                valid = self._load_review(safe_path(self.owned_root, "learning/release.json"), state=self.owned_root)
            except Cancelled:
                raise
            except Exception as exc:
                self._release_error(exc, candidate=False)
        try:
            pointer = read_json(directory / "pending-review.json")
            if not pointer.get("review_file"):
                return valid
            path = safe_path(directory, pointer["review_file"])
            draft = read_json(path)
            checks = draft.get("checks", [])
            if not checks:
                return valid
            evaluation = checked_json(safe_path(directory, draft["evaluation_file"]))
            if not CapabilityEvidence.complete(evaluation.get("cases", []), checks):
                return valid
            if valid and evaluation.get("model", {}).get("sha256") == self.serving_digest:
                return valid
            return self._load_review(path, pending=True)
        except Cancelled:
            raise
        except Exception as exc:
            self._release_error(exc, candidate=True)
            return valid

    def _release_error(self, exc, candidate=False):
        if not candidate:
            self.dialogue_ready = self.playback_ready = False
            self.serving_network = self.serving_digest = None
            self.capability_evidence = {}
            self.release_signature = None
        reason = concise_error(exc)
        key = "candidate_review_failure" if candidate else "release_failure"
        if reason != getattr(self, key, None):
            self.emit("notice", key="release_invalid", candidate=candidate, serving_preserved=bool(candidate and self.playback_ready), reason=reason)
        setattr(self, key, reason)

    def _load_review(self, path, pending=False, state=None, announce=True, cancel=None):
        candidate = copy.copy(self)
        result = candidate._stage_review(path, pending=pending, state=state, announce=False, cancel=cancel)
        if result:
            for name in ("serving_network", "serving_digest", "serving_manifest", "release_root", "capability_evidence", "dialogue_ready", "playback_ready", "release_signature", "release_files", "release_failure", "release_cases", "release_calibration", "release_scope"):
                if hasattr(candidate, name):
                    setattr(self, name, getattr(candidate, name))
            if announce:
                self.record_serving()
        return result

    def _stage_review(self, path, pending=False, state=None, announce=True, cancel=None):
        cancel = self.cancel if cancel is None else cancel
        state = self.state if state is None else Path(state)
        directory = safe_path(state, "learning")
        signature = (str(path.resolve()), digest_file(path, cancel))
        if not pending and signature == self.release_signature and self.serving_network is not None:
            unchanged = True
            for file, previous in self.release_files.items():
                stat = Path(file).stat()
                if (stat.st_mtime_ns, stat.st_ctime_ns, stat.st_size, stat.st_dev, stat.st_ino) != previous:
                    unchanged = False
                    break
            if unchanged:
                store = AudioStore(state, recover=False)
                try:
                    groups = [self._review_case(store, case, cancel)["group_id"] for case in self.release_cases]
                    for record in getattr(self, "release_calibration", []):
                        row = store.sample(record["sample"])
                        if row is None or SpeechVerifier.row_signature(row) != record["signature"]:
                            raise YuanError("发布验证模型的校准证据已改变 / Release verifier calibration evidence changed")
                        groups.append(row["group_id"])
                    store.assert_independent(groups)
                finally:
                    store.close()
                return self.playback_ready
        review = checked_json(path)
        if review.get("protocol") != "yuan-native-listening-v4" or not isinstance(review.get("reviewer"), str) or not review["reviewer"].strip():
            raise YuanError("听测验收协议或评审人无效 / Invalid listening acceptance protocol or reviewer")
        evaluation_path = safe_path(directory, review["evaluation_file"])
        if digest_file(evaluation_path, cancel) != review.get("evaluation_sha256"):
            raise YuanError("听测结果摘要不匹配 / Listening evaluation digest mismatch")
        evaluation = checked_json(evaluation_path)
        if evaluation.get("protocol") != review["protocol"] or evaluation.get("evaluator_sha256") != behavior_digest() or evaluation.get("build_sha256") != build_digest() or evaluation.get("identity") != self.identity():
            raise YuanError("听测程序版本或模型结构不匹配 / Listening evaluator version or model architecture mismatch")
        FinalAcceptance.validate(evaluation)
        reviewed_at = review.get("reviewed_at")
        if isinstance(reviewed_at, bool) or not isinstance(reviewed_at, (float, int)) or not math.isfinite(reviewed_at) or reviewed_at < evaluation["created"]:
            raise YuanError("听测验收时间无效 / Invalid listening review time")
        cases = evaluation.get("cases", [])
        checks = review.get("checks", [])
        if not cases or not isinstance(checks, list) or len(checks) != len(cases):
            raise YuanError("听测验收项目不完整 / Listening review cases are incomplete")
        approved = {item["id"]: item for item in checks}
        if len(approved) != len(cases) or set(approved) != {case["id"] for case in cases}:
            raise YuanError("听测验收项目重复或不匹配 / Duplicate or mismatched listening cases")
        if not CapabilityEvidence.complete(cases, checks):
            raise YuanError("听测验收尚未全部通过 / Listening acceptance has not passed all checks")
        dataset = [{key: case[key] for key in ("id", "pair", "language", "prompt", "recording_id", "user_digest", "target_digest", "annotation_digest", "input_samples", "input_start", "input_end", "scenarios", "history")} for case in cases]
        if payload_digest(dataset) != evaluation.get("dataset_sha256"):
            raise YuanError("听测数据集版本不匹配 / Listening dataset version mismatch")
        acceptance = AcceptancePolicy(self)
        if evaluation.get("acceptance_policy_sha256") != acceptance.digest:
            raise YuanError("验收策略与听测记录不匹配 / Acceptance policy does not match the listening record")
        acceptance.check_coverage(cases)
        files = [path, evaluation_path, Path(__file__), acceptance.path]
        self.release_calibration = []
        self.release_scope = "independent_human_listening"
        if review.get("automatic"):
            files.extend(self._verify_automatic(review, evaluation, directory, cancel))
        store = AudioStore(state, recover=False)
        try:
            groups = [self._review_case(store, case, cancel)["group_id"] for case in cases]
            store.assert_independent(groups)
        finally:
            store.close()
        import soundfile as sf
        for case in cases:
            check(cancel)
            for field in ("input", "output"):
                audio_path = safe_path(directory, case[field + "_file"])
                if digest_file(audio_path, cancel) != case[field + "_sha256"]:
                    raise YuanError("听测音频完整性校验失败 / Listening audio integrity validation failed")
                with sf.SoundFile(str(audio_path)) as audio_file:
                    if audio_file.samplerate != self.rate or audio_file.channels != 1 or audio_file.frames <= 0 or field == "input" and audio_file.frames != case["input_samples"]:
                        raise YuanError("听测音频无效 / Invalid listening audio")
                    for values in audio_file.blocks(blocksize=max(self.hop, self.window()), dtype="float32"):
                        check(cancel)
                        if not self.np.isfinite(values).all() or float(self.np.max(self.np.abs(values))) > 1:
                            raise YuanError("听测音频无效 / Invalid listening audio")
                files.append(audio_path)
        capability_evidence = CapabilityEvidence.build(evaluation, checks, self.release_scope)
        if review.get("automatic") and review.get("capabilities") != capability_evidence:
            raise YuanError("能力证据与验收版本不一致 / Capability evidence does not match the accepted version")
        if self.dialogue_ready and not capability_evidence["dialogue_ready"]:
            raise YuanError("候选验收范围未覆盖现有对话能力，保留服务模型 / Candidate acceptance scope does not cover current dialogue capability; serving model preserved")
        manifest = evaluation["model"]
        if manifest.get("dialogue_trained") is not True:
            raise YuanError("模型尚未通过对话训练验证 / Model has not passed dialogue training validation")
        network = self._load_network(manifest, cancel, state=state)
        files.append(safe_path(directory, manifest["file"]))
        next_files = {}
        for file in files:
            stat = file.stat()
            next_files[str(file)] = (stat.st_mtime_ns, stat.st_ctime_ns, stat.st_size, stat.st_dev, stat.st_ino)
        if pending:
            current = directory / "release.json"
            if current.is_file():
                previous = checked_json(current)
                atomic_json(directory / "previous-release.json", previous, cancel)
            atomic_json(current, review, cancel)
            path = directory / "release.json"
            try:
                (directory / "pending-review.json").unlink(missing_ok=True)
                sync_dir(directory)
            except OSError as exc:
                self.emit("notice", component="release_pointer", reason=concise_error(exc))
        self.serving_network, self.serving_digest = network, manifest["sha256"]
        self.serving_manifest = manifest
        self.release_root = state
        self.capability_evidence = capability_evidence
        self.dialogue_ready = CapabilityEvidence.ready(capability_evidence, manifest["sha256"])
        self.playback_ready = True
        self.release_signature = signature
        self.release_files = next_files
        self.release_failure = None
        self.release_cases = cases
        if announce:
            self.record_serving()
        return True

    def service_ready(self):
        return bool(self.playback_ready and self.serving_network is not None
                    and CapabilityEvidence.ready(self.capability_evidence, self.serving_digest))

    def record_serving(self):
        release_state = read_json(safe_path(self.state, "serving-state.json"), {})
        if release_state.get("model_sha256") != self.serving_digest:
            atomic_json(safe_path(self.state, "serving-state.json"), {"model_sha256": self.serving_digest, "versions": int(release_state.get("versions", 0)) + 1,
                                                                   "accepted_at": time.time()}, self.cancel)
        self.emit("model", key="release_loaded", dialogue_ready=self.dialogue_ready, playback_ready=self.playback_ready, conversation_verified=self.dialogue_ready,
                  serving_digest=self.serving_digest, capability=self.capability(), capability_evidence=getattr(self, "capability_evidence", {}), evidence_scope=getattr(self, "release_scope", None))

    @supervised('review_generation', 'learning')
    def prepare_review(self, store, cancel):
        if not self.dialogue_trained:
            return False
        verifier = getattr(self, "verifier", None)
        if verifier is None or not verifier.ready(cancel):
            return False
        directory = safe_path(self.state, "learning")
        self._prune_evaluations(cancel)
        held = getattr(self, "review_held", None)
        for name in ("pending-review.json", "release.json"):
            pointer = read_json(directory / name)
            try:
                evaluation_file = pointer.get("evaluation_file")
                evaluated = read_json(safe_path(directory, evaluation_file)) if evaluation_file else {}
                held_review = bool(name == "pending-review.json" and held and held == pointer.get("model_sha256") == evaluated.get("model", {}).get("sha256"))
                if ((evaluated.get("model", {}).get("sha256") == self.active_digest or held_review) and evaluated.get("evaluator_sha256") == behavior_digest()
                        and evaluated.get("protocol") == "yuan-native-listening-v4" and evaluated.get("identity") == self.identity()
                        and store.validation_current(evaluated)):
                    receipt = FinalAcceptance.validate(evaluated)
                    if receipt["identity"] != FinalAcceptance.identity(self, store, AcceptancePolicy(self)):
                        raise IneligibleSample("最终验收验证器已改变 / Final acceptance verifier changed")
                    cases = evaluated.get("cases", [])
                    if not cases:
                        raise YuanError("听测数据为空 / Listening cases are empty")
                    groups = [self._review_case(store, case)["group_id"] for case in cases]
                    store.assert_independent(groups)
                    return False
            except (OSError, ValueError, TypeError, KeyError, YuanError):
                pass
        self.review_held = None
        acceptance = AcceptancePolicy(self)
        policy_path = directory / "acceptance-policy.json"
        if policy_path.resolve() != acceptance.path.resolve():
            atomic_json(policy_path, acceptance.data, cancel)
        existing_final = FinalAcceptance.current(self, store, acceptance)
        if existing_final is not None and existing_final["status"] not in ("reserved", "evaluating"):
            return False
        selected = acceptance.select(store, self, fresh=True)
        if not selected:
            if existing_final is not None:
                previous = json.loads(existing_final["receipt"])
                rows = [store.db.execute("SELECT * FROM turn_pairs WHERE id=?", (identifier,)).fetchone() for identifier in previous["pair_ids"]]
                try:
                    current = store.evaluation_snapshot(rows) if all(row is not None for row in rows) else None
                    stale = current is None or current["sha256"] != previous["evaluation_snapshot_sha256"]
                except YuanError:
                    stale = True
                if stale:
                    FinalAcceptance.finish(store, previous, "stale")
            return False
        store.assert_independent([row["group_id"] for row in selected])
        snapshot = store.evaluation_snapshot(selected)
        training_revision = store.setting("training_revision")
        required = sum((store.sample(row["user_sample"])["count"] + self.capacity()) * self.np.dtype(self.np.float32).itemsize for row in selected)
        free = shutil.disk_usage(self.state).free
        reserve = max(required, getattr(self, "model_bytes", 0) * 2)
        if free < required + reserve:
            self.emit("notice", key="review_storage_pause", required_bytes=required + reserve, available_bytes=free)
            return False
        import soundfile as sf
        receipt = FinalAcceptance.claim(self, store, acceptance, selected, snapshot)
        frozen_network = self.network
        evaluation_id = receipt["sha256"][:len(uuid.uuid4().hex)]
        root = safe_path(directory, "evaluations/" + evaluation_id)
        root.mkdir(parents=True, exist_ok=True)
        resume_path = directory / "evaluation-resume.json"
        atomic_json(resume_path, {"final_acceptance_sha256": receipt["sha256"], "model_sha256": self.active_digest,
                                 "evaluation_file": (root / "evaluation.json").relative_to(directory).as_posix()}, cancel)
        receipt_path = root / "receipt.json"
        if receipt_path.exists() and checked_json(receipt_path) != receipt:
            FinalAcceptance.finish(store, receipt, "stale")
            raise IneligibleSample("验收恢复记录与冻结身份不一致 / Acceptance recovery record differs from the frozen identity")
        atomic_json(receipt_path, receipt, cancel)
        cases = []
        committed = False
        try:
            for row in selected:
                check(cancel)
                record_path = safe_path(root, row["id"] + "-case.json")
                if record_path.exists():
                    record = checked_json(record_path)
                    case = record["case"]
                    if record.get("final_acceptance_sha256") != receipt["sha256"] or case.get("pair") != row["id"]:
                        raise IneligibleSample("验收案例恢复身份不一致 / Acceptance case recovery identity differs")
                    self._review_case(store, case, cancel)
                    for kind in ("input", "output"):
                        if digest_file(safe_path(directory, case[kind + "_file"]), cancel) != case[kind + "_sha256"]:
                            raise InvalidAudio("验收缓存音频已改变 / Cached acceptance audio changed")
                    cases.append(case)
                    continue
                evidence = json.loads(row["evidence"])
                user, target = store.sample(row["user_sample"]), store.sample(row["assistant_sample"])
                if user["rate"] != self.rate:
                    raise InvalidAudio("听测输入采样率不匹配 / Listening input sample rate mismatch")
                store.read_audio(user, 0, min(user["count"], self.hop), cancel=cancel, verify=True)
                waveform = AudioSequence(int(user["count"]), lambda offset, count: store.read_audio(user, offset, count, cancel=cancel))
                store.read_audio(target, 0, min(target["count"], self.hop), cancel=cancel, verify=True)
                history, history_records = self.review_history(store, row, cancel)
                if "history" in evidence.get("scenarios", []) and not history:
                    raise YuanError("多轮听测缺少真实历史上下文 / Multi-turn listening evaluation lacks real history context")
                generation = {}
                output = self.respond_audio(evidence["prompt"], history, waveform, cancel, network=frozen_network, evaluation=generation)
                case_id = row["id"]
                input_path, output_path = (safe_path(root, case_id + "-" + kind + ".flac") for kind in ("input", "output"))
                for path, values in ((input_path, waveform), (output_path, output)):
                    with sf.SoundFile(str(path), mode="w", samplerate=self.rate, channels=1, format="FLAC", subtype="PCM_24") as output_file:
                        for block in self.audio_blocks(values, cancel):
                            output_file.write(block)
                    with path.open("rb") as stream:
                        os.fsync(stream.fileno())
                cases.append({"generation": generation, "history": history_records, "scenarios": evidence.get("scenarios", []), "id": case_id, "pair": row["id"], "language": evidence["language"], "prompt": evidence["prompt"], "recording_id": row["source_key"],
                              "user_digest": user["digest"], "target_digest": target["digest"], "annotation_digest": payload_digest(evidence),
                              "input_samples": user["count"], "input_start": 0, "input_end": user["count"],
                              "input_file": input_path.relative_to(directory).as_posix(), "input_sha256": digest_file(input_path, cancel),
                              "output_file": output_path.relative_to(directory).as_posix(), "output_sha256": digest_file(output_path, cancel)})
                atomic_json(record_path, {"final_acceptance_sha256": receipt["sha256"], "case": cases[-1]}, cancel)
            dataset = [{key: case[key] for key in ("id", "pair", "language", "prompt", "recording_id", "user_digest", "target_digest", "annotation_digest", "input_samples", "input_start", "input_end", "scenarios", "history")} for case in cases]
            evaluation = {"protocol": "yuan-native-listening-v4", "evaluator_sha256": behavior_digest(), "build_sha256": build_digest(), "identity": self.identity(),
                          "model": self.training_manifest, "dataset_sha256": payload_digest(dataset), "cases": cases, "created": time.time(),
                          "acceptance_policy_sha256": acceptance.digest, "minimum_independent_sources": acceptance.minimum,
                          "supervision_revisions": store.revisions(), "training_revision": training_revision, "evaluation_snapshot": snapshot,
                          "final_acceptance": receipt}
            if receipt["identity"] != FinalAcceptance.identity(self, store, acceptance) or self.network is not frozen_network:
                FinalAcceptance.finish(store, receipt, "stale")
                return False
            if not store.validation_current(evaluation):
                FinalAcceptance.finish(store, receipt, "stale")
                return False
            evaluation_path = root / "evaluation.json"
            atomic_json(evaluation_path, evaluation, cancel)
            review = {"protocol": evaluation["protocol"], "evaluation_file": evaluation_path.relative_to(directory).as_posix(), "evaluation_sha256": digest_file(evaluation_path, cancel),
                      "reviewer": "", "reviewed_at": None, "checks": [{"id": case["id"], **{key: None for key in ("understandable", "follows_prompt", "relevant_reply", "follows_history", "ends_normally", "no_abnormal_audio")}} for case in cases]}
            atomic_json(root / "review.json", review, cancel)
            old_pointer = read_json(directory / "pending-review.json")
            if old_pointer.get("evaluation_file"):
                self.emit("review_superseded", previous=old_pointer["evaluation_file"], model=self.active_digest)
            atomic_json(directory / "pending-review.json", {"model_sha256": self.active_digest, "state": "pending", "evaluation_file": review["evaluation_file"], "review_file": (root / "review.json").relative_to(directory).as_posix()}, cancel)
            committed = True
            self.emit("notice", key="release_wait", evaluation=evaluation_id, cases=len(cases), model=self.active_digest)
            return True
        except (YuanError, ValueError, TypeError, KeyError) as exc:
            if not isinstance(exc, YuanFault) or exc.category not in ("resource", "timeout"):
                FinalAcceptance.finish(store, receipt, "stale")
            raise
        finally:
            current = store.db.execute("SELECT status FROM final_acceptance_runs WHERE id=?", (receipt["sha256"],)).fetchone()
            resumable = current is not None and current["status"] in ("reserved", "evaluating")
            if not committed and not resumable:
                shutil.rmtree(root, ignore_errors=True)
            if committed or not resumable:
                try:
                    if read_json(resume_path).get("final_acceptance_sha256") == receipt["sha256"]:
                        resume_path.unlink(missing_ok=True)
                except OSError as exc:
                    self.emit("notice", key="checkpoint_failure", component="evaluation_resume", reason=concise_error(exc))

    def promote(self, candidate, metrics, cancel, task, store):
        active = copy.deepcopy(candidate).eval().requires_grad_(False)
        if not self._persist(active, metrics, cancel, increment=True, task=task, store=store):
            return False
        self.emit("model", accepted=self.accepted, steps=self.steps, acoustic_ready=self.acoustic_ready, dialogue_trained=self.dialogue_trained, dialogue_ready=self.dialogue_ready,
                  playback_ready=self.playback_ready, conversation_verified=self.dialogue_ready, serving_digest=self.serving_digest,
                  active_digest=self.active_digest, candidate_isolated=self.active_digest != self.serving_digest,
                  capability=self.capability(), identity=self.identity()[:12])
        return True


    def context_budget(self, incoming_count):
        capacity = self.capacity()
        return max(0, min(capacity // 2, capacity - max(self.hop, int(incoming_count))))

    def _history_budget(self, history, incoming_count, recalled=(), context_id=None):
        np = self.np
        budget = self.context_budget(incoming_count)
        def normalize(items):
            selected = []
            total = 0
            for role, audio in items:
                values = np.asarray(audio, dtype=np.float32).reshape(-1)
                total += len(values)
                if role in ("user", "assistant", "user_partial", "assistant_interrupted") and values.size and np.isfinite(values).all():
                    selected.append((role, values))
            return selected, total
        recent, recent_total = normalize(history)
        memories, memory_total = normalize(recalled)
        recent_size = sum(len(values) for role, values in recent)
        memory_size = sum(len(values) for role, values in memories)
        if recent_size and memory_size and budget:
            minimum = min(self.hop, budget // 2)
            share = int(budget * math.sqrt(memory_size) / (math.sqrt(memory_size) + math.sqrt(recent_size)))
            memory_budget = min(memory_size, budget - min(recent_size, minimum), max(min(memory_size, minimum), share))
            recent_budget = min(recent_size, budget - memory_budget)
            memory_budget = min(memory_size, budget - recent_budget)
        else:
            memory_budget = min(memory_size, budget)
            recent_budget = min(recent_size, budget - memory_budget)
        def retain(items, limit):
            selected = []
            used = 0
            for role, values in reversed(items):
                take = min(len(values), max(0, limit - used))
                if take:
                    selected.append((role, values[-take:]))
                    used += take
                if used >= limit:
                    break
            return list(reversed(selected)), used
        recent, recent_used = retain(recent, recent_budget)
        memories, memory_used = retain(memories, memory_budget)
        used = recent_used + memory_used
        total = recent_total + memory_total
        if total > used or memory_total:
            self.emit("context_budget", key="context_trimmed" if total > used else "memory_context_retained", id=context_id,
                      kept_samples=used, dropped_samples=total - used, budget_samples=budget, incoming_samples=int(incoming_count),
                      recent_samples=recent_used, recalled_samples=memory_used, recalled_count=len(memories))
        if memory_total:
            self.emit("memory_recall", key="memory_context_retained", id=context_id, count=len(memories), samples=memory_used,
                      matched_samples=memory_total, context_selected=True)
        return tuple(memories + recent)

    @supervised('input_encoding', 'conversation')
    def encode_input(self, prompt, history, waveform, cancel, hidden=None, network=None, final=True, recalled=(), context_id=None):
        np, torch = self.np, self.torch
        incoming = waveform if isinstance(waveform, AudioSequence) else np.asarray(waveform, dtype=np.float32).reshape(-1)
        if not len(incoming) or not isinstance(incoming, AudioSequence) and not np.isfinite(incoming).all():
            raise YuanError("模型输入音频无效 / Invalid model audio input")
        network = network if network is not None else self.serving_network if self.playback_ready and self.serving_network is not None else self.network
        network.eval()
        pending = condition = encoder = None
        if isinstance(hidden, AudioEncoding):
            hidden, pending, condition, encoder = hidden.hidden, hidden.pending, hidden.condition, hidden.encoder
        with self.interruptible(cancel), torch.inference_mode():
            if condition is None:
                condition = self._prompt_condition(network, prompt, cancel, "dialogue")
            if hidden is None:
                hidden = self._encode(network, prompt, np.empty(0, dtype=np.float32), history, cancel, task="dialogue", condition=condition,
                                      recalled=recalled, incoming_count=len(incoming), context_id=context_id)
            hidden, pending, encoder = self._encode_audio(network, incoming, hidden, "user", cancel, pending, final, condition, encoder)
            return hidden.detach() if final else AudioEncoding(hidden.detach(), pending, condition.detach(), encoder.detach() if encoder is not None else None)

    @supervised_stream('generation_block', 'conversation')
    def stream_audio(self, prompt, history, waveform, cancel, max_samples=None, network=None, hidden=None, reference_rms=None, evaluation=None):
        started = time.monotonic()
        if evaluation is not None:
            evaluation.clear()
            evaluation.update(complete=False, natural=False, limited=False, samples=0, first_audio_seconds=None, audio_domain="model")
        np, torch = self.np, self.torch
        incoming = waveform if isinstance(waveform, AudioSequence) else np.asarray(waveform, dtype=np.float32).reshape(-1)
        if not len(incoming) or not isinstance(incoming, AudioSequence) and not np.isfinite(incoming).all():
            raise YuanError("模型输入音频无效 / Invalid model audio input")
        if reference_rms is None:
            energy = 0.0
            for values in self.audio_blocks(incoming, cancel):
                values = values.astype(np.float64)
                energy += float(np.dot(values, values))
            reference = math.sqrt(energy / len(incoming))
        else:
            reference = float(reference_rms)
        if not math.isfinite(reference) or reference <= np.finfo(np.float32).eps:
            raise YuanError("模型输入为静音 / Model input is silent")
        network = network if network is not None else self.serving_network if self.playback_ready and self.serving_network is not None else self.network
        count = max(self.hop, min(int(max_samples) if max_samples is not None else self.reply_samples(incoming, history), self.capacity()))
        block_frames = max(1, min(math.ceil(count / self.hop), getattr(self, "decode_block_frames", max(1, round(math.sqrt(self.rate / self.hop))))))
        self.emit("phase", key="prefill", current=len(incoming), total=self.capacity(), unit="samples", reply_samples=count, reply_seconds=count / self.rate, streaming=True)
        network.eval()
        if hidden is None:
            hidden = self.encode_input(prompt, history, incoming, cancel, network=network)
        if isinstance(hidden, AudioEncoding):
            with self.interruptible(cancel), torch.inference_mode():
                hidden, pending, encoder = self._encode_audio(network, np.empty(0, dtype=np.float32), hidden.hidden, "user", cancel, hidden.pending, True, hidden.condition, hidden.encoder)
        condition = hidden
        previous = network.begin
        total_frames = max(1, math.ceil(count / self.hop))
        emitted = frames_done = 0
        compute_seconds = energy = 0.0
        energy_samples = 0
        natural = False
        try:
            while frames_done < total_frames and not natural:
                began = time.monotonic()
                pieces, endings = [], []
                with self.interruptible(cancel), torch.inference_mode():
                    seconds_per_frame = self.policy.measured(getattr(self, "performance_section", "performance"), "stream_seconds_per_frame", self.hop / self.rate)
                    target = CooperativeCompute(self, "streaming").target()
                    frames = max(1, min(block_frames, total_frames - frames_done, int(target / max(timing_floor(), seconds_per_frame))))
                    if not emitted:
                        frames = 1
                    for _ in range(frames):
                        check(cancel)
                        predicted, ending, hidden = network.decode(previous, hidden, condition)
                        pieces.append(predicted)
                        endings.append(ending)
                        previous = predicted
                    packed = torch.cat((torch.cat(pieces, dim=1), torch.stack(endings, dim=1)), dim=-1).reshape(frames, self.hop + 1)
                    host = packed.detach().float().cpu().numpy()
                    stops = np.flatnonzero(host[:, -1] > 0)
                    keep = int(stops[0]) + 1 if len(stops) else frames
                    if not np.isfinite(host[:keep]).all():
                        raise YuanError("模型输出含无效数值 / Model output contains invalid values")
                    natural = bool(len(stops))
                    frames_done += keep
                    values = host[:keep, :self.hop].reshape(-1)[:count - emitted].copy()
                elapsed = elapsed_seconds(began)
                self.policy.observe(getattr(self, "performance_section", "performance"), "stream_seconds_per_frame", elapsed / frames)
                compute_seconds += elapsed
                energy += float(np.dot(values.astype(np.float64), values.astype(np.float64)))
                energy_samples += len(values)
                emitted += len(values)
                check(cancel)
                self.emit("phase", key="generating", current=frames_done, total=total_frames, unit="frames", streaming=True)
                if evaluation is not None:
                    if evaluation["first_audio_seconds"] is None:
                        evaluation["first_audio_seconds"] = max(0.0, time.monotonic() - started)
                    evaluation["samples"] = emitted
                yield np.ascontiguousarray(values, dtype=np.float32)
            check(cancel)
            if energy_samples == 0 or energy <= np.finfo(np.float32).eps ** 2 * energy_samples:
                raise YuanError("模型输出为静音 / Model output is silent")
            if evaluation is not None:
                evaluation.update(complete=True, natural=natural, limited=not natural, frames=frames_done, samples=emitted,
                                  elapsed_seconds=max(0.0, time.monotonic() - started), compute_seconds=compute_seconds)
            self.emit("generation_end", key="natural_end" if natural else "limited", natural=natural, limited=not natural, frames=frames_done, samples=emitted, streaming=True)
            if not natural:
                self.emit("notice", key="limited", component="generation")
        finally:
            if emitted and compute_seconds > 0:
                section = getattr(self, "performance_section", "performance")
                self.policy.observe(section, "generation_realtime_factor", compute_seconds * self.rate / emitted)
                self.policy.observe(section, "workload_samples", emitted)
                self.emit("generation_measurement", compute_seconds=compute_seconds, samples=emitted, realtime_factor=compute_seconds * self.rate / emitted,
                          device=str(self.device), cancelled=bool(cancel and cancel.is_set()))

    def adapt_execution(self):
        section = getattr(self, "performance_section", "performance")
        previous = self.window()
        base, capacity = self._execution_limits(__import__("psutil"), self.rate, self.hop)
        self.chunk_seconds, self.capacity_seconds = base, capacity
        self.configure_execution()
        requested = self.window()
        estimate = self.width * self.layers * self.np.dtype(self.np.float32).itemsize * 72
        per_frame = max(estimate, self.policy.measured(section, "training_bytes_per_frame", estimate))
        headroom = self.memory_headroom()
        if headroom["measured"]:
            fixed = getattr(self, "model_bytes", 0) * 6
            budget = max(0, min(headroom["host_available"], headroom["device_available"]) - fixed)
            requested = min(requested, max(self.hop * 2, int(budget / per_frame) * self.hop))
        if time.monotonic() < self.training_retry_at or self.training_oom_window is not None:
            requested = min(previous, requested)
        if requested < previous:
            samples = requested
        else:
            samples = min(requested, math.ceil(math.sqrt(previous * requested) / self.hop) * self.hop)
        self.training_window_samples = max(self.hop * 2, int(samples) // self.hop * self.hop)
        self.policy.observe(section, "training_window_samples", self.window())
        self.policy.observe(section, "compute_quantum_seconds", self.compute_quantum_seconds)
        self.policy.observe(section, "decode_block_frames", self.decode_block_frames)

    def calibrate(self, cancel, force=False):
        import psutil
        torch = self.torch
        section = getattr(self, "performance_section", "performance")
        upper = execution_threads(psutil, self.policy)
        chosen = int(self.policy.measured(section, "best_threads", 0))
        workload = int(self.policy.measured(section, "workload_samples", self.hop * max(4, self.layers + 1)))
        count = max(self.hop * 2, min(self.window(), workload))
        count = max(self.hop, count // self.hop * self.hop)
        calibrated = self.policy.measured(section, "calibration_samples", 0.0)
        stale = calibrated <= 0 or max(count, calibrated) / max(self.hop, min(count, calibrated)) >= 2
        if not force and not stale and 1 <= chosen <= upper:
            torch.set_num_threads(chosen)
            return
        previous = torch.get_num_threads()
        best = None
        values = self.np.linspace(-0.1, 0.1, count, dtype=self.np.float32)
        candidates = sorted({1, min(previous, upper), max(1, math.isqrt(upper)), upper})
        try:
            for threads in candidates:
                check(cancel)
                torch.set_num_threads(threads)
                for trial in range(2):
                    began = time.monotonic()
                    with torch.inference_mode():
                        hidden = self._encode(self.network, "Yuan", values, cancel=cancel, task="dialogue")
                        output = self._decode(self.network, hidden, count, cancel, stop=False)
                        output.float().cpu().numpy()
                    elapsed = elapsed_seconds(began)
                    if trial:
                        self.emit("calibration", threads=threads, seconds=elapsed, samples=count, device=str(self.device))
                        if best is None or elapsed < best[0]:
                            best = (elapsed, threads)
            chosen = best[1] if best else previous
            torch.set_num_threads(chosen)
            self.policy.observe(section, "best_threads", chosen)
            self.policy.observe(section, "calibration_samples", count)
            self.adapt_execution()
            self.policy.save()
        except BaseException:
            torch.set_num_threads(previous)
            raise






    def _verify_automatic(self, review, evaluation, directory, cancel):
        descriptor = review.get("automatic", {})
        audit_path = safe_path(directory, descriptor["audit_file"])
        if descriptor.get("protocol") != "yuan-independent-task-release-v1" or digest_file(audit_path, cancel) != descriptor.get("audit_sha256"):
            raise YuanError("自动任务验收协议或摘要无效 / Invalid automatic task acceptance protocol or digest")
        audit = checked_json(audit_path)
        if (audit.get("protocol") != descriptor["protocol"] or audit.get("evaluator_sha256") != behavior_digest()
                or audit.get("candidate_sha256") != evaluation["model"]["sha256"]
                or audit.get("evaluation_sha256") != review["evaluation_sha256"]
                or audit.get("final_acceptance_sha256") != FinalAcceptance.validate(evaluation)["sha256"]
                or audit.get("acceptance_policy_sha256") != AcceptancePolicy(self).digest
                or audit.get("scope") not in (CapabilityEvidence.task_scope, CapabilityEvidence.dialogue_scope)):
            raise YuanError("自动任务验收与当前模型或策略不匹配 / Automatic task acceptance does not match the model or policy")
        independent = audit.get("independent", {})
        if set(independent) != {"validation", "guard"}:
            raise YuanError("自动任务验收缺少独立验证与保护检查 / Automatic task acceptance lacks validation and guard checks")
        for result in independent.values():
            numbers = [result.get(key) for key in ("before", "after", "margin")]
            if (result.get("passed") is not True or any(isinstance(value, bool) or not isinstance(value, (float, int)) or not math.isfinite(value) for value in numbers)
                    or result.get("sources", 0) < 1 or result["after"] > result["before"] + result["margin"]):
                raise YuanError("自动升级独立回归证据无效 / Invalid independent upgrade regression evidence")
        if audit.get("serving_sha256") and audit.get("improvement") is not True:
            raise YuanError("自动升级缺少改进证据 / Automatic upgrade lacks improvement evidence")
        cases = evaluation.get("cases", [])
        AcceptancePolicy(self).check_coverage(cases)
        checks = audit.get("cases", [])
        if len(checks) != len(cases) or {item["id"] for item in checks} != {case["id"] for case in cases}:
            raise YuanError("自动任务验收案例集合不匹配 / Automatic task acceptance cases do not match")
        approved = {item["id"]: item for item in checks}
        store = AudioStore(directory.parent, recover=False)
        probe = copy.copy(self)
        probe.state = directory.parent
        probe.emit = lambda *args, **kwargs: None
        try:
            verifier = SpeechVerifier(probe, store, probe.emit)
            files = [audit_path, *verifier.restore_snapshot(audit["verifier"], directory, cancel)]
            if FinalAcceptance.verifier_key(verifier) != evaluation["final_acceptance"]["identity"]["verifier_sha256"]:
                raise YuanError("最终验收验证器快照不一致 / Final acceptance verifier snapshot differs")
            recomputed, measured = [], []
            for case in cases:
                result, assets = probe._task_case(store, case, directory, verifier, cancel, controls=approved[case["id"]]["controls"])
                measured.append(result)
                recomputed.append(CapabilityEvidence.task_checks(result, audit["scope"]))
                files.extend(assets)
            if (CapabilityEvidence.automatic_scope(measured) != audit["scope"] or recomputed != review.get("checks")
                    or CapabilityEvidence.build(evaluation, recomputed, audit["scope"]) != review.get("capabilities")):
                raise YuanError("任务能力检查与独立复核不一致 / Task capability checks differ from independent revalidation")
            store.assert_independent([probe._review_case(store, case, cancel)["group_id"] for case in cases] + [record["group"] for record in verifier.certificate["records"]])
            self.release_calibration = copy.deepcopy(verifier.certificate["records"])
            self.release_scope = audit["scope"]
            return files
        finally:
            store.close()

    @supervised('automatic_release', 'learning')
    def automatic_review(self, store, cancel):
        if self.active_digest is not None and self.active_digest == self.serving_digest and self.playback_ready:
            proof = getattr(self, "capability_evidence", {})
            if (proof.get("model_sha256") == self.serving_digest and proof.get("sha256") == payload_digest({key: value for key, value in proof.items() if key != "sha256"})):
                current = store.db.execute("SELECT receipt,status FROM final_acceptance_runs WHERE id=?", (proof.get("final_acceptance_sha256"),)).fetchone()
                if current is not None and current["status"] in ("reserved", "evaluating"):
                    receipt = json.loads(current["receipt"])
                    if receipt["identity"]["candidate_sha256"] == self.serving_digest:
                        FinalAcceptance.finish(store, receipt, "accepted")
        if self.active_digest is not None and self.active_digest == self.serving_digest and self.service_ready():
            self.automatic_release_state = "serving_current"
            return False
        directory = safe_path(self.state, "learning")
        pointer = read_json(directory / "pending-review.json")
        if not pointer.get("review_file") or pointer.get("model_sha256") != self.active_digest or getattr(self, "review_held", None):
            self.automatic_release_state = "waiting_candidate_evaluation"
            return False
        verifier = getattr(self, "verifier", None)
        if verifier is None or not verifier.ready(cancel):
            self.automatic_release_state = "waiting_independent_verifier"
            return False
        revisions = store.revisions()
        identity = FinalAcceptance.identity(self, store, AcceptancePolicy(self))
        retry_key = "automatic_acceptance_retry_" + identity["sha256"]
        retry = store.setting(retry_key, {})
        if not isinstance(retry, dict):
            retry = {}
        retry = getattr(self, "automatic_retry", {}).get(retry_key, retry)
        if time.time() < retry.get("retry_at", 0):
            self.automatic_release_state = "runtime_retry"
            return False
        self.automatic_release_state = "evaluating_tasks"
        final_receipt = signature = current_final = None
        try:
            current_final = FinalAcceptance.current(self, store, AcceptancePolicy(self))
            if current_final is None or current_final["status"] not in ("reserved", "evaluating"):
                return False
            review_path = safe_path(directory, pointer["review_file"])
            review = checked_json(review_path)
            evaluation_path = safe_path(directory, review["evaluation_file"])
            checksum = digest_file(evaluation_path, cancel)
            signature = (self.active_digest, self.serving_digest, checksum, revisions["training_revision"], revisions["evaluation_revision"], payload_digest(verifier.certificate))
            if signature == getattr(self, "automatic_attempt", None):
                return False
            evaluation = checked_json(evaluation_path)
            final_receipt = FinalAcceptance.validate(evaluation)
            if final_receipt["identity"] != FinalAcceptance.identity(self, store, AcceptancePolicy(self)):
                raise IneligibleSample("最终验收的冻结验证器已变化 / Frozen final acceptance verifier changed")
            current_final = FinalAcceptance.current(self, store, AcceptancePolicy(self))
            if current_final is None or current_final["status"] not in ("reserved", "evaluating") or current_final["id"] != final_receipt["sha256"]:
                self.automatic_attempt = signature
                return False
            FinalAcceptance.finish(store, final_receipt, "evaluating")
            metrics = self.training_manifest.get("metrics", {})
            if (checksum != review.get("evaluation_sha256") or evaluation.get("model", {}).get("sha256") != self.active_digest
                    or metrics.get("training_validated") is not True or metrics.get("regression", {}).get("passed") is not True
                    or not store.validation_current(metrics) or not store.validation_current(evaluation)):
                raise IneligibleSample("候选缺少当前数据版本的独立训练验证 / Candidate lacks independent training validation for the current data revision")
            cases = evaluation.get("cases", [])
            acceptance = AcceptancePolicy(self)
            acceptance.check_coverage(cases)
            baseline = copy.copy(self)
            baseline.network = self.serving_network if self.serving_network is not None else self.network
            baseline.active_digest = self.serving_digest or self.active_digest
            assessor = AudioLearner(baseline, store, self.emit)
            assessor.candidate = self.network
            rows = {split: acceptance.select(store, self, split, require_controls=True, fresh=True) for split in ("validation", "guard")}
            if any(not selected for selected in rows.values()):
                raise IneligibleSample("独立验证或保护覆盖不足 / Independent validation or guard coverage is insufficient")
            selected_rows = [row for selected in rows.values() for row in selected]
            selected_rows.extend(self._review_case(store, case, cancel) for case in cases)
            selected_rows.extend(store.sample(item["sample"]) for item in verifier.certificate["records"])
            data_snapshot = store.evaluation_snapshot(selected_rows)
            independent, improved = {}, self.serving_network is None
            for split, selected in rows.items():
                comparison = assessor._evaluate(selected, "dialogue", cancel)
                if comparison is None:
                    raise IneligibleSample("独立版本比较无法完成 / Independent version comparison could not complete")
                passed, before, after, margin = assessor._comparison(*comparison, require_improvement=False)
                independent[split] = {"passed": passed, "before": before, "after": after, "margin": margin, "sources": len(comparison[0]),
                                      "data_sha256": payload_digest([dict(row) for row in selected]), "comparison": dict(assessor.comparison_result)}
                if not passed:
                    raise AcceptanceFailed("候选相对服务模型发生回归 / Candidate regressed relative to the serving model")
                if split == "validation":
                    improved = improved or before - after > margin
            if not improved and self.service_ready():
                raise AcceptanceFailed("候选缺少开发集改进证据 / Candidate lacks development-set improvement evidence")
            measured = []
            for case in cases:
                check(cancel)
                result, files = self._task_case(store, case, directory, verifier, cancel)
                measured.append(result)
            scope_expanded = not self.service_ready() and CapabilityEvidence.automatic_scope(measured) == CapabilityEvidence.dialogue_scope
            improved = improved or scope_expanded
            if not improved:
                raise AcceptanceFailed("候选保持现有能力但尚无独立改进证据 / Candidate preserves current ability but has no independent improvement evidence")
            verifier_snapshot = verifier.snapshot(evaluation_path.parent, cancel)
            audit = {"protocol": "yuan-independent-task-release-v1", "evaluator_sha256": behavior_digest(), "candidate_sha256": self.active_digest,
                     "serving_sha256": self.serving_digest, "evaluation_sha256": checksum, "independent": independent, "improvement": bool(improved),
                     "acceptance_policy_sha256": acceptance.digest, "created": time.time(), "verifier": verifier_snapshot, "cases": measured,
                     "final_acceptance_sha256": final_receipt["sha256"], "evaluation_roles": {"validation": "tuning", "guard": "regression_selection", "release": "final_acceptance"}, "revisions": revisions, "evaluation_snapshot": data_snapshot, "scope": CapabilityEvidence.automatic_scope(measured), "scope_expanded": scope_expanded}
            audit_path = evaluation_path.with_name("automatic.json")
            atomic_json(audit_path, audit, cancel)
            review["automatic"] = {"protocol": audit["protocol"], "audit_file": audit_path.relative_to(directory).as_posix(), "audit_sha256": digest_file(audit_path, cancel)}
            check(cancel)
            if (store.setting("training_revision") != revisions["training_revision"] or not store.snapshot_valid(data_snapshot)
                    or not store.validation_current(metrics) or not store.validation_current(evaluation) or not verifier.ready(cancel)):
                raise IneligibleSample("任务验收使用的监督数据发生变化 / Supervision used by task acceptance changed")
            checks = [CapabilityEvidence.task_checks(result, audit["scope"]) for result in measured]
            capabilities = CapabilityEvidence.build(evaluation, checks, audit["scope"])
            review.update(reviewer="Yuan / independently calibrated task verification", reviewed_at=time.time(), checks=checks, capabilities=capabilities)
            atomic_json(review_path, review, cancel)
            self._load_review(review_path, pending=True, cancel=cancel)
            FinalAcceptance.finish(store, final_receipt, "accepted")
            self.automatic_release_state = "accepted_dialogue_evidence" if self.service_ready() else "accepted_task_evidence"
            self.emit("notice", key="automatic_release_pass", model=self.serving_digest, independent=independent, evidence_scope=audit["scope"])
            return True
        except Cancelled:
            self.automatic_release_state = "yielded"
            raise
        except (OSError, ValueError, TypeError, KeyError, RuntimeError, sqlite3.Error) as exc:
            retryable = isinstance(exc, (OSError, sqlite3.Error)) or isinstance(exc, RuntimeError) and not isinstance(exc, YuanError)
            retryable = retryable or isinstance(exc, YuanFault) and exc.category in ("resource", "timeout")
            if retryable:
                attempts = int(retry.get("attempts", 0)) + 1
                retry = {"attempts": attempts, "retry_at": time.time() + store.retry_delay(attempts), "reason": concise_error(exc)}
                self.automatic_retry = {retry_key: retry}
                try:
                    store.set_setting(retry_key, retry)
                except (OSError, sqlite3.Error):
                    pass
                self.automatic_release_state = "runtime_retry"
                self.emit("notice", key="automatic_release_retry", reason=concise_error(exc), retry_at=retry["retry_at"],
                          frozen_task_retained=final_receipt is not None, serving_preserved=bool(self.playback_ready))
            else:
                self.automatic_attempt = signature
                if final_receipt is None and current_final is not None:
                    final_receipt = json.loads(current_final["receipt"])
                if final_receipt is not None:
                    FinalAcceptance.finish(store, final_receipt, "rejected" if isinstance(exc, AcceptanceFailed) else "stale")
                self.automatic_release_state = "semantic_evidence_missing" if isinstance(exc, IneligibleSample) else "candidate_isolated"
                self.emit("notice", key="automatic_release_wait", reason=concise_error(exc), serving_preserved=bool(self.playback_ready))
            return False

    def _task_audio(self, path, checksum, cancel):
        import soundfile as sf
        if digest_file(path, cancel) != checksum:
            raise InvalidAudio("任务评估音频摘要不匹配 / Task evaluation audio checksum mismatch")
        info = sf.info(str(path))
        if info.samplerate != self.rate or info.channels != 1 or info.frames <= 0 or info.frames > self.capacity():
            raise InvalidAudio("任务评估音频格式或预算无效 / Invalid task evaluation audio format or budget")
        values, rate = sf.read(str(path), dtype="float32")
        check(cancel)
        return values

    def _task_case(self, store, case, directory, verifier, cancel, controls=None):
        import soundfile as sf
        pair = self._review_case(store, case, cancel)
        evidence = json.loads(pair["evidence"])
        answers = SpeechVerifier.answers(evidence)
        target = store.sample(pair["assistant_sample"])
        metadata = json.loads(target["metadata"])
        normalization = SpeechVerifier.answer_policy(evidence)
        normalized_answers = {SpeechVerifier.task_answer(answer, normalization) for answer in answers}
        if (not answers or metadata.get("transcript_verified") is not True
                or SpeechVerifier.task_answer(metadata.get("transcript", ""), normalization) not in normalized_answers):
            raise IneligibleSample("任务缺少已验证的参考答案集合 / Task lacks verified reference answer sets")
        output = self._task_audio(safe_path(directory, case["output_file"]), case["output_sha256"], cancel)
        result = verifier.assess(output, evidence["language"], answers, case.get("generation", {}), cancel, normalization=SpeechVerifier.answer_policy(evidence))
        if not result["passed"]:
            raise AcceptanceFailed("候选未通过任务答案、音频质量或正常结束检查 / Candidate failed task answers, audio quality or natural ending checks")
        assessor = AudioLearner(self, store, self.emit)
        features, target = assessor._generation_features(pair, cancel)
        measured, files = {}, []
        dimensions = case.get("scenarios", [])
        if controls is not None and set(controls) != set(dimensions):
            raise YuanError("任务对照集合不完整 / Task contrast set is incomplete")
        for dimension in dimensions:
            check(cancel)
            control = evidence.get("contrasts", {}).get(dimension)
            alternatives = SpeechVerifier.answers(evidence, dimension)
            alternative_policy = SpeechVerifier.answer_policy(evidence, dimension)
            normalized_alternatives = {SpeechVerifier.task_answer(answer, alternative_policy) for answer in alternatives}
            if not control or not alternatives or normalized_answers.intersection(normalized_alternatives):
                raise IneligibleSample("任务缺少独立的对照答案标注 / Task lacks independently annotated contrast answers")
            alternative = assessor._contrast_features(pair, features, dimension, control, cancel)
            if controls is None:
                path = safe_path(safe_path(directory, case["output_file"]).parent, case["id"] + "-contrast-" + dimension + ".flac")
                record_path = path.with_suffix(".json")
                identity = payload_digest({"model": self.active_digest, "case": case, "dimension": dimension,
                                           "verifier": FinalAcceptance.verifier_key(verifier)})
                if record_path.exists():
                    record = checked_json(record_path)
                    if record.get("identity") != identity:
                        raise IneligibleSample("验收对照恢复身份不一致 / Acceptance contrast recovery identity differs")
                    artifact = record["artifact"]
                    if artifact.get("file") != path.relative_to(directory).as_posix():
                        raise IneligibleSample("验收对照恢复路径不一致 / Acceptance contrast recovery path differs")
                else:
                    generation = {}
                    values = self.respond_audio(alternative["prompt"], alternative["context"], alternative["source"], cancel, network=self.network, evaluation=generation)
                    sf.write(str(path), values, self.rate, format="FLAC", subtype="PCM_24")
                    with path.open("rb") as stream:
                        os.fsync(stream.fileno())
                    artifact = {"file": path.relative_to(directory).as_posix(), "sha256": digest_file(path, cancel), "generation": generation}
                    atomic_json(record_path, {"identity": identity, "artifact": artifact}, cancel)
            else:
                artifact = controls[dimension]
                path = safe_path(directory, artifact["file"])
            values = self._task_audio(path, artifact["sha256"], cancel)
            assessment = verifier.assess(values, evidence["language"], alternatives, artifact.get("generation", {}), cancel, normalization=SpeechVerifier.answer_policy(evidence, dimension))
            if not assessment["passed"]:
                raise AcceptanceFailed("提示词、输入或历史对照任务未通过 / Prompt, input or history contrast task did not pass")
            measured[dimension] = {**artifact, "assessment": assessment}
            files.append(path)
        return {"id": case["id"], "assessment": result, "controls": measured,
                "dialogue_evidence": CapabilityEvidence.dialogue_case(case, evidence)}, files

    @staticmethod
    def role_index(role):
        try:
            return ("user", "assistant", "user_partial", "assistant_interrupted").index(role)
        except ValueError as exc:
            raise YuanError("音频上下文角色无效 / Invalid audio context role") from exc

    @staticmethod
    def context_role(role, metadata):
        if role == "assistant" and (metadata.get("interrupted") or metadata.get("utterance_final") is False):
            return "assistant_interrupted"
        if role == "user" and (metadata.get("interrupted") or metadata.get("utterance_final") is False):
            return "user_partial"
        return role



class AudioLearner:
    def __init__(self, model, store, emit):
        self.model, self.store, self.emit = model, store, emit
        self.steps = model.steps
        self.data_revision = store.setting("data_revision")
        self.training_revision = store.setting("training_revision")
        self.evaluation_revision = store.setting("evaluation_revision")
        self.candidate = None
        self.optimizer = None
        self.training_loss = None
        self.dirty = False
        self.checkpoint_base = model.active_digest
        frames = max(1, model.capacity() // model.hop)
        self.validation_limit = model.policy.integer("learning", "validation_reservoir", max(1, math.isqrt(frames)), 1, max(1, math.isqrt(frames) * max(1, model.layers)))
        interval_default = max(1, math.isqrt(max(1, model.width * model.layers)))
        self.validation_interval = model.policy.integer("learning", "validation_interval", interval_default, 1, max(interval_default, math.isqrt(frames)))
        self.checkpoint_interval = model.policy.integer("learning", "checkpoint_interval", max(self.validation_interval, interval_default * 2), 1, max(self.validation_interval * 8, math.isqrt(frames) * 2))
        self.dialogue_mix = model.policy.ratio("learning", "dialogue_mix", 1 / math.sqrt(2))
        self.last_validation_step = self.steps
        self.last_checkpoint_step = self.steps
        self.training_seconds = None
        self.validation_seconds = None
        self.checkpoint_seconds = None
        self.generation_dimensions = {}
        self.model.policy.save()

    def _state(self):
        return {"steps": self.steps, "accepted": self.model.accepted, "acoustic_ready": self.model.acoustic_ready, "training_phase": self.model.training_phase(),
                "learning_model": self.model.active_digest, "serving_model": self.model.serving_digest,
                "candidate_isolated": bool(self.model.active_digest and self.model.active_digest != self.model.serving_digest),
                "dialogue_ready": self.model.dialogue_ready, "dialogue_trained": self.model.dialogue_trained, "playback_ready": self.model.playback_ready, "capability": self.model.capability()}

    def _resume_activation(self, cancel):
        if not self.model._resume_training_activation(self.store, cancel):
            return False
        self.steps = self.model.steps
        self._discard_candidate()
        return True

    def _refresh_data(self, snapshot=None):
        revisions = self.store.revisions()
        revision, training_revision = revisions["data_revision"], revisions["training_revision"]
        evaluation_revision = revisions["evaluation_revision"]
        previous_evaluation = getattr(self, "evaluation_revision", evaluation_revision)
        if revision == self.data_revision and training_revision == self.training_revision and evaluation_revision == previous_evaluation:
            return snapshot is not None and not self.store.snapshot_valid(snapshot)
        discarded = training_revision != self.training_revision
        invalidated = discarded or (not self.store.snapshot_valid(snapshot) if snapshot is not None else evaluation_revision != previous_evaluation)
        if discarded:
            self._discard_candidate()
            self.training_loss = None
        self.data_revision, self.training_revision = revision, training_revision
        self.evaluation_revision = evaluation_revision
        if invalidated:
            self.last_validation_step = max(0, self.steps - self.validation_interval)
        if invalidated:
            self.emit("learning", key="annotations_changed", data_revision=revision, training_revision=training_revision,
                      candidate_preserved=not discarded, validation_required=True, **self._state())
        return invalidated

    def _optimizer(self, network):
        parameters = sum(value.numel() for value in network.parameters())
        initial = 1 / math.sqrt(parameters)
        value = self.model.policy.measured("learning", "accepted_learning_rate", initial)
        rate = self.model.policy.number("learning", "learning_rate", value, initial / math.sqrt(parameters), min(1.0, initial * math.sqrt(self.model.width)))
        return self.model.torch.optim.AdamW(network.parameters(), lr=rate, weight_decay=1 / parameters, foreach=False if self.model.device.type == "privateuseone" else None)

    @supervised('candidate_prepare', 'learning')
    def _prepare(self, cancel):
        if self.candidate is not None:
            return
        torch = self.model.torch
        check(cancel)
        self.candidate = self.model.clone().train().requires_grad_(True)
        self.optimizer = self._optimizer(self.candidate)
        directory = safe_path(self.model.state, "learning")
        manifest = read_json(directory / "candidate.json")
        if not isinstance(manifest, dict) or manifest.get("identity") != self.model.identity() or manifest.get("training_revision") != self.training_revision:
            return
        try:
            target = safe_path(directory, manifest["file"])
            config = {key: getattr(self.model, key) for key in ("rate", "hop", "width", "layers")}
            ModelResources.checkpoint(target, ModelResources.estimate(config)["weight_bytes"] * 4)
            if manifest.get("base") != self.model.active_digest or digest_file(target, cancel) != manifest.get("sha256"):
                raise YuanError("候选存档基线或摘要不匹配 / Candidate checkpoint baseline or digest mismatch")
            state = torch.load(str(target), map_location="cpu", weights_only=True)
            if not all(isinstance(value, torch.Tensor) and torch.isfinite(value).all() for value in state["network"].values()):
                raise YuanError("候选权重无效 / Invalid candidate weights")
            self.candidate.load_state_dict(state["network"], strict=True)
            self.optimizer.load_state_dict(state["optimizer"])
            for values in self.optimizer.state.values():
                for value in values.values():
                    if isinstance(value, torch.Tensor) and not torch.isfinite(value).all():
                        raise YuanError("优化器状态无效 / Invalid optimizer state")
            steps = state["steps"]
            base_steps = self.model.steps
            last_validated = state.get("last_validation_step", base_steps)
            training_loss = state.get("training_loss")
            if (type(steps) is not int or steps < base_steps or type(last_validated) is not int or not 0 <= last_validated <= steps
                    or manifest.get("steps") != steps or training_loss is not None and
                    (isinstance(training_loss, bool) or not isinstance(training_loss, (int, float)) or not math.isfinite(training_loss))):
                raise YuanError("候选训练或验证进度无效 / Invalid candidate training or validation progress")
            timings = {}
            for key in ("training_seconds", "validation_seconds"):
                value = state.get(key)
                if value is not None and (isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0):
                    raise YuanError("候选执行时长无效 / Invalid candidate execution time")
                timings[key] = float(value) if value is not None else getattr(self, key)
            self.steps = steps
            self.model.steps = steps
            self.training_loss = float(training_loss) if training_loss is not None else None
            self.last_validation_step = (max(base_steps, last_validated) if manifest.get("evaluation_revision") == self.evaluation_revision else max(0, steps - self.validation_interval))
            self.last_checkpoint_step = steps
            self.training_seconds = timings["training_seconds"]
            self.validation_seconds = timings["validation_seconds"]
            self.dirty = False
            self.checkpoint_base = self.model.active_digest
            self.emit("learning", key="candidate_recovered", **self._state())
        except Cancelled:
            self.candidate = self.optimizer = None
            raise
        except Exception as exc:
            self.emit("notice", key="checkpoint_failure", component="candidate", reason=concise_error(exc))
            self.candidate = self.model.clone().train().requires_grad_(True)
            self.optimizer = self._optimizer(self.candidate)
            self.steps = self.model.steps
            self.training_loss = None
            self.last_validation_step = self.steps
            self.last_checkpoint_step = self.steps
            self.dirty = False
            self.checkpoint_base = self.model.active_digest

    @supervised('checkpointing', 'learning')
    def checkpoint(self, cancel, force=False):
                self._refresh_data()
                if self.candidate is None or not self.dirty and self.checkpoint_base == self.model.active_digest:
                    return
                if not force and self.steps - self.last_checkpoint_step < self.checkpoint_interval:
                    return
                began = time.monotonic()
                self.emit("phase", key="checkpointing", steps=self.steps)
                directory = safe_path(self.model.state, "learning")
                name = "candidate-" + uuid.uuid4().hex + ".pt"
                target = directory / name
                temporary = target.with_suffix(".partial")
                committed = False
                with StorageBudget(self.model.state).reserve(max(1, self.model.model_bytes * 4), "checkpoint"):
                    try:
                        check(cancel)
                        payload = {"network": {key: value.detach().cpu().contiguous() for key, value in self.candidate.state_dict().items()},
                                   "optimizer": self.optimizer.state_dict(), "steps": self.steps, "training_loss": self.training_loss,
                                   "last_validation_step": self.last_validation_step, "training_seconds": self.training_seconds, "validation_seconds": self.validation_seconds}
                        save_checkpoint(self.model.torch, payload, temporary, cancel, self.model.width * self.model.hop * 4)
                        with temporary.open("rb") as stream:
                            os.fsync(stream.fileno())
                        check(cancel)
                        os.replace(temporary, target)
                        atomic_json(directory / "candidate.json", {"identity": self.model.identity(), "base": self.model.active_digest,
                                    "file": name, "sha256": digest_file(target, cancel), "steps": self.steps, "data_revision": self.data_revision, "training_revision": self.training_revision, "evaluation_revision": self.evaluation_revision, "created": time.time()}, cancel)
                        committed = True
                        self.dirty = False
                        self.checkpoint_base = self.model.active_digest
                        self.last_checkpoint_step = self.steps
                        measured = elapsed_seconds(began)
                        self.checkpoint_seconds = measured if self.checkpoint_seconds is None else math.sqrt(self.checkpoint_seconds * measured)
                        if self.training_seconds:
                            suggested = max(1, int(math.ceil(self.checkpoint_seconds / max(timing_floor(), self.training_seconds))))
                            self.checkpoint_interval = max(self.validation_interval, int(round(math.sqrt(self.checkpoint_interval * max(self.validation_interval, suggested)))))
                        self.model.policy.observe("learning_control", "checkpoint_seconds", measured)
                        self.emit("checkpoint_saved", steps=self.steps, base=self.checkpoint_base, checkpoint_digest=read_json(directory / "candidate.json").get("sha256"))
                    finally:
                        temporary.unlink(missing_ok=True)
                        if not committed:
                            target.unlink(missing_ok=True)
                    for old in directory.glob("candidate-*.pt"):
                        if old != target:
                            try:
                                old.unlink(missing_ok=True)
                            except OSError as exc:
                                self.emit("notice", reason=concise_error(exc), component="candidate_cleanup")

    def _discard_candidate(self):
        directory = safe_path(self.model.state, "learning")
        manifest = read_json(directory / "candidate.json")
        if isinstance(manifest, dict) and isinstance(manifest.get("file"), str):
            try:
                safe_path(directory, manifest["file"]).unlink(missing_ok=True)
            except (OSError, ValueError):
                pass
        (directory / "candidate.json").unlink(missing_ok=True)
        for old in directory.glob("candidate-*.pt"):
            old.unlink(missing_ok=True)
        self.candidate = self.optimizer = None
        self.dirty = False
        self.checkpoint_base = self.model.active_digest
        self.last_checkpoint_step = self.steps

    def _prompt(self, group_id):
        session = self.store.db.execute("SELECT prompt FROM sessions WHERE id=?", (group_id,)).fetchone()
        if session and isinstance(session["prompt"], str) and session["prompt"].strip():
            return session["prompt"]
        source_id = group_id.removeprefix("public-")
        source = self.store.db.execute("SELECT metadata FROM sources WHERE id=?", (source_id,)).fetchone()
        language = self.store.setting("language", "中文")
        if source:
            try:
                metadata = json.loads(source["metadata"])
                if metadata.get("language") == "English":
                    language = "English"
                elif metadata.get("language") == "Mixed":
                    return tr("default_prompt", "中文") + " / " + tr("default_prompt", "English")
                else:
                    language = "中文"
            except (ValueError, TypeError):
                pass
        return tr("default_prompt", language)

    def _audio(self, row, cancel, start, count):
        check(cancel)
        values = self.store.read_audio(row, start, count, cancel=cancel)
        if row["rate"] != self.model.rate:
            raise YuanError("历史音频采样率不匹配 / Historical audio sample rate mismatch")
        check(cancel)
        return values

    def _context(self, group_id, before_created, source_count, cancel, excluded=()):
        hop = self.model.hop
        window = self.model.window()
        budget = max(0, self.model.capacity() // 2)
        used = 0
        context = []
        seen = set()
        for identifier in excluded:
            row = self.store.sample(identifier)
            if row is not None:
                seen.add(row["digest"])
        rows = self.store.db.execute("SELECT * FROM samples WHERE group_id=? AND created<? AND audio_status='ready' AND memory_eligible=1 ORDER BY created DESC,id DESC", (group_id, before_created))
        for previous in rows:
            check(cancel)
            if previous["id"] in excluded or previous["digest"] in seen:
                continue
            remaining = budget - used
            if remaining < hop:
                break
            take = min(window, previous["count"], remaining)
            if take < hop:
                continue
            try:
                values = self._audio(previous, cancel, previous["count"] - take, take)
                role = "assistant" if previous["role"] == "assistant" else "user"
                context.append((NativeAudio.context_role(role, json.loads(previous["metadata"])), values))
                seen.add(previous["digest"])
                used += len(values)
                self.emit("learning_context", key="history_context", sample=previous["id"], generated_as_target=False)
            except (OSError, RuntimeError, ValueError, YuanError) as exc:
                self.emit("notice", key="sample_skipped", sample=previous["id"], reason=concise_error(exc))
            if used >= budget:
                break
        context.reverse()
        return tuple(context)

    def endpoint(self, row, end):
        metadata = json.loads(row["metadata"])
        final = metadata.get("utterance_final")
        valid = isinstance(final, bool) and not any(metadata.get(key) for key in ("capture_gap", "playback_overlap", "interrupted", "discontinuous", "final"))
        if metadata.get("limited") and final is not False:
            valid = False
        return bool(valid and final and end == row["count"]), bool(valid)

    def acoustic_features(self, row, cancel, held_out=False):
        hop = self.model.hop
        total = row["count"]
        if row["generated"] or not row["learnable"] or row["task"] != "acoustic" or total < hop * 2:
            raise IneligibleSample("样本不能作为真实声学目标 / Sample cannot be used as a real acoustic target")
        window = self.model.window()
        if held_out:
            slots = max(1, (total - hop * 2) // hop + 1)
            cursor = (int(row["digest"][:16], 16) % slots) * hop
        else:
            last_start = ((total - hop) // hop) * hop
            cursor = max(0, min(int(row["cursor"]), last_start))
        start = max(hop, cursor)
        start -= start % hop
        end = min(total, start + window)
        source_start = max(0, start - window)
        audio = self._audio(row, cancel, source_start, end - source_start)
        cut = start - source_start
        source, target = audio[:cut], audio[cut:]
        if len(target) < hop:
            raise IneligibleSample("音频目标过短 / Audio target is too short")
        context = self._context(row["group_id"], row["created"], len(source), cancel, (row["id"],)) if row["origin"] == "local" else ()
        ended, end_label_valid = self.endpoint(row, end)
        return {"prompt": self._prompt(row["group_id"]), "source": source, "target": target, "ended": ended, "end_label_valid": end_label_valid, "context": context, "task": "acoustic"}, end

    def dialogue_features(self, pair, cancel, held_out=False, window_start=None):
        hop = self.model.hop
        if not self.store.trainable_pair(pair):
            raise IneligibleSample("对话配对缺少可用训练证据 / Dialogue pair lacks usable training evidence")
        user = self.store.sample(pair["user_sample"])
        target_row = self.store.sample(pair["assistant_sample"])
        if user is None or target_row is None or user["generated"] or target_row["generated"] or not user["dialogue_eligible"] or not target_row["dialogue_eligible"]:
            raise IneligibleSample("对话配对不能使用生成音频作为目标 / Generated audio cannot be a dialogue target")
        total = target_row["count"]
        if user["count"] < hop or total < hop:
            raise IneligibleSample("对话配对音频过短 / Dialogue pair audio is too short")
        window = max(hop, self.model.window() // hop * hop)
        if window_start is not None:
            if isinstance(window_start, bool) or not isinstance(window_start, int) or window_start < 0 or window_start % hop or window_start > total - hop:
                raise IneligibleSample("验证窗口位置无效 / Invalid validation window position")
            cursor = window_start
        elif held_out:
            cursor = 0
        else:
            cursor = max(0, min(int(pair["cursor"]), max(0, total - hop)))
        start = cursor - cursor % hop
        end = min(total, start + window)
        source = AudioSequence(int(user["count"]), lambda offset, count: self._audio(user, cancel, offset, count))
        target = self._audio(target_row, cancel, start, end - start)
        if len(target) < hop:
            raise IneligibleSample("对话目标过短 / Dialogue target is too short")
        context = self._context(pair["group_id"], user["created"], len(source), cancel, (user["id"], target_row["id"]))
        def prefix():
            for offset in range(0, start, window):
                yield self._audio(target_row, cancel, offset, min(window, start - offset))
        evidence = json.loads(pair["evidence"])
        ended, end_label_valid = self.endpoint(target_row, end)
        features = {"prompt": evidence["prompt"], "source": source, "target": target, "ended": ended, "end_label_valid": end_label_valid, "context": context, "task": "dialogue", "prefix": prefix if start else None}
        controls = evidence.get("contrasts", {}) if pair["verified"] else {}
        if not held_out and start == 0 and controls:
            dimension = sorted(controls)[int(pair["visits"]) % len(controls)]
            features["contrasts"] = (self._contrast_features(pair, features, dimension, controls[dimension], cancel),)
        return features, end, target_row["count"]

    def _usable(self, row, task, cancel, held_out=False, window_start=None):
        try:
            usable = self.dialogue_features(row, cancel, held_out, window_start) if task == "dialogue" else self.acoustic_features(row, cancel, held_out)
            if task == "dialogue" and row["failures"]:
                self.store.db.execute("UPDATE turn_pairs SET retry_at=0,failures=0,error='' WHERE id=?", (row["id"],))
                self.store.commit()
            return usable
        except IneligibleSample as exc:
            self.store.exclude_task(row, task, concise_error(exc))
            self.emit("notice", key="sample_skipped", sample=row["id"], task=task, retryable=False, reason=concise_error(exc))
            return None
        except Cancelled:
            raise
        except (OSError, RuntimeError, ValueError) as exc:
            if task == "dialogue":
                self.store.pair_failure(row, exc)
            else:
                self.store.audio_failure(row, exc)
            self.emit("notice", key="sample_skipped", sample=row["id"], task=task, retryable=not isinstance(exc, InvalidAudio), reason=concise_error(exc))
            return None

    def _held_out(self, task, split):
        if task != "dialogue":
            return self.store.held_out(split, self.validation_limit, min_count=self.model.hop * 2)
        rows = self.store.training_pairs(split, self.validation_limit, self.model.hop, self.model, self.model.cancel)
        return rows if len(rows) >= 2 else []

    def _evaluation_starts(self, row, task):
        if task != "dialogue":
            return (None,)
        target = self.store.sample(row["assistant_sample"])
        if target is None:
            return (0,)
        hop = self.model.hop
        window = max(hop * 2, self.model.window() // hop * hop)
        last = max(0, math.ceil((target["count"] - window) / hop))
        if not last:
            return (0,)
        count = self.model.policy.integer("learning", "validation_windows", min(self.model.layers + 2, last + 1), 2, last + 1)
        return tuple(sorted({round(index * last / (count - 1)) * hop for index in range(count)}))

    def _generation_features(self, pair, cancel):
        user, target = self.store.sample(pair["user_sample"]), self.store.sample(pair["assistant_sample"])
        if (user is None or target is None or user["generated"] or target["generated"]
                or not user["dialogue_eligible"] or not target["dialogue_eligible"]):
            raise IneligibleSample("完整生成评估需要真人输入与目标 / Full generation evaluation requires human input and target audio")
        for row in (user, target):
            self.store.read_audio(row, 0, min(row["count"], self.model.hop), cancel=cancel, verify=True)
        evidence = json.loads(pair["evidence"])
        eligibility = EvaluationEligibility.pair(self.store, self.model, pair, pair["split"])
        if not eligibility["ready"]:
            raise IneligibleSample("样本当前不可完整评估 / Sample cannot currently be evaluated in full: " + ",".join(eligibility["reasons"]))
        history, records = self.model.review_history(self.store, pair, cancel)
        source = AudioSequence(user["count"], lambda offset, count: self._audio(user, cancel, offset, count))
        return {"prompt": evidence["prompt"], "source": source, "context": history, "task_evidence": evidence}, target

    def _generated_score(self, network, features, target_row, cancel):
        np = self.model.np
        record = {"semantic_acceptance": False, "evaluation_kind": "unassessed", "dimensions": {}}
        evidence = features.get("task_evidence", {})
        verifier = getattr(self.model, "verifier", None)
        answers = SpeechVerifier.answers(evidence)
        assessable = verifier is not None and bool(answers) and verifier.ready(cancel)
        if not assessable:
            record.update(assessment_status="insufficient_evidence", reason="semantic_evidence_missing", promotion_eligible=False)
            return None, record
        total = int(target_row["count"])
        if total > self.model.reply_samples(features["source"], features["context"]) or total > EvaluationEligibility.budgets(self.model)["verifier"]:
            record.update(assessment_status="insufficient_resources", reason="reference_budget", promotion_eligible=False)
            return None, record
        try:
            generated = self.model.respond_audio(features["prompt"], features["context"], features["source"], cancel, network=network, evaluation=record)
        except Cancelled:
            raise
        except YuanError as exc:
            record.update(complete=False, passed=False, error=concise_error(exc), promotion_eligible=True,
                          assessment_status="invalid_output", evaluation_kind="annotated_answer_task",
                          dimensions={"content": 1.0, "audio_quality": 1.0, "natural_ending": 1.0})
            return 3.0, record
        energy = error = 0.0
        size = max(self.model.hop, self.model.window())
        for start in range(0, max(total, len(generated)), size):
            check(cancel)
            count = min(size, max(total, len(generated)) - start)
            reference, predicted = np.zeros(count, dtype=np.float64), np.zeros(count, dtype=np.float64)
            take = max(0, min(count, total - start))
            if take:
                reference[:take] = self._audio(target_row, cancel, start, take)
            take = max(0, min(count, len(generated) - start))
            if take:
                predicted[:take] = generated[start:start + take]
            energy += float(np.dot(reference, reference))
            difference = predicted - reference
            error += float(np.dot(difference, difference))
        if energy <= np.finfo(np.float32).eps ** 2 * max(1, total):
            raise IneligibleSample("参考回复为静音 / Reference reply is silent")
        assessment = verifier.assess(generated, evidence.get("language"), answers, record, cancel, normalization=SpeechVerifier.answer_policy(evidence))
        if assessment.get("assessment_status") == "insufficient_evidence":
            record.update(task_assessment=assessment, assessment_status="insufficient_evidence", promotion_eligible=False)
            return None, record
        dimensions = {"content": min(1.0, float(assessment["error"])), "audio_quality": float(not assessment.get("quality_passed")),
                      "natural_ending": float(not assessment.get("natural"))}
        score = math.fsum(dimensions.values())
        if not math.isfinite(score):
            raise YuanError("生成评估产生无效值 / Generation evaluation produced an invalid value")
        record.update(task_assessment=assessment, dimensions=dimensions, semantic_acceptance=assessment.get("passed") is True,
                      evaluation_kind="annotated_answer_task", assessment_status=assessment["assessment_status"], promotion_eligible=True,
                      reconstruction_diagnostic={"waveform_distance": math.sqrt(error / energy), "duration_error": abs(len(generated) - total) / max(1, total)},
                      reference_samples=total, reference_fits=True, teacher_forcing=False, audio_domain="model")
        return score, record

    def _evaluate_generation(self, rows, cancel):
        before, after, counts, axes = {}, {}, {}, {}
        self.candidate.eval()
        for index, row in enumerate(rows):
            check(cancel)
            self.emit("phase", key="validating", current=index, total=len(rows), unit="groups", split=row["split"], objective="full_dialogue_generation")
            try:
                features, target = self._generation_features(row, cancel)
                base, base_record = self._generated_score(self.model.network, features, target, cancel)
                candidate, candidate_record = self._generated_score(self.candidate, features, target, cancel)
            except IneligibleSample as exc:
                self.emit("notice", key="sample_skipped", sample=row["id"], reason=concise_error(exc))
                return None
            if base is None or candidate is None:
                self.emit("learning", key="semantic_evidence_missing", sample=row["id"], promotion_eligible=False,
                          baseline_generation=base_record, candidate_generation=candidate_record)
                return None
            group = row["group_id"]
            before[group] = before.get(group, 0.0) + base
            after[group] = after.get(group, 0.0) + candidate
            counts[group] = counts.get(group, 0) + 1
            for name in ("content", "audio_quality", "natural_ending"):
                left, right = axes.setdefault(name, ({}, {}))
                left[group] = left.get(group, 0.0) + base_record["dimensions"][name]
                right[group] = right.get(group, 0.0) + candidate_record["dimensions"][name]
            self.emit("validation_generation", sample=row["id"], split=row["split"], before=base, after=candidate,
                      baseline_generation=base_record, candidate_generation=candidate_record, teacher_forcing=False)
        if not counts:
            return None
        measurements = {}
        for name, (left, right) in axes.items():
            left = {group: value / counts[group] for group, value in left.items()}
            right = {group: value / counts[group] for group, value in right.items()}
            passed, baseline, updated, margin = self._comparison(left, right, False)
            measurements[name] = {"passed": passed, "before": baseline, "after": updated, "comparison": dict(self.comparison_result)}
        self.generation_dimensions[rows[0]["split"]] = measurements
        if not all(item["passed"] for item in measurements.values()):
            return None
        return ({group: value / counts[group] for group, value in before.items()}, {group: value / counts[group] for group, value in after.items()})

    def _evaluate(self, rows, task, cancel):
        if task == "dialogue":
            return self._evaluate_generation(rows, cancel)
        torch = self.model.torch
        before, after, weights = {}, {}, {}
        self.candidate.eval()
        for index, row in enumerate(rows):
            check(cancel)
            starts = self._evaluation_starts(row, task)
            base_total = candidate_total = weight = 0.0
            for position, start in enumerate(starts):
                self.emit("phase", key="validating", current=index, total=len(rows), unit="groups", split=row["split"], objective=task,
                          window=position + 1, windows=len(starts), window_start=start)
                with operation(self.emit, "validating", "learning"), self.model.interruptible(cancel), torch.no_grad():
                    usable = self._usable(row, task, cancel, held_out=True, window_start=start)
                    if usable is None:
                        return None
                    features = usable[0]
                    base = float(self.model.loss(self.model.network, **features, rollout=True).item())
                    candidate = float(self.model.loss(self.candidate, **features, rollout=True).item())
                if not math.isfinite(base) or not math.isfinite(candidate):
                    raise YuanError("验证指标无效 / Validation measurements are not finite")
                samples = len(features["target"])
                base_total += base * samples
                candidate_total += candidate * samples
                weight += samples
                self.emit("validation_window", sample=row["id"], group=row["group_id"], split=row["split"], objective=task,
                          start=start, end=usable[1], samples=samples, before=base, after=candidate, ending=features["ended"])
            group = row["group_id"]
            before[group] = before.get(group, 0.0) + base_total
            after[group] = after.get(group, 0.0) + candidate_total
            weights[group] = weights.get(group, 0.0) + weight
            self.emit("phase", key="validating", current=index + 1, total=len(rows), unit="groups", split=row["split"], objective=task)
        return {group: total / weights[group] for group, total in before.items()}, {group: total / weights[group] for group, total in after.items()}

    @staticmethod
    def comparison_quantile(confidence, degrees):
        if not 0.5 < confidence < 1 or type(degrees) is not int or degrees < 1:
            raise YuanError("比较置信度或自由度无效 / Invalid comparison confidence or degrees of freedom")
        epsilon = math.ulp(1.0)
        tiny = sys.float_info.min / epsilon
        def fraction(a, b, x):
            c = 1.0
            d = 1.0 - (a + b) * x / (a + 1)
            d = 1.0 / (d if abs(d) >= tiny else math.copysign(tiny, d))
            result = d
            for index in range(1, sys.float_info.mant_dig ** 2):
                twice = 2 * index
                for coefficient in (index * (b - index) * x / ((a + twice - 1) * (a + twice)),
                                    -(a + index) * (a + b + index) * x / ((a + twice) * (a + twice + 1))):
                    d = 1.0 + coefficient * d
                    c = 1.0 + coefficient / c
                    d = 1.0 / (d if abs(d) >= tiny else math.copysign(tiny, d))
                    c = c if abs(c) >= tiny else math.copysign(tiny, c)
                    delta = d * c
                    result *= delta
                if abs(delta - 1.0) <= epsilon * 4:
                    return result
            raise YuanError("比较统计量未收敛 / Comparison statistic did not converge")
        def beta(x, a, b):
            if x <= 0:
                return 0.0
            if x >= 1:
                return 1.0
            factor = math.exp(math.lgamma(a + b) - math.lgamma(a) - math.lgamma(b) + a * math.log(x) + b * math.log1p(-x))
            if x < (a + 1) / (a + b + 2):
                return factor * fraction(a, b, x) / a
            return 1.0 - factor * fraction(b, a, 1.0 - x) / b
        def survival(value):
            return beta(degrees / (degrees + value * value), degrees / 2.0, 0.5) / 2.0
        target, lower, upper = 1.0 - confidence, 0.0, 1.0
        while survival(upper) > target:
            upper *= 2
        while True:
            middle = (lower + upper) / 2
            if middle == lower or middle == upper or upper - lower <= epsilon * max(1.0, upper) * 4:
                return upper
            if survival(middle) > target:
                lower = middle
            else:
                upper = middle

    def _comparison(self, before, after, require_improvement=True):
        try:
            valid = (bool(before) and set(before) == set(after)
                     and all(not isinstance(value, bool) and math.isfinite(value) for values in (before, after) for value in values.values()))
        except (TypeError, ValueError, OverflowError):
            valid = False
        if not valid:
            raise YuanError("回归比较需要对应的有限测量 / Regression comparison requires matching finite measurements")
        count = len(before)
        baseline = math.fsum(float(value) / count for value in before.values())
        updated = math.fsum(float(value) / count for value in after.values())
        changes = [float(after[key]) - float(before[key]) for key in before]
        if not all(math.isfinite(value) for value in changes):
            raise YuanError("回归变化量超出数值范围 / Regression changes exceed the numeric range")
        acceptance = AcceptancePolicy(self.model)
        relative = float(acceptance.data.get("maximum_relative_regression", 0.0))
        absolute = float(acceptance.data.get("maximum_absolute_regression", 0.0))
        epsilon = float(self.model.torch.finfo(self.model.dtype).eps)
        tolerance = absolute + relative * abs(baseline) + epsilon * max(1.0, abs(baseline))
        per_group = {key: absolute + relative * abs(float(value)) + epsilon * max(1.0, abs(float(value))) for key, value in before.items()}
        mean = math.fsum(value / count for value in changes)
        radius = 0.0
        if count > 1:
            scale = max(1.0, *(abs(value) for value in changes))
            variance = math.fsum((value / scale - mean / scale) ** 2 for value in changes) / (count - 1)
            radius = self.comparison_quantile(acceptance.confidence, count - 1) * math.sqrt(variance / count) * scale
        upper = mean + radius
        regressions = [key for key, value in zip(before, changes) if value > per_group[key]]
        if not all(math.isfinite(value) for value in (baseline, updated, tolerance, mean, radius, upper)):
            raise YuanError("回归统计量超出数值范围 / Regression statistics exceed the numeric range")
        passed = count > 1 and not regressions and (upper < -tolerance if require_improvement else upper <= tolerance)
        reason = ("passed" if passed else "insufficient_sources" if count < 2 else "group_regression" if regressions
                  else "aggregate_regression" if mean > tolerance else "insufficient_improvement" if require_improvement else "uncertain")
        self.comparison_result = {"protocol": "paired-source-t-v1", "passed": bool(passed), "reason": reason,
                                  "sources": count, "confidence": acceptance.confidence, "mean_degradation": mean,
                                  "uncertainty_radius": radius, "degradation_upper": upper, "allowed_degradation": tolerance,
                                  "regressed_sources": len(regressions), "requires_improvement": bool(require_improvement),
                                  "acceptance_policy_sha256": acceptance.digest}
        return bool(passed), baseline, updated, radius + tolerance

    def _contrast_features(self, pair, features, dimension, control, cancel):
        alternative = dict(features)
        excluded = {self.store.sample(pair[field])["digest"] for field in ("user_sample", "assistant_sample")}
        if dimension == "prompt":
            alternative["prompt"] = control["prompt"]
        elif dimension == "input":
            row = self.store.sample(control["sample"])
            if row is None or row["group_id"] != pair["group_id"] or row["generated"] or not row["dialogue_eligible"] or row["role"] != "user" or row["digest"] in excluded:
                raise IneligibleSample("输入对照来源不符合独立验收要求 / Input contrast provenance does not satisfy independent acceptance")
            self.store.read_audio(row, 0, min(row["count"], self.model.hop), cancel=cancel, verify=True)
            alternative["source"] = AudioSequence(row["count"], lambda offset, count: self._audio(row, cancel, offset, count))
        else:
            context = []
            for identifier in control["samples"]:
                row = self.store.sample(identifier)
                if row is None or row["group_id"] != pair["group_id"] or row["generated"] or not row["dialogue_eligible"] or row["digest"] in excluded:
                    raise IneligibleSample("历史对照来源不符合独立验收要求 / History contrast provenance does not satisfy independent acceptance")
                take = row["count"]
                if sum(len(audio) for role, audio in context) + take > self.model.context_budget(len(features["source"])):
                    raise IneligibleSample("历史对照超过完整上下文预算 / History contrast exceeds the complete-context budget")
                context.append((row["role"], self._audio(row, cancel, 0, take)))
                excluded.add(row["digest"])
            if not features["context"] and not context:
                raise IneligibleSample("历史对照没有改变上下文 / History contrast does not change the context")
            alternative["context"] = tuple(context)
        alternative["task_evidence"] = features.get("task_evidence", {})
        return alternative

    def _regression(self, rows, cancel):
        from statistics import NormalDist
        acceptance = AcceptancePolicy(self.model)
        observed = {}
        evidence_rows = []
        self.candidate.eval()
        for pair in rows:
            check(cancel)
            evidence = json.loads(pair["evidence"])
            controls = evidence.get("contrasts", {})
            if not controls:
                continue
            features, target = self._generation_features(pair, cancel)
            with self.model.interruptible(cancel), self.model.torch.no_grad():
                base, base_record = self._generated_score(self.model.network, features, target, cancel)
                candidate, candidate_record = self._generated_score(self.candidate, features, target, cancel)
                if base is None or candidate is None or base_record.get("complete") is not True or candidate_record.get("complete") is not True:
                    continue
                for dimension, control in controls.items():
                    check(cancel)
                    alternative = self._contrast_features(pair, features, dimension, control, cancel)
                    wrong_base, wrong_base_record = self._generated_score(self.model.network, alternative, target, cancel)
                    wrong_candidate, wrong_candidate_record = self._generated_score(self.candidate, alternative, target, cancel)
                    if wrong_base is None or wrong_candidate is None or wrong_base_record.get("complete") is not True or wrong_candidate_record.get("complete") is not True:
                        continue
                    if not all(math.isfinite(value) for value in (base, candidate, wrong_base, wrong_candidate)):
                        raise YuanError("对照验收产生无效测量 / Contrast acceptance produced invalid measurements")
                    key = pair["split"] + ":" + evidence["language"] + ":" + dimension
                    observed.setdefault(key, {}).setdefault(pair["source_key"], []).append((wrong_base - base, wrong_candidate - candidate))
            evidence_rows.append({"pair": pair["id"], "source": pair["source_key"], "split": pair["split"], "annotation_sha256": payload_digest(evidence)})
        checks, missing = {}, []
        z = NormalDist().inv_cdf((1 + acceptance.confidence) / 2)
        for split in ("validation", "guard"):
            for language in acceptance.languages:
                for dimension in acceptance.dimensions:
                    key = split + ":" + language + ":" + dimension
                    values = [(sum(item[0] for item in source) / len(source), sum(item[1] for item in source) / len(source))
                              for source in observed.get(key, {}).values()]
                    if len(values) < acceptance.minimum:
                        missing.append(key)
                        continue
                    margins = [after for before, after in values]
                    changes = [after - before for before, after in values]
                    def bound(numbers):
                        mean = sum(numbers) / len(numbers)
                        variance = sum((value - mean) ** 2 for value in numbers) / max(1, len(numbers) - 1)
                        return mean, z * math.sqrt(variance / len(numbers))
                    margin, uncertainty = bound(margins)
                    change, change_uncertainty = bound(changes)
                    tolerance = math.sqrt(self.model.torch.finfo(self.model.dtype).eps) * max(1.0, abs(margin))
                    passed = margin - uncertainty > tolerance and change - change_uncertainty >= -tolerance
                    checks[key] = {"sources": len(values), "margin": margin, "uncertainty": uncertainty, "margin_change": change,
                                   "change_uncertainty": change_uncertainty, "passed": passed}
        return {"protocol": "yuan-generated-contrast-v2", "acceptance_policy_sha256": acceptance.digest, "checks": checks,
                "missing": missing, "passed": bool(checks) and not missing and all(row["passed"] for row in checks.values()),
                "evidence_sha256": payload_digest(evidence_rows), "semantic_acceptance": False, "teacher_forcing": False}

    def retrieval_plan(self, cancel):
        acceptance = AcceptancePolicy(self.model)
        data = MemoryCalibration(self.model, self.store).selection(acceptance, cancel, splits=("train",))
        available = [(language, labels) for language, labels in data["selected"]["train"].items() if labels[True] and labels[False]]
        if not available:
            return {"examples": (), "samples": 0}
        language, labels = available[self.steps % len(available)]
        common = sorted(set(labels[True]) & set(labels[False]))
        if common:
            source = common[(self.steps // len(available)) % len(common)]
            examples = (labels[True][source], labels[False][source])
        else:
            examples = tuple(list(labels[relevant].values())[(self.steps // len(available)) % len(labels[relevant])] for relevant in (True, False))
        samples = sum(math.ceil(count * self.model.rate / row["rate"])
                      for pair, query, candidate, example in examples
                      for row, count in ((query, query["count"]), (candidate, example["end"] - example["start"])))
        return {"examples": examples, "samples": samples, "language": language}

    def retrieval_loss(self, cancel):
        plan = self.retrieval_plan(cancel)
        if not plan["examples"]:
            return None
        torch = self.model.torch
        scores = []
        for pair, query, candidate, example in plan["examples"]:
            vectors = []
            for row, offset, count in ((query, 0, query["count"]), (candidate, example["start"], example["end"] - example["start"])):
                check(cancel)
                if row["split"] != "train" or row["generated"]:
                    raise YuanError("检索训练拒绝非训练数据 / Retrieval training rejects non-training data")
                values = self.store.read_audio(row, offset, count, cancel=cancel, verify=True)
                if row["rate"] != self.model.rate:
                    values = self.model.normalize(values, row["rate"])
                role = "assistant" if row["role"] == "assistant" else "user"
                vectors.append(self.model.memory_embedding(self.candidate, values, role, cancel))
            scores.append((vectors[0] * vectors[1]).sum(dim=-1).mean())
        temperature = self.model.policy.number("memory", "contrast_temperature", 1 / math.sqrt(self.model.width),
                                               math.sqrt(torch.finfo(self.model.dtype).eps), 1.0)
        loss = torch.nn.functional.softplus((scores[1] - scores[0]) / temperature) * temperature
        return loss, {"retrieval": float(loss.detach().item()), "retrieval_positive": float(scores[0].detach().item()),
                      "retrieval_negative": float(scores[1].detach().item()), "retrieval_language": plan["language"],
                      "retrieval_samples": plan["samples"], "retrieval_split": "train"}

    def phase_readiness(self, rows, task, metrics, cancel):
        phase = self.model.training_phase()
        result = {"phase": phase, "ready": False, "semantic_acceptance": False, "checks": {}}
        if phase in ("conditional_dialogue", "multi_turn"):
            regression = metrics.get("regression", {})
            result.update(ready=task == "dialogue" and metrics.get("training_validated") is True and regression.get("passed") is True,
                          scope="independent_generated_conditioning_contrasts", checks=copy.deepcopy(regression.get("checks", {})))
            return result
        if task != "acoustic" or metrics.get("training_validated") is not True:
            return result
        torch = self.model.torch
        self.candidate.eval()
        for split, records in rows.items():
            totals = {}
            for row in records:
                for start in self._evaluation_starts(row, task):
                    check(cancel)
                    usable = self._usable(row, task, cancel, held_out=True, window_start=start)
                    if usable is None:
                        return result
                    features = usable[0]
                    count = min(len(features["target"]), self.model.window())
                    with self.model.interruptible(cancel), torch.no_grad():
                        frames, _ = self.model._frames(features["target"][:count])
                        target = frames.reshape(1, -1)[:, :count]
                        reconstructed = self.candidate.reconstruct(frames).reshape(1, -1)[:, :count]
                        prior = torch.cat((torch.zeros_like(frames[:, :1]), frames[:, :-1]), dim=1).reshape(1, -1)[:, :count]
                        references = (torch.zeros_like(target), target.mean(dim=-1, keepdim=True).expand_as(target), prior)
                        reference = min(float(self.model._acoustic_loss(value, target).item()) for value in references)
                        actual = float(self.model._acoustic_loss(reconstructed, target).item())
                        measurements = {"representation": (reference, actual)}
                        if phase == "acoustic":
                            hidden = self.model._encode(self.candidate, features["prompt"], features["source"], features.get("context", ()), cancel, task="acoustic")
                            predicted = self.model._decode(self.candidate, hidden, count, cancel, stop=False)
                            seed, _ = self.model._frames(features["source"][-self.model.hop:])
                            repeated = seed[:, -1:].expand(1, math.ceil(count / self.model.hop), self.model.hop).reshape(1, -1)[:, :count]
                            reference = min(float(self.model._acoustic_loss(value, target).item()) for value in (torch.zeros_like(target), repeated))
                            measurements["acoustic_rollout"] = (reference, float(self.model._acoustic_loss(predicted, target).item()))
                    group = row["source_key"] if "source_key" in row.keys() else row["group_id"]
                    for dimension, (reference, actual) in measurements.items():
                        if not math.isfinite(reference) or not math.isfinite(actual):
                            raise YuanError("阶段能力测量无效 / Invalid curriculum proficiency measurement")
                        values = totals.setdefault(dimension, {}).setdefault(group, [0.0, 0.0, 0])
                        values[0] += reference * count
                        values[1] += actual * count
                        values[2] += count
            for dimension, groups in totals.items():
                reference = {group: values[0] / values[2] for group, values in groups.items()}
                actual = {group: values[1] / values[2] for group, values in groups.items()}
                passed, baseline, updated, margin = self._comparison(reference, actual, True)
                result["checks"][split + ":" + dimension] = {"passed": bool(passed), "reference": baseline, "candidate": updated,
                                                             "margin": margin, "sources": len(groups), "comparison": dict(self.comparison_result)}
        dimensions = ("representation",) if phase == "representation" else ("representation", "acoustic_rollout")
        required = {split + ":" + dimension for split in ("validation", "guard") for dimension in dimensions}
        result["ready"] = required.issubset(result["checks"]) and all(result["checks"][key]["passed"] for key in required)
        result["scope"] = "independent_audio_proficiency_against_signal_controls"
        return result

    def _select(self):
        pair = self.store.next_pair("train", self.model.hop, self.model.hop)
        sample = self.store.next_sample("train", self.model.hop * 2)
        if self.model.training_phase() in ("representation", "acoustic"):
            return ("acoustic", sample) if sample is not None else (None, None)
        if pair is None:
            return ("acoustic", sample) if sample is not None else (None, None)
        if sample is None:
            return "dialogue", pair
        errors = [self.model.policy.measured("learning", task + "_error", 1.0) for task in ("acoustic", "dialogue")]
        costs = [max(tick(), self.model.policy.measured("learning", task + "_seconds", 1.0)) for task in ("acoustic", "dialogue")]
        demands = [math.sqrt(max(tick(), error) / cost) for error, cost in zip(errors, costs)]
        threshold = demands[1] / sum(demands)
        threshold = (threshold + self.dialogue_mix) / 2
        phase = (self.steps * ((math.sqrt(5) - 1) / 2)) % 1
        return ("dialogue", pair) if phase < threshold else ("acoustic", sample)

    def _validate(self, task, train_row, cancel):
        began = time.monotonic()
        self.last_validation_step = self.steps
        coverage = None
        if task == "dialogue" or self.model.dialogue_trained:
            coverage = AcceptancePolicy(self.model).coverage(self.store, self.model, ("validation", "guard"), controls=True)
            if not coverage["ready"]:
                self.emit("learning", key="training_unvalidated", train=self.training_loss, objective=task,
                          training_validated=False, conversation_verified=False,
                          regression={"passed": False, "missing": coverage["missing"], "semantic_acceptance": False, "teacher_forcing": False},
                          **self._state())
                if self.model.dialogue_trained:
                    return False
                coverage = None
        rows = {split: self._held_out(task, split) for split in ("validation", "guard")}
        if any(not values for values in rows.values()):
            self.emit("learning", key="training_unvalidated", train=self.training_loss, objective=task,
                      validation_groups=len(rows["validation"]), guard_groups=len(rows["guard"]), **self._state())
            return False
        validation_groups = {sample["group_id"] for sample in rows["validation"]}
        guard_groups = {sample["group_id"] for sample in rows["guard"]}
        if train_row["group_id"] in validation_groups | guard_groups or validation_groups & guard_groups:
            raise YuanError("训练、验证与保护数据来源重叠 / Training, validation and guard sources overlap")
        self.store.assert_independent(list({train_row["group_id"]} | validation_groups | guard_groups))
        preserve_task = "dialogue" if task == "acoustic" and self.model.dialogue_trained else "acoustic" if task == "dialogue" else None
        preservation = {split: self._held_out(preserve_task, split) for split in ("validation", "guard")} if preserve_task is not None else {}
        selected = [value for values in rows.values() for value in values]
        selected.extend(value for values in preservation.values() for value in values)
        if coverage is not None:
            selected.extend(value for values in coverage["selected"].values() for value in values)
        snapshot = self.store.evaluation_snapshot(selected)
        self.emit("learning", key="validating", objective=task, **self._state())
        comparisons = {split: self._evaluate(values, task, cancel) for split, values in rows.items()}
        if any(value is None for value in comparisons.values()):
            self.emit("learning", key="training_unvalidated", objective=task, **self._state())
            return False
        metrics = {"train": self.training_loss, "groups": {}, "objective": "dialogue reply from real paired audio" if task == "dialogue" else "native acoustic continuation",
                   "conversation_verified": False, "semantic_acceptance": False,
                   "evidence_scope": "conditional_audio_training" if task == "dialogue" else "acoustic_training", "data_revision": self.data_revision,
                   "training_revision": self.training_revision, "evaluation_revision": self.evaluation_revision, "evaluation_snapshot": snapshot}
        passed = True
        for split, (before, after) in comparisons.items():
            okay, baseline, updated, margin = self._comparison(before, after, split == "validation")
            if split == "validation":
                metrics["tuning_passed"] = bool(okay)
            passed = passed and okay
            metrics["before" if split == "validation" else "guard_before"] = baseline
            metrics["after" if split == "validation" else "guard_after"] = updated
            metrics[split + "_margin"] = margin
            metrics[split + "_comparison"] = dict(self.comparison_result)
            metrics["groups"][split] = {key: {"before": before[key], "after": after[key]} for key in before}
        if preserve_task is not None:
            if any(not values for values in preservation.values()):
                passed = False
            else:
                preserve_checks = {split: self._evaluate(values, preserve_task, cancel) for split, values in preservation.items()}
                if any(value is None for value in preserve_checks.values()):
                    passed = False
                else:
                    for split, (before, after) in preserve_checks.items():
                        okay, baseline, updated, margin = self._comparison(before, after, False)
                        passed = passed and okay
                        metrics[preserve_task + "_" + split] = {"before": baseline, "after": updated, "margin": margin, "comparison": dict(self.comparison_result)}
        if coverage is not None:
            regression_rows = [value for values in coverage["selected"].values() for value in values]
            regression = self._regression(regression_rows, cancel)
            passed = passed and regression.get("passed") is True
            metrics["regression"] = regression
        evidence = []
        for record in [train_row, *[value for values in rows.values() for value in values]]:
            evidence.append({"group": record["group_id"], "sample": record["id"], "split": record["split"],
                             "content": payload_digest(dict(record))})
        metrics["data_evidence_sha256"] = payload_digest(evidence)
        metrics["training_components"] = dict(getattr(self, "training_components", {}))
        metrics["evaluation_dimensions"] = copy.deepcopy(self.generation_dimensions) if task == "dialogue" else {"acoustic_reconstruction": "training_diagnostic"}
        metrics["curriculum_phase"] = self.model.training_phase()
        metrics["training_validated"] = bool(passed)
        metrics["candidate_accepted"] = bool(passed)
        metrics["phase_readiness"] = self.phase_readiness(rows, task, metrics, cancel)
        metrics["phase_ready"] = bool(passed and metrics["phase_readiness"]["ready"])
        metrics["conversation_verified"] = False
        metrics["serving_conversation_verified"] = self.model.dialogue_ready
        measured = elapsed_seconds(began)
        self.validation_seconds = measured if self.validation_seconds is None else math.sqrt(self.validation_seconds * measured)
        if self.training_seconds:
            suggested = max(1, int(math.ceil(self.validation_seconds / max(timing_floor(), self.training_seconds))))
            self.validation_interval = max(1, int(round(math.sqrt(self.validation_interval * suggested))))
        check(cancel)
        if self._refresh_data(snapshot):
            return False
        metrics["evaluation_roles"] = {"validation": "tuning", "guard": "regression_selection", "release": "excluded_from_training_feedback"}
        self._adapt(task, metrics, metrics.get("tuning_passed") is True)
        if passed:
            passed = self.model.promote(self.candidate, metrics, cancel, task, self.store)
            if not passed:
                self._refresh_data()
                return False
            self._discard_candidate()
        self.emit("learning", key="promoted" if passed else "kept", **self._state(), **metrics)
        return passed

    def step(self, cancel):
        self._resume_activation(cancel)
        self._refresh_data()
        torch = self.model.torch
        task, row = self._select()
        if row is None:
            self.emit("learning", key="waiting_data", **self._state())
            return False
        with operation(self.emit, "training_data", "learning"):
            usable = self._usable(row, task, cancel)
        if usable is None:
            return False
        features = usable[0]
        cursor = usable[1]
        target_count = usable[2] if task == "dialogue" else None
        self._prepare(cancel)
        check(cancel)
        self.emit("learning", key="training_dialogue" if task == "dialogue" else "training_acoustic", sample=row["id"], group=row["group_id"], origin=row["origin"], split=row["split"], objective=task, context=len(features["context"]), **self._state())
        self.candidate.train().requires_grad_(True)
        began = time.monotonic()
        allocated = None
        retrieval_samples = self.retrieval_plan(cancel)["samples"]
        measured_frames = max(self.model.width, math.ceil((self.model.window() + retrieval_samples) / self.model.hop))
        if self.model.device.type == "cuda":
            try:
                torch.cuda.reset_peak_memory_stats(self.model.device)
                allocated = torch.cuda.memory_allocated(self.model.device)
            except RuntimeError:
                pass
        try:
            with operation(self.emit, "training_compute", "learning"), self.model.interruptible(cancel):
                self.optimizer.zero_grad(set_to_none=True)
                frames = max(1, math.ceil(len(features["target"]) / self.model.hop))
                section = "rollout_" + task
                initial = max(1, math.isqrt(frames))
                horizon = int(self.model.policy.measured(section, "accepted_frames", initial))
                failures = getattr(self, "validation_failures", 0)
                horizon = max(1, min(frames, int(horizon / math.sqrt(1 + failures))))
                weight = self.model.policy.ratio(section, "loss_weight", math.sqrt(horizon / frames))
                self.rollout_training = {"frames": horizon, "weight": weight}
                loss = self.model.loss(self.candidate, **features, rollout=True, rollout_frames=horizon, rollout_weight=weight)
                retrieval = self.retrieval_loss(cancel)
                if retrieval is not None:
                    retrieval_loss, retrieval_metrics = retrieval
                    retrieval_weight = self.model.policy.ratio("memory", "retrieval_loss_weight", 1 / math.sqrt(self.model.layers + 2))
                    scale = loss.detach().abs().clamp_min(math.sqrt(torch.finfo(self.model.dtype).eps))
                    loss = loss + retrieval_weight * scale * retrieval_loss
                    self.model.loss_components.update(retrieval_metrics, retrieval_weight=retrieval_weight)
                if not torch.isfinite(loss):
                    self.candidate = self.optimizer = None
                    self.dirty = False
                    self.emit("notice", key="candidate_reset")
                    raise YuanError("学习损失无效 / Learning loss is not finite")
                loss.backward()
                check(cancel)
                parameters = sum(value.numel() for value in self.candidate.parameters())
                torch.nn.utils.clip_grad_norm_(self.candidate.parameters(), math.sqrt(parameters), error_if_nonfinite=True)
                self.optimizer.step()
                if not tensors_finite(torch, self.candidate.parameters()):
                    self.candidate = self.optimizer = None
                    self.dirty = False
                    self.emit("notice", key="candidate_reset")
                    raise YuanError("更新产生无效数值 / Update produced non-finite values")
                self.training_loss = float(loss.item())
                self.training_components = dict(getattr(self.model, "loss_components", {}))
                self.steps += 1
                self.model.steps = self.steps
                self.dirty = True
            if allocated is not None:
                peak = max(0, torch.cuda.max_memory_allocated(self.model.device) - allocated)
                self.model.policy.observe(self.model.performance_section, "training_bytes_per_frame", peak / measured_frames)
                self.emit("learning_memory", device=str(self.model.device), peak_increment_bytes=peak, frames=measured_frames)
            self.model.training_retry_at = 0.0
            self.model.training_oom_window = None
            measured = elapsed_seconds(began)
            self.training_seconds = measured if self.training_seconds is None else math.sqrt(self.training_seconds * measured)
            actual_frames = max(1, math.ceil(len(features["target"]) / self.model.hop))
            self.model.policy.observe(self.model.performance_section, "training_seconds_per_frame", measured / actual_frames)
            self.model.policy.observe(self.model.performance_section, "workload_samples", len(features["source"]) + len(features["target"]))
            self.model.adapt_execution()
            if self._refresh_data():
                return False
            if task == "dialogue":
                self.store.advance_pair(row, cursor, target_count)
            else:
                self.store.advance(row, cursor)
            if self.steps - self.last_validation_step >= self.validation_interval:
                self._validate(task, row, cancel)
            self.checkpoint(cancel)
            return True
        finally:
            if self.optimizer is not None:
                self.optimizer.zero_grad(set_to_none=True)

    def _adapt(self, task, metrics, passed):
        validation = metrics.get("after")
        baseline = metrics.get("before")
        if validation is None or baseline is None or not all(math.isfinite(value) for value in (validation, baseline)):
            return
        progress = (baseline - validation) / max(abs(baseline), math.sqrt(self.model.torch.finfo(self.model.dtype).eps))
        self.model.policy.observe("learning", task + "_error", max(0.0, validation))
        self.model.policy.observe("learning", task + "_gain", max(0.0, progress))
        self.model.policy.observe("learning", task + "_seconds", self.training_seconds or tick())
        rollout = getattr(self, "rollout_training", {})
        if passed and rollout:
            maximum = max(1, math.ceil(self.model.window() / self.model.hop))
            horizon = min(maximum, max(rollout["frames"] + 1, math.ceil(rollout["frames"] * (1 + max(0.0, progress)))))
            self.model.policy.observe("rollout_" + task, "accepted_frames", horizon)
        if self.optimizer is not None:
            rate = self.optimizer.param_groups[0]["lr"]
            if passed:
                self.model.policy.observe("learning", "accepted_learning_rate", rate)
                self.validation_failures = 0
            else:
                self.validation_failures = getattr(self, "validation_failures", 0) + 1
                if progress <= 0:
                    factor = math.sqrt(1 + min(self.validation_failures, self.validation_interval))
                    floor = self.model.torch.finfo(self.model.dtype).eps
                    for group in self.optimizer.param_groups:
                        group["lr"] = max(floor, group["lr"] / factor)
        self.model.policy.save()


class DatasetImporter:
    def __init__(self, state, store, model, emit, namespace="workspace", root=None):
        if not isinstance(namespace, str) or not namespace.strip():
            raise YuanError("数据集来源命名空间无效 / Invalid dataset source namespace")
        self.namespace = namespace
        self.root = Path(root).resolve() if root is not None else safe_path(state, "datasets")
        if root is None:
            self.root.mkdir(parents=True, exist_ok=True)
        self.store, self.model, self.emit = store, model, emit
        self.failures = {}

    @staticmethod
    def fingerprints(data):
        fields = ("id", "role", "speaker", "sha256", "start_seconds", "reply_to", "response_verified", "utterance_final", "transcript", "transcript_verified")
        training = {key: data.get(key) for key in ("recording_id", "origin", "language", "prompt", "split")}
        training["turns"] = [{key: turn.get(key) for key in fields} for turn in data["turns"]]
        evaluation = {"training": training, "scenarios": data.get("scenarios", []),
                      "turns": [{key: turn.get(key) for key in ("id", "scenarios", "contrasts", "reference_checks", "semantic", "retrieval", "dialogue")} for turn in data["turns"]]}
        return {"training_sha256": payload_digest(training), "evaluation_sha256": payload_digest(evaluation)}

    def identity_key(self, path, data):
        identifier = data.get("dataset_id", path.name)
        if not isinstance(identifier, str) or not identifier.strip():
            raise YuanError("数据集身份无效 / Invalid dataset identity")
        return "dataset_" + payload_digest([self.namespace, identifier])

    @supervised('dataset_import', 'learning')
    def step(self, cancel, paths=None):
        with self.store.audio_files(cancel):
            return self._step(cancel, paths)

    def _step(self, cancel, paths=None):
        import numpy as np
        import soundfile as sf
        import psutil
        for path in sorted(self.root.glob("*.json") if paths is None else paths):
            check(cancel)
            if path.is_symlink():
                continue
            staged = []
            published = False
            checksum = None
            try:
                checksum = digest_file(path, cancel)
                failure = self.failures.get(path.name)
                if failure and failure["checksum"] == checksum and time.monotonic() < failure["retry_at"]:
                    continue
                data = checked_json(path)
                annotation_gaps = self.validate_annotations(data)
                self.validate_semantic(data)
                fingerprints = self.fingerprints(data)
                key = self.identity_key(path, data)
                file_key = "dataset_file_" + payload_digest([self.namespace, path.name])
                if self.store.setting(file_key) not in (None, key):
                    raise YuanError("同一数据集文件不能更换数据集身份 / A dataset file cannot change its dataset identity")
                if self.store.setting(key) == checksum:
                    self.store.set_setting(file_key, key)
                    continue
                required = ("recording_id", "reviewer", "annotation_id", "prompt", "license")
                if data.get("format") != "yuan-paired-audio-v1" or data.get("origin") != "human_recording" or data.get("language") not in ("中文", "English") or not all(isinstance(data.get(field), str) and data[field].strip() for field in required):
                    raise YuanError("缺少人工录音与标注信息 / Human recording and annotation metadata are required")
                turns = data.get("turns")
                if not isinstance(turns, list) or not turns:
                    raise YuanError("数据集没有音频轮次 / Dataset has no audio turns")
                group = "dataset-" + payload_digest(data["recording_id"])
                split = self.select_split(data)
                if split is not None and split not in ("train", "validation", "guard", "release"):
                    raise YuanError("数据集划分无效 / Invalid dataset split")
                planned = []
                identifiers = set()
                for turn in turns:
                    check(cancel)
                    if not isinstance(turn, dict) or not isinstance(turn.get("id"), str) or not turn["id"] or turn["id"] in identifiers or turn.get("role") not in ("user", "assistant") or not isinstance(turn.get("speaker"), str) or not turn["speaker"].strip() or not is_digest(turn.get("sha256")):
                        raise YuanError("音频轮次标注无效 / Invalid audio turn annotation")
                    identifiers.add(turn["id"])
                    if turn.get("utterance_final") is not None and not isinstance(turn["utterance_final"], bool):
                        raise YuanError("语句结束标注必须为完整、截断或未知 / Utterance ending must be complete, truncated or unknown")
                    target = safe_path(self.root, turn["audio"])
                    if digest_file(target, cancel) != turn["sha256"]:
                        raise YuanError("数据集音频摘要不匹配 / Dataset audio digest mismatch")
                    info = sf.info(str(target))
                    if info.frames <= 0 or info.samplerate <= 0 or info.channels <= 0:
                        raise YuanError("数据集音频格式无效 / Invalid dataset audio format")
                    if info.frames * max(1, info.channels) * np.dtype(np.float32).itemsize > available_resources(psutil)["memory"] // max(2, self.model.layers + 1):
                        raise MemoryError("音频超过当前导入预算 / Audio exceeds the current import memory budget")
                    timestamp = turn.get("start_seconds")
                    if isinstance(timestamp, bool) or not isinstance(timestamp, (int, float)) or not math.isfinite(timestamp) or timestamp < 0 or planned and timestamp < planned[-1][0]["start_seconds"]:
                        raise YuanError("音频轮次缺少有序时间标注 / Audio turns require ordered timestamps")
                    if turn["role"] == "assistant":
                        prior = next((item[0] for item in planned if item[0]["id"] == turn.get("reply_to")), None)
                        if prior is None or prior["role"] != "user" or prior["speaker"] == turn["speaker"] or turn.get("response_verified") is not True:
                            raise YuanError("回复关系或说话人未经标注 / Reply relation or speaker not annotated")
                    planned.append((turn, target))
                for turn, target in planned:
                    check(cancel)
                    waveform, rate = sf.read(str(target), dtype="float32", always_2d=True)
                    if digest_file(target, cancel) != turn["sha256"]:
                        raise InvalidAudio("导入期间音频发生变化 / Audio changed during import")
                    processed = self.model.normalize(waveform, int(rate))
                    prepared = self.store.prepare_audio(processed, self.model.rate, cancel)
                    staged.append((turn, prepared))
                    del waveform, processed
                if digest_file(path, cancel) != checksum:
                    raise YuanError("导入期间标注发生变化 / Annotations changed during import")
                with self.store.transaction():
                    self.store.group(group, "dataset", forced=split, source_key=data["recording_id"])
                    if self.store.setting(file_key) not in (None, key):
                        raise YuanError("同一数据集文件不能更换数据集身份 / A dataset file cannot change its dataset identity")
                    old_manifest = self.store.setting(key + "_manifest", {})
                    if old_manifest and old_manifest.get("recording_id") != data["recording_id"]:
                        raise YuanError("同一数据集文件不能更换录音来源身份 / A dataset file cannot change its recording identity")
                    changed = self.store.setting(key) not in (None, checksum)
                    if changed:
                        kind = ("content" if old_manifest.get("training_sha256") != fingerprints["training_sha256"] else
                                "evaluation" if old_manifest.get("evaluation_sha256") != fingerprints["evaluation_sha256"] else "metadata")
                        self.store.revise(group, kind)
                    retained_ids = {payload_digest([data["recording_id"], turn["id"]]) for turn in data["turns"]}
                    retired_digests = set()
                    previous_rows = self.store.db.execute("SELECT id,digest,metadata FROM samples WHERE group_id=?", (group,)).fetchall()
                    for previous in previous_rows:
                        if previous["id"] not in retained_ids and (previous["id"] in old_manifest.get("samples", []) or json.loads(previous["metadata"]).get("annotation_id") == data["annotation_id"]):
                            self.store.db.execute("UPDATE samples SET learnable=0,dialogue_eligible=0,memory_eligible=0,exclusion='annotation_removed',memory_exclusion='annotation_removed' WHERE id=?", (previous["id"],))
                            self.store.db.execute("UPDATE turn_pairs SET verified=0,eligible=0 WHERE user_sample=? OR assistant_sample=?", (previous["id"], previous["id"]))
                            self.store.db.execute("DELETE FROM memories WHERE sample_id=?", (previous["id"],))
                            retired_digests.add(previous["digest"])
                    recorded = {}
                    base_time = self.store.db.execute("SELECT created FROM groups WHERE id=?", (group,)).fetchone()[0]
                    for turn, prepared in staged:
                        check(cancel)
                        sample = self.store.add(group, turn["role"], None, self.model.rate, "dataset", cancel, created=base_time + turn["start_seconds"], sample_id=payload_digest([data["recording_id"], turn["id"]]),
                                                metadata={"recording_id": data["recording_id"], "speaker": turn["speaker"], "raw_sha256": turn["sha256"], "license": data["license"], "annotation": checksum, "annotation_id": data["annotation_id"], "utterance_final": turn.get("utterance_final"), "language": data["language"], "transcript": turn.get("transcript", ""), "transcript_verified": turn.get("transcript_verified") is True}, prepared=prepared)
                        recorded[turn["id"]] = (turn, self.store.sample(sample))
                        if turn["role"] == "assistant":
                            user_turn, user = recorded[turn["reply_to"]]
                            assistant = self.store.sample(sample)
                            evidence = {"method": "human_audio_annotation", "reviewer": data["reviewer"], "annotation_id": data["annotation_id"], "recording_id": data["recording_id"],
                                        "language": data["language"], "prompt": data["prompt"], "user_speaker": user_turn["speaker"], "assistant_speaker": turn["speaker"], "roles_verified": True,
                                        "response_verified": True, "user_sha256": user["digest"], "assistant_sha256": assistant["digest"], "annotation_sha256": checksum}
                            scenarios = turn.get("scenarios", data.get("scenarios", []))
                            if not isinstance(scenarios, list) or any(value not in AcceptancePolicy.dimensions for value in scenarios) or len(scenarios) != len(set(scenarios)):
                                raise YuanError("人工场景标注无效 / Invalid human scenario annotation")
                            evidence["scenarios"] = scenarios
                            retrieval = turn.get("retrieval")
                            if retrieval is not None:
                                if not isinstance(retrieval, dict) or retrieval.get("verified") is not True or retrieval.get("method") != "human_retrieval_relevance_v1" or not isinstance(retrieval.get("examples"), list) or not retrieval["examples"]:
                                    raise YuanError("检索相关性标注无效 / Invalid retrieval relevance annotations")
                                examples = []
                                for item in retrieval["examples"]:
                                    if not isinstance(item, dict) or type(item.get("relevant")) is not bool or item.get("sample") not in recorded:
                                        raise YuanError("检索标注缺少已记录音频 / Retrieval annotation lacks a recorded audio reference")
                                    reference = recorded[item["sample"]][1]
                                    left, right = item.get("start_seconds", 0.0), item.get("end_seconds", reference["seconds"])
                                    if any(isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) for value in (left, right)) or not 0 <= left < right <= reference["seconds"]:
                                        raise YuanError("检索标注区间无效 / Invalid annotated retrieval interval")
                                    examples.append({"sample": reference["id"], "start": int(round(left * reference["rate"])), "end": min(reference["count"], int(round(right * reference["rate"]))), "relevant": item["relevant"]})
                                evidence["retrieval"] = {"method": retrieval["method"], "verified": True, "examples": examples}
                            if "dialogue" in turn:
                                evidence["dialogue"] = copy.deepcopy(turn["dialogue"])
                            if "semantic" in turn:
                                evidence["semantic"] = copy.deepcopy(turn["semantic"])
                            if "reference_checks" in turn:
                                evidence["reference_checks"] = dict(turn["reference_checks"])
                            controls = turn.get("contrasts", {})
                            if not isinstance(controls, dict) or any(value not in AcceptancePolicy.dimensions for value in controls):
                                raise YuanError("对照标注无效 / Invalid contrast annotation")
                            contrasts = {}
                            for dimension, control in controls.items():
                                if not isinstance(control, dict) or control.get("requires_different_reply") is not True or control.get("verified") is not True:
                                    raise YuanError("对照必须由人工确认需要不同回复 / Human confirmation that the contrast requires a different reply is required")
                                if dimension == "prompt":
                                    alternative = control.get("prompt")
                                    if not isinstance(alternative, str) or not alternative.strip() or alternative == data["prompt"]:
                                        raise YuanError("提示词对照无效 / Invalid prompt contrast")
                                    contrasts[dimension] = {"prompt": alternative}
                                elif dimension == "input":
                                    other = recorded.get(control.get("turn_id"))
                                    if other is None or other[0]["role"] != "user" or other[1]["id"] == user["id"]:
                                        raise YuanError("输入对照必须引用不同的真实用户音频 / Input contrast must reference different real user audio")
                                    contrasts[dimension] = {"sample": other[1]["id"]}
                                else:
                                    identifiers = control.get("turn_ids")
                                    if not isinstance(identifiers, list) or len(identifiers) != len(set(identifiers)) or any(identifier not in recorded for identifier in identifiers):
                                        raise YuanError("历史对照引用无效 / Invalid history contrast references")
                                    alternate = [recorded[identifier][1]["id"] for identifier in identifiers]
                                    if user["id"] in alternate or sample in alternate:
                                        raise YuanError("历史对照不能包含当前输入或目标 / History contrast cannot contain the current input or target")
                                    contrasts[dimension] = {"samples": alternate}
                            for dimension, specification in contrasts.items():
                                if "semantic" in controls[dimension]:
                                    specification["semantic"] = copy.deepcopy(controls[dimension]["semantic"])
                            evidence["contrasts"] = contrasts
                            self.store.add_pair(group, user["id"], sample, "annotated_human_audio", verified=True, evidence=evidence)
                    retained_pairs = {(recorded[turn["reply_to"]][1]["id"], recorded[turn["id"]][1]["id"]) for turn in data["turns"] if turn["role"] == "assistant"}
                    for prior in self.store.db.execute("SELECT id,user_sample,assistant_sample,evidence FROM turn_pairs WHERE group_id=?", (group,)).fetchall():
                        if ((prior["user_sample"], prior["assistant_sample"]) not in retained_pairs
                                and json.loads(prior["evidence"]).get("annotation_id") in (old_manifest.get("annotation_id"), data["annotation_id"])):
                            self.store.db.execute("UPDATE turn_pairs SET verified=0,eligible=0 WHERE id=?", (prior["id"],))
                    retained = {sample[1]["id"] for sample in recorded.values()}
                    for retired_digest in retired_digests:
                        self.store.refresh_audio_owner(retired_digest)
                    self.store.assert_independent([group])
                    self.store.set_setting(file_key, key)
                    self.store.set_setting(key, checksum)
                    self.store.set_setting(key + "_manifest", {"namespace": self.namespace, "dataset_id": data.get("dataset_id", path.name),
                                                              "recording_id": data["recording_id"], "annotation_id": data["annotation_id"], "samples": sorted(retained), **fingerprints})
                published = True
                self.failures.pop(path.name, None)
                self.emit("dataset_import", file=path.name, group=group, turns=len(recorded), annotation_sha256=checksum, annotation_gaps=annotation_gaps)
                if hasattr(self.model, "policy"):
                    report = AcceptancePolicy(self.model).coverage(self.store, self.model)
                    self.emit("dataset_coverage", key="dataset_coverage", missing=report["missing"], coverage=report["cells"])
                return True
            except Cancelled:
                raise
            except (OSError, ValueError, KeyError, TypeError, RuntimeError, MemoryError) as exc:
                previous = self.failures.get(path.name, {})
                attempts = previous.get("attempts", 0) + 1 if previous.get("checksum") == checksum else 1
                delay = self.store.retry_delay(attempts)
                self.failures[path.name] = {"checksum": checksum, "attempts": attempts, "retry_at": time.monotonic() + delay}
                self.emit("notice", key="dataset_rejected", file=path.name, reason=concise_error(exc), retry_seconds=delay)
            finally:
                if not published:
                    for turn, prepared in staged:
                        self.store.discard_audio(prepared)
        return False

    def select_split(self, data):
        forced = data.get("split")
        if forced is not None:
            return forced
        existing = self.store.db.execute("SELECT split FROM groups WHERE source_key=? LIMIT 1", (data["recording_id"],)).fetchone()
        if existing is not None:
            return existing[0]
        report = AcceptancePolicy(self.model).coverage(self.store, self.model)
        turns = {turn["id"]: turn for turn in data["turns"]}
        supported = {split: set() for split in ("train", "validation", "guard", "release")}
        for turn in data["turns"]:
            if turn["role"] != "assistant":
                continue
            supported["train"].add(None)
            user = turns[turn["reply_to"]]
            if turn.get("utterance_final") is not True or user.get("utterance_final") is not True:
                continue
            scenarios = set(turn.get("scenarios", data.get("scenarios", [])))
            controls = set(turn.get("contrasts", {}))
            for split in ("validation", "guard"):
                supported[split].update(scenarios & controls)
            reference = turn.get("reference_checks", {})
            if isinstance(reference, dict) and all(reference.get(key) is True for key in AcceptancePolicy.reference_checks):
                supported["release"].update(scenarios)
        if any(cell["split"] == "train" and cell["language"] == data["language"] and not cell["ready"] for cell in report["cells"]):
            return "train"
        scores = {split: 0.0 for split in supported}
        for cell in report["cells"]:
            split = cell["split"]
            if cell["language"] != data["language"] or cell["scenario"] not in supported[split]:
                continue
            have = cell["reference_sources"] if split == "release" else cell["have"]
            scores[split] += max(0, cell["need"] - have) / cell["need"]
        return max(scores, key=lambda split: scores[split]) if max(scores.values()) > 0 else "train"

    @staticmethod
    def validate_annotations(data):
        required = ("recording_id", "reviewer", "annotation_id", "prompt", "license")
        if (not isinstance(data, dict) or data.get("format") != "yuan-paired-audio-v1" or data.get("origin") != "human_recording"
                or data.get("language") not in AcceptancePolicy.languages or not all(isinstance(data.get(key), str) and data[key].strip() for key in required)):
            raise YuanError("缺少真人录音、授权或标注身份 / Human recording, license or annotation identity is missing")
        split = data.get("split")
        if split not in (None, "train", "validation", "guard", "release"):
            raise YuanError("数据集划分无效 / Invalid dataset split")
        turns = data.get("turns")
        if not isinstance(turns, list) or not turns:
            raise YuanError("数据集没有音频轮次 / Dataset has no audio turns")
        seen, gaps = {}, []
        last_time = -math.inf
        for turn in turns:
            if not isinstance(turn, dict):
                raise YuanError("音频轮次无效 / Invalid audio turn")
            identity = turn.get("id")
            if not isinstance(identity, str) or not identity or identity in seen or turn.get("role") not in ("user", "assistant"):
                raise YuanError("音频轮次身份或角色无效 / Invalid turn identity or role")
            timestamp = turn.get("start_seconds")
            if (isinstance(timestamp, bool) or not isinstance(timestamp, (int, float)) or not math.isfinite(timestamp) or timestamp < max(0, last_time)
                    or not isinstance(turn.get("speaker"), str) or not turn["speaker"].strip() or not is_digest(turn.get("sha256"))
                    or not isinstance(turn.get("audio"), str) or not turn["audio"]):
                raise YuanError("音频轮次缺少有效时间、说话人或摘要 / Turn time, speaker or checksum is invalid")
            last_time = timestamp
            ending = turn.get("utterance_final")
            if ending is not None and type(ending) is not bool:
                raise YuanError("语句结束标注无效 / Invalid utterance ending annotation")
            if ending is not True:
                gaps.append({"turn": identity, "missing": "complete_utterance"})
            if turn["role"] == "assistant":
                CapabilityEvidence.dialogue_annotation({"recording_id": data["recording_id"], "dialogue": turn.get("dialogue")})
                reference = turn.get("reference_checks")
                if reference is not None and (not isinstance(reference, dict) or any(key not in AcceptancePolicy.reference_checks or type(value) is not bool for key, value in reference.items())):
                    raise YuanError("参考回复能力标注无效 / Invalid reference reply capability annotations")
                user = seen.get(turn.get("reply_to"))
                if user is None or user["role"] != "user" or user["speaker"] == turn["speaker"] or turn.get("response_verified") is not True:
                    raise YuanError("回复关系或说话人未经标注 / Reply relation or speaker is not verified")
                scenarios = turn.get("scenarios", data.get("scenarios", []))
                if not isinstance(scenarios, list) or any(value not in AcceptancePolicy.dimensions for value in scenarios) or len(set(scenarios)) != len(scenarios):
                    raise YuanError("场景标注无效 / Invalid scenario annotations")
                controls = turn.get("contrasts", {})
                if not isinstance(controls, dict) or any(value not in AcceptancePolicy.dimensions for value in controls):
                    raise YuanError("对照标注无效 / Invalid contrast annotations")
                for dimension in AcceptancePolicy.dimensions:
                    if dimension not in scenarios:
                        gaps.append({"turn": identity, "missing": "scenario", "scenario": dimension})
                    elif split in ("validation", "guard") and dimension not in controls:
                        gaps.append({"turn": identity, "missing": "contrast", "scenario": dimension})
                history = [value for value in seen.values() if value["id"] != user["id"] and value["start_seconds"] < user["start_seconds"]]
                if "history" in scenarios and not history:
                    raise YuanError("历史场景缺少当前输入之前的真实上下文 / History scenario lacks real context preceding the input")
                for dimension, control in controls.items():
                    if not isinstance(control, dict) or control.get("requires_different_reply") is not True or control.get("verified") is not True:
                        raise YuanError("对照需要人工确认不同回复 / Contrast requires human confirmation of a different reply")
                    if dimension == "prompt":
                        alternative = control.get("prompt")
                        if not isinstance(alternative, str) or not alternative.strip() or alternative == data["prompt"]:
                            raise YuanError("提示词对照没有改变提示词 / Prompt contrast does not change the prompt")
                    elif dimension == "input":
                        other = seen.get(control.get("turn_id"))
                        if other is None or other["role"] != "user" or other["id"] == user["id"]:
                            raise YuanError("输入对照必须引用不同的真实用户音频 / Input contrast must reference different real user audio")
                    else:
                        identifiers = control.get("turn_ids")
                        if (not isinstance(identifiers, list) or not all(isinstance(value, str) for value in identifiers) or len(set(identifiers)) != len(identifiers)
                                or any(value not in seen or value == user["id"] or seen[value]["start_seconds"] >= user["start_seconds"] for value in identifiers)
                                or identifiers == [value["id"] for value in history]):
                            raise YuanError("历史对照没有改变历史，或包含当前及未来轮次 / History contrast is unchanged or includes present or future turns")
            seen[identity] = turn
        return gaps

    @staticmethod
    def validate_semantic(data):
        for turn in data.get("turns", []):
            transcript = turn.get("transcript")
            verified = turn.get("transcript_verified")
            if transcript is not None and (not isinstance(transcript, str) or not SpeechVerifier.normalize_text(transcript) or verified is not True):
                raise YuanError("转写必须来自已验证的人工录音标注 / Transcripts require verified human recording annotations")
            if verified is not None and (not isinstance(verified, bool) or verified and not transcript):
                raise YuanError("转写验证状态无效 / Invalid transcript verification status")
            contract = turn.get("semantic")
            if contract is not None:
                answers = SpeechVerifier.answers({"semantic": contract})
                if turn.get("role") != "assistant" or not answers or SpeechVerifier.normalize_answer(transcript or "") not in answers:
                    raise YuanError("任务答案必须包含参考人工录音的已验证转写 / Task answers must include the verified reference recording transcript")
            for dimension, control in turn.get("contrasts", {}).items():
                if "semantic" not in control:
                    continue
                alternatives = SpeechVerifier.answers({"semantic": control["semantic"]})
                original = SpeechVerifier.answers({"semantic": contract})
                if (dimension not in AcceptancePolicy.dimensions or not original or not alternatives or set(original).intersection(alternatives)
                        or control.get("verified") is not True or control.get("requires_different_reply") is not True):
                    raise YuanError("对照答案必须有独立标注且与原答案集合不同 / Contrast answer sets require independent annotations and must not overlap the original")



class WorkspaceAudio:
    def __init__(self, state, store, model, emit):
        self.state, self.store, self.model, self.emit = Path(state).resolve(), store, model, emit
        self.root = self.state.parent
        self.pending = self.iterator = None
        self.phase = "manifest"
        self.next_scan = 0.0
        self.importers = {}

    def paths(self, suffixes, cancel):
        for directory, names, files in os.walk(self.root, followlinks=False):
            check(cancel)
            names[:] = sorted(name for name in names if not name.startswith(".") and not (Path(directory) / name).is_symlink())
            for name in sorted(files):
                check(cancel)
                path = Path(directory) / name
                if not name.startswith(".") and path.suffix.lower() in suffixes and not path.is_symlink():
                    yield path

    def key(self, path):
        return "history_" + payload_digest(path.relative_to(self.root).as_posix())

    def signature(self, path):
        value = path.stat()
        return [value.st_size, value.st_mtime_ns, value.st_ctime_ns, value.st_dev, value.st_ino]

    def manifest(self, path, cancel):
        import psutil
        if path.stat().st_size > available_resources(psutil)["memory"] // max(2, self.model.layers + 1):
            raise MemoryError("历史标注超过可用内存 / History annotations exceed available memory")
        data = checked_json(path)
        if not isinstance(data, dict) or data.get("format") != "yuan-paired-audio-v1":
            return False
        DatasetImporter.validate_annotations(data)
        namespace = "history:" + path.parent.relative_to(self.root).as_posix()
        importer = self.importers.get(namespace)
        if importer is None:
            importer = DatasetImporter(self.state, self.store, self.model, self.emit, namespace=namespace, root=path.parent)
            self.importers[namespace] = importer
        with self.store.audio_files(cancel), self.store.transaction():
            for turn in data["turns"]:
                check(cancel)
                audio = safe_path(path.parent, turn["audio"])
                previous = self.store.setting(self.key(audio), {})
                if previous.get("group"):
                    result = self.store.db.execute("UPDATE samples SET learnable=0,dialogue_eligible=0,memory_eligible=0,exclusion='annotated_history',memory_exclusion='annotated_history' WHERE group_id=? AND (learnable=1 OR dialogue_eligible=1)", (previous["group"],))
                    if result.rowcount:
                        self.store.revise(previous["group"])
            worked = importer.step(cancel, (path,))
            if importer.failures.get(path.name):
                raise YuanError("历史对话标注或音频未通过校验 / History dialogue annotations or audio did not pass verification")
            for turn in data["turns"]:
                audio = safe_path(path.parent, turn["audio"])
                self.store.set_setting("history_claim_" + payload_digest(audio.relative_to(self.root).as_posix()), True)
        return worked

    def recording(self, path, record, cancel):
        import soundfile as sf
        import psutil
        if self.store.setting("history_claim_" + payload_digest(path.relative_to(self.root).as_posix())):
            record["complete"] = True
            return False
        check(cancel)
        if not record.get("digest"):
            record["digest"] = digest_file(path, cancel)
            record.update(group="history-" + record["digest"], cursor=0)
        with sf.SoundFile(str(path)) as stream:
            if stream.frames <= 0 or stream.samplerate <= 0 or stream.channels <= 0:
                raise InvalidAudio("历史录音无有效音频 / History recording contains no valid audio")
            start = int(record.get("cursor", 0))
            if start >= stream.frames:
                record["complete"] = True
                return False
            maximum = available_resources(psutil)["memory"] // max(1, stream.channels * self.model.np.dtype(self.model.np.float32).itemsize * 8)
            take = min(stream.frames - start, max(1, int(self.model.chunk_seconds * stream.samplerate)), max(1, maximum))
            stream.seek(start)
            waveform = stream.read(take, dtype="float32", always_2d=True)
            end, rate, total = stream.tell(), stream.samplerate, stream.frames
        check(cancel)
        if self.signature(path) != record["signature"]:
            raise InvalidAudio("导入期间历史录音发生变化 / History recording changed during import")
        metadata = {"recording_id": record["digest"], "source_file": path.relative_to(self.root).as_posix(),
                    "source_sha256": record["digest"], "source_start": start, "source_end": end, "utterance_final": None, "roles_verified": False}
        self.store.add(record["group"], "reference", self.model.normalize(waveform, rate), self.model.rate, "history", cancel,
                       sample_id=payload_digest([record["digest"], start, end, self.model.rate]), metadata=metadata)
        record.update(cursor=end, complete=end >= total)
        self.emit("history_import", key="history_import", file=path.name, current=end, total=total, unit="samples", paired=False)
        return True

    def step(self, cancel):
        check(cancel)
        if self.iterator is None and self.pending is None:
            if time.monotonic() < self.next_scan:
                return False
            self.phase = "manifest"
            self.iterator = self.paths({".json"}, cancel)
        for _ in range(max(1, math.isqrt(self.model.capacity() // self.model.hop))):
            check(cancel)
            if self.pending is None:
                try:
                    self.pending = next(self.iterator)
                except StopIteration:
                    if self.phase == "manifest":
                        self.phase = "recording"
                        self.iterator = self.paths({".wav", ".flac", ".ogg", ".oga", ".mp3", ".opus", ".aiff", ".aif"}, cancel)
                        continue
                    self.iterator = None
                    self.next_scan = time.monotonic() + self.model.policy.estimate("history", "scan_interval_seconds", self.model.chunk_seconds)
                    return False
            path, began = self.pending, time.monotonic()
            key = self.key(path)
            record = self.store.setting(key, {})
            try:
                safe_path(self.root, path.relative_to(self.root).as_posix())
                signature = self.signature(path)
                if record.get("signature") != signature:
                    record = {"signature": signature, "cursor": 0, "complete": False}
                if record.get("complete") or time.time() < record.get("retry_at", 0):
                    self.pending = None
                    continue
                worked = self.manifest(path, cancel) if self.phase == "manifest" else self.recording(path, record, cancel)
                if self.phase == "manifest":
                    record["complete"] = True
                record.update(failures=0, retry_at=0)
                self.store.set_setting(key, record)
                if record.get("complete"):
                    self.pending = None
                self.model.policy.observe("history", "import_seconds", elapsed_seconds(began))
                if worked:
                    return True
            except Cancelled:
                self.iterator = self.pending = None
                raise
            except (OSError, ValueError, KeyError, TypeError, RuntimeError, MemoryError) as exc:
                record["failures"] = int(record.get("failures", 0)) + 1
                record["retry_at"] = time.time() + self.store.retry_delay(record["failures"])
                self.store.set_setting(key, record)
                self.pending = None
                if path.suffix.lower() != ".json" or record["failures"] == 1:
                    self.emit("notice", key="history_rejected", file=path.name, reason=concise_error(exc))
        return False

class PublicDialogue:
    repository = "kyutai/DailyTalkContiguous"

    def __init__(self, state, store, model, emit):
        self.state, self.store, self.model, self.emit = Path(state), store, model, emit
        self.root = safe_path(state, "dialogue-sources")
        self.root.mkdir(parents=True, exist_ok=True)
        self.network = Network(policy=model.policy, config=NetworkConfig(state))
        self.catalog = read_json(self.root / "catalog.json")
        self.retry_at = 0.0
        self.failures = 0

    def catalog_query(self, cancel):
        self.network.cancel = cancel
        pin_key = "dialogue_pin_" + payload_digest(self.repository)
        pin = self.store.setting(pin_key, {})
        suffix = "/revision/" + pin["revision"] if re.fullmatch(r"[a-f0-9]{40}", str(pin.get("revision", ""))) else ""
        data = self.network.json("https://huggingface.co/api/datasets/" + self.repository + suffix + "?blobs=true")
        revision = data.get("sha")
        licenses = (data.get("cardData") or {}).get("license")
        licenses = [licenses] if isinstance(licenses, str) else licenses
        if (not isinstance(licenses, list) or "cc-by-sa-4.0" not in licenses
                or not isinstance(revision, str) or not re.fullmatch(r"[a-f0-9]{40}", revision)
                or data.get("gated") or data.get("disabled") or pin and pin.get("revision") != revision):
            raise InvalidDownload("公开对话授权或版本信息不完整 / Public dialogue license or revision information is incomplete")
        files = []
        for row in data.get("siblings", []):
            check(cancel)
            name = row.get("rfilename", "")
            lfs = row.get("lfs") or {}
            checksum = lfs.get("sha256", lfs.get("oid"))
            size = lfs.get("size", row.get("size"))
            if (re.fullmatch(r"data_stereo/[0-9]+\.wav", name) and is_digest(checksum)
                    and isinstance(size, int) and not isinstance(size, bool) and size > 0):
                files.append({"file": name, "sha256": checksum, "size": size})
        if not files:
            raise InvalidDownload("公开对话目录缺少可核验音频 / Public dialogue catalog has no verifiable audio")
        files.sort(key=lambda item: payload_digest(item["file"]))
        self.catalog = {"repository": self.repository, "revision": revision, "license": "CC-BY-SA-4.0", "files": files, "created": time.time()}
        self.store.set_setting(pin_key, {"revision": revision, "license": "cc-by-sa-4.0", "manifest_sha256": payload_digest(files)})
        atomic_json(self.root / "catalog.json", self.catalog, cancel)

    def validate_catalog(self):
        data = self.catalog
        if (not isinstance(data, dict) or data.get("repository") != self.repository or data.get("license") != "CC-BY-SA-4.0"
                or not re.fullmatch(r"[a-f0-9]{40}", str(data.get("revision", ""))) or not isinstance(data.get("files"), list) or not data["files"]):
            raise InvalidDownload("公开对话目录身份或授权无效 / Invalid public dialogue catalog identity or license")
        names = set()
        for item in data["files"]:
            if (not isinstance(item, dict) or not isinstance(item.get("file"), str) or not re.fullmatch(r"data_stereo/[0-9]+\.wav", item["file"])
                    or item["file"] in names or not is_digest(item.get("sha256")) or type(item.get("size")) is not int or item["size"] <= 0):
                raise InvalidDownload("公开对话目录文件信息无效 / Invalid public dialogue catalog file metadata")
            names.add(item["file"])

    @staticmethod
    def channel_turns(values):
        import numpy as np
        values = np.asarray(values, dtype=np.float32)
        if values.ndim != 2 or values.shape[1] != 2 or not len(values) or not np.isfinite(values).all():
            raise InvalidAudio("公开对话必须是有效的双声道真人录音 / Public dialogue must be a valid stereo human recording")
        active = np.abs(values) > np.finfo(np.float32).eps
        if np.any(active[:, 0] & active[:, 1]):
            raise IneligibleSample("声道发生重叠，不作为自动配对证据 / Overlapping channels cannot establish automatic pair supervision")
        indices = np.flatnonzero(np.any(active, axis=1))
        if len(indices) < 2:
            raise IneligibleSample("公开对话缺少有效发言 / Public dialogue has insufficient speech")
        speakers = active[indices].argmax(axis=1)
        switches = np.flatnonzero(speakers[1:] != speakers[:-1]) + 1
        if not len(switches):
            raise IneligibleSample("公开对话没有说话人轮换 / Public dialogue has no speaker turns")
        boundaries = [0, *[((int(indices[position - 1]) + int(indices[position]) + 1) // 2) for position in switches], len(values)]
        channels = [int(speakers[0]), *[int(speakers[position]) for position in switches]]
        return [(start, end, channel) for start, end, channel in zip(boundaries, boundaries[1:], channels)]

    def import_recording(self, asset, path, cancel):
        import soundfile as sf
        import psutil
        info = sf.info(str(path))
        if info.frames * max(1, info.channels) * self.model.np.dtype(self.model.np.float32).itemsize > available_resources(psutil)["memory"] // max(2, self.model.layers + 1):
            raise MemoryError("公开对话超过导入内存预算 / Public dialogue exceeds the import memory budget")
        if info.channels != 2 or info.samplerate <= 0 or info.frames <= 0:
            raise InvalidAudio("公开对话声道或采样率无效 / Invalid public dialogue channels or sample rate")
        values, rate = sf.read(str(path), dtype="float32", always_2d=True)
        if digest_file(path, cancel) != asset["sha256"]:
            raise InvalidDownload("公开对话音频摘要不匹配 / Public dialogue audio checksum mismatch")
        turns = self.channel_turns(values)
        first_channel = turns[0][2]
        recording = "dailytalk:" + Path(asset["file"]).stem
        group = "corpus-" + payload_digest(recording)
        prompt = "Respond naturally in English to the other speaker, using the preceding conversation."
        staged, published = [], False
        try:
            with self.store.audio_files(cancel):
                for index, (start, end, channel) in enumerate(turns):
                    check(cancel)
                    processed = self.model.normalize(values[start:end, channel], rate)
                    if len(processed) < self.model.hop:
                        raise IneligibleSample("公开对话轮次过短 / Public dialogue turn is too short")
                    prepared = self.store.prepare_audio(processed, self.model.rate, cancel)
                    metadata = {"corpus": self.repository, "recording_id": recording, "revision": self.catalog["revision"],
                                "source_file_sha256": asset["sha256"], "license": self.catalog["license"],
                                "attribution": "DailyTalk: Keon Lee, Kyumin Park, Daeyoung Kim; stereo arrangement: Kyutai",
                                "source_url": "https://huggingface.co/datasets/" + self.repository + "/resolve/" + self.catalog["revision"] + "/" + asset["file"],
                                "source_start": start, "source_end": end, "source_rate": rate, "channel": channel,
                                "turn_index": index, "channel_separation_verified": True, "utterance_final": True,
                                "training_only": True}
                    staged.append((index, start, "user" if channel == first_channel else "assistant", metadata, prepared))
                with self.store.transaction():
                    self.store.group(group, "dataset", source_key=recording, retention="training_cache",
                                     provenance={key: staged[0][3][key] for key in ("corpus", "recording_id", "revision", "source_file_sha256", "license", "attribution", "source_url")})
                    base_time = self.store.db.execute("SELECT created FROM groups WHERE id=?", (group,)).fetchone()[0]
                    prior = None
                    for index, start, role, metadata, prepared in staged:
                        check(cancel)
                        sample = self.store.add(group, role, None, self.model.rate, "dataset", cancel, created=base_time + start / rate,
                                                sample_id=payload_digest([recording, asset["sha256"], index]), metadata=metadata, prepared=prepared)
                        if role == "assistant" and prior is not None:
                            self.store.add_corpus_pair(group, prior, sample, prompt)
                        prior = sample if role == "user" else None
                    self.store.assert_independent([group])
                    self.store.set_setting("corpus_import_" + payload_digest([self.repository, asset["file"]]), asset["sha256"])
                published = True
            self.emit("dataset_import", key="public_dialogue_import", corpus=self.repository, group=group, turns=len(staged),
                      training_only=True, semantic_acceptance=False)
            return True
        finally:
            if not published:
                for index, start, role, metadata, prepared in staged:
                    self.store.discard_audio(prepared)

    @supervised("public_dialogue", "learning")
    def step(self, cancel):
        if time.monotonic() < self.retry_at:
            return False
        self.network.cancel = cancel
        try:
            if not self.catalog:
                self.catalog_query(cancel)
            try:
                self.validate_catalog()
            except InvalidDownload:
                self.catalog = {}
                (self.root / "catalog.json").unlink(missing_ok=True)
                raise
            files = self.catalog["files"]
            key = "corpus_cursor_" + payload_digest([self.repository, self.catalog["revision"]])
            saved_position = self.store.setting(key, 0)
            position = saved_position if type(saved_position) is int and 0 <= saved_position <= len(files) else 0
            for index in range(position, len(files)):
                check(cancel)
                asset = files[index]
                imported = self.store.setting("corpus_import_" + payload_digest([self.repository, asset["file"]]))
                if imported == asset["sha256"]:
                    self.store.set_setting(key, index + 1)
                    continue
                path = safe_path(self.root, asset["sha256"] + ".wav")
                with StorageBudget(self.state).reserve(asset["size"] * 2, "learning"):
                    url = "https://huggingface.co/datasets/" + self.repository + "/resolve/" + self.catalog["revision"] + "/" + asset["file"]
                    self.emit("network", key="public_dialogue_download", corpus=self.repository, current=index, total=len(files))
                    self.network.download(url, path, expected_size=asset["size"], expected_hash=asset["sha256"], max_bytes=asset["size"])
                    try:
                        result = self.import_recording(asset, path, cancel)
                    except (IneligibleSample, InvalidAudio) as exc:
                        result = False
                        self.emit("notice", key="dataset_rejected", corpus=self.repository, file=asset["file"], reason=concise_error(exc))
                    self.store.set_setting(key, index + 1)
                    path.unlink(missing_ok=True)
                self.failures = 0
                return result
            interval = self.model.policy.number("network", "dialogue_catalog_recheck_seconds", 86400.0, 1.0, 30 * 86400.0)
            self.retry_at = time.monotonic() + interval
            self.catalog = {}
            return False
        except Cancelled:
            raise
        except (OSError, ValueError, KeyError, TypeError, RuntimeError, MemoryError) as exc:
            self.failures += 1
            delay = self.store.retry_delay(self.failures)
            self.retry_at = time.monotonic() + delay
            self.emit("network", key="public_dialogue_wait", reason=concise_error(exc), retry_seconds=delay)
            return False

class PublicAudio:
    def __init__(self, state, store, model, emit):
        self.store, self.model, self.emit = store, model, emit
        self.root = safe_path(state, "sources")
        self.root.mkdir(exist_ok=True)
        tracked = {row[0] for row in self.store.db.execute("SELECT path FROM sources WHERE path IS NOT NULL")}
        pending = {row[0] for row in self.store.db.execute("SELECT id FROM sources WHERE finished=0")}
        for path in self.root.iterdir():
            if path.is_file() and path.name not in tracked and path.stem not in pending and len(path.stem) == hashlib.sha1().digest_size * 2 and all(char in "0123456789abcdef" for char in path.stem):
                path.unlink(missing_ok=True)
        self.next_network = 0.0
        self.failures = 0
        self.empty_queries = 0
        self.duration = model.chunk_seconds
        self.next_catalog = int(store.setting("source_catalog", 0))
        self.catalogs = (("Chinese", "acoustic", "Category:Spoken Chinese Wikipedia"),
                         ("English", "acoustic", "Category:Spoken English Wikipedia"),
                         ("Mixed", "dialogue", "Category:Audio files of interviews"))
        self.network = Network(policy=model.policy)

    def query(self, cancel):
        language, task, root = self.catalogs[self.next_catalog % len(self.catalogs)]
        key = "catalog_" + hashlib.sha256((language + "\0" + task + "\0" + root).encode()).hexdigest()[:16]
        catalog = self.store.setting(key, {})
        if not isinstance(catalog, dict) or not catalog.get("pending"):
            catalog = {"pending": [root], "visited": [], "continue": {}}
        current = catalog["pending"][0]
        continuation = catalog.get("continue", {})
        requested = self.model.policy.integer("network", "catalog_page_size", max(1, math.isqrt(self.model.capacity() // self.model.hop)), 1, max(1, self.model.capacity() // self.model.hop))
        params = {"action": "query", "format": "json", "generator": "categorymembers", "gcmtitle": current,
                  "gcmtype": "file|subcat", "gcmlimit": str(min(500, requested)),
                  "prop": "imageinfo|categories", "cllimit": "max", "iiprop": "url|size|mime|sha1|extmetadata"}
        if isinstance(continuation, dict):
            params.update({name: value for name, value in continuation.items() if name in ("continue", "gcmcontinue", "clcontinue", "iicontinue")})
        self.network.cancel = cancel
        result = self.network.json("https://commons.wikimedia.org/w/api.php?" + urllib.parse.urlencode(params))
        if not isinstance(result, dict) or "error" in result:
            raise YuanError("公开音频目录暂不可用 / Public audio catalog is temporarily unavailable")
        added = 0
        for page in result.get("query", {}).get("pages", {}).values():
            check(cancel)
            if page.get("ns") == 14:
                title = page.get("title")
                if isinstance(title, str) and title not in catalog["pending"] and title not in catalog["visited"]:
                    catalog["pending"].append(title)
                continue
            infos = page.get("imageinfo") or []
            if not infos:
                continue
            info = infos[0]
            metadata = info.get("extmetadata", {})
            categories = " ".join(str(item.get("title", "")) for item in page.get("categories", [])).lower()
            if any(value in categories for value in ("speech synthesis", "text-to-speech", "synthetic speech", "语音合成", "語音合成")):
                continue
            license_name = str(metadata.get("LicenseShortName", {}).get("value", "")).lower().replace("-", " ")
            license_parts = license_name.split()
            allowed_license = license_name in ("cc0", "cc0 1.0", "public domain", "public domain mark") or (
                license_parts[:2] == ["cc", "by"] and all(part == "sa" or part.replace(".", "", 1).isdigit() for part in license_parts[2:]))
            if not allowed_license:
                continue
            url = info.get("url", "")
            parsed = urllib.parse.urlparse(url)
            if parsed.scheme != "https" or parsed.hostname != "upload.wikimedia.org" or not (str(info.get("mime", "")).startswith("audio/") or info.get("mime") == "application/ogg"):
                continue
            sha1 = str(info.get("sha1", "")).lower()
            if len(sha1) != 40 or any(char not in "0123456789abcdef" for char in sha1):
                try:
                    number = int(sha1, 36)
                    if number < 0 or number.bit_length() > 160:
                        continue
                    sha1 = format(number, "040x")
                except ValueError:
                    continue
            try:
                size = int(info.get("size", 0))
            except (ValueError, TypeError):
                continue
            if size <= 0:
                continue
            provenance = {"license": metadata.get("LicenseShortName", {}).get("value", ""), "license_url": metadata.get("LicenseUrl", {}).get("value", ""),
                          "artist": metadata.get("Artist", {}).get("value", ""), "attribution": metadata.get("Attribution", {}).get("value", ""),
                          "page": info.get("descriptionurl", ""), "title": page.get("title", ""), "size": size, "sha1": sha1, "mime": info.get("mime"),
                          "language": language, "task": task, "catalog": root}
            cursor = self.store.db.execute("INSERT OR IGNORE INTO sources(id,url,metadata,created) VALUES(?,?,?,?)", (sha1, url, json.dumps(provenance, ensure_ascii=False), time.time()))
            added += max(0, cursor.rowcount)
        self.store.db.commit()
        if result.get("continue"):
            catalog["continue"] = result["continue"]
        else:
            catalog["visited"].append(catalog["pending"].pop(0))
            catalog["continue"] = {}
        self.store.set_setting(key, catalog)
        self.next_catalog += 1
        self.store.set_setting("source_catalog", self.next_catalog)
        self.emit("source_catalog", language=language, task=task, category=current, added=added, pending=len(catalog["pending"]))
        return added

    def _dialogue_segments(self, waveform):
        np = self.model.np
        frame = self.model.hop
        frame_seconds = frame / self.model.rate
        min_seconds = min(self.model.chunk_seconds / 2, (self.model.layers + 2) * math.sqrt(frame_seconds * self.model.chunk_seconds))
        minimum = max(frame * 2, int(math.ceil(min_seconds * self.model.rate / frame)) * frame)
        max_seconds = max(self.model.chunk_seconds, self.model.capacity() / self.model.rate / 2)
        gate = SpeechGate(self.model.rate, frame, self.model.chunk_seconds, max_seconds)
        segments = []
        for start in range(0, len(waveform), frame):
            piece = waveform[start:start + frame]
            if len(piece) < frame:
                piece = np.pad(piece, (0, frame - len(piece)))
            result = gate.push(piece)
            if result is not None and len(result) >= minimum:
                segments.append(np.ascontiguousarray(result, dtype=np.float32))
        tail = gate.flush()
        if tail is not None and len(tail) >= minimum:
            segments.append(np.ascontiguousarray(tail, dtype=np.float32))
        return segments

    def _store_waveform(self, unfinished, waveform, offset, provenance, cancel):
        processed = self.model.normalize(waveform, int(provenance["rate"])) if provenance.get("rate") else self.model.normalize(waveform, self.model.rate)
        group_id = "public-" + unfinished["id"]
        base = {"source": unfinished["id"], "url": unfinished["url"], "page": provenance.get("page", ""), "title": provenance.get("title", ""),
                "license": provenance.get("license", ""), "license_url": provenance.get("license_url", ""), "artist": provenance.get("artist", ""),
                "attribution": provenance.get("attribution", ""), "recording_id": provenance.get("recording_id") or provenance.get("page") or unfinished["id"], "source_sha1": provenance.get("sha1"), "source_offset": unfinished["offset"], "source_end": offset, "source_task": provenance.get("task", "acoustic")}
        if provenance.get("task") != "dialogue":
            self.store.add(group_id, "reference", processed, self.model.rate, "public", cancel, metadata=base, task="acoustic")
            return 0
        segments = self._dialogue_segments(processed)
        ids = []
        lengths = []
        for index, segment in enumerate(segments):
            metadata = {**base, "utterance": index, "utterances": len(segments)}
            ids.append(self.store.add(group_id, "reference", segment, self.model.rate, "public", cancel, metadata=metadata, task="acoustic"))
            lengths.append(len(segment))
        pairs = 0
        for index in range(len(ids) - 1):
            left, right = lengths[index], lengths[index + 1]
            balance = math.sqrt(min(left, right) / max(left, right)) if max(left, right) else 0.0
            if balance <= 0:
                continue
            pair = self.store.add_pair(group_id, ids[index], ids[index + 1], "public_adjacent_audio", quality=balance, verified=False)
            pairs += 1
            self.emit("dialogue_pair", key="pair_candidate", pair=pair, group=group_id, source=unfinished["id"], quality=balance, verified=False)
        return pairs

    def _next_source(self, downloaded=False):
        return self.store.db.execute("SELECT * FROM sources WHERE finished=0 AND status IN ('pending','ready','retry') AND retry_at<=? AND " + ("path IS NOT NULL" if downloaded else "path IS NULL") + " ORDER BY retry_at,created,id LIMIT 1", (time.time(),)).fetchone()

    def _source_failure(self, row, exc, permanent=False):
        failures = int(row["failures"]) + 1
        delay = self.store.retry_delay(failures)
        retry_at = 0.0 if permanent else time.time() + delay
        status = "quarantined" if permanent else "retry"
        self.store.db.execute("UPDATE sources SET status=?,retry_at=?,failures=?,last_error=?,path=CASE WHEN ? THEN NULL ELSE path END WHERE id=?", (status, retry_at, failures, concise_error(exc), int(permanent), row["id"]))
        self.store.commit()
        if permanent:
            suffix = Path(urllib.parse.urlparse(row["url"]).path).suffix.lower()
            paths = [row["path"]] if row["path"] else []
            if suffix in (".flac", ".ogg", ".oga", ".wav", ".mp3", ".opus"):
                paths.extend((row["id"] + suffix, row["id"] + suffix + ".partial"))
            for name in set(paths):
                try:
                    safe_path(self.root, name).unlink(missing_ok=True)
                except (OSError, YuanError) as cleanup:
                    self.emit("notice", component="source_cleanup", source=row["id"], reason=concise_error(cleanup))
        self.emit("notice", key="source_skipped" if permanent else "source_retry", source=row["id"], status=status, failures=failures, retry_at=retry_at, retry_seconds=None if permanent else delay, reason=concise_error(exc))

    def step(self, cancel):
        import soundfile as sf
        import psutil
        check(cancel)
        storage = StorageBudget(self.model.state).snapshot(self.model.capacity() * self.model.np.dtype(self.model.np.float32).itemsize * 2)
        if not storage["ready"]:
            self.emit("network", key="learning_storage_pause", budget=storage)
            return False
        unfinished = self._next_source(downloaded=True)
        if unfinished is None and time.monotonic() >= self.next_network:
            began = time.monotonic()
            self.network.cancel = cancel
            missing = self._next_source()
            self.emit("network", key="network")
            if missing is None:
                try:
                    added = self.query(cancel)
                    self.empty_queries = self.empty_queries + 1 if not added else 0
                    self.failures = 0
                    missing = self._next_source()
                except Cancelled:
                    raise
                except Exception as exc:
                    self.failures += 1
                    self.emit("network", key="offline", component="catalog", reason=concise_error(exc))
            if missing is not None:
                try:
                    metadata = json.loads(missing["metadata"])
                    size = metadata["size"]
                    checksum = metadata["sha1"]
                    suffix = Path(urllib.parse.urlparse(missing["url"]).path).suffix.lower()
                    if isinstance(size, bool) or not isinstance(size, int) or size <= 0 or not isinstance(checksum, str) or not re.fullmatch(r"[0-9a-f]{40}", checksum) or suffix not in (".flac", ".ogg", ".oga", ".wav", ".mp3", ".opus"):
                        raise ValueError("公开音频元数据或格式无效 / Invalid public audio metadata or format")
                    available = min(available_resources(psutil)["memory"], StorageBudget(self.model.state).snapshot()["available_bytes"])
                    budget = self.model.policy.integer("network", "pending_audio_bytes", max(1, available // max(2, self.model.layers + 1)), 1, max(1, available))
                    if size > budget:
                        raise MemoryError("公开音频超过当前下载预算 / Public audio exceeds the current download budget")
                    target = safe_path(self.root, missing["id"] + suffix)
                    self.emit("source", url=missing["url"], metadata=metadata, file=target.name)
                    with StorageBudget(self.model.state).reserve(size):
                        self.network.download(missing["url"], target, size, checksum, algorithm="sha1", max_bytes=budget,
                                              progress=lambda done, total: self.emit("source_progress", key="network", current=done, total=total, unit="bytes", file=target.name))
                    check(cancel)
                    self.store.db.execute("UPDATE sources SET path=?,status='ready',retry_at=0,failures=0,last_error='' WHERE id=?", (target.name, missing["id"]))
                    self.store.commit()
                    unfinished = self.store.db.execute("SELECT * FROM sources WHERE id=?", (missing["id"],)).fetchone()
                    self.emit("network", key="available")
                except Cancelled:
                    raise
                except Exception as exc:
                    permanent = isinstance(exc, (ValueError, KeyError, TypeError, InvalidDownload)) or isinstance(exc, urllib.error.HTTPError) and exc.code in (400, 401, 403, 404, 410)
                    self._source_failure(missing, exc, permanent)
            measured = elapsed_seconds(began)
            self.duration = math.sqrt(max(tick(), self.duration) * measured)
            if self._next_source() is not None:
                self.next_network = time.monotonic()
            else:
                ceiling = self.model.policy.number("network", "catalog_retry_max_seconds", max(self.model.chunk_seconds, self.network.timeout if hasattr(self.network, "timeout") else self.model.chunk_seconds), tick(), 86400.0)
                delay = min(ceiling, self.duration * (min(self.failures + self.empty_queries, math.sqrt(ceiling / self.duration)) + 1) ** 2)
                retry = self.store.db.execute("SELECT min(retry_at) FROM sources WHERE finished=0 AND status='retry'").fetchone()[0]
                if retry is not None:
                    delay = min(delay, max(tick(), retry - time.time()))
                self.next_network = time.monotonic() + delay
        if unfinished is None:
            return False
        path = safe_path(self.root, unfinished["path"])
        if not path.is_file():
            self.store.db.execute("UPDATE sources SET path=NULL,offset=0,status='pending',retry_at=0 WHERE id=?", (unfinished["id"],))
            self.store.commit()
            return False
        try:
            provenance = json.loads(unfinished["metadata"])
            with sf.SoundFile(str(path)) as stream:
                if unfinished["offset"] >= stream.frames:
                    self.store.db.execute("UPDATE sources SET finished=1,path=NULL,status='finished',retry_at=0 WHERE id=?", (unfinished["id"],))
                    self.store.commit()
                    path.unlink(missing_ok=True)
                    return False
                stream.seek(unfinished["offset"])
                factor = max(1.0, math.sqrt(self.model.layers + 1)) if provenance.get("task") == "dialogue" else 1.0
                take = max(1, int(self.model.chunk_seconds * factor * stream.samplerate))
                waveform = stream.read(take, dtype="float32", always_2d=True).mean(axis=1)
                offset = stream.tell()
                completed = offset >= stream.frames
                rate = int(stream.samplerate)
            check(cancel)
            if waveform.size:
                provenance["rate"] = rate
                self._store_waveform(unfinished, waveform, offset, provenance, cancel)
            self.store.db.execute("UPDATE sources SET offset=?,finished=?,path=?,status=?,retry_at=0,failures=0,last_error='' WHERE id=?", (offset, int(completed), None if completed else unfinished["path"], "finished" if completed else "ready", unfinished["id"]))
            self.store.commit()
            if completed:
                path.unlink(missing_ok=True)
            return True
        except Cancelled:
            raise
        except Exception as exc:
            permanent = isinstance(exc, (sf.LibsndfileError, ValueError, YuanError))
            self._source_failure(unfinished, exc, permanent)
            return False

class SampleRing:
    def __init__(self, capacity, rate=1):
        import numpy as np
        self.rate = float(rate)
        if not math.isfinite(self.rate) or self.rate <= 0:
            raise ValueError("采样率无效 / Invalid sample rate")
        self.np = np
        self.buffer = np.empty(max(1, int(capacity)), dtype=np.float32)
        self.read_index = self.write_index = self.count = 0
        self.lock = threading.Lock()
        self.overflows = self.dropped = self.discontinuities = 0
        self.timestamp = 0.0
        self.segments = deque()
        self.expected = None
        self.gap_pending = False

    def _discard(self, size):
        self.read_index = (self.read_index + size) % len(self.buffer)
        self.count -= size
        remaining = size
        while remaining:
            segment = self.segments[0]
            take = min(remaining, segment[0])
            segment[0] -= take
            segment[1] += take / self.rate
            remaining -= take
            if not segment[0]:
                self.segments.popleft()
        if self.segments:
            self.timestamp = self.segments[0][1]

    def write(self, values, timestamp=None, discontinuity=False):
        size = len(values)
        if not size:
            self.gap_pending = self.gap_pending or bool(discontinuity)
            return
        if not self.lock.acquire(blocking=False):
            self.overflows += 1
            self.dropped += size
            self.gap_pending = True
            return
        try:
            timestamp = time.monotonic() if timestamp is None else float(timestamp)
            if not math.isfinite(timestamp):
                self.overflows += 1
                self.dropped += size
                self.gap_pending = True
                return
            gap = self.gap_pending or bool(discontinuity)
            self.gap_pending = False
            if size > len(self.buffer):
                discarded = size - len(self.buffer)
                values = values[discarded:]
                timestamp += discarded / self.rate
                self.overflows += 1
                self.dropped += discarded
                size = len(values)
                gap = True
            tolerance = max(0.5 / self.rate, math.ulp(timestamp) * 2)
            gap = gap or self.expected is not None and abs(timestamp - self.expected) > tolerance
            missing = max(0, size - (len(self.buffer) - self.count))
            if missing:
                self.overflows += 1
                self.dropped += missing
                self._discard(missing)
                if self.segments:
                    self.segments[0][2] = True
                else:
                    gap = True
            if gap:
                self.discontinuities += 1
            first = min(size, len(self.buffer) - self.write_index)
            self.buffer[self.write_index:self.write_index + first] = values[:first]
            self.buffer[:size - first] = values[first:]
            self.write_index = (self.write_index + size) % len(self.buffer)
            self.count += size
            if self.segments and not gap:
                self.segments[-1][0] += size
            else:
                self.segments.append([size, timestamp, bool(gap)])
            self.expected = timestamp + size / self.rate
            self.timestamp = self.segments[0][1]
        finally:
            self.lock.release()

    def read_block(self, size):
        requested = min(len(self.buffer), max(0, int(size)))
        result = self.np.empty(requested, dtype=self.np.float32)
        with self.lock:
            take = min(requested, self.segments[0][0] if self.segments else 0)
            timestamp = self.segments[0][1] if self.segments else self.timestamp
            gap = bool(take and self.segments[0][2])
            first = min(take, len(self.buffer) - self.read_index)
            result[:first] = self.buffer[self.read_index:self.read_index + first]
            result[first:take] = self.buffer[:take - first]
            if take:
                self.segments[0][2] = False
                self._discard(take)
                if not self.segments:
                    self.timestamp = timestamp + take / self.rate
        return result[:take], timestamp, gap

    def read(self, size):
        values, timestamp, gap = self.read_block(size)
        return values, timestamp


class AudioPolicy:
    def __init__(self, model, devices, emit):
        import numpy as np
        import psutil
        self.policy = model.policy
        frame_seconds = model.hop / model.rate
        latency = max(frame_seconds, *(float(device.get("default_high_" + direction + "_latency", frame_seconds))
                                      for device, direction in zip(devices, ("input", "output"))))
        memory_seconds = available_resources(psutil)["memory"] / (model.rate * np.dtype(np.float32).itemsize)
        self.frame_size = model.hop
        self.segment_seconds = self.number("segment_seconds", min(model.capacity() // 2, model.input_budget or model.capacity() // 2) / model.rate, frame_seconds, min(model.capacity() / model.rate, memory_seconds / 16))
        pause_default = (model.chunk_seconds ** 2 * frame_seconds) ** (1 / 3)
        observed_pause = self.policy.estimate("audio", "within_turn_pause_seconds", pause_default)
        self.pause_seconds = self.number("pause_seconds", max(frame_seconds, observed_pause + frame_seconds), frame_seconds, self.segment_seconds)
        self.onset_seconds = self.number("onset_seconds", math.sqrt(frame_seconds), frame_seconds, self.pause_seconds)
        self.buffer_seconds = self.number("buffer_seconds", max(model.chunk_seconds, latency * 2), frame_seconds, max(frame_seconds, memory_seconds / 16))
        self.echo_seconds = self.number("echo_seconds", max(latency * 2, self.pause_seconds), frame_seconds, self.segment_seconds)
        trials = max(1, self.echo_seconds * model.rate)
        self.echo_correlation = self.number("echo_correlation", min(1.0, math.sqrt(2 * math.log(trials / np.finfo(np.float32).eps) / self.frame_size)), np.finfo(np.float32).eps, 1.0)
        self.reconnect_seconds = self.number("reconnect_seconds", math.sqrt(model.chunk_seconds * latency), frame_seconds, model.capacity_seconds)
        self.latency = self.number("latency_seconds", math.sqrt(frame_seconds * latency), frame_seconds, max(frame_seconds, latency))
        self.policy.save()
        effective = dict(self.policy.effective.get("audio", {}))
        emit("audio_policy", **effective)

    def number(self, key, default, lower, upper):
        return self.policy.number("audio", key, default, lower, upper)

class AudioPreprocessor:
    def __init__(self, input_rate, output_rate):
        if any(isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value) or value <= 0 or int(value) != value for value in (input_rate, output_rate)):
            raise InvalidAudio("音频采样率无效 / Invalid audio sample rate")
        self.input_rate, self.output_rate = int(input_rate), int(output_rate)
        self.finished = False
        self.resampler = None
        if self.input_rate != self.output_rate:
            import soxr
            self.resampler = soxr.ResampleStream(self.input_rate, self.output_rate, 1, dtype="float32", quality="HQ")

    def process(self, waveform, final=False):
        import numpy as np
        if self.finished:
            raise InvalidAudio("音频流已经结束 / Audio stream has already ended")
        values = np.asarray(waveform, dtype=np.float32)
        if values.ndim not in (1, 2) or values.ndim == 2 and values.shape[1] == 0 or not np.isfinite(values).all():
            raise InvalidAudio("输入音频无效 / Invalid input audio")
        if values.ndim == 2:
            values = values.mean(axis=1, dtype=np.float64).astype(np.float32)
        values = np.ascontiguousarray(np.clip(values, -1.0, 1.0), dtype=np.float32)
        if self.resampler is not None:
            values = self.resampler.resample_chunk(values, last=bool(final))
        self.finished = bool(final)
        if not np.isfinite(values).all():
            raise InvalidAudio("处理后的音频含无效数值 / Processed audio contains invalid values")
        return np.ascontiguousarray(np.clip(values, -1.0, 1.0), dtype=np.float32)

class SpeechGate:
    def __init__(self, rate, frame_size, chunk_seconds, max_seconds, pause_seconds=None, onset_seconds=None, policy=None):
        self.rate, self.frame_size = int(rate), int(frame_size)
        self.frame_seconds = self.frame_size / self.rate
        self.pause = max(self.frame_seconds, pause_seconds or (chunk_seconds ** 2 * self.frame_seconds) ** (1 / 3))
        self.pause_limit = max(self.pause, chunk_seconds)
        self.max_frames = max(1, int(math.ceil(max_seconds / self.frame_seconds)))
        self.start_needed = max(1, int(math.ceil((onset_seconds or math.sqrt(self.frame_seconds)) / self.frame_seconds)))
        self.history = deque(maxlen=max(self.start_needed * 2, int(math.ceil(chunk_seconds / self.frame_seconds))))
        self.preroll = deque(maxlen=min(self.max_frames, max(self.start_needed, int(math.ceil(self.pause / self.frame_seconds)))))
        self.pauses = deque(maxlen=max(1, math.isqrt(self.max_frames)))
        self.bootstrap_spectrum = None
        self.frames = []
        self.silence = 0
        self.active = False
        self.limited = False
        self.start_count = 0
        self.confidence = 0.0
        self.policy = policy
        self.noise_frames = 0
        self.noise_state = "calibrating"
        self.last_voice_at = None
        self.ended_at = None
        self.sample_position = 0

    def _threshold(self):
        import numpy as np
        if len(self.history) < self.start_needed:
            return math.inf
        values = np.asarray(self.history, dtype=np.float64)
        lower = values[values <= np.median(values)]
        median = float(np.median(lower))
        deviation = float(np.median(np.abs(lower - median)))
        floor = float(np.finfo(np.float32).eps * math.sqrt(self.rate))
        spread = max(deviation, median / max(1.0, math.sqrt(len(values))), floor)
        return median + spread * max(1.0, math.log2(len(values) + 1))

    def bootstrap_voice(self, frame, level):
        import numpy as np
        floor = float(np.finfo(np.float32).eps * math.sqrt(self.rate))
        if level <= floor:
            self.bootstrap_spectrum = None
            return False, 0.0
        if len(frame) < 4:
            return True, 1.0
        middle = frame[1:-1].astype(np.float64)
        adjacent = frame[2:].astype(np.float64) + frame[:-2].astype(np.float64)
        middle = middle - middle.mean()
        adjacent = adjacent - adjacent.mean()
        denominator = float(np.dot(middle, middle))
        if denominator > np.finfo(np.float64).tiny:
            coefficient = float(np.dot(middle, adjacent) / denominator)
            residual = adjacent - coefficient * middle
            relative = math.sqrt(float(np.dot(residual, residual)) / denominator)
            if abs(coefficient) <= 2 and relative <= math.sqrt(np.finfo(np.float32).eps):
                self.bootstrap_spectrum = None
                return False, 0.0
        crossings = float(np.mean(np.signbit(frame[1:]) != np.signbit(frame[:-1])))
        window = np.hanning(len(frame)).astype(np.float64)
        power = np.abs(np.fft.rfft(frame.astype(np.float64) * window)) ** 2
        total = float(power.sum())
        if total <= np.finfo(np.float64).tiny:
            self.bootstrap_spectrum = None
            return False, 0.0
        distribution = power / total
        entropy = float(-(distribution * np.log(np.maximum(distribution, np.finfo(np.float64).tiny))).sum() / math.log(max(2, len(distribution))))
        spectrum = np.sqrt(distribution)
        if self.bootstrap_spectrum is None or len(self.bootstrap_spectrum) != len(spectrum):
            flux = 1.0
        else:
            flux = float(np.sqrt(np.mean((spectrum - self.bootstrap_spectrum) ** 2)))
        self.bootstrap_spectrum = spectrum
        zcr_limit = min(0.5, max(1 / len(frame), math.sqrt(self.frame_seconds)))
        entropy_limit = max(0.5, 1 - 1 / math.sqrt(max(2.0, math.log2(len(distribution) + 1))))
        flux_floor = 1 / max(2.0, math.sqrt(len(distribution)))
        voiced = crossings <= zcr_limit or entropy <= entropy_limit or flux >= flux_floor
        score = max(0.0, min(1.0, max((zcr_limit - crossings) / max(zcr_limit, np.finfo(np.float64).eps),
                                      (entropy_limit - entropy) / max(entropy_limit, np.finfo(np.float64).eps),
                                      flux / max(flux_floor, np.finfo(np.float64).eps) - 1)))
        return voiced, score

    def push(self, frame, timestamp=None):
        import numpy as np
        frame = np.asarray(frame, dtype=np.float32).reshape(-1)
        if not frame.size or not np.isfinite(frame).all():
            raise YuanError("检测音频无效 / Invalid detector audio")
        signal = frame.astype(np.float64) - frame.mean(dtype=np.float64)
        level = float(np.sqrt(np.mean(signal ** 2)))
        threshold = self._threshold()
        floor = float(np.finfo(np.float32).eps * math.sqrt(self.rate))
        spectral_voice, spectral_confidence = self.bootstrap_voice(signal, level)
        self.noise_frames = 0 if spectral_voice else self.noise_frames + 1
        energetic = level > threshold if math.isfinite(threshold) else level > floor
        structural_voice = energetic and spectral_voice
        voiced = structural_voice or energetic and self.active and self.noise_frames < self.start_needed
        energy_confidence = max(0.0, min(1.0, (level - threshold) / max(floor, abs(threshold)))) if math.isfinite(threshold) else 1.0
        self.confidence = min(energy_confidence, spectral_confidence) if structural_voice else 0.0
        self.noise_state = "speech" if structural_voice else "elevated_noise" if energetic else "tracking"
        end = (self.sample_position / self.rate if timestamp is None else timestamp) + len(frame) / self.rate
        self.sample_position += len(frame)
        if structural_voice:
            self.last_voice_at = end
        self.limited = False
        if not self.active:
            self.preroll.append(frame.copy())
            if not voiced:
                self.history.append(level)
            self.start_count = self.start_count + 1 if voiced else 0
            if self.start_count < self.start_needed:
                return None
            self.frames = list(self.preroll)
            self.preroll.clear()
            self.active = True
            self.silence = 0
            self.start_count = 0
        else:
            self.frames.append(frame.copy())
            if voiced:
                if self.silence:
                    self.pauses.append(self.silence * self.frame_seconds)
                    if self.policy is not None:
                        self.policy.observe("audio", "within_turn_pause_seconds", self.silence * self.frame_seconds)
                    middle = sorted(self.pauses)[len(self.pauses) // 2]
                    self.pause = min(self.pause_limit, max(self.frame_seconds, math.sqrt(max(self.frame_seconds, middle) * self.pause) + self.frame_seconds))
                self.silence = 0
            else:
                self.silence += 1
                self.history.append(level)
        self.limited = len(self.frames) >= self.max_frames
        ended = self.silence * self.frame_seconds >= self.pause
        if not ended and not self.limited:
            return None
        if ended:
            self.ended_at = end
            if self.policy is not None and self.last_voice_at is not None:
                self.policy.observe("audio", "endpoint_wait_seconds", max(0.0, end - self.last_voice_at))
        silence = self.silence
        limited = self.limited
        if limited and not ended:
            result = np.concatenate(self.frames) if self.frames else None
            self.frames = []
            self.preroll.clear()
            self.silence = silence
            self.active = True
        else:
            result = self.flush()
        self.limited = limited and not ended
        return result

    def flush(self):
        import numpy as np
        frames = self.frames if self.active else list(self.preroll) if self.start_count else []
        trim = min(max(0, self.silence - 1), max(0, len(frames) - 1))
        if trim:
            frames = frames[:-trim]
        result = np.concatenate(frames) if frames else None
        self.frames = []
        self.preroll.clear()
        self.active = False
        self.silence = self.start_count = 0
        return result

class ReplyCancel:
    def __init__(self, parent, capture, epoch, allow_speaking=False):
        self.parent, self.capture, self.epoch = parent, capture, epoch
        self.allow_speaking = bool(allow_speaking)

    def is_set(self):
        return (self.parent.is_set() or self.capture.stop_event.is_set() or self.capture.reply_epoch != self.epoch
                or (self.capture.trusted_speaking and not self.allow_speaking) or not self.capture.connected)

    def wait(self, timeout):
        deadline = time.monotonic() + max(0.0, timeout)
        while not self.is_set():
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                break
            self.parent.wait(min(remaining, math.sqrt(tick())))
        return self.is_set()

class Playback:
    def __init__(self, waveform, reference, rate, reference_rate, cancel):
        self.waveform, self.reference = waveform, reference
        self.rate, self.reference_rate, self.cancel = rate, reference_rate, cancel
        self.cursor = 0
        self.started_at = None
        self.drain_at = None
        self.interrupted = False
        self.discontinuous = False

    def played(self):
        if self.started_at is None:
            return 0
        return max(0, min(self.cursor, int((time.monotonic() - self.started_at) * self.rate)))

class PlaybackResult:
    def __init__(self, waveform, rate, generated_samples, submitted_samples, played_samples, interrupted=False, discontinuous=False, underruns=0, error=None, started_at=None):
        self.waveform = waveform
        self.rate = int(rate)
        self.generated_samples = int(generated_samples)
        self.submitted_samples = int(submitted_samples)
        self.played_samples = int(played_samples)
        self.interrupted = bool(interrupted)
        self.discontinuous = bool(discontinuous)
        self.underruns = int(underruns)
        self.error = error
        self.started_at = started_at

    def metadata(self):
        return {"interrupted": self.interrupted, "discontinuous": self.discontinuous, "playback_underruns": self.underruns,
                "generated_samples": self.generated_samples, "submitted_samples": self.submitted_samples,
                "estimated_played_samples": self.played_samples, "sample_rate": self.rate,
                "submitted_to_device": self.submitted_samples > 0, "playback_error": self.error,
                "playback_extent": "estimated", "audio_domain": "playback"}

class StreamingPlayback:
    def __init__(self, rate, reference_rate, cancel, buffer_samples, prebuffer_samples, reference_samples, timeline_samples=None):
        import numpy as np
        self.rate, self.reference_rate, self.cancel = int(rate), int(reference_rate), cancel
        self.capacity = max(1, int(buffer_samples))
        self.prebuffer = max(1, min(self.capacity, int(prebuffer_samples)))
        self._reference = np.empty(max(1, int(reference_samples)), dtype=np.float32)
        self.reference_count = 0
        self.items = deque()
        self.lock = threading.Lock()
        self.buffered = self.offset = self.cursor = 0
        self.started_at = self.drain_at = None
        self.interrupted = self.discontinuous = self.done = self.ready = False
        self.underruns = 0
        self.submitted = deque()
        self.audible_base = 0
        self.output_reference = OutputReference(self.rate, max(self.capacity, int(timeline_samples)) if timeline_samples is not None else max(self.capacity, math.ceil(reference_samples * self.rate / self.reference_rate)))

    @property
    def reference(self):
        return self._reference[:self.reference_count]

    def append_reference(self, values):
        size = len(values)
        if self.reference_count + size > len(self._reference):
            raise YuanError("播放参考超过内存边界 / Playback reference exceeds its memory boundary")
        self._reference[self.reference_count:self.reference_count + size] = values
        self.reference_count += size

    def push(self, values):
        with self.lock:
            if self.cancel.is_set() or self.interrupted or self.done or len(values) > self.capacity - self.buffered:
                return False
            if len(values):
                self.items.append(values)
                self.buffered += len(values)
            if self.buffered >= self.prebuffer:
                self.ready = True
        return True

    def finish(self):
        with self.lock:
            self.done = True
            self.ready = True

    def render(self, outdata, frames, timestamp):
        outdata.fill(0)
        if not self.lock.acquire(False):
            if self.started_at is not None:
                self.discontinuous = True
                self.underruns += 1
            self.output_reference.write(outdata[:, 0], timestamp)
            return
        try:
            if self.cancel.is_set() or self.interrupted:
                self.interrupted = True
                return
            now = time.monotonic()
            while self.submitted and self.submitted[0][1] + self.submitted[0][2] / self.rate <= now:
                start, _, size = self.submitted.popleft()
                self.audible_base = start + size
            if not self.ready:
                return
            filled = 0
            while filled < frames and self.items:
                values = self.items[0]
                size = min(frames - filled, len(values) - self.offset)
                outdata[filled:filled + size, :] = values[self.offset:self.offset + size, None]
                self.offset += size
                self.buffered -= size
                filled += size
                if self.offset == len(values):
                    self.items.popleft()
                    self.offset = 0
            if filled:
                if self.started_at is None:
                    self.started_at = timestamp
                self.submitted.append((self.cursor, timestamp, filled))
                self.cursor += filled
                self.drain_at = timestamp + filled / self.rate
            if filled < frames and not self.done:
                self.discontinuous = True
                self.underruns += 1
                self.ready = False
        finally:
            self.lock.release()
            self.output_reference.write(outdata[:, 0], timestamp)

    def played(self):
        with self.lock:
            total = self.audible_base
            now = time.monotonic()
            for start, timestamp, count in self.submitted:
                take = max(0, min(count, int((now - timestamp) * self.rate)))
                total = max(total, start + take)
                if take < count:
                    break
            return max(0, min(self.cursor, total))

    def result(self, values, rate, error=None):
        self.interrupted = self.interrupted or self.cancel.is_set()
        submitted = min(len(values), max(0, int(round(self.cursor * rate / self.rate))))
        complete = not self.interrupted and self.drained()
        played = len(values) if complete else min(submitted, max(0, int(self.played() * rate / self.rate)))
        if complete:
            submitted = len(values)
        return PlaybackResult(values[:played].copy(), rate, len(values), submitted, played, self.interrupted,
                              self.discontinuous, self.underruns, error, self.started_at)

    def drained(self):
        with self.lock:
            return self.done and self.buffered == 0 and (self.drain_at is None or time.monotonic() >= self.drain_at)

class OutputReference:
    def __init__(self, rate, capacity):
        import numpy as np
        self.rate = int(rate)
        if self.rate <= 0:
            raise ValueError("采样率无效 / Invalid sample rate")
        self.np = np
        self.values = np.zeros(max(1, int(capacity)), dtype=np.float32)
        self.stamps = np.full(len(self.values), -np.inf, dtype=np.float64)
        self.time_offsets = np.arange(len(self.values), dtype=np.float64) / self.rate
        self.count = 0
        self.lock = threading.Lock()
        self.latest = None
        self.dropped = 0
        self.version = 0
        self.read_retries = 0
        self.read_misses = 0

    def write(self, values, timestamp):
        if not len(values) or not math.isfinite(timestamp):
            return
        if not self.lock.acquire(False):
            self.dropped += len(values)
            return
        self.version += 1
        try:
            take = min(len(values), len(self.values))
            source = values[-take:]
            start = timestamp + (len(values) - take) / self.rate
            if self.latest is not None and start < self.latest - 0.5 / self.rate:
                self.count = 0
            offset = self.count % len(self.values)
            first = min(take, len(self.values) - offset)
            self.values[offset:offset + first] = source[:first]
            self.np.add(self.time_offsets[:first], start, out=self.stamps[offset:offset + first])
            if first < take:
                self.values[:take - first] = source[first:]
                self.np.add(self.time_offsets[first:take], start, out=self.stamps[:take - first])
            self.count += take
            self.latest = timestamp + len(values) / self.rate
        finally:
            self.version += 1
            self.lock.release()

    def _slice(self, start, stop, total):
        capacity = len(self.values)
        base = max(0, total - capacity)
        size = total - base
        def lower_bound(value, right=False):
            left, high = 0, size
            while left < high:
                middle = (left + high) // 2
                stamp = self.stamps[(base + middle) % capacity]
                if stamp < value or right and stamp == value:
                    left = middle + 1
                else:
                    high = middle
            return left
        left = lower_bound(start)
        right = lower_bound(stop, True)
        count = max(0, right - left)
        offset = (base + left) % capacity
        first = min(count, capacity - offset)
        stamps = self.np.empty(count, dtype=self.np.float64)
        values = self.np.empty(count, dtype=self.np.float32)
        stamps[:first], values[:first] = self.stamps[offset:offset + first], self.values[offset:offset + first]
        if first < count:
            stamps[first:], values[first:] = self.stamps[:count - first], self.values[:count - first]
        return stamps, values

    def window(self, start, count, rate):
        np = self.np
        if not math.isfinite(start) or not math.isfinite(rate) or rate <= 0:
            raise ValueError("参考音频时钟无效 / Invalid reference audio clock")
        result = np.zeros(max(0, int(count)), dtype=np.float64)
        known = np.zeros(len(result), dtype=bool)
        if not len(result):
            return result, known
        end = start + len(result) / rate
        stamps = values = None
        for attempt in range(max(2, math.isqrt(max(1, int(math.log2(len(self.values) + 1)))))):
            version, total = self.version, self.count
            if version % 2:
                self.read_retries += 1
                continue
            candidate_stamps, candidate_values = self._slice(start - 1 / self.rate, end + 1 / self.rate, total)
            if version == self.version:
                stamps, values = candidate_stamps, candidate_values
                break
            self.read_retries += 1
        if stamps is None:
            self.read_misses += 1
            return result, known
        if not len(stamps):
            return result, known
        times = start + np.arange(len(result)) / rate
        indices = np.searchsorted(stamps, times, side="right") - 1
        indices = np.clip(indices, 0, len(stamps) - 1)
        after = np.minimum(indices + 1, len(stamps) - 1)
        tolerance = max(0.51 / self.rate, math.ulp(max(abs(start), abs(end))) * 4)
        exact = np.abs(times - stamps[indices]) <= tolerance
        contiguous = (times >= stamps[indices]) & (times <= stamps[after]) & (stamps[after] - stamps[indices] <= 1.5 / self.rate)
        known = exact | contiguous
        spans = stamps[after] - stamps[indices]
        mix = np.divide(times - stamps[indices], spans, out=np.zeros(len(result)), where=spans > 0)
        result[known] = (values[indices] + np.clip(mix, 0, 1) * (values[after] - values[indices]))[known]
        return result, known

class EchoSuppressor:
    def __init__(self, rate, policy):
        self.rate, self.policy = rate, policy
        self.correlation = self.reduction = 0.0
        self.residual_correlation = None
        self.reference_complete = False
        self.playback_identity = None
        self.reference_epoch = None
        self.gain = None
        self.delay = None
        self.paths = ()
        self.double_talk = False
        self.reference_state = "inactive"

    def process(self, frame, timestamp, playback):
        import numpy as np
        self.correlation = self.reduction = 0.0
        self.residual_correlation = None
        self.reference_complete = False
        self.double_talk = False
        self.reference_state = "inactive"
        if playback is None or playback.started_at is None or len(frame) < 2:
            return frame, False
        timeline = getattr(playback, "output_reference", None)
        last = timeline.latest if timeline is not None else playback.started_at + playback.cursor / playback.rate
        if last is None or timestamp + len(frame) / self.rate < playback.started_at or timestamp > last + self.policy.echo_seconds:
            return frame, False
        epoch = (getattr(playback, "underruns", 0), getattr(timeline, "dropped", 0))
        if self.playback_identity is not playback or self.reference_epoch != epoch:
            self.playback_identity = playback
            self.reference_epoch = epoch
            self.gain = self.delay = None
            self.paths = ()
        self.reference_state = "missing"
        n = len(frame)
        lag = max(0, int(math.ceil(self.policy.echo_seconds * self.rate)))
        if timeline is not None:
            reference, known = timeline.window(timestamp - lag / self.rate, lag + n, self.rate)
        else:
            if playback.reference_rate != self.rate or playback.discontinuous:
                self.paths = ()
                return frame, True
            position = int(round((timestamp - playback.started_at) * self.rate)) - lag
            reference = np.zeros(lag + n, dtype=np.float64)
            known = np.zeros(lag + n, dtype=bool)
            start, end = max(0, position), min(len(playback.reference), position + len(reference), int(playback.cursor * self.rate / playback.rate))
            if end > start:
                offset = start - position
                reference[offset:offset + end - start] = playback.reference[start:end]
                known[offset:offset + end - start] = True
        microphone = np.asarray(frame, dtype=np.float64)
        reference = np.asarray(reference, dtype=np.float64)
        if (microphone.ndim != 1 or reference.ndim != 1 or len(reference) != lag + n or len(known) != len(reference)
                or not np.isfinite(microphone).all() or not np.isfinite(reference).all()):
            self.gain = self.delay = None
            self.paths = ()
            return frame, True
        if not np.all(known):
            self.gain = self.delay = None
            self.paths = ()
            return frame, True
        mean = float(microphone.mean())
        centered = microphone - mean
        energy = float(np.dot(centered, centered))
        epsilon = np.finfo(np.float32).eps ** 2 * n
        if energy <= epsilon:
            self.reference_state = "quiet"
            self.reference_complete = bool(np.all(known))
            self.residual_correlation = 0.0 if self.reference_complete else None
            return frame, True
        cumulative = np.concatenate(([0.0], np.cumsum(reference)))
        squares = np.concatenate(([0.0], np.cumsum(reference * reference)))
        counts = np.concatenate(([0], np.cumsum(known)))
        sums = cumulative[n:] - cumulative[:-n]
        energies = np.maximum(0.0, squares[n:] - squares[:-n] - sums * sums / n)
        valid = counts[n:] - counts[:-n] == n
        if not np.any(valid):
            return frame, True
        valid &= energies > epsilon
        if not np.any(valid):
            self.reference_state = "silent_reference"
            self.reference_complete = bool(np.all(known))
            self.residual_correlation = 0.0 if self.reference_complete else None
            self.double_talk = self.reference_complete
            return frame, True
        self.reference_state = "calibrating"
        self.reference_complete = True
        size = 1 << (len(reference) + n - 2).bit_length()
        spectrum = np.fft.rfft(reference, size)
        residual = centered.copy()
        indices, columns = [], []
        fitted = None
        clean_limit = max(np.finfo(np.float32).eps, min(1 - self.policy.echo_correlation, 1 / math.sqrt(n)))
        limit = min(int(np.count_nonzero(valid)), max(1, int(math.log2(n))), max(1, n // 2 - 1))
        for _ in range(limit):
            remaining = float(np.dot(residual, residual))
            if remaining <= epsilon:
                break
            cross = np.fft.irfft(spectrum * np.fft.rfft(residual[::-1], size), size)[n - 1:len(reference)]
            scores = np.abs(cross) / np.sqrt(np.maximum(np.finfo(np.float64).tiny, energies * remaining))
            scores[~valid] = 0
            scores[indices] = 0
            maximum = float(np.max(scores))
            if not indices:
                self.correlation = min(1.0, maximum)
            if maximum < self.policy.echo_correlation:
                break
            tied = np.flatnonzero(np.isclose(scores, maximum, rtol=math.sqrt(np.finfo(np.float32).eps), atol=np.finfo(np.float32).eps))
            preferred = lag - (self.delay if self.delay is not None else 0)
            best = int(tied[int(np.argmin(np.abs(tied - preferred)))])
            indices.append(best)
            columns.append(reference[best:best + n] - sums[best] / n)
            matrix = np.column_stack(columns)
            try:
                coefficients, _, rank, _ = np.linalg.lstsq(matrix, centered, rcond=None)
            except np.linalg.LinAlgError:
                break
            if rank != len(indices) or not np.isfinite(coefficients).all():
                break
            residual = centered - matrix @ coefficients
            if float(np.dot(residual, residual)) / energy > clean_limit:
                continue
            verified = n >= 4
            for offset in (0, 1):
                train, test = slice(offset, None, 2), slice(1 - offset, None, 2)
                try:
                    held_coefficients, _, held_rank, _ = np.linalg.lstsq(matrix[train], centered[train], rcond=None)
                except np.linalg.LinAlgError:
                    verified = False
                    break
                held = centered[test] - matrix[test] @ held_coefficients
                held_energy = float(np.dot(centered[test], centered[test]))
                if held_rank != len(indices) or not np.isfinite(held).all() or float(np.dot(held, held)) > clean_limit * max(epsilon, held_energy):
                    verified = False
                    break
            if verified:
                fitted = tuple((lag - index, float(coefficient)) for index, coefficient in zip(indices, coefficients))
            break
        if fitted is not None:
            self.paths = fitted
            self.delay, self.gain = max(fitted, key=lambda item: abs(item[1]))
            self.reference_state = "echo"
        if not self.paths:
            return frame, True
        prediction = np.zeros(n, dtype=np.float64)
        for delay, gain in self.paths:
            start = lag - delay
            if not 0 <= start < len(valid) or counts[start + n] - counts[start] < n:
                self.reference_state = "missing"
                return frame, True
            prediction += gain * reference[start:start + n]
        residual = centered - (prediction - prediction.mean())
        residual_energy = float(np.dot(residual, residual))
        reduction = 1 - residual_energy / energy
        self.double_talk = fitted is None and residual_energy > clean_limit * energy
        if self.double_talk:
            self.reference_state = "double_talk"
        if not math.isfinite(reduction) or reduction < 0:
            return frame, True
        result = microphone - prediction
        if residual_energy > epsilon:
            cross = np.fft.irfft(spectrum * np.fft.rfft(residual[::-1], size), size)[n - 1:len(reference)]
            scores = np.abs(cross) / np.sqrt(np.maximum(np.finfo(np.float64).tiny, energies * residual_energy))
            self.residual_correlation = min(1.0, float(np.max(scores[valid])))
        else:
            self.residual_correlation = 0.0
        self.reduction = min(1.0, reduction)
        return np.ascontiguousarray(result, dtype=np.float32), True

class DeviceExecutor:
    def __init__(self, emit):
        self.emit = emit
        self.requests = queue.Queue()
        self.lock = threading.Lock()
        self.failure = None
        self.closing = False
        self.thread = threading.Thread(target=self.run, daemon=True, name="YuanAudioDriver")
        self.thread.start()

    def poison(self, reason):
        with self.lock:
            if self.failure is None:
                self.failure = EngineFault(reason)
            self.closing = True
        return self.failure

    def call(self, key, function, timeout, cancel=None):
        with self.lock:
            if self.failure is not None:
                raise self.failure
            if self.closing:
                raise EngineFault("音频工作线程已关闭 / Audio driver worker is closed")
        if threading.current_thread() is self.thread:
            return function()
        check(cancel)
        deadline = time.monotonic() + max(tick(), timeout)
        done = threading.Event()
        result = []
        with operation(self.emit, key, scope="audio", budget_seconds=timeout):
            with self.lock:
                if self.failure is not None:
                    raise self.failure
                if self.closing:
                    raise EngineFault("音频工作线程已关闭 / Audio driver worker is closed")
                self.requests.put((function, done, result))
            while not done.wait(min(math.sqrt(tick()), max(0.0, deadline - time.monotonic()))):
                if time.monotonic() >= deadline:
                    raise self.poison("音频操作超时，需回收引擎 / Audio operation timed out; engine restart required: " + key)
            if time.monotonic() > deadline:
                raise self.poison("音频操作超时，需回收引擎 / Audio operation timed out; engine restart required: " + key)
            if isinstance(result[0], BaseException):
                raise result[0]
            check(cancel)
            return result[0]

    def run(self):
        while True:
            item = self.requests.get()
            if item is None:
                return
            function, done, result = item
            try:
                with self.lock:
                    failure = self.failure
                if failure is not None:
                    raise failure
                result.append(function())
            except BaseException as exc:
                result.append(exc)
            finally:
                done.set()

    def close(self, timeout):
        with self.lock:
            self.closing = True
            if not getattr(self, "stop_enqueued", False):
                self.stop_enqueued = True
                self.requests.put(None)
        self.thread.join(timeout=max(0.0, timeout))
        return not self.thread.is_alive()

class AudioDevices:
    def __init__(self, model, emit):
        import sounddevice as sd
        import soxr
        self.sd, self.soxr, self.model, self.emit = sd, soxr, model, emit
        self.streams = {}
        self.stream_lock = threading.RLock()
        self.faults = 0
        self.input_faults = 0
        self.input_callbacks = self.output_callbacks = 0
        self.last_input_callback = self.last_output_callback = time.monotonic()
        self.callback_timeout = model.policy.number("audio", "callback_timeout_seconds", max(1.0, model.chunk_seconds * 2), model.hop / model.rate, 3600.0)
        self.output_faults = 0
        self.vad_rate = model.rate
        self.frame_size = model.hop
        self.playback = None
        self.reference = None
        self.ring = None
        self.policy = None
        self.output_rate = model.rate
        self.input_rate = model.rate
        self.input_latency = self.output_latency = model.hop / model.rate
        self.capture = None
        self.driver = DeviceExecutor(emit)
        self.mono_buffer = None
        self.callback_errors = {"input": 0, "output": 0}
        self.callback_diagnostics = {"input": None, "output": None}
        self.callback_notices = {"input": 0, "output": 0}
        self.callback_failed = {"input": False, "output": False}
        self.output_failed_since = None
        self.input_gap_pending = False

    def timeout(self, key, default=None):
        default = max(5.0, self.model.chunk_seconds * 2) if default is None else default
        return self.model.policy.number("audio", key + "_seconds", default, max(tick(), 0.1), 3600.0)

    def cancel_playback(self):
        playback = self.playback
        if playback is not None:
            playback.interrupted = True
        self.playback = None

    def probe(self):
        return self.driver.call("audio_probe", self._probe, self.timeout("probe"))

    def open_streams(self, cancel):
        return self.driver.call("audio_open", lambda: self._open_streams(cancel), self.timeout("open"), cancel)

    def abort(self):
        self.cancel_playback()
        if self.driver.failure is None:
            return self.driver.call("audio_abort", self._abort, self.timeout("stop"))
        return False

    def close_streams(self):
        self.cancel_playback()
        if self.driver.failure is None:
            return self.driver.call("audio_close", self._close_streams, self.timeout("close"))
        return False

    def preflight(self, cancel):
        timeout = self.timeout("preflight")
        deadline = time.monotonic() + timeout
        return self.driver.call("audio_preflight", lambda: self._preflight(cancel, deadline), timeout, cancel)

    def defaults(self):
        devices = self.sd.query_devices()
        defaults = self.sd.default.device
        selected = []
        for position, direction in enumerate(("input", "output")):
            index = defaults[position]
            if index is None or index < 0 or index >= len(devices) or devices[index]["max_" + direction + "_channels"] < 1:
                options = [number for number, device in enumerate(devices) if device["max_" + direction + "_channels"] > 0]
                if not options:
                    raise YuanError("等待可用麦克风与扬声器 / Waiting for a microphone and speaker")
                index = options[0]
            selected.append(int(index))
        return selected, [devices[index] for index in selected]

    def _probe(self):
        defaults, _ = self.defaults()
        all_devices = self.sd.query_devices()
        indices, devices = [], []
        for default, direction in zip(defaults, ("input", "output")):
            options = [default, *[index for index, device in enumerate(all_devices) if index != default and device["max_" + direction + "_channels"] > 0]]
            selected = None
            reasons = []
            for index in options:
                device = dict(all_devices[index])
                maximum = int(device["max_" + direction + "_channels"])
                for channels in dict.fromkeys((1, min(2, maximum))):
                    for rate in dict.fromkeys((int(round(device["default_samplerate"])), self.model.rate)):
                        try:
                            getattr(self.sd, "check_" + direction + "_settings")(device=index, channels=channels, dtype="float32", samplerate=rate)
                            device.update(default_samplerate=rate, selected_channels=channels)
                            selected = index, device
                            break
                        except Exception as exc:
                            reasons.append(concise_error(exc))
                    if selected:
                        break
                if selected:
                    break
            if selected is None:
                raise YuanError("没有可用的音频设备配置 / No usable audio device configuration: " + "; ".join(dict.fromkeys(reasons)))
            indices.append(selected[0])
            devices.append(selected[1])
        self.emit("devices", input=devices[0]["name"], output=devices[1]["name"], input_rate=int(devices[0]["default_samplerate"]), output_rate=int(devices[1]["default_samplerate"]),
                  input_channels=devices[0]["selected_channels"], output_channels=devices[1]["selected_channels"], continuous=True)
        return indices, devices

    def _abort(self):
        playback = self.playback
        if playback is not None:
            playback.interrupted = True
        self.playback = None
        with self.stream_lock:
            streams = tuple(self.streams.values())
        for stream in streams:
            try:
                stream.abort(ignore_errors=True)
            except Exception:
                pass

    def _close_streams(self):
        with self.stream_lock:
            streams = tuple(self.streams.values())
            self.streams.clear()
        reasons = []
        for stream in streams:
            try:
                stream.abort(ignore_errors=True)
            except Exception as exc:
                reasons.append(concise_error(exc))
            try:
                stream.close(ignore_errors=True)
            except Exception as exc:
                reasons.append(concise_error(exc))
        if reasons:
            self.emit("notice", key="capture_recover", component="stream_cleanup", reason="; ".join(dict.fromkeys(reasons)))

    def timestamp(self, timing, key, fallback, frames=0, rate=None, discontinuity=False):
        now = time.monotonic()
        try:
            current = float(getattr(timing, "currentTime", 0.0))
            value = float(getattr(timing, key, 0.0))
        except (TypeError, ValueError, OverflowError):
            current = value = 0.0
        hardware = bool(current and value and math.isfinite(current) and math.isfinite(value))
        duration = frames / rate if frames > 0 and rate is not None and rate > 0 else 0.0
        if not hasattr(self, "clock_states"):
            self.clock_states = {}
        if not hasattr(self, "clock_offsets"):
            self.clock_offsets = {}
        previous = self.clock_states.get(key)
        if hardware:
            if previous is not None and not previous["hardware"] and not discontinuity:
                self.clock_offsets[key] = previous["next"] - value
            offset = self.clock_offsets.setdefault(key, now - current)
            timestamp = offset + value
        elif previous is not None and duration > 0 and not discontinuity:
            timestamp = previous["next"]
        else:
            timestamp = now + fallback
        self.clock_states[key] = {"next": timestamp + duration, "hardware": hardware, "arrival": now}
        return timestamp

    def input_callback(self, indata, frames, timing, status):
        self.last_input_callback = time.monotonic()
        self.input_callbacks += 1
        input_fault = self.input_gap_pending or bool(status and (status.input_overflow or status.input_underflow))
        self.input_gap_pending = False
        if input_fault:
            self.input_faults += 1
            self.faults += 1
        timestamp = self.timestamp(timing, "inputBufferAdcTime", -max(self.input_latency, frames / self.input_rate), frames, self.input_rate, input_fault)
        if indata.shape[1] == 1:
            self.ring.write(indata[:, 0], timestamp, discontinuity=input_fault)
        else:
            for offset in range(0, frames, len(self.mono_buffer)):
                count = min(len(self.mono_buffer), frames - offset)
                values = self.mono_buffer[:count]
                self.model.np.mean(indata[offset:offset + count], axis=1, out=values)
                self.ring.write(values, timestamp + offset / self.input_rate, discontinuity=input_fault and offset == 0)

    def output_callback(self, outdata, frames, timing, status):
        self.last_output_callback = time.monotonic()
        self.output_callbacks += 1
        outdata.fill(0)
        output_fault = bool(status and (status.output_underflow or status.output_overflow))
        if output_fault:
            self.output_faults += 1
            self.faults += 1
        timestamp = self.timestamp(timing, "outputBufferDacTime", self.output_latency, frames, self.output_rate, output_fault)
        playback = self.playback
        if playback is None:
            return
        if output_fault:
            playback.discontinuous = True
        if playback.cancel.is_set() or playback.interrupted:
            playback.interrupted = True
            if isinstance(playback, StreamingPlayback):
                playback.output_reference.write(outdata[:, 0], timestamp)
            return
        if status and status.output_overflow:
            return
        if isinstance(playback, StreamingPlayback):
            playback.render(outdata, frames, timestamp)
            return
        count = min(frames, len(playback.waveform) - playback.cursor)
        if count <= 0:
            return
        start = playback.cursor
        if playback.started_at is None:
            playback.started_at = timestamp
        outdata[:count, :] = playback.waveform[start:start + count, None]
        playback.cursor += count
        playback.drain_at = timestamp + count / playback.rate

    def guarded_input_callback(self, indata, frames, timing, status):
        try:
            self.input_callback(indata, frames, timing, status)
            self.callback_failed["input"] = False
        except Exception as exc:
            self.callback_diagnostics["input"] = (type(exc).__name__, exc.args, int(frames), time.monotonic())
            self.callback_errors["input"] += 1
            self.callback_failed["input"] = True
            self.input_gap_pending = True
            self.input_faults += 1
            self.faults += 1

    def guarded_output_callback(self, outdata, frames, timing, status):
        try:
            self.output_callback(outdata, frames, timing, status)
            self.callback_failed["output"] = False
            self.output_failed_since = None
        except Exception as exc:
            self.callback_diagnostics["output"] = (type(exc).__name__, exc.args, int(frames), time.monotonic())
            outdata.fill(0)
            self.callback_errors["output"] += 1
            self.callback_failed["output"] = True
            self.last_output_callback = time.monotonic()
            if self.output_failed_since is None:
                self.output_failed_since = self.last_output_callback
            self.output_faults += 1
            self.faults += 1
            playback = self.playback
            if playback is not None:
                playback.discontinuous = True
                playback.interrupted = True
            self.playback = None

    def duplex_callback(self, indata, outdata, frames, timing, status):
        self.guarded_input_callback(indata, frames, timing, status)
        self.guarded_output_callback(outdata, frames, timing, status)

    def callback_health(self):
        for direction in ("input", "output"):
            count = self.callback_errors[direction]
            if count != self.callback_notices[direction]:
                self.callback_notices[direction] = count
                diagnostic = self.callback_diagnostics[direction]
                details = {"exception": diagnostic[0], "reason": redact(str(diagnostic[1])), "frames": diagnostic[2],
                           "elapsed_seconds": max(0.0, time.monotonic() - diagnostic[3])} if diagnostic is not None else {}
                self.emit("notice", key="capture_gap" if direction == "input" else "playback_gap",
                          component=direction + "_callback", failures=count, recovered=not self.callback_failed[direction], **details)
        if self.callback_failed["input"]:
            self.emit("audio", continuous=False, speech_active=False, level=0.0)
            raise YuanError("输入回调失败，正在恢复收音 / Input callback failed; capture recovery required")
        if self.callback_failed["output"] and self.output_failed_since is not None and time.monotonic() - self.output_failed_since > self.callback_timeout:
            self.emit("audio", continuous=False, speech_active=False, level=0.0)
            raise YuanError("输出回调持续失败，正在恢复音频流 / Persistent output callback failure; audio stream recovery required")
        return self.active()

    def _open_streams(self, cancel):
        indices, devices = self._probe()
        self.clock_offsets = {}
        self.clock_states = {}
        self.policy = AudioPolicy(self.model, devices, self.emit)
        self.callback_failed = {"input": False, "output": False}
        self.output_failed_since = None
        self.input_gap_pending = False
        self.playback = self.reference = None
        self.last_input_callback = self.last_output_callback = time.monotonic()
        reasons = []
        common_rates = dict.fromkeys((int(devices[0]["default_samplerate"]), int(devices[1]["default_samplerate"]), self.model.rate))
        for rate in common_rates:
            check(cancel)
            stream = None
            try:
                self.input_rate = self.output_rate = rate
                self.clock_offsets = {}
                self.clock_states = {}
                self.ring = SampleRing(math.ceil(rate * self.policy.buffer_seconds), rate)
                self.mono_buffer = self.model.np.empty(len(self.ring.buffer), dtype=self.model.np.float32)
                stream = self.sd.Stream(device=tuple(indices), samplerate=rate, channels=tuple(device["selected_channels"] for device in devices), dtype="float32",
                                        blocksize=0, latency=self.policy.latency, callback=self.duplex_callback, never_drop_input=True)
                reported = stream.latency
                self.input_latency, self.output_latency = reported if isinstance(reported, (tuple, list)) else (reported, reported)
                with self.stream_lock:
                    check(cancel)
                    self.streams["duplex"] = stream
                stream.start()
                self.emit("devices", input_rate=rate, output_rate=rate, input_latency=self.input_latency, output_latency=self.output_latency, transport="duplex", continuous=True)
                return
            except Cancelled:
                if stream is not None:
                    stream.close(ignore_errors=True)
                self.close_streams()
                raise
            except Exception as exc:
                reasons.append(concise_error(exc))
                if stream is not None:
                    stream.close(ignore_errors=True)
                with self.stream_lock:
                    self.streams.clear()
        self.input_rate = int(devices[0]["default_samplerate"])
        self.output_rate = int(devices[1]["default_samplerate"])
        self.ring = SampleRing(math.ceil(self.input_rate * self.policy.buffer_seconds), self.input_rate)
        self.mono_buffer = self.model.np.empty(len(self.ring.buffer), dtype=self.model.np.float32)
        try:
            for direction, index, device in zip(("input", "output"), indices, devices):
                check(cancel)
                constructor = self.sd.InputStream if direction == "input" else self.sd.OutputStream
                stream = constructor(device=index, samplerate=int(device["default_samplerate"]), channels=device["selected_channels"], dtype="float32",
                                     blocksize=0, latency=self.policy.latency, callback=self.guarded_input_callback if direction == "input" else self.guarded_output_callback)
                setattr(self, direction + "_latency", float(stream.latency))
                with self.stream_lock:
                    self.streams[direction] = stream
                    check(cancel)
                stream.start()
            self.emit("devices", input_rate=self.input_rate, output_rate=self.output_rate, input_latency=self.input_latency, output_latency=self.output_latency, transport="separate-continuous", continuous=True)
        except BaseException:
            self.close_streams()
            raise
        self.emit("notice", key="full_duplex", component="separate_streams", reasons=reasons)

    def _preflight(self, cancel, deadline):
        self._close_streams()
        initial_input, initial_output = self.input_callbacks, self.output_callbacks
        try:
            self._open_streams(cancel)
            while time.monotonic() < deadline:
                check(cancel)
                if not self.active():
                    raise YuanError("音频流未保持运行 / Audio streams did not remain active")
                if self.input_callbacks > initial_input and self.output_callbacks > initial_output and not any(self.callback_failed.values()):
                    self.emit("devices", probed=True, continuous=False)
                    return True
                cancel.wait(min(math.sqrt(tick()), max(0.0, deadline - time.monotonic())))
            raise YuanError("音频设备未在期限内提供输入输出回调 / Audio devices did not provide input and output callbacks in time")
        finally:
            self._close_streams()
            self.ring = None

    def active(self):
        if self.driver.failure is not None:
            return False
        with self.stream_lock:
            opened = bool(self.streams)
        now = time.monotonic()
        return opened and not self.callback_failed["input"] and now - self.last_input_callback <= self.callback_timeout and now - self.last_output_callback <= self.callback_timeout

    @staticmethod
    def output_audio(waveform):
        import numpy as np
        values = np.asarray(waveform, dtype=np.float32).reshape(-1)
        if not np.isfinite(values).all():
            raise YuanError("播放音频包含无效数值 / Playback audio contains invalid values")
        return np.ascontiguousarray(np.clip(values, -1, 1), dtype=np.float32)

    def play(self, waveform, rate, cancel):
        import numpy as np
        check(cancel)
        original = np.asarray(waveform, dtype=np.float32).reshape(-1)
        if not original.size or not np.isfinite(original).all():
            raise YuanError("播放音频无效 / Invalid playback audio")
        if not self.active():
            raise YuanError("持续音频流不可用 / Continuous audio stream is unavailable")
        values = self.soxr.resample(original, rate, self.output_rate).astype(np.float32) if rate != self.output_rate else original.copy()
        values = self.output_audio(values)
        reference = self.soxr.resample(values, self.output_rate, self.vad_rate).astype(np.float32) if self.output_rate != self.vad_rate else values
        playback = Playback(values, reference, self.output_rate, self.vad_rate, cancel)
        self.reference = self.playback = playback
        self.emit("status", key="speaking", id=self.capture.session_id if self.capture else None)
        interval = max(self.frame_size / self.vad_rate, math.sqrt(tick()))
        try:
            while True:
                if cancel.is_set() or playback.interrupted:
                    playback.interrupted = True
                    break
                if not self.active():
                    playback.interrupted = True
                    raise YuanError("持续音频流已中断 / Continuous audio stream was interrupted")
                if playback.cursor == len(values) and playback.drain_at is not None and time.monotonic() >= playback.drain_at:
                    break
                cancel.wait(interval)
        finally:
            if self.playback is playback:
                self.playback = None
        played = min(len(original), int(playback.played() * rate / self.output_rate)) if playback.interrupted else len(original)
        self.emit("audio", id=self.capture.session_id if self.capture else None, output_seconds=played / rate,
                  interrupted=playback.interrupted, playback_discontinuity=playback.discontinuous, continuous=self.active())
        return original[:played].copy(), playback.interrupted


    def play_stream(self, chunks, rate, cancel, max_samples=None):
        import numpy as np
        check(cancel)
        if not self.active():
            raise YuanError("持续音频流不可用 / Continuous audio stream is unavailable")
        capacity = self.model.capacity() if max_samples is None else max(1, int(max_samples))
        duration = capacity / rate
        frame_seconds = self.frame_size / self.vad_rate
        section = getattr(self.model, "performance_section", "performance")
        realtime = self.model.policy.estimate(section, "generation_realtime_factor", 1.0)
        underruns = self.model.policy.measured(section, "playback_underruns", 0.0)
        producer_gap = self.model.policy.estimate(section, "generation_chunk_wait_seconds", frame_seconds)
        baseline = max(frame_seconds, producer_gap, self.output_latency * (1 + math.sqrt(1 + underruns)))
        seconds = self.model.policy.number("audio", "playback_buffer_seconds", max(baseline, self.model.chunk_seconds), frame_seconds, max(frame_seconds, duration))
        prebuffer = self.model.policy.number("audio", "playback_prebuffer_seconds", min(seconds, max(baseline, seconds * max(0.0, 1 - 1 / max(1.0, realtime)))), frame_seconds, seconds)
        playback = StreamingPlayback(self.output_rate, self.vad_rate, cancel, math.ceil(seconds * self.output_rate), math.ceil(prebuffer * self.output_rate),
                                     math.ceil(duration * self.vad_rate) + self.frame_size,
                                     timeline_samples=math.ceil((self.policy.echo_seconds + self.policy.buffer_seconds + seconds) * self.output_rate))
        resampler = self.soxr.ResampleStream(rate, self.output_rate, 1, dtype="float32") if rate != self.output_rate else None
        reference_resampler = self.soxr.ResampleStream(self.output_rate, self.vad_rate, 1, dtype="float32") if self.output_rate != self.vad_rate else None
        self.reference = self.playback = playback
        self.last_playback_error = None
        self.last_playback_started = None
        original = []
        generated = 0
        iterator = iter(chunks)
        interval = max(frame_seconds, math.sqrt(tick()))
        announced = False
        def observe_start():
            nonlocal announced
            if not announced and playback.started_at is not None:
                announced = True
                self.last_playback_started = playback.started_at
                self.emit("status", key="speaking", id=self.capture.session_id if self.capture else None, streaming=True)
        def queue_values(values, last=False):
            check(cancel)
            values = self.output_audio(values)
            reference = reference_resampler.resample_chunk(values, last=last) if reference_resampler is not None else values
            playback.append_reference(reference)
            offset = 0
            while offset < len(values):
                observe_start()
                check(cancel)
                if playback.interrupted:
                    raise Cancelled()
                if not self.active():
                    raise YuanError("持续音频流已中断 / Continuous audio stream was interrupted")
                with playback.lock:
                    available = playback.capacity - playback.buffered
                if available:
                    piece = np.ascontiguousarray(values[offset:offset + available], dtype=np.float32)
                    piece.setflags(write=False)
                    if playback.push(piece):
                        offset += len(piece)
                        continue
                cancel.wait(interval)
            observe_start()
        with operation(self.emit, "stream_playback", "conversation", budget_seconds=duration * (1 + max(1.0, realtime)) + seconds):
            try:
                while True:
                    generated_at = time.monotonic()
                    try:
                        chunk = next(iterator)
                    except StopIteration:
                        break
                    self.model.policy.observe(section, "generation_chunk_wait_seconds", time.monotonic() - generated_at)
                    check(cancel)
                    values = np.asarray(chunk, dtype=np.float32).reshape(-1)
                    if not values.size:
                        continue
                    if not np.isfinite(values).all() or generated + len(values) > capacity:
                        raise YuanError("播放片段无效或超过回复边界 / Invalid playback chunk or reply boundary exceeded")
                    values = np.ascontiguousarray(np.clip(values, -1, 1), dtype=np.float32)
                    original.append(values)
                    generated += len(values)
                    converted = resampler.resample_chunk(values) if resampler is not None else values
                    queue_values(converted)
                tail = resampler.resample_chunk(np.empty(0, dtype=np.float32), last=True) if resampler is not None else np.empty(0, dtype=np.float32)
                queue_values(tail, last=True)
                if not generated:
                    raise YuanError("模型没有提供播放音频 / Model provided no playback audio")
                playback.finish()
                while not playback.drained():
                    observe_start()
                    check(cancel)
                    if playback.interrupted:
                        raise Cancelled()
                    if not self.active():
                        raise YuanError("持续音频流已中断 / Continuous audio stream was interrupted")
                    cancel.wait(interval)
                observe_start()
            except Cancelled:
                playback.interrupted = True
            except Exception as exc:
                playback.interrupted = True
                self.last_playback_error = concise_error(exc)
                self.emit("notice", key="playback_gap", component="streamed_reply", reason=self.last_playback_error)
            finally:
                if self.playback is playback:
                    self.playback = None
                close = getattr(iterator, "close", None)
                if close is not None:
                    try:
                        close()
                    except Exception as exc:
                        playback.interrupted = True
                        self.last_playback_error = concise_error(exc)
                        self.emit("notice", key="playback_gap", component="generation_cleanup", reason=self.last_playback_error)
                self.model.policy.observe(section, "playback_underruns", playback.underruns)
            values = np.concatenate(original) if original else np.empty(0, dtype=np.float32)
            result = playback.result(values, rate, self.last_playback_error)
            self.emit("audio", id=self.capture.session_id if self.capture else None, output_seconds=result.played_samples / rate, streaming=True,
                      **result.metadata(), playback_discontinuity=result.discontinuous, underruns=result.underruns,
                      buffer_seconds=seconds, prebuffer_seconds=prebuffer, continuous=self.active())
            return result

class AudioPacketQueue:
    def __init__(self, byte_limit, item_limit):
        self.byte_limit = max(1, int(byte_limit))
        self.item_limit = max(1, int(item_limit))
        self.items = deque()
        self.bytes = 0
        self.closed = False
        self.rejected_utterance = None
        self.condition = threading.Condition()

    def put(self, packet, replace_oldest=False, preserve_utterance=False):
        size = int(packet["waveform"].nbytes)
        dropped = []
        def identity(item):
            return item.get("group_id"), item.get("metadata", {}).get("utterance_id")
        with self.condition:
            if self.closed:
                return False, dropped
            identifier = identity(packet) if preserve_utterance else None
            if preserve_utterance and not identifier[1]:
                raise ValueError("推理音频缺少语句身份 / Inference audio lacks an utterance identity")
            if preserve_utterance and self.rejected_utterance == identifier:
                return False, dropped
            if preserve_utterance:
                self.rejected_utterance = None
            def discard_utterance(target):
                retained = deque()
                for item in self.items:
                    if identity(item) == target:
                        self.bytes -= int(item["waveform"].nbytes)
                        dropped.append(item)
                    else:
                        retained.append(item)
                self.items = retained
                self.condition.notify_all()
            if size > self.byte_limit:
                if preserve_utterance:
                    discard_utterance(identifier)
                    self.rejected_utterance = identifier
                return False, dropped
            while self.items and (self.bytes + size > self.byte_limit or len(self.items) >= self.item_limit):
                if not replace_oldest:
                    return False, dropped
                if preserve_utterance:
                    oldest = identity(self.items[0])
                    discard_utterance(oldest)
                    if oldest == identifier:
                        self.rejected_utterance = identifier
                        return False, dropped
                else:
                    removed = self.items.popleft()
                    self.bytes -= int(removed["waveform"].nbytes)
                    dropped.append(removed)
            self.items.append(packet)
            self.bytes += size
            self.condition.notify_all()
            return True, dropped

    def get(self, timeout):
        with self.condition:
            if not self.items and not self.closed:
                self.condition.wait(timeout)
            if not self.items:
                return None
            packet = self.items.popleft()
            self.bytes -= int(packet["waveform"].nbytes)
            self.condition.notify_all()
            return packet

    def pending(self):
        with self.condition:
            return len(self.items)

    def close(self):
        with self.condition:
            self.closed = True
            self.condition.notify_all()

class UtteranceQueue(AudioPacketQueue):
    def __init__(self, byte_limit, item_limit):
        super().__init__(byte_limit, item_limit)
        self.identifier = None
        self.next_index = 0
        self.ended = False
        self.active = None
        self.terminal = None

    def _cancel(self, reason):
        dropped = list(self.items)
        self.items.clear()
        self.bytes = 0
        if self.active is not None:
            self.terminal = {"event": "utterance_cancelled", "group_id": self.active["group_id"],
                             "metadata": {**self.active["metadata"], "utterance_final": None,
                                          "input_incomplete": True, "reason": reason}}
            self.active = None
        self.rejected_utterance = self.identifier
        self.condition.notify_all()
        return dropped

    def cancel(self, reason):
        with self.condition:
            return self._cancel(reason)

    def put(self, packet, replace_oldest=True, preserve_utterance=True):
        metadata = packet.get("metadata", {})
        identifier = (packet.get("group_id"), metadata.get("utterance_id"))
        if not all(isinstance(value, str) and value for value in identifier):
            raise ValueError("推理音频缺少语句身份 / Inference audio lacks an utterance identity")
        size = int(packet["waveform"].nbytes)
        dropped = []
        with self.condition:
            if self.closed:
                return False, dropped
            if identifier != self.identifier:
                dropped.extend(self._cancel("inference_superseded"))
                self.identifier = identifier
                self.next_index = 0
                self.ended = False
                self.rejected_utterance = None
            elif self.rejected_utterance == identifier or self.ended:
                return False, dropped
            index = metadata.get("chunk_index")
            if (type(index) is not int or index != self.next_index or type(metadata.get("utterance_final")) is not bool
                    or metadata.get("capture_gap") or metadata.get("final") or size <= 0
                    or self.bytes + size > self.byte_limit or len(self.items) >= self.item_limit):
                dropped.extend(self._cancel("input_incomplete"))
                return False, dropped
            self.items.append(packet)
            self.bytes += size
            self.next_index += 1
            self.ended = metadata["utterance_final"]
            self.condition.notify_all()
            return True, dropped

    def get(self, timeout):
        with self.condition:
            self.condition.wait_for(lambda: self.terminal is not None or self.items or self.closed, timeout)
            if self.terminal is not None:
                packet, self.terminal = self.terminal, None
                return packet
            if not self.items:
                return None
            packet = self.items.popleft()
            self.bytes -= int(packet["waveform"].nbytes)
            self.active = None if packet["metadata"]["utterance_final"] else {
                "group_id": packet["group_id"], "metadata": dict(packet["metadata"])}
            self.condition.notify_all()
            return packet

    def pending(self):
        with self.condition:
            return len(self.items) + int(self.terminal is not None)

    def close(self):
        with self.condition:
            self.closed = True
            self._cancel("capture_stopped")


class AudioWriter:
    def __init__(self, model, emit):
        import psutil
        self.model, self.emit = model, emit
        minimum = max(1, model.capacity() * model.np.dtype(model.np.float32).itemsize)
        byte_limit = model.policy.integer("audio", "storage_queue_bytes", minimum * 2, minimum, max(minimum, available_resources(psutil)["memory"] // 8))
        item_limit = model.policy.integer("audio", "storage_queue_segments", max(2, math.isqrt(max(1, model.capacity() // model.hop))), 1, max(2, model.capacity() // model.hop))
        self.retry_limit = model.policy.integer("storage", "write_attempts", 3, 1, 64)
        self.retry_base = model.policy.number("storage", "write_retry_seconds", max(0.1, model.chunk_seconds), tick(), 3600.0)
        self.retry_max = model.policy.number("storage", "write_retry_max_seconds", max(self.retry_base, model.chunk_seconds * 4), self.retry_base, 86400.0)
        self.session_limit = model.policy.integer("storage", "session_stat_history", max(8, item_limit * 2), 1, 65536)
        StorageBudget(model.state).configure(model, byte_limit)
        self.queue = AudioPacketQueue(byte_limit, item_limit)
        self.closing = threading.Event()
        self.finished = threading.Event()
        self.condition = threading.Condition(threading.RLock())
        self.inflight = self.retrying = False
        self.accepted = self.completed = self.saved = self.failed = self.rejected = self.retries = 0
        self.lost_seconds = 0.0
        self.failure = self.fatal = None
        self.storage_available = False
        self.sessions = {}
        self.active_packet = None
        self.restarts = 0
        self.thread = threading.Thread(target=self.run, daemon=True, name="YuanAudioWriter")
        self.thread.start()

    def _session(self, session_id):
        value = self.sessions.get(session_id)
        if value is None:
            value = {"accepted": 0, "completed": 0, "saved": 0, "failed": 0, "rejected": 0, "lost_seconds": 0.0, "error": None, "sealed": False}
            self.sessions[session_id] = value
        return value

    def enqueue(self, packet):
        with self.condition:
            stats = self._session(packet["group_id"])
            if self.closing.is_set() or self.fatal is not None or stats["sealed"]:
                accepted = False
            else:
                accepted, _ = self.queue.put(dict(packet))
            if accepted:
                self.accepted += 1
                stats["accepted"] += 1
            else:
                duration = len(packet["waveform"]) / packet["rate"]
                self.rejected += 1
                self.lost_seconds += duration
                stats["rejected"] += 1
                stats["lost_seconds"] += duration
                stats["error"] = self.fatal or "存档队列未接收片段 / Storage queue did not accept the segment"
            self.condition.notify_all()
        if not accepted:
            self.emit("notice", key="storage_overload", id=packet["group_id"], sample=packet["id"], lost_seconds=len(packet["waveform"]) / packet["rate"], pending=self.queue.pending())
        return accepted

    def _complete(self, packet, saved, error=None):
        with self.condition:
            stats = self._session(packet["group_id"])
            self.completed += 1
            stats["completed"] += 1
            if saved:
                self.saved += 1
                stats["saved"] += 1
                self.storage_available = True
                self.failure = None
            else:
                duration = len(packet["waveform"]) / packet["rate"]
                self.failed += 1
                self.lost_seconds += duration
                stats["failed"] += 1
                stats["lost_seconds"] += duration
                stats["error"] = error or self.failure
            self.active_packet = None
            self.inflight = self.retrying = False
            self.condition.notify_all()
        self.emit("storage_state", id=packet["group_id"], session=self.session_status(packet["group_id"]), **self.status())

    def _close_store(self, store):
        if store is not None:
            try:
                store.close()
            except (OSError, sqlite3.Error) as exc:
                self.emit("notice", key="storage_retry", component="storage_close", reason=concise_error(exc))

    def _unavailable(self, exc, attempt, retryable=True):
        delay = min(self.retry_max, self.retry_base * min(attempt, math.sqrt(self.retry_max / self.retry_base)) ** 2)
        with self.condition:
            self.failure = concise_error(exc)
            self.storage_available = False
            self.retrying = retryable
            self.retries += int(retryable)
            if not retryable:
                self.fatal = self.failure
            self.condition.notify_all()
        self.emit("notice", key="storage_retry" if retryable else "storage_failed", component="storage_connection", reason=self.failure,
                  attempt=attempt, retry_seconds=delay if retryable else None, recoverable=retryable)
        self.emit("storage_state", **self.status())
        return delay

    def _probe(self, store):
        fd, name = tempfile.mkstemp(dir=store.audio, prefix=".probe-")
        try:
            with os.fdopen(fd, "wb") as probe:
                probe.write(b"Yuan")
                probe.flush()
                os.fsync(probe.fileno())
            store.set_setting("writer_probe", time.time())
        finally:
            Path(name).unlink(missing_ok=True)

    def run(self):
        store = None
        connections = 0
        try:
            while not self.closing.is_set() or self.queue.pending() or self.active_packet is not None:
                if store is None:
                    if self.closing.is_set():
                        break
                    try:
                        store = AudioStore(self.model.state, recover=False)
                        self._probe(store)
                        connections = 0
                        with self.condition:
                            self.storage_available = True
                            self.retrying = False
                            self.failure = None
                            self.condition.notify_all()
                        self.emit("storage_state", **self.status())
                    except Exception as exc:
                        self._close_store(store)
                        store = None
                        connections += 1
                        retryable = isinstance(exc, (OSError, sqlite3.OperationalError)) and not isinstance(exc, InvalidAudio)
                        delay = self._unavailable(exc, connections, retryable)
                        if not retryable:
                            break
                        self.closing.wait(delay)
                        continue
                packet = self.active_packet or self.queue.get(math.sqrt(tick()))
                if packet is None:
                    continue
                with self.condition:
                    self.active_packet = packet
                    self.inflight = True
                saved = False
                error = None
                for attempt in range(self.retry_limit):
                    try:
                        if store is None:
                            store = AudioStore(self.model.state, recover=False)
                        sample = store.add(packet["group_id"], packet["role"], packet["waveform"], packet["rate"], "local", generated=packet["role"] == "assistant",
                                           eligible=packet.get("eligible", True), created=packet["created"], metadata=packet["metadata"], sample_id=packet["id"])
                        saved = True
                        if packet["role"] == "assistant":
                            input_id = packet["metadata"].get("input_sample")
                            try:
                                if input_id and store.sample(input_id) is not None:
                                    pair = store.add_pair(packet["group_id"], input_id, sample, "yuan_generated", verified=False)
                                    self.emit("dialogue_pair", pair=pair, group=packet["group_id"], source="yuan_generated", verified=False)
                            except Exception as exc:
                                self.emit("notice", component="history_pair", sample=sample, input_sample=input_id, audio_saved=True, reason=concise_error(exc))
                        self.emit("capture_saved", id=packet["group_id"], sample=sample, role=packet["role"], seconds=len(packet["waveform"]) / packet["rate"],
                                  learnable=packet["role"] != "assistant" and packet.get("eligible", True), pending_storage=self.queue.pending())
                        break
                    except Exception as exc:
                        if saved:
                            self.emit("notice", component="storage_event", sample=packet["id"], audio_saved=True, reason=concise_error(exc))
                            break
                        error = concise_error(exc)
                        retryable = isinstance(exc, (OSError, sqlite3.OperationalError)) and not isinstance(exc, InvalidAudio)
                        self._close_store(store)
                        store = None
                        retry = retryable and attempt + 1 < self.retry_limit and not self.closing.is_set()
                        delay = self._unavailable(exc, attempt + 1, retryable)
                        self.emit("notice", key="storage_retry" if retry else "storage_failed", id=packet["group_id"], sample=packet["id"], reason=error,
                                  attempt=attempt + 1, retry_seconds=delay if retry else None, lost_seconds=0.0 if retry else len(packet["waveform"]) / packet["rate"])
                        if not retry:
                            break
                        self.closing.wait(delay)
                self._complete(packet, saved, error)
                if self.fatal is not None:
                    break
        except Exception as exc:
            with self.condition:
                self.failure = concise_error(exc)
                self.storage_available = False
            self.emit("notice", key="storage_failed", component="writer_worker", reason=self.failure, recoverable=True)
        finally:
            self._close_store(store)
            if self.closing.is_set() or self.fatal is not None:
                if self.active_packet is not None:
                    self._complete(self.active_packet, False, self.failure or "存档任务已关闭 / Storage worker closed")
                while True:
                    packet = self.queue.get(0)
                    if packet is None:
                        break
                    self._complete(packet, False, self.failure or "存档任务已关闭 / Storage worker closed")
            self.finished.set()
            with self.condition:
                self.storage_available = False
                self.condition.notify_all()

    def ensure_running(self):
        with self.condition:
            if self.closing.is_set() or self.fatal is not None or self.thread.is_alive():
                return
            self.finished.clear()
            self.restarts += 1
            self.thread = threading.Thread(target=self.run, daemon=True, name="YuanAudioWriter")
            self.thread.start()
        self.emit("notice", key="storage_retry", component="writer_restart", restarts=self.restarts)

    def session_status(self, session_id):
        with self.condition:
            row = dict(self._session(session_id))
            return {**row, "pending": max(0, row["accepted"] - row["completed"])}

    def flush_session(self, session_id, timeout):
        deadline = time.monotonic() + max(0.0, timeout)
        self.ensure_running()
        with self.condition:
            stats = self._session(session_id)
            stats["sealed"] = True
            target = stats["accepted"]
            while stats["completed"] < target and not self.finished.is_set():
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                self.condition.wait(min(remaining, math.sqrt(tick())))
            pending = max(0, target - stats["completed"])
            result = FlushResult(ok=pending == 0 and stats["saved"] >= target and not stats["failed"] and not stats["rejected"], session_id=session_id,
                                 target=target, saved=stats["saved"], failed=stats["failed"], rejected=stats["rejected"], pending=pending,
                                 retrying=self.retrying and pending > 0, lost_seconds=stats["lost_seconds"], error=stats["error"] or (self.failure if pending else None))
            for key in list(self.sessions):
                if len(self.sessions) <= self.session_limit:
                    break
                row = self.sessions[key]
                if key != session_id and row["sealed"] and row["accepted"] == row["completed"]:
                    del self.sessions[key]
            return result

    def flush(self, timeout):
        deadline = time.monotonic() + max(0.0, timeout)
        with self.condition:
            target = self.accepted
            while self.completed < target and not self.finished.is_set():
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    break
                self.condition.wait(min(remaining, math.sqrt(tick())))
            return FlushResult(ok=self.completed >= target and self.saved >= target and not self.failed and not self.rejected,
                               target=target, saved=self.saved, failed=self.failed, rejected=self.rejected, pending=max(0, target - self.completed),
                               retrying=self.retrying, lost_seconds=self.lost_seconds, error=self.failure)

    def close(self, timeout):
        deadline = time.monotonic() + max(0.0, timeout)
        self.closing.set()
        self.queue.close()
        result = self.flush(max(0.0, deadline - time.monotonic()))
        self.thread.join(timeout=max(0.0, deadline - time.monotonic()))
        if not result or self.thread.is_alive():
            self.emit("notice", key="storage_flush", **dict(result), writer_running=self.thread.is_alive())
        return bool(result) and not self.thread.is_alive()

    def status(self):
        with self.condition:
            budget = StorageBudget(self.model.state).snapshot(self.model.capacity() * self.model.np.dtype(self.model.np.float32).itemsize * 2, purpose="conversation")
            healthy = bool(self.storage_available and self.failure is None and not self.retrying and self.thread.is_alive() and not self.finished.is_set() and budget["ready"])
            return {"healthy": healthy, "budget": budget, "state": "ready" if healthy else "failed" if self.fatal else "closed" if self.closing.is_set() else "reconnecting",
                    "accepted": self.accepted, "saved": self.saved, "failed": self.failed, "rejected": self.rejected,
                    "pending": max(0, self.accepted - self.completed), "retrying": self.retrying, "retries": self.retries,
                    "lost_seconds": self.lost_seconds, "error": self.failure, "recoverable": self.fatal is None, "restarts": self.restarts}

class RecordedDialogueAdapter:
    @staticmethod
    def records(path, cancel):
        if path.suffix.lower() == ".jsonl":
            with path.open("r", encoding="utf-8-sig") as stream:
                for line in stream:
                    check(cancel)
                    if line.strip():
                        yield json.loads(line)
            return
        with path.open("r", encoding="utf-8-sig") as stream:
            data = json.load(stream, parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
        values = data if isinstance(data, list) else data.get("conversations", [data]) if isinstance(data, dict) else ()
        if not isinstance(values, list):
            raise InvalidDownload("对话导出格式无效 / Invalid conversation export format")
        for value in values:
            check(cancel)
            yield value

    @staticmethod
    def convert(raw):
        if not isinstance(raw, dict):
            raise IneligibleSample("对话记录不是对象 / Conversation record is not an object")
        if raw.get("format") == "yuan-paired-audio-v1":
            return copy.deepcopy(raw)
        messages = raw.get("messages")
        annotation = raw.get("annotation", {})
        if not isinstance(messages, list) or not messages or not isinstance(annotation, dict):
            raise IneligibleSample("没有带录音标注的对话轮次 / No annotated recorded conversation turns")
        recording = raw.get("recording_id", raw.get("conversation_id"))
        data = {"format": "yuan-paired-audio-v1", "recording_id": recording,
                "dataset_id": raw.get("dataset_id", recording), "origin": raw.get("origin"),
                "language": {"zh": "中文", "zh-CN": "中文", "en": "English"}.get(raw.get("language"), raw.get("language")),
                "license": raw.get("license"), "reviewer": raw.get("reviewer", annotation.get("reviewer")),
                "annotation_id": raw.get("annotation_id", annotation.get("id")),
                "prompt": raw.get("prompt", annotation.get("prompt")), "split": raw.get("split"), "turns": []}
        for message in messages:
            if not isinstance(message, dict) or not isinstance(message.get("annotations", {}), dict):
                raise IneligibleSample("轮次缺少有效人工标注 / Turn lacks valid human annotations")
            labels = message.get("annotations", {})
            audio = message.get("audio")
            item = {"id": message.get("id"), "role": message.get("role"),
                    "speaker": message.get("speaker", message.get("speaker_id")),
                    "start_seconds": message.get("start_seconds", message.get("timestamp")),
                    "audio": audio.get("path") if isinstance(audio, dict) else audio,
                    "sha256": audio.get("sha256") if isinstance(audio, dict) else message.get("sha256")}
            for key in ("reply_to", "response_verified", "utterance_final", "transcript_verified", "scenarios", "contrasts", "reference_checks", "semantic", "retrieval", "dialogue"):
                if key in message or key in labels:
                    item[key] = copy.deepcopy(message[key] if key in message else labels[key])
            if "transcript" in message or "text" in message:
                item["transcript"] = message.get("transcript", message.get("text"))
            data["turns"].append(item)
        DatasetImporter.validate_annotations(data)
        DatasetImporter.validate_semantic(data)
        return data

class SourceRegistry:
    def __init__(self, store):
        self.store = store
        self.store.db.execute("CREATE TABLE IF NOT EXISTS validated_sources(repository TEXT NOT NULL,task_id TEXT NOT NULL,revision TEXT NOT NULL,contract TEXT NOT NULL,updated REAL NOT NULL,PRIMARY KEY(repository,task_id))")
        self.store.db.execute("CREATE TABLE IF NOT EXISTS bootstrap_sources(repository TEXT PRIMARY KEY,contract TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'unchecked',attempts INTEGER NOT NULL DEFAULT 0,retry_at REAL NOT NULL DEFAULT 0,updated REAL NOT NULL DEFAULT 0,reason TEXT NOT NULL DEFAULT '')")
        seeds = [{"repository": item["repository"], "adapter": item["adapter"], "license": item["license"], "languages": list(item["languages"]),
                  "supported_tasks": ["raw_audio", "transcript_supervision"], "fields": list(item.get("columns", ("audio", "id", "human_transcription"))),
                  "independence": "publisher_recording_identity", "annotation_scope": "human_transcripts_not_dialogue_answers"} for item in PublishedSpeech.specifications]
        seeds.append({"repository": PublicDialogue.repository, "adapter": "published_stereo_dialogue_v1", "license": "cc-by-sa-4.0", "languages": ["English"],
                      "supported_tasks": ["paired_dialogue"], "fields": ["human_recording", "stereo_channels", "recording_id"],
                      "independence": "recording", "annotation_scope": "training_only_not_verified_answers"})
        for seed in seeds:
            self.store.db.execute("INSERT OR IGNORE INTO bootstrap_sources(repository,contract) VALUES(?,?)", (seed["repository"], json.dumps(seed, sort_keys=True)))
        self.store.commit()

    @staticmethod
    def failure_state(exc=None, blockers=None):
        blockers = blockers or {}
        if blockers.get("resource_budget") or isinstance(exc, MemoryError) or isinstance(exc, YuanFault) and exc.category in ("resource", "storage"):
            return "resource_wait"
        if blockers.get("source_conflict") or blockers.get("coverage_unchanged"):
            return "independence_wait"
        if blockers.get("unsupported_schema"):
            return "schema_wait"
        if blockers.get("missing_annotations") or blockers.get("invalid_annotations") or blockers.get("no_source"):
            return "annotation_wait"
        if exc is not None and isinstance(exc, (InvalidDownload, IneligibleSample, ValueError, TypeError, KeyError)):
            return "schema_wait"
        return "network_wait" if exc is not None or blockers.get("source_unavailable") else "annotation_wait"

    def preflight(self, model, jobs, cancel, emit):
        candidates = {job.repository: job for job in jobs}
        rows = self.store.db.execute("SELECT * FROM bootstrap_sources WHERE retry_at<=? ORDER BY status='path_verified',attempts,updated,repository", (time.time(),)).fetchall()
        for row in rows:
            job = candidates.get(row["repository"])
            if job is None:
                continue
            check(cancel)
            contract = json.loads(row["contract"])
            attempts = row["attempts"] + 1
            try:
                job.catalog_query(cancel)
                catalog = job.catalog
                if isinstance(job, PublishedSpeech):
                    items = [json.loads(item[0]) for item in self.store.db.execute("SELECT item FROM native_sources WHERE repository=? AND revision=? ORDER BY id", (job.repository, catalog["revision"]))]
                else:
                    job.validate_catalog()
                    items = catalog["files"]
                if not items or not re.fullmatch(r"[a-f0-9]{40}", str(catalog.get("revision", ""))):
                    raise InvalidDownload("启动来源没有可校验的数据路径 / Bootstrap source has no verifiable data path")
                contract.update(revision=catalog["revision"], license_revision=catalog.get("license_revision", catalog["revision"]),
                                manifest_sha256=payload_digest(items), files=len(items), integrity="pinned_revision_and_file_digests",
                                schema_validation="performed_before_each_import", semantic_acceptance=False)
                state, reason = "path_verified", ""
                delay = model.policy.number("network", "bootstrap_recheck_seconds", 86400.0, 1.0, 30 * 86400.0)
            except Cancelled:
                raise
            except (OSError, YuanError, ValueError, TypeError, KeyError, MemoryError) as exc:
                state, reason = self.failure_state(exc), concise_error(exc)
                delay = self.store.retry_delay(attempts, state != "network_wait")
            self.store.db.execute("UPDATE bootstrap_sources SET contract=?,status=?,attempts=?,retry_at=?,updated=?,reason=? WHERE repository=?",
                                  (json.dumps(contract, sort_keys=True), state, attempts, time.time() + delay, time.time(), reason, row["repository"]))
            self.store.commit()
            emit("bootstrap_source", repository=row["repository"], status=state, reason=reason, revision=contract.get("revision"),
                 manifest_sha256=contract.get("manifest_sha256"), capability_verified=False)
            return state == "path_verified"
        return False

    def remember(self, repository, revision, task, result):
        if not result.get("progressed") or not any(result.get("gained", {}).values()):
            return
        if not re.fullmatch(r"[a-f0-9]{40}", str(revision)):
            raise InvalidDownload("数据来源固定版本无效 / Invalid pinned data source revision")
        contract = {"language": task.get("language"), "split": task.get("split"), "scenario": task.get("scenario"),
                    "gap_kind": task.get("gap_kind"), "relevant": task.get("relevant"),
                    "required_fields": list(task.get("required_fields", [])), "gained": result["gained"],
                    "adapters": list(task.get("adapters", [])), "scope": "validated_import_not_capability_acceptance",
                    "before": result.get("before", {}), "after": result.get("after", {}),
                    "observed_data_revision": self.store.setting("data_revision"), "build_sha256": build_digest(),
                    "manifest_sha256": result.get("source_manifest_sha256")}
        self.store.db.execute("INSERT INTO validated_sources VALUES(?,?,?,?,?) ON CONFLICT(repository,task_id) DO UPDATE SET revision=excluded.revision,contract=excluded.contract,updated=excluded.updated",
                              (repository, AnnotatedAcquisition.task_identity(task), revision, json.dumps(contract, sort_keys=True), time.time()))
        self.store.commit()

    def matching(self, task):
        rows = self.store.db.execute("SELECT * FROM validated_sources WHERE task_id=? ORDER BY updated DESC,repository",
                                     (AnnotatedAcquisition.task_identity(task),)).fetchall()
        required = set(task.get("required_fields", []))
        return [dict(row) for row in rows if required.issubset(json.loads(row["contract"]).get("required_fields", []))]

    def candidates(self, task):
        kind = task.get("automatic_source")
        if kind == "annotated_catalog":
            return [{"repository": row["repository"], "revision": row["revision"], "scope": "previously_validated_import",
                     "verification": "revalidate_task_independence_and_pinned_revision", "status": "import_verified", "semantic_acceptance": False,
                     "manifest_sha256": json.loads(row["contract"]).get("manifest_sha256")} for row in self.matching(task)]
        candidates = []
        for row in self.store.db.execute("SELECT * FROM bootstrap_sources ORDER BY repository"):
            contract = json.loads(row["contract"])
            if task.get("language") is not None and task["language"] not in contract["languages"]:
                continue
            if task.get("gap_kind") not in contract["supported_tasks"]:
                continue
            if kind == "public_dialogue" and contract["repository"] != PublicDialogue.repository:
                continue
            proof = next((item for item in self.matching(task) if item["repository"] == row["repository"] and item["revision"] == contract.get("revision")), None)
            candidates.append({**contract, "status": "import_verified" if proof is not None else row["status"],
                               "import_evidence": json.loads(proof["contract"]) if proof is not None else None,
                               "reason": row["reason"], "semantic_acceptance": False})
        return candidates

    def plan(self, model, report, tasks):
        enriched = []
        for task in tasks:
            candidates = self.candidates(task)
            enriched.append({**task, "source_candidates": candidates,
                             "source_contract_ready": any(item.get("status") == "import_verified" for item in candidates),
                             "source_path_accessible": any(item.get("status") in ("path_verified", "import_verified") for item in candidates),
                             "stage": "training_data" if task.get("split") == "train" else "final_acceptance_data" if task.get("split") == "release" else "development_data"})
        training = [task for task in enriched if task["stage"] == "training_data"]
        development = [task for task in enriched if task["stage"] == "development_data"]
        final = [task for task in enriched if task["stage"] == "final_acceptance_data"]
        stages = {"model_created": bool(getattr(model, "network", None) is not None), "training_data": not training,
                  "development_data": not development, "final_acceptance_data": not final,
                  "training_path_ready": all(task["source_contract_ready"] for task in training),
                  "development_path_ready": all(task["source_contract_ready"] for task in development),
                  "final_acceptance_path_ready": all(task["source_contract_ready"] for task in final),
                  "complete_path_ready": not enriched,
                  "import_adapters_validated": all(task["source_contract_ready"] for task in enriched),
                  "owned_release_loaded": bool(getattr(model, "owned_root", None) is not None and model.service_ready()),
                  "embedded_release_present": bool(EMBEDDED_RELEASE),
                  "candidate_validated": bool(getattr(model, "dialogue_trained", False)),
                  "conversation_verified": bool(model.service_ready())}
        phase = ("accepted" if stages["conversation_verified"] else "acquiring_training_evidence" if training else
                 "acquiring_independent_evidence" if development or final else "training_and_evaluating")
        state = {"protocol": "yuan-autonomous-bootstrap-v3-import-evidence", "stages": stages, "tasks": enriched,
                 "phase": phase, "build_sha256": build_digest(), "requires_user_dataset_preparation": False,
                 "model_creation_is_capability_acceptance": False, "missing_task_count": len(enriched),
                 "unvalidated_import_count": sum(not task["source_contract_ready"] for task in enriched),
                 "blocked_contracts": [task for task in enriched if not task["source_contract_ready"]],
                 "recovery_actions": {"network_wait": "retry_transport_or_rotate_source", "schema_wait": "select_supported_adapter",
                                      "annotation_wait": "discover_human_annotated_sources", "independence_wait": "select_new_independent_recordings",
                                      "resource_wait": "restore_budget_or_select_complete_smaller_records"},
                 "completion": "independent_recorded_dialogue_acceptance", "automatic": True,
                 "coverage_sha256": payload_digest(report["cells"])}
        if self.store.setting("bootstrap_state", {}) != state:
            self.store.set_setting("bootstrap_state", state)
        return enriched

    def source_coverage(self, model, repository, task):
        kind = task.get("gap_kind")
        if kind == "retrieval_supervision":
            data = MemoryCalibration(model, self.store).selection(AcceptancePolicy(model), splits=(task["split"],))
            cell = next((item for item in data["coverage"] if item["language"] == task.get("language")
                         and item["relevant"] is task.get("relevant")), {})
            return {"sources": cell.get("have", 0), "reference_sources": 0, "dialogue_sources": 0}
        if kind in ("raw_audio", "transcript_supervision"):
            clauses = ["g.split=?", "s.generated=0", "s.audio_status='ready'", "json_extract(s.metadata,'$.corpus')=?", "s.count>=?"]
            args = [task.get("split", "train"), repository, model.hop]
            if kind == "transcript_supervision":
                clauses.extend(["s.dialogue_eligible=1", "json_extract(s.metadata,'$.transcript_verified')=1", "length(json_extract(s.metadata,'$.transcript'))>0", "s.count<=?"])
                args.append(EvaluationEligibility.budgets(model)["verifier"])
            else:
                clauses.append("s.learnable=1")
            if task.get("language") is not None:
                clauses.append("json_extract(s.metadata,'$.language')=?")
                args.append(task["language"])
            count = self.store.db.execute("SELECT count(DISTINCT g.source_key) FROM samples s JOIN groups g ON g.id=s.group_id WHERE " + " AND ".join(clauses), args).fetchone()[0]
            return {"sources": count, "reference_sources": 0, "dialogue_sources": 0}
        report = AcceptancePolicy(model).coverage(self.store, model, splits=(task["split"],), fresh=True)
        cell = next((item for item in report["cells"] if item["language"] == task.get("language") and item["scenario"] == task.get("scenario")), {})
        return {"sources": cell.get("have", 0), "reference_sources": cell.get("reference_sources", 0), "dialogue_sources": cell.get("dialogue_reference_sources", 0)}

    def run_source(self, model, job, tasks, cancel):
        repository = getattr(job, "repository", None)
        relevant = [task for task in tasks if any(item.get("repository") == repository for item in task.get("source_candidates", []))] if repository else []
        before = {AnnotatedAcquisition.task_identity(task): self.source_coverage(model, repository, task) for task in relevant}
        worked = job.step(cancel)
        revision = getattr(job, "catalog", {}).get("revision", "")
        if not worked or not re.fullmatch(r"[a-f0-9]{40}", str(revision)):
            return worked
        proof = payload_digest(job.catalog)
        for task in relevant:
            check(cancel)
            previous = before[AnnotatedAcquisition.task_identity(task)]
            after = self.source_coverage(model, repository, task)
            gained = AnnotatedAcquisition.target_gain(task, previous, after)
            result = {"before": previous, "after": after, "gained": gained, "progressed": any(gained.values()), "source_manifest_sha256": proof}
            self.remember(repository, revision, task, result)
            if result["progressed"]:
                model.emit("bootstrap_source", repository=repository, status="import_verified", revision=revision,
                           task_id=AnnotatedAcquisition.task_identity(task), gained=gained, capability_verified=False)
        return worked

    @staticmethod
    def order(jobs, tasks, turn):
        priorities = {}
        for task in tasks:
            for item in task.get("source_candidates", []):
                name = item["repository"]
                priorities[name] = priorities.get(name, 0) + max(0, task.get("missing_sources", 0))
        jobs = list(jobs)
        if not jobs:
            return jobs
        turn %= len(jobs)
        jobs = jobs[turn:] + jobs[:turn]
        return sorted(jobs, key=lambda job: -priorities.get(getattr(job, "repository", type(job).__name__), 0))

class AnnotatedAcquisition:
    licenses = frozenset(("cc-by-4.0", "cc-by-sa-4.0", "cc0-1.0", "apache-2.0", "mit"))

    def __init__(self, state, store, model, emit):
        self.state, self.store, self.model, self.emit = Path(state), store, model, emit
        self.root = safe_path(state, "datasets/remote")
        self.root.mkdir(parents=True, exist_ok=True)
        self.network = Network(policy=model.policy, config=NetworkConfig(state))
        self.store.db.execute("CREATE TABLE IF NOT EXISTS acquisition_tasks(id TEXT PRIMARY KEY,task TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','running','retry','needs_evidence','network_wait','schema_wait','annotation_wait','independence_wait','resource_wait','done')),attempts INTEGER NOT NULL DEFAULT 0,retry_at REAL NOT NULL DEFAULT 0,updated REAL NOT NULL,reason TEXT NOT NULL DEFAULT '')")
        self.store.db.execute("UPDATE acquisition_tasks SET status='retry',retry_at=0 WHERE status='running'")
        self.store.commit()
        self.catalog = read_json(self.root / "catalog.json")
        self.importers = {}
        self.acquisition_diagnostics = {}
        self.registry = SourceRegistry(store)

    def rejection(self, code):
        self.acquisition_diagnostics[code] = self.acquisition_diagnostics.get(code, 0) + 1

    @staticmethod
    def rejection_reason(diagnostics):
        labels = {"no_source": "尚未发现候选来源 / No candidate source discovered",
                  "unsupported_schema": "来源没有受支持的录音标注清单 / Source has no supported recording annotation manifest",
                  "missing_annotations": "缺少当前任务必需标注 / Required task annotations are missing",
                  "invalid_annotations": "录音标注未通过校验 / Recording annotations failed validation",
                  "source_conflict": "录音来源与目标划分冲突 / Recording source conflicts with the target split",
                  "resource_budget": "来源资源超过当前预算 / Source exceeds the current resource budget",
                  "coverage_unchanged": "有效导入未增加独立覆盖 / Valid import did not increase independent coverage",
                  "source_unavailable": "来源暂不可用 / Source temporarily unavailable"}
        return " · ".join(labels[code] for code in sorted(diagnostics) if code in labels and diagnostics[code])

    def sync(self, plan):
        keys = set()
        with self.store.transaction():
            for task in plan:
                if task["automatic_source"] != "annotated_catalog":
                    continue
                identifier = self.task_identity(task)
                keys.add(identifier)
                encoded = json.dumps(task, ensure_ascii=False, sort_keys=True)
                self.store.db.execute("INSERT INTO acquisition_tasks(id,task,status,updated) VALUES(?,?,'pending',?) ON CONFLICT(id) DO UPDATE SET task=excluded.task,status=CASE WHEN acquisition_tasks.status='done' THEN 'pending' ELSE acquisition_tasks.status END,retry_at=CASE WHEN acquisition_tasks.status='done' THEN 0 ELSE acquisition_tasks.retry_at END", (identifier, encoded, time.time()))
            for row in self.store.db.execute("SELECT id,status FROM acquisition_tasks WHERE status<>'done'").fetchall():
                if row["id"] not in keys:
                    self.store.db.execute("UPDATE acquisition_tasks SET status='done',reason='',updated=? WHERE id=?", (time.time(), row["id"]))
        summary = {row["status"]: row["n"] for row in self.store.db.execute("SELECT status,count(*) AS n FROM acquisition_tasks GROUP BY status")}
        self.store.set_setting("acquisition_summary", summary)
        blocked = [dict(item) for item in self.store.db.execute("SELECT task,reason,retry_at FROM acquisition_tasks WHERE status IN ('needs_evidence','network_wait','schema_wait','annotation_wait','independence_wait','resource_wait')")]
        self.store.set_setting("source_coverage_state", {"blocked": bool(blocked),
                               "gaps": [{"task": json.loads(item["task"]), "reason": item["reason"]} for item in blocked],
                               "retry_at": min((item["retry_at"] for item in blocked), default=None), "coverage_guaranteed": False})
        return summary

    @staticmethod
    def task_identity(task):
        return payload_digest([task.get("language"), task.get("split"), task.get("scenario"),
                               task.get("gap_kind"), task.get("relevant"), sorted(task.get("required_fields", []))])

    def target_coverage(self, task):
        if task.get("gap_kind") == "retrieval_supervision":
            data = MemoryCalibration(self.model, self.store).selection(AcceptancePolicy(self.model), splits=(task["split"],))
            cell = next((item for item in data["coverage"] if item["split"] == task["split"] and item["language"] == task["language"]
                         and item["relevant"] is task.get("relevant")), {})
            return {"sources": cell.get("have", 0), "reference_sources": 0, "dialogue_sources": 0}
        report = AcceptancePolicy(self.model).coverage(self.store, self.model, splits=(task["split"],), fresh=True)
        cell = next((cell for cell in report["cells"] if cell["language"] == task["language"] and cell["scenario"] == task["scenario"]), {})
        return {"sources": cell.get("have", 0), "reference_sources": cell.get("reference_sources", 0),
                "dialogue_sources": cell.get("dialogue_reference_sources", 0)}

    @staticmethod
    def target_gain(task, before, after):
        needs = {"sources": "missing_sources", "reference_sources": "missing_reference_sources", "dialogue_sources": "missing_dialogue_sources"}
        return {key: max(0, after.get(key, 0) - before.get(key, 0)) for key, need in needs.items() if task.get(need, 0) > 0}

    def matches_task(self, manifest, task):
        split, scenario = task.get("split"), task.get("scenario")
        if manifest.get("language") != task.get("language") or split not in ("train", "validation", "guard", "release"):
            return False
        if manifest.get("split") not in (None, split):
            return False
        existing = self.store.db.execute("SELECT DISTINCT split FROM groups WHERE source_key=?", (manifest["recording_id"],)).fetchall()
        if any(row["split"] != split for row in existing):
            return False
        turns = {turn["id"]: turn for turn in manifest["turns"]}
        for turn in manifest["turns"]:
            if turn["role"] != "assistant" or turn.get("response_verified") is not True:
                continue
            user = turns.get(turn.get("reply_to"), {})
            if task.get("gap_kind") == "retrieval_supervision":
                annotation = turn.get("retrieval", {})
                if (not isinstance(annotation, dict) or annotation.get("method") != "human_retrieval_relevance_v1"
                        or annotation.get("verified") is not True or not isinstance(annotation.get("examples"), list)):
                    continue
                for example in annotation["examples"]:
                    if not isinstance(example, dict) or type(example.get("relevant")) is not bool or example["relevant"] is not task.get("relevant"):
                        continue
                    candidate = turns.get(example.get("sample"))
                    if candidate is not None and candidate["id"] not in (user.get("id"), turn["id"]) and candidate["start_seconds"] < user.get("start_seconds", 0):
                        return True
                continue
            if split == "train":
                if scenario is None or scenario in turn.get("scenarios", manifest.get("scenarios", [])):
                    return True
                continue
            if (scenario not in turn.get("scenarios", manifest.get("scenarios", [])) or scenario not in turn.get("contrasts", {})
                    or turn.get("utterance_final") is not True or user.get("utterance_final") is not True):
                continue
            history = [value for value in manifest["turns"] if value["id"] != user.get("id") and value["start_seconds"] < user["start_seconds"]]
            if scenario == "history" and not history:
                continue
            if task.get("missing_reference_sources", 0) > 0 and not all(turn.get("reference_checks", {}).get(key) is True for key in AcceptancePolicy.reference_checks):
                continue
            if task.get("missing_dialogue_sources", 0) > 0:
                evidence = {**turn, "method": "human_audio_annotation", "recording_id": manifest["recording_id"],
                            "scenarios": turn.get("scenarios", manifest.get("scenarios", []))}
                if not {"user", "assistant"}.issubset({value["role"] for value in history}) or not CapabilityEvidence.dialogue_reference(evidence):
                    continue
            return True
        return False

    @staticmethod
    def catalog_url(url):
        parts = urllib.parse.urlsplit(url)
        if (parts.scheme != "https" or parts.hostname != "huggingface.co" or parts.username is not None or parts.password is not None
                or parts.port not in (None, 443) or parts.path.rstrip("/") != "/api/datasets" or parts.fragment):
            raise InvalidDownload("标注目录分页地址无效 / Invalid annotation catalog pagination URL")
        return url

    @classmethod
    def catalog_next(cls, headers, current):
        value = next((value for key, value in headers.items() if key.lower() == "link"), "")
        for part in urllib.request.parse_http_list(str(value)):
            match = re.search(r'<([^>]+)>', part)
            relation = re.search(r';\s*rel\s*=\s*(?:"([^"]+)"|([^;\s]+))', part, re.I)
            if match and relation and "next" in (relation.group(1) or relation.group(2)).split():
                return cls.catalog_url(urllib.parse.urljoin(current, match.group(1)))
        return None

    def discover(self, cancel, task=None):
        self.network.cancel = cancel
        task = task or {}
        identifier = self.task_identity(task)
        interval = self.model.policy.number("network", "annotation_catalog_seconds", 3600.0, 1.0, 86400.0)
        catalog = self.catalog if isinstance(self.catalog, dict) else {}
        entries = catalog.get("tasks", {})
        entries = entries if isinstance(entries, dict) else {}
        entry = entries.get(identifier, {})
        entry = entry if isinstance(entry, dict) else {}
        limit = self.model.policy.integer("network", "annotation_catalog_entries", max(1, available_resources(__import__("psutil"))["cpus"] * 4), 1, 256)
        language = {"中文": "Chinese", "English": "English"}.get(task.get("language"), "")
        queries = [{"search": " ".join(value for value in (language, "annotated audio dialogue") if value)},
                   {"search": " ".join(value for value in (language, "recorded conversation") if value)},
                   {"search": "speech dialogue"}, {"filter": "yuan-paired-audio-v1"}, {"search": "yuan-paired-audio"}]
        if task.get("gap_kind") == "retrieval_supervision":
            queries = [{"search": language + " speech retrieval relevance"}, {"search": "annotated spoken memory"}, *queries]
        query_states = entry.get("queries", {})
        query_states = query_states if isinstance(query_states, dict) else {}
        repositories = [name for name in catalog.get("repositories", []) if isinstance(name, str)
                        and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*", name)]
        cursor_key = "annotation_query_cursor_" + identifier
        cursor = int(self.store.setting(cursor_key, 0)) % len(queries)
        selected = None
        for offset in range(len(queries)):
            index = (cursor + offset) % len(queries)
            query = queries[index]
            state = query_states.get(payload_digest(query), {})
            state = state if isinstance(state, dict) else {}
            if state.get("complete") is not True or state.get("updated", 0) + interval <= time.time():
                selected = (index, query, state)
                break
        if selected is None:
            return repositories
        index, query, state = selected
        initial = "https://huggingface.co/api/datasets?" + urllib.parse.urlencode({**query, "limit": limit})
        continuing = state.get("complete") is not True and isinstance(state.get("next_url"), str)
        url = self.catalog_url(state["next_url"] if continuing else initial)
        rows, headers = self.network.json(url, with_headers=True)
        if not isinstance(rows, list):
            raise InvalidDownload("自动标注目录格式无效 / Invalid automatic annotation catalog")
        for row in rows:
            check(cancel)
            name = row.get("id", "") if isinstance(row, dict) else ""
            if isinstance(name, str) and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*", name) and not row.get("gated") and not row.get("disabled"):
                repositories.append(name)
        next_url = self.catalog_next(headers, url)
        seen = list(state.get("pages", [])) if continuing else []
        signature = payload_digest(url)
        if signature not in seen:
            seen.append(signature)
        if next_url and payload_digest(next_url) in seen:
            raise InvalidDownload("标注目录分页出现循环 / Annotation catalog pagination contains a cycle")
        query_states[payload_digest(query)] = {"query": query, "updated": time.time(), "next_url": next_url,
                                             "complete": next_url is None, "pages": seen}
        entries[identifier] = {"created": time.time(), "queries": query_states}
        self.catalog = {"repositories": sorted(set(repositories)), "tasks": entries}
        atomic_json(self.root / "catalog.json", self.catalog, cancel)
        self.store.set_setting(cursor_key, index + 1)
        return self.catalog["repositories"]

    @staticmethod
    def file_identity(row):
        if not isinstance(row, dict):
            raise InvalidDownload("来源文件清单无效 / Invalid source file manifest")
        name = row.get("rfilename", "")
        if (not isinstance(name, str) or not name or "\\" in name or Path(name).is_absolute() or ".." in Path(name).parts):
            raise InvalidDownload("来源文件路径无效 / Invalid source file path")
        lfs = row.get("lfs") or {}
        size = lfs.get("size", row.get("size"))
        checksum = lfs.get("sha256", lfs.get("oid"))
        git = row.get("blobId")
        if type(size) is not int or size <= 0 or not (is_digest(checksum) or isinstance(git, str) and re.fullmatch(r"[a-f0-9]{40}", git)):
            raise InvalidDownload("来源文件缺少完整性证据 / Source file lacks integrity evidence")
        return {"name": name, "size": size, "sha256": checksum if is_digest(checksum) else None, "git": git}

    def fetch(self, repository, revision, item, root, cancel):
        target = safe_path(root, item["name"])
        if target.exists():
            valid = target.stat().st_size == item["size"]
            if valid and item["sha256"]:
                valid = digest_file(target, cancel) == item["sha256"]
            elif valid:
                with target.open("rb") as stream:
                    digest = hashlib.sha1(("blob " + str(item["size"]) + "\0").encode())
                    for block in iter(lambda: stream.read(1024 * 1024), b""):
                        check(cancel)
                        digest.update(block)
                valid = digest.hexdigest() == item["git"]
            if valid:
                return target
            target.unlink()
        if item["size"] > StorageBudget(self.state).snapshot(item["size"])["available_bytes"]:
            raise IneligibleSample("公开标注资源超过存储预算 / Public annotation resource exceeds the storage budget")
        url = "https://huggingface.co/datasets/" + repository + "/resolve/" + revision + "/" + urllib.parse.quote(item["name"], safe="/")
        self.network.cancel = cancel
        self.network.download(url, target, expected_size=item["size"], expected_hash=item["sha256"], max_bytes=item["size"], storage=StorageBudget(self.state))
        if item["sha256"] is None:
            digest = hashlib.sha1(("blob " + str(item["size"]) + "\0").encode())
            with target.open("rb") as stream:
                for block in iter(lambda: stream.read(1024 * 1024), b""):
                    check(cancel)
                    digest.update(block)
            if digest.hexdigest() != item["git"]:
                target.unlink(missing_ok=True)
                raise InvalidDownload("公开标注文件身份校验失败 / Public annotation file identity verification failed")
        return target

    def repository(self, repository, cancel, revision=None):
        key = "annotation_pin_" + payload_digest(repository)
        pin = self.store.setting(key, {})
        if revision is not None:
            if not re.fullmatch(r"[a-f0-9]{40}", str(revision)):
                raise InvalidDownload("标注来源版本无效 / Invalid annotated source revision")
            pin = {**pin, "revision": revision}
        pinned = bool(re.fullmatch(r"[a-f0-9]{40}", str(pin.get("revision", ""))))
        suffix = "/revision/" + pin["revision"] if pinned else ""
        self.network.cancel = cancel
        data = self.network.json("https://huggingface.co/api/datasets/" + repository + suffix + "?blobs=true")
        revision = data.get("sha", "")
        licenses = (data.get("cardData") or {}).get("license", [])
        licenses = [licenses] if isinstance(licenses, str) else licenses
        if (data.get("gated") or data.get("disabled") or not isinstance(licenses, list)
                or not set(licenses).intersection(self.licenses) or not re.fullmatch(r"[a-f0-9]{40}", str(revision))
                or pinned and revision != pin.get("revision")):
            raise IneligibleSample("来源版本、授权或访问条件不满足要求 / Source version, license or access conditions are unsuitable")
        catalog = {}
        for row in data.get("siblings", []):
            check(cancel)
            try:
                item = self.file_identity(row)
                catalog[item["name"]] = item
            except InvalidDownload:
                continue
        if not pinned:
            self.store.set_setting(key, {"revision": revision, "licenses": licenses, "created": pin.get("created", time.time()), "checked_at": time.time()})
        return revision, catalog

    def import_export(self, repository, revision, item, catalog, root, cancel, task=None):
        path = self.fetch(repository, revision, item, root, cancel)
        cursor_key = "annotation_cursor_" + payload_digest([repository, revision, item, self.task_identity(task) if task else None])
        position = int(self.store.setting(cursor_key, 0))
        for index, raw in enumerate(RecordedDialogueAdapter.records(path, cancel)):
            if index < position:
                continue
            check(cancel)
            try:
                manifest = RecordedDialogueAdapter.convert(raw)
                if str(manifest.get("license", "")).casefold() not in self.licenses:
                    raise IneligibleSample("标注清单授权不符合要求 / Annotation manifest license is unsuitable")
                DatasetImporter.validate_annotations(manifest)
                DatasetImporter.validate_semantic(manifest)
                if task is not None:
                    if not self.matches_task(manifest, task):
                        conflict = self.store.db.execute("SELECT 1 FROM groups WHERE source_key=? AND split<>? LIMIT 1", (manifest["recording_id"], task["split"])).fetchone()
                        self.rejection("source_conflict" if conflict else "missing_annotations")
                        self.store.set_setting(cursor_key, index + 1)
                        continue
                    if manifest.get("split") is None:
                        manifest["split"] = task["split"]
            except (YuanError, ValueError, TypeError, KeyError) as exc:
                self.rejection("invalid_annotations")
                self.store.set_setting(cursor_key, index + 1)
                self.emit("network", key="dataset_rejected", repository=repository, file=item["name"], record=index, reason=concise_error(exc))
                continue
            importer_key = (repository, revision, str(path.parent))
            importer = self.importers.get(importer_key)
            if importer is None:
                importer = DatasetImporter(self.state, self.store, self.model, self.emit,
                                           namespace="public:" + repository + ":" + path.parent.relative_to(root).as_posix(), root=path.parent)
                self.importers[importer_key] = importer
            normalized = path.parent / ("normalized-" + payload_digest([item["name"], index]) + ".yuan.json")
            manifest.setdefault("dataset_id", payload_digest([repository, item["name"], manifest["recording_id"], index]))
            for turn in manifest["turns"]:
                local = safe_path(path.parent, turn["audio"])
                relative = local.relative_to(root).as_posix()
                audio = catalog.get(relative)
                if audio is None or audio["sha256"] not in (None, turn["sha256"]):
                    raise InvalidDownload("录音标注与源音频身份不一致 / Recording annotation and source audio identities differ")
                self.fetch(repository, revision, audio, root, cancel)
                if digest_file(local, cancel) != turn["sha256"]:
                    raise InvalidDownload("录音与人工标注摘要不一致 / Recording checksum differs from its annotation")
            atomic_json(normalized, manifest, cancel)
            key = importer.identity_key(normalized, manifest)
            if self.store.setting(key) != digest_file(normalized, cancel):
                worked = importer.step(cancel, paths=[normalized])
                if not worked:
                    raise IneligibleSample("来源录音未通过完整导入校验 / Source recording failed complete import validation")
                self.store.set_setting(cursor_key, index + 1)
                self.emit("network", key="dataset_import", repository=repository, revision=revision,
                          license=manifest["license"], language=manifest["language"], evidence_scope="publisher_annotations")
                return True
            self.store.set_setting(cursor_key, index + 1)
        return False

    def acquire(self, task, cancel):
        self.network.cancel = cancel
        before = self.target_coverage(task)
        self.acquisition_diagnostics = {}
        result = {"imported": 0, "before": before, "after": before, "gained": {}, "progressed": False, "blockers": self.acquisition_diagnostics}
        matching = self.registry.matching(task)
        revisions = {row["repository"]: row["revision"] for row in matching}
        preferred = [row["repository"] for row in matching if self.store.setting("annotation_repository_state_" + payload_digest([self.task_identity(task), row["repository"]]), {}).get("retry_at", 0) <= time.time()]
        try:
            discovered = [] if preferred else self.discover(cancel, task)
        except (OSError, YuanError, ValueError, TypeError):
            if not preferred:
                raise
            discovered = []
        candidates = list(dict.fromkeys([*preferred, *discovered]))
        requested = task.get("repositories")
        if isinstance(requested, list) and requested:
            candidates = sorted({repository for repository in requested if isinstance(repository, str)
                                 and re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9_.-]*/[A-Za-z0-9][A-Za-z0-9_.-]*", repository)})
        if not candidates:
            self.rejection("no_source")
            return result
        identifier = self.task_identity(task)
        cursor_key = "annotation_repository_cursor_" + identifier
        cursor = int(self.store.setting(cursor_key, 0)) % len(candidates)
        candidates = candidates[cursor:] + candidates[:cursor]
        batch = self.model.policy.integer("network", "annotation_repositories_per_step", 1, 1, max(1, len(candidates)))
        for repository in candidates[:batch]:
            check(cancel)
            self.store.set_setting(cursor_key, cursor + 1)
            cursor += 1
            key = "annotation_repository_state_" + payload_digest([identifier, repository])
            state = self.store.setting(key, {})
            if state.get("retry_at", 0) > time.time():
                continue
            imported = 0
            try:
                revision, catalog = self.repository(repository, cancel, revision=revisions.get(repository))
                result["source_manifest_sha256"] = payload_digest(catalog)
                root = safe_path(self.root, payload_digest(repository) + "/" + revision)
                root.mkdir(parents=True, exist_ok=True)
                limit = self.model.policy.integer("network", "annotation_manifest_bytes", 16 * 1024 * 1024, 1024,
                                                  max(1024, available_resources(__import__("psutil"))["memory"] // 8))
                hints = ({"中文": ("zh", "chinese", "mandarin"), "English": ("en", "english")}.get(task["language"], ())
                         + ((task["scenario"],) if task.get("scenario") else ()) + ("annotation", "dialogue", "conversation"))
                items = sorted(catalog.items(), key=lambda pair: (-sum(word in Path(pair[0]).stem.casefold() for word in hints), pair[0]))
                supported = [(name, item) for name, item in items if Path(name).suffix.lower() in (".json", ".jsonl")]
                if not supported:
                    self.rejection("unsupported_schema")
                for name, item in supported:
                    if item["size"] > limit:
                        self.rejection("resource_budget")
                        continue
                    check(cancel)
                    try:
                        if self.import_export(repository, revision, item, catalog, root, cancel, task=task):
                            imported += 1
                            result["imported"] += 1
                            result["after"] = self.target_coverage(task)
                            result["gained"] = self.target_gain(task, before, result["after"])
                            result["progressed"] = any(result["gained"].values())
                            self.store.set_setting(key, {"state": "active", "revision": revision})
                            if result["progressed"]:
                                self.registry.remember(repository, revision, task, result)
                                return result
                            self.rejection("coverage_unchanged")
                    except (InvalidDownload, IneligibleSample, ValueError, TypeError, KeyError) as exc:
                        self.rejection("invalid_annotations")
                        self.emit("network", key="dataset_rejected", repository=repository, file=name, reason=concise_error(exc))
                delay = self.model.policy.number("network", "annotation_catalog_seconds", 3600.0, 1.0, 86400.0)
                self.store.set_setting(key, {"state": "active" if imported else "exhausted", "revision": revision,
                                             "retry_at": 0 if imported else time.time() + delay})
            except Cancelled:
                raise
            except (OSError, YuanError, ValueError, TypeError, KeyError) as exc:
                self.rejection("source_unavailable")
                failures = state.get("failures", 0) + 1
                self.store.set_setting(key, {"state": "retry", "failures": failures, "reason": concise_error(exc),
                                             "retry_at": time.time() + self.store.retry_delay(failures)})
                self.emit("network", key="source_unavailable", repository=repository, reason=concise_error(exc))
        result["after"] = self.target_coverage(task)
        result["gained"] = self.target_gain(task, before, result["after"])
        result["progressed"] = any(result["gained"].values())
        return result

    def step(self, plan, cancel):
        self.sync(plan)
        row = self.store.db.execute("SELECT * FROM acquisition_tasks WHERE status IN ('pending','retry','needs_evidence','network_wait','schema_wait','annotation_wait','independence_wait','resource_wait') AND retry_at<=? ORDER BY attempts,updated,id LIMIT 1", (time.time(),)).fetchone()
        if row is None:
            return False
        task = json.loads(row["task"])
        self.store.db.execute("UPDATE acquisition_tasks SET status='running',attempts=attempts+1,updated=? WHERE id=?", (time.time(), row["id"]))
        self.store.commit()
        worked, state, reason = False, "annotation_wait", "未发现补齐当前缺口的授权标注资源 / No licensed annotated resource fills the current gap"
        result = {"imported": 0, "gained": {}, "progressed": False}
        try:
            result = self.acquire(task, cancel)
            worked = result["progressed"]
            if worked:
                state, reason = "pending", "目标独立来源覆盖增加，完成状态由实际覆盖重新计算 / Target independent-source coverage increased; completion is recalculated from actual coverage"
            elif result["imported"]:
                reason = "已导入有效数据，但未增加当前任务的独立覆盖 / Valid data imported without increasing independent coverage for this task"
            elif result.get("blockers"):
                state = SourceRegistry.failure_state(blockers=result["blockers"])
                reason = self.rejection_reason(result["blockers"]) or reason
        except Cancelled:
            self.store.db.execute("UPDATE acquisition_tasks SET status='pending',retry_at=0 WHERE id=?", (row["id"],))
            self.store.commit()
            raise
        except (OSError, ValueError, TypeError, KeyError, RuntimeError, sqlite3.Error) as exc:
            state, reason = SourceRegistry.failure_state(exc), concise_error(exc)
        attempts = row["attempts"] + 1
        initial = self.store.retry_delay(attempts, state in ("schema_wait", "annotation_wait", "independence_wait"))
        delay = self.model.policy.number("network", state + "_retry_seconds", initial, 1.0, 86400.0)
        if state == "pending":
            delay = math.sqrt(tick())
        self.store.db.execute("UPDATE acquisition_tasks SET status=?,reason=?,updated=?,retry_at=? WHERE id=?", (state, reason, time.time(), time.time() + delay, row["id"]))
        self.store.commit()
        report = AcceptancePolicy(self.model).coverage(self.store, self.model, fresh=True)
        self.sync(AcceptancePolicy(self.model).acquisition_plan(report))
        current = self.store.db.execute("SELECT status FROM acquisition_tasks WHERE id=?", (row["id"],)).fetchone()
        state = current["status"] if current is not None else state
        status = self.store.setting("source_coverage_state", {})
        self.emit("data_acquisition", key="data_sources_exhausted" if status.get("blocked") else "data_plan", task=task, state=state,
                  worked=worked, imported=result["imported"], gained=result["gained"], blockers=result.get("blockers", {}), reason=reason)
        return worked

class PublishedSpeech:
    specifications = (
        {"repository": "google/fleurs", "adapter": "fleurs", "revision_ref": "refs/convert/parquet", "license": "cc-by-4.0",
         "pattern": r"(?:cmn_hans_cn|en_us)/(train|validation|test)/[0-9]+\.parquet", "languages": ("中文", "English"),
         "columns": ("id", "audio", "raw_transcription", "path"), "attribution": "FLEURS: Conneau and collaborators, Google, 2022"},
        {"repository": "CAiRE/ASCEND", "adapter": "ascend", "license": "cc-by-sa-4.0", "pattern": r"main/(train|validation|test)-[0-9]+-of-[0-9]+\.parquet", "languages": ("中文", "English", "mixed"), "attribution": "ASCEND: Holy Lovenia and collaborators, CAiRE, LREC 2022"},
        {"repository": "openslr/librispeech_asr", "adapter": "librispeech", "license": "cc-by-4.0", "pattern": r"clean/(train\.100|validation|test)/[^/]+\.parquet", "languages": ("English",), "attribution": "LibriSpeech: Vassil Panayotov, Guoguo Chen, Daniel Povey and Sanjeev Khudanpur, ICASSP 2015"})

    def __init__(self, state, store, model, emit, specification):
        self.state, self.store, self.model, self.emit = Path(state), store, model, emit
        self.specification = dict(specification)
        self.repository = specification["repository"]
        self.root = safe_path(state, "datasets/native/" + payload_digest(self.repository))
        self.root.mkdir(parents=True, exist_ok=True)
        self.network = Network(policy=model.policy, config=NetworkConfig(state))
        self.reader = self.iterator = self.current = self.pending = None
        self.reader_path = None
        self.catalog = read_json(self.root / "catalog.json")
        self.store.db.execute("CREATE TABLE IF NOT EXISTS native_sources(id TEXT PRIMARY KEY,repository TEXT NOT NULL,revision TEXT NOT NULL,item TEXT NOT NULL,upstream TEXT NOT NULL,row_group INTEGER NOT NULL DEFAULT 0,row_offset INTEGER NOT NULL DEFAULT 0,finished INTEGER NOT NULL DEFAULT 0,failures INTEGER NOT NULL DEFAULT 0,retry_at REAL NOT NULL DEFAULT 0,error TEXT NOT NULL DEFAULT '')")
        self.store.commit()

    def close(self):
        self.iterator = self.pending = None
        if self.reader is not None:
            self.reader.close()
        self.reader = self.current = self.reader_path = None

    def catalog_query(self, cancel):
        self.network.cancel = cancel
        pin_key = "native_pin_" + payload_digest(self.repository)
        pin = self.store.setting(pin_key, {})
        root = "https://huggingface.co/api/datasets/" + self.repository
        license_ref = "/revision/" + pin["license_revision"] if pin.get("license_revision") else ""
        metadata = self.network.json(root + license_ref + "?blobs=true")
        licenses = (metadata.get("cardData") or {}).get("license", [])
        licenses = [licenses] if isinstance(licenses, str) else licenses
        license_revision = metadata.get("sha", "")
        if (metadata.get("gated") or metadata.get("disabled") or not isinstance(licenses, list)
                or self.specification["license"] not in licenses or not re.fullmatch(r"[a-f0-9]{40}", str(license_revision))
                or pin and license_revision != pin.get("license_revision")):
            raise InvalidDownload("原生语料版本或授权不可核验 / Native corpus revision or license cannot be verified")
        ref = pin.get("revision", self.specification.get("revision_ref"))
        data = self.network.json(root + "/revision/" + urllib.parse.quote(ref, safe="") + "?blobs=true") if ref else metadata
        revision = data.get("sha", "")
        if (not re.fullmatch(r"[a-f0-9]{40}", str(revision)) or pin and revision != pin.get("revision")
                or data.get("gated") or data.get("disabled")):
            raise InvalidDownload("原生语料固定版本身份不一致 / Pinned native corpus revision identity differs")
        items = []
        for raw in data.get("siblings", []):
            check(cancel)
            match = re.fullmatch(self.specification["pattern"], str(raw.get("rfilename", "")))
            if match:
                items.append((AnnotatedAcquisition.file_identity(raw), match[1]))
        if not items:
            raise InvalidDownload("原生语料没有受支持的可校验分片 / Native corpus has no supported verifiable shards")
        with self.store.transaction():
            for item, upstream in items:
                identifier = payload_digest([self.repository, revision, item])
                self.store.db.execute("INSERT OR IGNORE INTO native_sources(id,repository,revision,item,upstream) VALUES(?,?,?,?,?)", (identifier, self.repository, revision, json.dumps(item, sort_keys=True), upstream))
            self.store.set_setting(pin_key, {"revision": revision, "license_revision": license_revision, "license": self.specification["license"]})
        self.catalog = {"repository": self.repository, "revision": revision, "license_revision": license_revision,
                        "license": self.specification["license"], "created": time.time(), "pinned": True}
        atomic_json(self.root / "catalog.json", self.catalog, cancel)

    def descriptor(self, raw, upstream, asset_name=""):
        native_id = raw.get("id")
        if not isinstance(native_id, (str, int)) or isinstance(native_id, bool) or not str(native_id):
            raise InvalidDownload("原生语料缺少片段标识 / Native corpus lacks an utterance identity")
        if self.specification["adapter"] == "ascend":
            speaker, session = raw.get("original_speaker_id"), raw.get("session_id")
            if type(speaker) is not int or type(session) is not int or speaker < 0 or session < 0:
                raise InvalidDownload("ASCEND 说话人或录音会话标识无效 / Invalid ASCEND speaker or session identity")
            language = {"zh": "中文", "en": "English", "mixed": "mixed"}.get(raw.get("language"))
            transcript = raw.get("transcription")
            source = self.repository + ":speaker:" + str(speaker)
            identity = {"speaker": str(speaker), "session": session, "topic": str(raw.get("topic", "")), "source_language": raw.get("language"), "source_identity_scope": "speaker", "dialogue_pairing": "not_inferred"}
        elif self.specification["adapter"] == "fleurs":
            subset = str(asset_name).split("/", 1)[0]
            language = {"cmn_hans_cn": "中文", "en_us": "English"}.get(subset)
            transcript = raw.get("raw_transcription")
            if language is None or not isinstance(transcript, str) or not transcript.strip():
                raise IneligibleSample("FLEURS 缺少受支持的语言或原始转写 / FLEURS lacks a supported language or original transcript")
            source = self.repository + ":sentence:" + payload_digest(SpeechVerifier.normalize_text(transcript))
            native_id = subset + "/" + str(native_id) + "/" + Path(str(raw.get("path", ""))).name
            identity = {"source_language": subset, "source_identity_scope": "transcript_content", "speaker_independent": False,
                        "dialogue_pairing": "not_applicable"}
        elif self.specification["adapter"] == "librispeech":
            speaker, chapter = raw.get("speaker_id"), raw.get("chapter_id")
            if type(speaker) is not int or type(chapter) is not int or speaker < 0 or chapter < 0:
                raise InvalidDownload("LibriSpeech 说话人或章节标识无效 / Invalid LibriSpeech speaker or chapter identity")
            language, transcript = "English", raw.get("text")
            source = self.repository + ":chapter:" + str(chapter)
            identity = {"speaker": str(speaker), "chapter": chapter, "source_language": "en", "source_identity_scope": "book_chapter", "dialogue_pairing": "not_applicable"}
        else:
            raise InvalidDownload("不支持的原生语料适配器 / Unsupported native corpus adapter")
        if language is None or not isinstance(transcript, str) or not transcript.strip():
            raise IneligibleSample("原生语料缺少语言或人工转写 / Native corpus lacks language or human transcription")
        split = "train" if upstream.startswith("train") else "validation" if upstream == "validation" else "guard" if upstream == "test" else None
        if split is None:
            raise InvalidDownload("原生语料划分无效 / Invalid native corpus split")
        existing = self.store.db.execute("SELECT split FROM groups WHERE source_key=? LIMIT 1", (source,)).fetchone()
        if existing is not None and existing["split"] != split:
            raise IneligibleSample("原始来源跨集合，拒绝混入 / Original source crosses dataset splits; import rejected")
        return {**identity, "native_id": str(native_id), "recording_id": source, "split": split, "language": language, "transcript": transcript.strip(), "transcript_verified": True, "transcript_method": "publisher_human_transcription", "utterance_final": True, "semantic_acceptance": False, "upstream_split": upstream}

    def import_row(self, raw, source, cancel):
        import soundfile as sf
        import psutil
        descriptor = self.descriptor(raw, source["upstream"], json.loads(source["item"])["name"])
        audio = raw.get("audio")
        encoded = audio.get("bytes") if isinstance(audio, dict) else None
        if not isinstance(encoded, bytes) or not encoded:
            raise InvalidDownload("原生语料分片未包含音频字节 / Native corpus shard does not contain audio bytes")
        limit = max(1, available_resources(psutil)["memory"] // max(2, self.model.layers + 1))
        if len(encoded) > limit:
            raise MemoryError("原生语料音频超过内存预算 / Native corpus audio exceeds the memory budget")
        raw_digest = hashlib.sha256(encoded).hexdigest()
        identifier = payload_digest([self.repository, descriptor["native_id"], raw_digest])
        previous = self.store.sample(identifier)
        if previous is not None and json.loads(previous["metadata"]).get("revision") == source["revision"]:
            return False
        with sf.SoundFile(io.BytesIO(encoded)) as stream:
            if stream.channels != 1 or stream.frames <= 0 or stream.samplerate <= 0:
                raise InvalidAudio("原生语料应为完整单声道录音 / Native corpus must contain a complete mono recording")
            if stream.frames * max(4, math.ceil(self.model.rate / stream.samplerate) * 4) * 3 > limit:
                raise MemoryError("原生语料解码超过内存预算 / Native corpus decoding exceeds the memory budget")
            values, rate = stream.read(dtype="float32"), stream.samplerate
        check(cancel)
        values = self.model.normalize(values, rate)
        if len(values) < self.model.hop:
            raise IneligibleSample("原生语料片段过短 / Native corpus utterance is too short")
        metadata = {**descriptor, "corpus": self.repository, "revision": source["revision"], "license": self.specification["license"], "attribution": self.specification["attribution"], "raw_sha256": raw_digest, "source_shard": json.loads(source["item"]), "source_url": "https://huggingface.co/datasets/" + self.repository + "/tree/" + source["revision"]}
        group = "native-" + payload_digest(descriptor["recording_id"])
        prepared, published = None, False
        try:
            with self.store.audio_files(cancel):
                prepared = self.store.prepare_audio(values, self.model.rate, cancel)
                with self.store.transaction():
                    self.store.group(group, "dataset", forced=descriptor["split"], source_key=descriptor["recording_id"], retention="training_cache", provenance={key: metadata[key] for key in ("corpus", "revision", "license", "attribution", "source_url", "source_identity_scope")})
                    created = previous["created"] if previous is not None else time.time()
                    self.store.add(group, "user", None, self.model.rate, "dataset", cancel, created=created, sample_id=identifier, metadata=metadata, prepared=prepared)
                    self.store.assert_independent([group])
                published = True
            self.emit("dataset_import", key="public_speech_import", corpus=self.repository, sample=identifier, language=descriptor["language"], split=descriptor["split"], evidence_scope="human_transcript_supervision", semantic_acceptance=False)
            return True
        finally:
            if prepared is not None and not published:
                self.store.discard_audio(prepared)

    def open_source(self, source, cancel):
        import pyarrow.parquet as pq
        import psutil
        self.close()
        item = json.loads(source["item"])
        path = AnnotatedAcquisition.fetch(self, self.repository, source["revision"], item, self.root / source["revision"], cancel)
        memory = max(1, available_resources(psutil)["memory"] // max(2, self.model.layers + 1))
        with path.open("rb") as stream:
            if path.stat().st_size < 12:
                raise InvalidDownload("原生语料分片不完整 / Native corpus shard is incomplete")
            stream.seek(-8, 2)
            footer = stream.read(8)
            if footer[4:] != b"PAR1" or int.from_bytes(footer[:4], "little") > min(memory, path.stat().st_size - 8):
                raise InvalidDownload("原生语料分片尾部无效 / Invalid native corpus shard footer")
        reader = pq.ParquetFile(str(path), memory_map=True, pre_buffer=False, thrift_string_size_limit=memory, thrift_container_size_limit=max(1, memory // 64), page_checksum_verification=True)
        self.reader, self.reader_path, self.current = reader, path, source
        group = source["row_group"]
        if not 0 <= group < reader.num_row_groups:
            self.store.db.execute("UPDATE native_sources SET finished=1,error='' WHERE id=?", (source["id"],))
            self.store.commit()
            self.close()
            path.unlink(missing_ok=True)
            return False
        metadata = reader.metadata.row_group(group)
        if metadata.total_byte_size * 3 > memory:
            raise MemoryError("原生语料行组超过当前内存预算 / Native corpus row group exceeds the current memory budget")
        columns = self.specification.get("columns") or (("id", "audio", "transcription", "language", "original_speaker_id", "session_id", "topic") if self.specification["adapter"] == "ascend" else ("id", "audio", "text", "speaker_id", "chapter_id"))
        if not set(columns).issubset(reader.schema_arrow.names):
            raise InvalidDownload("原生语料字段与适配器不匹配 / Native corpus fields do not match the adapter")
        self.iterator = reader.iter_batches(batch_size=1, row_groups=[group], columns=list(columns), use_threads=False)
        if source["row_offset"] > metadata.num_rows or source["row_offset"] < 0:
            raise InvalidDownload("原生语料恢复位置无效 / Invalid native corpus resume position")
        for position in range(source["row_offset"]):
            check(cancel)
            next(self.iterator)
        return True

    def step(self, cancel):
        check(cancel)
        state_key = "native_source_" + payload_digest(self.repository)
        status = self.store.setting(state_key, {})
        if status.get("retry_at", 0) > time.time():
            return False
        source = self.current
        try:
            if (not self.catalog or self.catalog.get("repository") != self.repository
                    or not self.store.db.execute("SELECT 1 FROM native_sources WHERE repository=? AND revision=? LIMIT 1", (self.repository, self.catalog.get("revision"))).fetchone()):
                self.catalog_query(cancel)
            if source is None:
                rows = self.store.db.execute("SELECT * FROM native_sources WHERE repository=? AND revision=? AND finished=0 AND retry_at<=? ORDER BY id", (self.repository, self.catalog["revision"], time.time())).fetchall()
                last = self.store.setting(state_key + "_last", "")
                source = next((row for row in rows if row["id"] > last), rows[0] if rows else None)
                if source is None:
                    unfinished = self.store.db.execute("SELECT min(retry_at) FROM native_sources WHERE repository=? AND revision=? AND finished=0", (self.repository, self.catalog["revision"])).fetchone()[0]
                    interval = self.model.policy.number("network", "native_catalog_seconds", 86400.0, 1.0, 30 * 86400.0)
                    self.store.set_setting(state_key, {"retry_at": min(time.time() + interval, unfinished) if unfinished is not None else time.time() + interval, "state": "resource_wait" if unfinished is not None else "catalog_exhausted"})
                    if unfinished is None:
                        self.catalog = {}
                        (self.root / "catalog.json").unlink(missing_ok=True)
                    return False
                if not self.open_source(source, cancel):
                    return False
            if self.pending is None:
                try:
                    self.pending = next(self.iterator).to_pylist()[0]
                except StopIteration:
                    self.store.db.execute("UPDATE native_sources SET row_group=row_group+1,row_offset=0,failures=0,error='' WHERE id=?", (source["id"],))
                    self.store.set_setting(state_key + "_last", source["id"])
                    self.close()
                    return True
            try:
                worked = self.import_row(self.pending, source, cancel)
            except (IneligibleSample, InvalidAudio, InvalidDownload, ValueError, TypeError, KeyError) as exc:
                worked = False
                self.emit("notice", key="dataset_rejected", corpus=self.repository, file=json.loads(source["item"])["name"], row_group=source["row_group"], row_offset=self.current["row_offset"], reason=concise_error(exc))
            check(cancel)
            self.store.db.execute("UPDATE native_sources SET row_offset=row_offset+1,failures=0,retry_at=0,error='' WHERE id=?", (source["id"],))
            self.store.commit()
            self.current = self.store.db.execute("SELECT * FROM native_sources WHERE id=?", (source["id"],)).fetchone()
            self.pending = None
            self.store.set_setting(state_key, {"retry_at": 0, "state": "active"})
            return worked
        except Cancelled:
            self.close()
            raise
        except (OSError, ValueError, TypeError, KeyError, RuntimeError, MemoryError, ImportError) as exc:
            self.close()
            failures = (source["failures"] if source is not None else status.get("failures", 0)) + 1
            delay = self.store.retry_delay(failures, isinstance(exc, (InvalidDownload, ValueError)))
            reason = concise_error(exc)
            if source is not None:
                self.store.db.execute("UPDATE native_sources SET failures=?,retry_at=?,error=? WHERE id=?", (failures, time.time() + delay, reason, source["id"]))
                self.store.commit()
                self.store.set_setting(state_key + "_last", source["id"])
            else:
                self.store.set_setting(state_key, {"failures": failures, "retry_at": time.time() + delay, "state": "retry", "reason": reason})
            self.emit("network", key="source_unavailable", corpus=self.repository, reason=reason, retry_seconds=delay, progress_retained=True)
            return False

class SourceScheduler:
    def __init__(self, store, emit):
        self.store, self.emit = store, emit

    def step(self, name, operation, cancel):
        check(cancel)
        key = "source_schedule_" + payload_digest(name)
        status = self.store.setting(key, {})
        if status.get("retry_at", 0) > time.time():
            return False
        try:
            result = operation()
            if status:
                self.store.set_setting(key, {})
            return result
        except Cancelled:
            raise
        except sqlite3.Error:
            raise
        except Exception as exc:
            attempts = status.get("attempts", 0) + 1
            delay = self.store.retry_delay(attempts)
            self.store.set_setting(key, {"attempts": attempts, "retry_at": time.time() + delay, "reason": concise_error(exc)})
            self.emit("network", key="source_unavailable", source=name, reason=concise_error(exc), retry_seconds=delay, progress_retained=True)
            return False

class PublicAudioWorker:
    def __init__(self, state, model, emit, shutdown):
        self.state, self.model, self.emit, self.shutdown = Path(state), model, emit, shutdown
        self.closing = threading.Event()
        self.restarts = 0
        self.failure = None
        self.paused = threading.Event()
        self.paused.set()
        self.interrupt = threading.Event()
        self.wake = threading.Event()
        self.idle = threading.Event()
        self.idle.set()
        self.lock = threading.Lock()
        self.thread = threading.Thread(target=self.run, daemon=True, name="YuanPublicAudio")
        self.thread.start()

    def pause(self):
        with self.lock:
            self.paused.set()
            self.interrupt.set()
            self.wake.set()

    def resume(self):
        with self.lock:
            if not self.shutdown.is_set():
                self.interrupt.clear()
                self.paused.clear()
                self.wake.set()

    def wait_idle(self, cancel):
        timeout = self.model.policy.number("runtime", "source_pause_seconds", max(5.0, self.model.chunk_seconds * 2), 0.1, 3600.0)
        deadline = time.monotonic() + timeout
        while not self.idle.wait(min(math.sqrt(tick()), max(0.0, deadline - time.monotonic()))):
            check(cancel)
            if time.monotonic() >= deadline:
                raise EngineFault("联网任务未按时让出资源 / Network worker did not yield its resources in time")

    def run(self):
        store = sources = importer = owned_importer = history = dialogues = acquisition = scheduler = None
        native_sources = []
        plan_signature = None
        source_turn = 0
        cancel = AnyCancel(self.shutdown, self.interrupt, self.closing)
        failures = 0
        base = self.model.policy.number("network", "worker_retry_seconds", max(0.1, self.model.chunk_seconds), tick(), 3600.0)
        ceiling = self.model.policy.number("network", "worker_retry_max_seconds", max(base, self.model.chunk_seconds * 8), base, 86400.0)
        try:
            while not self.shutdown.is_set() and not self.closing.is_set():
                with self.lock:
                    paused = self.paused.is_set()
                    if not paused:
                        self.idle.clear()
                if paused:
                    for job in native_sources:
                        job.close()
                    self.wake.wait(math.sqrt(tick()))
                    self.wake.clear()
                    continue
                began = time.monotonic()
                worked = False
                try:
                    check(cancel)
                    if store is None:
                        store = AudioStore(self.state, recover=False)
                        sources = PublicAudio(self.state, store, self.model, self.emit)
                        dialogues = PublicDialogue(self.state, store, self.model, self.emit)
                        importer = DatasetImporter(self.state, store, self.model, self.emit)
                        history = WorkspaceAudio(self.state, store, self.model, self.emit)
                        acquisition = AnnotatedAcquisition(self.state, store, self.model, self.emit)
                        native_sources = [PublishedSpeech(self.state, store, self.model, self.emit, item) for item in PublishedSpeech.specifications]
                        scheduler = SourceScheduler(store, self.emit)
                    owned_root = getattr(self.model, "owned_root", None)
                    if owned_root is not None and (owned_importer is None or owned_importer.root != safe_path(owned_root, "datasets")):
                        owned_importer = DatasetImporter(owned_root, store, self.model, self.emit, namespace="owned")
                    budget = StorageBudget(self.state).reclaim(store, cancel, self.model.capacity() * self.model.np.dtype(self.model.np.float32).itemsize * 2)
                    if budget["ready"]:
                        worked = owned_importer.step(cancel) if owned_importer is not None else False
                        if not worked:
                            worked = importer.step(cancel)
                        check(cancel)
                        worked = history.step(cancel) or worked
                        check(cancel)
                        acceptance = AcceptancePolicy(self.model)
                        report = acceptance.coverage(store, self.model)
                        tasks = acceptance.acquisition_plan(report)
                        acquisition.registry.plan(self.model, report, tasks)
                        acquisition.registry.preflight(self.model, (*native_sources, dialogues), cancel, self.emit)
                        plan = acquisition.registry.plan(self.model, report, tasks)
                        signature = payload_digest(plan)
                        if signature != plan_signature:
                            self.emit("data_plan", key="data_plan", tasks=plan, unsupported=[task for task in plan if task["automatic_source"] is None])
                            plan_signature = signature
                        worked = scheduler.step("annotated_catalog", lambda: acquisition.step(plan, cancel), cancel) or worked
                        jobs = SourceRegistry.order((*native_sources, dialogues, sources), plan, source_turn)
                        source_turn += 1
                        for job in jobs:
                            check(cancel)
                            name = getattr(job, "repository", type(job).__name__)
                            worked = scheduler.step(name, lambda job=job: acquisition.registry.run_source(self.model, job, plan, cancel), cancel) or worked
                        report = acceptance.coverage(store, self.model, fresh=True)
                        plan = acquisition.registry.plan(self.model, report, acceptance.acquisition_plan(report))
                        signature = payload_digest(plan)
                        if signature != plan_signature:
                            self.emit("data_plan", key="data_plan", tasks=plan, unsupported=[task for task in plan if task["automatic_source"] is None])
                            plan_signature = signature
                    else:
                        self.emit("network", key="learning_storage_pause", budget=budget)
                    failures = 0
                    self.failure = None
                except Cancelled:
                    for job in native_sources:
                        job.close()
                    self.emit("network", key="source_paused")
                except Exception as exc:
                    failures += 1
                    self.failure = concise_error(exc)
                    self.emit("network", key="offline", component="public_worker", reason=self.failure, attempt=failures,
                              retry_seconds=min(ceiling, base * min(failures, math.sqrt(ceiling / base)) ** 2))
                    if store is not None:
                        try:
                            store.close()
                        except (OSError, sqlite3.Error):
                            pass
                    for job in native_sources:
                        job.close()
                    native_sources = []
                    store = sources = importer = owned_importer = history = dialogues = acquisition = scheduler = None
                finally:
                    self.idle.set()
                measured = elapsed_seconds(began)
                delay = min(ceiling, base * min(failures, math.sqrt(ceiling / base)) ** 2) if failures else max(math.sqrt(self.model.chunk_seconds * measured), self.model.chunk_seconds if not worked else math.sqrt(tick()))
                cancel.wait(delay)
        finally:
            self.idle.set()
            for job in native_sources:
                job.close()
            if store is not None:
                try:
                    store.close()
                except (OSError, sqlite3.Error) as exc:
                    self.emit("notice", key="history_full", reason=concise_error(exc))

    def close(self, timeout):
        self.closing.set()
        self.pause()
        self.thread.join(timeout=max(0.0, timeout))
        return not self.thread.is_alive()


    def ensure_running(self):
        with self.lock:
            if self.shutdown.is_set() or self.closing.is_set() or self.thread.is_alive():
                return
            self.restarts += 1
            self.thread = threading.Thread(target=self.run, daemon=True, name="YuanPublicAudio")
            self.thread.start()
        self.emit("network", key="retry", component="public_worker_restart", restarts=self.restarts)

class CaptureSession:
    def __init__(self, devices, session_id, parent, emit, writer):
        self.writer = writer
        self.devices, self.model, self.session_id, self.parent, self.emit = devices, devices.model, session_id, parent, emit
        self.stop_event = threading.Event()
        self.wake = threading.Event()
        self.connected = False
        self.speaking = False
        self.trusted_speaking = False
        self.utterance_confirmed = False
        self.reply_epoch = 0
        self.utterance_id = None
        self.chunk_index = 0
        self.saved = self.consumed = 0
        self.packet_sequence = 0
        self.inference_dropped = 0
        self.failure = None
        self.inference = UtteranceQueue(self.model.capacity() * self.model.np.dtype(self.model.np.float32).itemsize,
                                         max(1, math.isqrt(self.model.capacity() // self.model.hop)))
        self.thread = threading.Thread(target=self.run, daemon=True, name="YuanCapture")
        self.devices.capture = self

    def start(self):
        self.thread.start()
        return self

    def is_set(self):
        return self.parent.is_set() or self.stop_event.is_set()

    def wait(self, timeout):
        return self.stop_event.wait(timeout) or self.parent.is_set()

    def next(self, store=None):
        while not self.is_set():
            self.writer.ensure_running()
            packet = self.inference.get(math.sqrt(tick()))
            if packet is not None:
                self.consumed += 1
                return packet
            if not self.thread.is_alive():
                if self.failure is not None:
                    raise self.failure
                raise YuanError("收音任务已停止 / Audio capture worker stopped")
        raise Cancelled()

    def cancel_input(self, reason):
        dropped = self.inference.cancel(reason)
        self.inference_dropped += len(dropped)
        if dropped:
            self.emit("notice", key=reason, id=self.session_id, samples=[item["id"] for item in dropped],
                      dropped=self.inference_dropped, whole_utterance=True)
        self.wake.set()

    def submit(self, processed, created, metadata):
        self.packet_sequence += 1
        metadata = {**metadata, "queued_at": time.monotonic()}
        processed.setflags(write=False)
        packet = {"id": uuid.uuid4().hex, "group_id": self.session_id, "role": "user", "waveform": processed, "rate": self.model.rate,
                  "count": len(processed), "created": created, "metadata": dict(metadata), "eligible": not metadata.get("playback_overlap") and not metadata.get("capture_gap"),
                  "sequence": self.packet_sequence}
        packet["storage_queued"] = self.writer.enqueue(packet)
        self.saved += int(packet["storage_queued"])
        if metadata.get("final") or metadata.get("capture_gap"):
            self.cancel_input("capture_gap" if metadata.get("capture_gap") else "capture_stopped")
        elif not self.is_set() and metadata.get("utterance_confirmed") is True:
            accepted, dropped = self.inference.put(packet, replace_oldest=True, preserve_utterance=True)
            self.inference_dropped += len(dropped) + int(not accepted)
            if dropped or not accepted:
                self.emit("notice", key="inference_superseded" if accepted else "input_incomplete", id=self.session_id,
                          utterance_id=metadata["utterance_id"], samples=[item["id"] for item in dropped],
                          rejected=None if accepted else packet["id"], dropped=self.inference_dropped, whole_utterance=True)
        self.wake.set()
        return packet

    def stop(self):
        self.stop_event.set()
        self.devices.cancel_playback()
        self.wake.set()
        self.inference.close()
        timeout = self.devices.timeout("capture_stop", max(10.0, self.model.chunk_seconds * 4))
        with operation(self.emit, "capture_stop", scope="audio", budget_seconds=timeout):
            self.thread.join(timeout=timeout)
            if self.thread.is_alive():
                self.failure = self.devices.driver.poison("收音结束超时，尾部音频未确认 / Capture stop timed out; trailing audio unconfirmed")
                self.emit("notice", key="capture_incomplete", id=self.session_id, reason=concise_error(self.failure))
                raise self.failure
            if self.devices.capture is self:
                self.devices.capture = None
            if self.failure is not None:
                raise self.failure
        return True

    def run(self):
        try:
            while not self.is_set():
                try:
                    self.devices.open_streams(self)
                    self.connected = True
                    self.emit("status", key="listening", id=self.session_id)
                    self.emit("audio", id=self.session_id, continuous=True)
                    self.emit("notice", key="echo_note")
                    self.collect()
                except Cancelled:
                    break
                except EngineFault:
                    raise
                except Exception as exc:
                    self.emit("status", key="capture_recover", id=self.session_id)
                    self.emit("notice", key="capture_recover", reason=concise_error(exc))
                finally:
                    self.connected = self.speaking = self.trusted_speaking = self.utterance_confirmed = False
                    self.cancel_input("capture_stopped" if self.is_set() else "capture_gap")
                    self.emit("audio", id=self.session_id, continuous=False, speech_active=False, level=0.0)
                    self.reply_epoch += 1
                    self.devices.abort()
                    self.devices.close_streams()
                    self.wake.set()
                if not self.is_set():
                    self.wait(self.devices.policy.reconnect_seconds if self.devices.policy else math.sqrt(self.model.chunk_seconds))
        except Exception as exc:
            self.failure = exc
            self.emit("notice", key="capture_incomplete", reason=concise_error(exc), id=self.session_id)
        finally:
            self.connected = self.speaking = self.trusted_speaking = False
            self.inference.close()
            self.emit("audio", id=self.session_id, continuous=False, level=0.0, recorded=0.0)
            self.emit("capture_stopped", key="capture_stopped" if self.failure is None else "capture_incomplete", id=self.session_id, tail_complete=self.failure is None)
            self.wake.set()

    def collect(self):
        import numpy as np
        devices, model, policy = self.devices, self.model, self.devices.policy
        self.utterance_confirmed = False
        resampler = AudioPreprocessor(devices.input_rate, model.rate)
        gate = SpeechGate(model.rate, policy.frame_size, model.chunk_seconds, policy.segment_seconds, policy.pause_seconds, policy.onset_seconds, policy.policy)
        echo = EchoSuppressor(model.rate, policy)
        pending = np.empty(0, dtype=np.float32)
        origin = None
        position = 0
        prior_output_faults = devices.output_faults
        overlap_until = -math.inf
        segment_overlap = False
        segment_gap = False
        quality_frames = deque(maxlen=gate.preroll.maxlen)
        segment_quality = []
        last_levels = 0.0
        segment_start = None
        def save(values, timestamp, final=False):
            nonlocal segment_overlap, segment_gap, segment_start, segment_quality
            if values is None or not len(values):
                if final:
                    self.cancel_input("capture_gap" if segment_gap else "capture_stopped")
                return
            processed = np.ascontiguousarray(values, dtype=np.float32)
            created = time.time() + timestamp - time.monotonic()
            overlapping = [item for item in segment_quality if item["overlap"]]
            capture_quality = {"protocol": "yuan-capture-quality-v1", "frames": len(segment_quality),
                               "overlap_frames": len(overlapping),
                               "reference_complete": bool(overlapping) and all(item["reference_complete"] for item in overlapping),
                               "residual_clean": bool(overlapping) and all(item["residual_clean"] for item in overlapping),
                               "user_speech": any(item["user_speech"] for item in segment_quality)}
            metadata = {"capture_quality": capture_quality, "utterance_confirmed": self.utterance_confirmed, "reply_epoch": self.reply_epoch, "utterance_id": self.utterance_id, "chunk_index": self.chunk_index,
                        "utterance_final": None if final else not gate.active, "playback_overlap": segment_overlap, "capture_gap": segment_gap, "limited": gate.limited, "final": final,
                        "last_voice_at": gate.last_voice_at, "endpoint_at": gate.ended_at if not gate.active else None,
                        "captured_at": time.monotonic()}
            self.submit(processed, created, metadata)
            self.chunk_index += 1
            segment_overlap = segment_gap = False
            segment_quality = []
            segment_start = None
        def consume(converted, final=False, interrupted=False):
            nonlocal pending, position, overlap_until, segment_overlap, segment_gap, segment_start, last_levels, segment_quality
            pending = np.concatenate((pending, converted))
            while len(pending) >= policy.frame_size or final and len(pending):
                take = min(len(pending), policy.frame_size)
                frame, pending = pending[:take], pending[take:]
                timestamp = origin + position / model.rate
                position += take
                if not np.isfinite(frame).all():
                    devices.input_faults += 1
                    devices.faults += 1
                    segment_gap = True
                    continue
                frame, overlap = echo.process(frame, timestamp, devices.reference)
                residual_clean = bool(echo.residual_correlation is not None and math.isfinite(echo.residual_correlation)
                                      and echo.residual_correlation < policy.echo_correlation and echo.reference_complete)
                quality = {"overlap": overlap, "reference_complete": echo.reference_complete,
                           "residual_clean": residual_clean, "user_speech": False}
                quality_frames.append(quality)
                if overlap:
                    overlap_until = timestamp + gate.preroll.maxlen * gate.frame_seconds
                before = gate.active
                result = gate.push(frame, timestamp)
                quality["user_speech"] = bool((before or gate.active or result is not None) and gate.noise_state == "speech"
                                              and (not overlap or echo.double_talk and residual_clean))
                if not before and (gate.active or result is not None):
                    self.utterance_id = uuid.uuid4().hex
                    self.chunk_index = 0
                    self.utterance_confirmed = False
                    segment_quality = list(quality_frames)
                    segment_start = timestamp + take / model.rate - (sum(len(value) for value in gate.frames) if result is None else len(result)) / model.rate
                if quality["user_speech"] and not self.utterance_confirmed:
                    self.reply_epoch += 1
                    if before:
                        self.utterance_id = uuid.uuid4().hex
                        self.chunk_index = 0
                    self.utterance_confirmed = True
                    self.cancel_input("inference_superseded")
                self.trusted_speaking = bool(gate.active and self.utterance_confirmed)
                if before:
                    segment_quality.append(quality)
                if before or gate.active or result is not None:
                    segment_overlap = segment_overlap or timestamp <= overlap_until
                self.speaking = gate.active
                if result is not None:
                    save(result, segment_start if segment_start is not None else timestamp - len(result) / model.rate, final=interrupted)
                    if gate.active:
                        segment_start = timestamp + take / model.rate
                    else:
                        self.utterance_confirmed = False
                now = time.monotonic()
                if now - last_levels >= math.sqrt(gate.frame_seconds):
                    last_levels = now
                    self.emit("audio", id=self.session_id, level=float(np.sqrt(np.mean(frame.astype(np.float64) ** 2))), probability=gate.confidence, noise_state=gate.noise_state, faults=devices.faults + devices.ring.overflows,
                              input_faults=devices.input_faults + devices.ring.overflows, output_faults=devices.output_faults, recorded=sum(len(value) for value in gate.frames) / model.rate, continuous=True, speech_active=gate.active, trusted_speech_active=self.trusted_speaking,
                              pending=self.inference.pending(), pending_storage=self.writer.queue.pending(), dropped_samples=devices.ring.dropped, echo_correlation=echo.correlation, echo_reduction=echo.reduction, echo_state=echo.reference_state, double_talk=echo.double_talk, echo_paths=len(echo.paths), playback_overlap=overlap)
        def ingest(raw, timestamp, gap):
            nonlocal resampler, gate, echo, pending, origin, position, segment_gap, segment_overlap, segment_start, overlap_until, quality_frames, segment_quality
            if gap:
                segment_gap = True
                if origin is not None:
                    consume(resampler.process(np.empty(0, dtype=np.float32), final=True), final=True, interrupted=True)
                    save(gate.flush(), segment_start if segment_start is not None else origin + position / model.rate, final=True)
                resampler = AudioPreprocessor(devices.input_rate, model.rate)
                gate = SpeechGate(model.rate, policy.frame_size, model.chunk_seconds, policy.segment_seconds, policy.pause_seconds, policy.onset_seconds, policy.policy)
                echo = EchoSuppressor(model.rate, policy)
                quality_frames = deque(maxlen=gate.preroll.maxlen)
                segment_quality = []
                pending = np.empty(0, dtype=np.float32)
                origin = None
                position = 0
                segment_gap = True
                segment_overlap = False
                segment_start = None
                overlap_until = -math.inf
                self.speaking = self.trusted_speaking = self.utterance_confirmed = False
                self.cancel_input("capture_gap")
                self.reply_epoch += 1
                self.emit("notice", key="capture_gap", faults=devices.input_faults + devices.ring.overflows, dropped_samples=devices.ring.dropped, discontinuities=devices.ring.discontinuities, timestamp=timestamp)
            if origin is None:
                origin = timestamp
            consume(resampler.process(raw))
        try:
            while not self.is_set():
                if not devices.callback_health():
                    raise YuanError("持续收音已中断 / Continuous capture was interrupted")
                if devices.output_faults != prior_output_faults:
                    prior_output_faults = devices.output_faults
                    self.emit("notice", key="playback_gap", id=self.session_id, output_faults=prior_output_faults)
                raw, timestamp, gap = devices.ring.read_block(max(1, math.ceil(policy.frame_size * devices.input_rate / model.rate)))
                if raw.size:
                    ingest(raw, timestamp, gap)
                else:
                    if not devices.active():
                        raise YuanError("收音流已中断 / Capture stream was interrupted")
                    self.wait(policy.frame_size / model.rate)
        finally:
            devices.abort()
            if devices.driver.failure is not None:
                raise devices.driver.failure
            while devices.ring.count:
                raw, timestamp, gap = devices.ring.read_block(max(1, math.ceil(policy.frame_size * devices.input_rate / model.rate)))
                if raw.size:
                    ingest(raw, timestamp, gap)
            if origin is not None:
                consume(resampler.process(np.empty(0, dtype=np.float32), final=True), final=True, interrupted=True)
                save(gate.flush(), segment_start if segment_start is not None else origin + position / model.rate, final=True)
            self.speaking = self.trusted_speaking = self.utterance_confirmed = False

def concise_error(exc):
    seen = set()
    values = []
    while exc is not None and id(exc) not in seen:
        seen.add(id(exc))
        value = str(exc).strip().replace("\x00", "")
        values.append(type(exc).__name__ + (": " + value if value else ""))
        exc = exc.__cause__ if exc.__cause__ is not None else (None if exc.__suppress_context__ else exc.__context__)
    return redact(" ← ".join(values))

class MemoryCalibration:
    protocol = "yuan-memory-relevance-v2"

    def __init__(self, model, store):
        self.model, self.store = model, store

    @classmethod
    def model_key(cls, model):
        return payload_digest([cls.protocol, model.serving_digest or model.active_digest or model.identity(), behavior_digest(), model.rate, model.hop, model.width])

    def selection(self, acceptance, cancel=None, splits=("validation", "guard")):
        splits = tuple(splits)
        if not splits or len(set(splits)) != len(splits) or any(split not in ("train", "validation", "guard") for split in splits):
            raise YuanError("检索监督数据划分无效 / Invalid retrieval supervision split")
        revisions = self.store.revisions()
        window = self.model.memory_window()
        version = (revisions["evaluation_revision"], revisions["training_revision"], window, self.model.rate, acceptance.digest)
        caches = getattr(self.store, "retrieval_selection_cache", {})
        cached = caches.get(splits) if isinstance(caches, dict) else None
        if cached is not None and cached[0] == version:
            return cached[1]
        selected = {split: {language: {True: {}, False: {}} for language in acceptance.languages} for split in splits}
        placeholders = ",".join("?" for split in splits)
        rows = self.store.db.execute("SELECT p.*,g.split,g.source_key FROM turn_pairs p JOIN groups g ON g.id=p.group_id WHERE g.split IN (" + placeholders + ") AND p.verified=1 AND p.eligible=1 AND json_extract(p.evidence,'$.retrieval.verified')=1 ORDER BY g.source_key,p.id", splits)
        for pair in rows:
            check(cancel)
            evidence = json.loads(pair["evidence"])
            language = evidence.get("language")
            annotation = evidence.get("retrieval", {})
            if language not in acceptance.languages or not isinstance(annotation, dict) or annotation.get("method") != "human_retrieval_relevance_v1":
                continue
            query = self.store.sample(pair["user_sample"])
            if (query is None or query["split"] != pair["split"] or query["audio_status"] != "ready" or query["generated"] or not query["dialogue_eligible"]
                    or query["count"] < 1 or query["rate"] <= 0 or query["count"] / query["rate"] > window / self.model.rate):
                continue
            examples = annotation.get("examples")
            if not isinstance(examples, list):
                continue
            for example in examples:
                if not isinstance(example, dict) or type(example.get("relevant")) is not bool:
                    continue
                relevant = example["relevant"]
                items = selected[pair["split"]][language][relevant]
                if len(items) >= acceptance.minimum or pair["source_key"] in items:
                    continue
                sample_id = example.get("sample")
                if not isinstance(sample_id, str):
                    continue
                candidate = self.store.sample(sample_id)
                start, end = example.get("start"), example.get("end")
                if (candidate is None or candidate["split"] != pair["split"] or candidate["audio_status"] != "ready" or candidate["generated"]
                        or not candidate["dialogue_eligible"] or candidate["id"] in (query["id"], pair["assistant_sample"])
                        or candidate["group_id"] == query["group_id"] and candidate["created"] >= query["created"]
                        or type(start) is not int or type(end) is not int or not 0 <= start < end <= candidate["count"]
                        or candidate["rate"] <= 0 or (end - start) / candidate["rate"] > window / self.model.rate):
                    continue
                items[pair["source_key"]] = (pair, query, candidate, example)
        coverage = [{"kind": "retrieval_supervision", "language": language, "split": split, "relevant": relevant,
                     "have": len(items), "need": 1 if split == "train" else acceptance.minimum}
                    for split, languages in selected.items() for language, labels in languages.items() for relevant, items in labels.items()]
        result = {"selected": selected, "coverage": coverage, "missing": [item for item in coverage if item["have"] < item["need"]]}
        if not isinstance(caches, dict):
            caches = {}
        caches[splits] = (version, result)
        self.store.retrieval_selection_cache = caches
        return result

    def status(self):
        row = self.store.db.execute("SELECT certificate FROM memory_calibrations WHERE model_key=?", (self.model_key(self.model),)).fetchone()
        if row is None:
            return {}
        try:
            value = json.loads(row[0])
        except (ValueError, TypeError):
            return {}
        return value if isinstance(value, dict) else {}

    def record(self, value, signature, cancel=None):
        check(cancel)
        key = value["model_key"]
        if key != self.model_key(self.model):
            return False
        encoded = json.dumps(value, ensure_ascii=False, allow_nan=False)
        with self.store.transaction():
            check(cancel)
            self.store.db.execute("INSERT INTO memory_calibrations(model_key,attempt,certificate,updated) VALUES(?,?,?,?) ON CONFLICT(model_key) DO UPDATE SET attempt=excluded.attempt,certificate=excluded.certificate,updated=excluded.updated", (key, signature, encoded, time.time()))
        return True

    def certificate(self):
        value = self.status()
        if not isinstance(value, dict) or value.get("protocol") != self.protocol:
            return {}
        expected = {"model_key": self.model_key(self.model), "evaluator_sha256": behavior_digest(), "acceptance_policy_sha256": AcceptancePolicy(self.model).digest}
        threshold = value.get("threshold")
        if (value.get("passed") is not True or any(value.get(key) != item for key, item in expected.items())
                or isinstance(threshold, bool) or not isinstance(threshold, (float, int)) or not math.isfinite(threshold)
                or value.get("sha256") != payload_digest({key: item for key, item in value.items() if key != "sha256"})
                or not self.store.snapshot_valid(value.get("evaluation_snapshot"))):
            return {}
        return value

    def refresh(self, cancel):
        acceptance = AcceptancePolicy(self.model)
        identity = {"model_key": self.model_key(self.model), "evaluator_sha256": behavior_digest(), "acceptance_policy_sha256": acceptance.digest}
        if self.certificate():
            return False
        data = self.selection(acceptance, cancel)
        selected = data["selected"]
        rows = [row for languages in selected.values() for labels in languages.values() for items in labels.values()
                for pair, query, candidate, example in items.values() for row in (pair, query, candidate)]
        snapshot = self.store.evaluation_snapshot(rows)
        signature = payload_digest([identity, snapshot["sha256"], data["coverage"]])
        previous = self.store.db.execute("SELECT attempt FROM memory_calibrations WHERE model_key=?", (identity["model_key"],)).fetchone()
        if previous is not None and previous[0] == signature:
            return False
        if data["missing"]:
            self.record({**identity, "protocol": self.protocol, "passed": False,
                         "reason": "independent_retrieval_labels_missing", "missing": data["missing"], "coverage": data["coverage"]}, signature, cancel)
            return False
        measurements, records = {split: {True: [], False: []} for split in selected}, []
        np = self.model.np
        for split, languages in selected.items():
            for language, labels in languages.items():
                for relevant, items in labels.items():
                    for source, (pair, query, candidate, example) in items.items():
                        check(cancel)
                        start, end = example["start"], example["end"]
                        vectors = []
                        for row, offset, count in ((query, 0, query["count"]), (candidate, start, end - start)):
                            values = self.store.read_audio(row, offset, count, cancel=cancel, verify=True)
                            if row["rate"] != self.model.rate:
                                values = self.model.normalize(values, row["rate"])
                            vectors.append(self.model.memory_vector(values, "assistant" if row["role"] == "assistant" else "user", cancel))
                        denominator = float(np.linalg.norm(vectors[0]) * np.linalg.norm(vectors[1]))
                        score = float(np.dot(vectors[0], vectors[1]) / denominator) if denominator > np.finfo(np.float32).eps else math.nan
                        if not math.isfinite(score):
                            self.record({**identity, "protocol": self.protocol, "passed": False,
                                         "reason": "invalid_retrieval_embedding", "coverage": data["coverage"]}, signature, cancel)
                            return False
                        measurements[split][relevant].append(score)
                        records.append({"source": source, "pair": pair["id"], "language": language, "query": query["id"], "query_sha256": query["digest"],
                                        "candidate": candidate["id"], "candidate_sha256": candidate["digest"], "start": start, "end": end,
                                        "relevant": relevant, "similarity": score, "split": split})
        threshold = max(measurements["validation"][False])
        passed = all(score > threshold for labels in measurements.values() for score in labels[True]) and all(score <= threshold for score in measurements["guard"][False])
        check(cancel)
        if not self.store.snapshot_valid(snapshot) or self.model_key(self.model) != identity["model_key"]:
            return False
        value = {**identity, "protocol": self.protocol, "passed": passed, "threshold": threshold, "records": records, "coverage": data["coverage"],
                 "evaluation_snapshot": snapshot, "scope": "independently_annotated_bilingual_historical_retrieval"}
        if not passed:
            value["reason"] = "retrieval_relevance_not_separated"
        value["sha256"] = payload_digest(value)
        return self.record(value, signature, cancel) and passed

def training_checkpoint_status(model, learner=None, verify=True, cancel=None):
    directory = safe_path(model.state, "learning")
    active = read_json(directory / "active.json")
    candidate = read_json(directory / "candidate.json")
    cache = getattr(model, "checkpoint_verifications", {})
    model.checkpoint_verifications = cache
    def verified(pointer, root, key):
        if type(pointer.get("steps")) is not int or pointer["steps"] < 0 or not is_digest(pointer.get("sha256")) or not isinstance(pointer.get("file"), str):
            return False
        try:
            path = safe_path(root, pointer["file"])
            info = path.stat()
            signature = (str(path), info.st_size, info.st_mtime_ns, info.st_ctime_ns, info.st_dev, info.st_ino, pointer["sha256"])
            if not path.is_file() or info.st_size <= 0:
                return False
            if cache.get(key) != signature:
                if not verify:
                    return False
                if digest_file(path, cancel) != pointer["sha256"]:
                    return False
                cache[key] = signature
            return True
        except (OSError, ValueError, TypeError, YuanError):
            return False
    valid = (candidate.get("identity") == model.identity() and candidate.get("base") == active.get("sha256")
             and (learner is None or candidate.get("training_revision") == learner.training_revision))
    manifest = candidate if valid and verified(candidate, directory, "candidate") else active
    persisted = verified(manifest, directory, "selected")
    saved = manifest["steps"] if persisted else 0
    completed = max(0, int(getattr(learner, "steps", getattr(model, "steps", saved))))
    verifier = getattr(model, "verifier", None)
    verifier_manifest = read_json(directory / "verifier/current.json")
    verifier_saved = verifier_manifest["steps"] if verified(verifier_manifest, directory / "verifier", "verifier") else 0
    return {"completed_steps": completed, "saved_steps": saved, "unsaved_steps": max(0, completed - saved),
            "checkpoint_digest": manifest.get("sha256") if persisted else None,
            "verifier_completed_steps": getattr(verifier, "steps", verifier_saved), "verifier_saved_steps": verifier_saved}

class LearningProcess:
    def __init__(self, state, model, emit, shutdown):
        self.state, self.model, self.emit, self.shutdown = Path(state), model, emit, shutdown
        self.lock = threading.RLock()
        self.wake, self.idle, self.closing = threading.Event(), threading.Event(), threading.Event()
        self.idle.set()
        self.process = None
        self.desired = False
        self.pause_requested = self.pause_deadline = self.close_deadline = None
        self.request_id = None
        self.phase = "idle"
        self.failure = None
        self.latest = {}
        self.operations = {}
        self.retry_at = 0.0
        self.failures = 0
        observed = model.policy.measured("learning_control", "pause_seconds", 0.0)
        base = max(5.0, model.chunk_seconds * 2, observed * 2)
        self.grace = model.policy.number("runtime", "training_pause_seconds", base, max(1.0, observed), max(base, model.capacity_seconds))
        self.pause_limit = model.policy.number("runtime", "training_pause_limit_seconds", max(self.grace * 4, model.capacity_seconds), self.grace, 3600.0)
        self.stall = model.policy.number("runtime", "training_progress_seconds", max(120.0, model.capacity_seconds), max(1.0, model.chunk_seconds), 86400.0)
        self.thread = threading.Thread(target=self.run, daemon=True, name="YuanLearningSupervisor")
        self.thread.start()

    def send_control(self, action, **values):
        if self.process is None or self.process.poll() is not None:
            return False
        try:
            self.process.stdin.write(json.dumps({"action": action, **values}, ensure_ascii=False) + "\n")
            self.process.stdin.flush()
            return True
        except (OSError, ValueError, BrokenPipeError):
            return False

    def pause(self):
        with self.lock:
            self.desired = False
            if self.process is not None and self.phase not in ("paused", "pausing", "closing"):
                self.pause_requested = time.monotonic()
                self.pause_deadline = self.pause_requested + self.grace
                self.request_id = uuid.uuid4().hex
                self.phase = "pausing"
                self.idle.clear()
                self.send_control("pause", request_id=self.request_id)
            self.wake.set()

    def resume(self):
        with self.lock:
            if not self.shutdown.is_set() and not self.closing.is_set() and self.failure is None:
                self.desired = True
                self.wake.set()

    def wait_idle(self, cancel):
        while not self.idle.wait(math.sqrt(tick())):
            check(cancel)
            self.ensure_running()
        check(cancel)
        self.ensure_running()

    def snapshot(self):
        with self.lock:
            return copy.deepcopy(self.latest)

    def receive(self, process):
        try:
            for line in process.stdout:
                if len(line) > 16 * 1024 * 1024:
                    continue
                try:
                    event = json.loads(line)
                except (ValueError, TypeError):
                    continue
                if not isinstance(event, dict):
                    continue
                kind = event.pop("type", None)
                for key in ("at", "_sequence", "attempt_id"):
                    event.pop(key, None)
                with self.lock:
                    if process is not self.process:
                        return
                    now = time.monotonic()
                    if kind == "paused_ack":
                        if self.phase != "pausing" or event.get("request_id") != self.request_id or event.get("resources_released") is not True:
                            continue
                        elapsed = now - self.pause_requested
                        self.model.policy.observe("learning_control", "pause_seconds", elapsed)
                        self.grace = min(self.pause_limit, max(self.grace, elapsed * 2))
                        self.latest.update(event, training_active=False, training_state="paused")
                        self.phase = "paused"
                        self.pause_requested = self.pause_deadline = None
                        self.operations.clear()
                        self.idle.set()
                        self.wake.set()
                    elif kind == "resumed_ack":
                        if self.phase != "resuming" or event.get("request_id") != self.request_id:
                            continue
                        self.phase = "running"
                        self.last_progress = now
                    elif kind == "pause_progress":
                        if self.phase == "pausing" and event.get("request_id") == self.request_id:
                            budget = event.get("budget_seconds", self.grace)
                            if type(budget) in (int, float) and math.isfinite(budget) and budget > 0:
                                self.pause_deadline = min(self.pause_requested + self.pause_limit, max(self.pause_deadline, now + budget))
                    elif kind == "learning_snapshot":
                        self.latest.update(event)
                        if "completed_steps" in event:
                            self.latest["completed_steps_confirmed"] = True
                        if self.phase == "starting":
                            self.phase = "running"
                        if self.phase in ("paused", "pausing", "closing"):
                            self.latest.update(training_active=False, training_state=self.phase)
                        self.last_progress = now
                        self.failures = 0
                    elif kind == "checkpoint_saved":
                        self.latest.update(saved_steps=event.get("steps"), checkpoint_digest=event.get("checkpoint_digest"))
                        self.last_progress = now
                    elif kind == "operation":
                        identifier = event.get("operation_id")
                        if event.get("replaceable") is True and event.get("scope") != "startup":
                            identifier = payload_digest([event.get("scope"), event.get("pid"), event.get("thread"), event.get("key")])
                        if event.get("outcome") == "begin" and identifier:
                            seconds = event.get("budget_seconds", self.stall)
                            if type(seconds) not in (int, float) or not math.isfinite(seconds) or seconds <= 0:
                                seconds = self.stall
                            self.operations[identifier] = now + min(seconds, self.stall)
                        elif event.get("outcome") in ("complete", "failed", "cancelled"):
                            self.operations.pop(identifier, None)
                            if event.get("outcome") == "complete":
                                self.last_progress = now
                if kind in ("learning_snapshot", "paused_ack", "resumed_ack"):
                    self.emit("learning", key="learn_yield" if kind == "paused_ack" else "native_learning", **event)
                elif kind == "error":
                    self.emit("notice", key="paused", component="isolated_learning", reason=event.get("reason"), checkpoint=self.snapshot())
                elif kind not in ("pause_progress", "operation", "model", "ready", "readiness", "pipeline", "exit", "status", "policy", "deployment", "condition", None):
                    event.update(scope="learning", component="isolated_learning")
                    self.emit(kind, **event)
        except (OSError, ValueError, EngineFault):
            pass

    def run(self):
        try:
            while True:
                with self.lock:
                    now = time.monotonic()
                    closing = self.shutdown.is_set() or self.closing.is_set()
                    if closing:
                        self.desired = False
                    process = self.process
                    if process is None and self.desired and now >= self.retry_at:
                        env = workspace_environment(self.state.parent)
                        env["YUAN_TRAINER"] = "1"
                        if self.model.owned_root is not None:
                            env["YUAN_TRAINING_OWNED_ROOT"] = str(self.model.owned_root)
                        process = spawn([sys.executable, "-B", str(Path(__file__).resolve()), "--learn", str(self.state)], env,
                                        stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL,
                                        text=True, encoding="utf-8", errors="replace", bufsize=1)
                        self.process = process
                        self.phase = "starting"
                        self.pause_requested = self.pause_deadline = None
                        self.last_progress = now
                        self.operations.clear()
                        self.idle.clear()
                        self.reader = threading.Thread(target=self.receive, args=(process,), daemon=True, name="YuanLearningEvents")
                        self.reader.start()
                    if process is not None:
                        if closing and self.phase != "closing":
                            self.phase = "closing"
                            self.close_deadline = self.close_deadline or now + self.grace
                            self.send_control("close", request_id=uuid.uuid4().hex)
                        elif not closing and not self.desired:
                            self.pause()
                        elif not closing and self.desired and self.phase == "paused":
                            self.request_id = uuid.uuid4().hex
                            self.phase = "resuming"
                            self.last_progress = now
                            self.idle.clear()
                            self.send_control("resume", request_id=self.request_id, owned_root=str(self.model.owned_root) if self.model.owned_root is not None else None)
                    phase = self.phase
                    stalled = process is not None and phase in ("starting", "running", "resuming") and (now - self.last_progress > self.stall or any(now >= deadline for deadline in self.operations.values()))
                    timed_out = phase == "pausing" and self.pause_deadline is not None and now >= self.pause_deadline
                    expired_close = closing and self.close_deadline is not None and now >= self.close_deadline
                if process is not None:
                    forced = process.poll() is None and (stalled or timed_out or expired_close)
                    if forced:
                        end_process(process, timeout=max(tick(), min(self.grace, math.sqrt(tick()))))
                        status = training_checkpoint_status(self.model)
                        completed = self.snapshot().get("completed_steps", self.snapshot().get("steps", status["saved_steps"]))
                        status.update(completed_steps=completed, unsaved_steps=max(0, completed - status["saved_steps"]), completed_steps_confirmed=False)
                        with self.lock:
                            self.latest.update(status)
                        self.emit("learning", key="learn_yield" if timed_out or expired_close else "paused", process_isolated=True,
                                  forced=True, training_state="terminated", checkpoint="last_atomic_checkpoint", **status)
                    code = process.poll()
                    if code is not None:
                        self.reader.join(timeout=self.grace)
                        for stream in (process.stdin, process.stdout):
                            try:
                                stream.close()
                            except (OSError, ValueError):
                                pass
                        with self.lock:
                            self.process = None
                            self.pause_requested = self.pause_deadline = None
                            self.phase = "idle"
                            self.latest.update(training_active=False, training_state="terminated" if forced else "exited")
                            self.operations.clear()
                            self.idle.set()
                            if not closing:
                                self.failures += 1
                                self.retry_at = time.monotonic() + min(self.stall, max(self.grace, self.model.chunk_seconds) * self.failures ** 2)
                        if not closing:
                            self.emit("learning", key="paused", exit_code=code, process_isolated=True, checkpoint=training_checkpoint_status(self.model))
                if closing and self.process is None:
                    return
                self.wake.wait(math.sqrt(tick()))
                self.wake.clear()
        except BaseException as exc:
            self.failure = exc
            process = self.process
            if process is not None:
                try:
                    end_process(process, timeout=self.grace)
                finally:
                    if process.poll() is not None:
                        self.process = None
                        self.idle.set()

    def close(self, timeout):
        with self.lock:
            self.close_deadline = time.monotonic() + max(0.0, timeout)
            self.closing.set()
            self.desired = False
            self.wake.set()
        self.thread.join(timeout=max(0.0, timeout) + math.sqrt(tick()))
        return not self.thread.is_alive() and self.process is None

    def ensure_running(self):
        if self.failure is not None:
            raise EngineFault("训练进程监督器失败，保留当前服务模型 / Learning supervisor failed; current serving model is retained", code="learning_supervisor_failed") from self.failure

class LearningSession:
    def __init__(self, state, emit, cancel):
        self.state, self.emit, self.cancel = Path(state), emit, cancel
        self.paused, self.wake = threading.Event(), threading.Event()
        self.control_lock = threading.RLock()
        self.request_id = None
        self.resume_values = {}
        self.persistence_interrupt = threading.Event()

    def control(self):
        try:
            for line in sys.stdin:
                try:
                    action = json.loads(line)
                except (ValueError, TypeError):
                    continue
                if not isinstance(action, dict):
                    continue
                with self.control_lock:
                    command = action.get("action")
                    if command == "close":
                        break
                    if command == "pause":
                        self.request_id = action.get("request_id")
                        self.paused.set()
                    elif command == "resume":
                        self.resume_values = action
                        self.persistence_interrupt.set()
                        self.request_id = action.get("request_id")
                        self.paused.clear()
                    self.wake.set()
        finally:
            self.cancel.set()
            self.wake.set()

    def hold(self, model, learner, sources):
        began = time.monotonic()
        destination = model.device
        with self.control_lock:
            if not self.paused.is_set():
                return
            request_id = self.request_id
            self.persistence_interrupt.clear()
        def progress(stage):
            baseline = max(5.0, model.chunk_seconds * 2, model.policy.measured("learning_control", stage + "_seconds", 0.0) * 2)
            self.emit("pause_progress", request_id=request_id, stage=stage, budget_seconds=baseline)
        progress("sources")
        sources.pause()
        sources.wait_idle(self.cancel)
        progress("offload")
        offload_at = time.monotonic()
        model.training_placement(model.torch.device("cpu"), learner)
        model.policy.observe("learning_control", "offload_seconds", elapsed_seconds(offload_at))
        model.policy.observe("learning_control", "pause_seconds", elapsed_seconds(began))
        self.emit("paused_ack", request_id=request_id, training_active=False, training_state="paused", resources_released=True,
                  process_isolated=True, pid=os.getpid(), pause_seconds=elapsed_seconds(began), persistence_state="pending",
                  **training_checkpoint_status(model, learner, verify=False))
        saved_at = time.monotonic()
        persistence_cancel = AnyCancel(self.cancel, self.persistence_interrupt)
        state, failure = "saved", None
        status = None
        try:
            learner.checkpoint(persistence_cancel, force=True)
            model.verifier.checkpoint(persistence_cancel)
            check(persistence_cancel)
            status = training_checkpoint_status(model, learner, cancel=persistence_cancel)
            model.policy.save()
        except Cancelled:
            state = "deferred"
        except Exception as exc:
            state, failure = "failed", concise_error(exc)
            self.emit("notice", key="checkpoint_failure", reason=failure, in_memory_progress_retained=True,
                      **training_checkpoint_status(model, learner, verify=False))
        model.policy.observe("learning_control", "checkpoint_seconds", elapsed_seconds(saved_at))
        self.emit("learning_snapshot", training_active=False, training_state="paused", persistence_state=state,
                  checkpoint_error=failure, **(status or training_checkpoint_status(model, learner, verify=False)))
        while self.paused.is_set() and not self.cancel.is_set():
            self.wake.wait(math.sqrt(tick()))
            self.wake.clear()
        if self.cancel.is_set():
            return
        with self.control_lock:
            values = dict(self.resume_values)
        model.training_placement(destination, learner)
        supplied = values.get("owned_root")
        if "owned_root" in values:
            model.owned_root = None if supplied is None else safe_path(self.state, Path(supplied).resolve().relative_to(self.state.resolve()).as_posix())
        active = read_json(safe_path(self.state, "learning/active.json"))
        if active.get("sha256") != model.active_digest:
            with model.interruptible(self.cancel):
                model.restore()
            learner._discard_candidate()
        learner._refresh_data()
        if learner.candidate is not None and training_checkpoint_status(model, learner)["saved_steps"] < learner.steps:
            learner.dirty = True
        model.refresh_release()
        self.emit("resumed_ack", request_id=values.get("request_id"), training_state="running", device=str(model.device), pid=os.getpid(), **training_checkpoint_status(model, learner))
        if not self.paused.is_set():
            sources.resume()

    def run(self):
        threading.Thread(target=self.control, daemon=True, name="YuanLearningControl").start()
        model = learner = store = sources = None
        try:
            supervisor = StageSupervisor(self.state, self.emit)
            deps = {name: import_runtime_module(name, self.state, self.emit, self.cancel, supervisor, {}) for name in ("numpy", "psutil", "torch")}
            owned = os.environ.get("YUAN_TRAINING_OWNED_ROOT")
            model = NativeAudio(self.state, self.cancel, self.emit, owned_root=owned, dependencies=deps)
            store = AudioStore(self.state, recover=False)
            learner = AudioLearner(model, store, self.emit)
            model.verifier = SpeechVerifier(model, store, self.emit)
            helper = Engine(self.state, self.emit, self.cancel)
            helper.model, helper.store, helper.learner = model, store, learner
            sources = PublicAudioWorker(self.state, model, self.emit, self.cancel)
            self.emit("learning_snapshot", steps=model.steps, accepted=model.accepted, training_active=False, training_state="preflight", process_isolated=True)
            if not self.paused.is_set():
                sources.resume()
            failures = 0
            while not self.cancel.is_set():
                if self.paused.is_set():
                    self.hold(model, learner, sources)
                    continue
                work_cancel = AnyCancel(self.cancel, self.paused)
                began = time.monotonic()
                try:
                    with model.interruptible(work_cancel):
                        sources.ensure_running()
                        learner._resume_activation(work_cancel)
                        required = model.capacity() * model.np.dtype(model.np.float32).itemsize * 2
                        space = StorageBudget(self.state).snapshot(required)
                        worked = False
                        state = "waiting_data"
                        if not space["ready"]:
                            sources.pause()
                            sources.wait_idle(work_cancel)
                            model._prune_models()
                            model._prune_evaluations(work_cancel)
                            space = StorageBudget(self.state).reclaim(store, work_cancel, required)
                        if space["ready"]:
                            sources.resume()
                            store.recheck_audio(work_cancel)
                            model.refresh_release()
                            worked = helper.index_memory(work_cancel)
                            memory = model.training_budget(learner)
                            if memory["ready"]:
                                pending = (FinalAcceptance.current(model, store, AcceptancePolicy(model))
                                           if model.dialogue_trained and model.verifier.ready(work_cancel) else None)
                                frozen = pending is not None and pending["status"] in ("reserved", "evaluating")
                                if frozen:
                                    state = "verifying"
                                else:
                                    try:
                                        worked = model.verifier.step(work_cancel) or worked
                                    except Cancelled:
                                        raise
                                    except (OSError, ValueError, RuntimeError, MemoryError) as exc:
                                        self.emit("notice", key="semantic_evidence_missing", reason=concise_error(exc))
                                    allowed = learner._select()[1] is not None
                                    if allowed:
                                        state = "training"
                                        self.emit("learning_snapshot", steps=learner.steps, accepted=model.accepted, training_active=True, training_state=state, process_isolated=True)
                                        worked = learner.step(work_cancel) or worked
                                    else:
                                        state = "bootstrap_blocked"
                                    model.calibrate(work_cancel)
                                worked = model.prepare_review(store, work_cancel) or worked
                                worked = model.automatic_review(store, work_cancel) or worked
                            else:
                                state = "resource_paused"
                                self.emit("learning", key="memory_pause", budget=memory, **learner._state())
                        else:
                            state = "storage_paused"
                        learner.checkpoint(work_cancel)
                        model.verifier.checkpoint(work_cancel)
                        model.policy.save()
                        self.emit("learning_snapshot", steps=learner.steps, accepted=model.accepted, acoustic_ready=model.acoustic_ready,
                                  dialogue_trained=model.dialogue_trained, active_digest=model.active_digest, curriculum=(model.training_manifest or {}).get("curriculum", {}),
                                  automatic_release=getattr(model, "automatic_release_state", None), training_active=False, training_state=state,
                                  process_isolated=True, iteration_seconds=time.monotonic() - began, **training_checkpoint_status(model, learner))
                        failures = 0
                        work_cancel.wait(0.0 if worked else model.chunk_seconds)
                except Cancelled:
                    if self.cancel.is_set():
                        break
                except Exception as exc:
                    failures += 1
                    self.emit("learning", key="paused", reason=concise_error(exc), **learner._state())
                    if isinstance(exc, MemoryError) or "out of memory" in str(exc).casefold():
                        model.recover_training_memory(learner)
                    work_cancel.wait(max(model.chunk_seconds, time.monotonic() - began) * math.sqrt(failures))
        except Cancelled:
            pass
        finally:
            self.cancel.set()
            if sources is not None:
                sources.close(max(5.0, model.chunk_seconds * 2))
            if learner is not None:
                try:
                    learner.checkpoint(None, force=True)
                    model.verifier.checkpoint(None)
                    model.policy.save()
                    self.emit("learning_snapshot", training_active=False, training_state="closed", **training_checkpoint_status(model, learner))
                except Exception as exc:
                    self.emit("notice", key="checkpoint_failure", reason=concise_error(exc), **training_checkpoint_status(model, learner))
            if store is not None:
                store.close()


def learning_entry(state):
    with runtime_entry(state) as (emit, cancel):
        try:
            with WorkspaceLease(Path(state) / "training.lock"):
                LearningSession(state, emit, cancel).run()
        except Exception as exc:
            emit("error", key="failure", reason=concise_error(exc), fatal=True, fault=fault_event(exc))

class Engine:
    def __init__(self, state, emit, shutdown=None):
        self.state, self.emit = Path(state), emit
        self.shutdown = shutdown if shutdown is not None else threading.Event()
        self.interrupt = threading.Event()
        self.requests = queue.Queue()
        self.devices = None
        self.session_id = None
        self.language = "中文"
        self.store = None
        self.model = None
        self.last_metrics = 0.0
        self.metrics_period = 1.0
        self.command_lock = threading.Lock()
        self.closed_sessions = set()
        self.cached_samples = {}
        self.resource_thread = None
        self.policy_save_requested = threading.Event()
        self.writer = self.sources = None
        self.runtime_ready = self.pipeline_ready = self.audio_ready = False
        self.learner_ready = False
        self.next_audio_probe = 0.0
        self.audio_signature = self.audio_failure = self.last_readiness = None

    def receive(self):
        try:
            while not self.shutdown.is_set():
                line = sys.stdin.readline()
                if not line:
                    break
                try:
                    action = json.loads(line)
                except (ValueError, TypeError):
                    continue
                if not isinstance(action, dict):
                    continue
                command = action.get("action")
                if command not in ("start", "stop", "close", "language", "import_pair", "import_dataset", "review_open", "review_play", "review_submit", "review_close", "export_release"):
                    continue
                if command in ("import_pair", "import_dataset", "review_open", "review_play", "review_submit", "review_close", "export_release") and self.session_id is not None:
                    self.emit("notice", key="learn_yield")
                    continue
                with self.command_lock:
                    if command == "language":
                        self.language = "English" if action.get("language") == "English" else "中文"
                        continue
                    if command == "stop":
                        self.closed_sessions.add(str(action.get("id", "")))
                    received_at = time.monotonic()
                    action["_received_at"] = received_at
                    if not self.interrupt.is_set():
                        self.interrupt_requested_at = received_at
                    self.interrupt.set()
                    if self.sources:
                        self.sources.pause()
                    if command == "close":
                        self.shutdown.set()
                    if self.devices:
                        self.devices.cancel_playback()
                    try:
                        self.requests.put_nowait(action)
                    except queue.Full:
                        self.shutdown.set()
        finally:
            self.shutdown.set()
            self.interrupt.set()
            if self.devices:
                self.devices.cancel_playback()

    def stats(self, force=False):
        import psutil
        now = time.monotonic()
        if threading.current_thread() is threading.main_thread() and self.store:
            self.cached_samples = self.store.stats()
        if not force and now - self.last_metrics < self.metrics_period:
            return
        self.last_metrics = now
        limits = available_resources(psutil)
        disk = shutil.disk_usage(self.state)
        try:
            ram_used, process_ram, cpu = psutil.virtual_memory().used, psutil.Process().memory_info().rss, psutil.cpu_percent()
        except (OSError, NotImplementedError, psutil.Error):
            ram_used = process_ram = cpu = None
        values = {"cpu": cpu, "cpu_limit": limits["cpus"], "ram_used": ram_used, "ram_available": limits["memory"], "process_ram": process_ram,
                  "disk_free": disk.free, "disk_total": disk.total, "samples": self.cached_samples,
                  "storage_budget": getattr(self, "storage_budget", {}),
                  "capture": {"id": None, "continuous": False, "speech_active": False, "pending": 0}}
        if self.devices and self.devices.capture:
            capture = self.devices.capture
            values["capture"] = {"id": capture.session_id, "continuous": capture.connected, "speech_active": capture.speaking, "trusted_speech_active": capture.trusted_speaking, "pending": capture.inference.pending(), "pending_storage": capture.writer.queue.pending()}
        if self.devices:
            values["audio_clocks"] = {key: {"source": "hardware" if row["hardware"] else "sample_count", "arrival": row["arrival"]}
                                      for key, row in getattr(self.devices, "clock_states", {}).copy().items()}
        if self.writer:
            values["storage"] = self.writer.status()
        if self.model and self.model.device.type == "cuda":
            try:
                free, total = self.model.torch.cuda.mem_get_info()
                values.update(gpu_used=total - free, gpu_total=total)
            except RuntimeError:
                pass
        self.emit("metrics", **values)

    def persist_policy(self, force=False):
        if self.model is None or not (force or self.policy_save_requested.is_set()):
            return True
        self.policy_save_requested.clear()
        try:
            self.model.policy.save()
            return True
        except Exception as exc:
            self.policy_save_requested.set()
            self.emit("notice", key="checkpoint_failure", component="adaptive_policy", reason=concise_error(exc))
            return False

    def resource_loop(self):
        failure = None
        while not self.shutdown.wait(max(math.sqrt(tick()), min(1.0, self.metrics_period))):
            try:
                self.persist_policy()
                self.stats(True)
                if failure:
                    self.emit("notice", key="recovered", component="resources")
                failure = None
            except Exception as exc:
                reason = concise_error(exc)
                if reason != failure:
                    self.emit("notice", key="resource_failure", reason=reason)
                failure = reason

    @supervised('memory_recall', 'conversation')
    def _memory_context(self, waveform, session_id, cancel):
        np = self.model.np
        key = MemoryCalibration.model_key(self.model)
        certificate = MemoryCalibration(self.model, self.store).certificate()
        if not certificate or self.store.setting("serving_memory_key") != key:
            self.emit("memory_matches", key="memory_recall", id=session_id, count=0, samples=0, scanned=0,
                      model_key=key, calibrated=bool(certificate), index_ready=False, context_selected=False)
            return []
        threshold = certificate["threshold"]
        total = self.store.indexed_memory_count(key)
        budget = self.model.context_budget(len(waveform))
        if not total or budget < self.model.hop:
            return []
        pool = self.model.policy.integer("memory", "candidate_pool", max(1, math.isqrt(total)), 1, max(1, total))
        dimensions = max(1, self.model.width)
        bytes_per_candidate = dimensions * np.dtype(np.float32).itemsize
        budget_bytes = self.model.policy.integer("memory", "search_bytes", max(bytes_per_candidate, self.model.model_bytes), bytes_per_candidate, max(bytes_per_candidate, self.model.model_bytes * 2))
        pool = min(pool, max(1, budget_bytes // bytes_per_candidate))
        search_limit = min(total, max(pool, pool * max(1, math.isqrt(pool))))
        recall = self.model.policy.integer("memory", "recall_count", max(1, math.isqrt(pool)), 1, pool)
        query = self.model.memory_vector(waveform, "user", cancel)
        query_norm = float(np.linalg.norm(query))
        if not math.isfinite(query_norm) or query_norm <= np.finfo(np.float32).eps:
            return []
        key = MemoryCalibration.model_key(self.model)
        scored = []
        scanned = 0
        for row in self.store.memory_candidates(session_id, key, query, search_limit, cancel):
            check(cancel)
            scanned += 1
            try:
                dimensions = int(row["dims"])
                if dimensions != len(query) or len(row["vector"]) != dimensions * np.dtype(np.float32).itemsize:
                    continue
                vector = np.frombuffer(row["vector"], dtype=np.float32, count=dimensions)
                if not np.isfinite(vector).all():
                    continue
                denominator = query_norm * float(np.linalg.norm(vector))
                if not math.isfinite(denominator) or denominator <= np.finfo(np.float32).eps:
                    continue
                similarity = float(np.dot(query, vector) / denominator)
                if not math.isfinite(similarity) or similarity <= threshold:
                    continue
                item = (similarity, (row["id"], row["memory_start"], row["memory_end"]), row)
                if len(scored) < pool:
                    heapq.heappush(scored, item)
                elif item[:2] > scored[0][:2]:
                    heapq.heapreplace(scored, item)
            except (ValueError, TypeError, OverflowError):
                continue
        intervals = {}
        for similarity, identifier, row in sorted(scored, key=lambda item: (-item[0], item[1])):
            entries = intervals.setdefault(row["id"], [])
            entries.append((row["memory_start"], row["memory_end"], similarity, row))
        merged = []
        for entries in intervals.values():
            for start, end, similarity, row in sorted(entries, key=lambda item: item[0]):
                if merged and merged[-1][3]["id"] == row["id"] and start <= merged[-1][1]:
                    left = merged.pop()
                    merged.append((left[0], max(left[1], end), max(left[2], similarity), row))
                else:
                    merged.append((start, end, similarity, row))
        retained = []
        for start, end, similarity, row in sorted(merged, key=lambda item: (-item[2], item[3]["id"], item[0])):
            check(cancel)
            if len(retained) >= recall or budget < self.model.hop:
                break
            count = min(end - start, int(budget * int(row["rate"]) / self.model.rate))
            if count <= 0:
                continue
            try:
                values = self.store.read_audio(row, start, count, cancel=cancel)
                if row["rate"] != self.model.rate:
                    values = self.model.normalize(values, int(row["rate"]))
                values = values[:budget]
                if len(values) < self.model.hop:
                    continue
                retained.append((row["created"] + start / row["rate"], (row["id"], start, start + count), "assistant" if row["role"] == "assistant" else "user", values, similarity))
                budget -= len(values)
            except Cancelled:
                raise
            except (OSError, RuntimeError, ValueError, sqlite3.Error) as exc:
                self.emit("notice", key="sample_skipped", component="memory_recall", sample=row["id"], reason=concise_error(exc), degraded=True)
        retained.sort(key=lambda item: (item[0], item[1]))
        if retained:
            self.emit("memory_matches", key="memory_recall", id=session_id, count=len(retained), samples=sum(len(item[3]) for item in retained),
                      best=max(item[4] for item in retained), scanned=scanned, context_selected=False, search_mode=self.store.memory_search_mode,
                      intervals=[{"sample": item[1][0], "start": item[1][1], "end": item[1][2]} for item in retained], calibration_sha256=certificate["sha256"])
        return [(item[2], item[3]) for item in retained]

    def activate_memory_index(self, key, cancel):
        check(cancel)
        if key != MemoryCalibration.model_key(self.model):
            return False
        certificate = MemoryCalibration(self.model, self.store).certificate()
        if not certificate:
            return False
        with self.store.transaction():
            check(cancel)
            if self.store.memory_index_pending(key):
                return False
            missing = self.store.db.execute("SELECT 1 FROM memories m WHERE m.model_key=? AND NOT EXISTS(SELECT 1 FROM memory_buckets b WHERE b.sample_id=m.sample_id AND b.model_key=m.model_key AND b.start=m.start AND b.end=m.end) LIMIT 1", (key,)).fetchone()
            if missing is not None or key != MemoryCalibration.model_key(self.model) or not self.store.snapshot_valid(certificate.get("evaluation_snapshot")):
                return False
            previous = self.store.setting("serving_memory_key")
            if previous == key:
                if self.store.setting("building_memory_key") == key:
                    self.store.set_setting("building_memory_key", None)
                return False
            if previous:
                self.store.set_setting("previous_memory_key", previous)
            self.store.set_setting("serving_memory_key", key)
            self.store.set_setting("building_memory_key", None)
            self.store.prune_memory_versions(cancel)
        self.emit("learning_memory", model_key=key, previous_model_key=previous, index_ready=True,
                  indexed_count=self.store.indexed_memory_count(key), calibration_sha256=certificate["sha256"])
        return True

    @supervised('memory_encoding', 'learning')
    def index_memory(self, cancel):
        if not self.model.playback_ready:
            return False
        key = MemoryCalibration.model_key(self.model)
        previous = self.store.setting("serving_memory_key")
        building = key if previous != key else None
        if self.store.setting("building_memory_key") != building:
            with self.store.transaction():
                self.store.set_setting("building_memory_key", building)
                self.store.prune_memory_versions(cancel)
        try:
            MemoryCalibration(self.model, self.store).refresh(cancel)
        except Cancelled:
            raise
        except (OSError, RuntimeError, ValueError, KeyError) as exc:
            self.emit("notice", key="sample_skipped", component="memory_calibration", reason=concise_error(exc), audio_preserved=True)
        if getattr(self.store, "memory_index_repair", False) and self.store.repair_memory_index(key, cancel):
            return True
        row = self.store.db.execute("SELECT s.*,COALESCE(m.next_start,0) AS memory_cursor FROM samples s JOIN groups g ON g.id=s.group_id JOIN sessions x ON x.id=s.group_id LEFT JOIN memory_progress m ON m.sample_id=s.id AND m.model_key=? WHERE g.origin='local' AND x.ended IS NOT NULL AND s.audio_status='ready' AND s.memory_eligible=1 AND s.count>1 AND COALESCE(m.next_start,0)<s.count AND COALESCE(m.retry_at,0)<=? ORDER BY s.created,s.id LIMIT 1", (key, time.time())).fetchone()
        if row is None:
            repaired = self.store.repair_memory_index(key, cancel)
            return repaired or self.activate_memory_index(key, cancel)
        check(cancel)
        start = row["memory_cursor"]
        take = min(row["count"] - start, max(1, int(self.model.window() * row["rate"] / self.model.rate)))
        try:
            values = self.store.read_audio(row, start, take, cancel=cancel)
            if row["rate"] != self.model.rate:
                values = self.model.normalize(values, int(row["rate"]))
            vector = self.model.memory_vector(values, "assistant" if row["role"] == "assistant" else "user", cancel)
            return self.store.save_memory_vector(row["id"], key, vector, start, start + take)
        except Cancelled:
            raise
        except sqlite3.Error as exc:
            self.store.memory_index_repair = True
            self.emit("notice", component="memory_index", reason=concise_error(exc), audio_preserved=True)
            return False
        except (OSError, RuntimeError, ValueError) as exc:
            current = self.store.db.execute("SELECT failures FROM memory_progress WHERE sample_id=? AND model_key=?", (row["id"], key)).fetchone()
            failures = (current[0] if current else 0) + 1
            retry_at = time.time() + self.store.retry_delay(failures)
            self.store.db.execute("INSERT INTO memory_progress(sample_id,model_key,next_start,failures,retry_at) VALUES(?,?,?,?,?) ON CONFLICT(sample_id,model_key) DO UPDATE SET failures=excluded.failures,retry_at=excluded.retry_at", (row["id"], key, start, failures, retry_at))
            self.store.commit()
            self.emit("notice", key="sample_skipped", component="memory_encoding", sample=row["id"], reason=concise_error(exc), retry_at=retry_at, audio_preserved=True)
            return False

    def check_pipeline(self):
        import numpy as np
        count = self.model.hop * max(4, self.model.layers + 1)
        generator = np.random.default_rng(int(self.model.identity()[:16], 16))
        amplitude = np.finfo(np.float32).eps ** 0.25
        waveform = generator.normal(0.0, amplitude, count).astype(np.float32)
        output = self.model.respond_audio(tr("default_prompt", self.language), [], waveform, self.shutdown, max_samples=count)
        if not output.size or not np.isfinite(output).all():
            raise YuanError("端到端音频链路验证失败 / End-to-end audio pipeline validation failed")
        config = {key: getattr(self.model, key) for key in ("rate", "hop", "width", "layers")}
        identity = payload_digest([build_digest(), str(self.model.device), str(self.model.torch.__version__), config])
        certificate = read_json(self.state / "training-components.json")
        if certificate.get("identity") != identity or certificate.get("training_components_verified") is not True:
            components = probe_training_components(self.model.torch, np, self.state, self.model.policy, self.model.device, config, self.shutdown, self.emit)
            atomic_json(self.state / "training-components.json", {"identity": identity, **components}, self.shutdown)
            compute = read_json(self.state / "compute-verified.json")
            if compute.get("build_sha256") == build_digest():
                for row in compute.get("devices", []):
                    if row.get("device") == str(self.model.device):
                        row.update(components)
                atomic_json(self.state / "compute-verified.json", compute, self.shutdown)
        self.emit("pipeline", verified=True, training_components_verified=True, conversation_verified=self.model.dialogue_ready, path="ordered prompt + processed audio → Yuan audio encoder → latent dialogue core → Yuan audio decoder → autoregressive waveform",
                  transcription=False, text_to_speech=False, external_model=False, playback=self.model.playback_ready)

    def readiness(self, force=False):
        audio_ready = bool(self.audio_ready and self.devices is not None and self.devices.driver.failure is None)
        values = {"runtime_ready": self.runtime_ready, "pipeline_ready": self.pipeline_ready, "audio_ready": audio_ready,
                  "model_ready": bool(self.model and self.model.service_ready()),
                  "storage_ready": bool(self.writer and self.writer.status()["healthy"])}
        values["learning_ready"] = bool(self.runtime_ready and self.pipeline_ready and self.model is not None and self.store is not None and self.learner_ready)
        values["conversation_ready"] = can_converse(values) and values["storage_ready"]
        values["blockers"] = [key for key in ("runtime_ready", "pipeline_ready", "audio_ready", "model_ready", "storage_ready") if not values[key]]
        values["capability"] = self.model.capability() if self.model else "cold_start"
        values["capability_evidence"] = getattr(self.model, "capability_evidence", {})
        values["evidence_scope"] = getattr(self.model, "release_scope", None)
        values["learning"] = self.learning_state()
        values["model_blocker"] = None if values["model_ready"] else "release_invalid" if self.model and self.model.release_failure else "release_wait" if self.model and self.model.dialogue_trained else "native_learning"
        missing = values["learning"].get("missing", [])
        if not values["model_ready"] and values["model_blocker"] != "release_invalid":
            if any(row.get("split") == "train" for row in missing):
                values["model_blocker"] = "dialogue_data_missing"
            elif missing:
                values["model_blocker"] = "acceptance_data_missing"
            elif values["learning"].get("reference_missing") and not (self.model and self.model.serving_network is not None):
                values["model_blocker"] = "reference_data_missing"
            elif values["capability"] == "annotated_tasks_only":
                values["model_blocker"] = "annotated_tasks_only"
            elif values["learning"].get("dialogue_missing"):
                values["model_blocker"] = "dialogue_benchmark_missing"
            elif values["learning"].get("automatic_release") == "semantic_evidence_missing":
                values["model_blocker"] = "semantic_evidence_missing"
        values["data_source_state"] = values["learning"].get("source_state", {})
        values["bootstrap"] = values["learning"].get("bootstrap", {})
        values["bootstrap_phase"] = values["bootstrap"].get("phase", "initializing")
        values["missing_source_tasks"] = values["bootstrap"].get("missing_task_count", 0)
        values["unvalidated_import_tasks"] = values["bootstrap"].get("unvalidated_import_count", 0)
        values["model_detail"] = self.model.release_failure if self.model else None
        if not values["model_ready"] and values["data_source_state"].get("blocked"):
            values["data_blocker"] = values["model_blocker"]
            if values["model_blocker"] not in ("release_invalid", "annotated_tasks_only"):
                values["model_blocker"] = "data_sources_exhausted"
            values["model_detail"] = "独立多轮录音或标注覆盖不足，正在按来源退避重试 / Independent multi-turn recordings or annotations remain insufficient; sources will be retried"
        values["delivery_source"] = str(self.model.owned_root) if self.model and self.model.owned_root else None
        values["model_requires_action"] = False
        values["automatic_model_recovery"] = bool(not values["model_ready"] and values["learning_ready"])
        values["automatic_learning"] = bool(values["learning_ready"] and values["learning"].get("trainable_data") and self.session_id is None)
        values["training_active"] = values["learning"].get("training_active", False)
        values["automatic_release"] = values["learning"].get("automatic_release")
        values["serving_model"] = self.model.serving_digest if self.model else None
        values["learning_model"] = self.model.active_digest if self.model else None
        if force or values != self.last_readiness:
            self.last_readiness = dict(values)
            self.emit("readiness", **values)
        return values

    def refresh_delivery(self, cancel):
        descriptor, source, embedded = release_source(self.state)
        if source is None:
            return False
        marker = payload_digest(source)
        now = time.monotonic()
        if marker == getattr(self, "delivery_marker", None):
            return False
        if marker == getattr(self, "delivery_failure_marker", None) and now < getattr(self, "delivery_retry_at", 0.0):
            return False
        current = read_json(safe_path(self.state, "owned-release.json"), {})
        if source.get("sha256") == current.get("bundle_sha256"):
            self.delivery_marker = marker
            return False
        self.sources.pause()
        self.sources.wait_idle(cancel)
        fields = ("owned_root", "serving_network", "serving_digest", "serving_manifest", "release_root", "dialogue_ready", "playback_ready",
                  "release_signature", "release_files", "release_cases", "release_failure", "release_scope", "release_calibration", "capability_evidence")
        saved = {key: getattr(self.model, key) for key in fields if hasattr(self.model, key)}
        committed = False
        try:
            installer = OwnedReleaseInstaller(self.state, self.emit)
            root = installer.prepare(cancel)
            if root is None:
                return False
            supplied = checked_json(safe_path(root, "learning/model.json"))
            if any(supplied.get(key) != getattr(self.model, key) for key in ("rate", "hop", "width", "layers")):
                self.delivery_marker = marker
                self.emit("notice", key="release_restart_required")
                return False
            self.model.owned_root = root
            if not self.model._load_review(safe_path(root, "learning/release.json"), state=root, announce=False):
                raise YuanError("新交付未通过独立验收 / New delivery did not pass independent acceptance")
            installer.activate(root, self.model, cancel)
            committed = True
            self.delivery_marker = marker
            self.delivery_failures = 0
            self.delivery_retry_at = 0.0
            self.model.record_serving()
            local_release = safe_path(self.state, "learning/release.json")
            if local_release.exists():
                atomic_json(safe_path(self.state, "learning/previous-release.json"), checked_json(local_release), cancel)
                local_release.unlink()
            learner = getattr(self, "learner", None)
            if learner is not None:
                learner._discard_candidate()
            self.model.network = copy.deepcopy(self.model.serving_network).eval().requires_grad_(False)
            self.model.steps = int(self.model.serving_manifest["steps"])
            self.model.accepted = int(self.model.serving_manifest.get("accepted", 0))
            self.model.training_manifest = self.model.serving_manifest
            self.model._persist(self.model.network, self.model.serving_manifest.get("metrics", {}), cancel, increment=False, task="dialogue")
            return True
        except Cancelled:
            if not committed:
                for key, value in saved.items():
                    setattr(self.model, key, value)
            raise
        except Exception as exc:
            if not committed:
                for key, value in saved.items():
                    setattr(self.model, key, value)
                self.delivery_failure_marker = marker
                self.delivery_failures = getattr(self, "delivery_failures", 0) + 1
                self.delivery_retry_at = now + self.store.retry_delay(self.delivery_failures)
            self.emit("notice", key="release_invalid" if not committed else "checkpoint_failure", candidate=not committed,
                      serving_preserved=bool(self.model.playback_ready), reason=concise_error(exc))
            return committed

    def probe_audio(self, cancel, force=False):
        now = time.monotonic()
        interval = self.model.policy.number("audio", "probe_interval_seconds", max(5.0, self.model.chunk_seconds * 2), 1.0, 3600.0)
        if not force and now < self.next_audio_probe:
            return self.audio_ready
        self.next_audio_probe = now + interval
        import sounddevice as sd
        try:
            check(cancel)
            if self.devices is not None and self.devices.driver.failure is not None:
                if not self.devices.driver.close(0):
                    raise YuanError("音频驱动尚未释放，学习继续 / Audio driver is still busy; learning continues")
                self.devices = None
            if self.devices is None:
                self.devices = AudioDevices(self.model, self.emit)
            indices, devices = self.devices.probe()
            signature = [(index, device["name"], device["default_samplerate"], device["selected_channels"]) for index, device in zip(indices, devices)]
            if force or not self.audio_ready or signature != self.audio_signature:
                self.devices.preflight(cancel)
            self.audio_signature = signature
            self.audio_ready = True
            self.audio_failure = None
        except Cancelled:
            raise
        except (OSError, RuntimeError, ValueError, sd.PortAudioError) as exc:
            self.audio_ready = False
            reason = concise_error(exc)
            if reason != self.audio_failure:
                self.emit("notice", key="mic_missing", reason=reason, learning_blocked=False)
            self.audio_failure = reason
        return self.audio_ready

    def conversation(self, action):
        session_id = str(action.get("id", ""))
        if not session_id or session_id in self.closed_sessions:
            self.emit("ended", id=session_id)
            return
        if not self.readiness()["conversation_ready"]:
            self.emit("notice", key="start_rejected", id=session_id, blockers=self.readiness()["blockers"])
            self.emit("ended", id=session_id)
            return
        self.model.review_held = None
        self.language = "English" if action.get("language") == "English" else "中文"
        prompt = str(action.get("prompt", "")).strip() or tr("default_prompt", self.language)
        history = deque()
        utterance = None
        def retain(role, values, metadata=None):
            metadata = dict(metadata or {})
            if not len(values) or AudioStore.context_reason(metadata, generated=role == "assistant"):
                return
            history.append((NativeAudio.context_role(role, metadata), values))
            budget = self.model.capacity() // 2
            total = sum(len(item[1]) for item in history)
            removed = max(0, total - budget)
            while total > budget and history:
                old_role, old_values = history.popleft()
                take = min(len(old_values), total - budget)
                total -= take
                if take < len(old_values):
                    history.appendleft((old_role, old_values[take:]))
            if removed:
                self.emit("context_budget", key="context_trimmed", id=session_id, kept_samples=total, dropped_samples=removed, budget_samples=budget)
        turns = 0
        started = time.monotonic()
        capture = None
        registered = False
        try:
            if self.sources:
                self.sources.pause()
            self.probe_audio(self.interrupt)
            if not self.readiness()["conversation_ready"]:
                self.emit("notice", key="start_rejected", id=session_id, blockers=self.readiness()["blockers"])
                return
            check(self.interrupt)
            self.store.session(session_id, prompt, self.language)
            self.store.group(session_id, "local")
            registered = True
            self.session_id = session_id
            self.model.input_budget = max(self.model.hop * 2, self.model.capacity() // 2)
            capture = CaptureSession(self.devices, session_id, self.interrupt, self.emit, self.writer)
            self.emit("started", id=session_id, mode="dialogue", model=self.model.serving_digest, continuous=False,
                      acoustic_ready=self.model.acoustic_ready, dialogue_ready=True, playback_ready=True, reply_ready=False,
                      training_state="pausing")
            capture.start()
            self.emit("status", key="preparing_reply", id=session_id, reply_ready=False)
            if self.sources:
                self.sources.wait_idle(self.interrupt)
            self.record_yield(self.model, action.get("_received_at"))
            check(self.interrupt)
            self.emit("status", key="listening", id=session_id, reply_ready=True, training_state="paused")
            while not self.shutdown.is_set():
                check(self.interrupt)
                row = capture.next()
                if row.get("event") == "utterance_cancelled":
                    metadata = row["metadata"]
                    if utterance is not None and utterance["id"] == metadata["utterance_id"]:
                        utterance = None
                    self.emit("input_state", key=metadata["reason"], id=session_id, utterance_id=metadata["utterance_id"],
                              incomplete=True, cancelled=True)
                    continue
                dequeued_at = time.monotonic()
                processed = row["waveform"]
                if row["rate"] != self.model.rate or processed.ndim != 1 or len(processed) != row["count"] or not self.model.np.isfinite(processed).all():
                    self.emit("notice", key="capture_gap", sample=row["id"], reason="音频内存片段无效 / Invalid in-memory audio segment")
                    continue
                metadata = row["metadata"]
                epoch = int(metadata["reply_epoch"])
                input_cancel = ReplyCancel(self.interrupt, capture, epoch, allow_speaking=True)
                identifier = metadata["utterance_id"]
                if input_cancel.is_set():
                    if utterance is not None and utterance["id"] == identifier:
                        utterance = None
                    retain("user", processed, metadata)
                    self.emit("input_state", key="inference_superseded", id=session_id, utterance_id=identifier, chunk_index=metadata["chunk_index"])
                    continue
                if utterance is None or utterance["id"] != identifier:
                    utterance = {"id": identifier, "hidden": None, "next": 0, "samples": 0, "energy": 0.0, "incomplete": False, "started": time.monotonic(), "recall_seconds": 0.0, "encoding_seconds": 0.0}
                utterance["incomplete"] = utterance["incomplete"] or metadata["chunk_index"] != utterance["next"] or metadata.get("capture_gap", False)
                utterance["next"] = metadata["chunk_index"] + 1
                utterance["samples"] += len(processed)
                utterance["energy"] += float(self.model.np.dot(processed.astype(self.model.np.float64), processed.astype(self.model.np.float64)))
                if not utterance["incomplete"]:
                    try:
                        recalled = []
                        if utterance["hidden"] is None:
                            try:
                                recall_began = time.monotonic()
                                recalled = self._memory_context(processed, session_id, input_cancel)
                                utterance["recall_seconds"] += time.monotonic() - recall_began
                            except Cancelled:
                                raise
                            except (OSError, RuntimeError, ValueError, sqlite3.Error) as exc:
                                self.emit("notice", component="memory_recall", reason=concise_error(exc), degraded=True)
                        encoding_began = time.monotonic()
                        utterance["hidden"] = self.model.encode_input(prompt, list(history), processed, input_cancel, hidden=utterance["hidden"],
                                                                     final=metadata["utterance_final"], recalled=recalled, context_id=session_id)
                        utterance["encoding_seconds"] += time.monotonic() - encoding_began
                    except Cancelled:
                        retain("user", processed, metadata)
                        continue
                    except Exception as exc:
                        utterance["incomplete"] = True
                        self.emit("notice", key="input_incomplete", component="utterance_encoder", reason=concise_error(exc), id=session_id, utterance_id=identifier)
                self.emit("input_state", id=session_id, utterance_id=identifier, chunk_index=metadata["chunk_index"], utterance_final=metadata["utterance_final"],
                          input_samples=utterance["samples"], incomplete=utterance["incomplete"], reply_epoch=epoch)
                if not metadata["utterance_final"]:
                    retain("user", processed, metadata)
                    continue
                if utterance["incomplete"]:
                    retain("user", processed, metadata)
                    self.emit("notice", key="input_incomplete", id=session_id, utterance_id=identifier, input_samples=utterance["samples"])
                    utterance = None
                    continue
                reply_cancel = ReplyCancel(self.interrupt, capture, epoch)
                began = time.monotonic()
                heard = None
                output_sample = None
                latency = None
                timings = {"clock": "monotonic", "last_voice_at": metadata.get("last_voice_at"), "endpoint_at": metadata.get("endpoint_at"),
                           "dequeued_at": dequeued_at, "generation_started_at": began, "recall_seconds": utterance["recall_seconds"],
                           "encoding_seconds": utterance["encoding_seconds"]}
                endpoint, captured = metadata.get("endpoint_at"), metadata.get("queued_at", metadata.get("captured_at"))
                if isinstance(captured, (int, float)) and math.isfinite(captured):
                    timings["queue_seconds"] = max(0.0, dequeued_at - captured)
                if isinstance(endpoint, (int, float)) and isinstance(metadata.get("last_voice_at"), (int, float)):
                    timings["endpoint_wait_seconds"] = max(0.0, endpoint - metadata["last_voice_at"])
                mode = "superseded"
                playback_started = None
                playback_quality = {}
                try:
                    if not reply_cancel.is_set():
                        mode = "dialogue"
                        self.emit("status", key="thinking", id=session_id)
                        output = self.model.stream_audio(prompt, (), processed, reply_cancel, hidden=utterance["hidden"],
                                                         reference_rms=math.sqrt(utterance["energy"] / max(1, utterance["samples"])))
                        playback_started = time.time()
                        result = self.devices.play_stream(output, self.model.output_rate, reply_cancel)
                        heard, interrupted = result.waveform, result.interrupted
                        playback_quality = result.metadata()
                        actual_start = result.started_at
                        if actual_start is not None:
                            timings["first_played_at"] = actual_start
                            timings["generation_to_playback_seconds"] = max(0.0, actual_start - began)
                            voice_at = metadata.get("last_voice_at")
                            if isinstance(voice_at, (int, float)) and math.isfinite(voice_at) and voice_at <= actual_start:
                                latency = actual_start - voice_at
                                self.model.policy.observe("audio", "response_latency_seconds", latency)
                            playback_started = time.time() + actual_start - time.monotonic()
                        if result.error is not None:
                            mode = "failed"
                        elif interrupted:
                            mode = "interrupted"
                            self.emit("notice", key="barge_in", sample=row["id"])
                except Cancelled:
                    mode = "interrupted"
                    if not self.interrupt.is_set():
                        self.emit("notice", key="barge_in", sample=row["id"])
                except Exception as exc:
                    mode = "failed"
                    self.emit("notice", reason=concise_error(exc), component="reply", input_sample=row["id"])
                    if isinstance(exc, MemoryError) or "out of memory" in str(exc).lower():
                        self.model.capacity_scale /= math.sqrt(2)
                        self.model.input_budget = max(self.model.hop * 2, self.model.capacity() // 2)
                        import gc
                        gc.collect()
                        if self.model.torch.cuda.is_available():
                            self.model.torch.cuda.empty_cache()
                finally:
                    retain("user", processed, metadata)
                    if heard is not None and len(heard):
                        heard = self.model.np.ascontiguousarray(heard, dtype=self.model.np.float32)
                        heard.setflags(write=False)
                        playback_quality["interrupted"] = bool(playback_quality.get("interrupted") or mode in ("interrupted", "failed"))
                        playback_quality["actually_played"] = True
                        playback_quality["context_complete"] = not playback_quality["interrupted"]
                        retain("assistant", heard, playback_quality)
                        output_sample = uuid.uuid4().hex
                        packet = {"id": output_sample, "group_id": session_id, "role": "assistant", "waveform": heard,
                                  "rate": self.model.output_rate, "created": playback_started, "eligible": False,
                                  "metadata": {"input_sample": row["id"], "input_utterance": identifier, "input_chunks": utterance["next"], "model": self.model.serving_digest, **playback_quality}}
                        if not self.writer.enqueue(packet):
                            output_sample = None
                    turns += 1
                    self.emit("turn", id=session_id, turns=turns, latency=latency, timings=timings, input_seconds=utterance["samples"] / self.model.rate, utterance_id=identifier, input_chunks=utterance["next"],
                              output_seconds=len(heard) / self.model.output_rate if heard is not None else 0.0, elapsed=time.monotonic() - started,
                              mode=mode, input_sample=row["id"], output_sample=output_sample, model=self.model.serving_digest, playback=playback_quality,
                              pending=capture.inference.pending(), pending_storage=self.writer.queue.pending(), continuous=capture.connected)
                    utterance = None
                    if capture.connected and not self.interrupt.is_set():
                        self.emit("status", key="listening", id=session_id)
                    self.policy_save_requested.set()
                    self.stats(True)
        except Cancelled:
            pass
        except EngineFault:
            raise
        except Exception as exc:
            if not self.interrupt.is_set():
                self.emit("notice", reason=concise_error(exc), component="conversation")
        finally:
            cleanup_failure = self.devices.driver.failure
            try:
                if capture is not None:
                    capture.stop()
                self.devices.abort()
                self.devices.close_streams()
            except Exception as exc:
                cleanup_failure = exc
                self.emit("notice", key="capture_incomplete", id=session_id, reason=concise_error(exc))
            timeout = self.model.policy.number("audio", "storage_flush_seconds", max(5.0, self.model.chunk_seconds * 2), 0.1, 3600.0)
            result = FlushResult(ok=False, pending=0)
            if self.writer:
                result = self.writer.flush_session(session_id, timeout)
                self.emit("storage_state", **self.writer.status())
                if not result:
                    self.emit("notice", key="storage_flush", **dict(result))
            if registered:
                try:
                    self.store.end_session(session_id)
                except (OSError, sqlite3.Error) as exc:
                    cleanup_failure = cleanup_failure or exc
                    self.emit("notice", reason=concise_error(exc))
            self.model.input_budget = None
            history.clear()
            self.session_id = None
            self.persist_policy(force=True)
            complete = bool(result) and cleanup_failure is None
            self.emit("ended", id=session_id, turns=turns, storage_complete=complete, capture_complete=cleanup_failure is None, storage=dict(result))
            self.readiness(True)
            self.stats(True)
            if cleanup_failure is not None:
                raise EngineFault("会话结束未完成，重启音频引擎 / Session cleanup incomplete; restarting audio engine") from cleanup_failure

    def run(self):
        receiver = threading.Thread(target=self.receive, daemon=True, name="YuanControl")
        receiver.start()
        model = None
        learner = None
        try:
            owned_release_preflight(self.state, self.emit)
            dependencies = load_runtime_modules(self.state, self.emit, self.shutdown)
            psutil = dependencies["psutil"]
            self.metrics_period = math.sqrt(available_resources(psutil)["cpus"])
            startup_preflight(self.state, emit=self.emit)
            self.runtime_ready = True
            with operation(self.emit, "stage_owned_release"):
                owned_root = OwnedReleaseInstaller(self.state, self.emit).prepare(self.shutdown)
            with operation(self.emit, "stage_store"):
                self.store = AudioStore(self.state)
            self.language = self.store.setting("language", "中文")
            settings = read_json(self.state / "settings.json")
            if settings.get("language") in ("中文", "English"):
                self.language = settings["language"]
            self.stats(True)
            self.resource_thread = threading.Thread(target=self.resource_loop, daemon=True)
            self.resource_thread.start()
            self.emit("status", key="loading")
            model = NativeAudio(self.state, self.shutdown, self.emit, owned_root=owned_root, dependencies=dependencies)
            self.model = model
            if owned_root is not None and model.playback_ready:
                OwnedReleaseInstaller(self.state, self.emit).activate(owned_root, model, self.shutdown)
            self.emit("status", key="checking")
            with operation(self.emit, "stage_pipeline"):
                try:
                    self.model.calibrate(self.shutdown)
                    self.check_pipeline()
                except RuntimeError as exc:
                    raise YuanFault("加速链路验证需要修复 / Accelerator pipeline validation needs repair", category="compatibility", code="compute_backend_failed", device=str(model.device)) from exc
            self.pipeline_ready = True
            with operation(self.emit, "stage_learning"):
                learner = AudioLearner(model, self.store, self.emit)
                self.learner = learner
                model.verifier = SpeechVerifier(model, self.store, self.emit)
                self.writer = AudioWriter(model, self.emit)
                self.sources = LearningProcess(self.state, model, self.emit, self.shutdown)
                self.learner_ready = True
            self.probe_audio(self.shutdown, force=True)
            self.emit("ready", runtime_ready=True, capability=model.capability(), conversation_verified=model.dialogue_ready,
                      acoustic_ready=model.acoustic_ready, dialogue_trained=model.dialogue_trained, dialogue_ready=model.dialogue_ready, playback_ready=model.playback_ready)
            self.readiness(True)
            self.stats(True)
            while not self.shutdown.is_set():
                self.writer.ensure_running()
                self.sources.ensure_running()
                action = None
                with self.command_lock:
                    try:
                        action = self.requests.get_nowait()
                    except queue.Empty:
                        pass
                    if self.requests.empty() and not self.shutdown.is_set():
                        self.interrupt.clear()
                if action:
                    self.sources.pause()
                    if action["action"] not in ("close", "start"):
                        try:
                            self.sources.wait_idle(self.interrupt)
                        except Cancelled:
                            self.emit("ended", id=str(action.get("id", "")))
                            continue
                    if action["action"] != "start":
                        self.record_yield(model, action.get("_received_at"))
                    if action["action"] == "close":
                        break
                    if action["action"] == "start":
                        if self.interrupt.is_set():
                            self.emit("ended", id=str(action.get("id", "")))
                        else:
                            self.conversation(action)
                        continue
                    if action["action"] == "stop":
                        self.closed_sessions.discard(str(action.get("id", "")))
                        self.emit("ended", id=str(action.get("id", "")))
                        continue
                    if action["action"] in ("import_pair", "import_dataset", "review_open", "review_play", "review_submit", "review_close", "export_release"):
                        try:
                            self.sources.pause()
                            self.sources.wait_idle(self.interrupt)
                            with model.interruptible(self.interrupt):
                                model.restore()
                            learner._discard_candidate()
                            model.verifier = SpeechVerifier(model, self.store, self.emit)
                            self.learning_action(action, self.interrupt)
                        except Cancelled:
                            pass
                        except EngineFault:
                            raise
                        except Exception as exc:
                            self.emit("notice", key="dataset_rejected" if action["action"] == "import_pair" else "release_invalid", reason=concise_error(exc))
                        self.readiness(True)
                        continue
                try:
                    snapshot = self.sources.snapshot()
                    for key in ("steps", "accepted", "acoustic_ready", "dialogue_trained", "active_digest"):
                        if key in snapshot:
                            setattr(model, key, snapshot[key])
                    if snapshot.get("curriculum"):
                        model.training_manifest = {**(model.training_manifest or {}), "curriculum": snapshot["curriculum"]}
                    self.training_active = snapshot.get("training_active", False)
                    self.training_state = snapshot.get("training_state", "waiting_data")
                    if snapshot.get("automatic_release") is not None:
                        model.automatic_release_state = snapshot["automatic_release"]
                    self.store.set_setting("language", self.language)
                    self.refresh_delivery(self.interrupt)
                    pointer = read_json(safe_path(self.state, "learning/release.json"))
                    signature = payload_digest(pointer)
                    if signature != getattr(self, "isolated_release_signature", None):
                        self.sources.pause()
                        self.sources.wait_idle(self.interrupt)
                        with model.interruptible(self.interrupt):
                            model.refresh_release()
                        self.isolated_release_signature = signature
                    self.probe_audio(self.interrupt)
                    self.readiness()
                    self.stats(True)
                    with self.command_lock:
                        if self.requests.empty() and not self.interrupt.is_set() and not self.shutdown.is_set():
                            self.sources.resume()
                    self.interrupt.wait(max(math.sqrt(tick()), min(self.metrics_period, model.chunk_seconds)))
                except EngineFault:
                    raise
                except Cancelled:
                    self.sources.pause()
                    self.training_active = False
                    self.training_state = "yielded"
                except Exception as exc:
                    self.emit("notice", key="paused", component="serving_control", reason=concise_error(exc))
                    self.interrupt.wait(model.chunk_seconds)
        except Cancelled:
            pass
        except BaseException as exc:
            self.emit("error", key="failure", reason=concise_error(exc), fatal=True, fault=fault_event(exc))
        finally:
            self.shutdown.set()
            self.interrupt.set()
            if self.devices:
                try:
                    self.devices.abort()
                    self.devices.close_streams()
                except Exception as exc:
                    self.emit("notice", key="capture_incomplete", reason=concise_error(exc))
                self.devices.driver.close(math.sqrt(tick()))
            timeout = model.policy.number("runtime", "shutdown_grace_seconds", max(5.0, model.chunk_seconds * 2), 1.0, 3600.0) if model else self.metrics_period
            if self.sources and not self.sources.close(timeout):
                self.emit("notice", key="source_paused", reason="联网任务正在退出 / Network worker is shutting down")
            if self.writer:
                self.writer.close(timeout)
            if self.resource_thread:
                self.resource_thread.join(timeout=max(1.0, self.metrics_period))
            self.persist_policy(force=True)
            if self.store:
                try:
                    self.store.close()
                except (OSError, sqlite3.Error) as exc:
                    self.emit("notice", reason=concise_error(exc))
            self.emit("exit")

    def record_yield(self, model, requested):
        if requested is None or requested <= getattr(self, "last_yield_request", 0.0):
            return
        self.last_yield_request = requested
        elapsed = max(0.0, time.monotonic() - requested)
        target = CooperativeCompute(model, "learning").target()
        model.policy.observe("learning", "yield_seconds", elapsed)
        model.policy.observe("learning", "yield_over_budget", float(elapsed > target))
        model.adapt_execution()
        self.emit("learning", key="learn_yield", yield_seconds=elapsed, yield_target_seconds=target,
                  within_target=elapsed <= target, process_isolated=isinstance(self.sources, LearningProcess),
                  training_process_reaped=bool(isinstance(self.sources, LearningProcess) and self.sources.idle.is_set()), hard_deadline_guaranteed=False)

    def learning_state(self):
        if self.model is None or self.store is None:
            return {"missing": [], "sources": {}, "review_pending": False, "training_active": False}
        report = AcceptancePolicy(self.model).coverage(self.store, self.model)
        pointer = read_json(safe_path(self.state, "learning/pending-review.json"))
        serving = read_json(safe_path(self.state, "serving-state.json"), {})
        trainable = self.store.next_pair("train", self.model.hop, self.model.hop) is not None or self.store.next_sample("train", self.model.hop * 2) is not None
        return {"new_data": self.store.stats(), "candidate_improvements": self.model.accepted, "serving_versions": serving.get("versions", 0),
                "missing": report["missing"], "sources": report["sources"], "coverage": report["cells"], "data_gaps": report["data_gaps"],
                "acquisition_plan": AcceptancePolicy(self.model).acquisition_plan(report), "acquisition_state": self.store.setting("acquisition_summary", {}),
                "source_state": self.store.setting("source_coverage_state", {}),
                "bootstrap": self.store.setting("bootstrap_state", {}),
                "memory_calibration": {key: value for key, value in MemoryCalibration(self.model, self.store).status().items()
                                       if key in ("model_key", "passed", "reason", "coverage", "missing", "scope")},
                "memory_index": {"serving_model_key": self.store.setting("serving_memory_key"),
                                 "building_model_key": self.store.setting("building_memory_key"),
                                 "previous_model_key": self.store.setting("previous_memory_key"),
                                 "current_model_key": MemoryCalibration.model_key(self.model),
                                 "indexed_count": self.store.indexed_memory_count(MemoryCalibration.model_key(self.model))},
                "reference_missing": report["reference_missing"], "reference_ready": report["reference_ready"],
                "dialogue_missing": report["dialogue_missing"], "dialogue_reference_ready": report["dialogue_reference_ready"],
                "review_pending": bool(pointer.get("review_file")), "review_model": pointer.get("model_sha256"),
                "dialogue_trained": self.model.dialogue_trained, "serving_model": self.model.serving_digest,
                "active_model": self.model.active_digest, "candidate_isolated": bool(self.model.active_digest and self.model.active_digest != self.model.serving_digest),
                "trainable_data": trainable, "training_active": bool(getattr(self, "training_active", False)),
                "training_state": getattr(self, "training_state", "waiting_data"),
                "validation_ready": all(report["selected"][split] for split in ("validation", "guard")),
                "automatic_release": getattr(self.model, "automatic_release_state", "no_accepted_baseline")}

    @supervised('learning_action', 'learning')
    def learning_action(self, action, cancel):
        if os.environ.get("YUAN_PUBLISHER") != "1":
            raise YuanError("训练标注与人工验收仅供开发端使用 / Training annotation and manual acceptance are publisher-only operations")
        command = action["action"]
        if command == "export_release":
            OwnedReleaseInstaller(self.state, self.emit).export(self.model, cancel)
            return
        if command == "import_pair":
            return self.import_pair(action, cancel)
        if command == "import_dataset":
            return self.import_dataset(action, cancel)
        if command == "review_close":
            self.model.review_held = None
            return
        directory = safe_path(self.state, "learning")
        pointer = read_json(directory / "pending-review.json")
        if not pointer.get("review_file"):
            self.model.review_held = None
            self.emit("notice", key="review_missing")
            return
        path = safe_path(directory, pointer["review_file"])
        draft = checked_json(path)
        evaluation_path = safe_path(directory, draft["evaluation_file"])
        checksum = digest_file(evaluation_path, cancel)
        if checksum != draft.get("evaluation_sha256"):
            raise YuanError(tr("review_stale", self.language))
        evaluation = checked_json(evaluation_path)
        if command == "review_open":
            self.model.review_held = pointer.get("model_sha256")
            self.emit("review_snapshot", evaluation=evaluation, review=draft, evaluation_sha256=checksum)
            return
        if action.get("evaluation_sha256") != checksum:
            raise YuanError(tr("review_stale", self.language))
        if command == "review_play":
            field = action.get("field")
            case = next((item for item in evaluation["cases"] if item["id"] == action.get("case")), None)
            if field not in ("input", "output", "history", "context") or case is None:
                raise YuanError(tr("review_stale", self.language))
            self.model._review_case(self.store, case)
            import soundfile as sf
            gain = self.model.policy.number("acceptance", "preview_gain", 1 / math.sqrt(10), 0.0, 1.0)
            def segments():
                if field in ("history", "context"):
                    for index, item in enumerate(case["history"]):
                        check(cancel)
                        row = self.store.sample(item["id"])
                        values = self.store.read_audio(row, item["start"], item["samples"], cancel=cancel, verify=True)
                        self.emit("review_playback", case=case["id"], role=item["role"], position=index, samples=len(values), sha256=item["sha256"])
                        yield values, row["rate"]
                for part in (("input", "output") if field == "context" else (field,) if field in ("input", "output") else ()):
                    audio_path = safe_path(directory, case[part + "_file"])
                    if digest_file(audio_path, cancel) != case[part + "_sha256"]:
                        raise InvalidAudio("听测音频摘要不匹配 / Listening audio digest mismatch")
                    values, rate = sf.read(str(audio_path), dtype="float32", always_2d=False)
                    if values.ndim != 1 or not values.size or not self.model.np.isfinite(values).all():
                        raise InvalidAudio("听测音频无效 / Invalid listening audio")
                    self.emit("review_playback", case=case["id"], role=part, samples=len(values))
                    yield values, rate
            try:
                self.devices.open_streams(cancel)
                for values, rate in segments():
                    check(cancel)
                    self.devices.play(values * gain, rate, cancel)
            finally:
                self.devices.close_streams()
                self.emit("status", key="ready" if self.model.playback_ready else "preparing_model")
            return
        if command == "review_submit":
            checks = action.get("checks")
            reviewer = action.get("reviewer")
            required = ("understandable", "follows_prompt", "relevant_reply", "follows_history", "ends_normally", "no_abnormal_audio")
            if not isinstance(reviewer, str) or not reviewer.strip() or not isinstance(checks, list) or len(checks) != len(evaluation["cases"]):
                raise YuanError(tr("review_incomplete", self.language))
            if any(not isinstance(item, dict) or not isinstance(item.get("id"), str) or any(type(item.get(key)) is not bool for key in required) for item in checks):
                raise YuanError(tr("review_incomplete", self.language))
            if {item["id"] for item in checks} != {item["id"] for item in evaluation["cases"]}:
                raise YuanError(tr("review_stale", self.language))
            draft.update(reviewer=reviewer.strip(), reviewed_at=time.time(), checks=checks)
            atomic_json(path, draft, cancel)
            self.model.review_held = None
            self.model.refresh_release()
            self.emit("notice", key="review_saved")

    def import_pair(self, action, cancel):
        import soundfile as sf
        required = ("recording_id", "reviewer", "prompt", "license", "user_speaker", "assistant_speaker", "user_file", "assistant_file")
        if action.get("confirmed") is not True or action.get("language") not in ("中文", "English") or not all(isinstance(action.get(key), str) and action[key].strip() for key in required):
            raise YuanError(tr("required_fields", self.language))
        if action["user_speaker"].strip() == action["assistant_speaker"].strip():
            raise YuanError(tr("required_fields", self.language))
        split = action.get("split", "auto")
        if split not in ("auto", "train", "validation", "guard", "release"):
            raise YuanError(tr("required_fields", self.language))
        endings = {role: action.get(role + "_utterance_final") for role in ("user", "assistant")}
        if any(value is not None and not isinstance(value, bool) for value in endings.values()):
            raise YuanError("语句结束标注必须为完整、截断或未知 / Utterance ending must be complete, truncated or unknown")
        recording = action["recording_id"].strip()
        existing = self.store.db.execute("SELECT split FROM groups WHERE source_key=? LIMIT 1", (recording,)).fetchone()
        if split == "auto":
            split = existing[0] if existing else "train"
        if split != "train":
            raise YuanError("验证、保护和发布数据请通过完整标注数据集入口导入 / Import validation, guard and release data through the annotated dataset entry")
        annotation = uuid.uuid4().hex
        root = safe_path(self.state, "datasets")
        root.mkdir(parents=True, exist_ok=True)
        assets = safe_path(root, "assets/" + annotation)
        assets.mkdir(parents=True, exist_ok=False)
        turns = []
        published = False
        try:
            offset = 0.0
            for role, field in (("user", "user_file"), ("assistant", "assistant_file")):
                check(cancel)
                source = Path(action[field]).expanduser().resolve(strict=True)
                before = source.stat()
                if not source.is_file() or before.st_size <= 0 or before.st_size > shutil.disk_usage(root).free // 2:
                    raise OSError("音频文件或可用磁盘空间无效 / Invalid audio file or insufficient disk space")
                target = assets / (role + source.suffix.lower())
                block = max(1, min(1024 * 1024, math.isqrt(before.st_size)))
                with source.open("rb") as incoming, target.open("xb") as outgoing:
                    while True:
                        check(cancel)
                        part = incoming.read(block)
                        if not part:
                            break
                        outgoing.write(part)
                    outgoing.flush()
                    os.fsync(outgoing.fileno())
                after = source.stat()
                if (before.st_size, before.st_mtime_ns, before.st_ctime_ns) != (after.st_size, after.st_mtime_ns, after.st_ctime_ns):
                    raise OSError("复制期间源音频发生变化 / Source audio changed while copying")
                info = sf.info(str(target))
                if info.frames <= 0 or info.samplerate <= 0:
                    raise InvalidAudio("录音为空 / Recording is empty")
                turn = {"id": annotation + "-" + role, "role": role, "speaker": action[role + "_speaker"].strip(),
                        "audio": target.relative_to(root).as_posix(), "sha256": digest_file(target, cancel), "start_seconds": offset, "utterance_final": endings[role]}
                if role == "assistant":
                    turn.update(reply_to=turns[0]["id"], response_verified=True)
                turns.append(turn)
                offset += info.frames / info.samplerate
            data = {"format": "yuan-paired-audio-v1", "origin": "human_recording", "recording_id": recording, "language": action["language"],
                    "reviewer": action["reviewer"].strip(), "annotation_id": annotation, "prompt": action["prompt"].strip(),
                    "license": action["license"].strip(), "split": split, "turns": turns}
            atomic_json(root / (annotation + ".json"), data, cancel)
            published = True
            self.emit("notice", key="pair_submitted", recording_id=recording, split=split, annotation=annotation)
        finally:
            if not published:
                shutil.rmtree(assets, ignore_errors=True)

    def import_dataset(self, action, cancel):
        if action.get("confirmed") is not True or not isinstance(action.get("manifest_file"), str):
            raise YuanError(tr("required_fields", self.language))
        source_manifest = Path(action["manifest_file"]).expanduser().resolve(strict=True)
        if source_manifest.suffix.lower() != ".json" or not source_manifest.is_file():
            raise YuanError("请选择标注清单 JSON 文件 / Select an annotation manifest JSON file")
        original = digest_file(source_manifest, cancel)
        data = checked_json(source_manifest)
        gaps = DatasetImporter.validate_annotations(data)
        root = safe_path(self.state, "datasets")
        root.mkdir(parents=True, exist_ok=True)
        identifier = uuid.uuid4().hex
        assets = safe_path(root, "assets/" + identifier)
        assets.mkdir(parents=True, exist_ok=False)
        published = False
        try:
            copied = {}
            for turn in data["turns"]:
                check(cancel)
                source = safe_path(source_manifest.parent, turn["audio"])
                if source not in copied:
                    if not source.is_file() or source.stat().st_size <= 0:
                        raise InvalidAudio("数据集音频不存在或为空 / Dataset audio is missing or empty")
                    target = assets / (payload_digest(turn["audio"]) + source.suffix.lower())
                    with StorageBudget(self.state).reserve(source.stat().st_size, "dataset_import"):
                        with source.open("rb") as incoming, target.open("xb") as outgoing:
                            while True:
                                check(cancel)
                                block = incoming.read(1024 * 1024)
                                if not block:
                                    break
                                outgoing.write(block)
                            outgoing.flush()
                            os.fsync(outgoing.fileno())
                    checksum = digest_file(target, cancel)
                    if checksum != turn["sha256"] or digest_file(source, cancel) != checksum:
                        raise InvalidAudio("数据集音频摘要不匹配 / Dataset audio checksum mismatch")
                    copied[source] = (target, checksum)
                target, checksum = copied[source]
                if checksum != turn["sha256"]:
                    raise InvalidAudio("同一音频存在冲突摘要 / Conflicting checksums for the same audio")
                turn["audio"] = target.relative_to(root).as_posix()
            if digest_file(source_manifest, cancel) != original:
                raise YuanError("复制期间数据集标注发生变化 / Dataset annotations changed during copying")
            data.setdefault("dataset_id", payload_digest([data["recording_id"], data["annotation_id"]]))
            target_manifest = root / (payload_digest(data["dataset_id"]) + ".json")
            atomic_json(target_manifest, data, cancel)
            published = True
            importer = DatasetImporter(self.state, self.store, self.model, self.emit)
            while importer.step(cancel):
                check(cancel)
            key = importer.identity_key(target_manifest, data)
            if self.store.setting(key) != digest_file(target_manifest, cancel):
                raise YuanError("数据集未通过完整导入校验 / Dataset did not pass complete import validation")
            self.emit("dataset_coverage", key="dataset_coverage", annotation_gaps=gaps, **self.learning_state())
        finally:
            if not published:
                shutil.rmtree(assets, ignore_errors=True)


@contextmanager
def runtime_entry(state):
    state = ensure_workspace_identity(state)
    if state != workspace_state(state.parent).resolve():
        raise YuanFault("运行目录与当前版本不匹配 / Runtime directory does not match this build", category="integrity", code="workspace_build_mismatch")
    env = workspace_environment(state.parent)
    os.environ.clear()
    os.environ.update(env)
    tempfile.tempdir = env["TMPDIR"]
    os.chdir(state)
    output = os.fdopen(os.dup(sys.stdout.fileno()), "w", encoding="utf-8", buffering=1)
    events = EventStream(output)
    emit = events.emit
    read_fd, write_fd = os.pipe()
    os.dup2(write_fd, sys.stdout.fileno())
    os.dup2(write_fd, sys.stderr.fileno())
    os.close(write_fd)
    def capture():
        with os.fdopen(read_fd, "r", encoding="utf-8", errors="replace") as stream:
            for line in stream:
                value = line.rstrip("\r\n")
                if events.cancel.is_set():
                    return
    recorder = threading.Thread(target=capture, daemon=True, name="YuanRuntimeCapture")
    recorder.start()
    import logging
    logging.basicConfig(level=logging.WARNING)
    try:
        yield emit, events.cancel
    finally:
        for stream in (sys.stdout, sys.stderr):
            try:
                stream.flush()
                os.dup2(output.fileno(), stream.fileno())
            except (OSError, ValueError):
                pass
        recorder.join(timeout=max(1, math.sqrt(os.cpu_count() or 1)))
        if events.close():
            output.close()

def engine_entry(state):
    state = Path(state).resolve()
    with runtime_entry(state) as (emit, cancel):
        try:
            with WorkspaceLease(state / "engine.lock"):
                Engine(state, emit, shutdown=cancel).run()
        except Exception as exc:
            emit("error", key="failure", reason=concise_error(exc), fatal=True, fault=fault_event(exc))

class LiveStatus:
    def __init__(self, state):
        self.lock = threading.RLock()
        self.closed = False
        self.sequence = 0
        self.latest = {}

    def add(self, event):
        kind = event.get("type")
        if kind not in ("status", "error", "notice", "deployment", "learning", "network", "storage_state", "recovery"):
            return
        with self.lock:
            if self.closed:
                return
            self.sequence += 1
            value = {key: event[key] for key in ("at", "type", "key", "reason", "action_key") if key in event}
            self.latest[kind] = (self.sequence, value)

    def page(self, before=None, limit=None):
        with self.lock:
            rows = sorted((row for row in self.latest.values() if before is None or row[0] < before), key=lambda row: row[0])
            return rows[-max(1, int(limit or len(rows) or 1)):] if not self.closed else []

    def close(self):
        with self.lock:
            self.latest.clear()
            self.closed = True

def event_text(event, language, compact=False):
    moment = time.strftime("%H:%M:%S", time.localtime(event.get("at", time.time())))
    kind = event.get("key") or event.get("type", "")
    title = tr(kind, language)
    values = {key: value for key, value in redact(event).items() if key not in ("at", "type", "key", "generation", "_sequence")}
    if compact:
        fields = []
        if event.get("type") == "operation":
            fields.append(tr("operation_" + str(event.get("outcome", "")), language))
        fault = event.get("fault")
        if isinstance(fault, dict):
            fields.append(tr("fault_" + fault.get("category", "unknown"), language))
            if fault.get("stage"):
                fields.append(tr(fault["stage"], language))
        for key in ("component", "version", "file", "check"):
            if values.get(key):
                fields.append(str(values[key]))
        if isinstance(event.get("elapsed"), (int, float)):
            fields.append(f"{event['elapsed']:.2f}s")
        if event.get("type") == "attempt":
            fields.append(str(event.get("attempt_number", "")))
        if event.get("action_key"):
            fields.append(tr(event["action_key"], language))
        detail = values.get("reason") or (fault.get("reason") if isinstance(fault, dict) else None) or values.get("detail") or ""
        if detail:
            summary = local_message(detail, language).split("\n", 1)[0][:240]
            if summary not in fields:
                fields.append(summary)
        if isinstance(fault, dict) and fault.get("code"):
            fields.append(str(fault["code"]))
        body = " · ".join(value for value in fields if value)
    else:
        body = json.dumps(values, ensure_ascii=False, allow_nan=False, indent=2) if values else ""
    return moment + "  " + title + ((" · " if compact else "\n") + body if body else "") + "\n"

class Mailbox:
    control_types = frozenset(("attempt", "status", "ready", "started", "ended", "error", "closed", "engine_exit", "exit", "disconnected", "launcher_closed", "process_started", "process_reaped", "review_open", "review_close", "review_result", "release_export", "startup_blocked"))
    state_types = frozenset(("attempt", "status", "readiness", "audio", "metrics", "devices", "model", "progress", "phase", "source_progress", "startup_resources", "learning", "data_plan", "data_acquisition", "recovery"))
    telemetry_types = frozenset(("progress", "source_progress", "readiness", "phase", "audio", "metrics", "devices", "model", "supervision", "condition_check", "startup_resources", "generation_measurement", "learning_context", "validation_window", "learning_memory", "dataset_coverage", "data_plan", "learning", "network", "storage_budget", "data_acquisition", "calibration"))

    def __init__(self, limit=None):
        self.events, self.controls = deque(), deque()
        self.latest = {}
        self.lock = threading.Lock()
        self.sequence = 0
        self.limit = max(1, int(limit if limit is not None else max(32, (os.cpu_count() or 1) * 4)))
        self.control_limit = max(4, self.limit)
        self.overflow = None
        self.overflow_delivered = False
        self.coalesced = 0
        self.retained = {}
        self.retained_identity = None

    @classmethod
    def critical(cls, event):
        return event.get("type") in cls.control_types or event.get("fatal") is True or (event.get("type") == "operation" and event.get("scope") == "startup")

    def put(self, event):
        with self.lock:
            if self.overflow is not None:
                raise EngineFault("事件通道已过载 / Event channel is overloaded")
            self.sequence += 1
            event = {**event, "_sequence": self.sequence}
            kind = event.get("type")
            if event.get("generation") is not None:
                identity = (event.get("generation"), event.get("attempt_number"), event.get("attempt_id"))
                if kind == "attempt":
                    current = self.retained_identity
                    newer_generation = current is not None and type(identity[0]) is int and type(current[0]) is int and identity[0] > current[0]
                    newer_attempt = current is not None and identity[0] == current[0] and type(identity[1]) is int and identity[1] > (current[1] or 0)
                    if current is None or newer_generation or newer_attempt:
                        self.retained_identity = identity
                        self.retained.clear()
                if identity == self.retained_identity:
                    if kind == "status":
                        self.retained.pop("progress", None)
                        self.retained.pop("phase", None)
                    if kind in self.state_types:
                        previous = self.retained.get(kind, {})
                        merge = kind in ("audio", "devices", "model") and previous.get("id") == event.get("id")
                        self.retained[kind] = {**previous, **event} if merge else dict(event)
                    elif self.critical(event):
                        self.retained["lifecycle"] = dict(event)
            if self.critical(event):
                if len(self.controls) >= self.control_limit:
                    self.overflow = {"type": "error", "fatal": True, "key": "failure", "reason": "关键事件通道过载，停止当前任务 / Critical event channel overloaded; current task stopped", "at": time.time(), "_sequence": self.sequence, "generation": event.get("generation"), "attempt_id": event.get("attempt_id"), "event_overflow": True}
                    raise EngineFault(self.overflow["reason"])
                self.controls.append(event)
            else:
                replaceable = kind == "operation" and event.get("replaceable") is True
                if replaceable or kind in self.telemetry_types or kind == "notice":
                    key = (event.get("generation"), event.get("attempt_number"), event.get("attempt_id"), event.get("id"), kind, event.get("scope"), event.get("key") if kind in ("notice", "operation") else None)
                    previous = self.latest.pop(key, {})
                    if previous:
                        self.coalesced += 1
                    if kind in ("audio", "metrics", "devices", "model") and previous.get("id") == event.get("id"):
                        event = {**previous, **event}
                    event["_coalesced"] = int(previous.get("_coalesced", 0)) + int(bool(previous))
                    self.latest[key] = event
                else:
                    self.events.append(event)
                while len(self.latest) + len(self.events) > self.limit:
                    oldest = next(iter(self.latest), None)
                    if self.events and (oldest is None or self.events[0]["_sequence"] < self.latest[oldest]["_sequence"]):
                        self.events.popleft()
                    elif oldest is not None:
                        self.latest.pop(oldest)
                    self.coalesced += 1
            return self.sequence

    def snapshot(self):
        with self.lock:
            return sorted((copy.deepcopy(event) for event in self.retained.values()), key=lambda event: event["_sequence"])

    def drain(self, reconcile=False):
        with self.lock:
            events = list(self.controls) + list(self.events) + list(self.latest.values())
            if reconcile and events:
                combined = {event["_sequence"]: event for event in self.retained.values()}
                combined.update((event["_sequence"], event) for event in events)
                events = list(combined.values())
            if self.overflow is not None and not self.overflow_delivered:
                events.append(self.overflow)
                self.overflow_delivered = True
            self.controls.clear()
            self.events.clear()
            self.latest.clear()
        return sorted(events, key=lambda event: event["_sequence"])

class EventStream:
    def __init__(self, stream):
        self.stream = stream
        self.mailbox = Mailbox()
        self.wake = threading.Event()
        self.closing = threading.Event()
        self.cancel = threading.Event()
        self.failed = threading.Event()
        self.lock = threading.Lock()
        self.sent = threading.Condition()
        self.sent_sequence = 0
        self.phase_id = None
        self.attempt_id = os.environ.get("YUAN_ATTEMPT_ID")
        self.flush_seconds = max(1.0, math.sqrt(os.cpu_count() or 1))
        self.thread = threading.Thread(target=self.run, daemon=True, name="YuanEvents")
        self.thread.start()

    def emit(self, kind, **values):
        values = redact(values)
        with self.lock:
            if self.failed.is_set():
                raise EngineFault("事件通道已断开 / Event channel disconnected")
            if self.closing.is_set():
                return
            if kind == "status":
                self.phase_id = values.setdefault("phase_id", uuid.uuid4().hex)
            if kind in ("phase", "progress"):
                values.setdefault("phase_id", self.phase_id)
            try:
                sequence = self.mailbox.put({"type": kind, "at": time.time(), "attempt_id": self.attempt_id, **values})
            except EngineFault:
                self.failed.set()
                self.cancel.set()
                self.wake.set()
                raise
            self.wake.set()
        if kind in ("started", "ended", "error", "closed") or kind == "operation" and values.get("outcome") == "begin" and values.get("scope") == "startup":
            deadline = time.monotonic() + self.flush_seconds
            with self.sent:
                while self.sent_sequence < sequence and not self.failed.is_set() and not self.closing.is_set():
                    remaining = deadline - time.monotonic()
                    if remaining <= 0:
                        self.failed.set()
                        self.cancel.set()
                        raise EngineFault("阶段记录通道超时 / Stage event channel timed out")
                    self.sent.wait(remaining)
            if self.failed.is_set() or self.sent_sequence < sequence:
                self.cancel.set()
                raise EngineFault("关键事件未确认送达 / Critical event delivery was not acknowledged")

    def run(self):
        try:
            while True:
                self.wake.wait()
                self.wake.clear()
                events = self.mailbox.drain()
                if events:
                    payload = "".join(json.dumps(event, ensure_ascii=False, allow_nan=False, separators=(",", ":")) + "\n" for event in events)
                    self.stream.write(payload)
                    self.stream.flush()
                    with self.sent:
                        self.sent_sequence = max(self.sent_sequence, max(event["_sequence"] for event in events))
                        self.sent.notify_all()
                if self.closing.is_set():
                    if self.mailbox.sequence <= self.sent_sequence:
                        break
                    self.wake.set()
        except (OSError, ValueError, TypeError):
            self.failed.set()
            self.cancel.set()
        finally:
            with self.sent:
                self.sent.notify_all()

    def close(self):
        with self.lock:
            self.closing.set()
            self.wake.set()
        with self.sent:
            self.sent.notify_all()
        self.thread.join(timeout=self.flush_seconds)
        if self.thread.is_alive():
            self.failed.set()
            self.cancel.set()
        return not self.thread.is_alive()

class ProcessOutput:
    def __init__(self, process):
        self.process = process
        self.lines = queue.Queue(maxsize=max(32, (os.cpu_count() or 1) * 4))
        self.stopped = threading.Event()
        self.done = threading.Event()
        self.thread = threading.Thread(target=self.run, daemon=True, name="YuanEngineOutput")
        self.thread.start()

    def run(self):
        try:
            while not self.stopped.is_set():
                line = self.process.stdout.readline()
                if not line:
                    return
                while not self.stopped.is_set():
                    try:
                        self.lines.put(line, timeout=math.sqrt(tick()))
                        break
                    except queue.Full:
                        pass
        except (OSError, ValueError):
            pass
        finally:
            self.done.set()
            self.process.stdout.close()

    def close(self, timeout):
        self.stopped.set()
        self.thread.join(timeout=max(0.0, timeout))
        return not self.thread.is_alive()

class RecoveryGate:
    def __init__(self, state, emit, clock=None):
        self.state, self.emit, self.clock = Path(state), emit, clock or time.monotonic
        self.path = safe_path(self.state, "recovery.json")
        self.policy = AdaptivePolicy(self.state)
        initial = self.policy.number("supervision", "initial_phase_seconds", 120.0, tick(), 86400.0)
        self.total = self.policy.number("recovery", "startup_campaign_seconds", initial * 16, tick(), 86400.0)
        self.transfer_total = self.policy.number("recovery", "startup_transfer_seconds", self.total * 4, tick(), 86400.0)
        self.per_fault = self.policy.integer("recovery", "same_fault_attempts", 3, 1, 16)
        self.maximum = self.policy.integer("recovery", "total_attempts", 6, 1, 64)
        self.delay = self.policy.number("recovery", "retry_delay_seconds", math.sqrt(initial), tick(), self.total)
        self.delay_ceiling = self.policy.number("recovery", "retry_max_seconds", initial, self.delay, self.total)
        self.check_interval = self.policy.number("recovery", "condition_check_seconds", max(5.0, math.sqrt(initial)), tick(), 3600.0)
        self.stable_seconds = self.policy.number("recovery", "stable_runtime_seconds", initial, tick(), 86400.0)
        self.probe_seconds = self.policy.number("recovery", "condition_probe_seconds", max(self.check_interval, math.sqrt(initial * self.check_interval)), tick(), max(initial, self.check_interval))
        self.code = build_digest()
        saved = read_json(self.path)
        valid = saved.get("code") == self.code and saved.get("conditions") == self.conditions()
        self.records = saved.get("faults", {}) if valid else {}
        if not isinstance(self.records, dict):
            self.records = {}
        used = saved.get("used_seconds", 0.0) if valid else 0.0
        self.used = float(used) if isinstance(used, (float, int)) and not isinstance(used, bool) and math.isfinite(used) and used >= 0 else 0.0
        transferred = saved.get("transfer_used_seconds", 0.0) if valid else 0.0
        self.transfer_used = float(transferred) if isinstance(transferred, (int, float)) and not isinstance(transferred, bool) and math.isfinite(transferred) and transferred >= 0 else 0.0
        attempts = saved.get("attempts", 0) if valid else 0
        self.attempts = int(attempts) if isinstance(attempts, int) and not isinstance(attempts, bool) and attempts >= 0 else 0
        self.last = saved.get("last", {}) if valid else {}
        if not isinstance(self.last, dict):
            self.last = {}
        self.waited = self.probe_used = 0.0
        for field, key in (("waited", "wait_seconds"), ("probe_used", "probe_seconds")):
            value = saved.get(key, 0.0) if valid else 0.0
            if isinstance(value, (int, float)) and not isinstance(value, bool) and math.isfinite(value) and value >= 0:
                setattr(self, field, float(value))
        condition = saved.get("network_condition", {}) if valid else {}
        self.network_condition = {"target": condition["target"], "reachable": condition["reachable"]} if isinstance(condition, dict) and is_digest(condition.get("target")) and type(condition.get("reachable")) is bool else {}
        self.resource_since = None
        self.resource_stable_seconds = self.policy.number("recovery", "resource_stable_seconds", self.check_interval * math.sqrt(2), self.check_interval, max(self.check_interval, self.stable_seconds))
        self.policy.save()

    @property
    def remaining(self):
        return max(0.0, self.total - self.used)


    @property
    def transfer_remaining(self):
        return max(0.0, self.transfer_total - self.transfer_used)


    def conditions(self):
        paths = [Path(__file__).resolve(), self.state / "policy.json", self.state / "network.json", self.state / "runtime-current.json", self.state / "runtime-lock.json"]
        paths.append(self.state / "runtime-build.json")
        for root in (self.state.parent, Path(__file__).resolve().parent):
            paths.extend(root / name for name in ("Yuan.release.json", "Yuan.trust.json", "Yuan.model.json", "Yuan.acceptance.json"))
            source = read_json(root / "Yuan.release.json").get("source")
            if isinstance(source, str) and not urllib.parse.urlparse(source).scheme:
                try:
                    paths.append(safe_path(root, source))
                except YuanError:
                    pass
        for name in ("owned-release.json", "owned-release-pending.json"):
            paths.append(self.state / name)
            owned = read_json(self.state / name)
            if owned.get("directory"):
                try:
                    paths.append(safe_path(self.state, owned["directory"]) / "release-manifest.json")
                except (TypeError, YuanError):
                    pass
        for name in ("runtime-current.json", "runtime-build.json"):
            pointer = read_json(self.state / name)
            if pointer.get("directory"):
                try:
                    runtime = safe_path(self.state, pointer["directory"])
                    paths += [runtime / "ready.json", runtime / "lock.json", runtime / "pyvenv.cfg", runtime_python(runtime)]
                except YuanError:
                    pass
        try:
            config = NetworkConfig(self.state)
            configuration = [config.index_urls, config.proxy, config.ca_file, config.client_cert]
            paths += [Path(value) for value in (config.ca_file, config.client_cert) if value]
        except Exception as exc:
            configuration = [failure_category(exc), concise_error(exc)]
        stamps = []
        for path in paths:
            try:
                info = path.stat()
                stamps.append([str(path), info.st_size, info.st_mtime_ns])
            except OSError:
                stamps.append([str(path), None, None])
        return payload_digest([stamps, configuration])

    def save(self):
        try:
            atomic_json(self.path, {"code": self.code, "conditions": self.conditions(), "faults": self.records, "last": self.last,
                                    "used_seconds": self.used, "transfer_used_seconds": self.transfer_used, "attempts": self.attempts,
                                    "wait_seconds": self.waited, "probe_seconds": self.probe_used,
                                    "network_condition": self.network_condition, "updated": time.time()})
        except (OSError, YuanError) as exc:
            self.emit("notice", key="journal_failure", component="recovery", reason=concise_error(exc))

    def network_changed(self, target, reachable):
        key = payload_digest(target)
        previous = self.network_condition
        changed = bool(reachable and previous.get("target") == key and previous.get("reachable") is False)
        self.network_condition = {"target": key, "reachable": bool(reachable)}
        return changed

    def record(self, fault, seconds, identity=None, transfer_seconds=0.0):
        details = fault.get("details", {})
        fingerprint = payload_digest([identity or runtime_identity(self.state), fault.get("category"), fault.get("code"), fault.get("stage"),
                                      details.get("component"), details.get("package")])
        row = self.records.setdefault(fingerprint, {"count": 0})
        if not isinstance(row, dict):
            row = self.records[fingerprint] = {"count": 0}
        previous = row.get("count", 0)
        row["count"] = (previous if isinstance(previous, int) and not isinstance(previous, bool) and previous >= 0 else 0) + 1
        self.used += max(0.0, seconds)
        self.transfer_used += max(0.0, transfer_seconds)
        self.attempts += 1
        self.last = {**redact(fault), "fingerprint": fingerprint, "count": row["count"], "at": time.time()}
        row.update(code=fault.get("code"), stage=fault.get("stage"), category=fault.get("category"), at=time.time(),
                   used_seconds=max(0.0, float(row.get("used_seconds", 0))) + max(0.0, seconds),
                   transfer_used_seconds=max(0.0, float(row.get("transfer_used_seconds", 0))) + max(0.0, transfer_seconds))
        self.save()
        return self.last

    def resource_ready(self, fault, resources):
        required = fault.get("details", {}).get("required_bytes")
        available = resources.get("memory") if isinstance(resources, dict) else None
        resident = fault.get("details", {}).get("runtime_resident_bytes", 0)
        probe_resident = resources.get("process_rss", 0) if isinstance(resources, dict) else 0
        if type(available) is int and type(resident) is int and type(probe_resident) is int:
            available = max(0, available - max(0, resident - probe_resident))
        valid = (fault.get("code") == "model_memory_insufficient" and type(required) is int and required > 0
                 and type(available) is int and available >= required)
        if not valid:
            self.resource_since = None
            return False
        now = self.clock()
        if self.resource_since is None:
            self.resource_since = now
        return now - self.resource_since >= self.resource_stable_seconds

    def resume_fault(self, reason):
        row = self.records.pop(self.last.get("fingerprint"), {})
        self.attempts = max(0, self.attempts - max(0, int(row.get("count", 0))))
        self.used = max(0.0, self.used - max(0.0, float(row.get("used_seconds", 0))))
        self.transfer_used = max(0.0, self.transfer_used - max(0.0, float(row.get("transfer_used_seconds", 0))))
        self.last = {}
        self.resource_since = None
        self.save()
        self.emit("notice", key=reason, unrelated_faults_preserved=len(self.records))
        return self.can_retry()

    def retry_blocker(self):
        if self.last.get("details", {}).get("retry_blocker") == "retry_import_unchanged":
            return "retry_import_unchanged"
        if self.remaining <= 0:
            return "retry_time_exhausted"
        if self.transfer_remaining <= 0:
            return "retry_transfer_exhausted"
        if self.attempts >= self.maximum:
            return "retry_total_exhausted"
        if self.last.get("count", 0) >= self.per_fault:
            return "retry_same_fault_exhausted"
        return None


    def can_retry(self):
        return self.retry_blocker() is None

    def reset(self, reason):
        self.records, self.last, self.used, self.transfer_used, self.attempts = {}, {}, 0.0, 0.0, 0
        fresh = RecoveryGate(self.state, self.emit, self.clock)
        for field in ("policy", "total", "transfer_total", "per_fault", "maximum", "delay", "delay_ceiling", "check_interval", "probe_seconds", "stable_seconds", "code"):
            setattr(self, field, getattr(fresh, field))
        self.save()
        self.emit("notice", key=reason)

    def retry_delay(self):
        return min(self.delay_ceiling, self.delay * 2 ** min(max(0, self.last.get("count", 1) - 1), self.maximum), self.remaining)

class Launcher:
    def __init__(self, workspace, generation, mailbox, lease=None):
        self.workspace, self.generation, self.mailbox = Path(workspace).resolve(), generation, mailbox
        self.cancel = threading.Event()
        self.retry_requested = threading.Event()
        self.blocked = threading.Event()
        self.process_retained = False
        self.process = None
        self.lock = threading.RLock()
        self.thread = threading.Thread(target=self.run, daemon=True)
        self.lease = lease
        self.send_lock = threading.Lock()
        self.commands = queue.Queue()
        self.sender = threading.Thread(target=self.send_loop, daemon=True, name="YuanCommands")
        self.activity = LiveStatus(workspace_state(self.workspace))
        self.phase_at = time.monotonic()
        self.phase_key = "setup"
        self.retry_until = None
        self.activity_error = None
        self.event_lock = threading.RLock()
        self.event_sequence = 0
        self.attempt_id = None
        self.attempt_number = 0
        self.phase_id = None
        self.supervisor = StageSupervisor(workspace_state(self.workspace), self.emit)
        self.control_deadline = None
        self.control_id = None
        self.child_error = None
        self.child_fault = None
        self.engine_ever_ready = False
        self.engine_ready_at = None
        self.gate = RecoveryGate(workspace_state(self.workspace), self.emit)
        self.sender.start()
        self.thread.start()

    def emit(self, kind, **values):
        values = redact(values)
        with self.event_lock:
            self.event_sequence += 1
            if kind == "status":
                self.phase_at = time.monotonic()
                self.phase_key = values.get("key", self.phase_key)
                self.phase_id = values.setdefault("phase_id", uuid.uuid4().hex)
                self.retry_until = None
            elif kind == "recovery":
                self.retry_until = time.monotonic() + max(0, float(values["seconds"])) if values.get("mode") == "automatic_retry" and values.get("seconds") is not None else None
            if kind in ("progress", "phase"):
                values.setdefault("phase_id", self.phase_id)
            event = {"at": time.time(), **values, "type": kind, "generation": self.generation, "attempt_id": self.attempt_id,
                     "attempt_number": self.attempt_number, "event_sequence": self.event_sequence}
            try:
                self.activity.add(event)
                if self.activity_error:
                    recovered = {"type": "notice", "generation": self.generation, "at": time.time(), "key": "recording_resumed",
                                 "attempt_id": self.attempt_id, "attempt_number": self.attempt_number}
                    self.activity.add(recovered)
                    self.post_event(recovered)
                    self.activity_error = None
            except (sqlite3.Error, OSError, ValueError) as exc:
                reason = concise_error(exc)
                if reason != self.activity_error:
                    self.post_event({"type": "notice", "generation": self.generation, "at": time.time(), "key": "journal_failure", "reason": reason,
                                      "attempt_id": self.attempt_id, "attempt_number": self.attempt_number})
                self.activity_error = reason
            self.post_event(event)

    def post_event(self, event):
        try:
            self.mailbox.put(event)
            return True
        except EngineFault:
            self.cancel.set()
            self.control_deadline = time.monotonic()
            return False

    def send(self, action):
        with self.lock:
            process = self.process
            if not process or process.poll() is not None:
                return False
            if action.get("action") in ("stop", "close"):
                self.control_deadline = time.monotonic() + self.supervisor.grace
                self.control_id = action.get("id")
            self.commands.put((process, dict(action)))
        return True

    def send_loop(self):
        while True:
            item = self.commands.get()
            if item is None:
                return
            process, action = item
            with self.lock:
                current = self.process
            if process is not current or process.poll() is not None:
                continue
            try:
                with self.send_lock:
                    process.stdin.write(json.dumps(action, ensure_ascii=False, allow_nan=False) + "\n")
                    process.stdin.flush()
            except (OSError, ValueError, TypeError) as exc:
                self.emit("notice", key="command_failed", action=action.get("action"), id=action.get("id"), pid=process.pid, reason=concise_error(exc))
                with self.lock:
                    if self.process is process:
                        self.control_deadline = time.monotonic()

    def request_recheck(self):
        if self.cancel.is_set() or not self.blocked.is_set():
            return False
        self.retry_requested.set()
        return True

    def probe_resources(self, cancel, installer=None):
        state = workspace_state(self.workspace)
        candidates = []
        for name in ("runtime-current.json", "runtime-build.json"):
            pointer = read_json(state / name)
            if isinstance(pointer.get("directory"), str):
                try:
                    candidates.append(runtime_python(safe_path(state, pointer["directory"])))
                except YuanError:
                    pass
        if installer is not None and getattr(installer, "selected_executable", None):
            candidates.append(Path(installer.selected_executable))
        executable = next((path for path in candidates if path.is_file()), None)
        if executable is None:
            return None
        check(cancel)
        process = spawn([str(executable), "-B", str(Path(__file__).resolve()), "--probe-resources", str(state)],
                        workspace_environment(self.workspace), stdout=subprocess.PIPE, stderr=subprocess.DEVNULL)
        deadline = time.monotonic() + self.gate.probe_seconds
        try:
            while process.poll() is None:
                check(cancel)
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    return None
                cancel.wait(min(math.sqrt(tick()), remaining))
            output = process.stdout.read()
            if process.returncode != 0 or len(output) > 4096:
                return None
            result = json.loads(output)
            if not isinstance(result, dict) or type(result.get("memory")) is not int or type(result.get("cpus")) is not int:
                return None
            return result
        finally:
            if process.poll() is None:
                end_process(process)
            process.stdout.close()

    def wait_recovery(self, fault, installer=None):
        self.blocked.set()
        category = fault.get("category", "unknown")
        target = fault.get("details", {}).get("url")
        if not isinstance(target, str) or urllib.parse.urlsplit(target).scheme != "https" or "<redacted>" in target:
            target = installer.network_config.index_urls[0] if installer is not None else None
        initial_conditions = self.gate.conditions()
        try:
            initial_free = shutil.disk_usage(self.workspace).free
        except OSError:
            initial_free = None
        def writable():
            try:
                state = workspace_state(self.workspace)
                fd, path = tempfile.mkstemp(dir=state if state.is_dir() else self.workspace, prefix=".yuan-write-check-")
                os.close(fd)
                os.unlink(path)
                return True
            except (OSError, YuanError):
                return False
        initially_writable = writable() if category == "storage" else True
        self.gate.resource_since = None
        interrupted = AnyCancel(self.cancel, self.retry_requested)
        def publish(mode, seconds=None):
            action = "action_" + category if "action_" + category in TEXT else "action_unknown"
            key = "retry" if mode == "automatic_retry" else "network_wait" if category == "network" and mode == "waiting_conditions" else "startup_blocked"
            self.emit("status", key=key)
            self.emit("recovery", key="backoff" if mode == "automatic_retry" else key, mode=mode, blocked=True, task_running=False,
                      seconds=seconds if mode == "automatic_retry" else None, fault=redact(fault), action_key=action,
                      exhausted=not self.gate.can_retry(), retry_blocker=self.gate.retry_blocker() or ("retry_requires_change" if mode != "automatic_retry" else None),
                      matching_failures=self.gate.last.get("count", 0), same_fault_limit=self.gate.per_fault,
                      attempts=self.gate.attempts, attempts_limit=self.gate.maximum, remaining_seconds=self.gate.remaining,
                      transfer_remaining_seconds=self.gate.transfer_remaining, wait_seconds=self.gate.waited,
                      probe_seconds=self.gate.probe_used, probe_limit_seconds=self.gate.probe_seconds)
        if category in ("timeout", "engine", "unknown") and self.gate.can_retry():
            delay = self.gate.retry_delay()
            publish("automatic_retry", delay)
            began = time.monotonic()
            interrupted.wait(delay)
            self.gate.waited += max(0.0, time.monotonic() - began)
            self.gate.save()
            if not interrupted.is_set() and self.gate.can_retry():
                return True
        mode = "waiting_conditions" if self.gate.can_retry() or category == "network" and target else "paused"
        publish(mode)
        while not self.cancel.is_set():
            if self.retry_requested.is_set():
                self.retry_requested.clear()
                self.gate.reset("recheck_requested")
                return True
            if self.gate.conditions() != initial_conditions:
                self.gate.reset("conditions_changed")
                return True
            if category == "storage" and initial_free is not None:
                try:
                    free = shutil.disk_usage(self.workspace).free
                    margin = self.gate.policy.integer("recovery", "storage_growth_bytes", 1024 * 1024, 4096, max(4096, shutil.disk_usage(self.workspace).total))
                    if (free - initial_free >= margin or not initially_writable) and writable():
                        self.gate.reset("conditions_changed")
                        return True
                except OSError:
                    pass
            if category == "resource":
                began = time.monotonic()
                resources = None
                try:
                    resources = self.probe_resources(interrupted, installer)
                except Cancelled:
                    continue
                except (OSError, ValueError, TypeError, YuanError) as exc:
                    self.emit("condition_check", key="resource_check", reason=concise_error(exc), resource_probe_complete=False)
                finally:
                    self.gate.probe_used += max(0.0, time.monotonic() - began)
                    self.gate.save()
                ready = self.gate.resource_ready(fault, resources)
                self.emit("condition_check", key="resource_check", resource_probe_complete=resources is not None,
                          available_bytes=resources.get("memory") if resources else None, required_bytes=fault.get("details", {}).get("required_bytes"),
                          stable_seconds=0.0 if self.gate.resource_since is None else max(0.0, self.gate.clock() - self.gate.resource_since),
                          required_stable_seconds=self.gate.resource_stable_seconds)
                if ready and self.gate.resume_fault("resource_restored"):
                    return True
            if category == "network" and target:
                began = time.monotonic()
                reachable = changed = False
                try:
                    deadline = began + self.gate.probe_seconds
                    network = Network(interrupted, self.gate.policy)
                    try:
                        response = network.request(target, method="HEAD", deadline=deadline)
                    except urllib.error.HTTPError as exc:
                        exc.close()
                        if exc.code not in (405, 501):
                            raise
                        response = network.request(target, deadline=deadline)
                    response.close()
                    check(interrupted)
                    reachable = True
                    changed = self.gate.network_changed(target, True)
                except Cancelled:
                    continue
                except Exception as exc:
                    checked = fault_event(exc)
                    self.gate.network_changed(target, False)
                    self.emit("condition_check", key="network_wait", fault=checked, source=target)
                    if checked["category"] in ("integrity", "configuration", "resolution"):
                        category = checked["category"]
                        fault = {**checked, "stage": fault.get("stage")}
                        mode = "waiting_conditions"
                        publish(mode)
                finally:
                    self.gate.probe_used += max(0.0, time.monotonic() - began)
                    self.gate.save()
                if reachable and (self.gate.can_retry() or changed):
                    if changed:
                        if self.gate.resume_fault("network_restored"):
                            return True
                    elif self.gate.can_retry():
                        self.emit("notice", key="network_restored", source=target)
                        return True
            self.emit("condition_check", key="condition_check", blocked=True, mode=mode, task_running=False,
                      changed=False, next_check_seconds=self.gate.check_interval)
            began = time.monotonic()
            interrupted.wait(self.gate.check_interval)
            self.gate.waited += max(0.0, time.monotonic() - began)
            self.gate.save()
        return False

    def stop(self):
        if self.cancel.is_set():
            return
        self.cancel.set()
        self.send({"action": "close"})

    def monitor_process(self, process):
        output = ProcessOutput(process)
        self.supervisor.start(process.pid, remaining=self.startup_guard.deadline - time.monotonic())
        drain_deadline = None
        try:
            while True:
                now = time.monotonic()
                with self.lock:
                    if self.cancel.is_set() and self.control_deadline is None:
                        self.control_deadline = now + self.supervisor.grace
                    control_deadline = self.control_deadline
                if control_deadline is not None and now >= control_deadline:
                    if self.cancel.is_set():
                        raise Cancelled()
                    raise EngineFault("控制命令未按时完成，存档状态未确认 / Control command timed out; storage state unconfirmed: PID " + str(process.pid))
                if not self.cancel.is_set() and control_deadline is None:
                    self.supervisor.poll()
                try:
                    line = output.lines.get(timeout=math.sqrt(tick()))
                except queue.Empty:
                    line = None
                if line is not None:
                    try:
                        event = json.loads(line)
                    except (ValueError, TypeError):
                        self.emit("runtime_message", detail=line.rstrip("\r\n"), pid=process.pid)
                        event = None
                    if isinstance(event, dict) and isinstance(event.get("type"), str):
                        incoming_attempt = event.get("attempt_id")
                        if incoming_attempt is not None and incoming_attempt != self.attempt_id:
                            continue
                        self.supervisor.observe(event)
                        kind = event.pop("type")
                        if kind == "ready":
                            self.engine_ever_ready = True
                            self.engine_ready_at = time.monotonic()
                        if kind == "error":
                            self.child_error = event.get("reason")
                            if isinstance(event.get("fault"), dict):
                                self.child_fault = event["fault"]
                        if kind == "exit" or kind == "error" and event.get("fatal"):
                            with self.lock:
                                limit = time.monotonic() + self.supervisor.grace
                                self.control_deadline = min(self.control_deadline, limit) if self.control_deadline is not None else limit
                        if kind == "ended":
                            with self.lock:
                                if not self.cancel.is_set() and event.get("id") == self.control_id:
                                    self.control_deadline = None
                                    self.control_id = None
                        event.pop("generation", None)
                        event.pop("event_sequence", None)
                        self.emit(kind, **event)
                if process.poll() is not None:
                    if output.done.is_set() and output.lines.empty():
                        break
                    if drain_deadline is None:
                        drain_deadline = time.monotonic() + self.supervisor.grace
                    if time.monotonic() >= drain_deadline:
                        raise EngineFault("进程已退出但输出通道未关闭 / Process exited but output channel did not close: PID " + str(process.pid))
                elif output.done.is_set() and output.lines.empty():
                    if drain_deadline is None:
                        drain_deadline = time.monotonic() + self.supervisor.grace
                    if time.monotonic() >= drain_deadline:
                        raise EngineFault("引擎输出通道已关闭但进程仍在运行 / Engine output closed while process remains running: PID " + str(process.pid))
            return process.returncode
        finally:
            output.close(math.sqrt(tick()))

    def run(self):
        state = workspace_state(self.workspace)
        retained_process = False
        installer = None
        try:
            if self.lease is None:
                self.lease = WorkspaceLease(state / "workspace.lock")
            with WorkspaceLease(state / "engine.lock"):
                pass
            if self.gate.last and not self.gate.can_retry():
                self.emit("error", key="failure", reason=self.gate.last.get("reason", ""), fault=self.gate.last)
                if not self.wait_recovery(self.gate.last):
                    return
            while not self.cancel.is_set():
                self.blocked.clear()
                self.attempt_started = time.monotonic()
                with self.event_lock:
                    self.attempt_number += 1
                    self.attempt_id = uuid.uuid4().hex
                    self.phase_id = None
                    self.emit("attempt", key="attempt")
                with self.lock:
                    self.control_deadline = self.control_id = None
                self.child_error = self.child_fault = None
                self.engine_ever_ready = False
                self.engine_ready_at = None
                failure = None
                installer = None
                self.startup_guard = None
                try:
                    guard = StartupControl(self.cancel, self.attempt_started + self.gate.remaining, transfer_seconds=self.gate.transfer_remaining)
                    self.startup_guard = guard
                    check(guard)
                    self.supervisor = StageSupervisor(state, self.emit)
                    startup_preflight(state, emit=self.emit)
                    installer = RuntimeInstaller(self.workspace, guard, self.emit)
                    installer.env["YUAN_ATTEMPT_ID"] = self.attempt_id
                    owned_release_preflight(state, self.emit)
                    interpreter = installer.ensure()
                    check(guard)
                    self.supervisor = StageSupervisor(state, self.emit, identity=runtime_identity(state, installer.verified_entry))
                    self.emit("status", key="loading")
                    budgets = {"stage_import_" + name: self.supervisor.budget("stage_import_" + name) for name in RUNTIME_MODULES}
                    self.supervisor.policy.save()
                    env = {**installer.env, "YUAN_ATTEMPT_ID": self.attempt_id, "YUAN_IMPORT_BUDGETS": json.dumps(budgets),
                           "YUAN_IMPORT_IDENTITY": self.supervisor.fingerprint, "YUAN_STARTUP_DEADLINE": str(guard.deadline), "YUAN_COMPUTE_BACKEND": installer.compute_backend}
                    process = spawn([str(interpreter), "-B", str(Path(__file__).resolve()), "--engine", str(state)], env,
                                    stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, encoding="utf-8", errors="replace", bufsize=1)
                    with self.lock:
                        self.process = process
                    returncode = self.monitor_process(process)
                    check(self.cancel)
                    self.emit("disconnected", returncode=returncode, pid=process.pid, reason=self.child_error)
                    if self.child_fault:
                        details = dict(self.child_fault.get("details", {}))
                        raise YuanFault(self.child_fault.get("reason") or self.child_error or "引擎失败 / Engine failed", category=self.child_fault.get("category", "engine"),
                                        code=self.child_fault.get("code", "engine_failure"), stage=self.child_fault.get("stage"), **details)
                    raise EngineFault(self.child_error or "音频引擎意外退出 / Audio engine exited unexpectedly", code="engine_exited", stage=self.phase_key, returncode=returncode, pid=process.pid)
                except Cancelled:
                    break
                except Exception as exc:
                    failure = fault_details(exc, installer.phase if installer is not None and self.process is None else self.phase_key)
                    if failure["code"] == "process_reap_failed" or failure.get("details", {}).get("process_retained"):
                        retained_process = True
                        self.cancel.set()
                    self.emit("error", key="failure", reason=concise_error(exc), fault=redact(failure), component="launcher")
                finally:
                    self.supervisor.flush_history(force=True)
                    with self.lock:
                        process = self.process
                    if process:
                        try:
                            if process.poll() is None:
                                end_process(process)
                            self.emit("process_reaped", pid=process.pid, returncode=process.returncode)
                            with self.lock:
                                self.process = None
                            if process.stdin:
                                def close_input(retired=process):
                                    try:
                                        with self.send_lock:
                                            retired.stdin.close()
                                    except (OSError, ValueError):
                                        pass
                                closer = threading.Thread(target=close_input, daemon=True, name="YuanPipeCleanup")
                                closer.start()
                                closer.join(timeout=math.sqrt(tick()))
                        except Exception as exc:
                            retained_process = True
                            self.cancel.set()
                            self.emit("error", key="failure", reason=concise_error(exc), fault=fault_event(exc), pid=process.pid)
                if failure is not None and not self.cancel.is_set():
                    now = time.monotonic()
                    stable = self.engine_ready_at is not None and now - self.engine_ready_at >= self.gate.stable_seconds
                    if stable:
                        self.gate.reset("conditions_changed")
                    transfer_used = self.startup_guard.transfer_used if self.startup_guard is not None and not stable else 0.0
                    elapsed = 0.0 if stable else max(0.0, now - self.attempt_started - transfer_used)
                    self.gate.record(failure, elapsed, identity=installer.supervisor.fingerprint if installer is not None else None, transfer_seconds=transfer_used)
                    if not self.wait_recovery(failure, installer):
                        break
        except Cancelled:
            pass
        except Exception as exc:
            self.emit("error", key="failure", reason=concise_error(exc), fault=fault_event(exc))
        finally:
            self.blocked.clear()
            self.commands.put(None)
            self.sender.join(timeout=max(tick(), math.sqrt(tick())))
            self.process_retained = retained_process
            if self.lease and not retained_process:
                self.lease.close()
            self.emit("launcher_closed", process_retained=retained_process)

class InterfaceState:
    def __init__(self):
        self.generation = None
        self.reset()

    def reset(self):
        self.attempt_id = None
        self.attempt_number = self.sequence = 0
        self.phase_id = None
        self.readiness = {}
        self.audio = {}
        self.progress = {}
        self.metrics = {}
        self.status = "setup"
        self.session = None
        self.incomplete = False

    def apply(self, event, generation, session, closing=False, ending=False):
        if not isinstance(event, dict) or event.get("generation") not in (None, generation):
            return False
        if generation != self.generation:
            self.reset()
            self.generation = generation
        kind = event.get("type")
        if kind == "attempt":
            number = event.get("attempt_number")
            if type(number) is not int or number <= self.attempt_number or not event.get("attempt_id"):
                return False
            self.reset()
            self.attempt_number, self.attempt_id = number, event["attempt_id"]
            self.incomplete = session is not None
        elif event.get("attempt_id") is not None and event["attempt_id"] != self.attempt_id:
            return False
        if kind in ("status", "started", "ended", "audio", "turn", "metrics", "devices", "model") and event.get("id") is not None and event["id"] != session:
            return False
        if kind == "progress" and event.get("phase_id") != self.phase_id:
            return False
        sequence = event.get("event_sequence")
        if sequence is not None:
            if type(sequence) is not int or sequence <= self.sequence:
                return False
            self.sequence = sequence
        if self.session != session:
            self.audio = {}
        self.session = None if kind == "attempt" else session
        if kind == "readiness":
            self.readiness = dict(event)
            if session is None and not closing:
                ready, status = readiness_view(self.readiness, closing)
                if status is not None:
                    self.status = status
        elif kind == "status":
            if event.get("phase_id") != self.phase_id:
                self.progress = {}
            self.phase_id = event.get("phase_id")
            if not ending and not closing:
                self.status = event.get("key", self.status)
        elif kind in ("audio", "turn"):
            self.audio.update(event)
        elif kind == "metrics":
            self.metrics = dict(event)
        elif kind == "startup_resources":
            self.metrics.update(event)
        elif kind in ("progress", "source_progress"):
            self.progress.update(event)
        elif kind == "started" and not ending and not closing:
            self.status = "listening"
        elif kind == "ended":
            self.session = None
            self.status = "ended"
            self.audio.update(continuous=False, speech_active=False)
            self.progress = {}
            self.incomplete = event.get("storage_complete") is False or event.get("capture_complete") is False
        elif kind in ("exit", "disconnected", "launcher_closed", "process_reaped") or kind == "error" and event.get("fatal") is not False:
            self.incomplete = session is not None
            self.session = None
            self.readiness = {}
            self.audio.update(continuous=False, speech_active=False)
            self.progress = {}
            self.status = "failure" if kind == "error" else "ended"
        return True

class YuanApp:
    def __init__(self, root):
            import tkinter as tk
            from tkinter import ttk, font
            self.tk, self.ttk, self.root = tk, ttk, root
            self.mailbox = Mailbox()
            self.interface = InterfaceState()
            self.launcher = None
            self.workspace = None
            self.generation = 0
            self.attempt_id = None
            self.attempt_number = 0
            self.event_sequence = 0
            self.phase_id = None
            self.supervision_value = {}
            self.current_failure = {}
            self.last_failure = {}
            self.recovery_value = {}
            self.startup_values = {}
            self.deployment_value = {}
            self.notice_context = None
            self.ready = False
            self.runtime_ready = False
            self.readiness_values = {}
            self.session_id = None
            self.session_started = None
            self.ending = False
            self.closing = False
            self.language = "中文"
            self.status_key = "idle"
            self.learning_key = "waiting_data"
            self.network_key = "wait"
            self.reason = ""
            self.notice_key = ""
            self.device_values = {}
            self.model_values = {}
            self.audio_values = {}
            self.learning_values = {}
            self.resource_values = {}
            self.progress_value = {}
            self.source_values = {}
            self.phase_values = {}
            self.activity_window = None
            self.learning_window = self.review_window = None
            self.recent_activity = deque()
            self.pipeline_verified = False
            self.level = 0.0
            self.phase = 0.0
            self.last_draw = time.monotonic()
            self.last_saved_prompt = None
            self.save_job = None
            self.pending_workspace = None
            self.palette = {"bg": "#090d16", "panel": "#121a28", "field": "#0c1320", "border": "#25334a", "text": "#f0f4ff", "muted": "#a5b4cd",
                            "accent": "#79e7d2", "lavender": "#baacff", "warning": "#ffc891"}
            families = set(font.families(root))
            family = next((name for name in ("Microsoft YaHei UI", "PingFang SC", "Noto Sans CJK SC", "Noto Sans CJK TC", "WenQuanYi Micro Hei", "Arial") if name in families), "TkDefaultFont")
            self.unit = max(6, int(round(font.nametofont("TkDefaultFont").metrics("linespace") / 2.5)))
            system_size = int(font.nametofont("TkDefaultFont").cget("size"))
            self.base = max(11, (system_size if system_size > 0 else int(round(abs(system_size) * 72 / max(1, root.winfo_fpixels("1i"))))) + 1)
            self.font = font.Font(root=root, family=family, size=self.base)
            self.small_font = font.Font(root=root, family=family, size=self.base)
            self.heading_font = font.Font(root=root, family=family, size=self.base + 10, weight="bold")
            self.brand_font = font.Font(root=root, family=family, size=self.base + 16, weight="bold")
            self.bold_font = font.Font(root=root, family=family, size=self.base, weight="bold")
            self.root.title(APP_NAME)
            self.root.configure(bg=self.palette["bg"])
            self.root.option_add("*Font", self.font)
            screen_width, screen_height = root.winfo_screenwidth(), root.winfo_screenheight()
            width = min(screen_width, max(680, int(screen_width * .88)))
            height = min(screen_height, max(500, screen_height - self.font.metrics("linespace") * 2))
            self.root.geometry(f"{width}x{height}+{max(0, (screen_width-width)//2)}+{max(0, (screen_height-height)//2)}")
            self.root.minsize(min(420, screen_width), min(380, screen_height))
            self.style = ttk.Style(root)
            if "clam" in self.style.theme_names():
                self.style.theme_use("clam")
            self.style.configure("Yuan.Horizontal.TProgressbar", troughcolor=self.palette["field"], background=self.palette["accent"], bordercolor=self.palette["field"], lightcolor=self.palette["accent"], darkcolor=self.palette["accent"], thickness=3)
            self.style.configure("Yuan.Vertical.TScrollbar", background=self.palette["border"], troughcolor=self.palette["bg"], bordercolor=self.palette["bg"], arrowcolor=self.palette["muted"], width=9)
            self.root.grid_rowconfigure(0, weight=1)
            self.root.grid_columnconfigure(0, weight=1)
            self.viewport = tk.Canvas(root, bg=self.palette["bg"], highlightthickness=0, bd=0)
            self.viewport.grid(row=0, column=0, sticky="nsew")
            self.scrollbar = ttk.Scrollbar(root, orient="vertical", style="Yuan.Vertical.TScrollbar", command=self.viewport.yview)
            self.viewport.configure(yscrollcommand=self.scrollbar.set)
            self.body = tk.Frame(self.viewport, bg=self.palette["bg"], padx=self.unit*2, pady=self.unit)
            self.body_window = self.viewport.create_window(0, 0, window=self.body, anchor="nw")
            self.body.grid_columnconfigure(0, weight=1)
            self.body.grid_rowconfigure(6, weight=1)
            self.viewport.bind("<Configure>", self.resize)
            self.body.bind("<Configure>", self.measure)
            self.root.bind_all("<MouseWheel>", self.wheel)
            self.root.bind_all("<Button-4>", self.wheel)
            self.root.bind_all("<Button-5>", self.wheel)
            self.bound = []
            self.build_header()
            self.build_controls()
            self.build_hero()
            self.build_cards()
            self.build_footer()
            self.build_activity()
            self.root.protocol("WM_DELETE_WINDOW", self.close)
            self.root.bind("<Control-Return>", lambda event: self.toggle())
            self.root.report_callback_exception = self.callback_error
            self.localize()
            self.refresh()
            self.root.after(max(1, int(math.sqrt(tick()) * 1000)), self.pump)
            self.root.after(max(1, int(tick() * 1000)), self.animate)

    def label(self, parent, text="", key=None, **options):
        defaults = dict(bg=parent.cget("bg"), fg=self.palette["text"], anchor="w", justify="left", bd=0, font=self.font)
        defaults.update(options)
        widget = self.tk.Label(parent, text=text if key is None else tr(key, self.language), **defaults)
        if key:
            self.bound.append((widget, key))
        return widget

    def button(self, parent, command, text="", key=None, primary=False, **options):
        defaults = dict(bg=self.palette["accent"] if primary else self.palette["panel"], fg=self.palette["bg"] if primary else self.palette["text"],
                        activebackground=self.palette["lavender"] if primary else self.palette["border"], activeforeground=self.palette["bg"] if primary else self.palette["text"],
                        disabledforeground=self.palette["muted"], relief="flat", bd=0, padx=self.unit*2, pady=self.unit, cursor="hand2", font=self.bold_font,
                        highlightthickness=1, highlightbackground=self.palette["border"], highlightcolor=self.palette["accent"], takefocus=True)
        defaults.update(options)
        widget = self.tk.Button(parent, text=text if key is None else tr(key, self.language), command=command, **defaults)
        if key:
            self.bound.append((widget, key))
        return widget

    def build_header(self):
        top = self.tk.Frame(self.body, bg=self.palette["bg"])
        top.grid(row=0, column=0, sticky="ew", pady=(0, self.unit))
        top.grid_columnconfigure(1, weight=1)
        brand = self.label(top, text="Y U A N", font=self.brand_font)
        native = self.label(top, text="NATIVE AUDIO", fg=self.palette["accent"], font=self.small_font)
        subtitle = self.label(top, key="subtitle", fg=self.palette["muted"], font=self.small_font)
        self.language_button = self.button(top, self.switch_language, text="中文  /  EN", padx=self.unit, pady=max(3, self.unit//2))
        def layout(event):
            available = event.width - brand.winfo_reqwidth() - self.language_button.winfo_reqwidth() - self.unit*4
            compact = available < self.small_font.measure("Prompt + processed audio")
            brand.grid(row=0, column=0, rowspan=1 if compact else 2, sticky="w")
            self.language_button.grid(row=0, column=2, rowspan=1 if compact else 2, sticky="e")
            native.grid(row=1 if compact else 0, column=0 if compact else 1, columnspan=3 if compact else 1, sticky="w",
                        padx=0 if compact else self.unit*2, pady=(self.unit//2 if compact else 0, 0))
            subtitle.grid(row=2 if compact else 1, column=0 if compact else 1, columnspan=3 if compact else 1, sticky="ew",
                          padx=0 if compact else self.unit*2)
            subtitle.configure(wraplength=max(self.unit, event.width if compact else available))
        top.bind("<Configure>", layout)
        layout(types.SimpleNamespace(width=self.root.winfo_width()))

    def build_controls(self):
        panel = self.tk.Frame(self.body, bg=self.palette["panel"], padx=self.unit, pady=self.unit, highlightthickness=1, highlightbackground=self.palette["border"])
        panel.grid(row=1, column=0, sticky="ew")
        panel.grid_columnconfigure(1, weight=1)
        self.label(panel, key="folder", fg=self.palette["muted"], font=self.small_font).grid(row=0, column=0, sticky="w", padx=(0, self.unit))
        self.folder_var = self.tk.StringVar(value=tr("empty_folder", self.language))
        self.folder_entry = self.tk.Entry(panel, textvariable=self.folder_var, state="readonly", readonlybackground=self.palette["panel"], fg=self.palette["text"], relief="flat", bd=0, highlightthickness=0)
        self.folder_entry.grid(row=0, column=1, sticky="ew", padx=self.unit)
        self.folder_entry.configure(width=1)
        self.choose_button = self.button(panel, self.choose, key="choose", pady=max(3, self.unit//2))
        self.choose_button.grid(row=0, column=2, sticky="e")
        self.label(panel, key="prompt", fg=self.palette["muted"], font=self.small_font).grid(row=1, column=0, sticky="nw", pady=(self.unit, 0))
        self.prompt = self.tk.Text(panel, height=2, width=1, wrap="word", undo=True, maxundo=max(1, os.cpu_count() or 1), bg=self.palette["field"], fg=self.palette["text"],
                                   insertbackground=self.palette["accent"], selectbackground=self.palette["border"], relief="flat", bd=0, padx=self.unit, pady=self.unit//2,
                                   highlightthickness=1, highlightbackground=self.palette["border"], highlightcolor=self.palette["accent"])
        self.prompt.grid(row=1, column=1, columnspan=2, sticky="ew", padx=(self.unit, 0), pady=(self.unit, 0))
        self.prompt.insert("1.0", tr("default_prompt", self.language))
        self.prompt.bind("<<Modified>>", self.prompt_changed)
        self.prompt.bind("<Tab>", lambda event: self.focus_next(event, False))
        self.prompt.bind("<Shift-Tab>", lambda event: self.focus_next(event, True))
        self.prompt.edit_modified(False)
        actions = self.tk.Frame(panel, bg=self.palette["panel"])
        actions.grid(row=2, column=0, columnspan=2, sticky="w", pady=(self.unit, 0))
        self.retry_button = self.button(actions, self.recheck, key="recheck", pady=max(3, self.unit // 2))
        self.retry_button.grid(row=0, column=0, sticky="w")
        self.fault_button = self.button(actions, self.show_fault, key="open_fault", pady=max(3, self.unit // 2))
        self.fault_button.grid(row=0, column=1, sticky="w", padx=(self.unit, 0))
        self.fault_button.grid_remove()
        self.learning_button = self.button(panel, self.show_learning, key="learning_setup", pady=max(3, self.unit // 2))
        if os.environ.get("YUAN_PUBLISHER") == "1":
            self.learning_button.grid(row=2, column=2, sticky="e", pady=(self.unit, 0))

    def build_hero(self):
        self.hero = self.tk.Frame(self.body, bg=self.palette["bg"], pady=self.unit)
        self.hero.grid(row=2, column=0, sticky="ew")
        self.hero.grid_columnconfigure(1, weight=1)
        self.orb = self.tk.Canvas(self.hero, width=self.unit*7, height=self.unit*7, bg=self.palette["bg"], highlightthickness=0)
        self.orb.grid(row=0, column=0, rowspan=3, sticky="w", padx=(0, self.unit))
        self.status_label = self.label(self.hero, font=self.heading_font)
        self.status_label.grid(row=0, column=1, sticky="sw")
        self.status_detail = self.label(self.hero, key="full_duplex", fg=self.palette["muted"], font=self.small_font)
        self.status_detail.grid(row=1, column=1, sticky="new", pady=(self.unit//2, 0))
        self.model_blocker_label = self.label(self.hero, fg=self.palette["warning"], font=self.bold_font)
        self.model_blocker_label.grid(row=2, column=1, sticky="ew", pady=(self.unit//2, 0))
        self.model_blocker_label.grid_remove()
        self.action = self.button(self.hero, self.toggle, key="start", primary=True, padx=self.unit*3, pady=self.unit*2)
        self.action.grid(row=0, column=2, rowspan=3, sticky="e", padx=(self.unit, 0))
        def layout(event):
            available = event.width - self.orb.winfo_reqwidth() - self.action.winfo_reqwidth() - self.unit*2
            compact = available < self.heading_font.measure(tr("ended", self.language))
            self.action.grid_configure(row=3 if compact else 0, column=0 if compact else 2, columnspan=3 if compact else 1,
                                       rowspan=1 if compact else 3, sticky="ew" if compact else "e", padx=0 if compact else (self.unit, 0), pady=(self.unit, 0) if compact else 0)
            for widget in (self.status_label, self.status_detail, self.model_blocker_label):
                if widget is not self.model_blocker_label or widget.cget("text"):
                    widget.grid_configure(columnspan=2 if compact else 1)
                widget.configure(wraplength=max(self.unit, event.width-self.orb.winfo_reqwidth()-self.unit if compact else available))
        self.hero.bind("<Configure>", layout)
        progress_frame = self.tk.Frame(self.body, bg=self.palette["bg"])
        progress_frame.grid(row=3, column=0, sticky="ew", pady=(0, self.unit))
        progress_frame.grid_columnconfigure(0, weight=1)
        track = self.tk.Frame(progress_frame, bg=self.palette["bg"], height=max(2, self.unit//3))
        track.grid(row=0, column=0, sticky="ew")
        track.pack_propagate(False)
        self.progress = self.ttk.Progressbar(track, style="Yuan.Horizontal.TProgressbar", maximum=1.0)
        track.configure(height=max(self.progress.winfo_reqheight(), math.ceil(self.unit / 2)))
        self.progress.pack(fill="both", expand=True)
        self.progress_label = self.label(progress_frame, text="", fg=self.palette["muted"], font=self.small_font)
        self.progress_label.grid(row=1, column=0, sticky="ew", pady=(self.unit//2, 0))
        progress_frame.bind("<Configure>", lambda event: self.progress_label.configure(wraplength=max(self.unit*4, event.width)))

    def build_cards(self):
        self.cards_frame = self.tk.Frame(self.body, bg=self.palette["bg"])
        self.cards_frame.grid(row=4, column=0, sticky="nsew")
        self.cards = {}
        self.card_rows = {}
        self.card_columns = 0
        for key in ("devices", "model", "audio", "learning", "storage", "resources"):
            frame = self.tk.Frame(self.cards_frame, bg=self.palette["panel"], highlightthickness=1, highlightbackground=self.palette["border"], padx=self.unit, pady=max(3, self.unit//2))
            frame.grid_columnconfigure(0, weight=1)
            self.label(frame, key=key, fg=self.palette["accent"] if key in ("model", "learning") else self.palette["lavender"], font=self.bold_font).grid(row=0, column=0, sticky="w", pady=(0, self.unit//2))
            rows = []
            for index in range(4):
                widget = self.label(frame, text="—", font=self.small_font, fg=self.palette["text"] if index == 0 else self.palette["muted"])
                widget.grid(row=index+1, column=0, sticky="ew", pady=0)
                rows.append(widget)
            frame.bind("<Configure>", lambda event, labels=rows: [label.configure(wraplength=max(self.unit*4, event.width-self.unit*2)) for label in labels])
            self.cards[key] = frame
            self.card_rows[key] = rows
        self.layout_cards(3)

    def build_footer(self):
        bottom = self.tk.Frame(self.body, bg=self.palette["bg"])
        bottom.grid(row=5, column=0, sticky="ew", pady=(self.unit, 0))
        bottom.grid_columnconfigure(0, weight=1)
        self.notice = self.label(bottom, fg=self.palette["warning"], font=self.small_font)
        self.notice.grid(row=0, column=0, sticky="ew", pady=(0, self.unit//2))
        self.privacy = self.label(bottom, key="privacy", fg=self.palette["muted"], font=self.small_font)
        self.privacy.grid(row=1, column=0, sticky="ew")
        for widget in (self.notice, self.privacy):
            widget.bind("<Configure>", lambda event, target=widget: target.configure(wraplength=max(1, event.width)))
        self.dock = self.tk.Frame(self.root, bg=self.palette["panel"], padx=self.unit, pady=self.unit//2)
        self.dock.grid_columnconfigure(0, weight=1)
        self.dock_status = self.label(self.dock, fg=self.palette["text"])
        self.dock_status.grid(row=0, column=0, sticky="w")
        self.dock_action = self.button(self.dock, self.toggle, key="start", primary=True, pady=self.unit//2)
        self.dock_action.grid(row=0, column=1, sticky="e")
        self.dock.bind("<Configure>", lambda event: self.dock_status.configure(wraplength=max(self.unit, event.width-self.dock_action.winfo_reqwidth()-self.unit*3)))

    def build_activity(self):
        panel = self.tk.Frame(self.body, bg=self.palette["panel"], padx=self.unit, pady=self.unit, highlightthickness=1, highlightbackground=self.palette["border"])
        panel.grid(row=6, column=0, sticky="nsew", pady=(self.unit, 0))
        panel.grid_columnconfigure(0, weight=1)
        panel.grid_rowconfigure(1, weight=1)
        self.label(panel, key="activity", fg=self.palette["accent"], font=self.bold_font).grid(row=0, column=0, sticky="w")
        self.button(panel, self.show_activity, key="all_activity", pady=self.unit//2).grid(row=0, column=1, sticky="e")
        self.activity_text = self.tk.Text(panel, height=1, width=1, wrap="word", bg=self.palette["field"], fg=self.palette["text"], relief="flat", bd=0, font=self.small_font, padx=self.unit, pady=self.unit, state="disabled")
        self.activity_text.grid(row=1, column=0, columnspan=2, sticky="nsew", pady=(self.unit, 0))


    def record_activity(self, event):
        if event.get("type") not in ("status", "error", "notice", "deployment", "learning", "network", "recovery"):
            return
        event = {key: event[key] for key in ("at", "type", "key", "reason", "action_key") if key in event}
        self.recent_activity.append(event)
        limit = max(1, self.root.winfo_screenheight() // max(1, self.small_font.metrics("linespace")))
        while len(self.recent_activity) > limit:
            self.recent_activity.popleft()
        self.render_activity()

    def render_activity(self):
        text = self.activity_text
        text.configure(state="normal")
        text.delete("1.0", "end")
        for event in self.recent_activity:
            text.insert("end", event_text(event, self.language, compact=True))
        text.see("end")
        text.configure(state="disabled")

    def show_fault(self):
        from tkinter import messagebox
        fault = self.recovery_value.get("fault") or self.current_failure.get("fault", {})
        category = fault.get("category", "unknown")
        reason = local_message(fault.get("reason", tr("action_unknown", self.language)), self.language)
        action = tr(self.recovery_value.get("action_key", "action_" + category), self.language)
        messagebox.showwarning(APP_NAME, reason + "\n" + action, parent=self.root)

    def show_activity(self):
        if not self.launcher:
            return
        if self.activity_window and self.activity_window.winfo_exists():
            self.activity_window.lift()
            return
        from tkinter import scrolledtext
        window = self.tk.Toplevel(self.root)
        self.activity_window = window
        window.title(tr("all_activity", self.language))
        window.configure(bg=self.palette["bg"])
        window.geometry(f"{max(1, self.root.winfo_width())}x{max(1, self.root.winfo_height())}")
        bar = self.tk.Frame(window, bg=self.palette["panel"])
        bar.pack(fill="x")
        text = scrolledtext.ScrolledText(window, wrap="word", font=self.small_font, bg=self.palette["field"], fg=self.palette["text"],
                                         insertbackground=self.palette["accent"], relief="flat")
        text.pack(fill="both", expand=True)
        position = {"before": None, "trail": [], "first": None, "live": True, "last": None}
        store = self.launcher.activity
        def render():
            if not window.winfo_exists() or store.closed:
                return
            limit = max(1, window.winfo_height() // max(1, self.small_font.metrics("linespace")))
            try:
                rows = store.page(position["before"], limit)
            except (sqlite3.Error, OSError) as exc:
                rows = [(0, {"type": "error", "reason": concise_error(exc)})]
            marker = (rows[-1][0] if rows else None, position["before"], self.language)
            if marker != position["last"]:
                position["first"] = rows[0][0] if rows else None
                position["last"] = marker
                text.configure(state="normal")
                text.delete("1.0", "end")
                text.insert("1.0", "\n".join(event_text(event, self.language, compact=True) for _, event in rows))
                text.configure(state="disabled")
                if position["live"]:
                    text.see("end")
            self.root.after(max(1, int(math.sqrt(tick()) * 1000)), render)
        def earlier():
            if position["first"] is not None:
                position["trail"].append(position["before"])
                position["before"] = position["first"]
                position["live"] = False
        def later():
            position["before"] = position["trail"].pop() if position["trail"] else None
            position["live"] = position["before"] is None
        def live():
            position.update(before=None, trail=[], live=True, last=None)
        for key, command in (("older", earlier), ("newer", later), ("live", live)):
            self.button(bar, command, text=tr(key, self.language), pady=self.unit//2).pack(side="left", padx=self.unit//2, pady=self.unit//2)
        text.bind("<MouseWheel>", lambda event: position.update(live=False))
        render()

    def layout_cards(self, columns):
        if columns == self.card_columns:
            return
        for column in range(3):
            self.cards_frame.grid_columnconfigure(column, weight=1 if column < columns else 0, uniform="cards" if column < columns else "")
        for index, frame in enumerate(self.cards.values()):
            frame.grid(row=index//columns, column=index%columns, sticky="nsew", padx=(0 if index%columns == 0 else self.unit//2, 0 if index%columns == columns-1 else self.unit//2), pady=self.unit//2)
        self.card_columns = columns

    def resize(self, event):
        self.viewport.itemconfigure(self.body_window, width=event.width)
        self.layout_cards(3 if event.width >= self.font.measure("M") * 82 else 2 if event.width >= self.font.measure("M") * 56 else 1)
        self.root.after_idle(self.measure)


    def measure(self, event=None):
        required = self.body.winfo_reqheight()
        available = self.viewport.winfo_height()
        self.viewport.itemconfigure(self.body_window, height=max(required, available))
        self.viewport.configure(scrollregion=self.viewport.bbox("all"))
        needs_scroll = required > self.root.winfo_height()
        if needs_scroll:
            self.scrollbar.grid(row=0, column=1, sticky="ns")
            self.dock.grid(row=1, column=0, columnspan=2, sticky="ew")
        else:
            self.scrollbar.grid_remove()
            self.dock.grid_remove()
            self.viewport.yview_moveto(0)


    def wheel(self, event):
        if event.widget is self.prompt or event.widget is self.activity_text or event.widget.winfo_toplevel() is not self.root:
            return
        if self.body.winfo_reqheight() <= self.viewport.winfo_height():
            return
        delta = -1 if getattr(event, "num", None) == 4 or getattr(event, "delta", 0) > 0 else 1
        self.viewport.yview_scroll(delta, "units")

    def focus_next(self, event, reverse):
        (event.widget.tk_focusPrev() if reverse else event.widget.tk_focusNext()).focus_set()
        return "break"

    def localize(self):
        self.bound = [(widget, key) for widget, key in self.bound if widget.winfo_exists()]
        for widget, key in self.bound:
            widget.configure(text=tr(key, self.language))
        if self.workspace is None:
            self.folder_var.set(tr("empty_folder", self.language))
        self.language_button.configure(text="中文  /  EN" if self.language == "中文" else "EN  /  中文")
        self.render_activity()
        self.refresh()

    def switch_language(self):
        old_default = tr("default_prompt", self.language)
        current = self.prompt.get("1.0", "end-1c")
        self.language = "English" if self.language == "中文" else "中文"
        if not self.session_id and current == old_default:
            self.prompt.delete("1.0", "end")
            self.prompt.insert("1.0", tr("default_prompt", self.language))
        if self.launcher:
            self.launcher.send({"action": "language", "language": self.language})
        self.save_settings()
        self.localize()

    def prompt_changed(self, event=None):
        if self.prompt.edit_modified():
            self.prompt.edit_modified(False)
            if self.save_job:
                self.root.after_cancel(self.save_job)
            self.save_job = self.root.after(max(1, int(math.sqrt(tick()) * 1000)), self.save_settings)

    def save_settings(self):
        if self.save_job is not None:
            self.root.after_cancel(self.save_job)
            self.save_job = None
        if self.workspace is None:
            return True
        payload = {"prompt": self.prompt.get("1.0", "end-1c"), "language": self.language}
        if payload == self.last_saved_prompt:
            return True
        try:
            atomic_json(workspace_state(self.workspace) / "settings.json", payload)
            self.last_saved_prompt = payload
            return True
        except (OSError, ValueError, YuanError) as exc:
            self.reason = concise_error(exc)
            self.refresh()
            return False

    def recheck(self):
        if self.closing or self.session_id or not self.workspace or self.launcher and self.launcher.process_retained:
            return
        if self.launcher and self.launcher.thread.is_alive():
            if self.launcher.request_recheck():
                self.notice_key = "recheck_requested"
        else:
            try:
                gate = RecoveryGate(workspace_state(self.workspace), lambda *args, **kwargs: None)
                gate.reset("recheck_requested")
                self.open_workspace(self.workspace)
            except Exception as exc:
                self.reason = concise_error(exc)
        self.refresh()

    def choose(self):
        from tkinter import filedialog
        if self.session_id or self.closing or self.launcher and self.launcher.process_retained:
            return
        selected = filedialog.askdirectory(parent=self.root, title=tr("choose", self.language), mustexist=True, initialdir=str(self.workspace) if self.workspace else None)
        if not selected:
            return
        selected = Path(selected).resolve()
        if selected == self.workspace and self.launcher and self.launcher.thread.is_alive():
            return
        if not self.save_settings():
            return
        self.pending_workspace = selected
        self.ready = False
        self.runtime_ready = False
        self.readiness_values = {}
        if self.launcher and self.launcher.thread.is_alive():
            self.status_key = "closed"
            self.launcher.stop()
            self.choose_button.configure(state="disabled")
        else:
            self.open_workspace(selected)
        self.refresh()

    def open_workspace(self, workspace):
        self.pending_workspace = None
        workspace = Path(workspace).expanduser().resolve()
        if not self.save_settings():
            return
        lease = None
        try:
            state = workspace_state(workspace)
            state.mkdir(parents=True, exist_ok=True)
            fd, test = tempfile.mkstemp(dir=state)
            os.close(fd)
            os.unlink(test)
            lease = WorkspaceLease(state / "workspace.lock")
            prompt = self.prompt.get("1.0", "end-1c") if self.workspace is None or workspace == self.workspace else None
            settings = workspace_settings(state, self.language, prompt)
        except (OSError, YuanError) as exc:
            if lease is not None:
                lease.close()
            self.reason = concise_error(exc)
            self.status_key = "failure"
            self.refresh()
            return
        if self.launcher and not self.launcher.thread.is_alive():
            self.launcher.activity.close()
        if self.activity_window and self.activity_window.winfo_exists():
            self.activity_window.destroy()
        for window in (self.learning_window, self.review_window):
            if window and window.winfo_exists():
                window.destroy()
        self.workspace = workspace
        self.folder_var.set(str(workspace))
        self.last_saved_prompt = None
        self.language = settings["language"]
        self.prompt.configure(state="normal")
        self.prompt.delete("1.0", "end")
        self.prompt.insert("1.0", settings["prompt"])
        self.prompt.edit_modified(False)
        self.reason = ""
        self.notice_key = ""
        self.model_values, self.device_values, self.learning_values, self.resource_values, self.audio_values, self.progress_value = {}, {}, {}, {}, {}, {}
        self.pipeline_verified = False
        self.phase_values = {}
        self.source_values = {}
        self.learning_key = "waiting_data"
        self.network_key = "wait"
        self.recent_activity.clear()
        self.activity_text.configure(state="normal")
        self.activity_text.delete("1.0", "end")
        self.activity_text.configure(state="disabled")
        self.ready = False
        self.runtime_ready = False
        self.readiness_values = {}
        self.generation += 1
        self.attempt_id = None
        self.attempt_number = 0
        self.event_sequence = 0
        self.phase_id = None
        self.supervision_value = {}
        self.current_failure = {}
        self.last_failure = {}
        self.recovery_value = {}
        self.startup_values = {}
        self.deployment_value = {}
        self.notice_context = None
        self.status_key = "setup"
        self.save_settings()
        try:
            self.launcher = Launcher(workspace, self.generation, self.mailbox, lease=lease)
        except Exception as exc:
            lease.close()
            self.launcher = None
            self.status_key = "failure"
            self.reason = concise_error(exc)
        self.choose_button.configure(state="normal")
        self.localize()

    def can_start(self):
        return bool(not self.closing and not self.ending and not self.pending_workspace and self.workspace and self.launcher
                    and self.launcher.thread.is_alive() and self.ready and can_converse(self.readiness_values)
                    and self.readiness_values.get("storage_ready") is True)

    def toggle(self):
        from tkinter import messagebox
        if self.closing or self.ending:
            return
        if self.session_id:
            if not messagebox.askyesno(tr("confirm_title", self.language), tr("confirm_stop", self.language), parent=self.root):
                return
            self.ending = True
            self.status_key = "ending"
            self.level = 0.0
            if not self.launcher or not self.launcher.send({"action": "stop", "id": self.session_id}):
                self.notice_key = "stop_incomplete"
                self.ready = False
                self.readiness_values = {}
                if self.launcher:
                    self.launcher.stop()
        elif self.can_start():
            for window in (self.learning_window, self.review_window):
                if window and window.winfo_exists():
                    window.destroy()
            value = self.prompt.get("1.0", "end-1c").strip()
            if not value:
                value = tr("default_prompt", self.language)
                self.prompt.insert("1.0", value)
                self.notice_key = "no_prompt"
            if not self.save_settings():
                return
            session_id = uuid.uuid4().hex
            action = {"action": "start", "id": session_id, "prompt": value, "language": self.language}
            if self.launcher.send(action):
                self.session_id = session_id
                self.status_key = "connecting"
                self.ending = False
                self.audio_values = {"turns": 0}
                self.reason = ""
            else:
                self.notice_key = "command_failed"
        self.refresh()

    def finish_session(self):
        if self.session_started:
            self.audio_values["elapsed"] = time.monotonic() - self.session_started
        self.session_id = None
        self.session_started = None
        self.ending = False
        self.status_key = "ended"
        self.phase_values = {}
        self.device_values["continuous_active"] = False
        self.audio_values.update(continuous=False, speech_active=False, recorded=0.0)
        self.level = 0.0

    def close(self):
        from tkinter import messagebox
        if self.closing:
            return
        if self.session_id and not messagebox.askyesno(tr("confirm_title", self.language), tr("confirm_close", self.language), parent=self.root):
            return
        self.closing = True
        self.ready = False
        self.save_settings()
        self.status_key = "closed"
        if self.launcher and self.launcher.thread.is_alive():
            self.launcher.stop()
        else:
            if self.launcher:
                self.launcher.activity.close()
            self.destroy()
            return
        self.refresh()

    def destroy(self):
        self.progress.stop()
        for identifier in self.root.tk.call("after", "info"):
            self.root.tk.call("after", "cancel", identifier)
        self.root.destroy()

    def callback_error(self, kind, value, traceback):
        self.reason = concise_error(value)
        try:
            self.refresh()
        except Exception:
            pass

    def handle(self, event):
            kind = event.get("type")
            if not self.interface.apply(event, self.generation, self.session_id, self.closing, self.ending):
                return
            if kind == "attempt":
                number = event.get("attempt_number", 0)
                if self.current_failure:
                    self.last_failure = dict(self.current_failure)
                self.current_failure = {}
                self.recovery_value = {}
                self.startup_values = {}
                self.deployment_value = {}
                self.notice_context = None
                self.attempt_id = event.get("attempt_id")
                self.attempt_number = number
                self.event_sequence = 0
                self.phase_id = None
                self.supervision_value = {}
                self.reason = self.notice_key = ""
                self.ready = self.runtime_ready = self.pipeline_verified = False
                self.readiness_values = {}
                self.progress_value = self.phase_values = {}
                self.model_values = {}
                self.device_values = {}
                self.resource_values = {}
                self.learning_values = {}
                self.learning_key = "waiting_data"
                self.network_key = "wait"
                self.source_values = {}
                if self.session_id:
                    self.finish_session()
                    self.notice_key = "stop_incomplete"
                if not self.closing:
                    self.status_key = "setup"
            self.event_sequence = self.interface.sequence
            self.record_activity(event)
            if kind == "status":
                phase_id = event.get("phase_id")
                if phase_id != self.phase_id or event.get("key") != self.status_key:
                    self.progress_value = {}
                    self.phase_values = {}
                    self.supervision_value = {}
                self.phase_id = phase_id
                if self.current_failure and event.get("key") not in ("retry", "failure", "startup_blocked", "network_wait"):
                    self.last_failure = dict(self.current_failure)
                    self.current_failure = {}
                    self.notice_key = self.reason = ""
                if not self.ending and not self.closing:
                    self.status_key = event.get("key", self.status_key)
            elif kind == "recovery":
                self.recovery_value = dict(event)
                if event.get("blocked"):
                    self.progress_value = {}
                    self.phase_values = {}
                    self.supervision_value = {}
            elif kind == "startup_resources":
                self.startup_values = dict(event)
            elif kind == "runtime_profile":
                self.startup_values.update({key: event[key] for key in ("executable", "python", "machine") if key in event})
                if event.get("compute_backend"):
                    self.model_values["device"] = event["compute_backend"]
                hardware = event.get("hardware", {})
                adapters = hardware.get("adapters", [])
                if adapters:
                    self.model_values["architecture"] = " · ".join(item.get("name", item.get("vendor", "")) for item in adapters)
            elif kind == "hardware":
                adapters = event.get("hardware", {}).get("adapters", [])
                if adapters:
                    self.model_values["architecture"] = " · ".join(item.get("name", item.get("vendor", "")) for item in adapters)
            elif kind == "accelerators":
                devices = event.get("devices", [])
                if devices:
                    self.model_values["device"] = " · ".join(item["device"] for item in devices)
                    self.model_values["architecture"] = " · ".join(item["name"] for item in devices)
            elif kind == "deployment_preflight":
                self.deployment_value = dict(event)
            elif kind == "download_complete":
                context = (event.get("attempt_id"), event.get("phase_id"), event.get("artifact_id"))
                if self.notice_context == context and not self.current_failure:
                    self.notice_key = self.reason = ""
                    self.notice_context = None
            elif kind == "process_reaped" and event.get("scope") == "runtime_probe":
                self.startup_values.update(process_running=False, pid=None)
            elif kind == "supervision":
                self.supervision_value = {} if event.get("complete") else {**event, "received_at": time.monotonic()}
            elif kind == "progress":
                if event.get("phase_id") != self.phase_id:
                    return
                if not event.get("phase_id") and event.get("key") != self.status_key:
                    return
                self.progress_value = event
            elif kind == "source_progress":
                self.source_values = event
            elif kind == "phase":
                if event.get("phase_id") != self.phase_id:
                    return
                self.phase_values = event
            elif kind == "ready":
                if self.closing:
                    return
                self.model_values.update({key: event[key] for key in ("capability", "acoustic_ready", "dialogue_trained", "dialogue_ready", "playback_ready", "conversation_verified") if key in event})
                self.model_values.setdefault("capability", "cold_start")
                self.runtime_ready = True
                self.status_key = "preparing_model"
                self.progress_value = {}
                self.phase_values = {}
            elif kind == "readiness":
                self.readiness_values = dict(self.interface.readiness)
                self.runtime_ready = bool(event.get("runtime_ready"))
                self.ready, next_status = readiness_view(event, self.closing)
                if event.get("capability"):
                    self.model_values["capability"] = event["capability"]
                if not self.session_id and not self.closing and not self.ending:
                    self.status_key = next_status or self.status_key
                if self.ready and self.notice_key in ("start_rejected", "mic_missing", "release_invalid", "owned_release_missing"):
                    self.notice_key = self.reason = ""
            elif kind == "review_snapshot":
                self.show_review(event)
            elif kind == "storage_state":
                self.resource_values["storage"] = dict(event)
            elif kind == "pipeline":
                self.pipeline_verified = bool(event.get("verified"))
                if "conversation_verified" in event:
                    self.model_values["conversation_verified"] = bool(event.get("conversation_verified"))
            elif kind == "started":
                if event.get("id") != self.session_id:
                    return
                self.learning_key = "learn_yield"
                self.phase_values = {}
                self.session_started = time.monotonic()
                self.device_values["continuous_active"] = bool(event.get("continuous"))
                if not self.ending and not self.closing:
                    self.status_key = "listening" if event.get("continuous") else "connecting"
            elif kind == "ended":
                if event.get("id") == self.session_id:
                    self.finish_session()
                    if event.get("storage_complete") is False or event.get("capture_complete") is False:
                        self.notice_key = "stop_incomplete"
                        self.audio_values["storage_complete"] = False
            elif kind == "devices":
                self.device_values.update(event)
            elif kind == "model":
                self.model_values.update(event)
            elif kind in ("audio", "turn"):
                if kind == "turn" and event.get("id") != self.session_id:
                    return
                self.audio_values.update(event)
                if kind == "turn":
                    self.phase_values = {}
                if event.get("continuous") is not None:
                    self.device_values["continuous_active"] = bool(event["continuous"])
                if not self.ending:
                    self.level = max(0.0, min(1.0, float(event.get("level", 0.0))))
            elif kind == "generation_end":
                self.audio_values["generation_end"] = event.get("key")
            elif kind == "learning":
                self.learning_values.update(event)
                self.learning_key = event.get("key", self.learning_key)
                if self.phase_values.get("key") in ("validating", "checkpointing") and self.learning_key not in ("validating",):
                    self.phase_values = {}
                for key in ("accepted", "acoustic_ready", "dialogue_trained", "dialogue_ready", "playback_ready", "capability"):
                    if key in event:
                        self.model_values[key] = event[key]
                if "capability" not in event:
                    self.model_values["capability"] = ("dialogue_benchmark_ready" if self.readiness_values.get("evidence_scope") == CapabilityEvidence.dialogue_scope else "dialogue_ready") if self.model_values.get("playback_ready") and self.model_values.get("dialogue_ready") else "release_wait" if self.model_values.get("dialogue_trained") else "acoustic_only" if self.model_values.get("acoustic_ready") else "cold_start"
                if event.get("key") == "promoted" and self.notice_key == "collecting":
                    self.notice_key = ""
                if event.get("reason"):
                    self.reason = event["reason"]
            elif kind == "checkpoint_saved":
                if self.phase_values.get("key") == "checkpointing":
                    self.phase_values = {}
            elif kind == "network":
                self.network_key = event.get("key", self.network_key)
                if self.network_key == "available" and self.phase_values.get("key") == "network":
                    self.phase_values = {}
                if event.get("reason"):
                    self.reason = event["reason"]
            elif kind == "metrics":
                self.resource_values.update(event)
                capture = event.get("capture")
                if isinstance(capture, dict) and capture.get("id") == self.session_id:
                    self.audio_values.update(capture)
                    self.device_values["continuous_active"] = bool(capture.get("continuous"))
            elif kind in ("notice", "error"):
                self.notice_context = (event.get("attempt_id"), event.get("phase_id"), event.get("artifact_id")) if event.get("component") == "runtime_download" and event.get("artifact_id") else None
                self.notice_key = event.get("key", "")
                self.reason = event.get("reason") or ""
                if kind == "error" and event.get("fatal") is not False:
                    self.current_failure = dict(event)
                    self.ready = self.runtime_ready = self.pipeline_verified = False
                    self.readiness_values = {}
                    self.progress_value = {}
                    self.phase_values = {}
                    self.supervision_value = {}
                    self.status_key = "failure"
            elif kind in ("exit", "disconnected", "process_reaped"):
                self.runtime_ready = False
                self.readiness_values = {}
                self.ready = False
                self.pipeline_verified = False
                self.device_values["continuous_active"] = False
                self.audio_values.update(continuous=False, speech_active=False, level=0.0)
                self.level = 0.0
                self.phase_values = {}
                self.progress_value = {}
                self.supervision_value = {}
                if self.session_id:
                    self.finish_session()
                    self.notice_key = "stop_incomplete"
                if not self.closing:
                    self.status_key = "retry"
            elif kind == "launcher_closed":
                if event.get("process_retained"):
                    self.closing = False
                    self.pending_workspace = None
                    self.status_key = "failure"
                    self.choose_button.configure(state="disabled")
                    return
                if self.closing:
                    if self.launcher:
                        self.launcher.activity.close()
                    self.destroy()
                    return
                if self.pending_workspace:
                    if self.launcher and self.launcher.thread.is_alive():
                        self.root.after(max(1, int(math.sqrt(tick()) * 1000)), lambda: self.handle({"type": "launcher_closed"}))
                        return
                    self.open_workspace(self.pending_workspace)
                self.choose_button.configure(state="normal")

    def card(self, key, lines):
        for widget, text in zip(self.card_rows[key], lines):
            widget.configure(text=str(text))

    def refresh(self):
        language = self.language
        translate = lambda key: tr(key, language)
        status = translate(self.status_key) if self.workspace else translate("title")
        self.status_label.configure(text=status)
        self.dock_status.configure(text=status)
        flags = self.readiness_values
        readiness = " · ".join(("✓ " if flags.get(key) else "○ ") + translate(label) for key, label in (("runtime_ready", "environment"), ("pipeline_ready", "pipeline_ok"), ("audio_ready", "devices"), ("model_ready", "acceptance"), ("storage_ready", "storage_health"), ("learning_ready", "learning_ready")))
        detail = translate("empty_folder") if self.workspace is None else readiness + "\n" + translate(self.model_values.get("capability", "cold_start")) if self.runtime_ready else translate("subtitle")
        blocker = ""
        if self.workspace and not self.runtime_ready and self.deployment_value:
            if not self.deployment_value.get("source_configured"):
                blocker = translate(self.deployment_value.get("key", "owned_source_absent"))
            else:
                detail += "\n" + translate(self.deployment_value.get("key", "owned_source_found"))
        learning_state = flags.get("learning", {})
        if self.runtime_ready and not flags.get("model_ready"):
            if flags.get("model_blocker") in ("native_learning", "dialogue_data_missing", "acceptance_data_missing", "reference_data_missing"):
                detail = readiness
                blocker = translate("native_unverified" if flags.get("model_blocker") == "native_learning" else flags["model_blocker"])
            if flags.get("model_detail"):
                detail += "\n" + local_message(flags["model_detail"], language)
            if os.environ.get("YUAN_PUBLISHER") == "1":
                missing = learning_state.get("missing", [])
                if missing:
                    detail += "\n" + translate("missing_data") + ": " + "; ".join(f"{row['language']} {row['split']} {row.get('scenario') or 'pairs'} {row['have']}/{row['need']}" for row in missing)
                if learning_state.get("review_pending"):
                    detail += "\n" + translate("review_open")
            else:
                missing = learning_state.get("missing", [])
                if missing and flags.get("model_blocker") != "dialogue_data_missing":
                    detail += "\n" + translate("native_data_needed")
                elif not missing and learning_state.get("review_pending"):
                    detail += "\n" + translate("release_wait")
        self.model_blocker_label.configure(text=blocker)
        if blocker:
            self.model_blocker_label.grid()
        else:
            self.model_blocker_label.grid_remove()
        recovering = bool(self.launcher and self.launcher.blocked.is_set())
        retained = bool(self.launcher and self.launcher.process_retained)
        can_recheck = bool(self.workspace and not self.closing and not self.session_id and not retained and
                           (recovering or self.launcher is None or not self.launcher.thread.is_alive()))
        self.retry_button.configure(state="normal" if can_recheck else "disabled")
        if can_recheck:
            self.retry_button.grid()
            self.retry_button.master.grid()
        else:
            self.retry_button.grid_remove()
            if not self.current_failure:
                self.retry_button.master.grid_remove()
        if recovering and self.recovery_value:
            recovery = self.recovery_value
            fault = recovery.get("fault", {})
            detail = translate("fault_" + fault.get("category", "unknown"))
            if fault.get("stage"):
                detail += " · " + translate(fault["stage"])
            reason = local_message(fault.get("reason", ""), language).split("\n", 1)[0][:240]
            if reason:
                detail += " · " + reason
            detail += "\n" + translate("recovery_action") + " · " + translate(recovery.get("action_key", "action_unknown"))
            if recovery.get("retry_blocker"):
                detail += "\n" + translate(recovery["retry_blocker"])
            detail += "\n" + translate("recovery_attempts") + f" {recovery.get('matching_failures', 0)}/{recovery.get('same_fault_limit', '—')} · " + translate("campaign_remaining") + " " + human_duration(recovery.get("remaining_seconds", 0))
            if recovery.get("transfer_remaining_seconds") is not None:
                detail += " · " + translate("download_campaign_remaining") + " " + human_duration(recovery["transfer_remaining_seconds"])
        if recovering and self.recovery_value.get("fault"):
            self.fault_button.master.grid()
            self.fault_button.grid()
        else:
            self.fault_button.grid_remove()
        self.learning_button.configure(state="normal" if self.runtime_ready and self.workspace and not self.session_id and not self.closing else "disabled")
        self.status_detail.configure(text=detail, fg=self.palette["accent"] if self.ready else self.palette["warning"] if self.runtime_ready else self.palette["muted"])
        button_key = "ending" if self.ending else "stop" if self.session_id else "start"
        enabled = not self.closing and not self.ending and bool(self.session_id or self.can_start())
        for button in (self.action, self.dock_action):
            button.configure(text=translate(button_key), state="normal" if enabled else "disabled", bg=(self.palette["warning"] if self.session_id else self.palette["accent"]) if enabled else self.palette["border"])
        self.prompt.configure(state="disabled" if self.session_id or self.closing else "normal")
        self.choose_button.configure(state="disabled" if self.session_id or self.closing or self.pending_workspace or retained else "normal")
        devices = self.device_values
        self.card("devices", [translate("input") + " · " + str(devices.get("input", "—")), translate("output") + " · " + str(devices.get("output", "—")),
                              f"{devices.get('input_rate', '—')} Hz → {devices.get('output_rate', '—')} Hz",
                              ("● " if devices.get("continuous_active") and self.session_id else "○ ") + translate("full_duplex")])
        model = self.model_values
        acoustic_state = ("✓ 声学" if language == "中文" else "✓ Acoustics") if model.get("acoustic_ready") else ("○ 声学" if language == "中文" else "○ Acoustics")
        dialogue_state = ("✓ 听测" if language == "中文" else "✓ Review") if model.get("dialogue_ready") else ("○ 听测" if language == "中文" else "○ Review")
        playback_state = ("✓ 播放" if language == "中文" else "✓ Play") if model.get("playback_ready") else ("○ 播放" if language == "中文" else "○ Play")
        pipeline_state = ("✓" if self.pipeline_verified else "○") + (" 链路" if language == "中文" else " Pipeline")
        self.card("model", [model.get("name", "Yuan Native Audio"), f"{model.get('device', '—')} · {model.get('dtype', '—')} · {model.get('size', '—')}",
                            model.get("architecture", "prompt + audio → audio") + "\n" + translate("serving_model") + " · " + str(flags.get("serving_model") or "—")[:12] + " / " + translate("candidate_model") + " · " + str(flags.get("learning_model") or "—")[:12],
                            f"{pipeline_state} · {acoustic_state} · {dialogue_state} · {playback_state}"])
        audio = self.audio_values
        elapsed = time.monotonic() - self.session_started if self.session_started else audio.get("elapsed", 0.0)
        latency = audio.get("latency")
        self.card("audio", [f"{audio.get('turns', 0)} {translate('turns')} · {int(elapsed)//60:02}:{int(elapsed)%60:02}",
                            f"{translate('input')} {float(audio.get('input_seconds', audio.get('recorded', 0))):.1f}s · {translate('output')} {float(audio.get('output_seconds', 0)):.1f}s",
                            ("响应 " if language == "中文" else "Response ") + (f"{latency:.2f}s" if latency is not None else "—") + (" · " + translate(audio["generation_end"]) if audio.get("generation_end") else ""),
                            f"{translate('input_faults')} {audio.get('input_faults', 0)} · {translate('output_faults')} {audio.get('output_faults', 0)} · {translate('pending')} {audio.get('pending', 0)} · {translate('storage_queue')} {audio.get('pending_storage', 0)}"])
        learning = self.learning_values
        learning_label = self.learning_key if self.model_values else "native_bootstrap" if self.workspace else "idle"
        self.card("learning", [translate(learning_label),
                               f"{translate('candidate_progress')} {learning_state.get('candidate_improvements', learning.get('accepted', 0))}",
                               f"{translate('serving_versions')} {learning_state.get('serving_versions', 0)}",
                               translate("contrast_pending") if learning_state.get("review_pending") else translate("candidate_isolated") if learning_state.get("candidate_isolated") else f"{translate('steps')} {learning.get('steps', 0)}"])
        resources = self.resource_values
        samples = resources.get("samples", {})
        local, public, dialogue = samples.get("local", {}), samples.get("public", {}), samples.get("dialogue", {})
        history = samples.get("history", {})
        learnable = sum(values.get("learnable", 0) for key, values in samples.items() if key != "dialogue")
        excluded = sum(values.get("excluded", 0) for key, values in samples.items() if key != "dialogue")
        pair_text = (("可训练配对 " if language == "中文" else "Trainable pairs ") + str(dialogue.get("supervised", 0)) + " · "
                     + ("已标注配对 " if language == "中文" else "Annotated pairs ")) + f"{dialogue.get('verified', 0)}/{dialogue.get('count', 0)} · T/V/G/R {dialogue.get('train', 0)}/{dialogue.get('validation', 0)}/{dialogue.get('guard', 0)}/{dialogue.get('release', 0)}"
        source = self.source_values
        network_detail = translate(self.network_key)
        if source and self.network_key not in ("offline", "source_paused"):
            network_detail += " · " + human_bytes(source.get("current", 0)) + " / " + (human_bytes(source["total"]) if source.get("total") else translate("unknown_total"))
        storage = resources.get("storage", {})
        space = resources.get("storage_budget", {})
        storage_line = (translate("reserved_storage") + " " + human_bytes(space.get("reserved_bytes", 0)) + " · ") + f"{translate('saved')} {storage.get('saved', 0)} · {translate('pending')} {storage.get('pending', 0)} · {translate('lost')} {storage.get('lost_seconds', 0):.1f}s"
        if storage.get("retrying"):
            storage_line += " · " + translate("storage_retry")
        storage_details = (("可学习 " if language == "中文" else "Learnable ") + str(learnable) + " · " + translate("excluded") + " " + str(excluded) + " · " + pair_text + "\n") if os.environ.get("YUAN_PUBLISHER") == "1" else ""
        self.card("storage", [f"{translate('local')} {local.get('count', 0)} · {float(local.get('seconds', 0))/60:.1f} min · {translate('history')} {history.get('count', 0)}",
                              f"{translate('public')} {public.get('count', 0)} · {float(public.get('seconds', 0))/60:.1f} min",
                              network_detail, storage_details + storage_line])
        cpu_text = f"{resources['cpu']:.1f}%" if isinstance(resources.get("cpu"), (int, float)) else "—"
        self.card("resources", [f"CPU {cpu_text} · Yuan {human_bytes(resources.get('process_ram'))}",
                                "RAM " + translate("available") + " " + human_bytes(resources.get("ram_available", 0)),
                                "GPU " + human_bytes(resources["gpu_used"]) + " / " + human_bytes(resources["gpu_total"]) if "gpu_used" in resources else "GPU —",
                                "Disk " + human_bytes(resources.get("disk_free", 0)) + " / " + human_bytes(resources.get("disk_total", 0))] if resources else ["—"] * len(self.card_rows["resources"]))
        if not self.runtime_ready and self.workspace:
            startup = self.startup_values
            running = startup.get("process_running") and not recovering
            task_active = startup.get("task_running") and not recovering
            task = translate("process_running" if running else "no_startup_task" if recovering else "task_running" if task_active else "process_idle")
            if task_active and not running and startup.get("task_kind"):
                task += " · " + translate(startup["task_kind"])
            if running and startup.get("pid"):
                task += " · PID " + str(startup["pid"])
            activity = startup.get("process_activity")
            activity_text = (f"CPU {activity[0]:.2f}s · I/O {human_bytes(activity[1])} / {human_bytes(activity[2])}" if activity else translate("monitor_unknown") if running else translate("not_measured"))
            disk_text = "Disk " + human_bytes(startup["disk_free"]) + " / " + human_bytes(startup["disk_total"]) if startup.get("disk_free") is not None else "Disk · " + translate("not_measured")
            executable = startup.get("executable")
            interpreter = Path(executable).name if executable else translate("not_measured")
            if not running:
                interpreter += " · " + translate("engine_waiting")
            self.card("resources", [task, interpreter, activity_text, disk_text])
        supervised = {} if recovering else self.supervision_value
        progress = {} if recovering else self.phase_values if self.phase_values.get("total") else self.progress_value
        if supervised:
            progress = {}
        batch = "overall_current" in progress
        total = progress.get("overall_total") if batch else progress.get("total")
        current = progress.get("overall_current", 0) if batch else progress.get("current", 0)
        if total:
            self.progress.stop()
            self.progress.configure(mode="determinate", value=max(0, min(1, current/total)))
            suffix = f" · {human_bytes(current)} / {human_bytes(total)}" if progress.get("unit", "bytes") == "bytes" else f" · {current} / {total}"
        else:
            suffix = ""
            if self.workspace and (supervised or not self.runtime_ready) and not self.closing and self.status_key not in ("failure", "retry", "startup_blocked", "network_wait"):
                if self.progress.cget("mode") != "indeterminate":
                    self.progress.configure(mode="indeterminate")
                    self.progress.start(max(1, int(math.sqrt(tick()) * 1000)))
            else:
                self.progress.stop()
                self.progress.configure(mode="determinate", value=1.0 if self.ready and can_converse(self.readiness_values) else 0.0)
        detail = str(progress.get("detail", ""))
        if self.phase_values and (self.runtime_ready or self.status_key in ("checking", "loading")):
            phase = self.phase_values
            detail = translate(phase.get("key", "wait"))
            if "current" in phase:
                detail += f" · {phase['current']} / {phase.get('total', '—')} {phase.get('unit', '')}"
            suffix = ""
        if not total and progress.get("unit", "bytes") == "bytes" and progress.get("current"):
            suffix = " · " + human_bytes(current) + " / " + translate("unknown_total")
        if progress.get("file"):
            detail = str(progress["file"]) + (" · " + detail if detail and detail != progress["file"] else "")
        if batch:
            overall = translate("download_overall") + " · " + human_bytes(current) + " / " + (human_bytes(total) if total is not None else translate("unknown_total"))
            overall += " · " + translate("download_files") + f" {progress.get('files_completed', 0)}/{progress.get('file_count', 0)}"
            if progress.get("active_files"):
                overall += " · " + translate("download_parallel") + " " + str(progress["active_files"])
            if progress.get("overall_speed") is not None:
                overall += " · " + translate("download_speed") + " " + human_bytes(progress["overall_speed"]) + "/s"
            if progress.get("files_completed", 0) < progress.get("file_count", 0):
                overall += " · " + (translate("download_estimate") + " ≈ " + human_duration(progress["eta_seconds"]) if progress.get("eta_seconds") is not None else translate("download_estimate_unknown"))
            detail = overall + "\n" + translate("download_current") + " · " + detail
            suffix = " · " + human_bytes(progress.get("current", 0)) + " / " + (human_bytes(progress["total"]) if progress.get("total") is not None else translate("unknown_total"))
        elif progress.get("file_count"):
            suffix += f" · {progress.get('file_index', 0)} / {progress['file_count']}"
        if progress.get("transfer_state"):
            suffix += " · " + translate(progress["transfer_state"])
        if progress.get("source"):
            suffix += " · " + str(progress["source"])
        if progress.get("download_attempt"):
            suffix += " · " + translate("download_attempts") + f" {progress['download_attempt']}/{progress.get('download_attempts', '—')}"
        if progress.get("connect_seconds") is not None and progress.get("transfer_state") == "download_connecting":
            suffix += " · " + translate("download_connection_budget") + f" {progress['connect_seconds']:.1f}s"
        if not batch and progress.get("speed") is not None:
            suffix += " · " + human_bytes(progress["speed"]) + "/s"
        if progress.get("last_progress_at") and not self.runtime_ready:
            suffix += " · " + translate("last_progress") + f" {max(0.0, time.time() - progress['last_progress_at']):.1f}s"
        if progress.get("remaining_seconds") is not None:
            suffix += " · " + translate("remaining") + f" {max(0.0, progress['remaining_seconds']):.1f}s"
        if progress.get("monitor_available") is False:
            suffix += " · " + translate("monitor_unknown")
        if self.launcher and not self.runtime_ready:
            if recovering:
                mode = self.recovery_value.get("mode")
                detail = translate("retry_next_action" if mode == "automatic_retry" else "waiting_conditions" if mode == "waiting_conditions" else "no_startup_task")
                suffix = ""
                if mode == "automatic_retry" and self.launcher.retry_until is not None:
                    detail += "\n" + translate("backoff") + f" · {max(0, self.launcher.retry_until-time.monotonic()):.1f}s"
            elif self.status_key not in ("failure", "startup_blocked", "network_wait", "closed"):
                elapsed = time.monotonic() - self.launcher.phase_at
                detail = translate(self.launcher.phase_key) + f" · {elapsed:.1f}s" + ("\n" + detail if detail else "")
        if supervised:
            since = max(0.0, time.monotonic() - supervised["received_at"])
            detail = translate(supervised.get("key", "supervision")) + f" · {supervised.get('elapsed', 0.0) + since:.1f}s"
            suffix = " · " + translate("unknown_total") + " · " + translate("remaining") + f" {max(0.0, supervised.get('remaining_seconds', 0.0) - since):.1f}s"
            if supervised.get("pid"):
                suffix += " · PID " + str(supervised["pid"])
        self.progress_label.configure(text=detail + suffix, wraplength=max(self.unit*4, self.progress_label.master.winfo_width()))
        if detail:
            self.progress_label.grid()
        else:
            self.progress_label.grid_remove()
        message = translate(self.notice_key) if self.notice_key else ""
        if self.reason:
            fault = self.current_failure.get("fault", {})
            summary = translate("fault_" + fault.get("category", "unknown")) if fault else local_message(self.reason, language).split("\n", 1)[0][:240]
            message = (message + " · " if message else "") + summary
        if self.last_failure and not self.current_failure and recovering:
            history = translate("previous_failure") + " · " + (translate("fault_" + self.last_failure["fault"].get("category", "unknown")) if self.last_failure.get("fault") else local_message(self.last_failure.get("reason", ""), language).split("\n", 1)[0][:160])
            message = message + "\n" + history if message else history
        self.notice.configure(text=message)
        if message:
            self.notice.grid()
        else:
            self.notice.grid_remove()

    def pump(self):
        for event in self.mailbox.drain(reconcile=True):
            if event.get("generation") == self.generation:
                self.handle(event)
                try:
                    if not self.root.winfo_exists():
                        return
                except self.tk.TclError:
                    return
        if self.closing and self.launcher and not self.launcher.thread.is_alive():
            self.launcher.activity.close()
            self.destroy()
            return
        self.refresh()
        self.root.after(max(1, int(math.sqrt(tick()) * 1000)), self.pump)

    def animate(self):
        now = time.monotonic()
        delta = now - self.last_draw
        self.last_draw = now
        self.phase += delta * math.tau / max(1, math.sqrt(os.cpu_count() or 1))
        self.level *= math.exp(-delta)
        self.orb.delete("all")
        width, height = self.orb.winfo_width(), self.orb.winfo_height()
        center_x, center_y = width/2, height/2
        radius = min(width, height) * .31
        active = self.session_id is not None and not self.ending
        for index in range(3):
            size = radius * (1 + index*.19 + .035*math.sin(self.phase+index))
            self.orb.create_oval(center_x-size, center_y-size, center_x+size, center_y+size, outline=self.palette["accent"] if index == 0 else self.palette["border"], width=2 if index == 0 else 1)
        count = max(5, int(radius/self.unit)*4+1)
        for index in range(count):
            x = center_x + (index-(count-1)/2)*radius*1.4/count
            envelope = max(.1, math.cos((index-(count-1)/2)/count*math.pi))
            movement = (.2 + math.sqrt(self.level)*2) if active else .13
            amplitude = radius * envelope * (movement * (.5+.5*math.sin(self.phase*3+index*.7)) + .08)
            self.orb.create_line(x, center_y-amplitude, x, center_y+amplitude, fill=self.palette["accent"] if active else self.palette["lavender"], width=max(1, self.unit//3), capstyle="round")
        interval = max(tick(), 1 / max(1, min(60, math.sqrt(os.cpu_count() or 1)*10)))
        self.root.after(max(1, int(interval*1000)), self.animate)

    def show_learning(self):
        from tkinter import filedialog, messagebox
        if os.environ.get("YUAN_PUBLISHER") != "1" or not self.workspace or not self.launcher or self.session_id or not self.runtime_ready:
            return
        if self.learning_window and self.learning_window.winfo_exists():
            self.learning_window.lift()
            return
        window = self.tk.Toplevel(self.root)
        self.learning_window = window
        window.title(tr("learning_setup", self.language))
        window.configure(bg=self.palette["panel"])
        window.transient(self.root)
        window.grid_columnconfigure(1, weight=1)
        state = self.readiness_values.get("learning", {})
        missing = "; ".join(f"{row['language']} {row['split']} {row['have']}/{row['need']}" for row in state.get("missing", []))
        detail = tr("metrics_note", self.language) + ("\n" + tr("missing_data", self.language) + ": " + missing if missing else "")
        self.label(window, text=detail, bg=self.palette["panel"], wraplength=min(720, self.root.winfo_screenwidth() - self.unit * 6)).grid(row=0, column=0, columnspan=3, sticky="ew", padx=self.unit, pady=self.unit)
        fields = {}
        keys = ("recording_id", "reviewer", "user_speaker", "assistant_speaker", "license", "user_file", "assistant_file")
        for index, key in enumerate(keys, 1):
            self.label(window, text=tr(key, self.language), bg=self.palette["panel"]).grid(row=index, column=0, sticky="w", padx=self.unit, pady=self.unit // 2)
            value = self.tk.StringVar(window)
            fields[key] = value
            entry = self.tk.Entry(window, textvariable=value, width=36, bg=self.palette["field"], fg=self.palette["text"], insertbackground=self.palette["accent"])
            entry.grid(row=index, column=1, sticky="ew", padx=self.unit)
            if key.endswith("_file"):
                def choose(value=value):
                    filename = filedialog.askopenfilename(parent=window, title=tr("pair_import", self.language), filetypes=[("Audio", "*.wav *.flac *.ogg *.mp3 *.opus *.aiff"), ("All", "*")])
                    if filename:
                        value.set(filename)
                self.button(window, choose, key="choose_audio").grid(row=index, column=2, padx=self.unit)
        language = self.tk.StringVar(window, value=self.language)
        split = self.tk.StringVar(window, value="train")
        self.label(window, text="中文 / English", bg=self.palette["panel"]).grid(row=8, column=0, padx=self.unit, sticky="w")
        self.ttk.Combobox(window, textvariable=language, values=("中文", "English"), state="readonly").grid(row=8, column=1, sticky="ew", padx=self.unit)
        self.label(window, text=tr("split", self.language), bg=self.palette["panel"]).grid(row=9, column=0, padx=self.unit, sticky="w")
        self.ttk.Combobox(window, textvariable=split, values=("train",), state="readonly").grid(row=9, column=1, sticky="ew", padx=self.unit)
        endings = {}
        ending_values = tuple(tr(key, self.language) for key in ("ending_unknown", "ending_complete", "ending_truncated"))
        for index, role in enumerate(("user", "assistant"), 10):
            endings[role] = self.tk.StringVar(window, value=ending_values[0])
            self.label(window, text=tr(role + "_ending", self.language), bg=self.palette["panel"]).grid(row=index, column=0, padx=self.unit, sticky="w")
            self.ttk.Combobox(window, textvariable=endings[role], values=ending_values, state="readonly", width=40).grid(row=index, column=1, columnspan=2, sticky="ew", padx=self.unit)
        confirmed = self.tk.BooleanVar(window, value=False)
        self.tk.Checkbutton(window, text=tr("human_confirm", self.language), variable=confirmed, bg=self.palette["panel"], fg=self.palette["text"], selectcolor=self.palette["field"], wraplength=640).grid(row=12, column=0, columnspan=3, sticky="w", padx=self.unit, pady=self.unit)
        def submit():
            payload = {key: value.get().strip() for key, value in fields.items()}
            if not confirmed.get() or not all(payload.values()):
                messagebox.showwarning(APP_NAME, tr("required_fields", self.language), parent=window)
                return
            payload.update({role + "_utterance_final": (None, True, False)[ending_values.index(value.get())] for role, value in endings.items()})
            self.launcher.send({"action": "import_pair", **payload, "language": language.get(), "split": split.get(), "confirmed": True,
                                "prompt": self.prompt.get("1.0", "end").strip() or tr("default_prompt", language.get())})
            window.destroy()
        self.button(window, submit, key="pair_import", primary=True).grid(row=13, column=0, columnspan=2, sticky="ew", padx=self.unit, pady=self.unit)
        self.button(window, lambda: self.launcher.send({"action": "review_open"}), key="review_open").grid(row=13, column=2, padx=self.unit, pady=self.unit)
        def import_manifest():
            filename = filedialog.askopenfilename(parent=window, title=tr("dataset_manifest_import", self.language), filetypes=[("JSON", "*.json")])
            if filename:
                self.launcher.send({"action": "import_dataset", "manifest_file": filename, "confirmed": True})
                window.destroy()
        self.button(window, import_manifest, key="dataset_manifest_import", primary=True).grid(row=14, column=0, columnspan=3, padx=self.unit, pady=self.unit)
        self.button(window, lambda: self.launcher.send({"action": "export_release"}), key="owned_release_export").grid(row=15, column=0, columnspan=3, padx=self.unit, pady=self.unit)

    def show_review(self, event):
        from tkinter import messagebox
        if self.review_window and self.review_window.winfo_exists():
            self.review_window.destroy()
        evaluation, draft = event["evaluation"], event["review"]
        cases = evaluation["cases"]
        required = ("understandable", "follows_prompt", "relevant_reply", "follows_history", "ends_normally", "no_abnormal_audio")
        window = self.tk.Toplevel(self.root)
        self.review_window = window
        window.title(tr("review_open", self.language))
        window.configure(bg=self.palette["panel"])
        window.transient(self.root)
        window.grid_columnconfigure(1, weight=1)
        labels = {None: tr("review_pending", self.language), True: tr("review_pass", self.language), False: tr("review_fail", self.language)}
        prior = {row["id"]: row for row in draft.get("checks", [])}
        answers = {case["id"]: {key: self.tk.StringVar(window, value=labels[prior.get(case["id"], {}).get(key)]) for key in required} for case in cases}
        position = [0]
        heading = self.label(window, bg=self.palette["panel"], font=self.bold_font)
        heading.grid(row=0, column=0, columnspan=3, sticky="ew", padx=self.unit, pady=self.unit)
        prompt = self.label(window, bg=self.palette["panel"], wraplength=min(680, self.root.winfo_screenwidth() - self.unit * 6))
        prompt.grid(row=1, column=0, columnspan=3, sticky="ew", padx=self.unit)
        selectors = {}
        for index, key in enumerate(required, 3):
            self.label(window, text=tr(key, self.language), bg=self.palette["panel"]).grid(row=index, column=0, sticky="w", padx=self.unit, pady=self.unit // 2)
            selector = self.ttk.Combobox(window, state="readonly", values=tuple(labels.values()))
            selector.grid(row=index, column=1, columnspan=2, sticky="ew", padx=self.unit)
            selectors[key] = selector
        def display():
            case = cases[position[0]]
            heading.configure(text=f"{position[0] + 1} / {len(cases)} · {case['language']} · {evaluation['model']['sha256'][:12]}")
            prompt.configure(text=case["prompt"] + "\n" + " → ".join(f"{item['role']} [{item['start']}:{item['start'] + item['samples']}] {item['sha256'][:12]}" for item in case.get("history", [])))
            for key, selector in selectors.items():
                selector.configure(textvariable=answers[case["id"]][key])
        def move(delta):
            position[0] = (position[0] + delta) % len(cases)
            display()
        def play(field):
            self.launcher.send({"action": "review_play", "evaluation_sha256": event["evaluation_sha256"], "case": cases[position[0]]["id"], "field": field})
        self.button(window, lambda: play("input"), key="input").grid(row=2, column=0, padx=self.unit, pady=self.unit)
        self.button(window, lambda: play("output"), key="output").grid(row=2, column=1, padx=self.unit, pady=self.unit)
        self.button(window, lambda: play("context"), key="history_play").grid(row=2, column=2, padx=self.unit, pady=self.unit)
        self.button(window, lambda: move(-1), text="←").grid(row=9, column=0, padx=self.unit, pady=self.unit)
        self.button(window, lambda: move(1), text="→").grid(row=9, column=2, padx=self.unit, pady=self.unit)
        reviewer = self.tk.StringVar(window, value=draft.get("reviewer", ""))
        self.label(window, text=tr("reviewer", self.language), bg=self.palette["panel"]).grid(row=10, column=0, padx=self.unit)
        self.tk.Entry(window, textvariable=reviewer, bg=self.palette["field"], fg=self.palette["text"], insertbackground=self.palette["accent"]).grid(row=10, column=1, columnspan=2, sticky="ew", padx=self.unit)
        def close():
            if self.launcher:
                self.launcher.send({"action": "review_close"})
            window.destroy()
        def submit():
            if not reviewer.get().strip() or any(value.get() == labels[None] for case in answers.values() for value in case.values()):
                messagebox.showwarning(APP_NAME, tr("review_incomplete", self.language), parent=window)
                return
            checks = [{"id": case_id, **{key: value.get() == labels[True] for key, value in values.items()}} for case_id, values in answers.items()]
            self.launcher.send({"action": "review_submit", "evaluation_sha256": event["evaluation_sha256"], "reviewer": reviewer.get().strip(), "checks": checks})
            window.destroy()
        self.button(window, submit, key="review_submit", primary=True).grid(row=11, column=0, columnspan=3, sticky="ew", padx=self.unit, pady=self.unit)
        window.protocol("WM_DELETE_WINDOW", close)
        display()


def probe_training_components(torch, np, state, policy, device, config, cancel, emit):
    check(cancel)
    model = NativeAudio.__new__(NativeAudio)
    model.torch, model.np, model.state, model.policy, model.emit = torch, np, Path(state), policy, emit
    model.device, model.dtype, model.cancel = device, torch.float32, cancel
    for key in ("rate", "hop", "width", "layers"):
        setattr(model, key, config[key])
    frames = max(8, model.layers * 2)
    count = model.hop * frames
    model.chunk_seconds = max(1.0, count / model.rate * 2)
    model.capacity_seconds, model.capacity_scale = model.chunk_seconds * 4, 1.0
    model.input_budget = None
    model.performance_section = "preflight:" + payload_digest([str(device), config])
    model.training_manifest = {"curriculum": {"phase": "conditional_dialogue"}}
    network = verifier = optimizer = None
    began = time.monotonic()
    try:
        network = model._build().to(device=device, dtype=torch.float32).train()
        optimizer = torch.optim.AdamW(network.parameters(), foreach=False)
        values = (np.sin(np.arange(count, dtype=np.float32)) * 0.1).astype(np.float32)
        timings = []
        for task in ("acoustic", "dialogue"):
            optimizer.zero_grad(set_to_none=True)
            compute_began = time.monotonic()
            loss = model.loss(network, "Yuan", values, values[::-1].copy(), ended=True, task=task,
                              end_label_valid=True, rollout=task == "dialogue", rollout_frames=2)
            gradient_checkpoint(loss, cancel).backward()
            compute_sync(torch, device)
            if not bool(torch.isfinite(loss).item()) or not all(bool(torch.isfinite(p.grad).all().item()) for p in network.parameters() if p.grad is not None):
                raise YuanError("真实训练损失或梯度检查失败 / Actual training loss or gradient check failed")
            optimizer.step()
            compute_sync(torch, device)
            timings.append(elapsed_seconds(compute_began))
            check(cancel)
        if not tensors_finite(torch, network.parameters()):
            raise YuanError("训练优化器更新检查失败 / Training optimizer update check failed")
        optimizer.zero_grad(set_to_none=True)
        with torch.no_grad():
            hidden = model._encode(network, "Yuan", values, cancel=cancel)
            previous = network.begin
            condition = hidden
            for _ in range(2):
                previous, ending, hidden = network.decode(previous, hidden, condition)
                if not bool(torch.isfinite(previous).all().item()):
                    raise YuanError("流式音频生成检查失败 / Streaming audio generation check failed")
        verifier = SpeechVerifier.__new__(SpeechVerifier)
        verifier.model, verifier.emit = model, emit
        verifier.configure_device(device)
        verifier.network = verifier.build().train()
        verifier.accepted = None
        verifier.optimizer = torch.optim.AdamW(verifier.network.parameters(), foreach=False)
        features = verifier.features(values, cancel)
        output = verifier.network(features, cancel=cancel).transpose(0, 1)
        targets = torch.tensor([ord("a") + 1], dtype=torch.long)
        try:
            loss = verifier.ctc_loss(output, targets)
            torch.autograd.grad(loss, output, retain_graph=True)
        except (RuntimeError, NotImplementedError) as exc:
            if verifier.ctc_device.type == "cpu" or not unsupported_operation(exc):
                raise
            verifier.ctc_device = torch.device("cpu")
            emit("compute_partition", component="verifier_ctc_backward", device="cpu", network_device=str(device), reason=concise_error(exc))
            loss = verifier.ctc_loss(output, targets)
        gradient_checkpoint(loss, cancel).backward()
        compute_sync(torch, device)
        if not bool(torch.isfinite(loss).item()) or not all(p.grad is not None and bool(torch.isfinite(p.grad).all().item()) for p in verifier.network.parameters()):
            raise YuanError("语音验证器训练检查失败 / Speech verifier training check failed")
        verifier.optimizer.step()
        if not tensors_finite(torch, verifier.network.parameters()):
            raise YuanError("语音验证器优化器检查失败 / Speech verifier optimizer check failed")
        return {"verifier_feature_device": str(verifier.feature_device), "verifier_ctc_device": str(verifier.ctc_device),
                "verifier_network_device": str(device), "training_components_verified": True, "dtype": "float32",
                "training_probe_seconds": elapsed_seconds(began), "probe_frames": frames,
                "audio_seconds_per_frame": timings[-1] / frames,
                "probe_configuration": config, "conversation_verified": False}
    finally:
        network = verifier = optimizer = None
        module = getattr(torch, device.type, None)
        if module is not None and hasattr(module, "empty_cache"):
            module.empty_cache()

def runtime_probe_compute(state, emit, dependencies):
    np, torch, sf, soxr = (dependencies[name] for name in ("numpy", "torch", "soundfile", "soxr"))
    threads = torch.get_num_threads()
    try:
        torch.set_num_threads(execution_threads(dependencies["psutil"], AdaptivePolicy(state)))
        devices = compute_devices(torch, state, emit)
        validated = []
        failures = []
        for device, name in devices:
            try:
                emit("probe", key="stage_probe_compute", check="owned_network_forward_backward", device=str(device), name=name)
                model = NativeAudio.__new__(NativeAudio)
                model.torch, model.width, model.layers, model.hop = torch, 16, 1, 8
                network = model._build().to(device)
                ids = torch.tensor([[1, 2]], dtype=torch.long, device=device)
                prompt = network.condition(ids)
                hidden = network.initial(prompt, 1)
                hidden, encoder = network.encode(torch.zeros(1, 2, model.hop, device=device), hidden, 0)
                output, ending, hidden = network.decode(network.begin, hidden, hidden)
                loss = output.square().mean() + ending.square().mean()
                if not bool(torch.isfinite(loss).cpu()):
                    raise YuanError("计算检查产生无效数值 / Compute check produced invalid values")
                loss.backward()
                compute_sync(torch, device)
                gradients = [value.grad for value in network.parameters() if value.grad is not None]
                if not gradients or not tensors_finite(torch, gradients):
                    raise YuanError("模型反向计算检查失败 / Model backward check failed")
                for branch in (network.prompt, network.frame_encoder, network.audio_encoder, network.dialogue_core, network.decoder_condition):
                    if not any(value.grad is not None and bool((value.grad.abs().sum() > 0).cpu()) for value in branch.parameters()):
                        raise YuanError("模型条件分支梯度检查失败 / Model conditioning gradient check failed")
                optimizer = torch.optim.AdamW(network.parameters(), foreach=False)
                optimizer.step()
                compute_sync(torch, device)
                if not tensors_finite(torch, network.parameters()):
                    raise YuanError("优化器检查失败 / Optimizer check failed")
                emit("probe", key="stage_probe_compute", check="checkpoint_roundtrip", device=str(device))
                probe_root = safe_path(state, "tmp")
                probe_root.mkdir(parents=True, exist_ok=True)
                with tempfile.TemporaryDirectory(prefix="probe-", dir=probe_root) as directory:
                    path = Path(directory) / "weights.pt"
                    expected = {key: value.detach().cpu() for key, value in network.state_dict().items()}
                    torch.save(expected, path)
                    restored = model._build()
                    restored.load_state_dict(torch.load(path, map_location="cpu", weights_only=True), strict=True)
                    if not all(torch.equal(left, restored.state_dict()[key]) for key, left in expected.items()):
                        raise YuanError("权重读写检查失败 / Checkpoint round-trip check failed")
                components = probe_training_components(torch, np, state, AdaptivePolicy(state), device,
                                                      {"rate": 8000, "hop": model.hop, "width": model.width, "layers": model.layers}, None, emit)
                validated.append({"device": str(device), "name": name, "identity_sha256": compute_device_identity(torch, device, name), **components})
            except (RuntimeError, OSError, ValueError, YuanError) as exc:
                failures.append({"device": str(device), "name": name, "reason": concise_error(exc)})
            finally:
                if "network" in locals():
                    del network
        if not validated:
            raise YuanFault("加速计算验证未完成，继续匹配运行组件 / Accelerator computation validation incomplete; matching runtime components", category="compatibility", code="compute_backend_failed", devices=failures)
        atomic_json(Path(state) / "compute-verified.json", {"backend": os.environ.get("YUAN_COMPUTE_BACKEND", ""), "devices": validated, "failures": failures, "build_sha256": build_digest(), "at": time.time()})
        emit("probe", key="stage_probe_compute", check="audio_file_resampling")
        values = np.linspace(-0.1, 0.1, 256, dtype=np.float32)
        stream = io.BytesIO()
        sf.write(stream, values, 16000, format="WAV", subtype="FLOAT")
        stream.seek(0)
        recovered, rate = sf.read(stream, dtype="float32")
        resampled = soxr.resample(recovered, rate, rate * 2)
        if not np.array_equal(values, recovered) or not len(resampled) or not np.isfinite(resampled).all():
            raise YuanError("音频读写与重采样检查失败 / Audio file and resampling check failed")
        emit("probe", key="runtime_verify", check="complete", accelerators=validated)
    finally:
        torch.set_num_threads(threads)


def verify_installed_files(runtime, entry, emit, cancel, budget=None):
    import importlib.metadata as metadata
    import base64
    import csv
    import io
    runtime = Path(runtime).resolve()
    expected = {item["name"]: item["version"] for item in entry["packages"]}
    distributions = {}
    for distribution in metadata.distributions():
        check(cancel)
        name = re.sub(r"[-_.]+", "-", str(distribution.metadata.get("Name", ""))).lower()
        if not name:
            continue
        if name in distributions:
            raise YuanFault("运行组件元数据重复 / Duplicate installed distribution metadata", category="integrity", code="installed_metadata_duplicate", component=name)
        distributions[name] = distribution
    if set(distributions) - set(expected) - {"pip", "setuptools", "wheel"} or any(name not in distributions or distributions[name].version != version for name, version in expected.items()):
        raise YuanFault("运行环境版本与锁定记录不一致 / Runtime versions differ from the lock", category="integrity", code="installed_versions_mismatch")
    checked = unhashed = 0
    last_progress = -math.inf
    period = max(tick(), math.sqrt(tick()))
    with operation(emit, "runtime_inventory", "verification", budget_seconds=budget, stall_seconds=budget) as operation_id:
        for name in expected:
            check(cancel)
            distribution = distributions[name]
            record = distribution.read_text("RECORD")
            if not record:
                raise YuanFault("缺少组件安装文件清单 / Installed file manifest is missing", category="integrity", code="installed_record_missing", component=name)
            hashed = 0
            seen = set()
            for fields in csv.reader(io.StringIO(record)):
                check(cancel)
                if not fields:
                    continue
                if len(fields) != 3 or not fields[0] or fields[0] in seen or fields[2] and not re.fullmatch(r"[0-9]+", fields[2]):
                    raise YuanFault("组件安装清单格式无效 / Invalid installed file manifest", category="integrity", code="installed_record_invalid", component=name)
                item, recorded_hash, recorded_size = fields
                seen.add(item)
                raw = Path(distribution.locate_file(item))
                path = raw.resolve()
                if raw.is_symlink() or not path.is_relative_to(runtime):
                    raise YuanFault("安装文件超出候选运行环境 / Installed file escapes the candidate runtime", category="integrity", code="installed_path_invalid", component=name, file=item)
                if path.suffix == ".pyc" and not recorded_hash:
                    continue
                if not path.is_file():
                    raise YuanFault("组件安装文件缺失 / Installed component file is missing", category="integrity", code="installed_file_missing", component=name, file=item)
                if recorded_size and path.stat().st_size != int(recorded_size):
                    raise YuanFault("组件安装文件大小不符 / Installed component file size mismatch", category="integrity", code="installed_file_size", component=name, file=item)
                if recorded_hash:
                    try:
                        algorithm, expected_hash = recorded_hash.split("=", 1)
                        digest = hashlib.new(algorithm)
                        if digest.digest_size < hashlib.sha256().digest_size:
                            raise ValueError("Weak file hash")
                    except ValueError as exc:
                        raise YuanFault("组件文件哈希算法无效 / Invalid component file hash algorithm", category="integrity", code="installed_hash_algorithm", component=name, file=item) from exc
                    with path.open("rb") as stream:
                        for block in iter(lambda: stream.read(1024 * 1024), b""):
                            check(cancel)
                            digest.update(block)
                    actual = base64.urlsafe_b64encode(digest.digest()).rstrip(b"=").decode("ascii")
                    if actual != expected_hash:
                        raise YuanFault("组件安装文件哈希不匹配 / Installed component file hash mismatch", category="integrity", code="installed_file_hash", component=name, file=item)
                    hashed += 1
                else:
                    unhashed += 1
                checked += 1
                now = time.monotonic()
                if now - last_progress >= period:
                    last_progress = now
                    emit("operation", key="runtime_inventory", scope="verification", operation_id=operation_id,
                         outcome="progress", current=checked, component=name, pid=os.getpid())
            if not hashed:
                raise YuanFault("组件没有可核验的文件哈希 / No verifiable installed file hashes", category="integrity", code="installed_hashes_missing", component=name)
    emit("probe", key="runtime_install_verified", checked_files=checked, unhashed_files=unhashed, packages=len(expected))
    return {"checked_files": checked, "unhashed_files": unhashed, "packages": len(expected)}

def runtime_install_verify(state):
    state = Path(state).resolve()
    with runtime_entry(state) as (emit, cancel):
        try:
            runtime = Path(sys.prefix)
            if not runtime.resolve().is_relative_to(safe_path(state, "runtimes")):
                raise YuanFault("仅允许校验所选目录内的候选环境 / Verification requires a workspace candidate runtime", category="configuration", code="runtime_inventory_location")
            entry = checked_json(runtime / "lock.json")
            budgets = json.loads(os.environ.get("YUAN_IMPORT_BUDGETS", "{}"))
            verify_installed_files(runtime, entry, emit, cancel, budgets.get("runtime_inventory"))
        except BaseException as exc:
            emit("error", key="failure", reason=concise_error(exc), fatal=True, fault=fault_event(exc, "runtime_inventory"))
            raise SystemExit(1) from None

def runtime_probe_import(state, component):
    state = Path(state).resolve()
    with runtime_entry(state) as (emit, cancel):
        try:
            if component not in RUNTIME_MODULES:
                raise YuanFault("无效的组件导入复检目标 / Invalid isolated import target", category="configuration", code="probe_import_target")
            identity = os.environ.get("YUAN_IMPORT_IDENTITY")
            supervisor = StageSupervisor(state, emit, identity=identity if is_digest(identity) else None)
            budgets = json.loads(os.environ.get("YUAN_IMPORT_BUDGETS", "{}"))
            if not isinstance(budgets, dict):
                raise YuanError("导入预算格式无效 / Invalid import budget format")
            emit("runtime_profile", python=platform.python_version(), executable=sys.executable, system=platform.system(), machine=platform.machine(),
                 cwd=str(Path.cwd()), environment=supervisor.fingerprint, mode="isolated_import", component=component)
            import_runtime_module(component, state, emit, cancel, supervisor, budgets)
            supervisor.policy.save()
        except BaseException as exc:
            emit("error", key="failure", reason=concise_error(exc), fatal=True, fault=fault_event(exc, "stage_import_" + component))
            raise SystemExit(1) from None

def runtime_probe(state):
    state = Path(state).resolve()
    with runtime_entry(state) as (emit, cancel):
        try:
            dependencies = load_runtime_modules(state, emit, cancel)
            with operation(emit, "stage_probe_compute"):
                runtime_probe_compute(state, emit, dependencies)
        except BaseException as exc:
            emit("error", key="failure", reason=concise_error(exc), fatal=True, fault=fault_event(exc, "runtime_verify"))
            raise SystemExit(1) from None

def preparation_entry(workspace, publisher=False):
    workspace = Path(workspace).expanduser().resolve()
    workspace.mkdir(parents=True, exist_ok=True)
    state = workspace_state(workspace)
    env = workspace_environment(workspace)
    os.environ.update(env)
    tempfile.tempdir = env["TMPDIR"]
    if publisher:
        os.environ["YUAN_PUBLISHER"] = "1"
    cancel = threading.Event()
    def emit(kind, **values):
        if kind in ("status", "notice", "error", "deployment", "deployment_preflight"):
            key = values.get("key", kind)
            sys.stdout.write(tr(key, "中文") + " / " + tr(key, "English") + "\n")
            sys.stdout.flush()
    with WorkspaceLease(state / "workspace.lock"):
        owned_release_preflight(state, emit)
        installer = RuntimeInstaller(workspace, cancel, emit)
        interpreter = installer.ensure()
        command = [str(interpreter), str(Path(__file__).resolve()), "--publisher-key" if publisher else "--prepare-release", str(state)]
        child = subprocess.run(command, cwd=state, env=os.environ.copy(), check=False)
        return child.returncode

def prepare_release_entry(state, publisher=False):
    state = ensure_workspace_identity(state)
    if state != workspace_state(state.parent).resolve():
        raise YuanFault("运行目录与当前版本不匹配 / Runtime directory does not match this build", category="integrity", code="workspace_build_mismatch")
    env = workspace_environment(state.parent)
    os.environ.update(env)
    tempfile.tempdir = env["TMPDIR"]
    if publisher:
        path = ReleaseTrust(state).initialize_publisher()
        sys.stdout.write(str(path) + "\n")
        return 0
    emit = lambda kind, **values: None
    cancel = threading.Event()
    with WorkspaceLease(state / "engine.lock"):
        owned_release_preflight(state, emit)
        dependencies = load_runtime_modules(state, emit, cancel)
        installer = OwnedReleaseInstaller(state, emit)
        root = installer.prepare(cancel)
        model = NativeAudio(state, cancel, emit, owned_root=root, dependencies=dependencies)
        if root is not None:
            installer.activate(root, model, cancel)
        if model.playback_ready:
            sys.stdout.write("模型验收通过；音频设备将在界面启动时检查 / Model accepted; audio devices will be checked when the interface starts\n")
        else:
            sys.stdout.write("自建模型已初始化并保存；尚未通过对话验收，界面运行时将自动学习 / Native model initialized and saved; conversation not accepted yet, learning runs automatically with the interface\n")
    return 0


def ui_capabilities():
    import importlib.util
    display = sys.platform in ("win32", "darwin") or bool(os.environ.get("DISPLAY") or os.environ.get("WAYLAND_DISPLAY"))
    return {"python": sys.version_info >= (3, 10), "display": display, "tkinter": importlib.util.find_spec("tkinter") is not None}

class BrowserApp:
    def __init__(self, workspace=None):
            import secrets
            self.token = secrets.token_urlsafe(32)
            self.mailbox = Mailbox()
            self.interface = InterfaceState()
            self.lock = threading.RLock()
            self.launcher = None
            self.workspace = None
            self.pending_workspace = Path(workspace).expanduser().resolve() if workspace else None
            self.generation = 0
            self.attempt_id = None
            self.attempt_number = self.event_sequence = self.snapshot_sequence = 0
            self.phase_id = None
            self.language = "中文"
            self.prompt = tr("default_prompt", self.language)
            self.readiness_values = {}
            self.metrics = {}
            self.audio = {}
            self.progress = {}
            self.notices = deque(maxlen=24)
            self.status_key = "idle"
            self.reason = ""
            self.session_id = None
            self.ending = False
            self.closing = False
            self.closed = threading.Event()
            self.last_seen = time.monotonic()
            self.detached_at = None
            self.server = None

    def open_pending(self):
        if self.pending_workspace is None or self.session_id:
            return
        if self.launcher is not None:
            if self.launcher.thread.is_alive():
                self.launcher.stop()
                return
            if self.launcher.process_retained:
                raise YuanError("旧音频进程未安全结束 / Previous audio process did not stop safely")
            self.launcher.activity.close()
            self.launcher = None
        workspace = self.pending_workspace
        if not workspace.is_dir():
            raise YuanError("所选目录不存在 / Selected folder does not exist")
        state = workspace_state(workspace)
        state.mkdir(parents=True, exist_ok=True)
        lease = WorkspaceLease(state / "workspace.lock")
        try:
            settings = workspace_settings(state, self.language, self.prompt)
            atomic_json(state / "settings.json", settings)
            self.generation += 1
            self.attempt_id = self.phase_id = None
            self.attempt_number = self.event_sequence = 0
            self.readiness_values, self.metrics, self.audio, self.progress = {}, {}, {}, {}
            self.workspace = workspace
            self.language, self.prompt = settings["language"], settings["prompt"]
            self.status_key = "setup"
            self.reason = ""
            self.launcher = Launcher(workspace, self.generation, self.mailbox, lease=lease)
            self.pending_workspace = None
        except BaseException:
            lease.close()
            raise

    def snapshot(self):
            with self.lock:
                if not self.closing:
                    try:
                        self.open_pending()
                    except (OSError, ValueError, YuanError) as exc:
                        self.reason = concise_error(exc)
                        self.status_key = "failure"
                        self.pending_workspace = None
                for event in self.mailbox.drain(reconcile=True):
                    if not self.interface.apply(event, self.generation, self.session_id, self.closing, self.ending):
                        continue
                    kind = event.get("type")
                    if kind == "attempt":
                        number = event.get("attempt_number", 0)
                        self.attempt_id, self.attempt_number = event.get("attempt_id"), number
                        self.event_sequence = 0
                        self.phase_id = None
                        self.readiness_values, self.audio, self.progress, self.metrics = {}, {}, {}, {}
                        self.reason = ""
                        if self.session_id:
                            self.session_id = None
                            self.ending = False
                            self.reason = "音频引擎已重启，本次会话未完整确认 / Audio engine restarted; session completion is unconfirmed"
                    self.event_sequence = self.interface.sequence
                    if kind == "readiness":
                        self.readiness_values = dict(self.interface.readiness)
                        if not self.session_id and not self.closing:
                            ready, next_status = readiness_view(event, self.closing)
                            if next_status is not None:
                                self.status_key = next_status
                            if ready:
                                self.reason = ""
                    elif kind == "metrics":
                        self.metrics = event
                    elif kind in ("audio", "turn"):
                        if event.get("id") in (None, self.session_id):
                            self.audio.update(event)
                    elif kind in ("progress", "source_progress"):
                        if kind == "progress" and event.get("phase_id") != self.phase_id:
                            continue
                        self.progress.update(event)
                    elif kind == "startup_resources":
                        self.metrics.update(event)
                    elif kind == "status":
                        self.phase_id = event.get("phase_id")
                        self.progress = {}
                        if not self.ending and not self.closing:
                            self.status_key = event.get("key", self.status_key)
                    elif kind == "started":
                        self.status_key = "listening"
                    elif kind == "ended" and event.get("id") == self.session_id:
                        self.session_id = None
                        self.ending = False
                        self.status_key = "ended"
                        self.audio.update(continuous=False, speech_active=False)
                        self.progress = {}
                        if event.get("storage_complete") is False or event.get("capture_complete") is False:
                            self.reason = "对话已停止，但录音或存档未完整确认 / Conversation stopped; capture or storage completion is unconfirmed"
                    elif kind in ("exit", "disconnected", "launcher_closed", "process_reaped") or kind == "error" and event.get("fatal") is not False:
                        self.readiness_values = {}
                        self.audio.update(continuous=False, speech_active=False)
                        if self.session_id:
                            self.session_id = None
                            self.ending = False
                            self.reason = "音频引擎已退出，本次会话未完整确认 / Audio engine exited; session completion is unconfirmed"
                    if kind in ("notice", "error", "recovery", "deployment_preflight", "dataset_coverage"):
                        self.notices.append(event_text(event, self.language, compact=True).strip())
                        if kind == "error":
                            self.reason = event.get("reason", tr(event.get("key", "failure"), self.language))
                if self.closing and (self.launcher is None or not self.launcher.thread.is_alive()):
                    self.closed.set()
                ready = bool(not self.closing and not self.pending_workspace and self.launcher and self.launcher.thread.is_alive()
                             and readiness_view(self.readiness_values, self.closing)[0])
                self.snapshot_sequence += 1
                return {"revision": self.snapshot_sequence, "workspace": str(self.workspace) if self.workspace else "", "language": self.language, "prompt": self.prompt,
                        "status": tr(self.status_key, self.language), "reason": self.reason, "ready": ready, "session": self.session_id,
                        "ending": self.ending, "closing": self.closing, "readiness": self.readiness_values, "audio": self.audio,
                        "metrics": self.metrics, "progress": self.progress, "notices": list(self.notices)}

    def directories(self, path=None, offset=0):
        root = Path(path).expanduser().resolve(strict=True) if path else Path.home().resolve()
        if not root.is_dir():
            raise YuanError("目录不存在 / Folder does not exist")
        children = []
        with os.scandir(root) as entries:
            for entry in entries:
                try:
                    if entry.is_dir(follow_symlinks=False):
                        children.append(entry.name)
                except OSError:
                    continue
        children.sort(key=lambda name: (name.startswith("."), name.casefold()))
        offset = max(0, int(offset))
        page_size = 128
        return {"path": str(root), "parent": str(root.parent), "entries": [{"name": name, "path": str(root / name)} for name in children[offset:offset + page_size]],
                "offset": offset, "next": offset + page_size if offset + page_size < len(children) else None,
                "roots": [f"{letter}:\\" for letter in "ABCDEFGHIJKLMNOPQRSTUVWXYZ" if Path(f"{letter}:\\").is_dir()] if os.name == "nt" else ["/"]}

    def action(self, data):
        if not isinstance(data, dict):
            raise YuanError("请求无效 / Invalid request")
        command = data.get("action")
        with self.lock:
            self.snapshot()
            if command == "workspace":
                if self.session_id or self.closing or not isinstance(data.get("path"), str):
                    raise YuanError("当前不能切换目录 / Cannot switch workspace now")
                path = Path(data["path"]).expanduser().resolve(strict=True)
                if not path.is_dir():
                    raise YuanError("所选目录无效 / Invalid selected folder")
                if path != self.workspace:
                    self.pending_workspace = path
                    self.readiness_values = {}
                    self.open_pending()
            elif command == "settings":
                if self.session_id or self.closing or data.get("language") not in ("中文", "English") or not isinstance(data.get("prompt"), str):
                    raise YuanError("当前设置无效 / Invalid settings")
                self.language, self.prompt = data["language"], data["prompt"]
                if self.workspace:
                    atomic_json(workspace_state(self.workspace) / "settings.json", {"language": self.language, "prompt": self.prompt})
                if self.launcher:
                    self.launcher.send({"action": "language", "language": self.language})
            elif command == "start":
                if self.session_id or not self.snapshot()["ready"]:
                    raise YuanError("对话尚未就绪 / Conversation is not ready")
                identifier = uuid.uuid4().hex
                if not self.launcher.send({"action": "start", "id": identifier, "language": self.language, "prompt": self.prompt}):
                    raise YuanError("开始指令未送达 / Start command was not delivered")
                self.session_id = identifier
                self.ending = False
                self.audio = {}
            elif command == "stop":
                if data.get("confirmed") is not True:
                    raise YuanError("结束对话需要确认 / Ending the conversation requires confirmation")
                if self.session_id and not self.ending:
                    if not self.launcher or not self.launcher.send({"action": "stop", "id": self.session_id}):
                        raise YuanError("结束指令未送达，不能确认会话已结束 / Stop command was not delivered; session end is unconfirmed")
                    self.ending = True
            elif command == "recheck":
                if self.launcher and not self.session_id and not self.closing:
                    self.launcher.request_recheck()
            elif command == "detach":
                if self.session_id and data.get("confirmed") is not True:
                    raise YuanError("离开界面前需要确认 / Confirm before leaving the interface")
                self.detached_at = time.monotonic()
                if self.session_id and not self.ending and self.launcher:
                    self.launcher.send({"action": "stop", "id": self.session_id})
                    self.ending = True
            elif command in ("close", "disconnect"):
                if self.session_id and data.get("confirmed") is not True:
                    raise YuanError("退出前需要确认结束对话 / Confirm ending the conversation before exit")
                self.closing = True
                if self.launcher:
                    self.launcher.stop()
            else:
                raise YuanError("不支持的操作 / Unsupported action")
            return self.snapshot()

    def handler(self):
        import hmac
        import secrets
        from http.server import BaseHTTPRequestHandler
        app = self
        class Handler(BaseHTTPRequestHandler):
            def log_message(self, format, *args):
                return

            def send_payload(self, value, status=200, content_type="application/json; charset=utf-8", nonce=None):
                body = value.encode("utf-8") if isinstance(value, str) else json.dumps(value, ensure_ascii=False, allow_nan=False, separators=(",", ":")).encode("utf-8")
                self.send_response(status)
                self.send_header("Content-Type", content_type)
                self.send_header("Content-Length", str(len(body)))
                self.send_header("Cache-Control", "no-store")
                self.send_header("Referrer-Policy", "no-referrer")
                self.send_header("X-Content-Type-Options", "nosniff")
                self.send_header("X-Frame-Options", "DENY")
                policy = "default-src 'none'; base-uri 'none'; frame-ancestors 'none'; form-action 'none'"
                if nonce is not None and content_type.startswith("text/html"):
                    policy += "; script-src 'nonce-" + nonce + "'; style-src 'nonce-" + nonce + "'; connect-src 'self'"
                self.send_header("Content-Security-Policy", policy)
                self.end_headers()
                self.wfile.write(body)

            def authorized(self):
                host = "127.0.0.1:" + str(self.server.server_port)
                origin = self.headers.get("Origin")
                if self.headers.get("Host") != host or origin is not None and origin != "http://" + host:
                    return False
                if len(self.headers.get_all("Host", [])) != 1 or len(self.headers.get_all("Origin", [])) > 1 or len(self.headers.get_all("X-Yuan-Token", [])) > 1:
                    return False
                params = urllib.parse.parse_qs(urllib.parse.urlsplit(self.path).query)
                tokens = params.get("token", [])
                if len(tokens) > 1:
                    return False
                token = self.headers.get("X-Yuan-Token", tokens[0] if tokens else "")
                return isinstance(token, str) and token.isascii() and hmac.compare_digest(token, app.token)

            def do_GET(self):
                try:
                    if not self.authorized():
                        self.send_payload({"error": "拒绝未经授权的界面访问 / Unauthorized interface access"}, 403)
                        return
                    path = urllib.parse.urlsplit(self.path).path
                    app.last_seen = time.monotonic()
                    app.detached_at = None
                    if path == "/":
                        nonce = secrets.token_urlsafe(24)
                        self.send_payload(app.page(nonce), content_type="text/html; charset=utf-8", nonce=nonce)
                    elif path == "/api/state":
                        self.send_payload(app.snapshot())
                    else:
                        self.send_payload({"error": "Not found"}, 404)
                except (BrokenPipeError, ConnectionResetError):
                    return
                except Exception as exc:
                    self.send_payload({"error": concise_error(exc)}, 500)

            def do_POST(self):
                try:
                    if not self.authorized():
                        self.send_payload({"error": "拒绝未经授权的操作 / Unauthorized operation"}, 403)
                        return
                    if self.headers.get("Content-Type", "").split(";", 1)[0].strip().lower() != "application/json" or self.headers.get("Transfer-Encoding"):
                        self.send_payload({"error": "Invalid content type"}, 415)
                        return
                    size = int(self.headers.get("Content-Length", "0"))
                    if size <= 0 or size > 1024 * 1024:
                        self.send_payload({"error": "Invalid request size"}, 413)
                        return
                    self.connection.settimeout(10)
                    data = json.loads(self.rfile.read(size), parse_constant=lambda value: (_ for _ in ()).throw(ValueError(value)))
                    app.last_seen = time.monotonic()
                    path = urllib.parse.urlsplit(self.path).path
                    if path == "/api/directories" and isinstance(data, dict):
                        self.send_payload(app.directories(data.get("path"), data.get("offset", 0)))
                    elif path == "/api/action":
                        self.send_payload(app.action(data))
                    else:
                        self.send_payload({"error": "Not found"}, 404)
                except (BrokenPipeError, ConnectionResetError):
                    return
                except (OSError, ValueError, TypeError, YuanError) as exc:
                    self.send_payload({"error": concise_error(exc)}, 400)
        return Handler

